window.NEWQ={"questions":[{"id":5001,"img":"newq-art/5001.png","c":"7.18","sda":"Du vil standse og sætte en passager af. Den ledige plads ved kantstenen ligger lige før fodgængerfeltet. Hvad gælder?","sfa":"می‌خواهید بایستید و مسافری را پیاده کنید. جای خالی کنار جدول درست پیش از گذرگاه عابر پیاده است. چه قاعده‌ای برقرار است؟","sen":"You want to stop and let a passenger out. The free space at the kerb is right before the pedestrian crossing. What applies?","st":[{"da":"Jeg må gerne standse her, fordi det kun er et kort ophold.","fa":"می‌توانم این‌جا بایستم، چون فقط توقفی کوتاه است.","ok":0,"eda":"Nej. Standsning er forbudt på fodgængerfeltet og inden for 5 m før det, også et kort ophold.","efa":"خیر. توقف روی گذرگاه عابر و تا ۵ متر پیش از آن ممنوع است، حتی کوتاه.","en":"I may stop here because it is only a short stop.","een":"No. Stopping is forbidden on the crossing and within 5 m before it, even for a short while."},{"da":"Jeg må ikke standse nærmere end 5 m før fodgængerfeltet.","fa":"نباید نزدیک‌تر از ۵ متر پیش از گذرگاه عابر بایستم.","ok":1,"eda":"Ja. Færdselsloven § 29 forbyder standsning og parkering på fodgængerfeltet og inden for 5 m før det.","efa":"بله. ماده‌ی ۲۹ قانون، توقف و پارک روی گذرگاه عابر و تا ۵ متر پیش از آن را ممنوع می‌کند.","en":"I must not stop closer than 5 m before the pedestrian crossing.","een":"Yes. Færdselsloven § 29 forbids stopping and parking on the crossing and within 5 m before it."},{"da":"Jeg må standse på selve fodgængerfeltet, hvis jeg tænder havariblinket.","fa":"اگر چراغ خطر را روشن کنم، می‌توانم روی خود گذرگاه بایستم.","ok":0,"eda":"Nej. Havariblink giver ikke ret til at standse på et fodgængerfelt.","efa":"خیر. چراغ خطر اجازه‌ی توقف روی گذرگاه عابر را نمی‌دهد.","en":"I may stop on the crossing itself if I switch on the hazard lights.","een":"No. Hazard lights do not give a right to stop on a pedestrian crossing."},{"da":"En bil, der holder lige før feltet, kan skjule fodgængere for andre trafikanter.","fa":"خودرویی که درست پیش از گذرگاه ایستاده، می‌تواند عابران را از دید دیگران پنهان کند.","ok":1,"eda":"Ja. Det er grunden til forbuddet: andre kan ikke se den, der går ud foran den holdende bil.","efa":"بله. دلیل این ممنوعیت همین است: دیگران کسی را که از جلوی خودروی ایستاده وارد خیابان می‌شود نمی‌بینند.","en":"A car standing right before the crossing can hide pedestrians from other road users.","een":"Yes. That is why it is forbidden: others cannot see someone stepping out in front of the standing car."}]},{"id":5002,"img":"newq-art/5002.png","c":"7.18","sda":"Du vil standse et øjeblik for at aflevere en pakke i butikken til højre. Hvor må du holde?","sfa":"می‌خواهید لحظه‌ای بایستید تا بسته‌ای را به مغازه‌ی سمت راست بدهید. کجا می‌توانید بایستید؟","sen":"You want to stop for a moment to drop off a parcel at the shop on the right. Where may you stop?","st":[{"da":"Halvt oppe på fortovet, så jeg ikke generer trafikken.","fa":"نیمی روی پیاده‌رو، تا مزاحم ترافیک نباشم.","ok":0,"eda":"Nej. Det er forbudt at standse eller parkere på fortovet.","efa":"خیر. توقف یا پارک روی پیاده‌رو ممنوع است.","en":"Half up on the pavement, so that I am not in the way of traffic.","een":"No. It is forbidden to stop or park on the pavement."},{"da":"På kørebanen ved siden af en bil, der holder ved kanten.","fa":"روی سواره‌رو، کنار خودرویی که لب جدول ایستاده.","ok":0,"eda":"Nej. Du skal holde ved kørebanens yderkant; ved siden af en anden bil spærrer du for trafikken.","efa":"خیر. باید کنار لبه‌ی سواره‌رو بایستید؛ کنار خودروی دیگر راه ترافیک را می‌بندید.","en":"On the carriageway beside a car that is standing at the edge.","een":"No. You must stop at the edge of the carriageway; beside another car you block the traffic."},{"da":"På cykelstien, hvis jeg tænder havariblinket.","fa":"روی مسیر دوچرخه، اگر چراغ خطر را روشن کنم.","ok":0,"eda":"Nej. Standsning og parkering er forbudt på cykelstier, også med havariblink.","efa":"خیر. توقف و پارک روی مسیر دوچرخه ممنوع است، با چراغ خطر یا بدون آن.","en":"On the cycle path, if I switch on the hazard lights.","een":"No. Stopping and parking are forbidden on cycle paths, hazard lights or not."},{"da":"Ved kørebanens yderkant, hvis der ikke gælder andre forbud.","fa":"کنار لبه‌ی سواره‌رو، اگر ممنوعیت دیگری نباشد.","ok":1,"eda":"Ja. Man standser i vejens højre side ved kørebanens yderkant, når det ikke er forbudt eller til fare.","efa":"بله. توقف در سمت راست جاده و کنار لبه‌ی سواره‌رو است، جایی که ممنوع یا خطرناک نباشد.","en":"At the edge of the carriageway, if no other ban applies.","een":"Yes. You stop on the right side of the road at the edge of the carriageway, where it is not forbidden or dangerous."}]},{"id":5003,"img":"newq-art/5003.png","c":"7.18","sda":"Du vil parkere på den ledige plads lige før sidevejen til højre. Pladsen ligger omkring 5 m fra hjørnet. Hvad gælder?","sfa":"می‌خواهید در جای خالی درست پیش از فرعیِ سمت راست پارک کنید. این جا حدود ۵ متر با گوشه فاصله دارد. چه قاعده‌ای برقرار است؟","sen":"You want to park in the free space just before the side road on the right. The space is about 5 m from the corner. What applies?","st":[{"da":"Jeg må hverken standse eller parkere nærmere end 10 m fra den tværgående kørebanes nærmeste kant.","fa":"نه می‌توانم بایستم و نه پارک کنم، اگر کمتر از ۱۰ متر با نزدیک‌ترین لبه‌ی سواره‌روی متقاطع فاصله داشته باشم.","ok":1,"eda":"Ja. Færdselsloven § 29 forbyder standsning og parkering inden for 10 m fra et vejkryds.","efa":"بله. ماده‌ی ۲۹ قانون، توقف و پارک تا ۱۰ متری تقاطع را ممنوع می‌کند.","en":"I may neither stop nor park closer than 10 m to the nearest edge of the crossing carriageway.","een":"Yes. Færdselsloven § 29 forbids stopping and parking within 10 m of a junction."},{"da":"Forbuddet gælder kun i kryds med lyssignal.","fa":"این ممنوعیت فقط در تقاطع‌های چراغ‌دار است.","ok":0,"eda":"Nej. Forbuddet gælder ved alle vejkryds.","efa":"خیر. این ممنوعیت در همه‌ی تقاطع‌ها برقرار است.","en":"The ban only applies at junctions with traffic lights.","een":"No. The ban applies at every junction."},{"da":"Reglen om de 10 m gælder kun parkering, ikke en kort standsning.","fa":"قاعده‌ی ۱۰ متر فقط برای پارک است، نه توقف کوتاه.","ok":0,"eda":"Nej. Både standsning og parkering er forbudt nærmere end 10 m fra krydset, fordi en holdende bil tager oversigten fra andre.","efa":"خیر. هم توقف و هم پارک در فاصله‌ی کمتر از ۱۰ متر از تقاطع ممنوع است، چون خودروی ایستاده دید دیگران را می‌گیرد.","en":"The 10 m rule only applies to parking, not to a short stop.","een":"No. Both stopping and parking are forbidden closer than 10 m to the junction, because a standing car blocks other people's view."},{"da":"Jeg må gerne parkere her, hvis jeg holder helt inde ved kantstenen.","fa":"اگر کاملاً کنار جدول بایستم، می‌توانم این‌جا پارک کنم.","ok":0,"eda":"Nej. Afstanden til krydset er for kort, uanset hvor tæt på kantstenen bilen holder.","efa":"خیر. فاصله تا تقاطع کم است، هر قدر هم خودرو به جدول نزدیک باشد.","en":"I may park here if I stand right in at the kerb.","een":"No. The distance to the junction is too short, however close to the kerb the car stands."}]},{"id":5004,"img":"newq-art/5004.png","c":"7.18","sda":"Du vil standse ved stoppestedet for at hente en ven. Der er ingen afmærkning på kørebanen. Hvad gælder?","sfa":"می‌خواهید کنار ایستگاه اتوبوس بایستید تا دوستی را سوار کنید. روی سواره‌رو خط‌کشی نیست. چه قاعده‌ای برقرار است؟","sen":"You want to stop at the bus stop to pick up a friend. There are no markings on the road. What applies?","st":[{"da":"Jeg må ikke standse inden for 12 m på hver side af stoppestedsskiltet.","fa":"نباید تا ۱۲ متر در هر دو طرف تابلوی ایستگاه بایستم.","ok":1,"eda":"Ja. Uden afmærkning gælder forbuddet mod standsning og parkering 12 m på hver side af skiltet.","efa":"بله. بدون خط‌کشی، ممنوعیت توقف و پارک ۱۲ متر در هر طرف تابلو است.","en":"I must not stop within 12 m on either side of the bus-stop sign.","een":"Yes. Without markings, the ban on stopping and parking covers 12 m on each side of the sign."},{"da":"Jeg må standse, hvis jeg bliver siddende i bilen.","fa":"اگر داخل خودرو بمانم، می‌توانم بایستم.","ok":0,"eda":"Nej. Forbuddet gælder også, selv om føreren bliver i bilen.","efa":"خیر. این ممنوعیت حتی اگر راننده در خودرو بماند هم برقرار است.","en":"I may stop if I stay sitting in the car.","een":"No. The ban applies even if the driver stays in the car."},{"da":"Jeg må standse, når der ikke er nogen bus i nærheden.","fa":"وقتی اتوبوسی نزدیک نیست، می‌توانم بایستم.","ok":0,"eda":"Nej. Forbuddet gælder hele tiden, ikke kun når der kommer en bus.","efa":"خیر. این ممنوعیت همیشه هست، نه فقط وقتی اتوبوس می‌آید.","en":"I may stop when there is no bus nearby.","een":"No. The ban applies all the time, not only when a bus is coming."},{"da":"Forbuddet gælder kun parkering, ikke en kort standsning.","fa":"این ممنوعیت فقط برای پارک است، نه توقف کوتاه.","ok":0,"eda":"Nej. Ved stoppestedet er både standsning og parkering forbudt.","efa":"خیر. کنار ایستگاه، هم توقف و هم پارک ممنوع است.","en":"The ban only covers parking, not a short stop.","een":"No. At the bus stop both stopping and parking are forbidden."}]},{"id":5005,"img":"newq-art/5005.png","c":"7.18","sda":"Du kører i en ensrettet gade og vil parkere i venstre side. Hvad gælder?","sfa":"در یک خیابان یک‌طرفه می‌رانید و می‌خواهید در سمت چپ پارک کنید. چه قاعده‌ای برقرار است؟","sen":"You are driving in a one-way street and want to park on the left side. What applies?","st":[{"da":"Bilen skal holde i vejens længderetning ved kanten.","fa":"خودرو باید در امتداد طول جاده و کنار لبه بایستد.","ok":1,"eda":"Ja. Køretøjer skal holde parallelt med vejen ved kørebanens yderkant.","efa":"بله. خودروها باید موازی جاده و کنار لبه‌ی سواره‌رو بایستند.","en":"The car must stand lengthwise along the road at the edge.","een":"Yes. Vehicles must stand parallel to the road at the edge of the carriageway."},{"da":"Man må aldrig parkere i venstre side af vejen.","fa":"هرگز نمی‌توان در سمت چپ جاده پارک کرد.","ok":0,"eda":"Nej. På ensrettede veje og mindre befærdede veje er det tilladt.","efa":"خیر. در جاده‌های یک‌طرفه و کم‌تردد مجاز است.","en":"You may never park on the left side of the road.","een":"No. On one-way roads and roads with little traffic it is allowed."},{"da":"På en vej med ensrettet færdsel må jeg standse og parkere i venstre side.","fa":"در جاده‌ی یک‌طرفه می‌توانم در سمت چپ بایستم و پارک کنم.","ok":1,"eda":"Ja. Færdselsloven § 28 tillader standsning og parkering i venstre side på ensrettede veje og mindre befærdede veje.","efa":"بله. ماده‌ی ۲۸ قانون، توقف و پارک در سمت چپ را در جاده‌های یک‌طرفه و کم‌تردد مجاز می‌داند.","en":"On a one-way road I may stop and park on the left side.","een":"Yes. Færdselsloven § 28 allows stopping and parking on the left on one-way roads and roads with little traffic."}]},{"id":5006,"img":"newq-art/5006.png","c":"7.18","sda":"Du parkerer kl. 14.05 ved denne tavle. Hvordan stiller du P-skiven?","sfa":"ساعت ۱۴:۰۵ کنار این تابلو پارک می‌کنید. صفحه‌ی پارک (P-skive) را چطور تنظیم می‌کنید؟","sen":"You park at 14:05 at this sign. How do you set the parking disc?","st":[{"da":"På kl. 14.05.","fa":"روی ساعت ۱۴:۰۵.","ok":0,"eda":"Nej. Skiven stilles ikke på det præcise klokkeslæt, men på det næste hele kvarter efter ankomsten, her 14.15.","efa":"خیر. صفحه روی ساعت دقیق تنظیم نمی‌شود، بلکه روی ربع‌ساعت بعد از رسیدن؛ این‌جا ۱۴:۱۵.","en":"To 14:05.","een":"No. The disc is not set to the exact time but to the next quarter hour after you arrive, here 14:15."},{"da":"På kl. 14.15.","fa":"روی ساعت ۱۴:۱۵.","ok":1,"eda":"Ja. P-skiven stilles på det kvarter, der kommer efter ankomsttidspunktet.","efa":"بله. صفحه‌ی پارک روی ربع‌ساعتی تنظیم می‌شود که بعد از زمان رسیدن می‌آید.","en":"To 14:15.","een":"Yes. The disc is set to the quarter hour that follows the time you arrived."},{"da":"På kl. 16.05, når jeg skal køre igen.","fa":"روی ساعت ۱۶:۰۵، وقتی باید دوباره حرکت کنم.","ok":0,"eda":"Nej. Skiven viser ankomsten, ikke hvornår du kører; tavlen siger, hvor længe du må holde.","efa":"خیر. صفحه زمان رسیدن را نشان می‌دهد، نه زمان رفتن را؛ تابلو می‌گوید چقدر می‌توانید بمانید.","en":"To 16:05, when I have to drive off again.","een":"No. The disc shows when you arrived, not when you leave; the sign says how long you may stay."},{"da":"På kl. 14.00.","fa":"روی ساعت ۱۴:۰۰.","ok":0,"eda":"Nej. Skiven må ikke stilles på et tidspunkt før ankomsten.","efa":"خیر. صفحه را نباید روی زمانی پیش از رسیدن تنظیم کرد.","en":"To 14:00.","een":"No. The disc must not be set to a time before you arrived."}]},{"id":5007,"img":"newq-art/5007.png","c":"7.18","sda":"Langs kantstenen er der en ubrudt gul linje. Du vil hente brød i bageren og regner med at være væk i 2 minutter. Hvad gælder?","sfa":"کنار جدول خط زرد ممتدی کشیده شده است. می‌خواهید از نانوایی نان بخرید و فکر می‌کنید ۲ دقیقه طول بکشد. چه قاعده‌ای برقرار است؟","sen":"There is an unbroken yellow line along the kerb. You want to fetch bread at the bakery and expect to be gone for 2 minutes. What applies?","st":[{"da":"Jeg må holde her i 2 minutter, fordi det ikke er parkering.","fa":"می‌توانم ۲ دقیقه این‌جا بایستم، چون پارک حساب نمی‌شود.","ok":0,"eda":"Nej. En ubrudt gul linje betyder, at også standsning er forbudt.","efa":"خیر. خط زرد ممتد یعنی توقف هم ممنوع است.","en":"I may stand here for 2 minutes because it is not parking.","een":"No. An unbroken yellow line means that stopping is forbidden too."},{"da":"Den gule linje gælder kun om natten.","fa":"خط زرد فقط شب‌ها معتبر است.","ok":0,"eda":"Nej. Linjen gælder hele døgnet, medmindre en tavle siger andet.","efa":"خیر. این خط در تمام شبانه‌روز معتبر است، مگر تابلویی چیز دیگری بگوید.","en":"The yellow line only applies at night.","een":"No. The line applies all day and night unless a sign says otherwise."},{"da":"Den gule linje betyder, at jeg højst må holde her i 15 minutter.","fa":"خط زرد یعنی حداکثر ۱۵ دقیقه می‌توانم این‌جا بایستم.","ok":0,"eda":"Nej. En ubrudt gul linje giver ingen tid at holde i; den forbyder standsning og parkering.","efa":"خیر. خط زرد ممتد هیچ زمانی برای ایستادن نمی‌دهد؛ توقف و پارک را ممنوع می‌کند.","en":"The yellow line means that I may stand here for at most 15 minutes.","een":"No. An unbroken yellow line gives no time to stand at all; it forbids stopping and parking."},{"da":"Her er både standsning og parkering forbudt.","fa":"این‌جا هم توقف و هم پارک ممنوع است.","ok":1,"eda":"Ja. Den ubrudte gule kantlinje forbyder standsning og parkering i den side af vejen.","efa":"بله. خط زرد ممتد کنار جدول، توقف و پارک را در آن سمت جاده ممنوع می‌کند.","en":"Here both stopping and parking are forbidden.","een":"Yes. The unbroken yellow kerb line forbids stopping and parking on that side of the road."}]},{"id":5008,"img":"newq-art/5008.png","c":"7.18","sda":"Du parkerer på en stejl vej ned ad bakke. Hvordan sikrer du bilen?","sfa":"در یک سراشیبی تند پارک می‌کنید. خودرو را چطور ایمن می‌کنید؟","sen":"You park on a steep road going downhill. How do you secure the car?","st":[{"da":"Jeg drejer forhjulene ind mod kantstenen.","fa":"چرخ‌های جلو را به سمت جدول می‌چرخانم.","ok":1,"eda":"Ja. Så stopper kantstenen bilen, hvis den alligevel begynder at rulle.","efa":"بله. این‌طور اگر خودرو باز هم راه بیفتد، جدول جلویش را می‌گیرد.","en":"I turn the front wheels in towards the kerb.","een":"Yes. Then the kerb stops the car if it starts to roll anyway."},{"da":"Jeg sætter bilen i bakgear, eller i P, hvis den har automatgear.","fa":"خودرو را در دنده‌عقب می‌گذارم، یا اگر اتوماتیک است، روی P.","ok":1,"eda":"Ja. Et gear, der modvirker bakken, holder bilen ekstra igen, hvis bremsen skulle svigte.","efa":"بله. دنده‌ای که خلاف شیب کار می‌کند، اگر ترمز از کار بیفتد، خودرو را بیشتر نگه می‌دارد.","en":"I put the car in reverse gear, or in P if it is an automatic.","een":"Yes. A gear that works against the slope holds the car back further if the brake should fail."},{"da":"Det er nok at sætte gearet i frigear.","fa":"کافی است دنده را خلاص بگذارم.","ok":0,"eda":"Nej. I frigear kan bilen rulle; det sikrer den ikke.","efa":"خیر. در دنده‌ی خلاص خودرو می‌تواند حرکت کند؛ ایمنش نمی‌کند.","en":"Putting the gear in neutral is enough.","een":"No. In neutral the car can roll; it does not secure it."},{"da":"Jeg trækker parkeringsbremsen.","fa":"ترمز دستی را می‌کشم.","ok":1,"eda":"Ja. Når du forlader bilen, skal du sikre, at den ikke kan sætte i gang af sig selv.","efa":"بله. وقتی خودرو را ترک می‌کنید، باید مطمئن شوید خودبه‌خود راه نمی‌افتد.","en":"I apply the parking brake.","een":"Yes. When you leave the car you must make sure it cannot start moving by itself."}]},{"id":5009,"img":"newq-art/5009.png","c":"7.18","sda":"Du har parkeret og vil stige ud. Bag dig kommer en cyklist. Hvordan forholder du dig?","sfa":"پارک کرده‌اید و می‌خواهید پیاده شوید. از پشت سر دوچرخه‌سواری می‌آید. چه می‌کنید؟","sen":"You have parked and want to get out. A cyclist is coming up behind you. What do you do?","st":[{"da":"Jeg kigger i spejlet og over skulderen, før jeg åbner døren.","fa":"پیش از باز کردن در، در آینه و از روی شانه نگاه می‌کنم.","ok":1,"eda":"Ja. Så ser du cyklister og biler bagfra, også i den blinde vinkel.","efa":"بله. این‌طور دوچرخه‌ها و خودروهای پشت سر را، حتی در نقطه‌ی کور، می‌بینید.","en":"I look in the mirror and over my shoulder before I open the door.","een":"Yes. That way you see cyclists and cars behind you, also in the blind spot."},{"da":"Jeg venter med at åbne døren, til cyklisten er kørt forbi.","fa":"باز کردن در را تا رد شدن دوچرخه‌سوار عقب می‌اندازم.","ok":1,"eda":"Ja. Når du åbner døren eller stiger ud, må der ikke opstå fare for andre.","efa":"بله. باز کردن در یا پیاده شدن نباید دیگران را به خطر بیندازد.","en":"I wait to open the door until the cyclist has passed.","een":"Yes. Opening the door or getting out must not put others in danger."},{"da":"Mine passagerer skal også sikre sig, at de kan åbne døren uden fare.","fa":"مسافرانم هم باید مطمئن شوند که می‌توانند بی‌خطر در را باز کنند.","ok":1,"eda":"Ja. Pligten til at åbne døre uden fare for andre gælder alle i bilen, ikke kun føreren.","efa":"بله. وظیفه‌ی باز کردن در بدون خطر برای دیگران، برای همه‌ی سرنشینان است، نه فقط راننده.","en":"My passengers must also make sure that they can open the door safely.","een":"Yes. The duty to open doors without danger to others applies to everyone in the car, not only the driver."},{"da":"Jeg åbner døren langsomt, så cyklisten kan nå at se den.","fa":"در را آهسته باز می‌کنم تا دوچرخه‌سوار فرصت دیدنش را داشته باشد.","ok":0,"eda":"Nej. Også en dør, der åbnes langsomt, kan få cyklisten til at styrte.","efa":"خیر. حتی دری که آهسته باز شود، می‌تواند دوچرخه‌سوار را زمین بزند.","en":"I open the door slowly so that the cyclist has time to see it.","een":"No. Even a door opened slowly can make the cyclist crash."}]},{"id":5010,"img":"newq-art/5010.png","c":"7.9","sda":"Du vil overhale traktoren. Hvad skal du sikre dig, før du begynder?","sfa":"می‌خواهید از تراکتور سبقت بگیرید. پیش از شروع، از چه چیزهایی باید مطمئن شوید؟","sen":"You want to overtake the tractor. What must you make sure of before you start?","st":[{"da":"At der ikke er andre hindringer for overhalingen længere fremme.","fa":"این‌که جلوتر مانع دیگری برای سبقت نباشد.","ok":1,"eda":"Ja. Ud over modkørende må der heller ikke være andre hindringer, fx en vejindsnævring eller et kryds.","efa":"بله. به‌جز ترافیک روبه‌رو، نباید مانع دیگری هم باشد، مثلاً باریک شدن جاده یا تقاطع.","en":"That there are no other obstacles to the overtaking further ahead.","een":"Yes. Besides oncoming traffic, there must be no other obstacles either, for example a narrowing of the road or a junction."},{"da":"At ingen bagfra er begyndt at overhale mig.","fa":"این‌که کسی از پشت شروع به سبقت از من نکرده است.","ok":1,"eda":"Ja. Du må ikke begynde at overhale, hvis en bagfra allerede er i gang med at overhale dig.","efa":"بله. اگر کسی از پشت سبقت از شما را شروع کرده، نباید سبقت را آغاز کنید.","en":"That nobody behind me has started to overtake me.","een":"Yes. You must not start overtaking if someone behind has already started to overtake you."},{"da":"At den modkørende vognbane er fri over en tilstrækkelig lang strækning.","fa":"این‌که خط روبه‌رو به اندازه‌ی کافی خالی است.","ok":1,"eda":"Ja. Den, der overhaler, skal sikre sig, at vognbanen er fri for modkørende og andre hindringer langt nok frem.","efa":"بله. سبقت‌گیرنده باید مطمئن شود که خط تا فاصله‌ی کافی از خودروی روبه‌رو و مانع خالی است.","en":"That the oncoming lane is clear over a long enough distance.","een":"Yes. The overtaking driver must make sure the lane is free of oncoming traffic and obstacles far enough ahead."},{"da":"At jeg kan komme tilbage i højre side uden fare for traktoren.","fa":"این‌که بتوانم بی‌خطر برای تراکتور به سمت راست برگردم.","ok":1,"eda":"Ja. Du skal kunne vende tilbage til højre side, uden at den overhalede kommer i fare eller ulejlighed.","efa":"بله. باید بتوانید بی‌آنکه وسیله‌ی سبقت‌گرفته به خطر یا زحمت بیفتد، به سمت راست برگردید.","en":"That I can get back to the right without danger to the tractor.","een":"Yes. You must be able to return to the right without putting the overtaken vehicle in danger or trouble."}]},{"id":5011,"img":"newq-art/5011.png","c":"7.9","sda":"En bil er ved at overhale dig. Hvordan forholder du dig?","sfa":"خودرویی در حال سبقت از شماست. چه می‌کنید؟","sen":"A car is overtaking you. What do you do?","st":[{"da":"Jeg blinker til venstre for at vise, at bilen kan overhale.","fa":"راهنمای چپ می‌زنم تا نشان دهم خودرو می‌تواند سبقت بگیرد.","ok":0,"eda":"Nej. Et blink til venstre betyder, at du selv vil ud til venstre, og kan misforstås farligt.","efa":"خیر. راهنمای چپ یعنی خودتان می‌خواهید به چپ بروید و ممکن است به‌طرز خطرناکی اشتباه فهمیده شود.","en":"I signal left to show that the car can overtake.","een":"No. A left signal means that you yourself are going to move left, and it can be dangerously misunderstood."},{"da":"Jeg holder så langt til højre som muligt.","fa":"تا جای ممکن سمت راست می‌مانم.","ok":1,"eda":"Ja. Den, der bliver overhalet, skal holde så langt til højre som muligt.","efa":"بله. کسی که از او سبقت می‌گیرند، باید تا جای ممکن سمت راست بماند.","en":"I keep as far to the right as possible.","een":"Yes. The driver being overtaken must keep as far to the right as possible."},{"da":"Jeg bremser hårdt, så bilen hurtigt kan komme forbi.","fa":"محکم ترمز می‌کنم تا خودرو زود رد شود.","ok":0,"eda":"Nej. Pludselig hård opbremsning kan skabe fare for bilerne bag dig.","efa":"خیر. ترمز ناگهانی و محکم می‌تواند خودروهای پشت سر را به خطر بیندازد.","en":"I brake hard so that the car can get past quickly.","een":"No. Sudden hard braking can put the cars behind you in danger."},{"da":"Jeg øger farten, så overhalingen går hurtigere.","fa":"سرعتم را زیاد می‌کنم تا سبقت زودتر تمام شود.","ok":0,"eda":"Nej. Det gør overhalingen længere og farligere; du må ikke øge hastigheden.","efa":"خیر. این کار سبقت را طولانی‌تر و خطرناک‌تر می‌کند؛ نباید سرعت را زیاد کنید.","en":"I speed up so that the overtaking goes faster.","een":"No. That makes the overtaking longer and more dangerous; you must not increase your speed."}]},{"id":5012,"img":"newq-art/5012.png","c":"7.9","sda":"Bussen i højre vognbane holder stille lige før fodgængerfeltet. Du kører i venstre vognbane. Hvordan forholder du dig?","sfa":"اتوبوس در خط راست درست پیش از گذرگاه عابر ایستاده است. شما در خط چپ می‌رانید. چه می‌کنید؟","sen":"The bus in the right-hand lane has stopped just before the pedestrian crossing. You are in the left-hand lane. What do you do?","st":[{"da":"Jeg sænker farten og er klar til at standse før feltet.","fa":"سرعتم را کم می‌کنم و آماده‌ی ایستادن پیش از گذرگاه هستم.","ok":1,"eda":"Ja. Bussen kan holde for en fodgænger, du ikke kan se.","efa":"بله. ممکن است اتوبوس برای عابری ایستاده باشد که شما نمی‌بینید.","en":"I slow down and am ready to stop before the crossing.","een":"Yes. The bus may be waiting for a pedestrian you cannot see."},{"da":"Der kan gå en fodgænger ud foran bussen, som jeg ikke kan se.","fa":"ممکن است عابری که نمی‌بینم از جلوی اتوبوس وارد گذرگاه شود.","ok":1,"eda":"Ja. Derfor forbyder Færdselsloven § 25 at køre forbi.","efa":"بله. به همین دلیل ماده‌ی ۲۵ قانون، رد شدن از کنار آن را ممنوع کرده است.","en":"A pedestrian I cannot see may step out in front of the bus.","een":"Yes. That is why Færdselsloven § 25 forbids driving past."},{"da":"Jeg kører forbi bussen, fordi min vognbane er fri.","fa":"از کنار اتوبوس رد می‌شوم، چون خط من خالی است.","ok":0,"eda":"Nej. Du må ikke køre forbi et køretøj, der skjuler udsynet over fodgængerfeltet.","efa":"خیر. نباید از کنار وسیله‌ای که دیدتان را به گذرگاه عابر بسته است رد شوید.","en":"I drive past the bus because my lane is free.","een":"No. You must not drive past a vehicle that blocks your view of the pedestrian crossing."}]},{"id":5013,"img":"newq-art/5013.png","c":"7.9","sda":"Du kører på en vej, hvor trafikken fra sidevejen har ubetinget vigepligt. Hvad gælder for overhaling af varevognen lige før krydset?","sfa":"در جاده‌ای هستید که ترافیک فرعی باید بی‌قیدوشرط راه بدهد. درباره‌ی سبقت از ون درست پیش از تقاطع چه قاعده‌ای برقرار است؟","sen":"You are on a road where traffic from the side road must give way unconditionally. What applies to overtaking the van just before the junction?","st":[{"da":"Jeg må overhale, fordi den tværgående trafik har ubetinget vigepligt, hvis det i øvrigt kan ske uden fare.","fa":"می‌توانم سبقت بگیرم، چون ترافیک متقاطع باید بی‌قیدوشرط راه بدهد، به شرط آن‌که از نظر دیگر هم بی‌خطر باشد.","ok":1,"eda":"Ja. Forbuddet mod overhaling i kryds gælder ikke, når den tværgående trafik har ubetinget vigepligt.","efa":"بله. ممنوعیت سبقت در تقاطع، وقتی ترافیک متقاطع باید بی‌قیدوشرط راه بدهد، اعمال نمی‌شود.","en":"I may overtake because the crossing traffic must give way unconditionally, if it can otherwise be done safely.","een":"Yes. The ban on overtaking at junctions does not apply when the crossing traffic must give way unconditionally."},{"da":"Det er altid forbudt at overhale i et vejkryds.","fa":"سبقت در تقاطع همیشه ممنوع است.","ok":0,"eda":"Nej. Der er undtagelser, blandt andet når den tværgående trafik har ubetinget vigepligt.","efa":"خیر. استثنا وجود دارد، از جمله وقتی ترافیک متقاطع باید بی‌قیدوشرط راه بدهد.","en":"Overtaking at a junction is always forbidden.","een":"No. There are exceptions, for example when the crossing traffic must give way unconditionally."},{"da":"Jeg skal sikre mig, at ingen bagfra er begyndt at overhale mig.","fa":"باید مطمئن شوم که کسی از پشت شروع به سبقت از من نکرده است.","ok":1,"eda":"Ja. Det skal du altid sikre dig, før du begynder at overhale.","efa":"بله. همیشه پیش از شروع سبقت باید از این مطمئن شوید.","en":"I must make sure that nobody behind has started to overtake me.","een":"Yes. You must always make sure of that before you start overtaking."},{"da":"Jeg skal stadig sikre mig, at varevognen ikke skal svinge til venstre.","fa":"باز هم باید مطمئن شوم که ون قصد گردش به چپ ندارد.","ok":1,"eda":"Ja. En bil, der svinger til venstre, må ikke overhales i venstre side.","efa":"بله. از خودرویی که به چپ می‌پیچد نباید از سمت چپ سبقت گرفت.","en":"I must still make sure the van is not going to turn left.","een":"Yes. A car turning left must not be overtaken on its left."}]},{"id":5014,"img":"newq-art/5014.png","c":"7.9","sda":"Lige før krydset kører en cyklist foran dig. Hvad gælder for overhaling af cyklisten?","sfa":"درست پیش از تقاطع، دوچرخه‌سواری جلوی شما می‌رود. درباره‌ی سبقت از او چه قاعده‌ای برقرار است؟","sen":"Just before the junction a cyclist is riding in front of you. What applies to overtaking the cyclist?","st":[{"da":"Jeg behøver ikke holde tilbage for trafik fra højre, når jeg er i gang med at overhale.","fa":"وقتی در حال سبقت هستم، لازم نیست به ترافیک سمت راست راه بدهم.","ok":0,"eda":"Nej. Højrevigepligten i krydset gælder stadig.","efa":"خیر. حق تقدم دست راست در تقاطع همچنان برقرار است.","en":"I do not need to give way to traffic from the right while I am overtaking.","een":"No. The duty to give way to the right in the junction still applies."},{"da":"Jeg holder øje med, om cyklisten vil svinge, fx til venstre i krydset.","fa":"مراقبم که آیا دوچرخه‌سوار می‌خواهد بپیچد، مثلاً در تقاطع به چپ.","ok":1,"eda":"Ja. Cyklisten kan svinge i krydset; se efter tegn, før du overhaler.","efa":"بله. دوچرخه‌سوار ممکن است در تقاطع بپیچد؛ پیش از سبقت دنبال علامتش باشید.","en":"I watch whether the cyclist is going to turn, for example left at the junction.","een":"Yes. The cyclist may turn at the junction; look for signals before you overtake."},{"da":"Forbuddet mod overhaling i kryds gælder ikke overhaling af en tohjulet cykel.","fa":"ممنوعیت سبقت در تقاطع شامل دوچرخه‌ی دوچرخ نمی‌شود.","ok":1,"eda":"Ja. Færdselsloven § 23 undtager overhaling af tohjulede cykler og små knallerter.","efa":"بله. ماده‌ی ۲۳ قانون، سبقت از دوچرخه و موپد کوچک دوچرخ را استثنا کرده است.","en":"The ban on overtaking at junctions does not apply to a two-wheeled bicycle.","een":"Yes. Færdselsloven § 23 makes an exception for overtaking two-wheeled bicycles and small mopeds."},{"da":"Det skal kunne ske uden fare, og jeg skal holde god afstand til siden.","fa":"باید بی‌خطر باشد و باید فاصله‌ی پهلوی خوبی نگه دارم.","ok":1,"eda":"Ja. Undtagelsen fritager ikke for kravet om sikkerhed og sideafstand.","efa":"بله. این استثنا نیاز به ایمنی و فاصله‌ی پهلوی را از بین نمی‌برد.","en":"It must be safe, and I must keep a good side distance.","een":"Yes. The exception does not remove the need for safety and side distance."}]},{"id":5015,"img":"newq-art/5015.png","c":"7.9","sda":"Foran dig kører en langsom varevogn op mod en bakketop, hvor du ikke kan se, hvad der kommer. Hvad gælder?","sfa":"جلوی شما ونی آهسته به سمت بالای تپه‌ای می‌رود که نمی‌بینید پشتش چه می‌آید. چه قاعده‌ای برقرار است؟","sen":"In front of you a slow van is driving up towards a hilltop where you cannot see what is coming. What applies?","st":[{"da":"Jeg må ikke overhale ved en uoverskuelig bakketop.","fa":"در بالای تپه‌ی بی‌دید نباید سبقت بگیرم.","ok":1,"eda":"Ja. Overhaling er forbudt, hvor udsynet fremad er begrænset ved bakker og sving.","efa":"بله. سبقت جایی که دید جلو به‌خاطر تپه یا پیچ محدود است، ممنوع است.","en":"I must not overtake at a blind hilltop.","een":"Yes. Overtaking is forbidden where the view ahead is restricted by hills and bends."},{"da":"Forbuddet gælder ikke, hvis der er mindst to vognbaner i min retning, som modkørende ikke må bruge.","fa":"اگر در جهت من دست‌کم دو خط باشد که ترافیک روبه‌رو اجازه‌ی استفاده از آن را ندارد، این ممنوعیت نیست.","ok":1,"eda":"Ja. Så kan du overhale uden at komme over i de modkørendes side.","efa":"بله. در این حالت می‌توانید بدون رفتن به سمت ترافیک روبه‌رو سبقت بگیرید.","en":"The ban does not apply if there are at least two lanes in my direction that oncoming traffic may not use.","een":"Yes. Then you can overtake without moving into the oncoming side."},{"da":"Jeg må overhale, hvis jeg giver fuld gas og skynder mig.","fa":"اگر گاز بدهم و عجله کنم، می‌توانم سبقت بگیرم.","ok":0,"eda":"Nej. Fart ændrer ikke, at en modkørende kan dukke op over bakken.","efa":"خیر. سرعت این واقعیت را عوض نمی‌کند که ممکن است خودرویی از روبه‌رو از پشت تپه برسد.","en":"I may overtake if I accelerate hard and hurry.","een":"No. Speed does not change that an oncoming car may appear over the hill."}]},{"id":5016,"img":"newq-art/5016.png","c":"7.9","sda":"Den grå bil foran dig blinker til venstre og holder ved midterlinjen for at svinge. Hvordan må du køre forbi?","sfa":"خودروی خاکستری جلوی شما راهنمای چپ زده و کنار خط وسط ایستاده تا بپیچد. چطور می‌توانید از کنارش رد شوید؟","sen":"The grey car in front of you is indicating left and waiting at the centre line to turn. How may you pass it?","st":[{"da":"Jeg skal overhale den i venstre side.","fa":"باید از سمت چپش سبقت بگیرم.","ok":0,"eda":"Nej. Det ville være farligt: bilen er ved at svinge den vej, og der kommer en modkørende.","efa":"خیر. خطرناک است: خودرو در حال پیچیدن به همان سمت است و از روبه‌رو هم خودرویی می‌آید.","en":"I must overtake it on the left.","een":"No. That would be dangerous: the car is about to turn that way, and an oncoming car is coming."},{"da":"Jeg må overhale den i højre side, hvis det kan ske uden fare.","fa":"اگر بی‌خطر باشد، می‌توانم از سمت راستش سبقت بگیرم.","ok":1,"eda":"Ja. En bil, der svinger til venstre, må overhales i højre side.","efa":"بله. از خودرویی که به چپ می‌پیچد، می‌توان از سمت راست سبقت گرفت.","en":"I may overtake it on the right, if it can be done safely.","een":"Yes. A car turning left may be overtaken on its right."},{"da":"Jeg holder øje med cyklister og fodgængere i højre side.","fa":"مراقب دوچرخه‌سواران و عابران سمت راست هستم.","ok":1,"eda":"Ja. Når du kører forbi i højre side, er du tæt på vejkanten, hvor der kan være bløde trafikanter.","efa":"بله. وقتی از سمت راست رد می‌شوید، به لبه‌ی جاده نزدیکید و ممکن است کاربران آسیب‌پذیر آن‌جا باشند.","en":"I watch out for cyclists and pedestrians on the right.","een":"Yes. When you pass on the right you are close to the road edge, where there may be vulnerable road users."}]},{"id":5017,"img":"newq-art/5017.png","c":"7.9","sda":"Foran dig kører en traktor. Lidt længere fremme er en jernbaneoverkørsel. Hvad gælder for overhaling?","sfa":"جلوی شما تراکتوری می‌رود. کمی جلوتر تقاطع راه‌آهن است. درباره‌ی سبقت چه قاعده‌ای برقرار است؟","sen":"A tractor is driving in front of you. A little further ahead there is a level crossing. What applies to overtaking?","st":[{"da":"Jeg må ikke overhale umiddelbart før og på overkørslen.","fa":"درست پیش از تقاطع راه‌آهن و روی آن نباید سبقت بگیرم.","ok":1,"eda":"Ja. Det står i Færdselsloven § 23.","efa":"بله. این در ماده‌ی ۲۳ قانون آمده است.","en":"I must not overtake immediately before and on the level crossing.","een":"Yes. That is in Færdselsloven § 23."},{"da":"Jeg må heller ikke standse på selve overkørslen.","fa":"روی خود تقاطع راه‌آهن هم نباید بایستم.","ok":1,"eda":"Ja. Det er forbudt at standse og parkere på en jernbaneoverkørsel.","efa":"بله. توقف و پارک روی تقاطع راه‌آهن ممنوع است.","en":"I must not stop on the level crossing itself either.","een":"Yes. Stopping and parking on a level crossing are forbidden."},{"da":"Jeg må overhale, hvis der ikke kommer noget tog.","fa":"اگر قطاری نیاید، می‌توانم سبقت بگیرم.","ok":0,"eda":"Nej. Overhaling er forbudt umiddelbart før og på en jernbaneoverkørsel, uanset tog.","efa":"خیر. سبقت درست پیش از تقاطع راه‌آهن و روی آن ممنوع است، چه قطار بیاید چه نه.","en":"I may overtake if no train is coming.","een":"No. Overtaking is forbidden immediately before and on a level crossing, train or not."},{"da":"Jeg venter, til vi er over overkørslen, og det i øvrigt er sikkert.","fa":"صبر می‌کنم تا از تقاطع رد شویم و سبقت از نظر دیگر هم بی‌خطر باشد.","ok":1,"eda":"Ja. Efter overkørslen gælder de almindelige regler for overhaling igen.","efa":"بله. بعد از تقاطع، قاعده‌های معمول سبقت دوباره برقرارند.","en":"I wait until we are over the crossing and it is otherwise safe.","een":"Yes. After the crossing the ordinary overtaking rules apply again."}]},{"id":5018,"img":"newq-art/5018.png","c":"7.9","sda":"Du kører langsomt med campingvogn på en smal, snoet vej, og der er dannet kø bag dig. Hvordan forholder du dig?","sfa":"با کاروان در جاده‌ای باریک و پرپیچ آهسته می‌رانید و پشت سرتان صف تشکیل شده است. چه می‌کنید؟","sen":"You are driving slowly with a caravan on a narrow, winding road, and a queue has formed behind you. What do you do?","st":[{"da":"Jeg sænker farten og kører ind til siden, så snart det er muligt, så de andre kan komme forbi.","fa":"به محض این‌که شد، سرعت را کم می‌کنم و کنار می‌کشم تا بقیه رد شوند.","ok":1,"eda":"Ja. Færdselsloven § 22 kræver, at du gør det lettere at overhale dig, og om nødvendigt standser.","efa":"بله. ماده‌ی ۲۲ قانون می‌خواهد که سبقت از خودتان را آسان کنید و در صورت لزوم بایستید.","en":"I slow down and pull over as soon as possible so that the others can get past.","een":"Yes. Færdselsloven § 22 requires you to make it easier to overtake you, stopping if necessary."},{"da":"Det er de andres ansvar at vente; jeg behøver ikke gøre noget.","fa":"صبر کردن وظیفه‌ی بقیه است؛ من لازم نیست کاری بکنم.","ok":0,"eda":"Nej. Loven giver også den langsomme et ansvar for at lette overhalingen.","efa":"خیر. قانون به راننده‌ی کندرو هم وظیفه‌ی آسان کردن سبقت را می‌دهد.","en":"It is the others' job to wait; I do not need to do anything.","een":"No. The law also gives the slow driver a duty to make overtaking easier."},{"da":"Jeg kører hurtigere end sikkert, så køen kan følge med.","fa":"تندتر از حد ایمن می‌رانم تا صف بتواند همراهم بیاید.","ok":0,"eda":"Nej. Du må aldrig køre hurtigere, end forholdene og vogntoget tillader.","efa":"خیر. هرگز نباید تندتر از آن‌چه شرایط و خودرو با یدک اجازه می‌دهد برانید.","en":"I drive faster than is safe so that the queue can keep up.","een":"No. You must never drive faster than the conditions and the combination allow."},{"da":"Jeg holder øje med trafikken bagfra.","fa":"ترافیک پشت سر را زیر نظر دارم.","ok":1,"eda":"Ja. Den, der kører langsomt eller fylder meget, skal være særligt opmærksom på trafikken bagfra.","efa":"بله. کسی که آهسته می‌رود یا جای زیادی می‌گیرد، باید به ترافیک پشت سر توجه ویژه داشته باشد.","en":"I keep an eye on the traffic behind.","een":"Yes. Someone driving slowly or taking up much space must pay special attention to the traffic behind."}]},{"id":5019,"img":"newq-art/5019.png","c":"6.1","sda":"Du nærmer dig dette kryds. Hvad betyder tavlen og hajtænderne?","sfa":"به این تقاطع نزدیک می‌شوید. تابلو و دندان‌کوسه‌ها یعنی چه؟","sen":"You are approaching this junction. What do the sign and the shark teeth mean?","st":[{"da":"Jeg har kun vigepligt for trafikken fra højre.","fa":"فقط باید به ترافیک سمت راست راه بدهم.","ok":0,"eda":"Nej. Ubetinget vigepligt gælder for trafikken fra begge sider.","efa":"خیر. راه دادن بی‌قیدوشرط برای ترافیک هر دو طرف است.","en":"I only have to give way to traffic from the right.","een":"No. Unconditional give-way applies to traffic from both sides."},{"da":"Jeg har ubetinget vigepligt for trafikken på den tværgående vej fra begge sider.","fa":"باید بی‌قیدوشرط به ترافیک جاده‌ی متقاطع از هر دو طرف راه بدهم.","ok":1,"eda":"Ja. Tavle B 11 og hajtænder betyder ubetinget vigepligt.","efa":"بله. تابلوی B 11 و دندان‌کوسه یعنی باید بی‌قیدوشرط راه بدهید.","en":"I must give way unconditionally to the traffic on the crossing road from both sides.","een":"Yes. Sign B 11 and shark teeth mean you must give way unconditionally."},{"da":"Jeg må køre ud foran en bil på den tværgående vej, hvis den kan nå at bremse.","fa":"می‌توانم جلوی خودرویی در جاده‌ی متقاطع وارد شوم، اگر فرصت ترمز کردن داشته باشد.","ok":0,"eda":"Nej. Du må kun køre ud, hvis det kan ske uden fare eller ulempe for dem, du skal holde tilbage for; de må ikke skulle bremse for dig.","efa":"خیر. فقط وقتی می‌توانید وارد شوید که برای کسانی که باید به آن‌ها راه بدهید خطر یا مزاحمتی نداشته باشد؛ آن‌ها نباید مجبور شوند برایتان ترمز کنند.","en":"I may drive out in front of a car on the crossing road if it has time to brake.","een":"No. You may only drive out if it can be done without danger or inconvenience to those you must give way to; they must not have to brake for you."},{"da":"Jeg skal altid standse helt, selv om vejen er fri.","fa":"باید همیشه کامل بایستم، حتی اگر جاده خالی باشد.","ok":0,"eda":"Nej. Fuldt stop kræves ved stoptavlen B 13, ikke ved B 11.","efa":"خیر. توقف کامل برای تابلوی ایست B 13 لازم است، نه برای B 11.","en":"I must always stop completely, even if the road is clear.","een":"No. A full stop is required at the stop sign B 13, not at B 11."}]},{"id":5020,"img":"newq-art/5020.png","c":"6.1","sda":"Vejen på tværs er helt fri. Hvordan forholder du dig ved tavlen?","sfa":"جاده‌ی متقاطع کاملاً خالی است. کنار این تابلو چه می‌کنید؟","sen":"The crossing road is completely clear. What do you do at the sign?","st":[{"da":"Jeg standser helt ved stoplinjen.","fa":"کنار خط ایست کاملاً می‌ایستم.","ok":1,"eda":"Ja. Ved stoptavlen B 13 skal du altid standse helt ved stoplinjen.","efa":"بله. کنار تابلوی ایست B 13 همیشه باید پشت خط ایست کاملاً بایستید.","en":"I stop completely at the stop line.","een":"Yes. At the stop sign B 13 you must always stop completely at the stop line."},{"da":"Jeg har ubetinget vigepligt for trafikken fra begge sider.","fa":"باید بی‌قیدوشرط به ترافیک هر دو طرف راه بدهم.","ok":1,"eda":"Ja. Stoptavlen giver både stoppligt og ubetinget vigepligt.","efa":"بله. تابلوی ایست هم وظیفه‌ی ایستادن می‌دهد و هم راه دادن بی‌قیدوشرط.","en":"I must give way unconditionally to traffic from both sides.","een":"Yes. The stop sign gives both a duty to stop and unconditional give-way."},{"da":"Jeg må køre over uden at standse, når der ikke kommer nogen.","fa":"وقتی کسی نمی‌آید، می‌توانم بدون ایستادن رد شوم.","ok":0,"eda":"Nej. Stoppligten gælder også, når vejen er fri.","efa":"خیر. وظیفه‌ی ایستادن حتی وقتی جاده خالی است هم برقرار است.","en":"I may drive across without stopping when nobody is coming.","een":"No. The duty to stop applies even when the road is clear."}]},{"id":5021,"img":"newq-art/5021.png","c":"6.1","sda":"Du kører forbi denne tavle uden for byen. Hvad betyder den?","sfa":"بیرون شهر از کنار این تابلو رد می‌شوید. یعنی چه؟","sen":"You pass this sign outside town. What does it mean?","st":[{"da":"Trafikken fra sidevejene skal holde tilbage for mig, men jeg skal stadig være opmærksom.","fa":"ترافیک فرعی‌ها باید به من راه بدهد، ولی باز هم باید مراقب باشم.","ok":1,"eda":"Ja. Trafikken ud fra sidevejene har ubetinget vigepligt, men du skal altid være agtpågivende.","efa":"بله. ترافیکی که از فرعی‌ها می‌آید باید بی‌قیدوشرط راه بدهد، ولی شما همیشه باید هوشیار باشید.","en":"Traffic from the side roads must give way to me, but I must still pay attention.","een":"Yes. Traffic coming out of the side roads must give way unconditionally, but you must always be attentive."},{"da":"Jeg kører på en hovedvej.","fa":"در جاده‌ی اصلی می‌رانم.","ok":1,"eda":"Ja. Den gule rombe med hvid kant (B 16) betyder hovedvej.","efa":"بله. لوزی زرد با حاشیه‌ی سفید (B 16) یعنی جاده‌ی اصلی.","en":"I am driving on a main road.","een":"Yes. The yellow diamond with a white border (B 16) means main road."},{"da":"Uden for tættere bebygget område må jeg ikke parkere på kørebanen på denne vej.","fa":"بیرون از منطقه‌ی مسکونی، نباید روی سواره‌روی این جاده پارک کنم.","ok":1,"eda":"Ja. Parkering på kørebanen af hovedveje uden for tættere bebygget område er forbudt.","efa":"بله. پارک روی سواره‌روی جاده‌های اصلی بیرون از مناطق مسکونی ممنوع است.","en":"Outside built-up areas I must not park on the carriageway of this road.","een":"Yes. Parking on the carriageway of main roads outside built-up areas is forbidden."},{"da":"Jeg skal holde tilbage for trafik fra højre.","fa":"باید به ترافیک سمت راست راه بدهم.","ok":0,"eda":"Nej. På hovedvejen gælder højrereglen ikke over for sidevejene.","efa":"خیر. در جاده‌ی اصلی، قاعده‌ی دست راست در برابر فرعی‌ها اعمال نمی‌شود.","en":"I must give way to traffic from the right.","een":"No. On the main road the right-hand rule does not apply towards the side roads."}]},{"id":5022,"img":"newq-art/5022.png","c":"6.1","sda":"Du kører forbi denne tavle. Foran dig kører en cyklist og længere fremme en bil. Hvad gælder?","sfa":"از کنار این تابلو رد می‌شوید. جلوی شما یک دوچرخه‌سوار و جلوتر یک خودرو می‌رود. چه قاعده‌ای برقرار است؟","sen":"You pass this sign. In front of you there is a cyclist, and further ahead a car. What applies?","st":[{"da":"Jeg må overhale cyklisten, hvis det kan ske uden fare.","fa":"اگر بی‌خطر باشد، می‌توانم از دوچرخه‌سوار سبقت بگیرم.","ok":1,"eda":"Ja. Forbuddet (C 51) gælder ikke overhaling af tohjulede cykler og tohjulede små knallerter.","efa":"بله. این ممنوعیت (C 51) شامل سبقت از دوچرخه و موپد کوچک دوچرخ نمی‌شود.","en":"I may overtake the cyclist if it can be done safely.","een":"Yes. The ban (C 51) does not cover overtaking two-wheeled bicycles and two-wheeled small mopeds."},{"da":"Jeg må overhale en motorcykel på strækningen.","fa":"در این مسیر می‌توانم از موتورسیکلت سبقت بگیرم.","ok":0,"eda":"Nej. Undtagelsen gælder kun tohjulede cykler og små knallerter, ikke motorcykler.","efa":"خیر. این استثنا فقط برای دوچرخه و موپد کوچک دوچرخ است، نه موتورسیکلت.","en":"I may overtake a motorcycle on this stretch.","een":"No. The exception only covers two-wheeled bicycles and small mopeds, not motorcycles."},{"da":"Jeg må overhale alle køretøjer, når der ikke er modkørende.","fa":"وقتی ترافیک روبه‌رو نیست، می‌توانم از هر وسیله‌ای سبقت بگیرم.","ok":0,"eda":"Nej. Forbuddet gælder, uanset om der er modkørende.","efa":"خیر. این ممنوعیت برقرار است، چه ترافیک روبه‌رو باشد چه نباشد.","en":"I may overtake any vehicle when there is no oncoming traffic.","een":"No. The ban applies whether there is oncoming traffic or not."},{"da":"Jeg må ikke overhale bilen på strækningen.","fa":"در این مسیر نباید از خودرو سبقت بگیرم.","ok":1,"eda":"Ja. Tavlen forbyder overhaling af alle andre køretøjer end tohjulede cykler og små knallerter, medmindre de svinger bort fra vejen.","efa":"بله. این تابلو سبقت از همه‌ی وسایل به‌جز دوچرخه و موپد کوچک دوچرخ را ممنوع می‌کند، مگر وسیله‌ای که از جاده خارج می‌شود.","en":"I must not overtake the car on this stretch.","een":"Yes. The sign forbids overtaking any vehicles other than two-wheeled bicycles and small mopeds, unless they are turning off the road."}]},{"id":5023,"img":"newq-art/5023.png","c":"6.1","sda":"Du kører forbi denne tavle uden for byen. Vejen er våd. Hvad gælder?","sfa":"بیرون شهر از کنار این تابلو رد می‌شوید. جاده خیس است. چه قاعده‌ای برقرار است؟","sen":"You pass this sign outside town. The road is wet. What applies?","st":[{"da":"Jeg må højst køre 70 km/t på strækningen.","fa":"در این مسیر حداکثر ۷۰ کیلومتر بر ساعت می‌توانم برانم.","ok":1,"eda":"Ja. Tavle C 55 angiver den højst tilladte hastighed.","efa":"بله. تابلوی C 55 حداکثر سرعت مجاز را نشان می‌دهد.","en":"I may drive at most 70 km/h on this stretch.","een":"Yes. Sign C 55 gives the highest permitted speed."},{"da":"Jeg skal mindst køre 70 km/t.","fa":"باید دست‌کم ۷۰ کیلومتر بر ساعت برانم.","ok":0,"eda":"Nej. Den røde ring betyder et forbud, altså en højeste hastighed, ikke en mindste.","efa":"خیر. حلقه‌ی قرمز یعنی ممنوعیت، یعنی حداکثر سرعت، نه حداقل.","en":"I must drive at least 70 km/h.","een":"No. The red ring means a ban, a highest speed, not a lowest one."},{"da":"Jeg skal køre langsommere, hvis forholdene kræver det.","fa":"اگر شرایط ایجاب کند، باید آهسته‌تر برانم.","ok":1,"eda":"Ja. Hastigheden skal altid afpasses efter forholdene, fx en våd vej.","efa":"بله. سرعت همیشه باید با شرایط، مثلاً جاده‌ی خیس، جور باشد.","en":"I must drive slower if the conditions call for it.","een":"Yes. Your speed must always suit the conditions, for example a wet road."}]},{"id":5024,"img":"newq-art/5024.png","c":"6.1","sda":"Du kører forbi denne tavle. Hvad er den højst tilladte hastighed herefter, når der ikke er andre tavler?","sfa":"از کنار این تابلو رد می‌شوید. اگر تابلوی دیگری نباشد، از این‌جا به بعد حداکثر سرعت مجاز چقدر است؟","sen":"You pass this sign. What is the highest permitted speed after it when there are no other signs?","st":[{"da":"50 km/t.","fa":"۵۰ کیلومتر بر ساعت.","ok":1,"eda":"Ja. Tavlen (E 55) markerer tættere bebygget område, hvor grænsen er 50 km/t.","efa":"بله. این تابلو (E 55) شروع منطقه‌ی مسکونی است که حد سرعتش ۵۰ کیلومتر بر ساعت است.","en":"50 km/h.","een":"Yes. The sign (E 55) marks a built-up area, where the limit is 50 km/h."},{"da":"70 km/t.","fa":"۷۰ کیلومتر بر ساعت.","ok":0,"eda":"Nej. 70 km/t gælder kun, hvor en tavle viser det.","efa":"خیر. ۷۰ کیلومتر بر ساعت فقط جایی است که تابلویی آن را نشان دهد.","en":"70 km/h.","een":"No. 70 km/h only applies where a sign shows it."},{"da":"60 km/t.","fa":"۶۰ کیلومتر بر ساعت.","ok":0,"eda":"Nej. Den generelle grænse i tættere bebygget område er 50 km/t.","efa":"خیر. حد عمومی سرعت در مناطق مسکونی ۵۰ کیلومتر بر ساعت است.","en":"60 km/h.","een":"No. The general limit in built-up areas is 50 km/h."},{"da":"80 km/t.","fa":"۸۰ کیلومتر بر ساعت.","ok":0,"eda":"Nej. 80 km/t gælder uden for tættere bebygget område.","efa":"خیر. ۸۰ کیلومتر بر ساعت برای بیرون از مناطق مسکونی است.","en":"80 km/h.","een":"No. 80 km/h applies outside built-up areas."}]},{"id":5025,"img":"newq-art/5025.png","c":"6.1","sda":"Midt på vejen er der to ubrudte hvide linjer side om side. Hvad gælder?","sfa":"وسط جاده دو خط سفید ممتد کنار هم کشیده شده است. چه قاعده‌ای برقرار است؟","sen":"In the middle of the road there are two unbroken white lines side by side. What applies?","st":[{"da":"Linjerne adskiller de to kørselsretninger.","fa":"این خط‌ها دو جهت حرکت را از هم جدا می‌کنند.","ok":1,"eda":"Ja. En dobbelt spærrelinje midt på vejen adskiller de modsatte kørselsretninger.","efa":"بله. خط ممتد دوبل وسط جاده، دو جهت مخالف را از هم جدا می‌کند.","en":"The lines separate the two directions of traffic.","een":"Yes. A double barrier line in the middle of the road separates the opposite directions."},{"da":"Jeg må overskride dem for at overhale, hvis vejen er fri.","fa":"اگر جاده خالی باشد، برای سبقت می‌توانم از آن‌ها رد شوم.","ok":0,"eda":"Nej. Linjerne må ikke overskrides for at overhale, heller ikke når vejen er fri.","efa":"خیر. حتی وقتی جاده خالی است، برای سبقت نباید از این خط‌ها عبور کرد.","en":"I may cross them to overtake if the road is clear.","een":"No. The lines must not be crossed to overtake, not even when the road is clear."},{"da":"Det er spærrelinjer, som jeg ikke må overskride.","fa":"این‌ها خط ممتدند و نباید از آن‌ها رد شوم.","ok":1,"eda":"Ja. Spærrelinjer (Q 44) må ikke overskrides eller krydses.","efa":"بله. از خط‌های ممتد (Q 44) نباید عبور کرد.","en":"They are barrier lines that I must not cross.","een":"Yes. Barrier lines (Q 44) must not be crossed."},{"da":"Jeg må heller ikke køre over dem for at svinge ind til ejendommen til venstre.","fa":"برای پیچیدن به ملک سمت چپ هم نباید از آن‌ها رد شوم.","ok":1,"eda":"Ja. Der er ingen undtagelse for at svinge ind til en ejendom.","efa":"بله. برای پیچیدن به یک ملک استثنایی وجود ندارد.","en":"I must not drive over them to turn into the property on the left either.","een":"Yes. There is no exception for turning into a property."}]},{"id":5026,"img":"newq-art/5026.png","c":"7.6","sda":"Bussen ved stoppestedet blinker til venstre. Hvordan forholder du dig?","sfa":"اتوبوس کنار ایستگاه راهنمای چپ زده است. چه می‌کنید؟","sen":"The bus at the stop is indicating left. What do you do?","st":[{"da":"Jeg sænker farten og standser om nødvendigt, så bussen kan køre ud.","fa":"سرعتم را کم می‌کنم و در صورت لزوم می‌ایستم تا اتوبوس بتواند حرکت کند.","ok":1,"eda":"Ja. I tættere bebygget område skal du give bussen mulighed for at køre fra stoppestedet, når den giver tegn.","efa":"بله. در منطقه‌ی مسکونی، وقتی اتوبوس علامت می‌دهد، باید بگذارید از ایستگاه حرکت کند.","en":"I slow down and stop if necessary so that the bus can pull out.","een":"Yes. In built-up areas you must let the bus pull away from the stop when it signals."},{"da":"Reglen gælder kun uden for byen.","fa":"این قاعده فقط بیرون شهر است.","ok":0,"eda":"Nej. Reglen gælder netop i tættere bebygget område.","efa":"خیر. این قاعده دقیقاً برای مناطق مسکونی است.","en":"The rule only applies outside town.","een":"No. The rule applies precisely in built-up areas."},{"da":"Buschaufføren skal stadig være forsigtig, når bussen kører ud.","fa":"راننده‌ی اتوبوس هم هنگام حرکت باید مراقب باشد.","ok":1,"eda":"Ja. Reglen fritager ikke bussens fører for at udvise særlig forsigtighed.","efa":"بله. این قاعده راننده‌ی اتوبوس را از احتیاط ویژه معاف نمی‌کند.","en":"The bus driver must still be careful when pulling out.","een":"Yes. The rule does not free the bus driver from taking special care."},{"da":"Jeg har forkørselsret, fordi jeg allerede er på kørebanen.","fa":"حق تقدم با من است، چون از قبل روی سواره‌رو هستم.","ok":0,"eda":"Nej. Færdselsloven § 19 pålægger dig at give bussen plads til at køre ud.","efa":"خیر. ماده‌ی ۱۹ قانون از شما می‌خواهد به اتوبوس جا بدهید تا حرکت کند.","en":"I have the right of way because I am already on the carriageway.","een":"No. Færdselsloven § 19 requires you to give the bus room to pull out."}]},{"id":5027,"img":"newq-art/5027.png","c":"7.6","sda":"Skolebussen holder for at lade børn stige af. Hvordan forholder du dig?","sfa":"اتوبوس مدرسه ایستاده تا بچه‌ها پیاده شوند. چه می‌کنید؟","sen":"The school bus has stopped to let children off. What do you do?","st":[{"da":"Jeg viser særlig agtpågivenhed og sænker farten.","fa":"احتیاط ویژه می‌کنم و سرعتم را کم می‌کنم.","ok":1,"eda":"Ja. Ved en skolebus, der holder for at lade passagerer stige af, skal du vise særlig agtpågivenhed.","efa":"بله. کنار اتوبوس مدرسه‌ای که برای پیاده شدن مسافران ایستاده، باید احتیاط ویژه کنید.","en":"I take special care and slow down.","een":"Yes. Near a school bus stopped to let passengers off you must take special care."},{"da":"Jeg kører forbi med uændret fart, fordi bussen holder i sin egen side.","fa":"با همان سرعت رد می‌شوم، چون اتوبوس در سمت خودش ایستاده است.","ok":0,"eda":"Nej. Børnene kan komme ud på vejen; du skal være klar til at standse.","efa":"خیر. بچه‌ها ممکن است وارد جاده شوند؛ باید آماده‌ی ایستادن باشید.","en":"I drive past at the same speed because the bus is on its own side.","een":"No. The children may come out onto the road; you must be ready to stop."},{"da":"Jeg dytter, så børnene ved, at jeg kommer.","fa":"بوق می‌زنم تا بچه‌ها بفهمند می‌آیم.","ok":0,"eda":"Nej. Et dyt kan forskrække børnene, så de gør noget uventet; hornet bruges kun for at afværge fare.","efa":"خیر. بوق ممکن است بچه‌ها را بترساند و کار غیرمنتظره‌ای بکنند؛ بوق فقط برای دفع خطر است.","en":"I sound the horn so that the children know I am coming.","een":"No. A horn can startle the children into doing something unexpected; the horn is only for averting danger."},{"da":"Et barn kan løbe ud foran eller bag bussen.","fa":"ممکن است بچه‌ای از جلو یا پشت اتوبوس وارد جاده شود.","ok":1,"eda":"Ja. Børn ser ikke altid efter trafikken, når de skal over vejen.","efa":"بله. بچه‌ها همیشه هنگام عبور از جاده به ترافیک نگاه نمی‌کنند.","en":"A child may run out in front of or behind the bus.","een":"Yes. Children do not always look out for traffic when they cross the road."}]},{"id":5028,"img":"newq-art/5028.png","c":"7.6","sda":"To fodgængere går i venstre side af vejen og kommer imod dig. Hvordan forholder du dig?","sfa":"دو عابر در سمت چپ جاده به طرف شما می‌آیند. چه می‌کنید؟","sen":"Two pedestrians are walking on the left side of the road towards you. What do you do?","st":[{"da":"Jeg dytter, så de går ud i rabatten.","fa":"بوق می‌زنم تا به کنار جاده بروند.","ok":0,"eda":"Nej. Hornet må kun bruges for at afværge fare, ikke for at få andre til at flytte sig.","efa":"خیر. بوق فقط برای دفع خطر است، نه برای کنار زدن دیگران.","en":"I sound the horn so that they step onto the verge.","een":"No. The horn may only be used to avert danger, not to make others move."},{"da":"Hvis den modkørende bil og fodgængerne mødes ved mig, venter jeg bag fodgængerne.","fa":"اگر خودروی روبه‌رو و عابران هم‌زمان به من برسند، پشت عابران صبر می‌کنم.","ok":1,"eda":"Ja. Så kan du give fodgængerne plads uden at komme for tæt på den modkørende.","efa":"بله. این‌طور می‌توانید به عابران جا بدهید بی‌آنکه به خودروی روبه‌رو خیلی نزدیک شوید.","en":"If the oncoming car and the pedestrians meet where I am, I wait behind the pedestrians.","een":"Yes. That way you can give the pedestrians room without getting too close to the oncoming car."},{"da":"Fodgængerne går forkert, fordi de går i venstre side af vejen.","fa":"عابران اشتباه راه می‌روند، چون در سمت چپ جاده‌اند.","ok":0,"eda":"Nej. Gående på vejen skal gå yderst i venstre side, så de møder trafikken.","efa":"خیر. عابرانی که روی جاده راه می‌روند باید در منتهی‌الیه سمت چپ، رو به ترافیک، بروند.","en":"The pedestrians are walking wrongly because they are on the left side.","een":"No. Pedestrians on the road must walk at the far left, facing the traffic."},{"da":"Jeg sænker farten og giver dem god plads, når jeg passerer.","fa":"سرعتم را کم می‌کنم و هنگام رد شدن جای زیادی به آن‌ها می‌دهم.","ok":1,"eda":"Ja. Når du passerer gående, skal du give dem tid til at vige og god plads på vejen.","efa":"بله. هنگام رد شدن از کنار عابران، باید به آن‌ها فرصت کنار رفتن و جای کافی بدهید.","en":"I slow down and give them plenty of room when I pass.","een":"Yes. When you pass pedestrians you must give them time to step aside and plenty of room on the road."}]},{"id":5029,"img":"newq-art/5029.png","c":"7.6","sda":"En lastbil holder i din side af vejen. En bil kommer imod dig. Hvordan forholder du dig?","sfa":"کامیونی در سمت شما ایستاده است. خودرویی از روبه‌رو می‌آید. چه می‌کنید؟","sen":"A lorry has stopped on your side of the road. A car is coming towards you. What do you do?","st":[{"da":"Jeg holder tilbage for den modkørende, fordi forhindringen er i min side.","fa":"به خودروی روبه‌رو راه می‌دهم، چون مانع در سمت من است.","ok":1,"eda":"Ja. Den, der har forhindringen i sin side, skal holde tilbage.","efa":"بله. کسی که مانع در سمت اوست، باید راه بدهد.","en":"I give way to the oncoming car because the obstacle is on my side.","een":"Yes. The driver who has the obstacle on their side must give way."},{"da":"Jeg kører tæt op bag lastbilen, så jeg hurtigt kan komme forbi.","fa":"نزدیک پشت کامیون می‌روم تا زود رد شوم.","ok":0,"eda":"Nej. Tæt bag lastbilen kan du ikke se forbi den, og du får svært ved at køre ud; vent med god afstand.","efa":"خیر. نزدیک پشت کامیون نه جلو را می‌بینید و نه به‌راحتی می‌توانید بیرون بیایید؛ با فاصله‌ی خوب صبر کنید.","en":"I drive up close behind the lorry so that I can get past quickly.","een":"No. Close behind the lorry you cannot see past it, and it is hard to pull out; wait at a good distance."},{"da":"Jeg kører ud og blinker med lyset, så den modkørende standser.","fa":"وارد خط روبه‌رو می‌شوم و چراغ می‌زنم تا راننده‌ی روبه‌رو بایستد.","ok":0,"eda":"Nej. Lyssignaler giver ikke forkørselsret; du skal holde tilbage.","efa":"خیر. چراغ زدن حق تقدم نمی‌دهد؛ باید راه بدهید.","en":"I pull out and flash my lights so that the oncoming driver stops.","een":"No. Flashing lights does not give you the right of way; you must give way."},{"da":"Den modkørende skal holde tilbage, fordi jeg kom først.","fa":"راننده‌ی روبه‌رو باید راه بدهد، چون من اول رسیدم.","ok":0,"eda":"Nej. Det afgørende er, i hvis side forhindringen er, ikke hvem der kom først.","efa":"خیر. مهم این است که مانع در سمت کیست، نه این‌که چه کسی اول رسید.","en":"The oncoming driver must give way because I came first.","een":"No. What matters is whose side the obstacle is on, not who came first."}]},{"id":5030,"img":"newq-art/5030.png","c":"7.6","sda":"Du kører forbi denne tavle nær en skole. Hvordan forholder du dig?","sfa":"نزدیک یک مدرسه از کنار این تابلو رد می‌شوید. چه می‌کنید؟","sen":"You pass this sign near a school. What do you do?","st":[{"da":"Jeg kan køre med normal fart, når jeg ikke kan se nogen børn på kørebanen.","fa":"وقتی کودکی روی سواره‌رو نمی‌بینم، می‌توانم با سرعت معمول برانم.","ok":0,"eda":"Nej. Børn kan pludselig komme frem mellem de parkerede biler; tavlen varsler, at der kan være børn, og der skal vises særligt hensyn.","efa":"خیر. بچه‌ها ممکن است ناگهان از میان خودروهای پارک‌شده بیرون بیایند؛ تابلو هشدار می‌دهد که ممکن است بچه باشد و باید ملاحظه‌ی ویژه داشت.","en":"I can drive at normal speed when I cannot see any children on the carriageway.","een":"No. Children may suddenly appear between the parked cars; the sign warns that there may be children, and special consideration must be shown."},{"da":"Jeg sænker farten og er klar til at bremse.","fa":"سرعتم را کم می‌کنم و آماده‌ی ترمز هستم.","ok":1,"eda":"Ja. Nær børn skal hastigheden være passende lav.","efa":"بله. نزدیک بچه‌ها، سرعت باید به اندازه‌ی کافی کم باشد.","en":"I slow down and am ready to brake.","een":"Yes. Near children your speed must be suitably low."},{"da":"Tavlen gælder kun i skolens åbningstid.","fa":"این تابلو فقط در ساعات کار مدرسه معتبر است.","ok":0,"eda":"Nej. Tavlen gælder hele tiden, når der ikke er en undertavle med tidspunkter.","efa":"خیر. وقتی زیر تابلو تابلوی کوچکی با ساعت نیست، همیشه معتبر است.","en":"The sign only applies during school hours.","een":"No. The sign applies all the time when there is no plate under it with times."},{"da":"Jeg kan regne med, at børnene har set mig.","fa":"می‌توانم مطمئن باشم که بچه‌ها مرا دیده‌اند.","ok":0,"eda":"Nej. Børn har svært ved at vurdere trafikken og ser ikke altid bilerne.","efa":"خیر. بچه‌ها در سنجیدن ترافیک مشکل دارند و همیشه خودروها را نمی‌بینند.","en":"I can count on the children having seen me.","een":"No. Children find it hard to judge traffic and do not always see the cars."}]},{"id":5031,"img":"newq-art/5031.png","c":"7.6","sda":"En person med en hvid stok står ved fodgængerfeltet. Hvordan forholder du dig?","sfa":"کسی با عصای سفید کنار گذرگاه عابر ایستاده است. چه می‌کنید؟","sen":"A person with a white cane is standing at the pedestrian crossing. What do you do?","st":[{"da":"Jeg dytter, så personen ved, at jeg kommer.","fa":"بوق می‌زنم تا آن شخص بفهمد می‌آیم.","ok":0,"eda":"Nej. Et dyt kan forskrække og forvirre; du skal i stedet standse.","efa":"خیر. بوق می‌تواند بترساند و گیج کند؛ باید به‌جایش بایستید.","en":"I sound the horn so that the person knows I am coming.","een":"No. A horn can startle and confuse; you must stop instead."},{"da":"Den hvide stok viser, at personen ser dårligt eller er blind.","fa":"عصای سفید نشان می‌دهد که آن شخص کم‌بیناست یا نابیناست.","ok":1,"eda":"Ja. Over for personer med nedsat syn skal der vises særligt hensyn.","efa":"بله. باید نسبت به افراد کم‌بینا ملاحظه‌ی ویژه داشت.","en":"The white cane shows that the person has poor sight or is blind.","een":"Yes. Special consideration must be shown to people with impaired sight."},{"da":"Jeg standser og lader personen gå over.","fa":"می‌ایستم و می‌گذارم آن شخص رد شود.","ok":1,"eda":"Ja. Før et fodgængerfelt skal du afpasse hastigheden og om nødvendigt standse for den, der er på vej ud.","efa":"بله. پیش از گذرگاه عابر باید سرعت را تنظیم کنید و در صورت لزوم برای کسی که می‌خواهد رد شود بایستید.","en":"I stop and let the person cross.","een":"Yes. Before a crossing you must adjust your speed and stop if necessary for someone about to step out."},{"da":"Jeg kører forbi, fordi personen ikke kan se, om der kommer biler.","fa":"رد می‌شوم، چون آن شخص نمی‌تواند ببیند خودرویی می‌آید یا نه.","ok":0,"eda":"Nej. Netop derfor skal du tage særligt hensyn og lade personen gå over.","efa":"خیر. دقیقاً به همین دلیل باید ملاحظه کنید و بگذارید رد شود.","en":"I drive past because the person cannot see whether cars are coming.","een":"No. That is exactly why you must take special care and let the person cross."}]},{"id":5032,"img":"newq-art/5032.png","c":"7.3","sda":"Du kører i en almindelig bil på motorvejen. Der er ingen hastighedstavler. Hvad gælder?","sfa":"با خودروی معمولی در بزرگراه می‌رانید. تابلوی سرعتی نیست. چه قاعده‌ای برقرار است؟","sen":"You are driving an ordinary car on the motorway. There are no speed-limit signs. What applies?","st":[{"da":"Jeg må højst køre 130 km/t.","fa":"حداکثر ۱۳۰ کیلومتر بر ساعت می‌توانم برانم.","ok":1,"eda":"Ja. Den generelle grænse på motorvej er 130 km/t.","efa":"بله. حد عمومی سرعت در بزرگراه ۱۳۰ کیلومتر بر ساعت است.","en":"I may drive at most 130 km/h.","een":"Yes. The general limit on the motorway is 130 km/h."},{"da":"Der er ingen hastighedsgrænse på motorvejen.","fa":"در بزرگراه حد سرعتی وجود ندارد.","ok":0,"eda":"Nej. Der gælder altid en højeste hastighed, også på motorvej.","efa":"خیر. همیشه حداکثر سرعتی هست، در بزرگراه هم.","en":"There is no speed limit on the motorway.","een":"No. There is always a highest speed, also on the motorway."},{"da":"Jeg må køre hurtigere end 130 km/t, mens jeg overhaler.","fa":"هنگام سبقت می‌توانم تندتر از ۱۳۰ کیلومتر بر ساعت برانم.","ok":0,"eda":"Nej. Hastighedsgrænsen gælder også under overhaling.","efa":"خیر. حد سرعت هنگام سبقت هم برقرار است.","en":"I may drive faster than 130 km/h while I am overtaking.","een":"No. The speed limit also applies while overtaking."},{"da":"Jeg må højst køre 110 km/t.","fa":"حداکثر ۱۱۰ کیلومتر بر ساعت می‌توانم برانم.","ok":0,"eda":"Nej. 110 km/t gælder kun, hvor det er skiltet.","efa":"خیر. ۱۱۰ کیلومتر بر ساعت فقط جایی است که تابلو داشته باشد.","en":"I may drive at most 110 km/h.","een":"No. 110 km/h only applies where it is signed."}]},{"id":5033,"img":"newq-art/5033.png","c":"7.3","sda":"Du kører med en almindelig trailer på en landevej uden hastighedstavler. Hvad gælder?","sfa":"با یک تریلر معمولی در جاده‌ای بیرون شهر و بدون تابلوی سرعت می‌رانید. چه قاعده‌ای برقرار است؟","sen":"You are towing an ordinary trailer on a country road with no speed-limit signs. What applies?","st":[{"da":"Jeg må højst køre 80 km/t.","fa":"حداکثر ۸۰ کیلومتر بر ساعت می‌توانم برانم.","ok":1,"eda":"Ja. Bil med påhængskøretøj må højst køre 80 km/t uden for motorvej.","efa":"بله. خودرو با یدک بیرون از بزرگراه حداکثر ۸۰ کیلومتر بر ساعت می‌تواند برود.","en":"I may drive at most 80 km/h.","een":"Yes. A car with a trailer may drive at most 80 km/h off the motorway."},{"da":"Jeg må køre lige så hurtigt som uden trailer.","fa":"می‌توانم به همان سرعتِ بدون تریلر برانم.","ok":0,"eda":"Nej. Med trailer gælder en lavere grænse end for bilen alene.","efa":"خیر. با تریلر حد سرعت پایین‌تری از خودروی تنها برقرار است.","en":"I may drive as fast as without a trailer.","een":"No. With a trailer a lower limit applies than for the car alone."},{"da":"En trailer påvirker ikke bremselængden.","fa":"تریلر روی مسافت ترمز اثری ندارد.","ok":0,"eda":"Nej. Et vogntog er tungere og får længere bremselængde.","efa":"خیر. خودرو با یدک سنگین‌تر است و مسافت ترمزش بیشتر است.","en":"A trailer does not affect the braking distance.","een":"No. A combination is heavier and has a longer braking distance."},{"da":"På motorvej må jeg højst køre 100 km/t, hvis vogntoget opfylder betingelserne for det.","fa":"در بزرگراه اگر خودرو با یدک شرایطش را داشته باشد، حداکثر ۱۰۰ کیلومتر بر ساعت می‌توانم برانم.","ok":1,"eda":"Ja. Færdselsloven § 43 tillader 100 km/t på motorvej for vogntog, der opfylder bestemte krav.","efa":"بله. ماده‌ی ۴۳ قانون برای خودرو با یدکی که شرایط خاصی دارد، ۱۰۰ کیلومتر بر ساعت در بزرگراه را مجاز می‌داند.","en":"On the motorway I may drive at most 100 km/h if the combination meets the conditions for it.","een":"Yes. Færdselsloven § 43 allows 100 km/h on the motorway for combinations that meet certain requirements."}]},{"id":5034,"img":"newq-art/5034.png","c":"7.3","sda":"Der er tæt tåge. Hvordan forholder du dig?","sfa":"مه غلیظی است. چه می‌کنید؟","sen":"There is dense fog. What do you do?","st":[{"da":"Jeg må bruge tågeforlygter.","fa":"می‌توانم از چراغ‌های مه‌شکن جلو استفاده کنم.","ok":1,"eda":"Ja. Tågelygter må bruges i tåge og under kraftig nedbør.","efa":"بله. چراغ مه‌شکن در مه و بارش شدید مجاز است.","en":"I may use front fog lights.","een":"Yes. Fog lights may be used in fog and heavy precipitation."},{"da":"Jeg kører tæt bag bilen foran og følger dens baglygter.","fa":"نزدیک پشت خودروی جلو می‌رانم و چراغ‌های عقبش را دنبال می‌کنم.","ok":0,"eda":"Nej. Tæt afstand giver ingen tid til at bremse, hvis bilen foran standser.","efa":"خیر. فاصله‌ی کم، اگر خودروی جلو بایستد، فرصتی برای ترمز نمی‌گذارد.","en":"I drive close behind the car ahead and follow its rear lights.","een":"No. A short distance leaves no time to brake if the car ahead stops."},{"da":"Jeg kører så langsomt, at jeg kan standse på den strækning, jeg kan se.","fa":"آن‌قدر آهسته می‌رانم که بتوانم در فاصله‌ای که می‌بینم بایستم.","ok":1,"eda":"Ja. Du skal altid kunne standse på den del af vejen, du har udsyn over.","efa":"بله. همیشه باید بتوانید در بخشی از جاده که می‌بینید بایستید.","en":"I drive so slowly that I can stop within the distance I can see.","een":"Yes. You must always be able to stop within the part of the road you can see."},{"da":"Jeg tænder fjernlyset, så jeg kan se længere.","fa":"نور بالا را روشن می‌کنم تا دورتر را ببینم.","ok":0,"eda":"Nej. I tåge kaster fjernlyset lyset tilbage og blænder dig selv.","efa":"خیر. در مه، نور بالا بازمی‌تابد و خودتان را خیره می‌کند.","en":"I switch on the high beam so that I can see further.","een":"No. In fog the high beam reflects back and dazzles you."}]},{"id":5035,"img":"newq-art/5035.png","c":"7.3","sda":"Du kører med fjernlys, og langt fremme kommer en bil imod dig. Hvordan forholder du dig?","sfa":"با نور بالا می‌رانید و دورتر خودرویی از روبه‌رو می‌آید. چه می‌کنید؟","sen":"You are driving with high beam, and far ahead a car is coming towards you. What do you do?","st":[{"da":"Jeg beholder fjernlyset, til bilen er lige ud for mig.","fa":"نور بالا را تا رسیدن خودرو به کنارم روشن نگه می‌دارم.","ok":0,"eda":"Nej. Så bliver den modkørende blændet i lang tid.","efa":"خیر. این‌طور راننده‌ی روبه‌رو مدت زیادی خیره می‌شود.","en":"I keep the high beam on until the car is right beside me.","een":"No. Then the oncoming driver is dazzled for a long time."},{"da":"Jeg blinker med fjernlyset, så den modkørende ved, at jeg er her.","fa":"با نور بالا چراغ می‌زنم تا راننده‌ی روبه‌رو بداند من این‌جا هستم.","ok":0,"eda":"Nej. Det blænder og er ikke nødvendigt; den modkørende kan se dit lys.","efa":"خیر. این کار خیره می‌کند و لازم نیست؛ راننده‌ی روبه‌رو چراغ‌های شما را می‌بیند.","en":"I flash my high beam so that the oncoming driver knows I am here.","een":"No. It dazzles and is not needed; the oncoming driver can see your lights."},{"da":"Jeg afpasser farten efter det kortere udsyn med nærlys.","fa":"سرعتم را با دید کوتاه‌ترِ نور پایین تنظیم می‌کنم.","ok":1,"eda":"Ja. Før du skifter til nærlys, skal hastigheden passe til det nye, kortere udsyn.","efa":"بله. پیش از رفتن به نور پایین، سرعت باید با دید تازه و کوتاه‌تر جور باشد.","en":"I adjust my speed to the shorter view with dipped beam.","een":"Yes. Before you dip, your speed must suit the new, shorter view."},{"da":"Jeg skifter til nærlys i god tid, så den modkørende ikke bliver blændet.","fa":"به موقع به نور پایین می‌روم تا راننده‌ی روبه‌رو خیره نشود.","ok":1,"eda":"Ja. Fjernlys må ikke bruges, når en modkørende kan blive blændet.","efa":"بله. وقتی ممکن است راننده‌ی روبه‌رو خیره شود، نباید از نور بالا استفاده کرد.","en":"I switch to dipped beam in good time so that the oncoming driver is not dazzled.","een":"Yes. High beam must not be used when an oncoming driver could be dazzled."}]},{"id":5036,"img":"newq-art/5036.png","c":"7.3","sda":"Du nærmer dig et vejarbejde, hvor der arbejder folk tæt ved vejen. Hvordan forholder du dig?","sfa":"به محل کار جاده‌ای نزدیک می‌شوید که کارگرانی نزدیک جاده کار می‌کنند. چه می‌کنید؟","sen":"You are approaching road works with people working close to the road. What do you do?","st":[{"da":"Jeg følger de gule linjer på kørebanen.","fa":"خط‌های زرد روی جاده را دنبال می‌کنم.","ok":1,"eda":"Ja. Midlertidig gul afmærkning gælder forud for den hvide.","efa":"بله. خط‌کشی موقت زرد بر خط‌کشی سفید مقدم است.","en":"I follow the yellow lines on the road.","een":"Yes. Temporary yellow markings take priority over the white ones."},{"da":"Jeg holder farten, så jeg hurtigt er forbi.","fa":"سرعتم را حفظ می‌کنم تا زود رد شوم.","ok":0,"eda":"Nej. Vejarbejdere kan træde ud på vejen; der skal være tid til at reagere.","efa":"خیر. کارگران ممکن است وارد جاده شوند؛ باید فرصت واکنش داشت.","en":"I keep my speed so that I am past quickly.","een":"No. Road workers may step onto the road; there must be time to react."},{"da":"Tavlen gælder kun, når der er maskiner på vejen.","fa":"این تابلو فقط وقتی ماشین‌آلات روی جاده‌اند معتبر است.","ok":0,"eda":"Nej. Tavlen advarer om vejarbejde, uanset om der er maskiner.","efa":"خیر. این تابلو از کار جاده‌ای هشدار می‌دهد، چه ماشین‌آلات باشند چه نه.","en":"The sign only applies when there are machines on the road.","een":"No. The sign warns of road works whether there are machines or not."},{"da":"Jeg sænker farten.","fa":"سرعتم را کم می‌کنم.","ok":1,"eda":"Ja. Ved vejarbejde skal hastigheden være passende lav.","efa":"بله. در محل کار جاده‌ای سرعت باید به اندازه‌ی کافی کم باشد.","en":"I slow down.","een":"Yes. At road works your speed must be suitably low."}]},{"id":5037,"img":"newq-art/5037.png","c":"7.3","sda":"Du er i tvivl om vejen og kører meget langsomt. Bag dig er der dannet kø. Hvad gælder?","sfa":"مسیر را مطمئن نیستید و خیلی آهسته می‌رانید. پشت سرتان صف تشکیل شده است. چه قاعده‌ای برقرار است؟","sen":"You are unsure of the way and are driving very slowly. A queue has formed behind you. What applies?","st":[{"da":"Jeg bremser pludseligt, hver gang jeg skal læse et vejskilt.","fa":"هر بار که باید تابلویی را بخوانم، ناگهان ترمز می‌کنم.","ok":0,"eda":"Nej. Pludselig opbremsning uden grund kan få bilerne bag dig til at køre ind i dig.","efa":"خیر. ترمز ناگهانی بی‌دلیل ممکن است باعث شود خودروهای پشت سر به شما بزنند.","en":"I brake suddenly every time I need to read a road sign.","een":"No. Sudden braking without reason can make the cars behind run into you."},{"da":"Jeg må ikke uden rimelig grund køre så langsomt, at jeg hindrer andre.","fa":"نباید بی‌دلیل آن‌قدر آهسته برانم که مانع دیگران شوم.","ok":1,"eda":"Ja. Færdselsloven § 41 forbyder at hindre andre ved unødigt lav hastighed.","efa":"بله. ماده‌ی ۴۱ قانون مانع شدن دیگران با سرعت بی‌دلیل کم را ممنوع می‌کند.","en":"I must not, without good reason, drive so slowly that I hinder others.","een":"Yes. Færdselsloven § 41 forbids hindering others by needlessly low speed."},{"da":"Det er altid sikrest at køre så langsomt som muligt.","fa":"همیشه امن‌ترین کار آهسته‌ترین رانندگی است.","ok":0,"eda":"Nej. En meget lav fart kan skabe farlige overhalinger og kø.","efa":"خیر. سرعت خیلی کم می‌تواند به سبقت‌های خطرناک و صف منجر شود.","en":"It is always safest to drive as slowly as possible.","een":"No. Very low speed can cause dangerous overtaking and queues."},{"da":"Jeg kører ind i rastepladsen og finder vejen, når jeg holder stille.","fa":"وارد توقفگاه کنار جاده می‌شوم و وقتی ایستاده‌ام مسیر را پیدا می‌کنم.","ok":1,"eda":"Ja. Så kan køen komme forbi, og du kan læse kort eller skilte i ro.","efa":"بله. این‌طور صف رد می‌شود و شما با خیال راحت نقشه یا تابلو را می‌خوانید.","en":"I pull into the lay-by and work out the way while I am standing still.","een":"Yes. Then the queue can get past, and you can read a map or signs in peace."}]},{"id":5038,"img":"newq-art/5038.png","c":"7.12","sda":"Du vil køre ligeud i krydset. Fra højre kommer en bil, og fra venstre kommer en cyklist. Hvordan forholder du dig?","sfa":"می‌خواهید مستقیم از تقاطع رد شوید. از راست خودرویی و از چپ دوچرخه‌سواری می‌آید. چه می‌کنید؟","sen":"You want to drive straight on in the junction. A car is coming from the right and a cyclist from the left. What do you do?","st":[{"da":"Jeg kan regne med, at cyklisten holder tilbage, så jeg behøver ikke se efter den.","fa":"می‌توانم مطمئن باشم دوچرخه‌سوار راه می‌دهد، پس لازم نیست حواسم به او باشد.","ok":0,"eda":"Nej. Du skal altid være opmærksom på, om andre overholder deres vigepligt.","efa":"خیر. همیشه باید ببینید دیگران به وظیفه‌ی راه دادنشان عمل می‌کنند یا نه.","en":"I can count on the cyclist giving way, so I do not need to watch it.","een":"No. You must always watch whether others keep their duty to give way."},{"da":"Jeg har forkørselsret, fordi jeg kører ligeud.","fa":"حق تقدم با من است، چون مستقیم می‌روم.","ok":0,"eda":"Nej. At køre ligeud giver ikke forkørselsret over for trafik fra højre.","efa":"خیر. مستقیم رفتن در برابر ترافیک سمت راست حق تقدم نمی‌دهد.","en":"I have the right of way because I am going straight on.","een":"No. Going straight on does not give you the right of way over traffic from the right."},{"da":"Cyklisten fra venstre skal holde tilbage for mig.","fa":"دوچرخه‌سوار سمت چپ باید به من راه بدهد.","ok":1,"eda":"Ja. Højrereglen gælder også for cyklister: cyklisten har dig på sin højre side.","efa":"بله. قاعده‌ی دست راست برای دوچرخه‌سواران هم هست: شما در سمت راست او هستید.","en":"The cyclist from the left must give way to me.","een":"Yes. The right-hand rule also applies to cyclists: the cyclist has you on their right."},{"da":"Jeg holder tilbage for bilen fra højre.","fa":"به خودروی سمت راست راه می‌دهم.","ok":1,"eda":"Ja. Uden tavler og afmærkning gælder højrereglen: du holder tilbage for trafik fra højre.","efa":"بله. بدون تابلو و خط‌کشی، قاعده‌ی دست راست برقرار است: به ترافیک سمت راست راه می‌دهید.","en":"I give way to the car from the right.","een":"Yes. Without signs or markings the right-hand rule applies: you give way to traffic from the right."}]},{"id":5039,"img":"newq-art/5039.png","c":"7.12","sda":"Der er hajtænder på kørebanen foran dig, men ingen tavle. Hvad gælder?","sfa":"روی جاده جلوی شما دندان‌کوسه هست، ولی تابلویی نیست. چه قاعده‌ای برقرار است؟","sen":"There are shark teeth on the road ahead of you, but no sign. What applies?","st":[{"da":"Hajtænder gælder kun sammen med en vigepligtstavle.","fa":"دندان‌کوسه فقط همراه تابلوی راه بدهید معتبر است.","ok":0,"eda":"Nej. Afmærkningen alene giver vigepligt.","efa":"خیر. خود خط‌کشی به‌تنهایی وظیفه‌ی راه دادن می‌دهد.","en":"Shark teeth only apply together with a give-way sign.","een":"No. The marking alone gives the duty to give way."},{"da":"Bilen fra venstre skal have lov at køre først.","fa":"باید بگذارم خودروی سمت چپ اول برود.","ok":1,"eda":"Ja. Ubetinget vigepligt gælder for trafikken fra begge sider.","efa":"بله. راه دادن بی‌قیدوشرط برای ترافیک هر دو طرف است.","en":"The car from the left must be allowed to go first.","een":"Yes. Unconditional give-way applies to traffic from both sides."},{"da":"Jeg har ubetinget vigepligt for trafikken på den tværgående vej.","fa":"باید بی‌قیدوشرط به ترافیک جاده‌ی متقاطع راه بدهم.","ok":1,"eda":"Ja. Hajtænderne betyder ubetinget vigepligt, også uden tavle.","efa":"بله. دندان‌کوسه حتی بدون تابلو یعنی راه دادن بی‌قیدوشرط.","en":"I must give way unconditionally to the traffic on the crossing road.","een":"Yes. The shark teeth mean unconditional give-way, also without a sign."}]},{"id":5040,"img":"newq-art/5040.png","c":"7.12","sda":"Du har grønt lys, men der holder en kø lige efter krydset. Hvordan forholder du dig?","sfa":"چراغ سبز است، ولی درست بعد از تقاطع صف ایستاده است. چه می‌کنید؟","sen":"You have a green light, but there is a queue just after the junction. What do you do?","st":[{"da":"Jeg må køre ind i krydset, hvis jeg tænder havariblinket.","fa":"اگر چراغ خطر را روشن کنم، می‌توانم وارد تقاطع شوم.","ok":0,"eda":"Nej. Havariblinket ændrer ikke, at du spærrer krydset for den tværgående trafik.","efa":"خیر. چراغ خطر این را تغییر نمی‌دهد که تقاطع را برای ترافیک متقاطع می‌بندید.","en":"I may drive into the junction if I switch on the hazard lights.","een":"No. The hazard lights do not change the fact that you block the junction for the crossing traffic."},{"da":"Jeg kører frem og stiller mig skråt, så andre kan komme forbi.","fa":"جلو می‌روم و کج می‌ایستم تا دیگران رد شوند.","ok":0,"eda":"Nej. Du skal slet ikke køre ind i krydset, når der ikke er plads.","efa":"خیر. وقتی جا نیست، اصلاً نباید وارد تقاطع شوید.","en":"I drive forward and stand at an angle so that others can get past.","een":"No. You must not drive into the junction at all when there is no room."},{"da":"Jeg kører ind i krydset, fordi jeg har grønt.","fa":"وارد تقاطع می‌شوم، چون چراغم سبز است.","ok":0,"eda":"Nej. Grønt lys giver ikke ret til at blive holdende midt i krydset.","efa":"خیر. چراغ سبز اجازه‌ی ماندن وسط تقاطع را نمی‌دهد.","en":"I drive into the junction because I have a green light.","een":"No. A green light does not give a right to stand in the middle of the junction."},{"da":"Jeg venter før krydset, til der er plads på den anden side.","fa":"پیش از تقاطع صبر می‌کنم تا آن طرف جا باز شود.","ok":1,"eda":"Ja. Du må ikke køre ind på grønt, hvis du ikke kan komme ud af krydset, før de tværgående får grønt.","efa":"بله. اگر نتوانید پیش از سبز شدن چراغ ترافیک متقاطع از تقاطع خارج شوید، نباید با چراغ سبز واردش شوید.","en":"I wait before the junction until there is room on the other side.","een":"Yes. You must not drive in on green if you cannot get out of the junction before the crossing traffic gets green."}]},{"id":5041,"img":"newq-art/5041.png","c":"7.12","sda":"Du vil køre ud fra tankstationen. Hvordan forholder du dig?","sfa":"می‌خواهید از پمپ بنزین خارج شوید. چه می‌کنید؟","sen":"You want to drive out of the petrol station. What do you do?","st":[{"da":"Jeg har ubetinget vigepligt for trafikken på vejen.","fa":"باید بی‌قیدوشرط به ترافیک جاده راه بدهم.","ok":1,"eda":"Ja. Kørsel ud fra en tankstation giver ubetinget vigepligt.","efa":"بله. خروج از پمپ بنزین یعنی راه دادن بی‌قیدوشرط.","en":"I must give way unconditionally to the traffic on the road.","een":"Yes. Driving out of a petrol station means unconditional give-way."},{"da":"Fodgængeren skal vente, fordi jeg skal over fortovet.","fa":"عابر باید صبر کند، چون من باید از پیاده‌رو رد شوم.","ok":0,"eda":"Nej. Det er dig, der skal vente på fodgængeren.","efa":"خیر. شما هستید که باید منتظر عابر بمانید.","en":"The pedestrian must wait because I have to cross the pavement.","een":"No. It is you who must wait for the pedestrian."},{"da":"Jeg skal holde tilbage for fodgængeren og cyklisten.","fa":"باید به عابر و دوچرخه‌سوار راه بدهم.","ok":1,"eda":"Ja. Du skal holde tilbage for gående på fortovet og for cyklister på cykelstien, når du krydser dem.","efa":"بله. هنگام عبور از پیاده‌رو و مسیر دوچرخه، باید به عابران و دوچرخه‌سواران راه بدهید.","en":"I must give way to the pedestrian and the cyclist.","een":"Yes. You must give way to pedestrians on the pavement and cyclists on the cycle path when you cross them."},{"da":"Højrereglen gælder, fordi der ikke er nogen tavle.","fa":"قاعده‌ی دست راست برقرار است، چون تابلویی نیست.","ok":0,"eda":"Nej. Højrereglen gælder ikke ved udkørsel fra en tankstation.","efa":"خیر. قاعده‌ی دست راست در خروج از پمپ بنزین اعمال نمی‌شود.","en":"The right-hand rule applies because there is no sign.","een":"No. The right-hand rule does not apply when driving out of a petrol station."}]},{"id":5042,"img":"newq-art/5042.png","c":"7.12","sda":"Lyssignalet i krydset blinker gult. Hvordan forholder du dig?","sfa":"چراغ راهنمایی تقاطع زرد چشمک‌زن است. چه می‌کنید؟","sen":"The traffic light at the junction is flashing yellow. What do you do?","st":[{"da":"Lastbilen skal holde tilbage for mig, fordi den kommer fra venstre.","fa":"کامیون باید به من راه بدهد، چون از سمت چپ می‌آید.","ok":0,"eda":"Nej. Med vigepligtstavlen holder du tilbage for trafikken fra begge sider.","efa":"خیر. با تابلوی راه بدهید، به ترافیک هر دو طرف راه می‌دهید.","en":"The lorry must give way to me because it comes from the left.","een":"No. With the give-way sign you give way to traffic from both sides."},{"da":"Jeg følger tavlen og hajtænderne og har ubetinget vigepligt.","fa":"از تابلو و دندان‌کوسه پیروی می‌کنم و بی‌قیدوشرط راه می‌دهم.","ok":1,"eda":"Ja. Når signalet blinker gult, gælder tavler og afmærkning.","efa":"بله. وقتی چراغ زرد چشمک می‌زند، تابلوها و خط‌کشی‌ها معتبرند.","en":"I follow the sign and the shark teeth and give way unconditionally.","een":"Yes. When the signal flashes yellow, the signs and markings apply."},{"da":"Blinkende gult betyder, at jeg har forkørselsret.","fa":"زرد چشمک‌زن یعنی حق تقدم با من است.","ok":0,"eda":"Nej. Blinkende gult giver ikke forkørselsret; tavlen giver dig vigepligt.","efa":"خیر. زرد چشمک‌زن حق تقدم نمی‌دهد؛ تابلو شما را موظف به راه دادن می‌کند.","en":"A flashing yellow light means I have the right of way.","een":"No. A flashing yellow light gives no right of way; the sign makes you give way."},{"da":"Jeg kører frem med særlig forsigtighed.","fa":"با احتیاط ویژه جلو می‌روم.","ok":1,"eda":"Ja. Blinkende gult advarer om, at du skal være ekstra opmærksom.","efa":"بله. زرد چشمک‌زن هشدار می‌دهد که باید بیشتر مراقب باشید.","en":"I drive on with special care.","een":"Yes. A flashing yellow light warns you to be extra attentive."}]},{"id":5043,"img":"newq-art/5043.png","c":"7.12","sda":"Du får grønt lys, men en ældre mand er stadig på fodgængerfeltet foran dig. Hvordan forholder du dig?","sfa":"چراغ شما سبز می‌شود، ولی مرد مسنی هنوز روی گذرگاه عابر جلوی شماست. چه می‌کنید؟","sen":"You get a green light, but an elderly man is still on the pedestrian crossing in front of you. What do you do?","st":[{"da":"Jeg dytter, så han skynder sig.","fa":"بوق می‌زنم تا عجله کند.","ok":0,"eda":"Nej. Et dyt kan forskrække og få ham til at falde.","efa":"خیر. بوق می‌تواند او را بترساند و باعث افتادنش شود.","en":"I sound the horn so that he hurries.","een":"No. A horn can startle him and make him fall."},{"da":"Jeg holder tilbage og lader ham komme over.","fa":"صبر می‌کنم تا رد شود.","ok":1,"eda":"Ja. Ved et reguleret fodgængerfelt skal du holde tilbage for gående, der allerede er på feltet.","efa":"بله. در گذرگاه چراغ‌دار، باید به عابرانی که روی گذرگاه‌اند راه بدهید.","en":"I wait and let him get across.","een":"Yes. At a controlled crossing you must give way to pedestrians already on it."},{"da":"Jeg kører, fordi jeg har grønt, og han har rødt.","fa":"حرکت می‌کنم، چون چراغ من سبز و چراغ او قرمز است.","ok":0,"eda":"Nej. Grønt lys giver ikke ret til at køre ind på en, der allerede er på feltet.","efa":"خیر. چراغ سبز اجازه نمی‌دهد به سمت کسی که روی گذرگاه است برانید.","en":"I drive because I have green and he has red.","een":"No. A green light gives no right to drive at someone who is already on the crossing."},{"da":"Ældre mennesker kan have brug for længere tid til at gå over.","fa":"افراد مسن ممکن است برای رد شدن به زمان بیشتری نیاز داشته باشند.","ok":1,"eda":"Ja. Der skal vises særligt hensyn over for ældre mennesker.","efa":"بله. نسبت به افراد مسن باید ملاحظه‌ی ویژه داشت.","en":"Elderly people may need more time to cross.","een":"Yes. Special consideration must be shown to elderly people."}]},{"id":5044,"img":"newq-art/5044.png","c":"7.14","sda":"Du har grønt lys og vil svinge til venstre. En bil og en cyklist kommer imod dig. Hvordan forholder du dig?","sfa":"چراغ سبز است و می‌خواهید به چپ بپیچید. یک خودرو و یک دوچرخه‌سوار از روبه‌رو می‌آیند. چه می‌کنید؟","sen":"You have a green light and want to turn left. A car and a cyclist are coming towards you. What do you do?","st":[{"da":"Jeg holder tilbage for den modkørende bil.","fa":"به خودروی روبه‌رو راه می‌دهم.","ok":1,"eda":"Ja. Når du svinger til venstre, må du ikke genere de modkørende.","efa":"بله. هنگام گردش به چپ نباید مزاحم ترافیک روبه‌رو شوید.","en":"I give way to the oncoming car.","een":"Yes. When you turn left you must not inconvenience oncoming traffic."},{"da":"Jeg kan køre lidt frem i krydset og vente der, hvis det ikke generer andre.","fa":"اگر مزاحم دیگران نباشد، می‌توانم کمی وارد تقاطع شوم و آن‌جا صبر کنم.","ok":1,"eda":"Ja. Så er du klar til at svinge, når de modkørende er passeret.","efa":"بله. این‌طور وقتی ترافیک روبه‌رو رد شد، آماده‌ی پیچیدن هستید.","en":"I may drive a little into the junction and wait there if it does not hinder others.","een":"Yes. Then you are ready to turn when the oncoming traffic has passed."},{"da":"Jeg har forkørselsret, fordi jeg har grønt.","fa":"حق تقدم با من است، چون چراغم سبز است.","ok":0,"eda":"Nej. De modkørende har også grønt, og den venstresvingende skal vente.","efa":"خیر. ترافیک روبه‌رو هم سبز است و کسی که به چپ می‌پیچد باید صبر کند.","en":"I have the right of way because I have green.","een":"No. The oncoming traffic also has green, and the left-turner must wait."},{"da":"Jeg holder også tilbage for den modkørende cyklist.","fa":"به دوچرخه‌سوار روبه‌رو هم راه می‌دهم.","ok":1,"eda":"Ja. Reglen gælder alle modkørende, også cyklister.","efa":"بله. این قاعده برای همه‌ی ترافیک روبه‌رو، از جمله دوچرخه‌سواران، است.","en":"I also give way to the oncoming cyclist.","een":"Yes. The rule applies to all oncoming traffic, cyclists too."}]},{"id":5045,"img":"newq-art/5045.png","c":"7.14","sda":"Du vil svinge til venstre ind på sidevejen. Hvordan placerer du bilen?","sfa":"می‌خواهید به چپ وارد فرعی شوید. خودرو را چطور قرار می‌دهید؟","sen":"You want to turn left into the side road. How do you position the car?","st":[{"da":"Jeg kører først ind til højre kant for at få et bredere sving.","fa":"اول به لبه‌ی راست می‌روم تا گردش بازتری داشته باشم.","ok":0,"eda":"Nej. Det forvirrer trafikken bag dig, som tror, du vil svinge til højre.","efa":"خیر. این کار ترافیک پشت سر را که خیال می‌کنند به راست می‌پیچید، گیج می‌کند.","en":"I first move to the right edge to get a wider turn.","een":"No. It confuses the traffic behind you, who think you are turning right."},{"da":"Jeg skærer svinget, så jeg hurtigt kommer ud af krydset.","fa":"گوشه را میان‌بر می‌زنم تا زود از تقاطع بیرون بروم.","ok":0,"eda":"Nej. Så kommer du over i venstre side af sidevejen og kan ramme en, der kommer ud.","efa":"خیر. این‌طور به سمت چپ فرعی می‌روید و ممکن است با کسی که بیرون می‌آید برخورد کنید.","en":"I cut the corner so that I get out of the junction quickly.","een":"No. Then you end up on the left side of the side road and may hit someone coming out."},{"da":"Så tæt på midten af vejen som muligt, før jeg svinger.","fa":"پیش از پیچیدن، تا جای ممکن نزدیک وسط جاده.","ok":1,"eda":"Ja. Ved venstresving skal du holde nær midten af kørebanen.","efa":"بله. در گردش به چپ باید نزدیک وسط سواره‌رو بمانید.","en":"As close to the middle of the road as possible before I turn.","een":"Yes. When turning left you must keep near the middle of the carriageway."},{"da":"Efter svinget kører jeg i højre side af sidevejen.","fa":"بعد از پیچیدن در سمت راست فرعی می‌رانم.","ok":1,"eda":"Ja. Svinget skal ende i højre side af den vej, du kører ind på.","efa":"بله. گردش باید در سمت راستِ جاده‌ای که واردش می‌شوید تمام شود.","en":"After the turn I drive on the right side of the side road.","een":"Yes. The turn must end on the right side of the road you enter."}]},{"id":5046,"img":"newq-art/5046.png","c":"7.14","sda":"Du vil svinge til venstre. To fodgængere går over sidevejen, du skal ind på. Hvordan forholder du dig?","sfa":"می‌خواهید به چپ بپیچید. دو عابر در حال عبور از فرعی‌ای هستند که می‌خواهید واردش شوید. چه می‌کنید؟","sen":"You want to turn left. Two pedestrians are crossing the side road you are turning into. What do you do?","st":[{"da":"Fodgængerne skal vente, fordi jeg allerede er i gang med at svinge.","fa":"عابران باید صبر کنند، چون من در حال پیچیدن هستم.","ok":0,"eda":"Nej. Det er dig, der skal tage hensyn til fodgængerne.","efa":"خیر. شما هستید که باید مراقب عابران باشید.","en":"The pedestrians must wait because I am already turning.","een":"No. It is you who must take care of the pedestrians."},{"da":"Jeg ser efter fodgængere i sidevejen, før jeg begynder at svinge.","fa":"پیش از شروع پیچیدن، عابران فرعی را نگاه می‌کنم.","ok":1,"eda":"Ja. Så kan du vente det rigtige sted uden at spærre for andre.","efa":"بله. این‌طور می‌توانید در جای درست صبر کنید بی‌آنکه راه را ببندید.","en":"I look for pedestrians in the side road before I start to turn.","een":"Yes. Then you can wait in the right place without blocking others."},{"da":"Jeg venter, til fodgængerne er kommet over.","fa":"صبر می‌کنم تا عابران رد شوند.","ok":1,"eda":"Ja. Når du svinger, må du ikke være til fare for gående, der går over den vej, du svinger ind på.","efa":"بله. هنگام پیچیدن نباید عابرانی را که از جاده‌ی مقصد رد می‌شوند به خطر بیندازید.","en":"I wait until the pedestrians are across.","een":"Yes. When you turn you must not endanger pedestrians crossing the road you turn into."}]},{"id":5047,"img":"newq-art/5047.png","c":"7.14","sda":"Både du og den modkørende vil svinge til venstre i krydset. Hvad gælder?","sfa":"هم شما و هم راننده‌ی روبه‌رو می‌خواهید در تقاطع به چپ بپیچید. چه قاعده‌ای برقرار است؟","sen":"Both you and the oncoming driver want to turn left in the junction. What applies?","st":[{"da":"Den, der kom først til krydset, har forkørselsret og svinger først.","fa":"هر کس اول به تقاطع رسیده، حق تقدم دارد و اول می‌پیچد.","ok":0,"eda":"Nej. Der er ingen sådan regel; I kan svinge samtidig og passere hinanden til venstre.","efa":"خیر. چنین قاعده‌ای نیست؛ می‌توانید هم‌زمان بپیچید و از سمت چپ از کنار هم رد شوید.","en":"Whoever reached the junction first has the right of way and turns first.","een":"No. There is no such rule; you can turn at the same time and pass each other on the left."},{"da":"Vi kan køre forbi hinanden til venstre, hvis det kan ske uden fare.","fa":"اگر بی‌خطر باشد، می‌توانیم از سمت چپ از کنار هم رد شویم.","ok":1,"eda":"Ja. Modkørende venstresvingende må køre forbi hinanden til venstre.","efa":"بله. دو خودروی روبه‌رو که به چپ می‌پیچند، می‌توانند از سمت چپ از کنار هم رد شوند.","en":"We may pass each other on the left if it can be done safely.","een":"Yes. Oncoming left-turners may pass each other on the left."},{"da":"Vi skal begge holde tilbage for modkørende, der kører ligeud.","fa":"هر دو باید به ترافیک روبه‌رویی که مستقیم می‌رود راه بدهیم.","ok":1,"eda":"Ja. Den grå bil, der kører ligeud, skal kunne passere først.","efa":"بله. باید بگذاریم خودروی خاکستری که مستقیم می‌رود اول رد شود.","en":"We must both give way to oncoming traffic going straight on.","een":"Yes. The grey car going straight on must be allowed to pass first."}]},{"id":5048,"img":"newq-art/5048.png","c":"7.14","sda":"Du kører på en ensrettet vej og vil svinge til venstre. Hvordan placerer du dig?","sfa":"در جاده‌ی یک‌طرفه می‌رانید و می‌خواهید به چپ بپیچید. چطور قرار می‌گیرید؟","sen":"You are on a one-way road and want to turn left. How do you position yourself?","st":[{"da":"Jeg blinker i god tid og sikrer mig, at svinget kan ske uden fare for trafikken bag mig.","fa":"به موقع راهنما می‌زنم و مطمئن می‌شوم گردش برای ترافیک پشت سرم بی‌خطر است.","ok":1,"eda":"Ja. Signalet skal gives i god tid, og du må ikke bringe trafikken bag dig i fare.","efa":"بله. علامت باید به موقع داده شود و نباید ترافیک پشت سر را به خطر بیندازید.","en":"I indicate in good time and make sure the turn can be made without danger to the traffic behind me.","een":"Yes. The signal must be given in good time, and you must not endanger the traffic behind you."},{"da":"Så langt til venstre som muligt.","fa":"تا جای ممکن سمت چپ.","ok":1,"eda":"Ja. På en ensrettet vej skal du ved venstresving holde nær venstre kant.","efa":"بله. در جاده‌ی یک‌طرفه برای گردش به چپ باید نزدیک لبه‌ی چپ باشید.","en":"As far to the left as possible.","een":"Yes. On a one-way road you keep near the left edge when turning left."},{"da":"Nær midten af vejen, som når jeg svinger til venstre fra en almindelig vej.","fa":"نزدیک وسط جاده، مثل گردش به چپ از یک جاده‌ی معمولی.","ok":0,"eda":"Nej. Der er ingen modkørende; du placerer dig ved venstre kant.","efa":"خیر. ترافیک روبه‌رو نیست؛ کنار لبه‌ی چپ قرار می‌گیرید.","en":"Near the middle of the road, as when I turn left from an ordinary road.","een":"No. There is no oncoming traffic; you position yourself at the left edge."}]},{"id":5049,"img":"newq-art/5049.png","c":"7.13","sda":"Du vil svinge til højre. På cykelstien til højre for dig kører en cyklist ligeud. Hvordan forholder du dig?","sfa":"می‌خواهید به راست بپیچید. روی مسیر دوچرخه‌ی سمت راستتان دوچرخه‌سواری مستقیم می‌رود. چه می‌کنید؟","sen":"You want to turn right. On the cycle path to your right a cyclist is going straight on. What do you do?","st":[{"da":"Jeg skynder mig at svinge, før cyklisten når krydset.","fa":"عجله می‌کنم پیش از رسیدن دوچرخه‌سوار به تقاطع بپیچم.","ok":0,"eda":"Nej. Det er farligt; cyklisten kan være tættere på, end du tror.","efa":"خیر. خطرناک است؛ ممکن است دوچرخه‌سوار نزدیک‌تر از آن باشد که فکر می‌کنید.","en":"I hurry to turn before the cyclist reaches the junction.","een":"No. That is dangerous; the cyclist may be closer than you think."},{"da":"Cyklisten skal holde tilbage, fordi jeg blinker.","fa":"دوچرخه‌سوار باید راه بدهد، چون من راهنما زده‌ام.","ok":0,"eda":"Nej. Blinklyset giver dig ikke forkørselsret.","efa":"خیر. راهنما به شما حق تقدم نمی‌دهد.","en":"The cyclist must give way because I am indicating.","een":"No. The indicator does not give you the right of way."},{"da":"Jeg kigger over højre skulder for at se i den blinde vinkel.","fa":"از روی شانه‌ی راست به نقطه‌ی کور نگاه می‌کنم.","ok":1,"eda":"Ja. En cyklist tæt ved bilen kan være skjult i den blinde vinkel.","efa":"بله. دوچرخه‌سواری نزدیک خودرو ممکن است در نقطه‌ی کور پنهان باشد.","en":"I look over my right shoulder to check the blind spot.","een":"Yes. A cyclist close to the car may be hidden in the blind spot."},{"da":"Jeg holder tilbage for cyklisten, der kører ligeud.","fa":"به دوچرخه‌سواری که مستقیم می‌رود راه می‌دهم.","ok":1,"eda":"Ja. Ved højresving må du ikke genere cyklister, der kører ligeud.","efa":"بله. در گردش به راست نباید مزاحم دوچرخه‌سوارانی شوید که مستقیم می‌روند.","en":"I give way to the cyclist going straight on.","een":"Yes. When turning right you must not inconvenience cyclists going straight on."}]},{"id":5050,"img":"newq-art/5050.png","c":"7.13","sda":"Du vil svinge til højre ind på sidevejen. Hvordan kører du?","sfa":"می‌خواهید به راست وارد فرعی شوید. چطور می‌رانید؟","sen":"You want to turn right into the side road. How do you drive?","st":[{"da":"Jeg holder farten i svinget, så jeg ikke generer trafikken bag mig.","fa":"سرعتم را در پیچ حفظ می‌کنم تا مزاحم ترافیک پشت سرم نشوم.","ok":0,"eda":"Nej. Ved sving skal farten ned, så du kan svinge sikkert og se efter cyklister og gående.","efa":"خیر. هنگام پیچیدن باید سرعت را کم کنید تا ایمن بپیچید و دوچرخه‌سواران و عابران را ببینید.","en":"I keep my speed in the turn so that I do not hold up the traffic behind me.","een":"No. When turning your speed must come down so that you can turn safely and look for cyclists and pedestrians."},{"da":"Jeg trækker først ud mod midten for at få et bredere sving.","fa":"اول به سمت وسط می‌روم تا گردش بازتری داشته باشم.","ok":0,"eda":"Nej. Så kan en bagfra eller en cyklist komme ind i højre side af dig.","efa":"خیر. این‌طور ممکن است کسی از پشت یا دوچرخه‌سواری از سمت راستتان بیاید.","en":"I first pull out towards the middle to get a wider turn.","een":"No. Then someone from behind or a cyclist may come up on your right."},{"da":"Jeg svinger ind i venstre side af sidevejen for ikke at ramme kantstenen.","fa":"به سمت چپ فرعی می‌پیچم تا به جدول نخورم.","ok":0,"eda":"Nej. Du skal ende i højre side af den vej, du kører ind på.","efa":"خیر. باید در سمت راستِ جاده‌ای که واردش می‌شوید قرار بگیرید.","en":"I turn into the left side of the side road so as not to hit the kerb.","een":"No. You must end up on the right side of the road you enter."},{"da":"Jeg holder så tæt ind til højre kant som muligt og gør svinget lille.","fa":"تا جای ممکن نزدیک لبه‌ی راست می‌مانم و گردش را کوچک می‌گیرم.","ok":1,"eda":"Ja. Ved højresving skal du holde nær højre kant og svinge så lidt som muligt.","efa":"بله. در گردش به راست باید نزدیک لبه‌ی راست بمانید و تا جای ممکن کوچک بپیچید.","en":"I keep as close to the right edge as possible and make the turn small.","een":"Yes. When turning right you keep near the right edge and turn as tightly as possible."}]},{"id":5051,"img":"newq-art/5051.png","c":"7.13","sda":"Du har grønt lys og vil svinge til højre. Fodgængere går over den vej, du skal ind på. Hvordan forholder du dig?","sfa":"چراغ شما سبز است و می‌خواهید به راست بپیچید. عابران از جاده‌ای که می‌خواهید واردش شوید رد می‌شوند. چه می‌کنید؟","sen":"You have a green light and want to turn right. Pedestrians are crossing the road you are turning into. What do you do?","st":[{"da":"Jeg dytter for at advare dem om, at jeg svinger.","fa":"بوق می‌زنم تا بدانند می‌پیچم.","ok":0,"eda":"Nej. Hornet bruges kun for at afværge fare; her skal du blot vente.","efa":"خیر. بوق فقط برای دفع خطر است؛ این‌جا فقط باید صبر کنید.","en":"I sound the horn to warn them that I am turning.","een":"No. The horn is only for averting danger; here you just wait."},{"da":"Jeg kører forsigtigt ind mellem fodgængerne.","fa":"با احتیاط از میان عابران رد می‌شوم.","ok":0,"eda":"Nej. Du må ikke køre ind på feltet, mens de gående er på det.","efa":"خیر. وقتی عابران روی گذرگاه‌اند، نباید واردش شوید.","en":"I drive carefully in between the pedestrians.","een":"No. You must not drive onto the crossing while the pedestrians are on it."},{"da":"Jeg holder tilbage for fodgængerne, til de er kommet over.","fa":"تا رد شدن عابران صبر می‌کنم.","ok":1,"eda":"Ja. Når du svinger gennem et fodgængerfelt, skal du sænke farten og om nødvendigt standse for de gående.","efa":"بله. وقتی از روی گذرگاه عابر می‌پیچید، باید سرعت را کم کنید و در صورت لزوم برای عابران بایستید.","en":"I wait for the pedestrians until they are across.","een":"Yes. When you turn through a pedestrian crossing you must slow down and stop if necessary for the pedestrians."},{"da":"Fodgængerne skal vente, fordi jeg også har grønt.","fa":"عابران باید صبر کنند، چون چراغ من هم سبز است.","ok":0,"eda":"Nej. Fodgængerne har grønt samtidig med dig; du skal vente på dem.","efa":"خیر. عابران هم‌زمان با شما سبزند؛ شما باید منتظرشان بمانید.","en":"The pedestrians must wait because I have green too.","een":"No. The pedestrians have green at the same time as you; you must wait for them."}]},{"id":5052,"img":"newq-art/5052.png","c":"7.13","sda":"Du vil svinge til højre. Cykelstien er dobbeltrettet, og en cyklist kommer imod dig på den. Hvordan forholder du dig?","sfa":"می‌خواهید به راست بپیچید. مسیر دوچرخه دوطرفه است و دوچرخه‌سواری روی آن از روبه‌رو می‌آید. چه می‌کنید؟","sen":"You want to turn right. The cycle path is two-way, and a cyclist is coming towards you on it. What do you do?","st":[{"da":"Cyklister på cykelstien kommer kun fra én retning.","fa":"دوچرخه‌سواران روی این مسیر فقط از یک جهت می‌آیند.","ok":0,"eda":"Nej. Pilene viser, at stien er dobbeltrettet.","efa":"خیر. فلش‌ها نشان می‌دهند که مسیر دوطرفه است.","en":"Cyclists on the cycle path only come from one direction.","een":"No. The arrows show that the path is two-way."},{"da":"Jeg holder tilbage for cyklisten, der kommer imod mig på cykelstien.","fa":"به دوچرخه‌سواری که روی مسیر دوچرخه از روبه‌رو می‌آید راه می‌دهم.","ok":1,"eda":"Ja. Ved højresving må du ikke være til ulempe for cyklister, der kører ligeud; på en dobbeltrettet cykelsti også dem, der kommer imod dig.","efa":"بله. هنگام گردش به راست نباید مزاحم دوچرخه‌سوارانی شوید که مستقیم می‌روند؛ در مسیر دوچرخه‌ی دوطرفه، این شامل کسانی هم می‌شود که از روبه‌رو می‌آیند.","en":"I give way to the cyclist coming towards me on the cycle path.","een":"Yes. When turning right you must not inconvenience cyclists going straight ahead; on a two-way cycle path that includes those coming towards you."},{"da":"Jeg ser efter cyklister fra begge retninger.","fa":"دوچرخه‌سواران هر دو جهت را نگاه می‌کنم.","ok":1,"eda":"Ja. På en dobbeltrettet cykelsti kan der komme cyklister både bagfra og forfra.","efa":"بله. روی مسیر دوچرخه‌ی دوطرفه، دوچرخه‌سواران هم از پشت و هم از جلو می‌آیند.","en":"I look for cyclists coming from both directions.","een":"Yes. On a two-way cycle path cyclists can come both from behind and from ahead."},{"da":"Jeg har forkørselsret, fordi cyklisten kører mod færdselsretningen.","fa":"حق تقدم با من است، چون دوچرخه‌سوار خلاف جهت ترافیک می‌رود.","ok":0,"eda":"Nej. På en dobbeltrettet cykelsti kører cyklisten lovligt i begge retninger.","efa":"خیر. روی مسیر دوچرخه‌ی دوطرفه، دوچرخه‌سوار مجاز است در هر دو جهت برود.","en":"I have the right of way because the cyclist is riding against the traffic.","een":"No. On a two-way cycle path the cyclist may lawfully ride in both directions."}]},{"id":5053,"img":"newq-art/5053.png","c":"1.2","sda":"Hvad er den mindste lovlige mønsterdybde i hovedmønsteret på en almindelig bils dæk?","sfa":"کمترین عمق مجاز آج در شیارهای اصلی لاستیک یک خودروی معمولی چقدر است؟","sen":"What is the smallest legal tread depth in the main grooves of an ordinary car's tyres?","st":[{"da":"1,6 mm.","fa":"۱٫۶ میلی‌متر.","ok":1,"eda":"Ja. Mønsterdybden skal være mindst 1,6 mm i hovedmønsteret.","efa":"بله. عمق آج در شیارهای اصلی باید دست‌کم ۱٫۶ میلی‌متر باشد.","en":"1.6 mm.","een":"Yes. The tread depth must be at least 1.6 mm in the main grooves."},{"da":"Der er intet krav, så længe dækket holder luft.","fa":"تا وقتی لاستیک باد نگه دارد، شرطی نیست.","ok":0,"eda":"Nej. Der er et lovkrav til mønsterdybden.","efa":"خیر. برای عمق آج حد قانونی وجود دارد.","en":"There is no requirement as long as the tyre holds air.","een":"No. There is a legal requirement for the tread depth."},{"da":"3 mm.","fa":"۳ میلی‌متر.","ok":0,"eda":"Nej. Mere mønster er godt især om vinteren, men kravet er 1,6 mm.","efa":"خیر. آج بیشتر به‌ویژه در زمستان خوب است، ولی حد قانونی ۱٫۶ میلی‌متر است.","en":"3 mm.","een":"No. More tread is good, especially in winter, but the requirement is 1.6 mm."},{"da":"1,0 mm.","fa":"۱٫۰ میلی‌متر.","ok":0,"eda":"Nej. 1,0 mm er under den lovlige grænse.","efa":"خیر. ۱٫۰ میلی‌متر کمتر از حد مجاز است.","en":"1.0 mm.","een":"No. 1.0 mm is below the legal limit."}]},{"id":5054,"img":"newq-art/5054.png","c":"1.2","sda":"Du opdager, at det ene af bilens bremselys ikke virker. Hvad gælder?","sfa":"متوجه می‌شوید یکی از چراغ‌های ترمز خودرو کار نمی‌کند. چه قاعده‌ای برقرار است؟","sen":"You find out that one of the car's brake lights is not working. What applies?","st":[{"da":"Bilen er ikke i lovlig stand, og jeg skal have det repareret.","fa":"خودرو در وضعیت قانونی نیست و باید تعمیرش کنم.","ok":1,"eda":"Ja. Alle påbudte lygter skal virke.","efa":"بله. همه‌ی چراغ‌های الزامی باید کار کنند.","en":"The car is not in a lawful condition and I must get it repaired.","een":"Yes. All required lights must work."},{"da":"Det er lovligt, så længe det andet bremselys virker.","fa":"تا وقتی چراغ ترمز دیگر کار کند، قانونی است.","ok":0,"eda":"Nej. Begge bremselys skal virke.","efa":"خیر. هر دو چراغ ترمز باید کار کنند.","en":"It is legal as long as the other brake light works.","een":"No. Both brake lights must work."},{"da":"Jeg kan bruge havariblinket i stedet, når jeg bremser.","fa":"هنگام ترمز می‌توانم به‌جایش چراغ خطر بزنم.","ok":0,"eda":"Nej. Havariblinket er ikke en erstatning for bremselyset.","efa":"خیر. چراغ خطر جایگزین چراغ ترمز نیست.","en":"I can use the hazard lights instead when I brake.","een":"No. The hazard lights are no substitute for the brake light."},{"da":"Jeg kan vente med at få det repareret, til bilen skal til syn næste gang.","fa":"می‌توانم تعمیرش را تا معاینه‌ی فنی بعدی خودرو عقب بیندازم.","ok":0,"eda":"Nej. Bilen skal være i lovlig stand, hver gang du kører; bremselyset advarer dem bag dig og skal virke.","efa":"خیر. خودرو هر بار که رانندگی می‌کنید باید در وضعیت قانونی باشد؛ چراغ ترمز به پشت‌سری‌ها هشدار می‌دهد و باید کار کند.","en":"I can wait to have it repaired until the car's next inspection.","een":"No. The car must be in a lawful condition every time you drive; the brake light warns those behind you and must work."}]},{"id":5055,"img":"newq-art/5055.png","c":"1.2","sda":"Det er vinter, og der ligger sne og sjap på vejen. Hvad gælder om bilens dæk?","sfa":"زمستان است و روی جاده برف و برفابه است. درباره‌ی لاستیک‌های خودرو چه قاعده‌ای برقرار است؟","sen":"It is winter, and there is snow and slush on the road. What applies to the car's tyres?","st":[{"da":"Det er mig som fører, der har ansvaret for, at dækkene passer til føret.","fa":"این من، یعنی راننده، هستم که مسئولم لاستیک‌ها با وضعیت جاده جور باشند.","ok":1,"eda":"Ja. Føreren skal selv sørge for, at bilen, også dækkene, er i forsvarlig stand til den kørsel, der skal ske.","efa":"بله. راننده خودش باید مطمئن شود خودرو، از جمله لاستیک‌ها، برای رانندگی پیش رو در وضعیت ایمنی است.","en":"It is me, the driver, who is responsible for the tyres suiting the conditions.","een":"Yes. The driver must make sure that the car, including its tyres, is in a safe condition for the driving to be done."},{"da":"Sommerdæk er lovlige i alt slags føre, når bare mønsterdybden er mindst 1,6 mm.","fa":"لاستیک تابستانی در هر وضعیتی از جاده قانونی است، به شرط آن‌که عمق آجش دست‌کم ۱٫۶ میلی‌متر باشد.","ok":0,"eda":"Nej. Sommerdæk i sne, sjap og slud anses i praksis for uegnede og dermed ulovlige.","efa":"خیر. لاستیک تابستانی در برف، برفابه و باران‌برف در عمل نامناسب و در نتیجه غیرقانونی شمرده می‌شود.","en":"Summer tyres are legal in all road conditions as long as the tread depth is at least 1.6 mm.","een":"No. Summer tyres in snow, slush and sleet are in practice considered unsuitable and so illegal."},{"da":"Jeg må ikke køre med dæk, der er åbenbart uegnede til føret.","fa":"نباید با لاستیک‌هایی برانم که آشکارا برای وضعیت جاده مناسب نیستند.","ok":1,"eda":"Ja. Siden 1. juli 2025 er det ulovligt at køre med dæk, der er åbenbart uegnede til føret, fx sommerdæk i sne og sjap.","efa":"بله. از ۱ ژوئیه‌ی ۲۰۲۵ رانندگی با لاستیک‌هایی که آشکارا برای وضعیت جاده نامناسب‌اند، مثلاً لاستیک تابستانی در برف و برفابه، غیرقانونی است.","en":"I must not drive on tyres that are obviously unsuitable for the road conditions.","een":"Yes. Since 1 July 2025 it is illegal to drive on tyres that are obviously unsuitable for the conditions, for example summer tyres in snow and slush."},{"da":"Pigdæk må bruges i perioden fra 1. november til 15. april.","fa":"لاستیک میخ‌دار را می‌توان از ۱ نوامبر تا ۱۵ آوریل استفاده کرد.","ok":1,"eda":"Ja. I Danmark er pigdæk tilladt fra 1. november til 15. april.","efa":"بله. در دانمارک لاستیک میخ‌دار از ۱ نوامبر تا ۱۵ آوریل مجاز است.","en":"Studded tyres may be used in the period from 1 November to 15 April.","een":"Yes. In Denmark studded tyres are allowed from 1 November to 15 April."}]},{"id":5056,"img":"newq-art/5056.png","c":"1.2","sda":"Hvordan skal nakkestøtten være indstillet?","sfa":"پشت‌سری صندلی چطور باید تنظیم شود؟","sen":"How should the head restraint be set?","st":[{"da":"Den beskytter mod nakkeskader ved påkørsel bagfra.","fa":"در تصادف از پشت، از آسیب گردن جلوگیری می‌کند.","ok":1,"eda":"Ja. Nakkestøtten forhindrer, at hovedet slynges bagover.","efa":"بله. پشت‌سری نمی‌گذارد سر به عقب پرتاب شود.","en":"It protects against neck injuries in a rear-end collision.","een":"Yes. The head restraint stops the head from being thrown backwards."},{"da":"Overkanten skal være i højde med toppen af hovedet og tæt ved hovedet.","fa":"لبه‌ی بالایش باید هم‌سطح بالای سر و نزدیک سر باشد.","ok":1,"eda":"Ja. Så støtter den hovedet bedst ved et stød bagfra.","efa":"بله. این‌طور در ضربه از پشت، بهترین پشتیبانی را از سر می‌کند.","en":"Its top edge should be level with the top of the head and close to the head.","een":"Yes. Then it supports the head best in an impact from behind."},{"da":"Den skal sidde så lavt som muligt for at give udsyn bagud.","fa":"باید تا جای ممکن پایین باشد تا دید عقب بهتر شود.","ok":0,"eda":"Nej. En lav nakkestøtte kan give alvorlige nakkeskader.","efa":"خیر. پشت‌سری پایین می‌تواند آسیب جدی به گردن بزند.","en":"It should be as low as possible to give a view to the rear.","een":"No. A low head restraint can cause serious neck injuries."},{"da":"Nakkestøtten skal indstilles efter den, der sidder i sædet.","fa":"پشت‌سری باید برای همان کسی تنظیم شود که روی صندلی نشسته است.","ok":1,"eda":"Ja. Folk er forskellige høje; tjek indstillingen, når en anden skal sidde i sædet.","efa":"بله. قد آدم‌ها فرق دارد؛ وقتی کس دیگری روی صندلی می‌نشیند، تنظیم را بررسی کنید.","en":"The head restraint must be set for the person sitting in the seat.","een":"Yes. People are of different heights; check the setting when someone else is going to sit in the seat."}]},{"id":5057,"img":"newq-art/5057.png","c":"1.2","sda":"Du skal køre med tunge kasser i bilen. Hvordan forholder du dig?","sfa":"باید با جعبه‌های سنگین در خودرو رانندگی کنید. چه می‌کنید؟","sen":"You are going to drive with heavy boxes in the car. What do you do?","st":[{"da":"Jeg sikrer lasten, så den ikke kan flytte sig.","fa":"بار را محکم می‌کنم تا جابه‌جا نشود.","ok":1,"eda":"Ja. Løs last kan blive kastet frem ved en kraftig opbremsning.","efa":"بله. بار شل در ترمز شدید به جلو پرتاب می‌شود.","en":"I secure the load so that it cannot move.","een":"Yes. A loose load can be thrown forward in hard braking."},{"da":"Tunge ting lægges så lavt og så langt frem i bagagerummet som muligt.","fa":"وسایل سنگین تا جای ممکن پایین و جلوی صندوق گذاشته می‌شوند.","ok":1,"eda":"Ja. Så påvirker de bilens køreegenskaber mindst og bliver bedst holdt på plads.","efa":"بله. این‌طور کمترین اثر را بر رفتار خودرو دارند و بهتر سر جایشان می‌مانند.","en":"Heavy items go as low and as far forward in the boot as possible.","een":"Yes. Then they affect the car's handling least and are held in place best."},{"da":"Værktøjskassen kan godt ligge løst på hattehylden.","fa":"جعبه‌ابزار می‌تواند شل روی طاقچه‌ی عقب بماند.","ok":0,"eda":"Nej. En tung, løs genstand på hattehylden kan ramme dem i bilen ved et brat stop.","efa":"خیر. شیء سنگین و شل روی طاقچه‌ی عقب، در توقف ناگهانی به سرنشینان می‌خورد.","en":"The toolbox can lie loose on the parcel shelf.","een":"No. A heavy loose object on the parcel shelf can hit the people in the car in a sudden stop."},{"da":"Lasten påvirker ikke bilens bremselængde.","fa":"بار روی مسافت ترمز خودرو اثری ندارد.","ok":0,"eda":"Nej. En tungt lastet bil har længere bremselængde.","efa":"خیر. خودروی پربار مسافت ترمز بیشتری دارد.","en":"The load does not affect the car's braking distance.","een":"No. A heavily loaded car has a longer braking distance."}]},{"id":5058,"img":"newq-art/5058.png","c":"7.7","sda":"Vejen er så smal, at to biler ikke kan passere hinanden. En varevogn kommer imod dig. Hvordan forholder du dig?","sfa":"جاده آن‌قدر باریک است که دو خودرو نمی‌توانند از کنار هم رد شوند. ونی از روبه‌رو می‌آید. چه می‌کنید؟","sen":"The road is so narrow that two cars cannot pass each other. A van is coming towards you. What do you do?","st":[{"da":"Jeg sænker farten og holder så langt til højre som muligt.","fa":"سرعتم را کم می‌کنم و تا جای ممکن سمت راست می‌مانم.","ok":1,"eda":"Ja. Ved møde skal du holde til højre og tilpasse farten.","efa":"بله. در برخورد با خودروی روبه‌رو باید سمت راست بمانید و سرعت را تنظیم کنید.","en":"I slow down and keep as far to the right as possible.","een":"Yes. When meeting you must keep right and adjust your speed."},{"da":"Jeg kører ind på vigepladsen i min side og lader varevognen passere.","fa":"وارد جای کنار جاده در سمت خودم می‌شوم و می‌گذارم ون رد شود.","ok":1,"eda":"Ja. Ved møde på smal vej skal den, der kan, give plads; her har du vigepladsen i din side.","efa":"بله. در برخورد در جاده‌ی باریک، هر که بتواند باید جا بدهد؛ این‌جا جای کنار جاده در سمت شماست.","en":"I pull into the passing place on my side and let the van pass.","een":"Yes. When meeting on a narrow road, whoever can must make room; here the passing place is on your side."},{"da":"Jeg blinker med lyset for at få varevognen til at bakke.","fa":"چراغ می‌زنم تا ون دنده‌عقب برود.","ok":0,"eda":"Nej. Lyssignaler giver ikke forkørselsret, og bakning er ofte farligere.","efa":"خیر. چراغ زدن حق تقدم نمی‌دهد و دنده‌عقب رفتن اغلب خطرناک‌تر است.","en":"I flash my lights to make the van reverse.","een":"No. Flashing lights gives no right of way, and reversing is often more dangerous."},{"da":"Den, der kører hurtigst, skal holde tilbage.","fa":"هر که تندتر می‌رود باید راه بدهد.","ok":0,"eda":"Nej. Der er ingen sådan regel; I skal sammen finde en sikker løsning.","efa":"خیر. چنین قاعده‌ای نیست؛ باید با هم راه ایمنی پیدا کنید.","en":"Whoever is driving fastest must give way.","een":"No. There is no such rule; together you must find a safe solution."}]},{"id":5059,"img":"newq-art/5059.png","c":"7.7","sda":"Du bliver blændet af en modkørende bil. Hvordan forholder du dig?","sfa":"خودروی روبه‌رو چشم شما را خیره کرده است. چه می‌کنید؟","sen":"You are dazzled by an oncoming car. What do you do?","st":[{"da":"Jeg sænker farten.","fa":"سرعتم را کم می‌کنم.","ok":1,"eda":"Ja. Når du ikke kan se, hvad der er foran, skal hastigheden ned.","efa":"بله. وقتی جلو را نمی‌بینید، باید سرعت را کم کنید.","en":"I slow down.","een":"Yes. When you cannot see what is ahead, your speed must come down."},{"da":"Jeg ser mod højre vejkant.","fa":"به لبه‌ی راست جاده نگاه می‌کنم.","ok":1,"eda":"Ja. Så bliver du mindre blændet og kan holde din plads på vejen.","efa":"بله. این‌طور کمتر خیره می‌شوید و جایتان را در جاده حفظ می‌کنید.","en":"I look towards the right edge of the road.","een":"Yes. That way you are dazzled less and can keep your place on the road."},{"da":"Jeg tænder fjernlyset for at blænde den modkørende igen.","fa":"نور بالا را روشن می‌کنم تا راننده‌ی روبه‌رو را هم خیره کنم.","ok":0,"eda":"Nej. Så kan I begge ikke se noget; det er farligt.","efa":"خیر. این‌طور هیچ‌کدام چیزی نمی‌بینید؛ خطرناک است.","en":"I switch on my high beam to dazzle the oncoming driver back.","een":"No. Then neither of you can see anything; it is dangerous."},{"da":"Jeg er klar til at standse, hvis jeg ikke kan se vejen.","fa":"اگر جاده را نبینم، آماده‌ی ایستادن هستم.","ok":1,"eda":"Ja. Du skal kunne standse på den strækning, du kan overskue.","efa":"بله. باید بتوانید در فاصله‌ای که می‌بینید بایستید.","en":"I am ready to stop if I cannot see the road.","een":"Yes. You must be able to stop within the distance you can see."}]},{"id":5060,"img":"newq-art/5060.png","c":"7.7","sda":"En bred lastbil kommer imod dig på en smal vej. Hvordan forholder du dig?","sfa":"کامیون پهنی در جاده‌ای باریک از روبه‌رو می‌آید. چه می‌کنید؟","sen":"A wide lorry is coming towards you on a narrow road. What do you do?","st":[{"da":"Jeg sænker farten og holder godt til højre.","fa":"سرعتم را کم می‌کنم و خوب سمت راست می‌مانم.","ok":1,"eda":"Ja. Ved møde skal du give den modkørende tilstrækkelig plads.","efa":"بله. در برخورد باید به وسیله‌ی روبه‌رو جای کافی بدهید.","en":"I slow down and keep well to the right.","een":"Yes. When meeting you must give the oncoming vehicle enough room."},{"da":"Luftsuget fra lastbilen kan rykke i min bil.","fa":"جریان هوای کامیون ممکن است خودروی مرا تکان بدهد.","ok":1,"eda":"Ja. Hold derfor godt fast i rattet og god afstand.","efa":"بله. پس فرمان را محکم نگه دارید و فاصله‌ی خوبی بگیرید.","en":"The air pressure from the lorry may pull at my car.","een":"Yes. So hold the wheel firmly and keep a good distance."},{"da":"Jeg holder fast i midten af min vognbane, fordi det er min side.","fa":"وسط خط خودم می‌مانم، چون سمت من است.","ok":0,"eda":"Nej. Du skal tilpasse dig og give plads, når den modkørende fylder meget.","efa":"خیر. وقتی وسیله‌ی روبه‌رو جای زیادی می‌گیرد، باید خودتان را تطبیق دهید و جا بدهید.","en":"I stay in the middle of my lane because it is my side.","een":"No. You must adapt and make room when the oncoming vehicle takes up a lot of space."},{"da":"Jeg standser om nødvendigt, hvor der er plads nok.","fa":"در صورت لزوم جایی که جای کافی هست می‌ایستم.","ok":1,"eda":"Ja. Det er bedre at vente kort end at møde lastbilen, hvor der ikke er plads.","efa":"بله. بهتر است کمی صبر کنید تا این‌که جایی که جا نیست با کامیون روبه‌رو شوید.","en":"I stop if necessary where there is enough room.","een":"Yes. It is better to wait briefly than to meet the lorry where there is no room."}]},{"id":5061,"img":"newq-art/5061.png","c":"7.11","sda":"Du skal ud på den tværgående vej. Hækkene skjuler udsynet. Hvordan forholder du dig?","sfa":"می‌خواهید وارد جاده‌ی متقاطع شوید. پرچین‌ها جلوی دید را گرفته‌اند. چه می‌کنید؟","sen":"You are going to drive onto the crossing road. The hedges hide the view. What do you do?","st":[{"da":"Jeg kører langsomt frem, til jeg kan se, om der kommer nogen.","fa":"آهسته جلو می‌روم تا ببینم کسی می‌آید یا نه.","ok":1,"eda":"Ja. Først når du kan se, at vejen er fri, kan du køre ud uden fare.","efa":"بله. فقط وقتی ببینید جاده خالی است، می‌توانید بی‌خطر وارد شوید.","en":"I edge forward slowly until I can see whether anyone is coming.","een":"Yes. Only when you can see that the road is clear can you drive out safely."},{"da":"Jeg kører ud, når jeg ikke kan høre nogen biler.","fa":"وقتی صدای خودرویی نمی‌شنوم، وارد می‌شوم.","ok":0,"eda":"Nej. Du kan ikke høre alle køretøjer, fx cyklister og elbiler.","efa":"خیر. صدای همه‌ی وسایل، مثلاً دوچرخه و خودروی برقی، را نمی‌شنوید.","en":"I drive out when I cannot hear any cars.","een":"No. You cannot hear every vehicle, for example cyclists and electric cars."},{"da":"Jeg sænker farten i god tid.","fa":"به موقع سرعتم را کم می‌کنم.","ok":1,"eda":"Ja. Du har ubetinget vigepligt og skal vise det i god tid.","efa":"بله. باید بی‌قیدوشرط راه بدهید و این را به موقع نشان دهید.","en":"I slow down in good time.","een":"Yes. You must give way unconditionally and show it in good time."},{"da":"Hajtænderne gælder kun trafikken fra venstre.","fa":"دندان‌کوسه فقط برای ترافیک سمت چپ است.","ok":0,"eda":"Nej. Du har ubetinget vigepligt for trafikken fra begge sider.","efa":"خیر. باید بی‌قیدوشرط به ترافیک هر دو طرف راه بدهید.","en":"The shark teeth only apply to traffic from the left.","een":"No. You must give way unconditionally to traffic from both sides."}]},{"id":5062,"img":"newq-art/5062.png","c":"7.11","sda":"Du kører forbi denne tavle. Hvad betyder den?","sfa":"از کنار این تابلو رد می‌شوید. یعنی چه؟","sen":"You pass this sign. What does it mean?","st":[{"da":"Der kommer et kryds, hvor trafikken fra sidevejene har ubetinget vigepligt.","fa":"تقاطعی در پیش است که ترافیک فرعی‌ها در آن باید بی‌قیدوشرط راه بدهد.","ok":1,"eda":"Ja. Tavle A 11 varsler et farligt vejkryds, hvor den krydsende trafik har ubetinget vigepligt.","efa":"بله. تابلوی A 11 از تقاطع خطرناکی هشدار می‌دهد که ترافیک متقاطع در آن باید بی‌قیدوشرط راه بدهد.","en":"A junction is coming where traffic from the side roads must give way unconditionally.","een":"Yes. Sign A 11 warns of a dangerous junction where the crossing traffic must give way unconditionally."},{"da":"Tavlen betyder, at jeg skal standse ved krydset.","fa":"این تابلو یعنی باید در تقاطع بایستم.","ok":0,"eda":"Nej. Tavlen er en advarsel; det er den krydsende trafik, der har ubetinget vigepligt, men vær klar til at reagere.","efa":"خیر. این تابلو هشدار است؛ ترافیک متقاطع است که باید بی‌قیدوشرط راه بدهد، ولی آماده‌ی واکنش باشید.","en":"The sign means that I must stop at the junction.","een":"No. The sign is a warning; it is the crossing traffic that must give way unconditionally, but be ready to react."},{"da":"Jeg skal holde tilbage for trafik fra højre.","fa":"باید به ترافیک سمت راست راه بدهم.","ok":0,"eda":"Nej. Det er trafikken fra sidevejene, der skal holde tilbage for dig.","efa":"خیر. ترافیک فرعی‌هاست که باید به شما راه بدهد.","en":"I must give way to traffic from the right.","een":"No. It is the traffic from the side roads that must give way to you."},{"da":"Tavlen betyder, at krydset er reguleret med lyssignal.","fa":"این تابلو یعنی تقاطع چراغ راهنمایی دارد.","ok":0,"eda":"Nej. Lyssignaler varsles med en anden tavle.","efa":"خیر. برای چراغ راهنمایی تابلوی هشدار دیگری هست.","en":"The sign means the junction is controlled by traffic lights.","een":"No. Traffic lights are warned of with a different sign."}]},{"id":5063,"img":"newq-art/5063.png","c":"7.11","sda":"Du kører forbi denne tavle. Lidt fremme kommer en sidevej fra højre uden tavler. Hvad gælder?","sfa":"از کنار این تابلو رد می‌شوید. کمی جلوتر فرعی‌ای بدون تابلو از سمت راست می‌آید. چه قاعده‌ای برقرار است؟","sen":"You pass this sign. A little further on there is a side road from the right with no signs. What applies?","st":[{"da":"Tavlen betyder, at vejen bliver ensrettet.","fa":"این تابلو یعنی جاده یک‌طرفه می‌شود.","ok":0,"eda":"Nej. Ensretning har sin egen tavle.","efa":"خیر. یک‌طرفه بودن تابلوی خودش را دارد.","en":"The sign means the road becomes one-way.","een":"No. One-way traffic has its own sign."},{"da":"Ved sidevejen gælder højrereglen, fordi der ikke er andre tavler.","fa":"کنار آن فرعی قاعده‌ی دست راست برقرار است، چون تابلوی دیگری نیست.","ok":1,"eda":"Ja. Uden tavler og afmærkning skal du holde tilbage for trafik fra højre.","efa":"بله. بدون تابلو و خط‌کشی باید به ترافیک سمت راست راه بدهید.","en":"At the side road the right-hand rule applies because there are no other signs.","een":"Yes. Without signs or markings you must give way to traffic from the right."},{"da":"Jeg har stadig forkørselsret i alle kryds.","fa":"هنوز در همه‌ی تقاطع‌ها حق تقدم دارم.","ok":0,"eda":"Nej. Forkørselsretten på hovedvejen ophører med tavlen.","efa":"خیر. حق تقدم جاده‌ی اصلی با این تابلو تمام می‌شود.","en":"I still have the right of way at every junction.","een":"No. The right of way of the main road ends with the sign."},{"da":"Hovedvejen ophører.","fa":"جاده‌ی اصلی تمام می‌شود.","ok":1,"eda":"Ja. Tavle B 17 viser, at hovedvejen ophører.","efa":"بله. تابلوی B 17 نشان می‌دهد جاده‌ی اصلی تمام شده است.","en":"The main road ends.","een":"Yes. Sign B 17 shows that the main road ends."}]},{"id":5064,"img":"newq-art/5064.png","c":"7.11","sda":"En cyklist kommer fra højre ad en sti gennem parken og skal over vejen. Hvad gælder?","sfa":"دوچرخه‌سواری از سمت راست، از مسیری در پارک، می‌آید و می‌خواهد از جاده رد شود. چه قاعده‌ای برقرار است؟","sen":"A cyclist is coming from the right along a path through the park and is going to cross the road. What applies?","st":[{"da":"Højrereglen gælder, så jeg skal holde tilbage for cyklisten.","fa":"قاعده‌ی دست راست برقرار است، پس باید به دوچرخه‌سوار راه بدهم.","ok":0,"eda":"Nej. Højrereglen gælder ikke for den, der kommer fra en sådan sti.","efa":"خیر. قاعده‌ی دست راست برای کسی که از چنین مسیری می‌آید اعمال نمی‌شود.","en":"The right-hand rule applies, so I must give way to the cyclist.","een":"No. The right-hand rule does not apply to someone coming from such a path."},{"da":"Cyklisten har ubetinget vigepligt, fordi stien ikke hører til en vej.","fa":"دوچرخه‌سوار باید بی‌قیدوشرط راه بدهد، چون این مسیر جزو جاده نیست.","ok":1,"eda":"Ja. Cyklister fra en sti, der ikke er anlagt i forbindelse med en vej, har ubetinget vigepligt.","efa":"بله. دوچرخه‌سوارانی که از مسیری جدا از جاده می‌آیند، باید بی‌قیدوشرط راه بدهند.","en":"The cyclist must give way unconditionally because the path is not part of a road.","een":"Yes. Cyclists coming from a path not built as part of a road must give way unconditionally."},{"da":"Jeg er alligevel klar til at bremse, hvis cyklisten ikke holder tilbage.","fa":"با این حال آماده‌ی ترمزم، اگر دوچرخه‌سوار راه ندهد.","ok":1,"eda":"Ja. Du skal altid være opmærksom på, om andre overholder deres vigepligt.","efa":"بله. همیشه باید ببینید دیگران وظیفه‌ی راه دادن را رعایت می‌کنند یا نه.","en":"I am still ready to brake if the cyclist does not give way.","een":"Yes. You must always watch whether others keep their duty to give way."}]},{"id":5065,"img":"newq-art/5065.png","c":"7.4","sda":"Du vil skifte til venstre vognbane. Hvordan forholder du dig?","sfa":"می‌خواهید به خط چپ بروید. چه می‌کنید؟","sen":"You want to change to the left-hand lane. What do you do?","st":[{"da":"Jeg giver tegn med blinklyset i god tid, før jeg skifter vognbane.","fa":"پیش از تغییر خط، به موقع راهنما می‌زنم.","ok":1,"eda":"Ja. Andre skal kunne nå at se, hvad du vil gøre.","efa":"بله. دیگران باید فرصت داشته باشند ببینند چه می‌خواهید بکنید.","en":"I signal with the indicator in good time before I change lanes.","een":"Yes. Others must have time to see what you are going to do."},{"da":"Jeg skifter først, når det kan ske uden fare eller unødig ulempe for bilen i venstre vognbane.","fa":"فقط وقتی تغییر خط می‌دهم که برای خودروی خط چپ خطر یا مزاحمت بی‌جا نداشته باشد.","ok":1,"eda":"Ja. Færdselsloven § 18 kræver, at vognbaneskift kan ske uden fare eller unødig ulempe for andre.","efa":"بله. ماده‌ی ۱۸ قانون می‌خواهد تغییر خط بدون خطر یا مزاحمت بی‌جا برای دیگران باشد.","en":"I only change when it can be done without danger or undue inconvenience to the car in the left lane.","een":"Yes. Færdselsloven § 18 requires a lane change to be possible without danger or undue inconvenience to others."},{"da":"Jeg ser i spejlet og over skulderen, før jeg skifter vognbane.","fa":"پیش از تغییر خط، در آینه و از روی شانه نگاه می‌کنم.","ok":1,"eda":"Ja. Et skulderkig viser det, der er i den blinde vinkel.","efa":"بله. نگاه از روی شانه آن‌چه را در نقطه‌ی کور است نشان می‌دهد.","en":"I look in the mirror and over my shoulder before I change lanes.","een":"Yes. A look over the shoulder shows what is in the blind spot."},{"da":"Bilen i venstre vognbane skal sænke farten, når jeg blinker.","fa":"خودروی خط چپ وقتی راهنما می‌زنم، باید سرعتش را کم کند.","ok":0,"eda":"Nej. Blinklyset giver dig ikke ret til at skifte vognbane.","efa":"خیر. راهنما به شما حق تغییر خط نمی‌دهد.","en":"The car in the left lane must slow down when I indicate.","een":"No. The indicator does not give you the right to change lanes."}]},{"id":5066,"img":"newq-art/5066.png","c":"7.4","sda":"Den ene vognbane ophører, og der er tæt trafik i begge vognbaner. Hvad gælder?","sfa":"یکی از خط‌ها تمام می‌شود و در هر دو خط ترافیک سنگین است. چه قاعده‌ای برقرار است؟","sen":"One of the lanes ends, and there is dense traffic in both lanes. What applies?","st":[{"da":"Det er en god idé at flette skiftevis, én bil fra hver vognbane.","fa":"خوب است به نوبت، یکی از هر خط، ادغام شویم.","ok":1,"eda":"Ja. Fletning på skift får trafikken til at glide bedst.","efa":"بله. ادغام نوبتی باعث می‌شود ترافیک روان‌تر حرکت کند.","en":"It is a good idea to merge in turn, one car from each lane.","een":"Yes. Merging in turn makes the traffic flow best."},{"da":"Den, der kører i den vognbane, der fortsætter, behøver ikke tage hensyn.","fa":"کسی که در خطی می‌رود که ادامه دارد، لازم نیست ملاحظه کند.","ok":0,"eda":"Nej. Hensynet gælder begge veje.","efa":"خیر. ملاحظه از هر دو طرف لازم است.","en":"Whoever drives in the lane that continues need not show any consideration.","een":"No. Consideration applies both ways."},{"da":"Vi skal vise gensidigt hensyn og tilpasse farten.","fa":"باید به هم ملاحظه نشان دهیم و سرعت را تنظیم کنیم.","ok":1,"eda":"Ja. Når antallet af vognbaner bliver mindre, skal de kørende tilpasse sig under gensidig hensyntagen.","efa":"بله. وقتی تعداد خط‌ها کم می‌شود، رانندگان باید با ملاحظه‌ی متقابل خود را تطبیق دهند.","en":"We must show each other consideration and adjust our speed.","een":"Yes. When the number of lanes decreases, drivers must adapt with mutual consideration."}]},{"id":5067,"img":"newq-art/5067.png","c":"7.16","sda":"Du kører på accelerationsbanen ind mod motorvejen. Hvordan forholder du dig?","sfa":"در خط شتاب‌گیری به سمت بزرگراه می‌رانید. چه می‌کنید؟","sen":"You are on the acceleration lane onto the motorway. What do you do?","st":[{"da":"Jeg tilpasser farten til trafikken på motorvejen.","fa":"سرعتم را با ترافیک بزرگراه هماهنگ می‌کنم.","ok":1,"eda":"Ja. På accelerationsbanen skal du tilpasse farten til trafikken i den vognbane, du skal over i.","efa":"بله. در خط شتاب‌گیری باید سرعت را با ترافیک خطی که واردش می‌شوید هماهنگ کنید.","en":"I adjust my speed to the traffic on the motorway.","een":"Yes. On the acceleration lane you must match your speed to the traffic in the lane you are joining."},{"da":"Trafikken på motorvejen skal altid skifte vognbane for at lukke mig ind.","fa":"ترافیک بزرگراه همیشه باید خط عوض کند تا مرا راه بدهد.","ok":0,"eda":"Nej. De på motorvejen skal om nødvendigt lette din indkørsel, men du skal selv tilpasse farten og finde et sikkert hul.","efa":"خیر. رانندگان بزرگراه در صورت لزوم ورود شما را آسان‌تر می‌کنند، ولی خودتان باید سرعت را هماهنگ کنید و فاصله‌ی امنی پیدا کنید.","en":"The motorway traffic must always change lanes to let me in.","een":"No. Those on the motorway should make it easier for you to join if needed, but you must match your speed and find a safe gap yourself."},{"da":"Jeg standser for enden af banen og venter på et stort hul.","fa":"در انتهای خط می‌ایستم و منتظر فاصله‌ای بزرگ می‌مانم.","ok":0,"eda":"Nej. At standse er farligt; brug banens længde til at tilpasse farten og find et hul.","efa":"خیر. ایستادن خطرناک است؛ از طول خط برای هماهنگ کردن سرعت و پیدا کردن فاصله استفاده کنید.","en":"I stop at the end of the lane and wait for a big gap.","een":"No. Stopping is dangerous; use the lane's length to match your speed and find a gap."},{"da":"Jeg kører ud på motorvejen, når det kan ske uden fare.","fa":"وقتی بی‌خطر باشد وارد بزرگراه می‌شوم.","ok":1,"eda":"Ja. Du skal forlade accelerationsbanen, når det kan ske uden fare.","efa":"بله. وقتی بی‌خطر باشد، باید خط شتاب‌گیری را ترک کنید.","en":"I move onto the motorway when it can be done safely.","een":"Yes. You must leave the acceleration lane when it can be done safely."}]},{"id":5068,"img":"newq-art/5068.png","c":"7.1","sda":"Du holder ved kantstenen og vil køre ud. Bag dig kommer en cyklist. Hvordan forholder du dig?","sfa":"کنار جدول ایستاده‌اید و می‌خواهید حرکت کنید. از پشت دوچرخه‌سواری می‌آید. چه می‌کنید؟","sen":"You are parked at the kerb and want to drive off. A cyclist is coming up behind you. What do you do?","st":[{"da":"Jeg lader cyklisten passere, før jeg kører ud.","fa":"می‌گذارم دوچرخه‌سوار رد شود و بعد حرکت می‌کنم.","ok":1,"eda":"Ja. Du må kun køre ud fra vejkanten, når det kan ske uden fare eller unødig ulempe for andre.","efa":"بله. فقط وقتی می‌توانید از کنار جاده حرکت کنید که برای دیگران خطر یا مزاحمت بی‌جا نداشته باشد.","en":"I let the cyclist pass before I drive off.","een":"Yes. You may only pull away from the kerb when it can be done without danger or undue inconvenience to others."},{"da":"Når jeg blinker, skal cyklisten holde tilbage.","fa":"وقتی راهنما بزنم، دوچرخه‌سوار باید راه بدهد.","ok":0,"eda":"Nej. Blinklyset giver dig ikke ret til at køre ud.","efa":"خیر. راهنما به شما حق حرکت نمی‌دهد.","en":"When I indicate, the cyclist must give way.","een":"No. The indicator does not give you the right to pull out."},{"da":"Jeg blinker og kigger over venstre skulder, før jeg kører ud.","fa":"راهنما می‌زنم و پیش از حرکت از روی شانه‌ی چپ نگاه می‌کنم.","ok":1,"eda":"Ja. Du skal give tegn, før du kører ud fra vejkanten, og tjekke den blinde vinkel.","efa":"بله. پیش از حرکت از کنار جاده باید علامت بدهید و نقطه‌ی کور را بررسی کنید.","en":"I indicate and look over my left shoulder before I pull out.","een":"Yes. You must signal before pulling away from the kerb and check the blind spot."},{"da":"Spejlene er nok; jeg behøver ikke dreje hovedet.","fa":"آینه‌ها کافی‌اند؛ لازم نیست سرم را بچرخانم.","ok":0,"eda":"Nej. Spejlene viser ikke den blinde vinkel.","efa":"خیر. آینه‌ها نقطه‌ی کور را نشان نمی‌دهند.","en":"The mirrors are enough; I do not need to turn my head.","een":"No. The mirrors do not show the blind spot."}]},{"id":5069,"img":"newq-art/5069.png","c":"7.1","sda":"Du vil standse ved kantstenen lidt fremme. Hvordan forholder du dig?","sfa":"می‌خواهید کمی جلوتر کنار جدول بایستید. چه می‌کنید؟","sen":"You want to stop at the kerb a little further ahead. What do you do?","st":[{"da":"Jeg holder øje med cyklisten i højre side.","fa":"مراقب دوچرخه‌سوار سمت راست هستم.","ok":1,"eda":"Ja. Du må ikke klemme cyklisten mellem bilen og kantstenen.","efa":"بله. نباید دوچرخه‌سوار را بین خودرو و جدول گیر بیندازید.","en":"I keep an eye on the cyclist on the right.","een":"Yes. You must not squeeze the cyclist between the car and the kerb."},{"da":"Jeg ser i spejlet og giver tegn i god tid.","fa":"در آینه نگاه می‌کنم و به موقع علامت می‌دهم.","ok":1,"eda":"Ja. Bilerne bag dig skal kunne forstå, hvad du vil.","efa":"بله. خودروهای پشت سر باید بفهمند چه قصدی دارید.","en":"I look in the mirror and signal in good time.","een":"Yes. The cars behind you must be able to understand what you are doing."},{"da":"Jeg bremser hårdt, så jeg hurtigt kommer ind til kanten.","fa":"محکم ترمز می‌کنم تا زود کنار جدول برسم.","ok":0,"eda":"Nej. Pludselig opbremsning kan skabe fare for dem bag dig.","efa":"خیر. ترمز ناگهانی ممکن است پشت‌سری‌ها را به خطر بیندازد.","en":"I brake hard so that I get to the kerb quickly.","een":"No. Sudden braking can endanger those behind you."}]},{"id":5070,"img":"newq-art/5070.png","c":"7.2","sda":"Der er ingen modkørende. Hvordan placerer du bilen på vejen?","sfa":"ترافیک روبه‌رو نیست. خودرو را در جاده چطور قرار می‌دهید؟","sen":"There is no oncoming traffic. How do you position the car on the road?","st":[{"da":"Manden går forkert, fordi han går i højre side.","fa":"آن مرد اشتباه می‌رود، چون در سمت راست است.","ok":0,"eda":"Nej. Den, der trækker en cykel, skal gå i vejens højre side.","efa":"خیر. کسی که دوچرخه را با دست می‌برد، باید در سمت راست جاده برود.","en":"The man is walking wrongly because he is on the right side.","een":"No. Someone pushing a bicycle must walk on the right side of the road."},{"da":"Jeg holder så langt til højre, som forholdene tillader.","fa":"تا جایی که شرایط اجازه دهد سمت راست می‌مانم.","ok":1,"eda":"Ja. Kørende skal holde så langt til højre som muligt under hensyn til anden færdsel og forholdene.","efa":"بله. رانندگان باید با در نظر گرفتن ترافیک و شرایط، تا جای ممکن سمت راست بمانند.","en":"I keep as far to the right as the conditions allow.","een":"Yes. Drivers must keep as far right as possible, considering other traffic and the conditions."},{"da":"Jeg kører midt på vejen, fordi der ikke er nogen modkørende.","fa":"وسط جاده می‌رانم، چون ترافیک روبه‌رو نیست.","ok":0,"eda":"Nej. Reglen om at holde til højre gælder også på en tom vej.","efa":"خیر. قاعده‌ی سمت راست ماندن در جاده‌ی خالی هم برقرار است.","en":"I drive in the middle of the road because there is no oncoming traffic.","een":"No. The keep-right rule applies on an empty road too."},{"da":"Når jeg passerer manden med cyklen, giver jeg ham god plads.","fa":"وقتی از کنار مرد دوچرخه‌به‌دست رد می‌شوم، جای زیادی به او می‌دهم.","ok":1,"eda":"Ja. Gående skal have god plads, når du passerer dem.","efa":"بله. هنگام رد شدن از کنار عابران باید جای کافی به آن‌ها بدهید.","en":"When I pass the man with the bicycle, I give him plenty of room.","een":"Yes. Pedestrians must be given plenty of room when you pass them."}]},{"id":5071,"img":"newq-art/5071.png","c":"7.2","sda":"Vejen har tre vognbaner og trafik i begge retninger. Hvad gælder?","sfa":"جاده سه خط دارد و از هر دو طرف ترافیک دارد. چه قاعده‌ای برقرار است؟","sen":"The road has three lanes and traffic in both directions. What applies?","st":[{"da":"Jeg må ikke bruge vognbanen længst til venstre.","fa":"نباید از چپ‌ترین خط استفاده کنم.","ok":1,"eda":"Ja. På en vej med tre vognbaner og trafik i begge retninger må den venstre vognbane ikke bruges.","efa":"بله. در جاده‌ی سه‌خطه‌ی دوطرفه، نباید از خط سمت چپ استفاده کرد.","en":"I must not use the lane furthest to the left.","een":"Yes. On a road with three lanes and traffic in both directions the left lane must not be used."},{"da":"Midtervognbanen er kun for min retning.","fa":"خط وسط فقط برای جهت من است.","ok":0,"eda":"Nej. Den deles af begge retninger; vær særligt opmærksom på modkørende i den.","efa":"خیر. هر دو جهت از آن استفاده می‌کنند؛ مراقب ترافیک روبه‌رو در آن باشید.","en":"The middle lane is only for my direction.","een":"No. It is shared by both directions; watch especially for oncoming traffic in it."},{"da":"Den modkørende i midtervognbanen viser, at jeg ikke kan overhale traktoren lige nu.","fa":"خودروی روبه‌رو در خط وسط نشان می‌دهد که الان نمی‌توانم از تراکتور سبقت بگیرم.","ok":1,"eda":"Ja. Midtervognbanen kan bruges til overhaling fra begge retninger.","efa":"بله. خط وسط برای سبقت از هر دو جهت قابل استفاده است.","en":"The oncoming car in the middle lane shows that I cannot overtake the tractor right now.","een":"Yes. The middle lane can be used for overtaking from both directions."}]},{"id":5072,"img":"newq-art/5072.png","c":"7.19","sda":"Du vil parkere i vejkanten på en mørk vej uden for byen om natten. Hvilke lygter skal være tændt, når bilen holder der?","sfa":"می‌خواهید شب کنار جاده‌ای تاریک بیرون از شهر پارک کنید. وقتی خودرو آن‌جا ایستاده، کدام چراغ‌ها باید روشن باشند؟","sen":"You want to park at the edge of a dark road outside town at night. Which lights must be on while the car is parked there?","st":[{"da":"Nærlyset, så modkørende kan se mig tydeligt.","fa":"نور پایین، تا رانندگان روبه‌رو مرا واضح ببینند.","ok":0,"eda":"Nej. Andre lygter end positionslys, baglygter og nummerpladelys må ikke holdes tændt på en holdende bil.","efa":"خیر. در خودروی ایستاده، چراغی جز چراغ موقعیت، چراغ‌های عقب و چراغ پلاک نباید روشن بماند.","en":"The dipped beam, so that oncoming drivers can see me clearly.","een":"No. Lights other than the position lights, rear lights and number-plate light must not be kept on in a standing car."},{"da":"Positionslys (parkeringslys).","fa":"چراغ‌های موقعیت (چراغ پارک).","ok":1,"eda":"Ja. I lygtetændingstiden skal en bil, der holder på vejen, have positionslys, baglygter og nummerpladelys tændt.","efa":"بله. در زمان روشن کردن چراغ‌ها، خودرویی که در جاده ایستاده باید چراغ موقعیت، چراغ‌های عقب و چراغ پلاک را روشن داشته باشد.","en":"Position lights (parking lights).","een":"Yes. During lighting-up time a car standing on the road must have its position lights, rear lights and number-plate light on."},{"da":"Nummerpladelygten.","fa":"چراغ پلاک.","ok":1,"eda":"Ja. Nummerpladelygten hører med til de lygter, der skal være tændt.","efa":"بله. چراغ پلاک جزو چراغ‌هایی است که باید روشن باشند.","en":"The number-plate light.","een":"Yes. The number-plate light is one of the lights that must be on."},{"da":"Baglygterne.","fa":"چراغ‌های عقب.","ok":1,"eda":"Ja. Baglygterne viser dem, der kommer bagfra, at bilen holder der.","efa":"بله. چراغ‌های عقب به کسانی که از پشت می‌آیند نشان می‌دهند خودرو آن‌جاست.","en":"The rear lights.","een":"Yes. The rear lights show those coming from behind that the car is there."}]},{"id":5073,"img":"newq-art/5073.png","c":"7.19","sda":"Du kører på en godt oplyst gade i byen om aftenen. Hvilket lys bruger du?","sfa":"عصر در خیابانی پرنور در شهر می‌رانید. از کدام چراغ استفاده می‌کنید؟","sen":"You are driving on a well-lit street in town in the evening. Which lights do you use?","st":[{"da":"Tågeforlygter, fordi det er mørkt.","fa":"چراغ‌های مه‌شکن جلو، چون تاریک است.","ok":0,"eda":"Nej. I mørke må tågelygter kun bruges i tåge eller under kraftig nedbør.","efa":"خیر. در تاریکی، چراغ مه‌شکن فقط در مه یا بارش شدید مجاز است.","en":"Front fog lights, because it is dark.","een":"No. In the dark, fog lights may only be used in fog or heavy precipitation."},{"da":"Kun positionslys.","fa":"فقط چراغ‌های موقعیت.","ok":0,"eda":"Nej. Under kørsel er positionslys ikke nok; du skal have nærlys.","efa":"خیر. هنگام رانندگی چراغ موقعیت کافی نیست؛ باید نور پایین روشن باشد.","en":"Only the position lights.","een":"No. Position lights are not enough while driving; you must have dipped beam."},{"da":"Fjernlys.","fa":"نور بالا.","ok":0,"eda":"Nej. Fjernlys er forbudt på en godt oplyst vej.","efa":"خیر. نور بالا در جاده‌ی پرنور ممنوع است.","en":"High beam.","een":"No. High beam is forbidden on a well-lit road."},{"da":"Nærlys.","fa":"نور پایین.","ok":1,"eda":"Ja. Fjernlys må ikke bruges på en tilstrækkeligt oplyst vej; så skal du bruge nærlys.","efa":"بله. در جاده‌ی به اندازه‌ی کافی روشن، نور بالا مجاز نیست و باید از نور پایین استفاده کنید.","en":"Dipped beam.","een":"Yes. High beam must not be used on a sufficiently lit road; then you must use dipped beam."}]},{"id":5074,"img":"newq-art/5074.png","c":"7.19","sda":"Du kører i mørke bag en anden bil. Hvilket lys bruger du?","sfa":"در تاریکی پشت خودروی دیگری می‌رانید. از کدام چراغ استفاده می‌کنید؟","sen":"You are driving behind another car in the dark. Which lights do you use?","st":[{"da":"Nærlys, fordi fjernlyset kan blænde føreren foran.","fa":"نور پایین، چون نور بالا می‌تواند راننده‌ی جلویی را خیره کند.","ok":1,"eda":"Ja. Fjernlys må ikke bruges, når du kører efter en, der kan blive blændet.","efa":"بله. وقتی پشت کسی می‌رانید که ممکن است خیره شود، نباید از نور بالا استفاده کنید.","en":"Dipped beam, because the high beam can dazzle the driver ahead.","een":"Yes. High beam must not be used when you are following someone who could be dazzled."},{"da":"Fjernlyset kan blænde gennem bilens spejle.","fa":"نور بالا می‌تواند از طریق آینه‌های خودرو خیره کند.","ok":1,"eda":"Ja. Spejlene kaster dit lys ind i øjnene på føreren foran.","efa":"بله. آینه‌ها نور شما را به چشم راننده‌ی جلویی می‌اندازند.","en":"The high beam can dazzle through the car's mirrors.","een":"Yes. The mirrors throw your light into the eyes of the driver ahead."},{"da":"Fjernlys, så jeg kan se længere frem.","fa":"نور بالا، تا جلوتر را ببینم.","ok":0,"eda":"Nej. Fjernlyset blænder føreren foran gennem spejlene.","efa":"خیر. نور بالا از طریق آینه‌ها راننده‌ی جلویی را خیره می‌کند.","en":"High beam, so that I can see further ahead.","een":"No. The high beam dazzles the driver ahead through the mirrors."}]},{"id":5075,"img":"newq-art/5075.png","c":"7.16","sda":"Hvem må køre på motorvejen?","sfa":"چه کسانی می‌توانند در بزرگراه رانندگی کنند؟","sen":"Who may drive on the motorway?","st":[{"da":"Motorkøretøjer, der kan og må køre mindst 50 km/t.","fa":"وسایل موتوری‌ای که بتوانند و اجازه داشته باشند دست‌کم ۵۰ کیلومتر بر ساعت بروند.","ok":1,"eda":"Ja. Motorvejen er forbeholdt motorkøretøjer, der på vandret vej kan og må køre mindst 50 km/t.","efa":"بله. بزرگراه مخصوص وسایل موتوری‌ای است که در جاده‌ی هموار بتوانند و اجازه داشته باشند دست‌کم ۵۰ کیلومتر بر ساعت بروند.","en":"Motor vehicles that can and may drive at least 50 km/h.","een":"Yes. The motorway is reserved for motor vehicles that can and may do at least 50 km/h on level road."},{"da":"Alle motorkøretøjer, uanset hvor hurtigt de kan køre.","fa":"همه‌ی وسایل موتوری، هر قدر هم سرعتشان باشد.","ok":0,"eda":"Nej. Et motorkøretøj, der ikke kan eller ikke må køre mindst 50 km/t, må ikke bruge motorvejen.","efa":"خیر. وسیله‌ی موتوری‌ای که نتواند یا اجازه نداشته باشد دست‌کم ۵۰ کیلومتر بر ساعت برود، نباید از بزرگراه استفاده کند.","en":"All motor vehicles, however fast they can go.","een":"No. A motor vehicle that cannot or may not do at least 50 km/h must not use the motorway."},{"da":"En lille knallert, der højst kører 30 km/t.","fa":"موپد کوچکی که حداکثر ۳۰ کیلومتر بر ساعت می‌رود.","ok":0,"eda":"Nej. Den kan ikke køre 50 km/t og må derfor ikke køre på motorvejen.","efa":"خیر. نمی‌تواند ۵۰ کیلومتر بر ساعت برود، پس اجازه‌ی رانندگی در بزرگراه ندارد.","en":"A small moped that does at most 30 km/h.","een":"No. It cannot do 50 km/h and therefore may not drive on the motorway."},{"da":"Cyklister, hvis de holder i nødsporet.","fa":"دوچرخه‌سواران، اگر در شانه‌ی اضطراری بمانند.","ok":0,"eda":"Nej. Cyklister må ikke færdes på motorvejen.","efa":"خیر. دوچرخه‌سواران اجازه‌ی رفت‌وآمد در بزرگراه را ندارند.","en":"Cyclists, if they keep to the hard shoulder.","een":"No. Cyclists must not use the motorway."}]},{"id":5076,"img":"newq-art/5076.png","c":"7.16","sda":"Du har lige kørt forbi den frakørsel, du skulle have taget. Hvad gør du?","sfa":"همین الان از خروجی‌ای که باید می‌گرفتید رد شده‌اید. چه می‌کنید؟","sen":"You have just driven past the exit you should have taken. What do you do?","st":[{"da":"Jeg standser i nødsporet og ser på kortet, hvor jeg skal køre.","fa":"در شانه‌ی اضطراری می‌ایستم و روی نقشه نگاه می‌کنم کجا بروم.","ok":0,"eda":"Nej. På motorvejen må du kun standse på de anviste parkerings- og rastepladser eller ved en nødtelefon for at bruge den.","efa":"خیر. در بزرگراه فقط در پارکینگ‌ها و استراحتگاه‌های تعیین‌شده، یا کنار تلفن اضطراری برای استفاده از آن، می‌توانید بایستید.","en":"I stop on the hard shoulder and look at the map to see where to go.","een":"No. On the motorway you may only stop at the designated parking and rest areas, or at an emergency phone in order to use it."},{"da":"Jeg kører videre til den næste frakørsel.","fa":"تا خروجی بعدی ادامه می‌دهم.","ok":1,"eda":"Ja. Du må hverken bakke eller vende på motorvejen; brug den næste frakørsel.","efa":"بله. در بزرگراه نه می‌توانید دنده‌عقب بروید و نه دور بزنید؛ از خروجی بعدی استفاده کنید.","en":"I drive on to the next exit.","een":"Yes. You may neither reverse nor turn round on the motorway; use the next exit."},{"da":"Jeg bakker tilbage i nødsporet til frakørslen.","fa":"در شانه‌ی اضطراری دنده‌عقب تا خروجی برمی‌گردم.","ok":0,"eda":"Nej. Det er forbudt at bakke på motorvejen og på dens til- og frakørselsveje.","efa":"خیر. دنده‌عقب رفتن در بزرگراه و راه‌های ورودی و خروجی آن ممنوع است.","en":"I reverse back along the hard shoulder to the exit.","een":"No. Reversing is forbidden on the motorway and on its slip roads."},{"da":"Jeg vender gennem en åbning i midterrabatten.","fa":"از شکافی در جداکننده‌ی وسط دور می‌زنم.","ok":0,"eda":"Nej. Kørsel over midterrabatten eller gennem åbninger i den er ikke tilladt.","efa":"خیر. رد شدن از روی جداکننده‌ی وسط یا از شکاف‌های آن مجاز نیست.","en":"I turn round through a gap in the central reservation.","een":"No. Driving over the central reservation or through gaps in it is not allowed."}]},{"id":5077,"img":"newq-art/5077.png","c":"7.16","sda":"Du kører bil med trailer på en motorvej med tre vognbaner i din retning. Vogntoget er over 7 m langt. Hvad gælder?","sfa":"با خودرو و تریلر در بزرگراهی با سه خط در جهت خودتان رانندگی می‌کنید. طول مجموعه بیش از ۷ متر است. چه قاعده‌ای برقرار است؟","sen":"You are driving a car with a trailer on a motorway with three lanes in your direction. The combination is more than 7 m long. What applies?","st":[{"da":"Med trailer må jeg køre 130 km/t, når vejen er fri.","fa":"با تریلر وقتی جاده خالی است، می‌توانم ۱۳۰ کیلومتر بر ساعت بروم.","ok":0,"eda":"Nej. Bil med trailer må højst køre 80 km/t, på motorvej dog 100 km/t, hvis vogntoget opfylder betingelserne for det.","efa":"خیر. خودرو با تریلر حداکثر ۸۰ کیلومتر بر ساعت می‌تواند برود؛ در بزرگراه اگر مجموعه شرایطش را داشته باشد، ۱۰۰.","en":"With a trailer I may drive at 130 km/h when the road is clear.","een":"No. A car with a trailer may drive at most 80 km/h, though 100 km/h on the motorway if the combination meets the conditions for it."},{"da":"Jeg må kun bruge en af de to vognbaner længst til højre.","fa":"فقط می‌توانم از یکی از دو خط سمت راست استفاده کنم.","ok":1,"eda":"Ja. Vogntog, der er over 7 m lange, må på en motorvej med tre eller flere vognbaner i samme retning kun bruge de to vognbaner længst til højre.","efa":"بله. در بزرگراهی با سه خط یا بیشتر در یک جهت، مجموعه‌های بلندتر از ۷ متر فقط می‌توانند از دو خط سمت راست استفاده کنند.","en":"I may only use one of the two lanes furthest to the right.","een":"Yes. Combinations longer than 7 m may only use the two right-hand lanes on a motorway with three or more lanes in the same direction."},{"da":"Reglen om vognbanerne gælder kun for lastbiler.","fa":"قاعده‌ی خط‌ها فقط برای کامیون‌هاست.","ok":0,"eda":"Nej. Den gælder både biler med en tilladt totalvægt over 3,5 t og vogntog, der er over 7 m lange.","efa":"خیر. هم برای خودروهای با وزن کل مجاز بالای ۳٫۵ تن و هم برای مجموعه‌های بلندتر از ۷ متر است.","en":"The lane rule only applies to lorries.","een":"No. It applies both to vehicles with a permitted total weight over 3.5 t and to combinations longer than 7 m."},{"da":"Jeg må bruge vognbanen længst til venstre, når jeg overhaler varevognen.","fa":"وقتی از ون سبقت می‌گیرم، می‌توانم از چپ‌ترین خط استفاده کنم.","ok":0,"eda":"Nej. Forbuddet gælder også, når du vil overhale; her må du blive bag varevognen.","efa":"خیر. این ممنوعیت هنگام سبقت هم برقرار است؛ این‌جا باید پشت ون بمانید.","en":"I may use the left-hand lane when I overtake the van.","een":"No. The ban applies when you want to overtake too; here you must stay behind the van."}]},{"id":5078,"img":"newq-art/5078.png","c":"6.2","sda":"Din bil er gået i stå lige efter et skarpt sving, og du kan ikke flytte den med det samme. Hvad gør du?","sfa":"خودروی شما درست بعد از یک پیچ تند خراب شده و نمی‌توانید فوراً جابه‌جایش کنید. چه می‌کنید؟","sen":"Your car has broken down just after a sharp bend, and you cannot move it straight away. What do you do?","st":[{"da":"Jeg tænder havariblinket.","fa":"چراغ خطر را روشن می‌کنم.","ok":1,"eda":"Ja. Havariblinket advarer de andre trafikanter om, at bilen holder der.","efa":"بله. چراغ خطر به دیگران هشدار می‌دهد که خودرو آن‌جا ایستاده است.","en":"I switch on the hazard lights.","een":"Yes. The hazard lights warn other road users that the car is standing there."},{"da":"Jeg stiller advarselstrekanten op før svinget, så de bagfrakommende bliver advaret i god tid.","fa":"مثلث خطر را پیش از پیچ می‌گذارم تا کسانی که از پشت می‌آیند به موقع باخبر شوند.","ok":1,"eda":"Ja. Trekanten skal stå sådan, at de, der nærmer sig, bliver advaret i god tid; her skjuler svinget bilen.","efa":"بله. مثلث باید طوری باشد که نزدیک‌شوندگان به موقع باخبر شوند؛ این‌جا پیچ خودرو را پنهان کرده است.","en":"I put up the warning triangle before the bend, so that those coming from behind are warned in good time.","een":"Yes. The triangle must stand so that those approaching are warned in good time; here the bend hides the car."},{"da":"Havariblinket er nok, så advarselstrekanten kan blive i bagagerummet.","fa":"چراغ خطر کافی است، پس مثلث خطر می‌تواند در صندوق بماند.","ok":0,"eda":"Nej. En bil, der holder til fare og ikke kan fjernes straks, skal afmærkes med en advarselstrekant.","efa":"خیر. خودرویی که جای خطرناکی ایستاده و نمی‌شود فوراً جابه‌جایش کرد، باید با مثلث خطر مشخص شود.","en":"The hazard lights are enough, so the warning triangle can stay in the boot.","een":"No. A car that stands where it is a danger and cannot be removed at once must be marked with a warning triangle."},{"da":"Jeg sørger for at få bilen flyttet hurtigst muligt.","fa":"ترتیبی می‌دهم که خودرو هر چه زودتر جابه‌جا شود.","ok":1,"eda":"Ja. Et køretøj, der holder til fare, skal fjernes snarest muligt.","efa":"بله. وسیله‌ای که جای خطرناکی ایستاده، باید هر چه زودتر برداشته شود.","en":"I make sure the car is moved as quickly as possible.","een":"Yes. A vehicle standing where it is a danger must be removed as soon as possible."}]},{"id":5079,"img":"newq-art/5079.png","c":"6.2","sda":"Du har grønt lys, men politibetjenten i krydset giver dig tegn til at standse. Hvad gør du?","sfa":"چراغ شما سبز است، ولی مأمور پلیس در تقاطع به شما علامت ایست می‌دهد. چه می‌کنید؟","sen":"You have a green light, but the police officer in the junction signals you to stop. What do you do?","st":[{"da":"Politiets anvisninger går også forud for færdselstavler og afmærkning.","fa":"دستور پلیس بر تابلوها و خط‌کشی‌ها هم مقدم است.","ok":1,"eda":"Ja. Anvisninger fra politiet skal efterkommes før alle andre anvisninger og før færdselsreglerne.","efa":"بله. دستور پلیس پیش از همه‌ی علائم دیگر و پیش از قوانین عمومی رانندگی باید اجرا شود.","en":"The police's directions also take precedence over road signs and markings.","een":"Yes. Directions from the police must be obeyed before all other directions and before the traffic rules."},{"da":"Jeg kører, fordi jeg har grønt lys.","fa":"حرکت می‌کنم، چون چراغم سبز است.","ok":0,"eda":"Nej. Politiets tegn går forud for lyssignalet.","efa":"خیر. علامت پلیس بر چراغ راهنمایی مقدم است.","en":"I drive on because I have a green light.","een":"No. The police officer's signal takes precedence over the traffic light."},{"da":"Jeg skal kun følge betjenten, hvis lyssignalet er slukket.","fa":"فقط وقتی چراغ‌ها خاموش‌اند باید از مأمور پیروی کنم.","ok":0,"eda":"Nej. Politiets anvisninger gælder, uanset hvad lyssignalet viser.","efa":"خیر. دستور پلیس، هر رنگی که چراغ نشان دهد، معتبر است.","en":"I only have to follow the officer if the traffic lights are switched off.","een":"No. The police's directions apply whatever the traffic light shows."},{"da":"Jeg standser, fordi politiets anvisninger går forud for lyssignalet.","fa":"می‌ایستم، چون دستور پلیس بر چراغ راهنمایی مقدم است.","ok":1,"eda":"Ja. Trafikanter skal følge politiets anvisninger, og de skal efterkommes forud for lyssignaler, tavler og afmærkning.","efa":"بله. کاربران راه باید از دستور پلیس پیروی کنند و این دستور بر چراغ، تابلو و خط‌کشی مقدم است.","en":"I stop, because the police's directions take precedence over the traffic light.","een":"Yes. Road users must follow the police's directions, and these must be obeyed before traffic lights, signs and markings."}]},{"id":5080,"img":"newq-art/5080.png","c":"6.2","sda":"Bag dig kommer en ambulance med blå blink og sirene. Hvad gør du?","sfa":"از پشت سر شما آمبولانسی با چراغ آبی چشمک‌زن و آژیر می‌آید. چه می‌کنید؟","sen":"An ambulance with flashing blue lights and siren is coming up behind you. What do you do?","st":[{"da":"Jeg bremser hårdt og standser midt på vejen.","fa":"محکم ترمز می‌کنم و وسط جاده می‌ایستم.","ok":0,"eda":"Nej. Midt på vejen spærrer du for ambulancen, og en pludselig opbremsning kan give en påkørsel.","efa":"خیر. وسط جاده راه آمبولانس را می‌بندید و ترمز ناگهانی ممکن است باعث تصادف شود.","en":"I brake hard and stop in the middle of the road.","een":"No. In the middle of the road you block the ambulance, and sudden braking can cause a collision."},{"da":"Jeg øger farten, så ambulancen ikke skal vente på mig.","fa":"سرعتم را زیاد می‌کنم تا آمبولانس منتظر من نماند.","ok":0,"eda":"Nej. Du skal give plads, ikke køre om kap med ambulancen.","efa":"خیر. باید جا باز کنید، نه این‌که با آمبولانس مسابقه بدهید.","en":"I speed up so that the ambulance does not have to wait for me.","een":"No. You must make room, not race the ambulance."},{"da":"Jeg kører ind til højre og standser om nødvendigt.","fa":"به سمت راست می‌کشم و در صورت لزوم می‌ایستم.","ok":1,"eda":"Ja. Kørende skal om nødvendigt standse for udrykningskøretøjet.","efa":"بله. رانندگان باید در صورت لزوم برای خودروی امدادی بایستند.","en":"I pull over to the right and stop if necessary.","een":"Yes. Drivers must stop for the emergency vehicle if necessary."},{"da":"Jeg gør i god tid plads, så ambulancen kan komme forbi.","fa":"به موقع جا باز می‌کنم تا آمبولانس رد شود.","ok":1,"eda":"Ja. Andre trafikanter skal i god tid holde vejen åben for et køretøj under udrykning.","efa":"بله. دیگران باید به موقع راه را برای خودروی امدادی در مأموریت باز کنند.","en":"I make room in good time so that the ambulance can get past.","een":"Yes. Other road users must keep the road open in good time for a vehicle on an emergency call."}]},{"id":5081,"img":"newq-art/5081.png","c":"7.15","sda":"Du vil køre ind i rundkørslen og fortsætte ligeud. Hvad gælder?","sfa":"می‌خواهید وارد میدان شوید و مستقیم ادامه دهید. چه قاعده‌ای برقرار است؟","sen":"You want to enter the roundabout and carry straight on. What applies?","st":[{"da":"Jeg har ubetinget vigepligt for bilen, der allerede kører i rundkørslen.","fa":"باید بی‌قیدوشرط به خودرویی که در میدان است راه بدهم.","ok":1,"eda":"Ja. Vigepligtstavlen og hajtænderne betyder, at du har ubetinget vigepligt for dem, der kører i rundkørslen.","efa":"بله. تابلوی رعایت حق تقدم و دندان‌کوسه یعنی باید بی‌قیدوشرط به کسانی که در میدان‌اند راه بدهید.","en":"I must give way unconditionally to the car already driving in the roundabout.","een":"Yes. The give-way sign and the shark teeth mean that you must give way unconditionally to those driving in the roundabout."},{"da":"Jeg skal blinke til venstre, når jeg kører ind i rundkørslen.","fa":"هنگام ورود به میدان باید راهنمای چپ بزنم.","ok":0,"eda":"Nej. Skal du ligeud, behøver du ikke blinke, når du kører ind; du blinker til højre, før du kører ud.","efa":"خیر. اگر مستقیم می‌روید، لازم نیست هنگام ورود راهنما بزنید؛ پیش از خروج راهنمای راست می‌زنید.","en":"I must signal left when I enter the roundabout.","een":"No. If you are going straight on, you need not signal as you enter; you signal right before you leave."},{"da":"Bilen i rundkørslen skal holde tilbage for mig, fordi jeg kommer fra højre.","fa":"خودروی داخل میدان باید به من راه بدهد، چون از سمت راست می‌آیم.","ok":0,"eda":"Nej. Højrereglen gælder ikke her, fordi tavlen og hajtænderne giver dig ubetinget vigepligt.","efa":"خیر. قاعده‌ی دست راست این‌جا اعمال نمی‌شود، چون تابلو و دندان‌کوسه شما را مکلف به راه دادن بی‌قیدوشرط می‌کنند.","en":"The car in the roundabout must give way to me because I am coming from the right.","een":"No. The right-hand rule does not apply here, because the sign and the shark teeth make you give way unconditionally."},{"da":"Jeg har også ubetinget vigepligt for cyklisten i rundkørslen.","fa":"به دوچرخه‌سوار داخل میدان هم باید بی‌قیدوشرط راه بدهم.","ok":1,"eda":"Ja. Vigepligten gælder alle, der kører i rundkørslen, også cyklister.","efa":"بله. وظیفه‌ی راه دادن برای همه‌ی کسانی است که در میدان‌اند، دوچرخه‌سواران هم.","en":"I must also give way unconditionally to the cyclist in the roundabout.","een":"Yes. The duty to give way applies to everyone driving in the roundabout, cyclists too."}]},{"id":5082,"img":"newq-art/5082.png","c":"7.15","sda":"Du skal ud ved den næste vej. En cyklist i yderkanten af rundkørslen skal videre rundt. Hvordan forholder du dig?","sfa":"می‌خواهید از خیابان بعدی خارج شوید. دوچرخه‌سواری در لبه‌ی بیرونی میدان می‌خواهد دور را ادامه دهد. چه می‌کنید؟","sen":"You are leaving at the next road. A cyclist at the outer edge of the roundabout is going further round. What do you do?","st":[{"da":"Jeg giver tegn til højre, før jeg kører ud.","fa":"پیش از خروج راهنمای راست می‌زنم.","ok":1,"eda":"Ja. At køre ud af rundkørslen er et højresving, og du skal give tegn i god tid.","efa":"بله. خروج از میدان گردش به راست است و باید به موقع راهنما بزنید.","en":"I signal right before I leave.","een":"Yes. Leaving the roundabout is a right turn, and you must signal in good time."},{"da":"Jeg holder tilbage for cyklisten, der skal videre rundt.","fa":"به دوچرخه‌سواری که دور را ادامه می‌دهد راه می‌دهم.","ok":1,"eda":"Ja. Når du svinger til højre ud af rundkørslen, må du ikke være til ulempe for cyklister, der kører videre.","efa":"بله. وقتی برای خروج از میدان به راست می‌پیچید، نباید مزاحم دوچرخه‌سوارانی شوید که ادامه می‌دهند.","en":"I give way to the cyclist who is going further round.","een":"Yes. When you turn right out of the roundabout, you must not inconvenience cyclists who carry on."},{"da":"Jeg kigger over højre skulder efter cyklister, før jeg kører ud.","fa":"پیش از خروج از روی شانه‌ی راست دوچرخه‌سواران را نگاه می‌کنم.","ok":1,"eda":"Ja. Cyklister kan være i din blinde vinkel i højre side.","efa":"بله. دوچرخه‌سواران ممکن است در نقطه‌ی کور سمت راست شما باشند.","en":"I look over my right shoulder for cyclists before I leave.","een":"Yes. Cyclists may be in your blind spot on the right."},{"da":"Cyklisten skal holde tilbage for mig, fordi jeg blinker.","fa":"دوچرخه‌سوار باید به من راه بدهد، چون راهنما زده‌ام.","ok":0,"eda":"Nej. Blinklyset giver dig ikke forkørselsret.","efa":"خیر. راهنما به شما حق تقدم نمی‌دهد.","en":"The cyclist must give way to me because I am signalling.","een":"No. The indicator does not give you the right of way."}]},{"id":5083,"img":"newq-art/5083.png","c":"7.8","sda":"Du kører med trailer uden for byen bag en lastbil. Hvilken afstand holder du til lastbilen?","sfa":"بیرون از شهر با تریلر پشت یک کامیون می‌رانید. چه فاصله‌ای با کامیون نگه می‌دارید؟","sen":"You are towing a trailer outside town behind a lorry. What distance do you keep to the lorry?","st":[{"da":"Så stor, at jeg ikke kører ind i lastbilen, hvis den bremser.","fa":"آن‌قدر که اگر کامیون ترمز کرد، به آن نخورم.","ok":1,"eda":"Ja. Afstanden til den forankørende skal være så stor, at der ikke er fare for påkørsel, hvis den standser eller sætter farten ned.","efa":"بله. فاصله با جلویی باید آن‌قدر باشد که اگر بایستد یا سرعتش را کم کند، خطر تصادف نباشد.","en":"Large enough that I will not run into the lorry if it brakes.","een":"Yes. The distance to the vehicle ahead must be such that there is no risk of a collision if it stops or slows down."},{"da":"Jeg lægger mig tæt bag lastbilen, så ingen kan køre ind foran mig.","fa":"نزدیک پشت کامیون می‌مانم تا کسی نتواند جلوی من بیاید.","ok":0,"eda":"Nej. Så kan de, der overhaler, ikke komme ind, og du har ikke plads til at bremse.","efa":"خیر. این‌طور سبقت‌گیرندگان جا ندارند و خودتان هم جای ترمز ندارید.","en":"I keep close behind the lorry so that nobody can pull in in front of me.","een":"No. Then those overtaking cannot pull in, and you have no room to brake."},{"da":"Så stor, at biler, der overhaler mig, uden fare kan komme ind mellem mig og lastbilen.","fa":"آن‌قدر که خودروهایی که از من سبقت می‌گیرند، بی‌خطر بتوانند بین من و کامیون جا بگیرند.","ok":1,"eda":"Ja. Køretøjer med en særlig hastighedsgrænse, fx bil med trailer, skal uden for byen holde så stor afstand til den forankørende, at overhalende kan køre ind imellem.","efa":"بله. وسایلی که محدودیت سرعت ویژه دارند، مثل خودرو با تریلر، بیرون از شهر باید آن‌قدر از جلویی فاصله بگیرند که سبقت‌گیرندگان بتوانند بینشان جا بگیرند.","en":"Large enough that cars overtaking me can pull in safely between me and the lorry.","een":"Yes. Vehicles with a special speed limit, such as a car with a trailer, must outside town keep such a distance to the vehicle ahead that overtakers can pull in between."},{"da":"Med trailer må jeg her højst køre 80 km/t.","fa":"با تریلر این‌جا حداکثر می‌توانم ۸۰ کیلومتر بر ساعت بروم.","ok":1,"eda":"Ja. Bil med trailer må højst køre 80 km/t uden for motorvej.","efa":"بله. خودرو با تریلر بیرون از بزرگراه حداکثر ۸۰ کیلومتر بر ساعت می‌تواند برود.","en":"With a trailer I may drive at most 80 km/h here.","een":"Yes. A car with a trailer may drive at most 80 km/h off the motorway."}]},{"id":5084,"img":"newq-art/5084.png","c":"7.8","sda":"En bil kører meget tæt bag dig. Hvordan forholder du dig?","sfa":"خودرویی خیلی نزدیک پشت سر شما می‌آید. چه می‌کنید؟","sen":"A car is driving very close behind you. What do you do?","st":[{"da":"Jeg kører ud mod midten af vejen, så bilen ikke kan overhale.","fa":"به سمت وسط جاده می‌روم تا خودرو نتواند سبقت بگیرد.","ok":0,"eda":"Nej. Du skal holde til højre og gøre det lettere, ikke sværere, at overhale dig.","efa":"خیر. باید سمت راست بمانید و سبقت گرفتن از خودتان را آسان‌تر کنید، نه سخت‌تر.","en":"I move out towards the middle of the road so that the car cannot overtake.","een":"No. You must keep right and make it easier, not harder, to overtake you."},{"da":"Jeg øger farten, så bilen bag mig får mere plads.","fa":"سرعتم را زیاد می‌کنم تا خودروی پشتی جای بیشتری داشته باشد.","ok":0,"eda":"Nej. Du skal ikke lade dig presse til at køre hurtigere, end det er sikkert og lovligt.","efa":"خیر. نباید بگذارید شما را وادار کنند تندتر از حد ایمن و مجاز برانید.","en":"I speed up so that the car behind me gets more room.","een":"No. You must not let yourself be pushed into driving faster than is safe and legal."},{"da":"Jeg bremser kort for at få bilen bag mig til at holde mere afstand.","fa":"کوتاه ترمز می‌کنم تا خودروی پشتی فاصله بگیرد.","ok":0,"eda":"Nej. Du må ikke bremse brat uden grund; det kan give en påkørsel bagfra.","efa":"خیر. نباید بی‌دلیل ناگهانی ترمز کنید؛ ممکن است از پشت به شما بزنند.","en":"I brake briefly to make the car behind keep more distance.","een":"No. You must not brake sharply without reason; it can cause a rear-end collision."},{"da":"Jeg holder ekstra god afstand til bilen foran, så jeg kan bremse roligt, hvis det bliver nødvendigt.","fa":"فاصله‌ی بیشتری با خودروی جلو نگه می‌دارم تا اگر لازم شد، آرام ترمز کنم.","ok":1,"eda":"Ja. Når du kan bremse blødt, får bilen bag dig mere tid til at reagere.","efa":"بله. وقتی بتوانید نرم ترمز کنید، خودروی پشتی وقت بیشتری برای واکنش دارد.","en":"I keep an extra good distance to the car ahead so that I can brake gently if it becomes necessary.","een":"Yes. When you can brake smoothly, the car behind you gets more time to react."}]},{"id":5085,"img":"newq-art/5085.png","c":"7.5","sda":"Du vil bakke ud fra din indkørsel. En høj hæk skjuler fortovet. Hvordan forholder du dig?","sfa":"می‌خواهید با دنده‌عقب از ورودی خانه‌تان بیرون بیایید. پرچین بلندی جلوی دید پیاده‌رو را گرفته است. چه می‌کنید؟","sen":"You want to reverse out of your driveway. A tall hedge hides the pavement. What do you do?","st":[{"da":"Jeg bakker meget langsomt og er klar til at standse.","fa":"خیلی آهسته دنده‌عقب می‌روم و آماده‌ی ایستادنم.","ok":1,"eda":"Ja. Før du bakker, skal du sikre dig, at det kan ske uden fare eller ulempe for andre; når du ikke kan se, må det kun gå meget langsomt.","efa":"بله. پیش از دنده‌عقب باید مطمئن شوید که برای دیگران خطر یا مزاحمتی ندارد؛ وقتی دید ندارید، فقط باید خیلی آهسته بروید.","en":"I reverse very slowly and am ready to stop.","een":"Yes. Before reversing you must make sure it can be done without danger or inconvenience to others; when you cannot see, you may only go very slowly."},{"da":"Bakkameraet viser alt, så jeg behøver ikke se mig omkring.","fa":"دوربین عقب همه‌چیز را نشان می‌دهد، پس لازم نیست اطرافم را نگاه کنم.","ok":0,"eda":"Nej. Kameraet viser ikke det hele, fx ikke det, der kommer fra siden bag hækken.","efa":"خیر. دوربین همه‌چیز را نشان نمی‌دهد، مثلاً آن‌چه از کنار و پشت پرچین می‌آید.","en":"The reversing camera shows everything, so I do not need to look around.","een":"No. The camera does not show everything, for example not what is coming from the side behind the hedge."},{"da":"Jeg skal holde tilbage for fodgængere på fortovet og for trafikken på vejen.","fa":"باید به عابران پیاده‌رو و به ترافیک خیابان راه بدهم.","ok":1,"eda":"Ja. Når du kører ud fra en ejendom over et fortov, skal du holde tilbage for de gående, og du har ubetinget vigepligt for de kørende.","efa":"بله. وقتی از یک ملک از روی پیاده‌رو بیرون می‌آیید، باید به عابران راه بدهید و بی‌قیدوشرط به رانندگان هم.","en":"I must give way to pedestrians on the pavement and to the traffic on the street.","een":"Yes. When you drive out of a property across a pavement, you must give way to pedestrians, and you must give way unconditionally to traffic."},{"da":"Fodgængerne skal vente, fordi jeg er i gang med at bakke.","fa":"عابران باید صبر کنند، چون من دارم دنده‌عقب می‌روم.","ok":0,"eda":"Nej. Du skal holde tilbage for de gående, når du kører over fortovet.","efa":"خیر. وقتی از روی پیاده‌رو رد می‌شوید، باید به عابران راه بدهید.","en":"The pedestrians must wait because I am already reversing.","een":"No. You must give way to pedestrians when you drive across the pavement."}]},{"id":5086,"img":"newq-art/5086.png","c":"5.2","sda":"Det er frostvejr, og vejen har været tør. Nu nærmer du dig en bro. Hvad skal du være opmærksom på?","sfa":"هوا یخبندان است و جاده تا این‌جا خشک بوده. حالا به یک پل نزدیک می‌شوید. به چه چیزی باید توجه کنید؟","sen":"There is frost, and the road has been dry. Now you are approaching a bridge. What should you be aware of?","st":[{"da":"Glatte veje er kun et problem, når der ligger sne.","fa":"جاده‌ی لغزنده فقط وقتی برف هست مشکل است.","ok":0,"eda":"Nej. Is kan være næsten usynlig på en vej uden sne.","efa":"خیر. یخ روی جاده‌ی بی‌برف تقریباً دیده نمی‌شود.","en":"Slippery roads are only a problem when there is snow.","een":"No. Ice can be almost invisible on a road without snow."},{"da":"Broer bliver først glatte længe efter resten af vejen.","fa":"پل‌ها خیلی دیرتر از بقیه‌ی جاده لغزنده می‌شوند.","ok":0,"eda":"Nej. Det er omvendt: broer bliver ofte glatte først.","efa":"خیر. برعکس است: پل‌ها اغلب زودتر لغزنده می‌شوند.","en":"Bridges only become slippery long after the rest of the road.","een":"No. It is the other way round: bridges often become slippery first."},{"da":"Broen kan være glat, selv om resten af vejen ikke er det.","fa":"پل ممکن است لغزنده باشد، حتی اگر بقیه‌ی جاده نباشد.","ok":1,"eda":"Ja. En bro køles ned både oven- og nedefra og kan derfor fryse til før resten af vejen.","efa":"بله. پل هم از بالا و هم از پایین سرد می‌شود و برای همین زودتر از بقیه‌ی جاده یخ می‌زند.","en":"The bridge may be slippery even if the rest of the road is not.","een":"Yes. A bridge is cooled from both above and below and can therefore freeze before the rest of the road."},{"da":"Jeg kan holde samme fart, fordi vejen har været tør.","fa":"می‌توانم با همان سرعت ادامه دهم، چون جاده خشک بوده.","ok":0,"eda":"Nej. Sænk farten før broen, så du ikke skal bremse eller dreje kraftigt på den.","efa":"خیر. پیش از پل سرعت را کم کنید تا مجبور نشوید روی آن محکم ترمز کنید یا فرمان بدهید.","en":"I can keep the same speed because the road has been dry.","een":"No. Slow down before the bridge so that you do not have to brake or steer hard on it."}]},{"id":5087,"img":"newq-art/5087.png","c":"4.5","sda":"En bold triller ud på vejen mellem to parkerede biler. Hvordan forholder du dig?","sfa":"توپی از میان دو خودروی پارک‌شده به جاده می‌غلتد. چه می‌کنید؟","sen":"A ball rolls out onto the road between two parked cars. What do you do?","st":[{"da":"Jeg bremser og er klar til at standse.","fa":"ترمز می‌کنم و آماده‌ی ایستادنم.","ok":1,"eda":"Ja. Du skal kunne standse, hvis der pludselig kommer nogen ud på vejen.","efa":"بله. باید بتوانید اگر کسی ناگهان وارد جاده شد، بایستید.","en":"I brake and am ready to stop.","een":"Yes. You must be able to stop if someone suddenly comes out onto the road."},{"da":"Der kan komme et barn løbende efter bolden.","fa":"ممکن است کودکی دنبال توپ بدود.","ok":1,"eda":"Ja. Børn tænker på bolden og ikke på trafikken.","efa":"بله. کودکان به توپ فکر می‌کنند، نه به ترافیک.","en":"A child may come running after the ball.","een":"Yes. Children think about the ball, not about the traffic."},{"da":"Jeg holder øje med, om der er flere børn mellem bilerne.","fa":"مراقبم که بچه‌های دیگری میان خودروها نباشند.","ok":1,"eda":"Ja. Hvor ét barn leger, kan der også være flere.","efa":"بله. جایی که یک کودک بازی می‌کند، ممکن است بچه‌های دیگری هم باشند.","en":"I watch out for more children between the cars.","een":"Yes. Where one child is playing, there may be more."},{"da":"Jeg dytter og kører videre med samme fart.","fa":"بوق می‌زنم و با همان سرعت ادامه می‌دهم.","ok":0,"eda":"Nej. Et barn, der løber efter en bold, reagerer måske ikke på hornet.","efa":"خیر. کودکی که دنبال توپ می‌دود، شاید به بوق واکنشی نشان ندهد.","en":"I sound the horn and drive on at the same speed.","een":"No. A child running after a ball may not react to the horn."}]},{"id":5088,"img":"newq-art/5088.png","c":"4.5","sda":"Cyklisten foran dig rækker venstre arm ud til siden. Hvad betyder det?","sfa":"دوچرخه‌سوار جلوی شما دست چپش را به پهلو دراز کرده است. یعنی چه؟","sen":"The cyclist in front of you holds the left arm out to the side. What does it mean?","st":[{"da":"Cyklisten vil svinge til højre.","fa":"دوچرخه‌سوار می‌خواهد به راست بپیچد.","ok":0,"eda":"Nej. Et højresving vises med højre arm.","efa":"خیر. گردش به راست با دست راست نشان داده می‌شود.","en":"The cyclist is going to turn right.","een":"No. A right turn is shown with the right arm."},{"da":"Cyklisten vil standse.","fa":"دوچرخه‌سوار می‌خواهد بایستد.","ok":0,"eda":"Nej. Den udstrakte venstre arm viser et venstresving, ikke en standsning.","efa":"خیر. دست دراز چپ گردش به چپ را نشان می‌دهد، نه ایستادن.","en":"The cyclist is going to stop.","een":"No. The outstretched left arm shows a left turn, not a stop."},{"da":"Cyklisten vil svinge til venstre.","fa":"دوچرخه‌سوار می‌خواهد به چپ بپیچد.","ok":1,"eda":"Ja. En arm strakt ud til venstre er cyklistens tegn til at svinge til venstre; vent med at overhale.","efa":"بله. دست دراز به چپ علامت گردش به چپ دوچرخه‌سوار است؛ برای سبقت صبر کنید.","en":"The cyclist is going to turn left.","een":"Yes. An arm stretched out to the left is the cyclist's signal for turning left; wait before overtaking."},{"da":"Cyklisten giver mig tegn til at overhale.","fa":"دوچرخه‌سوار به من علامت می‌دهد که سبقت بگیرم.","ok":0,"eda":"Nej. Cyklisten viser, hvad han selv vil gøre; overhal ikke, mens han svinger til venstre.","efa":"خیر. دوچرخه‌سوار نشان می‌دهد خودش چه می‌خواهد بکند؛ وقتی به چپ می‌پیچد، سبقت نگیرید.","en":"The cyclist is signalling me to overtake.","een":"No. The cyclist shows what he himself is going to do; do not overtake while he is turning left."}]},{"id":5089,"img":"newq-art/5089.png","c":"4.4","sda":"Hvad gælder om alkohol og bilkørsel?","sfa":"درباره‌ی الکل و رانندگی چه قاعده‌ای برقرار است؟","sen":"What applies to alcohol and driving?","st":[{"da":"Kaffe og frisk luft får promillen hurtigere ned.","fa":"قهوه و هوای تازه الکل خون را زودتر پایین می‌آورند.","ok":0,"eda":"Nej. Kun tiden får promillen ned; kroppen forbrænder alkohol i sit eget tempo.","efa":"خیر. فقط زمان الکل خون را پایین می‌آورد؛ بدن الکل را با سرعت خودش می‌سوزاند.","en":"Coffee and fresh air bring the level down faster.","een":"No. Only time brings the level down; the body burns alcohol at its own pace."},{"da":"De første 3 år efter mit første kørekort til bil må min promille ikke være over 0,2.","fa":"در ۳ سال اول پس از نخستین گواهینامه‌ی خودرو، الکل خونم نباید بیش از ۰٫۲ در هزار باشد.","ok":1,"eda":"Ja. Siden 1. juli 2025 er grænsen for nye bilister 0,20 promille i blodet (0,10 mg pr. liter udåndingsluft); ellers er den 0,50 promille.","efa":"بله. از ۱ ژوئیه‌ی ۲۰۲۵ حد راننده‌ی تازه‌کار ۰٫۲۰ در هزار در خون (۰٫۱۰ میلی‌گرم در هر لیتر هوای بازدم) است؛ برای بقیه ۰٫۵۰ در هزار.","en":"For the first 3 years after my first car licence my blood alcohol must not be over 0.2 per mille.","een":"Yes. Since 1 July 2025 the limit for new drivers is 0.20 per mille in the blood (0.10 mg per litre of exhaled air); otherwise it is 0.50 per mille."},{"da":"Alkohol gør min reaktionstid længere.","fa":"الکل زمان واکنش مرا طولانی‌تر می‌کند.","ok":1,"eda":"Ja. Selv lidt alkohol nedsætter din evne til at opfatte og reagere.","efa":"بله. حتی کمی الکل توانایی شما در دیدن و واکنش را کم می‌کند.","en":"Alcohol makes my reaction time longer.","een":"Yes. Even a little alcohol reduces your ability to notice and react."},{"da":"Jeg kan straffes, selv om min promille er under grænsen, hvis jeg ikke kan køre fuldt betryggende.","fa":"اگر نتوانم کاملاً ایمن رانندگی کنم، حتی با الکل کمتر از حد مجاز هم ممکن است مجازات شوم.","ok":1,"eda":"Ja. Det er forbudt at køre, når alkohol gør, at du ikke kan føre bilen på fuldt betryggende måde, uanset promillen.","efa":"بله. اگر الکل باعث شود نتوانید کاملاً ایمن رانندگی کنید، رانندگی ممنوع است، میزانش هر چه باشد.","en":"I can be punished even if my blood alcohol is under the limit if I cannot drive in a fully safe manner.","een":"Yes. It is forbidden to drive when alcohol means you cannot drive the car in a fully safe manner, whatever the level."}]},{"id":5090,"img":"newq-art/5090.png","c":"4.4","sda":"Du har høj feber og føler dig sløj, men du skal hente dit barn i børnehaven. Hvad gælder?","sfa":"تب بالایی دارید و حالتان خوب نیست، ولی باید فرزندتان را از مهدکودک بیاورید. چه قاعده‌ای برقرار است؟","sen":"You have a high temperature and feel unwell, but you need to pick up your child from the kindergarten. What applies?","st":[{"da":"Reglen gælder kun sygdomme, som lægen har skrevet ned.","fa":"این قاعده فقط درباره‌ی بیماری‌هایی است که پزشک ثبت کرده.","ok":0,"eda":"Nej. Det afgørende er, hvordan du har det, når du skal køre.","efa":"خیر. مهم این است که وقتی می‌خواهید رانندگی کنید، حالتان چطور است.","en":"The rule only applies to illnesses that the doctor has written down.","een":"No. What matters is how you feel when you are going to drive."},{"da":"Jeg må ikke køre, hvis jeg på grund af sygdom ikke kan køre på fuldt betryggende måde.","fa":"اگر به خاطر بیماری نتوانم کاملاً ایمن رانندگی کنم، نباید برانم.","ok":1,"eda":"Ja. Det er forbudt at køre, når sygdom, svækkelse, overanstrengelse eller mangel på søvn gør, at du ikke kan køre fuldt betryggende.","efa":"بله. اگر بیماری، ضعف، خستگی شدید یا کم‌خوابی نگذارد کاملاً ایمن برانید، رانندگی ممنوع است.","en":"I must not drive if, because of illness, I cannot drive in a fully safe manner.","een":"Yes. It is forbidden to drive when illness, weakness, exhaustion or lack of sleep means you cannot drive in a fully safe manner."},{"da":"Sygdom har kun betydning, hvis jeg også har drukket alkohol.","fa":"بیماری فقط وقتی مهم است که الکل هم خورده باشم.","ok":0,"eda":"Nej. Sygdom alene kan gøre det forbudt at køre.","efa":"خیر. بیماری به‌تنهایی می‌تواند رانندگی را ممنوع کند.","en":"Illness only matters if I have also been drinking alcohol.","een":"No. Illness alone can make it forbidden to drive."},{"da":"Jeg kan godt køre, hvis jeg åbner vinduet og kører langsomt.","fa":"اگر پنجره را باز کنم و آهسته برانم، می‌توانم رانندگی کنم.","ok":0,"eda":"Nej. Det ændrer ikke på, at du ikke er i stand til at køre sikkert.","efa":"خیر. این تغییری در این واقعیت نمی‌دهد که توان رانندگی ایمن ندارید.","en":"I can drive if I open the window and drive slowly.","een":"No. That does not change the fact that you are not fit to drive safely."}]},{"id":5091,"img":"newq-art/5091.png","c":"8.1","sda":"Din medicin har en rød advarselstrekant på pakningen. Hvad gælder?","sfa":"روی بسته‌ی داروی شما مثلث هشدار قرمز هست. چه قاعده‌ای برقرار است؟","sen":"Your medicine has a red warning triangle on the package. What applies?","st":[{"da":"Jeg må aldrig køre bil, mens jeg tager medicinen.","fa":"تا وقتی این دارو را مصرف می‌کنم، هرگز نباید رانندگی کنم.","ok":0,"eda":"Nej. I nogle tilfælde er det tilladt at køre, når medicinen tages som anvist; det afhænger af, hvordan den påvirker dig.","efa":"خیر. در برخی موارد اگر دارو طبق دستور مصرف شود، رانندگی مجاز است؛ بستگی دارد چه اثری روی شما بگذارد.","en":"I may never drive while I am taking the medicine.","een":"No. In some cases driving is allowed when the medicine is taken as directed; it depends on how it affects you."},{"da":"Medicin uden rød advarselstrekant kan aldrig påvirke min kørsel.","fa":"دارویی که مثلث قرمز ندارد، هرگز روی رانندگی‌ام اثر نمی‌گذارد.","ok":0,"eda":"Nej. Trafikfarlig medicin er ofte, men ikke altid, mærket med den røde trekant.","efa":"خیر. داروی خطرناک برای ترافیک اغلب، ولی نه همیشه، با مثلث قرمز مشخص شده است.","en":"Medicine without a red warning triangle can never affect my driving.","een":"No. Medicine that is dangerous in traffic is often, but not always, marked with the red triangle."},{"da":"Medicinen kan påvirke min evne til at køre bil sikkert.","fa":"این دارو ممکن است توانایی‌ام در رانندگی ایمن را تحت تأثیر قرار دهد.","ok":1,"eda":"Ja. Den røde trekant bruges på medicin, der kan være trafikfarlig.","efa":"بله. مثلث قرمز روی داروهایی است که ممکن است در ترافیک خطرناک باشند.","en":"The medicine may affect my ability to drive safely.","een":"Yes. The red triangle is used on medicine that can be dangerous in traffic."},{"da":"Jeg spørger min læge, om jeg kan køre bil, mens jeg tager medicinen.","fa":"از پزشکم می‌پرسم که آیا با مصرف این دارو می‌توانم رانندگی کنم.","ok":1,"eda":"Ja. Lægen kan vurdere, om medicinen gør det usikkert for dig at køre.","efa":"بله. پزشک می‌تواند بسنجد که آیا دارو رانندگی را برایتان ناایمن می‌کند.","en":"I ask my doctor whether I can drive while taking the medicine.","een":"Yes. The doctor can judge whether the medicine makes it unsafe for you to drive."}]},{"id":5092,"img":"newq-art/5092.png","c":"8.1","sda":"Du kører på motorvejen og bliver meget søvnig. Hvad gør du?","sfa":"در بزرگراه رانندگی می‌کنید و خیلی خواب‌آلود می‌شوید. چه می‌کنید؟","sen":"You are driving on the motorway and become very sleepy. What do you do?","st":[{"da":"Jeg kører hurtigere, så jeg hurtigere er fremme.","fa":"تندتر می‌رانم تا زودتر برسم.","ok":0,"eda":"Nej. Højere fart gør det endnu farligere at være træt.","efa":"خیر. سرعت بیشتر، خستگی را خطرناک‌تر می‌کند.","en":"I drive faster so that I arrive sooner.","een":"No. Higher speed makes being tired even more dangerous."},{"da":"Jeg kører ind på rastepladsen og holder pause, gerne med en kort lur.","fa":"وارد استراحتگاه می‌شوم و استراحت می‌کنم، ترجیحاً با یک چرت کوتاه.","ok":1,"eda":"Ja. Kun hvile og søvn hjælper mod træthed.","efa":"بله. فقط استراحت و خواب در برابر خستگی کمک می‌کند.","en":"I pull into the rest area and take a break, preferably with a short nap.","een":"Yes. Only rest and sleep help against tiredness."},{"da":"Jeg drikker en kop kaffe i bilen og kører videre uden pause.","fa":"در خودرو یک فنجان قهوه می‌خورم و بی‌استراحت ادامه می‌دهم.","ok":0,"eda":"Nej. Kaffe kan ikke erstatte hvile; du kan stadig falde i søvn bag rattet.","efa":"خیر. قهوه جای استراحت را نمی‌گیرد؛ هنوز ممکن است پشت فرمان خوابتان ببرد.","en":"I drink a cup of coffee in the car and drive on without a break.","een":"No. Coffee cannot replace rest; you may still fall asleep at the wheel."},{"da":"Jeg skruer op for musikken og åbner vinduet, så går det over.","fa":"صدای موسیقی را بلند می‌کنم و پنجره را باز می‌کنم، خوب می‌شوم.","ok":0,"eda":"Nej. Det hjælper højst et øjeblik; trætheden forsvinder ikke.","efa":"خیر. این حداکثر برای لحظه‌ای کمک می‌کند؛ خستگی از بین نمی‌رود.","en":"I turn the music up and open the window, and then it will pass.","een":"No. That helps for a moment at most; the tiredness does not go away."}]},{"id":5093,"img":"newq-art/5093.png","c":"8.1","sda":"Du holder for rødt lys, og din telefon ringer. Hvad gælder?","sfa":"پشت چراغ قرمز ایستاده‌اید و تلفنتان زنگ می‌زند. چه قاعده‌ای برقرار است؟","sen":"You are waiting at a red light, and your phone rings. What applies?","st":[{"da":"Forbuddet mod håndholdt telefon gælder også, mens jeg holder for rødt lys.","fa":"ممنوعیت تلفن دستی وقتی پشت چراغ قرمزم هم برقرار است.","ok":1,"eda":"Ja. At holde for rødt lys er stadig en del af kørslen.","efa":"بله. ایستادن پشت چراغ قرمز هنوز بخشی از رانندگی است.","en":"The ban on hand-held phones also applies while I am waiting at a red light.","een":"Yes. Waiting at a red light is still part of driving."},{"da":"Jeg kan ringe tilbage, når jeg har parkeret et sikkert sted.","fa":"وقتی جای امنی پارک کردم، می‌توانم تماس بگیرم.","ok":1,"eda":"Ja. Når du holder parkeret, er du ikke længere under kørsel.","efa":"بله. وقتی پارک کرده‌اید، دیگر در حال رانندگی نیستید.","en":"I can call back when I have parked in a safe place.","een":"Yes. When you are parked, you are no longer driving."},{"da":"Jeg må ikke tage telefonen i hånden og tale i den.","fa":"نباید تلفن را با دست بردارم و صحبت کنم.","ok":1,"eda":"Ja. Førere må under kørsel ikke bruge håndholdt telefon eller andre håndholdte kommunikationsapparater.","efa":"بله. رانندگان در حین رانندگی نباید از تلفن یا دیگر وسایل ارتباطی دستی استفاده کنند.","en":"I must not pick up the phone and talk on it holding it in my hand.","een":"Yes. Drivers must not use a hand-held phone or other hand-held communication devices while driving."},{"da":"Jeg må godt skrive en sms, når jeg kører langsomt i kø.","fa":"وقتی در ترافیک آهسته می‌رانم، می‌توانم پیامک بنویسم.","ok":0,"eda":"Nej. Forbuddet gælder al brug af håndholdt telefon under kørsel, også i kø.","efa":"خیر. ممنوعیت شامل هر نوع استفاده از تلفن دستی در حین رانندگی است، در ترافیک هم.","en":"I may write a text message when I am driving slowly in a queue.","een":"No. The ban covers all use of a hand-held phone while driving, in queues too."}]},{"id":5094,"img":"newq-art/5094.png","c":"3.2","sda":"Lastbilen foran dig vil svinge til højre. Hvad skal du være opmærksom på?","sfa":"کامیون جلوی شما می‌خواهد به راست بپیچد. به چه چیزی باید توجه کنید؟","sen":"The lorry in front of you is going to turn right. What should you be aware of?","st":[{"da":"Chaufføren kan have svært ved at se cyklisten ved siden af lastbilen.","fa":"راننده ممکن است دوچرخه‌سوار کنار کامیون را به‌سختی ببیند.","ok":1,"eda":"Ja. Lastbiler har store blinde vinkler, især i højre side.","efa":"بله. کامیون‌ها نقاط کور بزرگی دارند، به‌خصوص در سمت راست.","en":"The driver may find it hard to see the cyclist beside the lorry.","een":"Yes. Lorries have large blind spots, especially on the right-hand side."},{"da":"Lastbilen kan have brug for at trække ud mod venstre for at komme rundt i svinget.","fa":"کامیون ممکن است برای پیچیدن لازم داشته باشد اول کمی به چپ بکشد.","ok":1,"eda":"Ja. Lange køretøjer har brug for meget plads i sving, og baghjulene kører tættere på indersiden af svinget end forhjulene.","efa":"بله. وسایل بلند در پیچ جای زیادی لازم دارند و چرخ‌های عقب نزدیک‌تر از چرخ‌های جلو به داخل پیچ حرکت می‌کنند.","en":"The lorry may need to move out to the left to get round the turn.","een":"Yes. Long vehicles need a lot of room in turns, and the rear wheels run closer to the inside of the turn than the front wheels."},{"da":"Lastbilen kan svinge lige så skarpt som en personbil.","fa":"کامیون می‌تواند به تندی یک سواری بپیچد.","ok":0,"eda":"Nej. En lastbil er lang og har brug for et meget større sving.","efa":"خیر. کامیون بلند است و به پیچ خیلی بازتری نیاز دارد.","en":"The lorry can turn as sharply as a car.","een":"No. A lorry is long and needs a much wider turn."},{"da":"Jeg holder god afstand og kører ikke op i højre side af lastbilen.","fa":"فاصله‌ی خوبی نگه می‌دارم و از سمت راست کامیون جلو نمی‌روم.","ok":1,"eda":"Ja. I højre side af lastbilen kan du blive klemt, når den svinger.","efa":"بله. در سمت راست کامیون ممکن است هنگام پیچیدنش گیر بیفتید.","en":"I keep a good distance and do not drive up on the right-hand side of the lorry.","een":"Yes. On the right-hand side of the lorry you can get squeezed when it turns."}]},{"id":5095,"img":"newq-art/5095.png","c":"3.2","sda":"Du overvejer at overhale et langt vogntog på landevejen. Hvad gælder?","sfa":"در جاده‌ی بیرون شهر به سبقت از یک کامیون با تریلر بلند فکر می‌کنید. چه قاعده‌ای برقرار است؟","sen":"You are considering overtaking a long lorry combination on a country road. What applies?","st":[{"da":"Jeg kan regne med, at chaufføren sætter farten ned, når jeg overhaler.","fa":"می‌توانم مطمئن باشم که راننده هنگام سبقت من سرعتش را کم می‌کند.","ok":0,"eda":"Nej. Du skal selv sikre dig, at overhalingen kan ske uden fare; du kan ikke regne med hjælp fra chaufføren.","efa":"خیر. خودتان باید مطمئن شوید سبقت بی‌خطر است؛ نمی‌توانید روی کمک راننده حساب کنید.","en":"I can count on the driver slowing down when I overtake.","een":"No. You must make sure yourself that the overtaking can be done safely; you cannot count on help from the driver."},{"da":"Jeg lægger mig helt tæt bag vogntoget, så jeg er klar til at overhale.","fa":"کاملاً نزدیک پشت کامیون می‌مانم تا آماده‌ی سبقت باشم.","ok":0,"eda":"Nej. Tæt bag vogntoget kan du ikke se forbi det, og chaufføren kan ikke se dig.","efa":"خیر. نزدیک پشت کامیون نه شما جلو را می‌بینید، نه راننده شما را.","en":"I keep right up close behind the lorry so that I am ready to overtake.","een":"No. Close behind the lorry you cannot see past it, and the driver cannot see you."},{"da":"Luftsuget fra vogntoget kan rykke i min bil, når jeg kører forbi.","fa":"جریان هوای کامیون ممکن است هنگام عبور، خودروی مرا تکان دهد.","ok":1,"eda":"Ja. Hold godt fast i rattet og god afstand til siden.","efa":"بله. فرمان را محکم نگه دارید و از کنار فاصله‌ی خوبی بگیرید.","en":"The air pressure from the lorry may pull at my car as I pass.","een":"Yes. Hold the wheel firmly and keep a good distance to the side."},{"da":"Overhalingen tager længere tid end forbi en personbil, så den modkørende vognbane skal være fri over en længere strækning.","fa":"سبقت از آن بیشتر از سواری طول می‌کشد، پس خط مقابل باید در مسافت طولانی‌تری خالی باشد.","ok":1,"eda":"Ja. Jo længere køretøjet er, jo længere tid er du i den modkørende vognbane.","efa":"بله. هر چه وسیله بلندتر باشد، مدت بیشتری در خط مقابل می‌مانید.","en":"The overtaking takes longer than past a car, so the oncoming lane must be clear over a longer stretch.","een":"Yes. The longer the vehicle, the longer you are in the oncoming lane."}]},{"id":5096,"img":"newq-art/5096.png","c":"5.1","sda":"Vejen har én fælles kørebane i midten og kantbaner i begge sider. En bil kommer imod dig. Hvordan forholder du dig?","sfa":"جاده یک خط مشترک در وسط و خط‌های کناری در دو طرف دارد. خودرویی از روبه‌رو می‌آید. چه می‌کنید؟","sen":"The road has one shared driving lane in the middle and edge lanes on both sides. A car is coming towards you. What do you do?","st":[{"da":"Jeg kører midt på vejen og trækker kun ud i kantbanen, når der kommer en modkørende bil.","fa":"وسط جاده می‌رانم و فقط وقتی خودرویی از روبه‌رو می‌آید، به خط کناری می‌روم.","ok":1,"eda":"Ja. På en 2-minus-1-vej kører bilerne i midten; kantbanerne bruges kun til at vige for modkørende.","efa":"بله. در جاده‌ی «۲ منهای ۱» خودروها وسط می‌رانند و از خط‌های کناری فقط برای راه دادن به خودروی روبه‌رو استفاده می‌شود.","en":"I drive in the middle of the road and only move out into the edge lane when an oncoming car comes.","een":"Yes. On a 2-minus-1 road the cars drive in the middle; the edge lanes are only used to make way for oncoming traffic."},{"da":"Jeg kører hele tiden i kantbanen i højre side.","fa":"همیشه در خط کناری سمت راست می‌رانم.","ok":0,"eda":"Nej. Kantbanen er ikke din vognbane; du kører i midten.","efa":"خیر. خط کناری خط شما نیست؛ شما وسط می‌رانید.","en":"I drive in the edge lane on the right all the time.","een":"No. The edge lane is not your lane; you drive in the middle."},{"da":"Er cyklisten i kantbanen, når vi mødes, holder jeg tilbage og standser om nødvendigt.","fa":"اگر هنگام برخورد دوچرخه‌سوار در خط کناری باشد، صبر می‌کنم و در صورت لزوم می‌ایستم.","ok":1,"eda":"Ja. Kantbanen er for cyklister og gående; du må kun trække ud i den, når der er plads.","efa":"بله. خط کناری مال دوچرخه‌سواران و عابران است؛ فقط وقتی جا هست می‌توانید واردش شوید.","en":"If the cyclist is in the edge lane when we meet, I hold back and stop if necessary.","een":"Yes. The edge lane is for cyclists and pedestrians; you may only move out into it when there is room."},{"da":"Jeg sænker farten, fordi vejen er smal, og der kan komme modkørende.","fa":"سرعتم را کم می‌کنم، چون جاده باریک است و ممکن است خودرویی از روبه‌رو بیاید.","ok":1,"eda":"Ja. Vejen giver kun plads til én bil ad gangen i midten.","efa":"بله. جاده هر بار فقط برای یک خودرو در وسط جا دارد.","en":"I slow down because the road is narrow and oncoming traffic may come.","een":"Yes. The road only has room for one car at a time in the middle."}]},{"id":5097,"img":"newq-art/5097.png","c":"10.3","sda":"Hvad må du med et almindeligt kørekort til kategori B?","sfa":"با گواهینامه‌ی معمولی رده‌ی B چه کارهایی مجاز است؟","sen":"What may you do with an ordinary category B driving licence?","st":[{"da":"Køre en minibus med 12 passagerer, hvis den vejer under 3.500 kg.","fa":"رانندگی مینی‌بوس با ۱۲ مسافر، اگر وزنش کمتر از ۳٬۵۰۰ کیلوگرم باشد.","ok":0,"eda":"Nej. Med B må du højst have 8 passagerer, uanset vægten.","efa":"خیر. با B حداکثر ۸ مسافر مجاز است، وزن هر چه باشد.","en":"Drive a minibus with 12 passengers if it weighs under 3,500 kg.","een":"No. With B you may have at most 8 passengers, whatever the weight."},{"da":"Køre bil med en tilladt totalvægt på højst 3.500 kg.","fa":"رانندگی با خودرویی با وزن کل مجاز حداکثر ۳٬۵۰۰ کیلوگرم.","ok":1,"eda":"Ja. Kategori B gælder biler med en tilladt totalvægt på højst 3.500 kg.","efa":"بله. رده‌ی B برای خودروهایی با وزن کل مجاز حداکثر ۳٬۵۰۰ کیلوگرم است.","en":"Drive a car with a permitted total weight of at most 3,500 kg.","een":"Yes. Category B covers cars with a permitted total weight of at most 3,500 kg."},{"da":"Have højst 8 passagerer med ud over mig selv.","fa":"حداکثر ۸ مسافر به‌جز خودم سوار کنم.","ok":1,"eda":"Ja. Bilen må højst være indrettet til 8 personer ud over føreren.","efa":"بله. خودرو حداکثر برای ۸ نفر به‌جز راننده ساخته شده باشد.","en":"Carry at most 8 passengers besides myself.","een":"Yes. The car may be built for at most 8 people besides the driver."},{"da":"Trække en hvilken som helst trailer, så længe bilen er under 3.500 kg.","fa":"هر تریلری را بکشم، به شرط آن‌که خودرو کمتر از ۳٬۵۰۰ کیلوگرم باشد.","ok":0,"eda":"Nej. Med B må traileren højst have en tilladt totalvægt på 750 kg, ellers må bil og trailer tilsammen højst veje 3.500 kg.","efa":"خیر. با B وزن کل مجاز تریلر حداکثر ۷۵۰ کیلوگرم است؛ وگرنه مجموع خودرو و تریلر حداکثر ۳٬۵۰۰ کیلوگرم.","en":"Tow any trailer at all as long as the car is under 3,500 kg.","een":"No. With B the trailer's permitted total weight may be at most 750 kg; otherwise the car and trailer together may weigh at most 3,500 kg."}]},{"id":5098,"img":"newq-art/5098.png","c":"7.10","sda":"Du kører forbi denne tavle ind i et område. Hvad gælder?","sfa":"از کنار این تابلو وارد یک محدوده می‌شوید. چه قاعده‌ای برقرار است؟","sen":"You pass this sign into an area. What applies?","st":[{"da":"Jeg må kun parkere på de særligt afmærkede pladser.","fa":"فقط در جاهای مخصوص علامت‌گذاری‌شده می‌توانم پارک کنم.","ok":1,"eda":"Ja. Parkering må ikke ske uden for særligt afmærkede pladser.","efa":"بله. پارک بیرون از جاهای مخصوص علامت‌گذاری‌شده مجاز نیست.","en":"I may only park in the specially marked places.","een":"Yes. Parking must not take place outside specially marked places."},{"da":"Børn må lege på hele vejens bredde.","fa":"بچه‌ها می‌توانند در تمام عرض خیابان بازی کنند.","ok":1,"eda":"Ja. Det er tilladt at opholde sig og lege på vejen i hele dens bredde, og de kørende skal holde tilbage for de gående.","efa":"بله. ماندن و بازی در تمام عرض خیابان مجاز است و رانندگان باید به عابران راه بدهند.","en":"Children may play across the whole width of the street.","een":"Yes. It is allowed to stay and play on the road across its whole width, and drivers must give way to pedestrians."},{"da":"Når jeg kører ud af området, har jeg ubetinget vigepligt.","fa":"وقتی از این محدوده بیرون می‌روم، باید بی‌قیدوشرط راه بدهم.","ok":1,"eda":"Ja. Kørende har ubetinget vigepligt ved udkørsel fra et opholds- og legeområde.","efa":"بله. رانندگان هنگام خروج از محدوده‌ی اقامت و بازی باید بی‌قیدوشرط راه بدهند.","en":"When I drive out of the area, I must give way unconditionally.","een":"Yes. Drivers must give way unconditionally when leaving a play-and-living area."},{"da":"Jeg må kun køre med meget lav hastighed, normalt under 15 km/t.","fa":"فقط با سرعت خیلی کم، معمولاً کمتر از ۱۵ کیلومتر بر ساعت، می‌توانم برانم.","ok":1,"eda":"Ja. I et opholds- og legeområde må der kun køres med meget lav hastighed (normalt under 15 km/t).","efa":"بله. در محدوده‌ی اقامت و بازی فقط با سرعت خیلی کم (معمولاً زیر ۱۵ کیلومتر بر ساعت) می‌توان راند.","en":"I may only drive at a very low speed, normally under 15 km/h.","een":"Yes. In a play-and-living area you may only drive at a very low speed (normally under 15 km/h)."}]},{"id":5099,"img":"newq-art/5099.png","c":"7.20","sda":"Du skal køre gennem en lang tunnel. Hvad gælder?","sfa":"قرار است از یک تونل طولانی عبور کنید. چه قاعده‌ای برقرار است؟","sen":"You are going to drive through a long tunnel. What applies?","st":[{"da":"Jeg må ikke standse eller parkere i tunnelen, medmindre jeg er tvunget til det.","fa":"در تونل نباید توقف یا پارک کنم، مگر ناچار باشم.","ok":1,"eda":"Ja. Det er forbudt at standse og parkere i en tunnel.","efa":"بله. توقف و پارک در تونل ممنوع است.","en":"I must not stop or park in the tunnel unless I am forced to.","een":"Yes. Stopping and parking in a tunnel are forbidden."},{"da":"Jeg tænder nærlyset, inden jeg kører ind i tunnelen.","fa":"پیش از ورود به تونل نور پایین را روشن می‌کنم.","ok":1,"eda":"Ja. I tunnelen skal du kunne se og blive set; nærlyset tænder også baglygterne.","efa":"بله. در تونل باید ببینید و دیده شوید؛ نور پایین چراغ‌های عقب را هم روشن می‌کند.","en":"I switch on the dipped beam before I drive into the tunnel.","een":"Yes. In the tunnel you must be able to see and be seen; the dipped beam also switches on the rear lights."},{"da":"Jeg tager solbrillerne på, fordi lyset i tunnelen blænder.","fa":"عینک آفتابی می‌زنم، چون نور تونل چشم را می‌زند.","ok":0,"eda":"Nej. Solbriller gør det sværere at se i tunnelen; tag dem af, før du kører ind.","efa":"خیر. عینک آفتابی دیدن در تونل را سخت‌تر می‌کند؛ پیش از ورود آن را بردارید.","en":"I put on my sunglasses because the light in the tunnel dazzles.","een":"No. Sunglasses make it harder to see in the tunnel; take them off before you go in."},{"da":"Går bilen i stå, holder jeg ind til siden, tænder havariblinket og bruger en nødtelefon.","fa":"اگر خودرو خراب شد، کنار می‌کشم، چراغ خطر را روشن می‌کنم و از تلفن اضطراری استفاده می‌کنم.","ok":1,"eda":"Ja. Så advarer du de andre, og nødtelefonen viser straks, hvor du er.","efa":"بله. این‌طور به دیگران هشدار می‌دهید و تلفن اضطراری فوراً محل شما را نشان می‌دهد.","en":"If the car breaks down, I pull in to the side, switch on the hazard lights and use an emergency phone.","een":"Yes. That way you warn the others, and the emergency phone shows at once where you are."}]},{"id":5100,"img":"newq-art/5100.png","c":"7.17","sda":"Du har længe kørt ved siden af en lastbil i vognbanen til højre for dig. Hvordan forholder du dig?","sfa":"مدتی است کنار کامیونی در خط سمت راستتان می‌رانید. چه می‌کنید؟","sen":"You have been driving for a long time beside a lorry in the lane to your right. What do you do?","st":[{"da":"Jeg undgår at blive liggende i lastbilens blinde vinkel.","fa":"از ماندن در نقطه‌ی کور کامیون پرهیز می‌کنم.","ok":1,"eda":"Ja. Chaufføren kan ikke se dig, og lastbilen kan skifte vognbane ind over dig.","efa":"بله. راننده شما را نمی‌بیند و ممکن است کامیون به سمت شما تغییر خط دهد.","en":"I avoid staying in the lorry's blind spot.","een":"Yes. The driver cannot see you, and the lorry may change lanes into you."},{"da":"Chaufføren kan altid se mig i sine spejle.","fa":"راننده همیشه مرا در آینه‌هایش می‌بیند.","ok":0,"eda":"Nej. Lastbiler har store blinde vinkler, som spejlene ikke dækker.","efa":"خیر. کامیون‌ها نقاط کور بزرگی دارند که آینه‌ها پوشش نمی‌دهند.","en":"The driver can always see me in his mirrors.","een":"No. Lorries have large blind spots that the mirrors do not cover."},{"da":"Jeg bliver ved siden af lastbilen, så chaufføren ved, hvor jeg er.","fa":"کنار کامیون می‌مانم تا راننده بداند کجا هستم.","ok":0,"eda":"Nej. Ved siden af lastbilen er netop der, hvor chaufføren kan have svært ved at se dig.","efa":"خیر. درست کنار کامیون جایی است که راننده ممکن است شما را به‌سختی ببیند.","en":"I stay beside the lorry so that the driver knows where I am.","een":"No. Beside the lorry is exactly where the driver may find it hard to see you."},{"da":"Jeg kører forbi lastbilen eller lægger mig bag den.","fa":"یا از کامیون رد می‌شوم یا پشت سرش قرار می‌گیرم.","ok":1,"eda":"Ja. Så kan chaufføren se dig i spejlene, eller du er ude af vejen.","efa":"بله. این‌طور راننده شما را در آینه‌ها می‌بیند یا از سر راه کنار رفته‌اید.","en":"I drive past the lorry or drop back behind it.","een":"Yes. Then the driver can see you in the mirrors, or you are out of the way."}]},{"id":5101,"img":"newq-art/5101.png","c":"7.18","sda":"Du vil parkere i vejkanten omkring 20 m før jernbaneoverkørslen. Hvad gælder?","sfa":"می‌خواهید حدود ۲۰ متر پیش از تقاطع راه‌آهن کنار جاده پارک کنید. چه قاعده‌ای برقرار است؟","sen":"You want to park at the edge of the road about 20 m before the level crossing. What applies?","st":[{"da":"Jeg må parkere, hvis jeg lader havariblinket være tændt.","fa":"اگر چراغ خطر را روشن بگذارم، می‌توانم پارک کنم.","ok":0,"eda":"Nej. Havariblinket giver ikke ret til at parkere, hvor det er forbudt.","efa":"خیر. چراغ خطر اجازه‌ی پارک در جای ممنوع را نمی‌دهد.","en":"I may park if I leave the hazard lights on.","een":"No. Hazard lights do not give a right to park where it is forbidden."},{"da":"Jeg må ikke parkere nærmere end 30 m fra overkørslen.","fa":"نباید نزدیک‌تر از ۳۰ متر به تقاطع پارک کنم.","ok":1,"eda":"Ja. Parkering er forbudt nærmere end 30 m fra en jernbaneoverkørsel.","efa":"بله. پارک در فاصله‌ی کمتر از ۳۰ متر از تقاطع راه‌آهن ممنوع است.","en":"I must not park closer than 30 m to the crossing.","een":"Yes. Parking is forbidden closer than 30 m to a level crossing."},{"da":"Jeg må gerne standse kort for at lade en passager stige ud, hvis det ikke er til fare.","fa":"اگر خطری نداشته باشد، می‌توانم کوتاه بایستم تا مسافری پیاده شود.","ok":1,"eda":"Ja. Forbuddet inden for 30 m gælder parkering; standsning er kun forbudt på selve overkørslen.","efa":"بله. ممنوعیت ۳۰ متر برای پارک است؛ توقف فقط روی خود تقاطع ممنوع است.","en":"I may stop briefly to let a passenger get out, if it is not dangerous.","een":"Yes. The 30 m ban covers parking; stopping is only forbidden on the crossing itself."},{"da":"Forbuddet gælder kun, når bommene er nede.","fa":"این ممنوعیت فقط وقتی است که راه‌بندها پایین‌اند.","ok":0,"eda":"Nej. Forbuddet gælder hele tiden.","efa":"خیر. این ممنوعیت همیشه برقرار است.","en":"The ban only applies when the barriers are down.","een":"No. The ban applies all the time."}]},{"id":5102,"img":"newq-art/5102.png","c":"7.18","sda":"Den eneste ledige plads ved kantstenen er lige ud for en indkørsel til et hus. Du vil parkere. Hvad gælder?","sfa":"تنها جای خالی کنار جدول درست جلوی ورودی ماشین‌روی یک خانه است. می‌خواهید پارک کنید. چه قاعده‌ای برقرار است؟","sen":"The only free space at the kerb is right in front of the driveway to a house. You want to park. What applies?","st":[{"da":"Det er tilladt, når jeg kun holder der i en time.","fa":"اگر فقط یک ساعت آن‌جا بمانم، مجاز است.","ok":0,"eda":"Nej. Forbuddet gælder uanset hvor længe, du parkerer.","efa":"خیر. این ممنوعیت هر قدر هم کوتاه پارک کنید، برقرار است.","en":"It is allowed as long as I only stand there for an hour.","een":"No. The ban applies however long you park."},{"da":"Det er tilladt om natten, når ingen skal ud.","fa":"شب، وقتی کسی بیرون نمی‌رود، مجاز است.","ok":0,"eda":"Nej. Forbuddet gælder hele døgnet.","efa":"خیر. این ممنوعیت در تمام شبانه‌روز برقرار است.","en":"It is allowed at night, when nobody is going out.","een":"No. The ban applies day and night."},{"da":"Det er tilladt, hvis jeg lægger mit telefonnummer i forruden.","fa":"اگر شماره‌ی تلفنم را پشت شیشه بگذارم، مجاز است.","ok":0,"eda":"Nej. Et telefonnummer ændrer ikke på forbuddet.","efa":"خیر. شماره‌ی تلفن ممنوعیت را تغییر نمی‌دهد.","en":"It is allowed if I put my phone number in the windscreen.","een":"No. A phone number does not change the ban."},{"da":"Det er forbudt at parkere ud for ind- og udkørslen til en ejendom.","fa":"پارک جلوی ورودی و خروجی یک ملک ممنوع است.","ok":1,"eda":"Ja. Parkering må ikke ske ud for ind- og udkørsel til og fra en ejendom.","efa":"بله. پارک جلوی راه ورود و خروج یک ملک مجاز نیست.","en":"Parking in front of the entrance and exit of a property is forbidden.","een":"Yes. Parking is not allowed in front of the way in and out of a property."}]},{"id":5103,"img":"newq-art/5103.png","c":"7.18","sda":"Alle pladser ved kantstenen er optaget. Du vil hurtigt hente en vare i butikken. Hvad gælder?","sfa":"همه‌ی جاهای کنار جدول پر است. می‌خواهید سریع چیزی از مغازه بگیرید. چه قاعده‌ای برقرار است؟","sen":"All the places at the kerb are taken. You want to fetch something quickly from the shop. What applies?","st":[{"da":"En bil, der holder ved siden af de parkerede, kan spærre for trafikken og skjule fodgængere.","fa":"خودرویی که کنار خودروهای پارک‌شده بایستد، می‌تواند راه را ببندد و عابران را پنهان کند.","ok":1,"eda":"Ja. Derfor er dobbeltparkering forbudt.","efa":"بله. به همین دلیل پارک دوبل ممنوع است.","en":"A car standing beside the parked ones can block the traffic and hide pedestrians.","een":"Yes. That is why double parking is forbidden."},{"da":"Jeg skal finde en lovlig plads, også selv om det tager længere tid.","fa":"باید جای مجازی پیدا کنم، حتی اگر بیشتر طول بکشد.","ok":1,"eda":"Ja. Du må kun standse og parkere, hvor det er tilladt og ikke til fare eller ulempe.","efa":"بله. فقط جایی می‌توانید بایستید یا پارک کنید که مجاز باشد و خطر یا مزاحمتی نداشته باشد.","en":"I must find a legal place, even if it takes longer.","een":"Yes. You may only stop and park where it is allowed and not dangerous or a nuisance."},{"da":"Jeg må parkere ved siden af en bil, der holder ved kantstenen, hvis jeg tænder havariblinket.","fa":"اگر چراغ خطر را روشن کنم، می‌توانم کنار خودرویی که لب جدول ایستاده پارک کنم.","ok":0,"eda":"Nej. Det er forbudt at parkere ved siden af et andet køretøj, der holder ved kørebanens kant.","efa":"خیر. پارک کنار وسیله‌ی دیگری که لب سواره‌رو ایستاده، ممنوع است.","en":"I may park beside a car standing at the kerb if I switch on the hazard lights.","een":"No. It is forbidden to park beside another vehicle standing at the edge of the carriageway."},{"da":"Det er tilladt i op til 3 minutter.","fa":"تا ۳ دقیقه مجاز است.","ok":0,"eda":"Nej. Også en kort standsning skal ske ved kørebanens kant; ved siden af parkerede biler må du hverken standse eller parkere.","efa":"خیر. حتی توقف کوتاه هم باید کنار لبه‌ی سواره‌رو باشد؛ کنار خودروهای پارک‌شده نه می‌توانید بایستید و نه پارک کنید.","en":"It is allowed for up to 3 minutes.","een":"No. Even a short stop must be made at the edge of the carriageway; beside parked cars you may neither stop nor park."}]},{"id":5104,"img":"newq-art/5104.png","c":"7.18","sda":"Du kører over en bro over motorvejen og vil standse og tage et billede af udsigten. Hvad gælder?","sfa":"از روی پلی بالای بزرگراه می‌گذرید و می‌خواهید بایستید و از منظره عکس بگیرید. چه قاعده‌ای برقرار است؟","sen":"You are driving over a bridge over the motorway and want to stop and take a picture of the view. What applies?","st":[{"da":"Det er forbudt at standse og parkere på en bro over en motorvej.","fa":"توقف و پارک روی پل بالای بزرگراه ممنوع است.","ok":1,"eda":"Ja. Standsning og parkering er forbudt på bro over motorvej, i viadukt og i tunnel.","efa":"بله. توقف و پارک روی پل بالای بزرگراه، در زیرگذر و در تونل ممنوع است.","en":"Stopping and parking on a bridge over a motorway are forbidden.","een":"Yes. Stopping and parking are forbidden on a bridge over a motorway, in a viaduct and in a tunnel."},{"da":"Forbuddet gælder kun på selve motorvejen, ikke på broen.","fa":"این ممنوعیت فقط در خود بزرگراه است، نه روی پل.","ok":0,"eda":"Nej. Forbuddet gælder netop på broen over motorvejen.","efa":"خیر. این ممنوعیت دقیقاً روی پل بالای بزرگراه است.","en":"The ban only applies on the motorway itself, not on the bridge.","een":"No. The ban applies precisely on the bridge over the motorway."},{"da":"Jeg må standse kort, hvis jeg tænder havariblinket.","fa":"اگر چراغ خطر را روشن کنم، می‌توانم کوتاه بایستم.","ok":0,"eda":"Nej. Havariblinket gør ikke en forbudt standsning tilladt.","efa":"خیر. چراغ خطر توقف ممنوع را مجاز نمی‌کند.","en":"I may stop briefly if I switch on the hazard lights.","een":"No. Hazard lights do not make a forbidden stop allowed."}]},{"id":5105,"img":"newq-art/5105.png","c":"7.18","sda":"Du vil standse i vejkanten lige i et uoverskueligt sving. Hvad gælder?","sfa":"می‌خواهید درست در یک پیچ بی‌دید کنار جاده بایستید. چه قاعده‌ای برقرار است؟","sen":"You want to stop at the edge of the road right in a blind bend. What applies?","st":[{"da":"Jeg må ikke standse i eller ved et uoverskueligt sving.","fa":"نباید در پیچ بی‌دید یا نزدیک آن بایستم.","ok":1,"eda":"Ja. Standsning og parkering er forbudt i eller ved uoverskueligt vejsving og på eller nær en bakketop.","efa":"بله. توقف و پارک در پیچ بی‌دید یا نزدیک آن و روی تپه یا نزدیک آن ممنوع است.","en":"I must not stop in or near a blind bend.","een":"Yes. Stopping and parking are forbidden in or near a blind bend and on or near a hilltop."},{"da":"Jeg kører videre og standser et sted, hvor der er god oversigt.","fa":"ادامه می‌دهم و جایی می‌ایستم که دید خوبی دارد.","ok":1,"eda":"Ja. Find et sted, hvor andre kan se bilen i god tid.","efa":"بله. جایی پیدا کنید که دیگران خودرو را به موقع ببینند.","en":"I drive on and stop at a place with a good view.","een":"Yes. Find a place where others can see the car in good time."},{"da":"Forbuddet gælder kun om natten.","fa":"این ممنوعیت فقط شب‌هاست.","ok":0,"eda":"Nej. Forbuddet gælder hele døgnet.","efa":"خیر. این ممنوعیت در تمام شبانه‌روز برقرار است.","en":"The ban only applies at night.","een":"No. The ban applies day and night."},{"da":"Andre kan komme rundt i svinget og pludselig have bilen lige foran sig.","fa":"دیگران ممکن است از پیچ بیایند و ناگهان خودرو را درست جلوی خود ببینند.","ok":1,"eda":"Ja. De kan ikke se den holdende bil i tide.","efa":"بله. آن‌ها خودروی ایستاده را به موقع نمی‌بینند.","en":"Others may come round the bend and suddenly have the car right in front of them.","een":"Yes. They cannot see the standing car in time."}]},{"id":5106,"img":"newq-art/5106.png","c":"7.18","sda":"Du kører forbi denne tavle i højre side af vejen. Hvad gælder?","sfa":"از کنار این تابلو در سمت راست جاده رد می‌شوید. چه قاعده‌ای برقرار است؟","sen":"You pass this sign on the right-hand side of the road. What applies?","st":[{"da":"Forbuddet gælder i begge sider af vejen.","fa":"این ممنوعیت در هر دو سمت جاده است.","ok":0,"eda":"Nej. Tavlen gælder kun i den vejside, hvor den er sat op.","efa":"خیر. این تابلو فقط در همان سمتی از جاده که نصب شده معتبر است.","en":"The ban applies on both sides of the road.","een":"No. The sign only applies on the side of the road where it stands."},{"da":"Jeg må ikke standse på kørebanen i denne side af vejen.","fa":"در این سمت جاده نباید روی سواره‌رو بایستم.","ok":1,"eda":"Ja. Tavlen (C 61) forbyder standsning på kørebanen, som ikke sker af hensyn til den øvrige færdsel.","efa":"بله. این تابلو (C 61) توقف روی سواره‌رو را، جز به‌خاطر ترافیک، ممنوع می‌کند.","en":"I must not stop on the carriageway on this side of the road.","een":"Yes. The sign (C 61) forbids stopping on the carriageway that is not for the sake of the other traffic."},{"da":"Forbuddet gælder frem til næste vejkryds, hvis det ikke ophæves før.","fa":"این ممنوعیت تا تقاطع بعدی برقرار است، مگر زودتر لغو شود.","ok":1,"eda":"Ja. Standsnings- og parkeringsforbud gælder i færdselsretningen frem til næste vejkryds.","efa":"بله. ممنوعیت توقف و پارک در جهت حرکت تا تقاطع بعدی برقرار است.","en":"The ban applies up to the next junction, unless it is lifted before.","een":"Yes. Stopping and parking bans apply in the direction of travel up to the next junction."},{"da":"Jeg må standse kort for at sætte en passager af.","fa":"می‌توانم کوتاه بایستم تا مسافری پیاده شود.","ok":0,"eda":"Nej. Ved denne tavle er også en kort standsning forbudt.","efa":"خیر. با این تابلو حتی توقف کوتاه هم ممنوع است.","en":"I may stop briefly to let a passenger out.","een":"No. At this sign even a short stop is forbidden."}]},{"id":5107,"img":"newq-art/5107.png","c":"7.9","sda":"Bilen foran dig er ved at trække ud for at overhale en traktor. Hvad gælder for dig?","sfa":"خودروی جلوی شما دارد بیرون می‌کشد تا از یک تراکتور سبقت بگیرد. برای شما چه قاعده‌ای برقرار است؟","sen":"The car in front of you is moving out to overtake a tractor. What applies to you?","st":[{"da":"Jeg venter, til bilen er færdig med sin overhaling.","fa":"صبر می‌کنم تا سبقت آن خودرو تمام شود.","ok":1,"eda":"Ja. Derefter kan du selv vurdere, om du kan overhale uden fare.","efa":"بله. بعد از آن خودتان می‌سنجید که آیا بی‌خطر می‌توانید سبقت بگیرید.","en":"I wait until the car has finished its overtaking.","een":"Yes. After that you can judge for yourself whether you can overtake safely."},{"da":"Jeg kan overhale begge køretøjer på én gang, hvis jeg skynder mig.","fa":"اگر عجله کنم، می‌توانم هم‌زمان از هر دو سبقت بگیرم.","ok":0,"eda":"Nej. Du må ikke begynde, når den foran selv er ved at overhale.","efa":"خیر. وقتی جلویی خودش در حال سبقت است، نباید شروع کنید.","en":"I can overtake both vehicles at once if I hurry.","een":"No. You must not start when the one in front is overtaking itself."},{"da":"Jeg må ikke begynde at overhale, mens bilen foran giver tegn til at overhale.","fa":"تا وقتی خودروی جلو علامت سبقت می‌دهد، نباید سبقت را شروع کنم.","ok":1,"eda":"Ja. Før du overhaler, skal du sikre dig, at den foran ikke giver tegn til at overhale et andet køretøj.","efa":"بله. پیش از سبقت باید مطمئن شوید که جلویی علامت سبقت از وسیله‌ی دیگری نمی‌دهد.","en":"I must not start overtaking while the car in front is signalling to overtake.","een":"Yes. Before you overtake, you must make sure that the one in front is not signalling to overtake another vehicle."},{"da":"Bilen foran skal lade mig komme først, fordi jeg kører hurtigere.","fa":"خودروی جلو باید اجازه دهد اول من بروم، چون تندتر می‌رانم.","ok":0,"eda":"Nej. Det er dig, der skal vente; fart giver ingen ret.","efa":"خیر. شما باید صبر کنید؛ سرعت حقی به شما نمی‌دهد.","en":"The car in front must let me go first because I am driving faster.","een":"No. It is you who must wait; speed gives no right."}]},{"id":5108,"img":"newq-art/5108.png","c":"7.9","sda":"Du har lige overhalet en lastbil. Lidt længere fremme kører endnu en lastbil, som du også vil overhale med det samme. Hvad gælder?","sfa":"همین الان از یک کامیون سبقت گرفته‌اید. کمی جلوتر کامیون دیگری است که می‌خواهید فوراً از آن هم سبقت بگیرید. چه قاعده‌ای برقرار است؟","sen":"You have just overtaken a lorry. A little further ahead there is another lorry that you also want to overtake straight away. What applies?","st":[{"da":"Jeg må blive i venstre vognbane, så længe jeg vil.","fa":"تا هر وقت بخواهم می‌توانم در خط چپ بمانم.","ok":0,"eda":"Nej. Venstre vognbane bruges til at overhale, ikke til at blive i.","efa":"خیر. خط چپ برای سبقت است، نه برای ماندن.","en":"I may stay in the left lane for as long as I like.","een":"No. The left lane is for overtaking, not for staying in."},{"da":"Jeg skal straks trække ind lige foran den første lastbil.","fa":"باید فوراً درست جلوی کامیون اول برگردم.","ok":0,"eda":"Nej. Du må ikke trække ind så tæt, at du generer den, du har overhalet.","efa":"خیر. نباید آن‌قدر نزدیک برگردید که مزاحم وسیله‌ی سبقت‌گرفته شوید.","en":"I must pull in right in front of the first lorry at once.","een":"No. You must not pull in so close that you inconvenience the one you have overtaken."},{"da":"Jeg må blive i venstre vognbane, når jeg straks skal overhale den næste lastbil.","fa":"وقتی قرار است فوراً از کامیون بعدی سبقت بگیرم، می‌توانم در خط چپ بمانم.","ok":1,"eda":"Ja. Du behøver ikke køre tilbage til højre, hvis du straks vil overhale endnu et køretøj, og betingelserne er opfyldt.","efa":"بله. اگر قصد دارید فوراً از وسیله‌ی دیگری سبقت بگیرید و شرایط فراهم است، لازم نیست به راست برگردید.","en":"I may stay in the left lane when I am going to overtake the next lorry straight away.","een":"Yes. You need not move back to the right if you are going to overtake another vehicle straight away and the conditions are met."},{"da":"Ellers skal jeg tilbage til højre, så snart det kan ske uden fare eller ulempe.","fa":"در غیر این صورت باید به محض این‌که بی‌خطر و بی‌مزاحمت باشد، به راست برگردم.","ok":1,"eda":"Ja. Efter en overhaling til venstre skal du holde til højre igen, så snart det kan ske uden fare eller ulempe.","efa":"بله. پس از سبقت از چپ، باید به محض این‌که بی‌خطر و بی‌مزاحمت باشد، دوباره سمت راست بمانید.","en":"Otherwise I must move back to the right as soon as it can be done without danger or inconvenience.","een":"Yes. After overtaking on the left you must keep right again as soon as it can be done without danger or inconvenience."}]},{"id":5109,"img":"newq-art/5109.png","c":"7.9","sda":"Du vil overhale cyklisten, men en bil kommer imod dig. Hvordan forholder du dig?","sfa":"می‌خواهید از دوچرخه‌سوار سبقت بگیرید، ولی خودرویی از روبه‌رو می‌آید. چه می‌کنید؟","sen":"You want to overtake the cyclist, but a car is coming towards you. What do you do?","st":[{"da":"Jeg venter med at overhale, til jeg kan give cyklisten god plads til siden.","fa":"صبر می‌کنم تا بتوانم از پهلو فاصله‌ی زیادی به دوچرخه‌سوار بدهم.","ok":1,"eda":"Ja. Den, der overhaler, skal holde tilstrækkelig afstand til siden.","efa":"بله. سبقت‌گیرنده باید فاصله‌ی پهلوی کافی نگه دارد.","en":"I wait to overtake until I can give the cyclist plenty of room to the side.","een":"Yes. The overtaking driver must keep enough distance to the side."},{"da":"Cyklisten kan svaje, fx i blæst eller for at undgå et hul i vejen.","fa":"دوچرخه‌سوار ممکن است منحرف شود، مثلاً در باد یا برای دور زدن یک چاله.","ok":1,"eda":"Ja. Derfor skal der være god plads mellem bilen og cyklisten.","efa":"بله. به همین دلیل باید بین خودرو و دوچرخه‌سوار فاصله‌ی خوبی باشد.","en":"The cyclist may wobble, for example in the wind or to avoid a hole in the road.","een":"Yes. That is why there must be plenty of room between the car and the cyclist."},{"da":"Jeg kan presse mig forbi, fordi cyklisten fylder så lidt.","fa":"می‌توانم به زور رد شوم، چون دوچرخه‌سوار جای کمی می‌گیرد.","ok":0,"eda":"Nej. En overhaling tæt på cyklisten kan få den til at vælte.","efa":"خیر. سبقت از نزدیک ممکن است دوچرخه‌سوار را زمین بزند.","en":"I can squeeze past because the cyclist takes up so little room.","een":"No. Overtaking close to the cyclist can make them fall."},{"da":"Jeg kører et stykke bag cyklisten, til den modkørende er kørt forbi.","fa":"تا رد شدن خودروی روبه‌رو با فاصله پشت دوچرخه‌سوار می‌رانم.","ok":1,"eda":"Ja. Så kan du overhale med god plads, når vejen er fri.","efa":"بله. این‌طور وقتی جاده خالی شد، با فاصله‌ی خوب سبقت می‌گیرید.","en":"I drive some way behind the cyclist until the oncoming car has passed.","een":"Yes. Then you can overtake with plenty of room when the road is clear."}]},{"id":5110,"img":"newq-art/5110.png","c":"7.9","sda":"Midt på vejen er der en dobbelt spærrelinje. Foran dig kører en langsom traktor. Hvad gælder?","sfa":"وسط جاده خط ممتد دوبل است. جلوی شما تراکتوری آهسته می‌رود. چه قاعده‌ای برقرار است؟","sen":"In the middle of the road there is a double barrier line. A slow tractor is driving in front of you. What applies?","st":[{"da":"Jeg må overhale, hvis jeg kun kører lidt ind over linjen.","fa":"اگر فقط کمی روی خط بروم، می‌توانم سبقت بگیرم.","ok":0,"eda":"Nej. Linjen må slet ikke overskrides.","efa":"خیر. اصلاً نباید از این خط عبور کرد.","en":"I may overtake if I only drive a little over the line.","een":"No. The line must not be crossed at all."},{"da":"Jeg må ikke overskride spærrelinjen for at overhale.","fa":"برای سبقت نباید از خط ممتد عبور کنم.","ok":1,"eda":"Ja. En spærrelinje må ikke overskrides, heller ikke for at overhale en langsom traktor.","efa":"بله. از خط ممتد نباید عبور کرد، حتی برای سبقت از یک تراکتور آهسته.","en":"I must not cross the barrier line to overtake.","een":"Yes. A barrier line must not be crossed, not even to overtake a slow tractor."},{"da":"Jeg må overhale, hvis traktoren kører under 30 km/t.","fa":"اگر تراکتور کمتر از ۳۰ کیلومتر بر ساعت برود، می‌توانم سبقت بگیرم.","ok":0,"eda":"Nej. Der er ingen sådan undtagelse.","efa":"خیر. چنین استثنایی وجود ندارد.","en":"I may overtake if the tractor is doing under 30 km/h.","een":"No. There is no such exception."},{"da":"Jeg må overhale, når der ikke er modkørende.","fa":"وقتی ترافیک روبه‌رو نیست، می‌توانم سبقت بگیرم.","ok":0,"eda":"Nej. Spærrelinjen gælder, også når vejen er fri.","efa":"خیر. خط ممتد حتی وقتی جاده خالی است هم معتبر است.","en":"I may overtake when there is no oncoming traffic.","een":"No. The barrier line applies even when the road is clear."}]},{"id":5111,"img":"newq-art/5111.png","c":"7.9","sda":"Du nærmer dig et kryds uden tavler og afmærkning. Foran dig kører en langsom varevogn. Hvad gælder?","sfa":"به تقاطعی بدون تابلو و خط‌کشی نزدیک می‌شوید. جلوی شما ونی آهسته می‌رود. چه قاعده‌ای برقرار است؟","sen":"You are approaching a junction with no signs or markings. A slow van is driving in front of you. What applies?","st":[{"da":"Jeg må overhale, fordi jeg kører på den største vej.","fa":"می‌توانم سبقت بگیرم، چون در جاده‌ی بزرگ‌تر هستم.","ok":0,"eda":"Nej. Her gælder højrereglen; vejens størrelse giver ingen ret.","efa":"خیر. این‌جا قاعده‌ی دست راست برقرار است؛ بزرگی جاده حقی نمی‌دهد.","en":"I may overtake because I am on the bigger road.","een":"No. The right-hand rule applies here; the size of the road gives no right."},{"da":"Jeg må overhale, hvis jeg blinker i god tid.","fa":"اگر به موقع راهنما بزنم، می‌توانم سبقت بگیرم.","ok":0,"eda":"Nej. Blinklyset ændrer ikke på forbuddet.","efa":"خیر. راهنما ممنوعیت را تغییر نمی‌دهد.","en":"I may overtake if I signal in good time.","een":"No. The indicator does not change the ban."},{"da":"Jeg må ikke overhale varevognen i krydset.","fa":"در تقاطع نباید از ون سبقت بگیرم.","ok":1,"eda":"Ja. Overhaling i vejkryds er forbudt, når der ikke gælder en af undtagelserne, fx at den tværgående trafik har ubetinget vigepligt.","efa":"بله. سبقت در تقاطع ممنوع است، مگر یکی از استثناها برقرار باشد، مثلاً ترافیک متقاطع باید بی‌قیدوشرط راه بدهد.","en":"I must not overtake the van at the junction.","een":"Yes. Overtaking at a junction is forbidden unless one of the exceptions applies, for example that the crossing traffic must give way unconditionally."}]},{"id":5112,"img":"newq-art/5112.png","c":"6.1","sda":"Du kører forbi denne advarselstavle uden for byen. Der er ingen undertavle. Hvad gælder?","sfa":"بیرون از شهر از کنار این تابلوی هشدار رد می‌شوید. زیرش تابلوی کوچکی نیست. چه قاعده‌ای برقرار است؟","sen":"You pass this warning sign outside town. There is no plate under it. What applies?","st":[{"da":"Faren er lige ved tavlen.","fa":"خطر درست کنار تابلوست.","ok":0,"eda":"Nej. Uden for byen står tavlen normalt et godt stykke før faren.","efa":"خیر. بیرون از شهر تابلو معمولاً مسافتی پیش از خطر است.","en":"The danger is right at the sign.","een":"No. Outside town the sign normally stands a good way before the danger."},{"da":"Faren er mindst 1 km fremme.","fa":"خطر دست‌کم ۱ کیلومتر جلوتر است.","ok":0,"eda":"Nej. Er afstanden en anden end normalt, står den på en undertavle.","efa":"خیر. اگر فاصله غیرعادی باشد، روی تابلوی کوچک زیرین نوشته می‌شود.","en":"The danger is at least 1 km ahead.","een":"No. If the distance is other than normal, it is shown on a plate under the sign."},{"da":"Faren er normalt mellem 150 og 250 m fremme.","fa":"خطر معمولاً ۱۵۰ تا ۲۵۰ متر جلوتر است.","ok":1,"eda":"Ja. Uden for tættere bebygget område sættes advarselstavler normalt op mellem 150 og 250 m før farestedet.","efa":"بله. بیرون از مناطق مسکونی، تابلوهای هشدار معمولاً ۱۵۰ تا ۲۵۰ متر پیش از محل خطر نصب می‌شوند.","en":"The danger is normally between 150 and 250 m ahead.","een":"Yes. Outside built-up areas warning signs are normally put up between 150 and 250 m before the danger."},{"da":"Der kan være kreaturer på vejen.","fa":"ممکن است دام روی جاده باشد.","ok":1,"eda":"Ja. Tavlen (A 27) advarer om kreaturer.","efa":"بله. این تابلو (A 27) درباره‌ی دام هشدار می‌دهد.","en":"There may be livestock on the road.","een":"Yes. The sign (A 27) warns of livestock."}]},{"id":5113,"img":"newq-art/5113.png","c":"6.1","sda":"Du har kørt på en strækning med overhalingsforbud og en lokal hastighedsgrænse. Nu kører du forbi denne tavle. Hvad gælder?","sfa":"در مسیری با ممنوعیت سبقت و حد سرعت محلی رانده‌اید. حالا از کنار این تابلو رد می‌شوید. چه قاعده‌ای برقرار است؟","sen":"You have been driving on a stretch with a no-overtaking ban and a local speed limit. Now you pass this sign. What applies?","st":[{"da":"Overhalingsforbuddet og den lokale hastighedsgrænse er ophævet.","fa":"ممنوعیت سبقت و حد سرعت محلی لغو شده‌اند.","ok":1,"eda":"Ja. Tavlen (C 59) ophæver alle forbudstavler på den forudgående strækning undtagen standsnings- og parkeringsforbud.","efa":"بله. این تابلو (C 59) همه‌ی تابلوهای ممنوعیت مسیر قبلی را، جز ممنوعیت توقف و پارک، لغو می‌کند.","en":"The no-overtaking ban and the local speed limit are lifted.","een":"Yes. The sign (C 59) lifts all prohibition signs on the stretch before it except stopping and parking bans."},{"da":"Et standsnings- eller parkeringsforbud gælder stadig.","fa":"ممنوعیت توقف یا پارک هنوز برقرار است.","ok":1,"eda":"Ja. Standsnings- og parkeringsforbud ophæves ikke af denne tavle.","efa":"بله. ممنوعیت توقف و پارک با این تابلو لغو نمی‌شود.","en":"A stopping or parking ban still applies.","een":"Yes. Stopping and parking bans are not lifted by this sign."},{"da":"Nu gælder der ingen hastighedsgrænse.","fa":"حالا هیچ حد سرعتی وجود ندارد.","ok":0,"eda":"Nej. Den generelle hastighedsgrænse gælder igen, fx 80 km/t uden for byen.","efa":"خیر. حد سرعت عمومی دوباره برقرار است، مثلاً بیرون شهر ۸۰ کیلومتر بر ساعت.","en":"Now there is no speed limit at all.","een":"No. The general speed limit applies again, for example 80 km/h outside town."},{"da":"Tavlen betyder, at vejen snart ender.","fa":"این تابلو یعنی جاده به‌زودی تمام می‌شود.","ok":0,"eda":"Nej. Tavlen handler om forbud, ikke om vejens forløb.","efa":"خیر. این تابلو درباره‌ی ممنوعیت‌هاست، نه مسیر جاده.","en":"The sign means that the road ends soon.","een":"No. The sign is about prohibitions, not about where the road goes."}]},{"id":5114,"img":"newq-art/5114.png","c":"6.1","sda":"Du vil svinge ind på sidevejen med denne tavle for at aflevere en pakke i butikken. Hvad gælder?","sfa":"می‌خواهید وارد فرعی‌ای با این تابلو شوید تا بسته‌ای را به مغازه بدهید. چه قاعده‌ای برقرار است؟","sen":"You want to turn into the side road with this sign to deliver a parcel at the shop. What applies?","st":[{"da":"Jeg må ikke køre ind på vejen med noget køretøj.","fa":"با هیچ وسیله‌ای نباید وارد این راه شوم.","ok":1,"eda":"Ja. Tavlen (C 19) forbyder indkørsel med ethvert køretøj.","efa":"بله. این تابلو (C 19) ورود با هر وسیله‌ای را ممنوع می‌کند.","en":"I must not drive into the road with any vehicle.","een":"Yes. The sign (C 19) forbids entry with any vehicle."},{"da":"Jeg må køre ind, hvis der ikke kommer nogen ud.","fa":"اگر کسی بیرون نیاید، می‌توانم وارد شوم.","ok":0,"eda":"Nej. Forbuddet gælder, uanset om der er trafik.","efa":"خیر. این ممنوعیت، چه ترافیک باشد چه نباشد، برقرار است.","en":"I may drive in if nobody is coming out.","een":"No. The ban applies whether or not there is traffic."},{"da":"Tavlen gælder kun for lastbiler.","fa":"این تابلو فقط برای کامیون‌هاست.","ok":0,"eda":"Nej. Den gælder alle køretøjer, når der ikke er en undertavle.","efa":"خیر. وقتی تابلوی زیرین نباشد، برای همه‌ی وسایل است.","en":"The sign only applies to lorries.","een":"No. It applies to all vehicles when there is no plate under it."},{"da":"Jeg må køre ind, når jeg kun skal aflevere en pakke.","fa":"وقتی فقط باید بسته‌ای بدهم، می‌توانم وارد شوم.","ok":0,"eda":"Nej. Et kort ærinde er ikke en undtagelse fra forbuddet.","efa":"خیر. کار کوتاه از این ممنوعیت مستثنا نیست.","en":"I may drive in when I only have to deliver a parcel.","een":"No. A short errand is no exception to the ban."}]},{"id":5115,"img":"newq-art/5115.png","c":"6.1","sda":"Du kører forbi denne tavle ved et kryds. Hvad gælder?","sfa":"در یک تقاطع از کنار این تابلو رد می‌شوید. چه قاعده‌ای برقرار است؟","sen":"You pass this sign at a junction. What applies?","st":[{"da":"Jeg må heller ikke vende i krydset.","fa":"در این تقاطع دور زدن هم ممنوع است.","ok":1,"eda":"Ja. Forbuddet mod venstresving gælder også vending.","efa":"بله. ممنوعیت گردش به چپ شامل دور زدن هم می‌شود.","en":"I must not turn round at the junction either.","een":"Yes. The ban on turning left also covers turning round."},{"da":"Forbuddet gælder frem til næste kryds.","fa":"این ممنوعیت تا تقاطع بعدی است.","ok":0,"eda":"Nej. Forbuddet gælder kun i det kryds, hvor tavlen er sat op.","efa":"خیر. این ممنوعیت فقط در همان تقاطعی است که تابلو نصب شده.","en":"The ban applies up to the next junction.","een":"No. The ban only applies at the junction where the sign is put up."},{"da":"Jeg må svinge til venstre, hvis der ikke er modkørende.","fa":"اگر ترافیک روبه‌رو نباشد، می‌توانم به چپ بپیچم.","ok":0,"eda":"Nej. Forbuddet gælder, uanset trafikken.","efa":"خیر. این ممنوعیت، ترافیک هر چه باشد، برقرار است.","en":"I may turn left if there is no oncoming traffic.","een":"No. The ban applies whatever the traffic."},{"da":"Jeg må ikke svinge til venstre i krydset.","fa":"در این تقاطع نباید به چپ بپیچم.","ok":1,"eda":"Ja. Tavlen (C 11) forbyder venstresving i det kryds, hvor den står.","efa":"بله. این تابلو (C 11) گردش به چپ را در همان تقاطع ممنوع می‌کند.","en":"I must not turn left at the junction.","een":"Yes. The sign (C 11) forbids turning left at the junction where it stands."}]},{"id":5116,"img":"newq-art/5116.png","c":"6.1","sda":"Før krydset kørte du forbi en tavle med 60 km/t. Efter krydset er der ingen nye tavler. Hvad gælder?","sfa":"پیش از تقاطع از کنار تابلوی ۶۰ کیلومتر بر ساعت رد شدید. بعد از تقاطع تابلوی تازه‌ای نیست. چه قاعده‌ای برقرار است؟","sen":"Before the junction you passed a 60 km/h sign. After the junction there are no new signs. What applies?","st":[{"da":"Grænsen ophører i krydset, ligesom de fleste andre forbud.","fa":"این حد، مثل بیشتر ممنوعیت‌ها، در تقاطع تمام می‌شود.","ok":0,"eda":"Nej. Hastighedsgrænser fortsætter efter kryds; det gør de fleste andre forbud ikke.","efa":"خیر. حد سرعت بعد از تقاطع ادامه دارد؛ بیشتر ممنوعیت‌های دیگر نه.","en":"The limit ends at the junction, like most other bans.","een":"No. Speed limits continue after junctions; most other bans do not."},{"da":"Grænsen på 60 km/t gælder stadig.","fa":"حد ۶۰ کیلومتر بر ساعت هنوز برقرار است.","ok":1,"eda":"Ja. En lokal hastighedsgrænse gælder, til den ophæves af en ophørstavle, en afstand på en undertavle eller en anden grænse.","efa":"بله. حد سرعت محلی تا وقتی تابلوی پایان، فاصله‌ی روی تابلوی زیرین یا حد دیگری آن را لغو کند، برقرار است.","en":"The 60 km/h limit still applies.","een":"Yes. A local speed limit applies until it is lifted by an end sign, a distance on a plate or another limit."},{"da":"Nu gælder 80 km/t, fordi jeg er uden for byen.","fa":"حالا ۸۰ کیلومتر بر ساعت معتبر است، چون بیرون شهرم.","ok":0,"eda":"Nej. Den lokale grænse gælder, indtil den bliver ophævet.","efa":"خیر. حد محلی تا لغو شدنش برقرار است.","en":"Now 80 km/h applies because I am outside town.","een":"No. The local limit applies until it is lifted."}]},{"id":5117,"img":"newq-art/5117.png","c":"7.6","sda":"En bus holder ved stoppestedet foran dig, og passagerer stiger af. Hvordan forholder du dig?","sfa":"اتوبوسی جلوی شما در ایستگاه ایستاده و مسافران پیاده می‌شوند. چه می‌کنید؟","sen":"A bus is standing at the stop in front of you, and passengers are getting off. What do you do?","st":[{"da":"Jeg sænker farten, fordi passagerer kan gå ud på kørebanen foran bussen.","fa":"سرعتم را کم می‌کنم، چون ممکن است مسافران از جلوی اتوبوس وارد سواره‌رو شوند.","ok":1,"eda":"Ja. Når du nærmer dig en bus, der holder for at sætte passagerer af, skal hastigheden være passende lav.","efa":"بله. وقتی به اتوبوسی نزدیک می‌شوید که برای پیاده کردن مسافر ایستاده، سرعت باید به اندازه‌ی کافی کم باشد.","en":"I slow down because passengers may step out into the road in front of the bus.","een":"Yes. When you approach a bus that has stopped to let passengers off, your speed must be suitably low."},{"da":"Blinker bussen til venstre for at køre ud, lader jeg den komme ud.","fa":"اگر اتوبوس برای حرکت راهنمای چپ بزند، می‌گذارم بیرون بیاید.","ok":1,"eda":"Ja. I tættere bebygget område skal du give plads til en bus, der giver tegn til at køre ud fra et stoppested.","efa":"بله. در مناطق مسکونی باید به اتوبوسی که برای حرکت از ایستگاه علامت می‌دهد، جا بدهید.","en":"If the bus signals left to pull out, I let it out.","een":"Yes. In built-up areas you must make room for a bus that signals to pull out from a stop."},{"da":"Jeg kører forbi med uændret fart, fordi bussen holder stille.","fa":"با همان سرعت رد می‌شوم، چون اتوبوس ایستاده است.","ok":0,"eda":"Nej. Netop når bussen holder, kan der komme passagerer ud foran den.","efa":"خیر. درست وقتی اتوبوس ایستاده، ممکن است مسافران از جلویش بیرون بیایند.","en":"I drive past at the same speed because the bus is standing still.","een":"No. It is precisely when the bus is standing that passengers may come out in front of it."},{"da":"Passagererne skal vente, så jeg behøver ikke tage hensyn.","fa":"مسافران باید صبر کنند، پس لازم نیست ملاحظه کنم.","ok":0,"eda":"Nej. Du skal altid vise hensyn over for gående, også dem, der går ud ved en bus.","efa":"خیر. همیشه باید به عابران ملاحظه کنید، از جمله کسانی که کنار اتوبوس وارد جاده می‌شوند.","en":"The passengers have to wait, so I need not take care.","een":"No. You must always show consideration for pedestrians, including those stepping out by a bus."}]},{"id":5118,"img":"newq-art/5118.png","c":"7.6","sda":"Foran dig rider to ryttere i vejkanten. Hvordan forholder du dig?","sfa":"جلوی شما دو سوارکار کنار جاده اسب‌سواری می‌کنند. چه می‌کنید؟","sen":"Two riders on horseback are riding at the edge of the road in front of you. What do you do?","st":[{"da":"Jeg sænker farten i god tid.","fa":"به موقع سرعتم را کم می‌کنم.","ok":1,"eda":"Ja. Når du nærmer dig heste på vejen, skal hastigheden være passende lav.","efa":"بله. وقتی به اسب‌ها روی جاده نزدیک می‌شوید، سرعت باید به اندازه‌ی کافی کم باشد.","en":"I slow down in good time.","een":"Yes. When you approach horses on the road, your speed must be suitably low."},{"da":"Jeg kører forbi i god afstand og roligt.","fa":"با فاصله‌ی زیاد و آرام رد می‌شوم.","ok":1,"eda":"Ja. En hest kan blive bange og springe til siden.","efa":"بله. اسب ممکن است بترسد و به کنار بپرد.","en":"I pass at a good distance and calmly.","een":"Yes. A horse may take fright and jump to the side."},{"da":"Hestene er vant til trafik, så jeg kan køre tæt forbi.","fa":"اسب‌ها به ترافیک عادت دارند، پس می‌توانم از نزدیک رد شوم.","ok":0,"eda":"Nej. Du kan aldrig vide, hvordan en hest reagerer.","efa":"خیر. هرگز نمی‌دانید اسب چه واکنشی نشان می‌دهد.","en":"The horses are used to traffic, so I can drive close past them.","een":"No. You can never know how a horse will react."},{"da":"Jeg undgår at dytte eller give gas tæt ved hestene.","fa":"از بوق زدن یا گاز دادن نزدیک اسب‌ها پرهیز می‌کنم.","ok":1,"eda":"Ja. Pludselige lyde kan skræmme hestene.","efa":"بله. صداهای ناگهانی می‌تواند اسب‌ها را بترساند.","en":"I avoid sounding the horn or revving up close to the horses.","een":"Yes. Sudden noises can frighten the horses."}]},{"id":5119,"img":"newq-art/5119.png","c":"7.6","sda":"Det er mørkt, og to fodgængere går i vejens venstre side og kommer imod dig. Hvordan forholder du dig?","sfa":"هوا تاریک است و دو عابر در سمت چپ جاده به سمت شما می‌آیند. چه می‌کنید؟","sen":"It is dark, and two pedestrians are walking on the left side of the road towards you. What do you do?","st":[{"da":"Jeg sænker farten og giver dem god plads, når jeg kører forbi.","fa":"سرعتم را کم می‌کنم و هنگام عبور جای زیادی به آن‌ها می‌دهم.","ok":1,"eda":"Ja. Du skal give de gående tid til at vige og fornøden plads på vejen.","efa":"بله. باید به عابران فرصت کنار رفتن و جای لازم روی جاده بدهید.","en":"I slow down and give them plenty of room when I pass.","een":"Yes. You must give pedestrians time to step aside and the room they need on the road."},{"da":"Mørkt tøj gør dem svære at se, så jeg må regne med, at der kan være flere.","fa":"لباس تیره دیدنشان را سخت می‌کند، پس باید انتظار داشته باشم عابران دیگری هم باشند.","ok":1,"eda":"Ja. Gående uden refleks ses først meget sent i nærlys.","efa":"بله. عابران بدون شبرنگ در نور پایین خیلی دیر دیده می‌شوند.","en":"Dark clothes make them hard to see, so I must expect that there may be more.","een":"Yes. Pedestrians without reflectors are seen only very late in dipped beam."},{"da":"De går forkert, fordi de går i venstre side.","fa":"اشتباه می‌روند، چون در سمت چپ‌اند.","ok":0,"eda":"Nej. Gående på en vej uden fortov skal gå i venstre side, imod trafikken.","efa":"خیر. عابران در جاده‌ی بدون پیاده‌رو باید سمت چپ و رو به ترافیک راه بروند.","en":"They are walking wrongly because they are on the left side.","een":"No. Pedestrians on a road without a pavement must walk on the left, facing the traffic."},{"da":"Jeg dytter, så de går ud i rabatten.","fa":"بوق می‌زنم تا به کنار جاده بروند.","ok":0,"eda":"Nej. Hornet bruges kun for at afværge fare; sænk i stedet farten.","efa":"خیر. بوق فقط برای دفع خطر است؛ به‌جایش سرعت را کم کنید.","en":"I sound the horn so that they move onto the verge.","een":"No. The horn is only for averting danger; slow down instead."}]},{"id":5120,"img":"newq-art/5120.png","c":"7.6","sda":"Du kommer til et uheldssted, hvor politiet dirigerer trafikken forbi. Hvordan forholder du dig?","sfa":"به محل تصادفی می‌رسید که پلیس ترافیک را از کنارش هدایت می‌کند. چه می‌کنید؟","sen":"You come to the scene of an accident where the police are directing traffic past. What do you do?","st":[{"da":"Jeg standser for at se, hvad der er sket, selv om politiet har styr på det.","fa":"می‌ایستم تا ببینم چه شده، با آن‌که پلیس اوضاع را در دست دارد.","ok":0,"eda":"Nej. Nysgerrige, der standser, kan skabe nye uheld og hindre redningsarbejdet.","efa":"خیر. کنجکاوهایی که می‌ایستند، ممکن است باعث تصادف تازه شوند و کار امداد را مختل کنند.","en":"I stop to see what has happened, even though the police have it in hand.","een":"No. Curious drivers who stop can cause new accidents and hinder the rescue work."},{"da":"Jeg følger politiets anvisninger.","fa":"از دستور پلیس پیروی می‌کنم.","ok":1,"eda":"Ja. Politiets anvisninger skal efterkommes.","efa":"بله. دستور پلیس باید اجرا شود.","en":"I follow the police's directions.","een":"Yes. The police's directions must be obeyed."},{"da":"Jeg sænker farten, når jeg kører forbi uheldsstedet.","fa":"هنگام عبور از کنار محل تصادف سرعتم را کم می‌کنم.","ok":1,"eda":"Ja. Forbi et uheldssted skal hastigheden være passende lav.","efa":"بله. هنگام عبور از محل تصادف سرعت باید به اندازه‌ی کافی کم باشد.","en":"I slow down when I drive past the accident.","een":"Yes. Past an accident your speed must be suitably low."},{"da":"Jeg kører langsomt forbi og filmer uheldet med telefonen.","fa":"آهسته رد می‌شوم و با تلفن از تصادف فیلم می‌گیرم.","ok":0,"eda":"Nej. Du må ikke bruge håndholdt telefon under kørsel, og du skal holde opmærksomheden på vejen.","efa":"خیر. در حین رانندگی نباید از تلفن دستی استفاده کنید و باید حواستان به جاده باشد.","en":"I drive past slowly and film the accident with my phone.","een":"No. You must not use a hand-held phone while driving, and you must keep your attention on the road."}]},{"id":5121,"img":"newq-art/5121.png","c":"7.3","sda":"Du kører i en almindelig personbil uden for tættere bebygget område. Der er ingen hastighedstavler. Hvad er den højst tilladte hastighed?","sfa":"با یک سواری معمولی بیرون از منطقه‌ی مسکونی می‌رانید. تابلوی سرعتی نیست. حداکثر سرعت مجاز چقدر است؟","sen":"You are driving an ordinary car outside a built-up area. There are no speed-limit signs. What is the highest permitted speed?","st":[{"da":"70 km/t.","fa":"۷۰ کیلومتر بر ساعت.","ok":0,"eda":"Nej. 70 km/t gælder kun, hvor det er skiltet.","efa":"خیر. ۷۰ کیلومتر بر ساعت فقط جایی است که تابلو داشته باشد.","en":"70 km/h.","een":"No. 70 km/h only applies where it is signed."},{"da":"100 km/t.","fa":"۱۰۰ کیلومتر بر ساعت.","ok":0,"eda":"Nej. 100 km/t er ikke den generelle grænse på landevej.","efa":"خیر. ۱۰۰ کیلومتر بر ساعت حد عمومی جاده‌ی بیرون شهر نیست.","en":"100 km/h.","een":"No. 100 km/h is not the general limit on a country road."},{"da":"90 km/t.","fa":"۹۰ کیلومتر بر ساعت.","ok":0,"eda":"Nej. 90 km/t gælder kun, hvor det er skiltet.","efa":"خیر. ۹۰ کیلومتر بر ساعت فقط جایی است که تابلو داشته باشد.","en":"90 km/h.","een":"No. 90 km/h only applies where it is signed."},{"da":"80 km/t.","fa":"۸۰ کیلومتر بر ساعت.","ok":1,"eda":"Ja. Uden for tættere bebygget område er den generelle grænse 80 km/t.","efa":"بله. بیرون از مناطق مسکونی حد عمومی ۸۰ کیلومتر بر ساعت است.","en":"80 km/h.","een":"Yes. Outside built-up areas the general limit is 80 km/h."}]},{"id":5122,"img":"newq-art/5122.png","c":"7.3","sda":"Der er tæt tåge, og du kan kun se omkring 50 m frem. Hvordan forholder du dig?","sfa":"مه غلیظ است و فقط حدود ۵۰ متر جلو را می‌بینید. چه می‌کنید؟","sen":"There is thick fog, and you can only see about 50 m ahead. What do you do?","st":[{"da":"Jeg må bruge tågelygter.","fa":"می‌توانم از چراغ مه‌شکن استفاده کنم.","ok":1,"eda":"Ja. Tågelygter må bruges i tåge og under kraftig nedbør.","efa":"بله. چراغ مه‌شکن در مه و بارش شدید مجاز است.","en":"I may use fog lights.","een":"Yes. Fog lights may be used in fog and heavy precipitation."},{"da":"Jeg kører så langsomt, at jeg kan standse på den strækning, jeg kan se.","fa":"آن‌قدر آهسته می‌رانم که بتوانم در فاصله‌ای که می‌بینم بایستم.","ok":1,"eda":"Ja. Du skal kunne standse på den del af vejen, du har udsyn over.","efa":"بله. باید بتوانید در بخشی از جاده که می‌بینید بایستید.","en":"I drive so slowly that I can stop within the distance I can see.","een":"Yes. You must be able to stop within the part of the road you can see."},{"da":"Jeg holder større afstand til bilen foran.","fa":"فاصله‌ی بیشتری با خودروی جلو نگه می‌دارم.","ok":1,"eda":"Ja. I tåge har du brug for mere tid til at reagere.","efa":"بله. در مه به زمان بیشتری برای واکنش نیاز دارید.","en":"I keep a greater distance to the car in front.","een":"Yes. In fog you need more time to react."},{"da":"Jeg tænder fjernlyset for at se længere.","fa":"نور بالا را روشن می‌کنم تا دورتر را ببینم.","ok":0,"eda":"Nej. I tåge reflekteres fjernlyset og blænder dig selv.","efa":"خیر. در مه نور بالا بازتاب می‌شود و خودتان را خیره می‌کند.","en":"I switch on the high beam to see further.","een":"No. In fog the high beam is reflected and dazzles you yourself."}]},{"id":5123,"img":"newq-art/5123.png","c":"7.3","sda":"Der står store vandpytter langs kantstenen, og der går fodgængere på fortovet. Hvordan forholder du dig?","sfa":"کنار جدول چاله‌های بزرگ آب است و عابران در پیاده‌رو راه می‌روند. چه می‌کنید؟","sen":"There are big puddles along the kerb, and pedestrians are walking on the pavement. What do you do?","st":[{"da":"Det er fodgængernes eget ansvar at holde afstand til vandet.","fa":"دور ماندن از آب وظیفه‌ی خود عابران است.","ok":0,"eda":"Nej. Det er den kørendes pligt at undgå at tilstænke andre.","efa":"خیر. وظیفه‌ی راننده است که آب روی دیگران نپاشد.","en":"It is the pedestrians' own job to keep away from the water.","een":"No. It is the driver's duty to avoid splashing others."},{"da":"Jeg sænker farten, så jeg ikke sprøjter vand på dem.","fa":"سرعتم را کم می‌کنم تا آب روی آن‌ها نپاشد.","ok":1,"eda":"Ja. I dårligt føre skal du afpasse hastigheden, så andre så vidt muligt ikke bliver tilstænket.","efa":"بله. در شرایط بد باید سرعت را طوری تنظیم کنید که تا جای ممکن آب روی دیگران پاشیده نشود.","en":"I slow down so that I do not splash water on them.","een":"Yes. In poor conditions you must adjust your speed so that others are not splashed as far as possible."},{"da":"Jeg kører hurtigt forbi, så det er hurtigt overstået.","fa":"تند رد می‌شوم تا زود تمام شود.","ok":0,"eda":"Nej. Høj fart sprøjter mest.","efa":"خیر. سرعت زیاد بیشترین آب را می‌پاشد.","en":"I drive past fast so that it is over quickly.","een":"No. High speed splashes the most."}]},{"id":5124,"img":"newq-art/5124.png","c":"1.2","sda":"Cyklerne på din cykelholder dækker bilens nummerplade og den ene baglygte. Hvad gælder?","sfa":"دوچرخه‌های روی دوچرخه‌بر، پلاک خودرو و یکی از چراغ‌های عقب را پوشانده‌اند. چه قاعده‌ای برقرار است؟","sen":"The bicycles on your bike rack cover the car's number plate and one of the rear lights. What applies?","st":[{"da":"Lasten må ikke skjule nummerpladen eller de påbudte lygter.","fa":"بار نباید پلاک یا چراغ‌های الزامی را بپوشاند.","ok":1,"eda":"Ja. Gods skal anbringes, så påbudte lygter og nummerpladen ikke skjules.","efa":"بله. بار باید طوری گذاشته شود که چراغ‌های الزامی و پلاک پوشانده نشوند.","en":"The load must not cover the number plate or the required lights.","een":"Yes. Goods must be placed so that the required lights and the number plate are not covered."},{"da":"Det er tilladt, hvis jeg højst kører 50 km/t.","fa":"اگر حداکثر ۵۰ کیلومتر بر ساعت بروم، مجاز است.","ok":0,"eda":"Nej. Reglen gælder uanset farten.","efa":"خیر. این قاعده، سرعت هر چه باشد، برقرار است.","en":"It is allowed if I drive at most 50 km/h.","een":"No. The rule applies whatever the speed."},{"da":"Det er tilladt, når cyklerne er spændt godt fast.","fa":"وقتی دوچرخه‌ها محکم بسته شده‌اند، مجاز است.","ok":0,"eda":"Nej. Lasten skal både sidde fast og lade lygter og nummerplade være synlige.","efa":"خیر. بار هم باید محکم باشد و هم چراغ‌ها و پلاک را نپوشاند.","en":"It is allowed when the bicycles are firmly strapped on.","een":"No. The load must both be secure and leave the lights and number plate visible."},{"da":"Jeg kan bruge en ekstra nummerplade på cykelholderen.","fa":"می‌توانم روی دوچرخه‌بر یک پلاک اضافه بگذارم.","ok":1,"eda":"Ja. En ekstra (tredje) nummerplade skal bruges, når bilens bageste nummerplade er helt eller delvis dækket.","efa":"بله. وقتی پلاک عقب خودرو کاملاً یا تا حدی پوشیده است، باید از پلاک اضافه (سوم) استفاده کرد.","en":"I can use an extra number plate on the bike rack.","een":"Yes. An extra (third) number plate must be used when the car's rear number plate is fully or partly covered."}]},{"id":5125,"img":"newq-art/5125.png","c":"1.2","sda":"Du skal til at køre. Hvad skal du som fører holde øje med, at bilen er i orden?","sfa":"می‌خواهید راه بیفتید. به‌عنوان راننده باید مراقب سالم بودن چه چیزهایی در خودرو باشید؟","sen":"You are about to drive. What must you as the driver check that the car is in order?","st":[{"da":"Styretøjet.","fa":"فرمان.","ok":1,"eda":"Ja. Fejl i styretøjet kan gøre bilen umulig at styre.","efa":"بله. عیب فرمان ممکن است هدایت خودرو را ناممکن کند.","en":"The steering.","een":"Yes. A fault in the steering can make the car impossible to steer."},{"da":"Intet; det er kun ejerens ansvar.","fa":"هیچ؛ این فقط وظیفه‌ی مالک است.","ok":0,"eda":"Nej. Ejeren har ansvaret for bilens lovlige stand, men føreren skal også selv kontrollere den.","efa":"خیر. مالک مسئول وضعیت قانونی خودروست، ولی راننده هم باید خودش آن را بررسی کند.","en":"Nothing; it is only the owner's job.","een":"No. The owner is responsible for the car's lawful condition, but the driver must check it too."},{"da":"Bremserne.","fa":"ترمزها.","ok":1,"eda":"Ja. Føreren skal hele tiden påse, at styre-, bremse-, signal- og tegngivningsapparater samt lygter er i forsvarlig stand.","efa":"بله. راننده باید همیشه مراقب باشد فرمان، ترمز، وسایل علامت‌دهی و چراغ‌ها در وضعیت ایمنی باشند.","en":"The brakes.","een":"Yes. The driver must always see to it that the steering, brakes, signalling equipment and lights are in a safe condition."},{"da":"Lygterne og blinklysene.","fa":"چراغ‌ها و راهنماها.","ok":1,"eda":"Ja. Bilen skal kunne ses, og dine tegn skal kunne forstås.","efa":"بله. خودرو باید دیده شود و علامت‌هایتان فهمیده شود.","en":"The lights and the indicators.","een":"Yes. The car must be visible and your signals understood."}]},{"id":5126,"img":"newq-art/5126.png","c":"7.18","sda":"Du kører forbi denne tavle og vil sætte en passager af lidt længere fremme. Hvad gælder?","sfa":"از کنار این تابلو رد می‌شوید و می‌خواهید کمی جلوتر مسافری را پیاده کنید. چه قاعده‌ای برقرار است؟","sen":"You pass this sign and want to let a passenger out a little further on. What applies?","st":[{"da":"Forbuddet gælder frem til næste vejkryds, når der ikke er andre tavler.","fa":"وقتی تابلوی دیگری نباشد، این ممنوعیت تا تقاطع بعدی برقرار است.","ok":1,"eda":"Ja. Parkeringsforbuddet gælder i færdselsretningen frem til næste kryds.","efa":"بله. ممنوعیت پارک در جهت حرکت تا تقاطع بعدی برقرار است.","en":"The ban applies up to the next junction when there are no other signs.","een":"Yes. The parking ban applies in the direction of travel up to the next junction."},{"da":"Tavlen forbyder også en kort standsning for at sætte en passager af.","fa":"این تابلو توقف کوتاه برای پیاده کردن مسافر را هم ممنوع می‌کند.","ok":0,"eda":"Nej. Det er tavlen med det røde kryds (C 61), der forbyder standsning.","efa":"خیر. تابلوی ضربدر قرمز (C 61) است که توقف را ممنوع می‌کند.","en":"The sign also forbids a short stop to let a passenger out.","een":"No. It is the sign with the red cross (C 61) that forbids stopping."},{"da":"Jeg må godt standse kort for at lade passageren stige ud.","fa":"می‌توانم کوتاه بایستم تا مسافر پیاده شود.","ok":1,"eda":"Ja. Tavlen (C 62) forbyder parkering, ikke en kort standsning for at lade passagerer stige af.","efa":"بله. این تابلو (C 62) پارک را ممنوع می‌کند، نه توقف کوتاه برای پیاده کردن مسافر.","en":"I may stop briefly to let the passenger get out.","een":"Yes. The sign (C 62) forbids parking, not a short stop to let passengers off."},{"da":"Jeg må ikke parkere i denne side af vejen.","fa":"در این سمت جاده نباید پارک کنم.","ok":1,"eda":"Ja. Forbuddet gælder i den vejside, hvor tavlen står.","efa":"بله. این ممنوعیت در همان سمتی از جاده است که تابلو نصب شده.","en":"I must not park on this side of the road.","een":"Yes. The ban applies on the side of the road where the sign stands."}]},{"id":5127,"img":"newq-art/5127.png","c":"7.18","sda":"Du vil parkere på pladsen lige efter krydset, omkring 5 m efter den tværgående vej. Hvad gælder?","sfa":"می‌خواهید در جای خالی درست بعد از تقاطع، حدود ۵ متر بعد از جاده‌ی متقاطع، پارک کنید. چه قاعده‌ای برقرار است؟","sen":"You want to park in the space just after the junction, about 5 m past the crossing road. What applies?","st":[{"da":"Det er forbudt, fordi forbuddet gælder inden for 10 m fra den tværgående kørebanes kant, også efter krydset.","fa":"ممنوع است، چون این ممنوعیت تا ۱۰ متری لبه‌ی سواره‌روی متقاطع است، بعد از تقاطع هم.","ok":1,"eda":"Ja. Standsning og parkering er forbudt i vejkryds og inden for 10 m fra den tværgående kørebanes nærmeste kant.","efa":"بله. توقف و پارک در تقاطع و تا ۱۰ متری نزدیک‌ترین لبه‌ی سواره‌روی متقاطع ممنوع است.","en":"It is forbidden, because the ban applies within 10 m of the edge of the crossing carriageway, also after the junction.","een":"Yes. Stopping and parking are forbidden in a junction and within 10 m of the nearest edge of the crossing carriageway."},{"da":"Holdende biler tæt ved krydset kan tage oversigten fra dem, der svinger.","fa":"خودروهای ایستاده نزدیک تقاطع می‌توانند دید کسانی را که می‌پیچند بگیرند.","ok":1,"eda":"Ja. Derfor skal der være fri oversigt omkring krydset.","efa":"بله. به همین دلیل اطراف تقاطع باید دید آزاد باشد.","en":"Cars standing close to the junction can block the view of those turning.","een":"Yes. That is why there must be a clear view around the junction."},{"da":"Forbuddet gælder kun før krydset.","fa":"این ممنوعیت فقط پیش از تقاطع است.","ok":0,"eda":"Nej. Afstanden regnes fra den tværgående kørebane, så den gælder på begge sider af den.","efa":"خیر. فاصله از سواره‌روی متقاطع حساب می‌شود، پس در هر دو طرف آن برقرار است.","en":"The ban only applies before the junction.","een":"No. The distance is counted from the crossing carriageway, so it applies on both sides of it."},{"da":"Det er tilladt, fordi jeg holder i højre side.","fa":"مجاز است، چون در سمت راست می‌ایستم.","ok":0,"eda":"Nej. Den rigtige side gør ikke afstanden til krydset lovlig.","efa":"خیر. سمت درست، فاصله‌ی کم از تقاطع را مجاز نمی‌کند.","en":"It is allowed because I am standing on the right-hand side.","een":"No. The right side does not make the distance to the junction legal."}]},{"id":5128,"img":"newq-art/5128.png","c":"7.18","sda":"Du vil standse ved kanten af en smal vej. Mellem bilen og spærrelinjen midt på vejen vil der kun være 2 m. Hvad gælder?","sfa":"می‌خواهید کنار یک جاده‌ی باریک بایستید. بین خودرو و خط ممتد وسط جاده فقط ۲ متر فاصله خواهد بود. چه قاعده‌ای برقرار است؟","sen":"You want to stop at the edge of a narrow road. Between the car and the barrier line in the middle of the road there will only be 2 m. What applies?","st":[{"da":"Det er tilladt, hvis jeg tænder havariblinket.","fa":"اگر چراغ خطر را روشن کنم، مجاز است.","ok":0,"eda":"Nej. Havariblinket ændrer ikke på forbuddet.","efa":"خیر. چراغ خطر ممنوعیت را تغییر نمی‌دهد.","en":"It is allowed if I switch on the hazard lights.","een":"No. The hazard lights do not change the ban."},{"da":"Reglen gælder kun for lastbiler.","fa":"این قاعده فقط برای کامیون‌هاست.","ok":0,"eda":"Nej. Reglen gælder alle køretøjer.","efa":"خیر. این قاعده برای همه‌ی وسایل است.","en":"The rule only applies to lorries.","een":"No. The rule applies to all vehicles."},{"da":"Jeg må ikke standse her, fordi afstanden til spærrelinjen er under 3 m.","fa":"نباید این‌جا بایستم، چون فاصله تا خط ممتد کمتر از ۳ متر است.","ok":1,"eda":"Ja. Standsning og parkering er forbudt ved siden af en spærrelinje, hvis afstanden mellem køretøjet og linjen er mindre end 3 m.","efa":"بله. توقف و پارک کنار خط ممتد، اگر فاصله‌ی خودرو تا خط کمتر از ۳ متر باشد، ممنوع است.","en":"I must not stop here because the distance to the barrier line is under 3 m.","een":"Yes. Stopping and parking are forbidden beside a barrier line if the distance between the vehicle and the line is less than 3 m."}]},{"id":5129,"img":"newq-art/5129.png","c":"7.18","sda":"Du vil parkere, så du kommer til at holde lige foran en anden bil, der så ikke kan køre ud. Hvad gælder?","sfa":"می‌خواهید طوری پارک کنید که درست جلوی خودروی دیگری قرار بگیرید و آن خودرو نتواند بیرون برود. چه قاعده‌ای برقرار است؟","sen":"You want to park so that you will stand right in front of another car, which then cannot drive out. What applies?","st":[{"da":"Det er forbudt at parkere, så en anden bil ikke kan komme ud.","fa":"پارکی که خودروی دیگری را گیر بیندازد ممنوع است.","ok":1,"eda":"Ja. Parkering må ikke ske, så adgangen til et andet køretøj hindres, eller det ikke kan køre væk.","efa":"بله. پارک نباید راه دسترسی به وسیله‌ی دیگر را ببندد یا مانع حرکتش شود.","en":"It is forbidden to park so that another car cannot get out.","een":"Yes. Parking must not block access to another vehicle or stop it from being driven away."},{"da":"Det er tilladt, når jeg kun er væk i kort tid.","fa":"اگر فقط مدت کوتاهی دور باشم، مجاز است.","ok":0,"eda":"Nej. Også kort tid kan forhindre den anden i at køre.","efa":"خیر. حتی مدت کوتاه هم می‌تواند مانع رفتن دیگری شود.","en":"It is allowed when I am only gone for a short while.","een":"No. Even a short while can stop the other driver from leaving."},{"da":"Det er den andens problem, når jeg holder ved kanten.","fa":"اگر کنار لبه بایستم، مشکل خود اوست.","ok":0,"eda":"Nej. Forbuddet gælder, uanset hvor du holder.","efa":"خیر. این ممنوعیت هر جا بایستید برقرار است.","en":"It is the other driver's problem as long as I stand at the edge.","een":"No. The ban applies wherever you stand."}]},{"id":5130,"img":"newq-art/5130.png","c":"7.18","sda":"Du holder ved kantstenen og skal læsse tunge kasser ud. Hvordan forholder du dig?","sfa":"کنار جدول ایستاده‌اید و باید جعبه‌های سنگینی را خالی کنید. چه می‌کنید؟","sen":"You are standing at the kerb and need to unload heavy boxes. What do you do?","st":[{"da":"Jeg må stille kasserne på kørebanen, mens jeg bærer dem ind.","fa":"می‌توانم جعبه‌ها را تا بردنشان روی سواره‌رو بگذارم.","ok":0,"eda":"Nej. Kasser på kørebanen er en fare for trafikken.","efa":"خیر. جعبه روی سواره‌رو برای ترافیک خطرناک است.","en":"I may put the boxes on the carriageway while I carry them in.","een":"No. Boxes on the carriageway are a danger to traffic."},{"da":"Jeg holder øje med trafikken, mens jeg står ved bilen.","fa":"وقتی کنار خودرو ایستاده‌ام، مراقب ترافیک هستم.","ok":1,"eda":"Ja. Bilister og cyklister kører tæt forbi bilen.","efa":"بله. رانندگان و دوچرخه‌سواران از نزدیک خودرو رد می‌شوند.","en":"I keep an eye on the traffic while I am standing by the car.","een":"Yes. Drivers and cyclists pass close to the car."},{"da":"Jeg må lade førerdøren stå åben ud mod kørebanen, mens jeg læsser.","fa":"می‌توانم در راننده را رو به سواره‌رو باز بگذارم تا بار را خالی کنم.","ok":0,"eda":"Nej. En åben dør ud mod trafikken kan blive ramt og skabe fare.","efa":"خیر. در باز رو به ترافیک ممکن است ضربه بخورد و خطر ایجاد کند.","en":"I may leave the driver's door open towards the carriageway while I unload.","een":"No. An open door towards the traffic can be hit and cause danger."},{"da":"Jeg læsser ud, så der ikke opstår fare eller unødig ulempe for andre.","fa":"طوری بار را خالی می‌کنم که برای دیگران خطر یا مزاحمت بی‌جا پیش نیاید.","ok":1,"eda":"Ja. Åbning af døre og af- og pålæsning skal ske, så der ikke opstår fare eller unødig ulempe.","efa":"بله. باز کردن در و بار زدن یا خالی کردن نباید خطر یا مزاحمت بی‌جا ایجاد کند.","en":"I unload so that there is no danger or undue inconvenience to others.","een":"Yes. Opening doors and loading and unloading must not cause danger or undue inconvenience."}]},{"id":5131,"img":"newq-art/5131.png","c":"7.9","sda":"Du har grønt lys og kører i venstre af to vognbaner. Den langsomme varevogn i højre vognbane skal også ligeud. Hvad gælder for overhaling i krydset?","sfa":"چراغ شما سبز است و در خط چپ از دو خط می‌رانید. ون آهسته در خط راست هم مستقیم می‌رود. درباره‌ی سبقت در تقاطع چه قاعده‌ای برقرار است؟","sen":"You have a green light and are in the left of two lanes. The slow van in the right lane is also going straight on. What applies to overtaking at the junction?","st":[{"da":"Jeg må overhale, selv om mit lys skifter til gult lige før krydset.","fa":"حتی اگر چراغم درست پیش از تقاطع زرد شود، می‌توانم سبقت بگیرم.","ok":0,"eda":"Nej. Gult lys betyder stop, medmindre du er så tæt på, at en standsning vil skabe fare.","efa":"خیر. چراغ زرد یعنی ایست، مگر آن‌قدر نزدیک باشید که ایستادن خطرناک باشد.","en":"I may overtake even if my light changes to yellow just before the junction.","een":"No. Yellow means stop, unless you are so close that stopping would be dangerous."},{"da":"Jeg må overhale i krydset, fordi færdslen reguleres af lyssignal, hvis det kan ske uden fare.","fa":"می‌توانم در تقاطع سبقت بگیرم، چون ترافیک با چراغ کنترل می‌شود، به شرط آن‌که بی‌خطر باشد.","ok":1,"eda":"Ja. Forbuddet mod overhaling i kryds gælder ikke, hvor færdslen reguleres af lyssignal eller politi.","efa":"بله. ممنوعیت سبقت در تقاطع، جایی که ترافیک با چراغ یا پلیس کنترل می‌شود، اعمال نمی‌شود.","en":"I may overtake at the junction because the traffic is controlled by traffic lights, if it can be done safely.","een":"Yes. The ban on overtaking at junctions does not apply where traffic is controlled by traffic lights or police."},{"da":"Det er altid forbudt at overhale i et kryds.","fa":"سبقت در تقاطع همیشه ممنوع است.","ok":0,"eda":"Nej. Der er undtagelser, fx i kryds med lyssignal.","efa":"خیر. استثناهایی هست، مثلاً تقاطع چراغ‌دار.","en":"Overtaking at a junction is always forbidden.","een":"No. There are exceptions, for example at junctions with traffic lights."},{"da":"Jeg holder øje med fodgængere og cyklister, der kan krydse.","fa":"مراقب عابران و دوچرخه‌سوارانی هستم که ممکن است رد شوند.","ok":1,"eda":"Ja. Også med grønt lys skal du være opmærksom i krydset.","efa":"بله. حتی با چراغ سبز هم باید در تقاطع حواستان جمع باشد.","en":"I watch out for pedestrians and cyclists who may cross.","een":"Yes. Even with a green light you must be attentive at the junction."}]},{"id":5132,"img":"newq-art/5132.png","c":"7.9","sda":"Vejen svinger, og du kan ikke se, om der kommer modkørende. Lastbilen foran dig blinker til højre. Hvad gælder?","sfa":"جاده می‌پیچد و نمی‌بینید خودرویی از روبه‌رو می‌آید یا نه. کامیون جلوی شما راهنمای راست زده است. چه قاعده‌ای برقرار است؟","sen":"The road bends, and you cannot see whether anything is coming. The lorry in front of you is indicating right. What applies?","st":[{"da":"Jeg må overhale, hvis jeg tænder fjernlyset først.","fa":"اگر اول نور بالا را روشن کنم، می‌توانم سبقت بگیرم.","ok":0,"eda":"Nej. Lyset ændrer ikke på, at du ikke kan se de modkørende.","efa":"خیر. چراغ این واقعیت را تغییر نمی‌دهد که ترافیک روبه‌رو را نمی‌بینید.","en":"I may overtake if I switch on the high beam first.","een":"No. The lights do not change the fact that you cannot see oncoming traffic."},{"da":"Jeg må ikke overhale ved det uoverskuelige sving.","fa":"در این پیچ بی‌دید نباید سبقت بگیرم.","ok":1,"eda":"Ja. Overhaling er forbudt, hvor oversigten er begrænset, fx i uoverskuelige sving.","efa":"بله. سبقت جایی که دید محدود است، مثلاً در پیچ بی‌دید، ممنوع است.","en":"I must not overtake at the blind bend.","een":"Yes. Overtaking is forbidden where the view is limited, for example in blind bends."},{"da":"Jeg må overhale, fordi lastbilchaufføren viser, at vejen er fri.","fa":"می‌توانم سبقت بگیرم، چون راننده‌ی کامیون نشان می‌دهد راه باز است.","ok":0,"eda":"Nej. Du skal selv sikre dig, at overhalingen kan ske uden fare; et blink er ikke en garanti.","efa":"خیر. خودتان باید مطمئن شوید سبقت بی‌خطر است؛ چراغ راهنما تضمین نیست.","en":"I may overtake because the lorry driver is showing that the road is clear.","een":"No. You must make sure yourself that the overtaking is safe; an indicator is no guarantee."}]},{"id":5133,"img":"newq-art/5133.png","c":"7.9","sda":"Bilen foran dig kører 75 km/t, og grænsen er 80 km/t. Du overvejer at overhale. Hvad gælder?","sfa":"خودروی جلو ۷۵ کیلومتر بر ساعت می‌رود و حد سرعت ۸۰ است. به سبقت فکر می‌کنید. چه قاعده‌ای برقرار است؟","sen":"The car in front of you is doing 75 km/h, and the limit is 80 km/h. You are thinking of overtaking. What applies?","st":[{"da":"Jeg må ikke køre hurtigere end 80 km/t under overhalingen.","fa":"هنگام سبقت نباید تندتر از ۸۰ کیلومتر بر ساعت برانم.","ok":1,"eda":"Ja. Hastighedsgrænsen gælder også, mens du overhaler.","efa":"بله. حد سرعت هنگام سبقت هم برقرار است.","en":"I must not drive faster than 80 km/h during the overtaking.","een":"Yes. The speed limit also applies while you are overtaking."},{"da":"Det er tilladt at køre hurtigere end grænsen, når jeg overhaler.","fa":"هنگام سبقت مجازم از حد سرعت تندتر بروم.","ok":0,"eda":"Nej. Der er ingen undtagelse fra hastighedsgrænsen ved overhaling.","efa":"خیر. برای سبقت استثنایی از حد سرعت وجود ندارد.","en":"It is allowed to drive faster than the limit when I overtake.","een":"No. There is no exception from the speed limit for overtaking."},{"da":"Overhalingen vil tage lang tid, fordi forskellen i fart er lille.","fa":"سبقت طول می‌کشد، چون اختلاف سرعت کم است.","ok":1,"eda":"Ja. Jo mindre forskel, jo længere er du i den modkørende vognbane.","efa":"بله. هر چه اختلاف کمتر باشد، مدت بیشتری در خط مقابل می‌مانید.","en":"The overtaking will take a long time because the difference in speed is small.","een":"Yes. The smaller the difference, the longer you are in the oncoming lane."},{"da":"Det kan være bedre at blive bag bilen.","fa":"شاید بهتر باشد پشت آن خودرو بمانم.","ok":1,"eda":"Ja. En lang overhaling med lille fartforskel giver meget lidt og øger risikoen.","efa":"بله. سبقت طولانی با اختلاف سرعت کم سود کمی دارد و خطر را بیشتر می‌کند.","en":"It may be better to stay behind the car.","een":"Yes. A long overtaking with little difference in speed gains very little and increases the risk."}]},{"id":5134,"img":"newq-art/5134.png","c":"7.9","sda":"En bil er i gang med at overhale dig, og der kommer en lastbil imod den. Hvordan forholder du dig?","sfa":"خودرویی در حال سبقت از شماست و کامیونی از روبه‌رو به سمتش می‌آید. چه می‌کنید؟","sen":"A car is overtaking you, and a lorry is coming towards it. What do you do?","st":[{"da":"Jeg øger farten, så den overhalende må opgive og trække ind bag mig.","fa":"سرعتم را زیاد می‌کنم تا سبقت‌گیرنده منصرف شود و پشت سرم برگردد.","ok":0,"eda":"Nej. Den, der bliver overhalet, må ikke øge hastigheden.","efa":"خیر. کسی که از او سبقت می‌گیرند نباید سرعتش را زیاد کند.","en":"I speed up so that the overtaking car has to give up and pull in behind me.","een":"No. The driver being overtaken must not increase speed."},{"da":"Jeg sænker farten, så den overhalende hurtigt kan komme ind foran mig.","fa":"سرعتم را کم می‌کنم تا سبقت‌گیرنده زود جلوی من برگردد.","ok":1,"eda":"Ja. Du kan hjælpe med at undgå en farlig situation ved at give plads.","efa":"بله. با جا دادن می‌توانید از یک موقعیت خطرناک جلوگیری کنید.","en":"I slow down so that the overtaking car can quickly pull in in front of me.","een":"Yes. You can help avoid a dangerous situation by making room."},{"da":"Jeg er klar til at bremse, hvis det bliver nødvendigt.","fa":"اگر لازم شد، آماده‌ی ترمز هستم.","ok":1,"eda":"Ja. Situationen kan ændre sig hurtigt.","efa":"بله. این موقعیت ممکن است سریع تغییر کند.","en":"I am ready to brake if it becomes necessary.","een":"Yes. The situation can change quickly."},{"da":"Jeg holder så langt til højre som muligt.","fa":"تا جای ممکن سمت راست می‌مانم.","ok":1,"eda":"Ja. Den, der bliver overhalet, skal holde så langt til højre som muligt.","efa":"بله. کسی که از او سبقت می‌گیرند باید تا جای ممکن سمت راست بماند.","en":"I keep as far to the right as possible.","een":"Yes. The driver being overtaken must keep as far to the right as possible."}]},{"id":5135,"img":"newq-art/5135.png","c":"7.9","sda":"Du holder i kø. En cyklist kører op langs højre side af din bil. Hvad gælder?","sfa":"در صف ایستاده‌اید. دوچرخه‌سواری از سمت راست خودرو جلو می‌آید. چه قاعده‌ای برقرار است؟","sen":"You are standing in a queue. A cyclist is riding up along the right side of your car. What applies?","st":[{"da":"Jeg kører tæt ind mod kantstenen, så cyklisten ikke kan komme forbi.","fa":"به جدول نزدیک می‌شوم تا دوچرخه‌سوار نتواند رد شود.","ok":0,"eda":"Nej. Du må ikke spærre for cyklisten; det kan skabe fare.","efa":"خیر. نباید راه دوچرخه‌سوار را ببندید؛ ممکن است خطرناک باشد.","en":"I move close to the kerb so that the cyclist cannot get past.","een":"No. You must not block the cyclist; it can be dangerous."},{"da":"Jeg ser efter cyklister i højre side, før jeg svinger til højre.","fa":"پیش از گردش به راست، دوچرخه‌سواران سمت راست را نگاه می‌کنم.","ok":1,"eda":"Ja. En cyklist kan være i din blinde vinkel i højre side.","efa":"بله. دوچرخه‌سوار ممکن است در نقطه‌ی کور سمت راستتان باشد.","en":"I look for cyclists on the right before I turn right.","een":"Yes. A cyclist may be in your blind spot on the right."},{"da":"Cyklister må overhale biler i højre side.","fa":"دوچرخه‌سواران می‌توانند از سمت راست از خودروها سبقت بگیرند.","ok":1,"eda":"Ja. Cyklister og førere af lille knallert kan overhale andre køretøjer til højre.","efa":"بله. دوچرخه‌سواران و موپدسواران کوچک می‌توانند از سمت راست از وسایل دیگر سبقت بگیرند.","en":"Cyclists may overtake cars on the right.","een":"Yes. Cyclists and riders of small mopeds may overtake other vehicles on the right."},{"da":"Cyklisten gør noget ulovligt.","fa":"دوچرخه‌سوار کار غیرقانونی می‌کند.","ok":0,"eda":"Nej. Cyklister må gerne overhale biler i højre side.","efa":"خیر. دوچرخه‌سواران اجازه دارند از سمت راست از خودروها سبقت بگیرند.","en":"The cyclist is doing something illegal.","een":"No. Cyclists may well overtake cars on the right."}]},{"id":5136,"img":"newq-art/5136.png","c":"6.1","sda":"Du kører forbi denne tavle. Hvad betyder den, og hvordan forholder du dig?","sfa":"از کنار این تابلو رد می‌شوید. یعنی چه و چه می‌کنید؟","sen":"You pass this sign. What does it mean, and what do you do?","st":[{"da":"Der er særlig fare, fordi cyklister kan køre ind på eller over kørebanen.","fa":"خطر ویژه‌ای هست، چون ممکن است دوچرخه‌سواران وارد سواره‌رو شوند یا از عرض آن رد شوند.","ok":1,"eda":"Ja. Tavlen (A 21) advarer om steder, hvor cyklister og førere af lille knallert kører ind på eller over kørebanen.","efa":"بله. این تابلو (A 21) درباره‌ی جاهایی هشدار می‌دهد که دوچرخه‌سواران و موپدسواران کوچک وارد سواره‌رو می‌شوند یا از آن رد می‌شوند.","en":"There is a special danger because cyclists may ride onto or across the carriageway.","een":"Yes. The sign (A 21) warns of places where cyclists and riders of small mopeds ride onto or across the carriageway."},{"da":"Tavlen betyder, at der er cykelsti langs hele vejen.","fa":"این تابلو یعنی در تمام طول جاده مسیر دوچرخه هست.","ok":0,"eda":"Nej. Det er en advarsel om en særlig fare, ikke en oplysning om cykelsti.","efa":"خیر. این هشدار خطر ویژه است، نه اطلاع درباره‌ی مسیر دوچرخه.","en":"The sign means that there is a cycle path all along the road.","een":"No. It is a warning of a special danger, not information about a cycle path."},{"da":"Jeg sænker farten og holder øje med cyklisterne.","fa":"سرعتم را کم می‌کنم و مراقب دوچرخه‌سواران هستم.","ok":1,"eda":"Ja. Ved en advarselstavle skal du være klar til at reagere.","efa":"بله. کنار تابلوی هشدار باید آماده‌ی واکنش باشید.","en":"I slow down and watch the cyclists.","een":"Yes. At a warning sign you must be ready to react."},{"da":"Tavlen betyder, at cyklisterne skal holde tilbage for mig.","fa":"این تابلو یعنی دوچرخه‌سواران باید به من راه بدهند.","ok":0,"eda":"Nej. En advarselstavle siger ikke noget om vigepligt.","efa":"خیر. تابلوی هشدار چیزی درباره‌ی حق تقدم نمی‌گوید.","en":"The sign means that the cyclists must give way to me.","een":"No. A warning sign says nothing about who gives way."}]},{"id":5137,"img":"newq-art/5137.png","c":"6.1","sda":"Du kører forbi denne tavle i skumringen. Hvordan forholder du dig?","sfa":"هنگام غروب از کنار این تابلو رد می‌شوید. چه می‌کنید؟","sen":"You pass this sign at dusk. What do you do?","st":[{"da":"Jeg sænker farten og er klar til at bremse.","fa":"سرعتم را کم می‌کنم و آماده‌ی ترمز هستم.","ok":1,"eda":"Ja. Med lavere fart kan du nå at standse, hvis et dyr springer frem.","efa":"بله. با سرعت کمتر، اگر حیوانی بیرون بپرد، به موقع می‌ایستید.","en":"I slow down and am ready to brake.","een":"Yes. At a lower speed you can stop in time if an animal jumps out."},{"da":"Kommer der ét dyr over vejen, kan der komme flere.","fa":"اگر یک حیوان از جاده رد شود، ممکن است بقیه هم بیایند.","ok":1,"eda":"Ja. Hjorte og rådyr går ofte i flok.","efa":"بله. آهوها و گوزن‌ها اغلب گروهی حرکت می‌کنند.","en":"If one animal crosses the road, more may follow.","een":"Yes. Deer often move in groups."},{"da":"Jeg regner med, at der pludselig kan komme dyr ud på vejen.","fa":"انتظار دارم ناگهان حیوانی وارد جاده شود.","ok":1,"eda":"Ja. Tavlen (A 26) advarer om vildt; i skumringen er dyrene særligt aktive.","efa":"بله. این تابلو (A 26) درباره‌ی حیوانات وحشی هشدار می‌دهد؛ هنگام غروب این حیوانات فعال‌ترند.","en":"I expect that animals may suddenly come out onto the road.","een":"Yes. The sign (A 26) warns of wild animals; at dusk they are especially active."},{"da":"Tavlen gælder kun om dagen.","fa":"این تابلو فقط روزها معتبر است.","ok":0,"eda":"Nej. Tavlen gælder hele døgnet, og faren er ofte størst i skumring og mørke.","efa":"خیر. این تابلو در تمام شبانه‌روز معتبر است و خطر اغلب در غروب و تاریکی بیشتر است.","en":"The sign only applies in the daytime.","een":"No. The sign applies day and night, and the danger is often greatest at dusk and in the dark."}]},{"id":5138,"img":"newq-art/5138.png","c":"6.1","sda":"Du kører forbi denne tavle. Hvad betyder den?","sfa":"از کنار این تابلو رد می‌شوید. یعنی چه؟","sen":"You pass this sign. What does it mean?","st":[{"da":"Påbuddet ophører ved næste kryds.","fa":"این دستور در تقاطع بعدی تمام می‌شود.","ok":0,"eda":"Nej. Det gælder, indtil det ophæves af tavlen for ophør af mindste hastighed eller en afstand på en undertavle.","efa":"خیر. تا وقتی تابلوی پایان حداقل سرعت یا فاصله‌ی روی تابلوی زیرین آن را لغو کند، برقرار است.","en":"The order ends at the next junction.","een":"No. It applies until it is lifted by the end-of-minimum-speed sign or a distance on a plate."},{"da":"Tavlen angiver den højst tilladte hastighed.","fa":"این تابلو حداکثر سرعت مجاز را نشان می‌دهد.","ok":0,"eda":"Nej. Den højst tilladte hastighed vises på en hvid tavle med rød kant.","efa":"خیر. حداکثر سرعت روی تابلوی سفید با حاشیه‌ی قرمز نشان داده می‌شود.","en":"The sign gives the highest permitted speed.","een":"No. The highest permitted speed is shown on a white sign with a red border."},{"da":"Påbuddet gælder ikke cyklister og førere af lille knallert.","fa":"این دستور برای دوچرخه‌سواران و موپدسواران کوچک نیست.","ok":1,"eda":"Ja. Mindste hastighed gælder kørende bortset fra cyklister og førere af lille knallert.","efa":"بله. حداقل سرعت برای همه به‌جز دوچرخه‌سواران و موپدسواران کوچک است.","en":"The order does not apply to cyclists and riders of small mopeds.","een":"Yes. The minimum speed applies to drivers other than cyclists and riders of small mopeds."},{"da":"Tavlen angiver en mindste hastighed for strækningen.","fa":"این تابلو حداقل سرعت این مسیر را نشان می‌دهد.","ok":1,"eda":"Ja. Den blå runde tavle med et tal (D 55) er et påbud om mindste hastighed.","efa":"بله. تابلوی گرد آبی با عدد (D 55) دستور حداقل سرعت است.","en":"The sign gives a minimum speed for the stretch.","een":"Yes. The round blue sign with a number (D 55) is an order to keep a minimum speed."}]},{"id":5139,"img":"newq-art/5139.png","c":"6.1","sda":"Du kører en varevogn med last på taget; den samlede højde er 3,7 m. Foran viadukten står denne tavle. Hvad gælder?","sfa":"با یک ون که روی سقفش بار دارد می‌رانید؛ ارتفاع کل ۳٫۷ متر است. پیش از پل این تابلو هست. چه قاعده‌ای برقرار است؟","sen":"You are driving a van with a load on the roof; the total height is 3.7 m. This sign stands before the viaduct. What applies?","st":[{"da":"Jeg må køre igennem, hvis jeg kører meget langsomt.","fa":"اگر خیلی آهسته بروم، می‌توانم رد شوم.","ok":0,"eda":"Nej. Lav fart gør ikke køretøjet lavere.","efa":"خیر. سرعت کم وسیله را کوتاه‌تر نمی‌کند.","en":"I may drive through if I go very slowly.","een":"No. Low speed does not make the vehicle lower."},{"da":"Tavlen gælder kun for lastbiler.","fa":"این تابلو فقط برای کامیون‌هاست.","ok":0,"eda":"Nej. Tavlen gælder alle køretøjer, der er højere end angivet.","efa":"خیر. این تابلو برای هر وسیله‌ای است که بلندتر از عدد نشان‌داده باشد.","en":"The sign only applies to lorries.","een":"No. The sign applies to every vehicle that is higher than shown."},{"da":"Jeg må ikke køre under viadukten, fordi højden med last er over 3,5 m.","fa":"نباید از زیر پل رد شوم، چون ارتفاع با بار بیش از ۳٫۵ متر است.","ok":1,"eda":"Ja. Tavlen (C 42) forbyder kørsel med køretøjer, hvis højde inklusive læs er større end den angivne.","efa":"بله. این تابلو (C 42) عبور وسایلی را که ارتفاعشان با بار بیش از عدد نشان‌داده است، ممنوع می‌کند.","en":"I must not drive under the viaduct because the height with the load is over 3.5 m.","een":"Yes. The sign (C 42) forbids driving with vehicles whose height including the load is greater than the one shown."},{"da":"Tavlen gælder kun bilens egen højde uden last.","fa":"این تابلو فقط برای ارتفاع خود خودرو بدون بار است.","ok":0,"eda":"Nej. Højden regnes inklusive læs.","efa":"خیر. ارتفاع با احتساب بار حساب می‌شود.","en":"The sign only applies to the car's own height without the load.","een":"No. The height is counted including the load."}]},{"id":5140,"img":"newq-art/5140.png","c":"7.6","sda":"En ældre mand går langsomt over vejen et stykke fra et fodgængerfelt. Hvordan forholder du dig?","sfa":"مرد مسنی دور از گذرگاه عابر آهسته از عرض خیابان رد می‌شود. چه می‌کنید؟","sen":"An elderly man is slowly crossing the road some way from a pedestrian crossing. What do you do?","st":[{"da":"Jeg dytter, så han skynder sig.","fa":"بوق می‌زنم تا عجله کند.","ok":0,"eda":"Nej. Hornet kan forskrække ham, så han falder eller standser midt på vejen.","efa":"خیر. بوق ممکن است او را بترساند تا بیفتد یا وسط خیابان بایستد.","en":"I sound the horn so that he hurries.","een":"No. The horn may startle him so that he falls or stops in the middle of the road."},{"da":"Ældre kan have svært ved at bedømme bilernes fart.","fa":"سالمندان ممکن است سرعت خودروها را به‌سختی بسنجند.","ok":1,"eda":"Ja. De kan også bevæge sig langsommere end ventet.","efa":"بله. ممکن است آهسته‌تر از انتظار هم حرکت کنند.","en":"Elderly people may find it hard to judge the speed of cars.","een":"Yes. They may also move more slowly than expected."},{"da":"Han skal vente, fordi han ikke går i et fodgængerfelt.","fa":"او باید صبر کند، چون از گذرگاه عابر رد نمی‌شود.","ok":0,"eda":"Nej. Også uden for et fodgængerfelt skal du undgå at bringe gående i fare.","efa":"خیر. حتی بیرون از گذرگاه عابر هم نباید عابران را به خطر بیندازید.","en":"He has to wait because he is not on a pedestrian crossing.","een":"No. Even outside a pedestrian crossing you must avoid putting pedestrians in danger."},{"da":"Jeg sænker farten og lader ham komme over.","fa":"سرعتم را کم می‌کنم و می‌گذارم رد شود.","ok":1,"eda":"Ja. Du skal vise særligt hensyn over for ældre og give gående tid og plads.","efa":"بله. باید به سالمندان ملاحظه‌ی ویژه نشان دهید و به عابران وقت و جا بدهید.","en":"I slow down and let him get across.","een":"Yes. You must show special consideration for the elderly and give pedestrians time and room."}]},{"id":5141,"img":"newq-art/5141.png","c":"7.6","sda":"Du kører forbi en række parkerede biler. I en af dem sidder føreren og ser ud til at ville stige ud. Hvordan forholder du dig?","sfa":"از کنار ردیفی از خودروهای پارک‌شده رد می‌شوید. راننده‌ی یکی از آن‌ها نشسته و به نظر می‌رسد می‌خواهد پیاده شود. چه می‌کنید؟","sen":"You are passing a row of parked cars. In one of them the driver is sitting and seems about to get out. What do you do?","st":[{"da":"Jeg sænker farten og er klar til at bremse.","fa":"سرعتم را کم می‌کنم و آماده‌ی ترمز هستم.","ok":1,"eda":"Ja. Så kan du standse, hvis døren åbnes, eller føreren træder ud.","efa":"بله. این‌طور اگر در باز شد یا راننده بیرون آمد، می‌توانید بایستید.","en":"I slow down and am ready to brake.","een":"Yes. Then you can stop if the door opens or the driver steps out."},{"da":"Føreren skal se sig for, så jeg behøver ikke gøre noget.","fa":"راننده باید خودش نگاه کند، پس لازم نیست کاری بکنم.","ok":0,"eda":"Nej. Du skal selv være forberedt på, at andre laver fejl.","efa":"خیر. خودتان باید برای اشتباه دیگران آماده باشید.","en":"The driver must look out, so I need not do anything.","een":"No. You must be prepared yourself for others to make mistakes."},{"da":"Jeg kigger efter folk i de parkerede biler.","fa":"به دنبال آدم‌هایی در خودروهای پارک‌شده نگاه می‌کنم.","ok":1,"eda":"Ja. En person i en parkeret bil kan være på vej ud.","efa":"بله. کسی که در خودروی پارک‌شده نشسته، ممکن است در حال پیاده شدن باشد.","en":"I look for people in the parked cars.","een":"Yes. A person in a parked car may be about to get out."},{"da":"Jeg holder god afstand til siden, så jeg ikke rammer en dør, der åbnes.","fa":"از پهلو فاصله‌ی خوبی نگه می‌دارم تا به دری که باز می‌شود نخورم.","ok":1,"eda":"Ja. En dør kan pludselig blive åbnet ud mod kørebanen.","efa":"بله. ممکن است دری ناگهان رو به سواره‌رو باز شود.","en":"I keep a good distance to the side so that I do not hit a door that opens.","een":"Yes. A door may suddenly be opened out into the carriageway."}]},{"id":5142,"img":"newq-art/5142.png","c":"7.6","sda":"En isbil holder ved vejen, og der er børn omkring den. Hvordan forholder du dig?","sfa":"ماشین بستنی‌فروشی کنار خیابان ایستاده و بچه‌ها دورش هستند. چه می‌کنید؟","sen":"An ice-cream van has stopped by the road, and there are children around it. What do you do?","st":[{"da":"Jeg holder øje med begge sider af vejen.","fa":"مراقب هر دو طرف خیابان هستم.","ok":1,"eda":"Ja. Børn kan komme løbende fra den anden side.","efa":"بله. ممکن است بچه‌ها از طرف دیگر بدوند.","en":"I watch both sides of the road.","een":"Yes. Children may come running from the other side."},{"da":"Jeg dytter, så børnene holder sig på fortovet.","fa":"بوق می‌زنم تا بچه‌ها در پیاده‌رو بمانند.","ok":0,"eda":"Nej. Hornet kan få et barn til at gøre noget uventet; sænk i stedet farten.","efa":"خیر. بوق ممکن است کودک را به کار غیرمنتظره‌ای وادارد؛ به‌جایش سرعت را کم کنید.","en":"I sound the horn so that the children stay on the pavement.","een":"No. The horn can make a child do something unexpected; slow down instead."},{"da":"Jeg sænker farten kraftigt og er klar til at standse.","fa":"سرعتم را خیلی کم می‌کنم و آماده‌ی ایستادنم.","ok":1,"eda":"Ja. Når du nærmer dig børn på eller ved vejen, skal hastigheden være passende lav.","efa":"بله. وقتی به بچه‌هایی روی جاده یا کنار آن نزدیک می‌شوید، سرعت باید به اندازه‌ی کافی کم باشد.","en":"I slow down a lot and am ready to stop.","een":"Yes. When you approach children on or by the road, your speed must be suitably low."},{"da":"Børn kan løbe over vejen uden at se sig for.","fa":"بچه‌ها ممکن است بی‌آنکه نگاه کنند از خیابان رد شوند.","ok":1,"eda":"Ja. Børn tænker på isen og ikke på trafikken.","efa":"بله. بچه‌ها به بستنی فکر می‌کنند، نه به ترافیک.","en":"Children may run across the road without looking.","een":"Yes. Children think about the ice cream, not about the traffic."}]},{"id":5143,"img":"newq-art/5143.png","c":"7.6","sda":"En bil holder i din vognbane med havariblinket tændt. Hvordan forholder du dig?","sfa":"خودرویی با چراغ خطر روشن در خط شما ایستاده است. چه می‌کنید؟","sen":"A car is standing in your lane with its hazard lights on. What do you do?","st":[{"da":"Havariblinket betyder, at bilen snart kører igen, så jeg venter tæt bag den.","fa":"چراغ خطر یعنی خودرو به‌زودی راه می‌افتد، پس نزدیک پشتش صبر می‌کنم.","ok":0,"eda":"Nej. Havariblink er en advarsel; hold god afstand.","efa":"خیر. چراغ خطر هشدار است؛ فاصله‌ی خوبی نگه دارید.","en":"The hazard lights mean that the car will soon drive on, so I wait close behind it.","een":"No. Hazard lights are a warning; keep a good distance."},{"da":"Jeg sænker farten og kører forbi med god afstand, når det kan ske uden fare.","fa":"سرعتم را کم می‌کنم و وقتی بی‌خطر باشد، با فاصله‌ی خوب رد می‌شوم.","ok":1,"eda":"Ja. Havariblinket advarer om fare; der kan være folk ved bilen.","efa":"بله. چراغ خطر از خطر خبر می‌دهد؛ ممکن است کسی کنار خودرو باشد.","en":"I slow down and pass with a good distance when it can be done safely.","een":"Yes. Hazard lights warn of danger; there may be people by the car."},{"da":"Jeg dytter, så bilen flytter sig.","fa":"بوق می‌زنم تا خودرو جابه‌جا شود.","ok":0,"eda":"Nej. Bilen holder sandsynligvis på grund af et problem; dyt hjælper ikke.","efa":"خیر. خودرو احتمالاً به‌خاطر مشکلی ایستاده؛ بوق کمکی نمی‌کند.","en":"I sound the horn so that the car moves.","een":"No. The car is probably standing because of a problem; the horn does not help."},{"da":"Jeg kører forbi med det samme, selv om der kommer en modkørende.","fa":"فوراً رد می‌شوم، حتی اگر خودرویی از روبه‌رو بیاید.","ok":0,"eda":"Nej. Hindringen er i din side, så du skal om nødvendigt standse og lade den modkørende passere.","efa":"خیر. مانع در سمت شماست، پس در صورت لزوم باید بایستید و بگذارید خودروی روبه‌رو رد شود.","en":"I drive past straight away, even though a car is coming the other way.","een":"No. The obstacle is on your side, so you must stop if necessary and let the oncoming car pass."}]},{"id":5144,"img":"newq-art/5144.png","c":"7.12","sda":"Lyset skifter til gult, mens du er 40 m fra krydset og roligt kan standse. Hvordan forholder du dig?","sfa":"چراغ زرد می‌شود، وقتی ۴۰ متر با تقاطع فاصله دارید و می‌توانید آرام بایستید. چه می‌کنید؟","sen":"The light changes to yellow while you are 40 m from the junction and can stop calmly. What do you do?","st":[{"da":"Jeg standser før stoplinjen.","fa":"پیش از خط ایست می‌ایستم.","ok":1,"eda":"Ja. Gult lys betyder stop.","efa":"بله. چراغ زرد یعنی ایست.","en":"I stop before the stop line.","een":"Yes. Yellow means stop."},{"da":"Gult lys gælder kun fodgængere.","fa":"چراغ زرد فقط برای عابران است.","ok":0,"eda":"Nej. Lyssignalet gælder de kørende.","efa":"خیر. این چراغ برای رانندگان است.","en":"Yellow only applies to pedestrians.","een":"No. The traffic light applies to drivers."},{"da":"Gult lys betyder, at jeg skal skynde mig over.","fa":"چراغ زرد یعنی باید عجله کنم و رد شوم.","ok":0,"eda":"Nej. Gult lys betyder stop, ikke kør hurtigere.","efa":"خیر. زرد یعنی ایست، نه تندتر رفتن.","en":"Yellow means that I must hurry across.","een":"No. Yellow means stop, not drive faster."},{"da":"Jeg må kun køre videre, hvis jeg er så tæt på, at en standsning vil skabe fare.","fa":"فقط وقتی می‌توانم ادامه دهم که آن‌قدر نزدیک باشم که ایستادن خطرناک باشد.","ok":1,"eda":"Ja. Den, der er nået så langt frem, at standsning vil medføre fare, behøver ikke standse.","efa":"بله. کسی که آن‌قدر جلو آمده که ایستادن خطر ایجاد کند، لازم نیست بایستد.","en":"I may only drive on if I am so close that stopping would be dangerous.","een":"Yes. Whoever has come so far that stopping would cause danger need not stop."}]},{"id":5145,"img":"newq-art/5145.png","c":"7.12","sda":"Du holder ved stoplinjen, og dit lyssignal viser rødt og gult på samme tid. Hvordan forholder du dig?","sfa":"پشت خط ایست ایستاده‌اید و چراغ شما هم‌زمان قرمز و زرد را نشان می‌دهد. چه می‌کنید؟","sen":"You are waiting at the stop line, and your traffic light shows red and yellow at the same time. What do you do?","st":[{"da":"Jeg holder stille, til lyset bliver grønt.","fa":"تا سبز شدن چراغ می‌ایستم.","ok":1,"eda":"Ja. Rødt og gult lys samtidig betyder stop; det viser, at lyset snart skifter til grønt.","efa":"بله. قرمز و زرد با هم یعنی ایست؛ نشان می‌دهد چراغ به‌زودی سبز می‌شود.","en":"I stay where I am until the light turns green.","een":"Yes. Red and yellow together mean stop; they show that the light will soon change to green."},{"da":"Jeg må køre lidt frem over stoplinjen og vente der.","fa":"می‌توانم کمی از خط ایست جلوتر بروم و آن‌جا صبر کنم.","ok":0,"eda":"Nej. Du skal holde før stoplinjen.","efa":"خیر. باید پیش از خط ایست بایستید.","en":"I may move a little forward over the stop line and wait there.","een":"No. You must wait before the stop line."},{"da":"Jeg må køre, fordi lyset snart bliver grønt.","fa":"می‌توانم حرکت کنم، چون چراغ به‌زودی سبز می‌شود.","ok":0,"eda":"Nej. Du må først køre, når lyset er grønt.","efa":"خیر. فقط وقتی چراغ سبز شد می‌توانید حرکت کنید.","en":"I may go because the light will soon turn green.","een":"No. You may only go when the light is green."},{"da":"Rødt og gult betyder, at jeg må køre, hvis vejen er fri.","fa":"قرمز و زرد یعنی اگر راه باز باشد می‌توانم بروم.","ok":0,"eda":"Nej. Rødt og gult betyder stop, uanset trafikken.","efa":"خیر. قرمز و زرد یعنی ایست، ترافیک هر چه باشد.","en":"Red and yellow mean that I may go if the road is clear.","een":"No. Red and yellow mean stop whatever the traffic."}]},{"id":5146,"img":"newq-art/5146.png","c":"7.12","sda":"Du kommer ad en markvej og skal ud på landevejen. Der er ingen tavler. Hvad gælder?","sfa":"از یک راه خاکی میان مزرعه می‌آیید و می‌خواهید وارد جاده‌ی اصلی شوید. تابلویی نیست. چه قاعده‌ای برقرار است؟","sen":"You are coming along a field road and are going to drive onto the country road. There are no signs. What applies?","st":[{"da":"Traktoren fra venstre skal holde tilbage for mig.","fa":"تراکتوری که از چپ می‌آید باید به من راه بدهد.","ok":0,"eda":"Nej. Du skal holde tilbage for både bilen og traktoren.","efa":"خیر. باید هم به خودرو و هم به تراکتور راه بدهید.","en":"The tractor from the left must give way to me.","een":"No. You must give way to both the car and the tractor."},{"da":"Højrereglen gælder, fordi der ikke er tavler.","fa":"قاعده‌ی دست راست برقرار است، چون تابلویی نیست.","ok":0,"eda":"Nej. Højrereglen gælder ikke for den, der kommer fra en markvej.","efa":"خیر. قاعده‌ی دست راست برای کسی که از راه خاکی مزرعه می‌آید اعمال نمی‌شود.","en":"The right-hand rule applies because there are no signs.","een":"No. The right-hand rule does not apply to someone coming from a field road."},{"da":"Jeg har ubetinget vigepligt for trafikken på landevejen fra begge sider.","fa":"باید بی‌قیدوشرط به ترافیک جاده از هر دو طرف راه بدهم.","ok":1,"eda":"Ja. Kørende ud fra en markvej har ubetinget vigepligt.","efa":"بله. کسی که از راه خاکی مزرعه بیرون می‌آید، باید بی‌قیدوشرط راه بدهد.","en":"I must give way unconditionally to the traffic on the country road from both sides.","een":"Yes. Drivers coming out of a field road must give way unconditionally."}]},{"id":5147,"img":"newq-art/5147.png","c":"7.12","sda":"I krydset uden tavler kommer en cyklist fra højre og en bil fra venstre. Alle skal ligeud. Hvad gælder?","sfa":"در تقاطع بدون تابلو، دوچرخه‌سواری از راست و خودرویی از چپ می‌آید. همه مستقیم می‌روند. چه قاعده‌ای برقرار است؟","sen":"At the junction with no signs a cyclist is coming from the right and a car from the left. Everyone is going straight on. What applies?","st":[{"da":"Bilen fra venstre skal holde tilbage for mig.","fa":"خودروی سمت چپ باید به من راه بدهد.","ok":1,"eda":"Ja. For bilen fra venstre kommer du fra højre.","efa":"بله. برای خودروی سمت چپ، شما از سمت راست می‌آیید.","en":"The car from the left must give way to me.","een":"Yes. For the car from the left, you are coming from the right."},{"da":"Jeg holder tilbage for cyklisten fra højre.","fa":"به دوچرخه‌سوار سمت راست راه می‌دهم.","ok":1,"eda":"Ja. Højrereglen gælder også over for cyklister.","efa":"بله. قاعده‌ی دست راست برای دوچرخه‌سواران هم برقرار است.","en":"I give way to the cyclist from the right.","een":"Yes. The right-hand rule also applies to cyclists."},{"da":"Cyklister skal altid holde tilbage for biler.","fa":"دوچرخه‌سواران همیشه باید به خودروها راه بدهند.","ok":0,"eda":"Nej. Der er ingen regel om, at cyklister altid skal holde tilbage.","efa":"خیر. قاعده‌ای نیست که دوچرخه‌سوار همیشه راه بدهد.","en":"Cyclists must always give way to cars.","een":"No. There is no rule that cyclists must always give way."},{"da":"Jeg har forkørselsret, fordi jeg kører ligeud.","fa":"حق تقدم با من است، چون مستقیم می‌روم.","ok":0,"eda":"Nej. At køre ligeud giver ingen forkørselsret.","efa":"خیر. مستقیم رفتن حق تقدم نمی‌دهد.","en":"I have the right of way because I am going straight on.","een":"No. Going straight on gives no right of way."}]},{"id":5148,"img":"newq-art/5148.png","c":"7.7","sda":"En varevogn holder parkeret i den modkørendes side. En modkørende bil skal forbi den. Hvad gælder?","sfa":"ونی در سمت ترافیک روبه‌رو پارک شده است. خودرویی از روبه‌رو باید از کنارش رد شود. چه قاعده‌ای برقرار است؟","sen":"A van is parked on the oncoming side. An oncoming car has to get past it. What applies?","st":[{"da":"Den modkørende skal om nødvendigt standse og lade mig passere.","fa":"راننده‌ی روبه‌رو در صورت لزوم باید بایستد و بگذارد من رد شوم.","ok":1,"eda":"Ja. Er vejen delvis spærret, skal den, i hvis side spærringen er, om nødvendigt standse og lade de mødende passere.","efa":"بله. اگر جاده تا حدی بسته باشد، کسی که مانع در سمت اوست باید در صورت لزوم بایستد و بگذارد مقابلش رد شود.","en":"The oncoming driver must stop if necessary and let me pass.","een":"Yes. If the road is partly blocked, the driver on whose side the obstruction is must stop if necessary and let oncoming traffic pass."},{"da":"Jeg skal standse og lade den modkørende komme forbi varevognen først.","fa":"باید بایستم و بگذارم خودروی روبه‌رو اول از کنار ون رد شود.","ok":0,"eda":"Nej. Hindringen er i den modkørendes side; du har ikke pligt til at standse.","efa":"خیر. مانع در سمت مقابل است؛ شما موظف به ایستادن نیستید.","en":"I must stop and let the oncoming car get past the van first.","een":"No. The obstacle is on the oncoming side; you are not obliged to stop."},{"da":"Den, der blinker først med lyset, har forkørselsret.","fa":"هر که اول چراغ بزند، حق تقدم دارد.","ok":0,"eda":"Nej. Lyssignaler giver ingen forkørselsret.","efa":"خیر. چراغ زدن حق تقدم نمی‌دهد.","en":"Whoever flashes their lights first has the right of way.","een":"No. Flashing lights gives no right of way."},{"da":"Jeg holder alligevel øje med, om den modkørende kører ud foran mig.","fa":"با این حال مراقبم که خودروی روبه‌رو جلوی من بیرون نیاید.","ok":1,"eda":"Ja. Du skal altid være klar til, at andre ikke overholder reglerne.","efa":"بله. همیشه باید آماده باشید که دیگران قوانین را رعایت نکنند.","en":"I still watch whether the oncoming driver pulls out in front of me.","een":"Yes. You must always be ready for others not keeping the rules."}]},{"id":5149,"img":"newq-art/5149.png","c":"7.7","sda":"Du kører med fjernlys i mørke, og en cyklist med lygte kommer imod dig. Hvordan forholder du dig?","sfa":"در تاریکی با نور بالا می‌رانید و دوچرخه‌سواری با چراغ از روبه‌رو می‌آید. چه می‌کنید؟","sen":"You are driving with high beam in the dark, and a cyclist with a light is coming towards you. What do you do?","st":[{"da":"Jeg tilpasser farten til det kortere udsyn med nærlys.","fa":"سرعتم را با دید کوتاه‌تر نور پایین هماهنگ می‌کنم.","ok":1,"eda":"Ja. Farten skal tilpasses de nye sigtforhold, før du blænder ned.","efa":"بله. پیش از رفتن به نور پایین باید سرعت را با دید تازه هماهنگ کنید.","en":"I adjust my speed to the shorter view with dipped beam.","een":"Yes. Your speed must be adjusted to the new visibility before you dip."},{"da":"Jeg skifter til nærlys, så cyklisten ikke bliver blændet.","fa":"به نور پایین می‌روم تا دوچرخه‌سوار خیره نشود.","ok":1,"eda":"Ja. Fjernlys må ikke bruges ved møde med andet køretøj i en afstand, hvor føreren kan blændes; en cykel er også et køretøj.","efa":"بله. هنگام برخورد با وسیله‌ی دیگری در فاصله‌ای که راننده‌اش خیره شود، نور بالا ممنوع است؛ دوچرخه هم وسیله‌ی نقلیه است.","en":"I switch to dipped beam so that the cyclist is not dazzled.","een":"Yes. High beam must not be used when meeting another vehicle at a distance where its driver can be dazzled; a bicycle is a vehicle too."},{"da":"Cyklister bliver ikke blændet, så jeg kan beholde fjernlyset.","fa":"دوچرخه‌سواران خیره نمی‌شوند، پس می‌توانم نور بالا را نگه دارم.","ok":0,"eda":"Nej. En blændet cyklist kan køre ud i vejen eller vælte.","efa":"خیر. دوچرخه‌سوار خیره‌شده ممکن است به وسط جاده برود یا زمین بخورد.","en":"Cyclists are not dazzled, so I can keep the high beam.","een":"No. A dazzled cyclist may ride out into the road or fall."},{"da":"Jeg blinker med fjernlyset, så cyklisten ved, at jeg kommer.","fa":"با نور بالا چراغ می‌زنم تا دوچرخه‌سوار بداند می‌آیم.","ok":0,"eda":"Nej. Blink med fjernlyset blænder også.","efa":"خیر. چراغ زدن با نور بالا هم خیره می‌کند.","en":"I flash the high beam so that the cyclist knows I am coming.","een":"No. Flashing the high beam dazzles too."}]},{"id":5150,"img":"newq-art/5150.png","c":"4.5","sda":"Foran dig kører en gruppe unge cyklister, nogle ved siden af hinanden. Hvordan forholder du dig?","sfa":"جلوی شما گروهی از دوچرخه‌سواران جوان می‌رانند و برخی کنار هم هستند. چه می‌کنید؟","sen":"A group of young cyclists is riding in front of you, some of them side by side. What do you do?","st":[{"da":"Jeg overhaler først, når jeg kan give hele gruppen god plads.","fa":"فقط وقتی سبقت می‌گیرم که بتوانم به کل گروه جای کافی بدهم.","ok":1,"eda":"Ja. En gruppe er længere og bredere end én cyklist.","efa":"بله. یک گروه از یک دوچرخه‌سوار درازتر و پهن‌تر است.","en":"I only overtake when I can give the whole group plenty of room.","een":"Yes. A group is longer and wider than one cyclist."},{"da":"Jeg må regne med, at en af dem pludselig kan svinge ud.","fa":"باید انتظار داشته باشم یکی‌شان ناگهان به وسط بیاید.","ok":1,"eda":"Ja. En cyklist, der kigger sig tilbage, kan være ved at svinge.","efa":"بله. دوچرخه‌سواری که به عقب نگاه می‌کند، ممکن است بخواهد بپیچد.","en":"I must expect that one of them may suddenly swerve out.","een":"Yes. A cyclist looking back may be about to turn."},{"da":"Jeg dytter, så de kører ind til siden.","fa":"بوق می‌زنم تا به کنار بروند.","ok":0,"eda":"Nej. Hornet kan forskrække dem og få nogen til at vælte.","efa":"خیر. بوق ممکن است آن‌ها را بترساند و یکی زمین بخورد.","en":"I sound the horn so that they move to the side.","een":"No. The horn can startle them and make someone fall."},{"da":"Jeg kører tæt forbi for at vise, at de fylder for meget.","fa":"از نزدیک رد می‌شوم تا نشانشان دهم زیادی جا گرفته‌اند.","ok":0,"eda":"Nej. At køre tæt forbi cyklister er farligt.","efa":"خیر. رد شدن از نزدیک دوچرخه‌سواران خطرناک است.","en":"I drive close past to show them that they take up too much room.","een":"No. Driving close past cyclists is dangerous."}]},{"id":5151,"img":"newq-art/5151.png","c":"7.3","sda":"En traktor har kørt jord ud på vejen fra en mark. Hvordan forholder du dig?","sfa":"تراکتوری از مزرعه خاک روی جاده آورده است. چه می‌کنید؟","sen":"A tractor has brought soil out onto the road from a field. What do you do?","st":[{"da":"Jord på vejen er kun farligt, når det regner.","fa":"خاک روی جاده فقط وقتی باران می‌بارد خطرناک است.","ok":0,"eda":"Nej. Også fugtig jord uden regn kan være meget glat.","efa":"خیر. خاک مرطوب حتی بدون باران هم می‌تواند خیلی لغزنده باشد.","en":"Soil on the road is only dangerous when it is raining.","een":"No. Damp soil can be very slippery even without rain."},{"da":"Jeg regner med, at vejen kan være glat.","fa":"انتظار دارم جاده لغزنده باشد.","ok":1,"eda":"Ja. Jord på en fugtig vej kan gøre føret fedtet og glat.","efa":"بله. خاک روی جاده‌ی مرطوب می‌تواند سطح را چرب و لغزنده کند.","en":"I expect that the road may be slippery.","een":"Yes. Soil on a damp road can make the surface greasy and slippery."},{"da":"Jeg sænker farten.","fa":"سرعتم را کم می‌کنم.","ok":1,"eda":"Ja. I vådt, glat eller fedtet føre skal hastigheden være passende lav.","efa":"بله. در شرایط خیس، لغزنده یا چرب سرعت باید به اندازه‌ی کافی کم باشد.","en":"I slow down.","een":"Yes. In wet, slippery or greasy conditions your speed must be suitably low."},{"da":"Bremselængden kan blive længere end normalt.","fa":"مسافت ترمز ممکن است بیشتر از معمول باشد.","ok":1,"eda":"Ja. Dækkene får dårligere greb på jord og mudder.","efa":"بله. لاستیک‌ها روی خاک و گل چسبندگی کمتری دارند.","en":"The braking distance may be longer than normal.","een":"Yes. The tyres grip less well on soil and mud."}]},{"id":5152,"img":"newq-art/5152.png","c":"7.3","sda":"Du nærmer dig en bakketop, hvor du ikke kan se, hvad der er på den anden side. Hvordan forholder du dig?","sfa":"به بالای تپه‌ای نزدیک می‌شوید که پشتش را نمی‌بینید. چه می‌کنید؟","sen":"You are approaching a hilltop where you cannot see what is on the other side. What do you do?","st":[{"da":"Jeg holder godt til højre.","fa":"خوب سمت راست می‌مانم.","ok":1,"eda":"Ja. En modkørende kan dukke op over bakken.","efa":"بله. ممکن است وسیله‌ای از روبه‌رو از پشت تپه پیدا شود.","en":"I keep well to the right.","een":"Yes. An oncoming vehicle may appear over the hill."},{"da":"Jeg kører midt på vejen for at se bedre.","fa":"وسط جاده می‌رانم تا بهتر ببینم.","ok":0,"eda":"Nej. Midt på vejen kan du støde sammen med en modkørende.","efa":"خیر. وسط جاده ممکن است با وسیله‌ی روبه‌رو برخورد کنید.","en":"I drive in the middle of the road to see better.","een":"No. In the middle of the road you may collide with an oncoming vehicle."},{"da":"Jeg sænker farten før bakketoppen.","fa":"پیش از رسیدن به بالای تپه سرعتم را کم می‌کنم.","ok":1,"eda":"Ja. Foran en bakketop, hvor oversigten er begrænset, skal hastigheden være passende lav.","efa":"بله. پیش از بالای تپه‌ای که دید محدود است، سرعت باید به اندازه‌ی کافی کم باشد.","en":"I slow down before the hilltop.","een":"Yes. Before a hilltop where the view is limited, your speed must be suitably low."},{"da":"Jeg holder farten, så jeg hurtigt kommer over.","fa":"سرعتم را حفظ می‌کنم تا زود رد شوم.","ok":0,"eda":"Nej. Der kan holde en bil eller ligge noget på vejen lige efter toppen.","efa":"خیر. ممکن است درست پشت تپه خودرویی ایستاده یا چیزی روی جاده افتاده باشد.","en":"I keep my speed so that I get over quickly.","een":"No. A car may be standing or something lying on the road just after the top."}]},{"id":5153,"img":"newq-art/5153.png","c":"7.3","sda":"Du kører i et boligkvarter, hvor børn leger på fortovet. Hvordan forholder du dig?","sfa":"در محله‌ای مسکونی می‌رانید که بچه‌ها در پیاده‌رو بازی می‌کنند. چه می‌کنید؟","sen":"You are driving in a residential area where children are playing on the pavement. What do you do?","st":[{"da":"Jeg sænker farten.","fa":"سرعتم را کم می‌کنم.","ok":1,"eda":"Ja. Når du nærmer dig børn på eller ved vejen, skal hastigheden være passende lav.","efa":"بله. وقتی به بچه‌هایی روی جاده یا کنار آن نزدیک می‌شوید، سرعت باید به اندازه‌ی کافی کم باشد.","en":"I slow down.","een":"Yes. When you approach children on or by the road, your speed must be suitably low."},{"da":"Et barn kan pludselig løbe ud på vejen.","fa":"ممکن است کودکی ناگهان به خیابان بدود.","ok":1,"eda":"Ja. Børn kan ikke altid vurdere trafikken.","efa":"بله. بچه‌ها همیشه نمی‌توانند ترافیک را بسنجند.","en":"A child may suddenly run out into the road.","een":"Yes. Children cannot always judge the traffic."},{"da":"Jeg er klar til at bremse.","fa":"آماده‌ی ترمز هستم.","ok":1,"eda":"Ja. Så kan du standse hurtigere, hvis et barn kommer ud.","efa":"بله. این‌طور اگر کودکی بیرون آمد، زودتر می‌ایستید.","en":"I am ready to brake.","een":"Yes. Then you can stop sooner if a child comes out."},{"da":"Jeg kan holde 50 km/t, fordi det er tilladt her.","fa":"می‌توانم ۵۰ برانم، چون این‌جا مجاز است.","ok":0,"eda":"Nej. Grænsen er en øvre grænse; nær børn skal farten ned.","efa":"خیر. حد سرعت سقف است؛ نزدیک بچه‌ها باید سرعت را کم کنید.","en":"I can keep to 50 km/h because it is allowed here.","een":"No. The limit is an upper limit; near children your speed must come down."}]},{"id":5154,"img":"newq-art/5154.png","c":"7.3","sda":"Du nærmer dig et sving, hvor du ikke kan se vejen efter svinget. Hvordan forholder du dig?","sfa":"به پیچی نزدیک می‌شوید که جاده‌ی بعد از آن را نمی‌بینید. چه می‌کنید؟","sen":"You are approaching a bend where you cannot see the road after it. What do you do?","st":[{"da":"Jeg kører så langsomt, at jeg kan standse, hvis der er en hindring efter svinget.","fa":"آن‌قدر آهسته می‌رانم که اگر بعد از پیچ مانعی باشد، بتوانم بایستم.","ok":1,"eda":"Ja. Du skal kunne standse på den strækning, du kan se, og foran enhver hindring, der kan påregnes.","efa":"بله. باید بتوانید در فاصله‌ای که می‌بینید و پیش از هر مانعی که قابل انتظار است بایستید.","en":"I drive so slowly that I can stop if there is an obstacle after the bend.","een":"Yes. You must be able to stop within the distance you can see and before any obstacle that can be expected."},{"da":"Jeg kan regne med, at vejen er fri, fordi jeg ikke kan se noget.","fa":"می‌توانم مطمئن باشم راه باز است، چون چیزی نمی‌بینم.","ok":0,"eda":"Nej. Det, du ikke kan se, kan være der.","efa":"خیر. چیزی که نمی‌بینید ممکن است آن‌جا باشد.","en":"I can count on the road being clear because I cannot see anything.","een":"No. What you cannot see may be there."},{"da":"Jeg må køre 80 km/t, fordi det er grænsen.","fa":"می‌توانم ۸۰ برانم، چون حد سرعت همین است.","ok":0,"eda":"Nej. Grænsen er det højeste, du må; i svinget kan det være alt for hurtigt.","efa":"خیر. حد سرعت بیشترین مقدار مجاز است؛ در پیچ ممکن است خیلی زیاد باشد.","en":"I may drive at 80 km/h because that is the limit.","een":"No. The limit is the most you may do; in the bend it may be far too fast."},{"da":"Jeg sænker først farten, når jeg ser en hindring.","fa":"فقط وقتی مانعی ببینم سرعتم را کم می‌کنم.","ok":0,"eda":"Nej. Så kan det være for sent; farten skal ned før svinget.","efa":"خیر. آن وقت ممکن است دیر باشد؛ سرعت باید پیش از پیچ کم شود.","en":"I only slow down when I see an obstacle.","een":"No. Then it may be too late; your speed must come down before the bend."}]},{"id":5155,"img":"newq-art/5155.png","c":"7.3","sda":"Det regner kraftigt i mørke, og du har svært ved at se vejens kanter. Hvordan forholder du dig?","sfa":"در تاریکی باران شدیدی می‌بارد و لبه‌های جاده را به‌سختی می‌بینید. چه می‌کنید؟","sen":"It is raining heavily in the dark, and you find it hard to see the edges of the road. What do you do?","st":[{"da":"Jeg holder større afstand til bilen foran.","fa":"فاصله‌ی بیشتری با خودروی جلو نگه می‌دارم.","ok":1,"eda":"Ja. På våd vej er bremselængden længere.","efa":"بله. در جاده‌ی خیس مسافت ترمز بیشتر است.","en":"I keep a greater distance to the car in front.","een":"Yes. On a wet road the braking distance is longer."},{"da":"Jeg sætter farten ned, fordi sigtbarheden er nedsat.","fa":"سرعتم را کم می‌کنم، چون دید کم شده است.","ok":1,"eda":"Ja. Når sigtbarheden er nedsat på grund af lys- eller vejrforholdene, skal hastigheden være passende lav.","efa":"بله. وقتی نور یا هوا دید را کم می‌کند، سرعت باید به اندازه‌ی کافی کم باشد.","en":"I lower my speed because visibility is reduced.","een":"Yes. When visibility is reduced by the light or the weather, your speed must be suitably low."},{"da":"Jeg holder hastighedsgrænsen, så er det sikkert.","fa":"حد سرعت را رعایت می‌کنم، پس ایمن است.","ok":0,"eda":"Nej. Grænsen gælder gode forhold; i regn og mørke skal farten ned.","efa":"خیر. حد سرعت برای شرایط خوب است؛ در باران و تاریکی باید سرعت را کم کنید.","en":"I keep to the speed limit, and then it is safe.","een":"No. The limit is for good conditions; in rain and darkness your speed must come down."},{"da":"Jeg kører tæt bag bilen foran og følger dens baglygter.","fa":"نزدیک پشت خودروی جلو می‌رانم و چراغ‌های عقبش را دنبال می‌کنم.","ok":0,"eda":"Nej. Bremser den, kan du ikke nå at standse.","efa":"خیر. اگر ترمز کند، به موقع نمی‌ایستید.","en":"I drive close behind the car in front and follow its rear lights.","een":"No. If it brakes, you cannot stop in time."}]},{"id":5156,"img":"newq-art/5156.png","c":"7.12","sda":"Du skal ligeud, og dit signal viser rødt. Signalet for venstresvingsbanen ved siden af viser grøn pil. Hvad gælder?","sfa":"می‌خواهید مستقیم بروید و چراغ شما قرمز است. چراغ خط گردش به چپ کنار شما فلش سبز است. چه قاعده‌ای برقرار است؟","sen":"You are going straight on, and your signal shows red. The signal for the left-turn lane beside you shows a green arrow. What applies?","st":[{"da":"Jeg må køre ligeud, hvis der ikke kommer nogen fra siden.","fa":"اگر کسی از کنار نیاید، می‌توانم مستقیم بروم.","ok":0,"eda":"Nej. Rødt lys betyder stop, uanset trafikken.","efa":"خیر. چراغ قرمز یعنی ایست، ترافیک هر چه باشد.","en":"I may go straight on if nobody is coming from the side.","een":"No. Red means stop whatever the traffic."},{"da":"Jeg holder stille, fordi den grønne pil kun gælder dem, der svinger til venstre.","fa":"می‌ایستم، چون فلش سبز فقط برای کسانی است که به چپ می‌پیچند.","ok":1,"eda":"Ja. Et pilsignal gælder for trafikanter, der vil køre i den retning, pilen viser.","efa":"بله. چراغ فلش‌دار برای کسانی است که می‌خواهند به جهت فلش بروند.","en":"I wait, because the green arrow only applies to those turning left.","een":"Yes. An arrow signal applies to road users going in the direction the arrow shows."},{"da":"Jeg må køre, når bilerne ved siden af kører.","fa":"وقتی خودروهای کنارم حرکت می‌کنند، می‌توانم بروم.","ok":0,"eda":"Nej. Du skal følge signalet for din egen vognbane.","efa":"خیر. باید از چراغ خط خودتان پیروی کنید.","en":"I may go when the cars beside me go.","een":"No. You must follow the signal for your own lane."}]},{"id":5157,"img":"newq-art/5157.png","c":"7.12","sda":"Du kører på en hovedvej. Fra en sidevej med hajtænder ruller en bil langsomt frem mod krydset. Hvordan forholder du dig?","sfa":"در جاده‌ی اصلی می‌رانید. از فرعی‌ای با دندان‌کوسه خودرویی آهسته به سمت تقاطع می‌آید. چه می‌کنید؟","sen":"You are driving on a main road. From a side road with shark teeth a car is rolling slowly towards the junction. What do you do?","st":[{"da":"Jeg skal holde tilbage, fordi bilen kommer fra højre.","fa":"باید راه بدهم، چون خودرو از راست می‌آید.","ok":0,"eda":"Nej. Højrereglen gælder ikke her, hvor sidevejen har hajtænder.","efa":"خیر. این‌جا که فرعی دندان‌کوسه دارد، قاعده‌ی دست راست اعمال نمی‌شود.","en":"I must give way because the car is coming from the right.","een":"No. The right-hand rule does not apply here, where the side road has shark teeth."},{"da":"Jeg holder øje med, om den virkelig standser.","fa":"مراقبم که واقعاً بایستد.","ok":1,"eda":"Ja. Du skal være klar til at reagere, hvis den anden ikke overholder sin vigepligt.","efa":"بله. باید آماده باشید اگر دیگری راه نداد، واکنش نشان دهید.","en":"I watch whether it really stops.","een":"Yes. You must be ready to react if the other driver does not give way."},{"da":"Bilen fra sidevejen skal holde tilbage for mig.","fa":"خودروی فرعی باید به من راه بدهد.","ok":1,"eda":"Ja. Hajtænderne giver bilen i sidevejen ubetinget vigepligt.","efa":"بله. دندان‌کوسه‌ها خودروی فرعی را مکلف به راه دادن بی‌قیدوشرط می‌کنند.","en":"The car from the side road must give way to me.","een":"Yes. The shark teeth make the car in the side road give way unconditionally."},{"da":"Jeg kan regne med, at den holder tilbage, så jeg øger farten.","fa":"می‌توانم مطمئن باشم راه می‌دهد، پس سرعتم را زیاد می‌کنم.","ok":0,"eda":"Nej. Du skal altid være forberedt på, at andre laver fejl.","efa":"خیر. همیشه باید برای اشتباه دیگران آماده باشید.","en":"I can count on it giving way, so I speed up.","een":"No. You must always be prepared for others to make mistakes."}]},{"id":5158,"img":"newq-art/5158.png","c":"7.12","sda":"Du kommer til et rødt lys. Der er en stoplinje på kørebanen et stykke før fodgængerfeltet. Hvor standser du?","sfa":"به چراغ قرمز می‌رسید. روی سواره‌رو کمی پیش از گذرگاه عابر خط ایست هست. کجا می‌ایستید؟","sen":"You come to a red light. There is a stop line on the road some way before the pedestrian crossing. Where do you stop?","st":[{"da":"Lige før fodgængerfeltet, efter stoplinjen.","fa":"درست پیش از گذرگاه عابر، بعد از خط ایست.","ok":0,"eda":"Nej. Stoplinjen viser, hvor du skal standse.","efa":"خیر. خط ایست نشان می‌دهد کجا باید بایستید.","en":"Just before the pedestrian crossing, after the stop line.","een":"No. The stop line shows where you must stop."},{"da":"På fodgængerfeltet, når der ikke er fodgængere.","fa":"روی گذرگاه عابر، وقتی عابری نیست.","ok":0,"eda":"Nej. Du skal så vidt muligt undgå at standse på et fodgængerfelt.","efa":"خیر. تا جای ممکن نباید روی گذرگاه عابر بایستید.","en":"On the pedestrian crossing, when there are no pedestrians.","een":"No. You must as far as possible avoid stopping on a pedestrian crossing."},{"da":"Før stoplinjen.","fa":"پیش از خط ایست.","ok":1,"eda":"Ja. Ved rødt lys skal du standse før stoplinjen.","efa":"بله. در چراغ قرمز باید پیش از خط ایست بایستید.","en":"Before the stop line.","een":"Yes. At a red light you must stop before the stop line."},{"da":"Et sted, hvor fodgængerfeltet er helt frit.","fa":"جایی که گذرگاه عابر کاملاً آزاد بماند.","ok":1,"eda":"Ja. Fodgængerne skal kunne gå over uden at gå uden om din bil.","efa":"بله. عابران باید بتوانند بدون دور زدن خودروی شما رد شوند.","en":"Somewhere the pedestrian crossing is completely clear.","een":"Yes. Pedestrians must be able to cross without walking round your car."}]},{"id":5159,"img":"newq-art/5159.png","c":"7.12","sda":"Du kører ligeud. Fra en sidevej til højre kommer en bil. Der er ingen tavler eller hajtænder. Hvad gælder?","sfa":"مستقیم می‌روید. از فرعی سمت راست خودرویی می‌آید. تابلو یا دندان‌کوسه‌ای نیست. چه قاعده‌ای برقرار است؟","sen":"You are going straight on. A car is coming from a side road on the right. There are no signs or shark teeth. What applies?","st":[{"da":"Jeg har forkørselsret, fordi jeg kører ligeud.","fa":"حق تقدم با من است، چون مستقیم می‌روم.","ok":0,"eda":"Nej. At køre ligeud giver ingen forkørselsret.","efa":"خیر. مستقیم رفتن حق تقدم نمی‌دهد.","en":"I have the right of way because I am going straight on.","een":"No. Going straight on gives no right of way."},{"da":"Højrereglen gælder, selv om sidevejen ser mindre ud.","fa":"قاعده‌ی دست راست برقرار است، حتی اگر فرعی کوچک‌تر به نظر برسد.","ok":1,"eda":"Ja. Kun tavler, afmærkning eller særlige udkørsler (fx fra en ejendom) ændrer det.","efa":"بله. فقط تابلو، خط‌کشی یا خروجی‌های خاص (مثلاً از یک ملک) این را تغییر می‌دهند.","en":"The right-hand rule applies even if the side road looks smaller.","een":"Yes. Only signs, markings or special exits (for example from a property) change that."},{"da":"Jeg skal holde tilbage for bilen fra højre.","fa":"باید به خودروی سمت راست راه بدهم.","ok":1,"eda":"Ja. Uden tavler og afmærkning gælder højrereglen.","efa":"بله. بدون تابلو و خط‌کشی، قاعده‌ی دست راست برقرار است.","en":"I must give way to the car from the right.","een":"Yes. Without signs or markings the right-hand rule applies."},{"da":"Bilen fra sidevejen skal holde tilbage, fordi den kommer fra en mindre vej.","fa":"خودروی فرعی باید راه بدهد، چون از راه کوچک‌تری می‌آید.","ok":0,"eda":"Nej. En vejs størrelse bestemmer ikke vigepligten.","efa":"خیر. بزرگی جاده حق تقدم را تعیین نمی‌کند.","en":"The car from the side road must give way because it is coming from a smaller road.","een":"No. The size of a road does not decide who gives way."}]},{"id":5160,"img":"newq-art/5160.png","c":"7.14","sda":"Du holder midt i krydset for at svinge til venstre, og lyset skifter til gult. Hvordan forholder du dig?","sfa":"وسط تقاطع ایستاده‌اید تا به چپ بپیچید و چراغ زرد می‌شود. چه می‌کنید؟","sen":"You are waiting in the middle of the junction to turn left, and the light changes to yellow. What do you do?","st":[{"da":"Jeg holder stadig tilbage for modkørende, der ikke kan nå at standse.","fa":"هنوز به خودروهای روبه‌رویی که نمی‌توانند به موقع بایستند راه می‌دهم.","ok":1,"eda":"Ja. Ved venstresving må du ikke være til ulempe for de modkørende.","efa":"بله. هنگام گردش به چپ نباید مزاحم ترافیک روبه‌رو شوید.","en":"I still give way to oncoming cars that cannot stop in time.","een":"Yes. When turning left you must not inconvenience oncoming traffic."},{"da":"Jeg kører ud af krydset, når de modkørende er kørt forbi eller standset.","fa":"وقتی خودروهای روبه‌رو رد شدند یا ایستادند، از تقاطع خارج می‌شوم.","ok":1,"eda":"Ja. Du er allerede i krydset og skal ud af det, så snart det kan ske uden fare.","efa":"بله. شما در تقاطع هستید و باید به محض بی‌خطر شدن از آن خارج شوید.","en":"I drive out of the junction when the oncoming cars have passed or stopped.","een":"Yes. You are already in the junction and must get out of it as soon as it can be done safely."},{"da":"Jeg bakker tilbage bag stoplinjen.","fa":"دنده‌عقب تا پشت خط ایست برمی‌گردم.","ok":0,"eda":"Nej. At bakke i et kryds er farligt; trafikken bag dig kører frem.","efa":"خیر. دنده‌عقب در تقاطع خطرناک است؛ ترافیک پشت سرتان جلو می‌آید.","en":"I reverse back behind the stop line.","een":"No. Reversing in a junction is dangerous; the traffic behind you is moving forward."},{"da":"Jeg bliver stående i krydset, til jeg får grønt igen.","fa":"در تقاطع می‌مانم تا دوباره سبز شود.","ok":0,"eda":"Nej. Så spærrer du for den tværgående trafik, når den får grønt.","efa":"خیر. این‌طور راه ترافیک متقاطع را وقتی سبز می‌شود می‌بندید.","en":"I stay in the junction until I get green again.","een":"No. Then you block the crossing traffic when it gets green."}]},{"id":5161,"img":"newq-art/5161.png","c":"7.14","sda":"Du vil svinge til venstre ind på en sidevej. Langs vejens venstre side er der en dobbeltrettet cykelsti. Hvad gælder?","sfa":"می‌خواهید به چپ وارد فرعی شوید. در سمت چپ جاده مسیر دوچرخه‌ی دوطرفه هست. چه قاعده‌ای برقرار است؟","sen":"You want to turn left into a side road. Along the left side of the road there is a two-way cycle path. What applies?","st":[{"da":"Jeg må ikke svinge, før det kan ske uden ulempe for cyklisterne, der kører ligeud.","fa":"تا وقتی برای دوچرخه‌سوارانی که مستقیم می‌روند مزاحمتی نداشته باشد، نباید بپیچم.","ok":1,"eda":"Ja. Er der en dobbeltrettet cykelsti, må du ikke svinge til venstre, før det kan ske uden ulempe for cyklister og knallertkørere, der kører ligeud.","efa":"بله. وقتی مسیر دوچرخه‌ی دوطرفه هست، تا وقتی برای دوچرخه‌سواران و موپدسوارانی که مستقیم می‌روند مزاحمتی نداشته باشد، نباید به چپ بپیچید.","en":"I must not turn until it can be done without inconvenience to the cyclists going straight on.","een":"Yes. With a two-way cycle path you must not turn left until it can be done without inconvenience to cyclists and moped riders going straight on."},{"da":"Jeg ser efter cyklister fra begge retninger.","fa":"دوچرخه‌سواران هر دو جهت را نگاه می‌کنم.","ok":1,"eda":"Ja. På en dobbeltrettet cykelsti kommer cyklisterne både forfra og bagfra.","efa":"بله. روی مسیر دوچرخه‌ی دوطرفه، دوچرخه‌سواران هم از جلو و هم از پشت می‌آیند.","en":"I look for cyclists from both directions.","een":"Yes. On a two-way cycle path cyclists come both from ahead and from behind."},{"da":"Cyklisterne skal holde tilbage, fordi jeg blinker.","fa":"دوچرخه‌سواران باید راه بدهند، چون راهنما زده‌ام.","ok":0,"eda":"Nej. Blinklyset giver ingen ret til at svinge.","efa":"خیر. راهنما حق پیچیدن نمی‌دهد.","en":"The cyclists must give way because I am signalling.","een":"No. The indicator gives no right to turn."},{"da":"Jeg holder også tilbage for modkørende biler.","fa":"به خودروهای روبه‌رو هم راه می‌دهم.","ok":1,"eda":"Ja. Ved venstresving må du ikke være til ulempe for de modkørende.","efa":"بله. هنگام گردش به چپ نباید مزاحم ترافیک روبه‌رو شوید.","en":"I also give way to oncoming cars.","een":"Yes. When turning left you must not inconvenience oncoming traffic."}]},{"id":5162,"img":"newq-art/5162.png","c":"7.14","sda":"Du vil svinge til venstre. En modkørende bil vil svinge til højre ind på samme vej som dig. Hvad gælder?","sfa":"می‌خواهید به چپ بپیچید. خودرویی از روبه‌رو می‌خواهد به راست وارد همان جاده‌ای شود که شما می‌روید. چه قاعده‌ای برقرار است؟","sen":"You want to turn left. An oncoming car wants to turn right into the same road as you. What applies?","st":[{"da":"Vi skal begge standse og vinke hinanden frem.","fa":"هر دو باید بایستیم و به هم اشاره کنیم که اول برو.","ok":0,"eda":"Nej. Reglerne siger, hvem der skal holde tilbage; her er det dig.","efa":"خیر. قانون می‌گوید چه کسی باید راه بدهد؛ این‌جا شما هستید.","en":"We must both stop and wave each other on.","een":"No. The rules say who must give way; here it is you."},{"da":"Jeg holder tilbage for den modkørende, der svinger til højre.","fa":"به خودروی روبه‌رو که به راست می‌پیچد راه می‌دهم.","ok":1,"eda":"Ja. Ved venstresving må du ikke være til ulempe for modkørende, heller ikke dem, der svinger til højre.","efa":"بله. هنگام گردش به چپ نباید مزاحم ترافیک روبه‌رو شوید، از جمله کسانی که به راست می‌پیچند.","en":"I give way to the oncoming car that is turning right.","een":"Yes. When turning left you must not inconvenience oncoming traffic, including those turning right."},{"da":"Jeg har forkørselsret, fordi jeg kom først.","fa":"حق تقدم با من است، چون اول رسیدم.","ok":0,"eda":"Nej. Hvem der kom først, betyder ikke noget.","efa":"خیر. این‌که چه کسی اول رسید، اهمیتی ندارد.","en":"I have the right of way because I got there first.","een":"No. Who got there first does not matter."}]},{"id":5163,"img":"newq-art/5163.png","c":"7.14","sda":"Du vil svinge til venstre ind på en markvej. Bag dig kommer en motorcykel hurtigt. Hvordan forholder du dig?","sfa":"می‌خواهید به چپ وارد یک راه خاکی مزرعه شوید. از پشت موتورسیکلتی با سرعت می‌آید. چه می‌کنید؟","sen":"You want to turn left into a field road. A motorcycle is coming up fast behind you. What do you do?","st":[{"da":"Jeg ser i spejlet og over venstre skulder, før jeg svinger.","fa":"پیش از پیچیدن در آینه و از روی شانه‌ی چپ نگاه می‌کنم.","ok":1,"eda":"Ja. Før du svinger, skal du sikre dig, at det kan ske uden fare for dem, der kører i samme retning.","efa":"بله. پیش از پیچیدن باید مطمئن شوید که برای کسانی که هم‌جهت شما می‌آیند خطری ندارد.","en":"I look in the mirror and over my left shoulder before I turn.","een":"Yes. Before you turn, you must make sure that it can be done without danger to those going in the same direction."},{"da":"Motorcyklen skal altid holde tilbage, fordi jeg blinker.","fa":"موتورسیکلت همیشه باید راه بدهد، چون راهنما زده‌ام.","ok":0,"eda":"Nej. Blinklyset giver dig ikke ret til at svinge foran andre.","efa":"خیر. راهنما به شما حق پیچیدن جلوی دیگران را نمی‌دهد.","en":"The motorcycle must always give way because I am signalling.","een":"No. The indicator does not give you the right to turn in front of others."},{"da":"Jeg blinker i god tid og placerer mig ved midten af vejen.","fa":"به موقع راهنما می‌زنم و نزدیک وسط جاده قرار می‌گیرم.","ok":1,"eda":"Ja. Så kan de bagfra se, hvad du vil.","efa":"بله. این‌طور پشت‌سری‌ها می‌بینند چه می‌خواهید بکنید.","en":"I signal in good time and place myself near the middle of the road.","een":"Yes. Then those behind can see what you are going to do."},{"da":"Jeg kan svinge med det samme, fordi jeg har blinket.","fa":"می‌توانم فوراً بپیچم، چون راهنما زده‌ام.","ok":0,"eda":"Nej. Er motorcyklen ved at overhale, skal du vente.","efa":"خیر. اگر موتورسیکلت در حال سبقت است، باید صبر کنید.","en":"I can turn straight away because I have signalled.","een":"No. If the motorcycle is overtaking, you must wait."}]},{"id":5164,"img":"newq-art/5164.png","c":"7.14","sda":"Du svinger til venstre ind på en vej med to vognbaner i din nye retning. Lidt længere fremme skal du til højre. Hvad gælder?","sfa":"به چپ وارد جاده‌ای می‌شوید که در جهت تازه‌تان دو خط دارد. کمی جلوتر باید به راست بپیچید. چه قاعده‌ای برقرار است؟","sen":"You are turning left into a road with two lanes in your new direction. A little further on you are going to turn right. What applies?","st":[{"da":"Det kan være den højre vognbane, når jeg snart skal til højre.","fa":"وقتی به‌زودی باید به راست بپیچم، ممکن است خط راست باشد.","ok":1,"eda":"Ja. Så undgår du et vognbaneskift lige før næste sving.","efa":"بله. این‌طور از تغییر خط درست پیش از پیچ بعدی پرهیز می‌کنید.","en":"It may be the right-hand lane when I am soon going to turn right.","een":"Yes. That way you avoid a lane change just before the next turn."},{"da":"Jeg vælger den vognbane, der passer bedst til trafikken og min videre kørsel.","fa":"خطی را انتخاب می‌کنم که با ترافیک و ادامه‌ی مسیرم بیشتر جور است.","ok":1,"eda":"Ja. Har vejen, du svinger ind på, to eller flere vognbaner i samme retning, svinger du på den måde, der er mest hensigtsmæssig.","efa":"بله. اگر جاده‌ای که واردش می‌شوید دو یا چند خط هم‌جهت دارد، به مناسب‌ترین شکل می‌پیچید.","en":"I choose the lane that best suits the traffic and where I am going next.","een":"Yes. If the road you turn into has two or more lanes in the same direction, you turn in the way that is most suitable."},{"da":"Jeg må skifte vognbane midt i svinget uden at se mig for.","fa":"می‌توانم وسط پیچ بدون نگاه کردن تغییر خط بدهم.","ok":0,"eda":"Nej. Et vognbaneskift skal altid kunne ske uden fare.","efa":"خیر. تغییر خط همیشه باید بی‌خطر باشد.","en":"I may change lanes in the middle of the turn without looking.","een":"No. A lane change must always be done safely."},{"da":"Jeg skal altid ende i den venstre vognbane efter et venstresving.","fa":"پس از گردش به چپ همیشه باید در خط چپ قرار بگیرم.","ok":0,"eda":"Nej. Der er ingen sådan regel, når vejen har flere vognbaner.","efa":"خیر. وقتی جاده چند خط دارد، چنین قاعده‌ای نیست.","en":"I must always end up in the left lane after a left turn.","een":"No. There is no such rule when the road has several lanes."}]},{"id":5165,"img":"newq-art/5165.png","c":"7.14","sda":"Du venter på at svinge til venstre. Den modkørende bil standser og blinker med lyset. Hvordan forholder du dig?","sfa":"منتظر گردش به چپ هستید. خودروی روبه‌رو می‌ایستد و چراغ می‌زند. چه می‌کنید؟","sen":"You are waiting to turn left. The oncoming car stops and flashes its lights. What do you do?","st":[{"da":"Jeg sikrer mig selv, at svinget kan ske uden fare, før jeg kører.","fa":"پیش از حرکت خودم مطمئن می‌شوم که پیچیدن بی‌خطر است.","ok":1,"eda":"Ja. Et lyssignal er efter loven en advarsel og giver dig ingen ret; der kan komme en cyklist bag bilen.","efa":"بله. طبق قانون چراغ زدن هشدار است و حقی به شما نمی‌دهد؛ ممکن است دوچرخه‌سواری پشت آن خودرو بیاید.","en":"I make sure myself that the turn can be done safely before I go.","een":"Yes. By law a light signal is a warning and gives you no right; a cyclist may be coming behind the car."},{"da":"Blinket betyder altid, at jeg kan svinge med det samme.","fa":"چراغ زدن همیشه یعنی می‌توانم فوراً بپیچم.","ok":0,"eda":"Nej. Du ved ikke, hvad den anden mener, og du kan ikke se alt bag bilen.","efa":"خیر. نمی‌دانید منظور او چیست و همه‌چیز پشت آن خودرو را نمی‌بینید.","en":"The flash always means that I can turn straight away.","een":"No. You do not know what the other driver means, and you cannot see everything behind the car."},{"da":"Blinket betyder, at den modkørende har pligt til at holde tilbage for mig.","fa":"چراغ زدن یعنی راننده‌ی روبه‌رو موظف است به من راه بدهد.","ok":0,"eda":"Nej. Det er dig, der skal holde tilbage ved venstresving.","efa":"خیر. هنگام گردش به چپ، این شما هستید که باید راه بدهید.","en":"The flash means that the oncoming driver has a duty to give way to me.","een":"No. It is you who must give way when turning left."},{"da":"Jeg skal køre nu, ellers er jeg til ulempe for den modkørende.","fa":"باید الان بروم، وگرنه مزاحم راننده‌ی روبه‌رو هستم.","ok":0,"eda":"Nej. Sikkerheden går forud; vent, til du kan se, at vejen er fri.","efa":"خیر. ایمنی مقدم است؛ صبر کنید تا ببینید راه باز است.","en":"I must go now, otherwise I am in the oncoming driver's way.","een":"No. Safety comes first; wait until you can see the way is clear."}]},{"id":5166,"img":"newq-art/5166.png","c":"7.13","sda":"Du vil svinge til højre, og lyset er rødt. Der kommer ingen. Hvad gælder?","sfa":"می‌خواهید به راست بپیچید و چراغ قرمز است. کسی نمی‌آید. چه قاعده‌ای برقرار است؟","sen":"You want to turn right, and the light is red. Nobody is coming. What applies?","st":[{"da":"Jeg må svinge, hvis jeg kører meget langsomt.","fa":"اگر خیلی آهسته بروم، می‌توانم بپیچم.","ok":0,"eda":"Nej. Farten ændrer ikke på signalet.","efa":"خیر. سرعت چیزی را درباره‌ی چراغ تغییر نمی‌دهد.","en":"I may turn if I drive very slowly.","een":"No. Speed does not change the signal."},{"da":"Jeg holder stille, til jeg får grønt.","fa":"تا سبز شدن چراغ می‌ایستم.","ok":1,"eda":"Ja. Rødt lys betyder stop, også når du skal svinge til højre.","efa":"بله. چراغ قرمز یعنی ایست، حتی وقتی می‌خواهید به راست بپیچید.","en":"I wait until I get green.","een":"Yes. Red means stop, also when you are going to turn right."},{"da":"Jeg må svinge til højre for rødt, når vejen er fri.","fa":"وقتی راه باز است، می‌توانم با چراغ قرمز به راست بپیچم.","ok":0,"eda":"Nej. Der er ingen regel, der tillader biler at svinge til højre for rødt.","efa":"خیر. هیچ قاعده‌ای پیچیدن خودرو به راست با چراغ قرمز را مجاز نمی‌کند.","en":"I may turn right on red when the road is clear.","een":"No. There is no rule allowing cars to turn right on red."}]},{"id":5167,"img":"newq-art/5167.png","c":"7.13","sda":"Du vil svinge til højre. Bag dig kommer en cyklist i cykelbanen. Hvordan forholder du dig?","sfa":"می‌خواهید به راست بپیچید. از پشت دوچرخه‌سواری در خط دوچرخه می‌آید. چه می‌کنید؟","sen":"You want to turn right. A cyclist is coming up behind you in the cycle lane. What do you do?","st":[{"da":"Cyklisten skal holde tilbage, fordi jeg blinker.","fa":"دوچرخه‌سوار باید راه بدهد، چون راهنما زده‌ام.","ok":0,"eda":"Nej. Blinklyset giver ingen ret.","efa":"خیر. راهنما حقی نمی‌دهد.","en":"The cyclist must give way because I am signalling.","een":"No. The indicator gives no right."},{"da":"Jeg skynder mig at svinge, før cyklisten når frem.","fa":"عجله می‌کنم تا پیش از رسیدن دوچرخه‌سوار بپیچم.","ok":0,"eda":"Nej. Det kan føre til en farlig ulykke i krydset.","efa":"خیر. این کار ممکن است به تصادف خطرناکی در تقاطع منجر شود.","en":"I hurry to turn before the cyclist gets there.","een":"No. That can lead to a dangerous accident in the junction."},{"da":"Jeg kigger i spejlet og over højre skulder, før jeg svinger.","fa":"پیش از پیچیدن در آینه و از روی شانه‌ی راست نگاه می‌کنم.","ok":1,"eda":"Ja. Cyklisten kan være i din blinde vinkel.","efa":"بله. دوچرخه‌سوار ممکن است در نقطه‌ی کور شما باشد.","en":"I look in the mirror and over my right shoulder before I turn.","een":"Yes. The cyclist may be in your blind spot."},{"da":"Jeg lader cyklisten køre ligeud forbi, før jeg svinger.","fa":"می‌گذارم دوچرخه‌سوار مستقیم رد شود، بعد می‌پیچم.","ok":1,"eda":"Ja. Ved svingning til højre må du ikke være til ulempe for cyklister, der kører ligeud.","efa":"بله. هنگام گردش به راست نباید مزاحم دوچرخه‌سوارانی شوید که مستقیم می‌روند.","en":"I let the cyclist ride straight on past before I turn.","een":"Yes. When turning right you must not inconvenience cyclists going straight on."}]},{"id":5168,"img":"newq-art/5168.png","c":"7.13","sda":"Du vil svinge til højre ind i en indkørsel over cykelstien og fortovet. Hvad gælder?","sfa":"می‌خواهید به راست وارد ورودی یک خانه شوید که از روی مسیر دوچرخه و پیاده‌رو می‌گذرد. چه قاعده‌ای برقرار است؟","sen":"You want to turn right into a driveway across the cycle path and the pavement. What applies?","st":[{"da":"Fodgængeren skal vente, fordi jeg blinker.","fa":"عابر باید صبر کند، چون راهنما زده‌ام.","ok":0,"eda":"Nej. Blinklyset giver dig ikke ret til at køre over fortovet foran fodgængeren.","efa":"خیر. راهنما به شما حق نمی‌دهد جلوی عابر از روی پیاده‌رو رد شوید.","en":"The pedestrian must wait because I am signalling.","een":"No. The indicator does not give you the right to cross the pavement in front of the pedestrian."},{"da":"Jeg holder tilbage for fodgængeren på fortovet.","fa":"به عابر پیاده‌رو راه می‌دهم.","ok":1,"eda":"Ja. Når du kører bort fra kørebanen, må du ikke være til fare for gående; over fortovet skal du holde tilbage for dem.","efa":"بله. وقتی از سواره‌رو بیرون می‌روید، نباید عابران را به خطر بیندازید؛ روی پیاده‌رو باید به آن‌ها راه بدهید.","en":"I give way to the pedestrian on the pavement.","een":"Yes. When you leave the carriageway you must not endanger pedestrians; across the pavement you must give way to them."},{"da":"Jeg holder tilbage for cyklisten på cykelstien.","fa":"به دوچرخه‌سوار روی مسیر دوچرخه راه می‌دهم.","ok":1,"eda":"Ja. Du må ikke svinge ind foran cyklisten, så den kommer i fare eller bliver generet.","efa":"بله. نباید جلوی دوچرخه‌سوار بپیچید، طوری که به خطر بیفتد یا اذیت شود.","en":"I give way to the cyclist on the cycle path.","een":"Yes. You must not turn in front of the cyclist so that they are put in danger or inconvenienced."}]},{"id":5169,"img":"newq-art/5169.png","c":"7.13","sda":"Lige før krydset, hvor du skal svinge til højre, kører en cyklist foran dig i højre side. Hvordan forholder du dig?","sfa":"درست پیش از تقاطعی که باید به راست بپیچید، دوچرخه‌سواری جلوی شما در سمت راست می‌رود. چه می‌کنید؟","sen":"Just before the junction where you are going to turn right, a cyclist is riding in front of you on the right. What do you do?","st":[{"da":"Cyklisten skal holde tilbage, fordi bilen er større.","fa":"دوچرخه‌سوار باید راه بدهد، چون خودرو بزرگ‌تر است.","ok":0,"eda":"Nej. Størrelse giver ingen ret.","efa":"خیر. بزرگی حقی نمی‌دهد.","en":"The cyclist must give way because the car is bigger.","een":"No. Size gives no right."},{"da":"Jeg bliver bag cyklisten og svinger, når den er kørt ligeud forbi sidevejen.","fa":"پشت دوچرخه‌سوار می‌مانم و وقتی از کنار فرعی مستقیم رد شد، می‌پیچم.","ok":1,"eda":"Ja. Ved højresving må du ikke være til ulempe for cyklister, der kører ligeud.","efa":"بله. هنگام گردش به راست نباید مزاحم دوچرخه‌سوارانی شوید که مستقیم می‌روند.","en":"I stay behind the cyclist and turn when they have gone straight past the side road.","een":"Yes. When turning right you must not inconvenience cyclists going straight on."},{"da":"Jeg overhaler cyklisten og svinger ind foran den.","fa":"از دوچرخه‌سوار سبقت می‌گیرم و جلویش می‌پیچم.","ok":0,"eda":"Nej. Så kan cyklisten køre ind i siden af bilen.","efa":"خیر. این‌طور ممکن است دوچرخه‌سوار به پهلوی خودرو بخورد.","en":"I overtake the cyclist and turn in front of them.","een":"No. Then the cyclist may ride into the side of the car."}]},{"id":5170,"img":"newq-art/5170.png","c":"7.13","sda":"Du skal svinge til højre i et kryds, hvor vejen har to vognbaner i din retning. Hvordan gør du?","sfa":"باید در تقاطعی بپیچید که جاده در جهت شما دو خط دارد و می‌خواهید به راست بروید. چه می‌کنید؟","sen":"You are going to turn right at a junction where the road has two lanes in your direction. How do you do it?","st":[{"da":"Jeg blinker i god tid.","fa":"به موقع راهنما می‌زنم.","ok":1,"eda":"Ja. Tegn skal gives i god tid før svinget.","efa":"بله. علامت باید به موقع پیش از پیچ داده شود.","en":"I signal in good time.","een":"Yes. Signals must be given in good time before the turn."},{"da":"I god tid før krydset lægger jeg mig i vognbanen længst til højre.","fa":"به موقع پیش از تقاطع به راست‌ترین خط می‌روم.","ok":1,"eda":"Ja. I god tid før et kryds skal du lægge dig i vognbanen længst til højre, hvis du skal svinge til højre.","efa":"بله. اگر می‌خواهید به راست بپیچید، باید به موقع پیش از تقاطع به راست‌ترین خط بروید.","en":"In good time before the junction I move into the lane furthest to the right.","een":"Yes. In good time before a junction you must move into the lane furthest to the right if you are going to turn right."},{"da":"Jeg kan svinge til højre fra venstre vognbane, hvis der er plads.","fa":"اگر جا باشد، می‌توانم از خط چپ به راست بپیچم.","ok":0,"eda":"Nej. Så skærer du ind foran trafikken i højre vognbane.","efa":"خیر. این‌طور جلوی ترافیک خط راست می‌پیچید.","en":"I can turn right from the left lane if there is room.","een":"No. Then you cut in front of the traffic in the right lane."},{"da":"Jeg sænker farten før svinget.","fa":"پیش از پیچیدن سرعتم را کم می‌کنم.","ok":1,"eda":"Ja. Ved kryds skal hastigheden være passende lav.","efa":"بله. در تقاطع سرعت باید به اندازه‌ی کافی کم باشد.","en":"I slow down before the turn.","een":"Yes. At junctions your speed must be suitably low."}]},{"id":5171,"img":"newq-art/5171.png","c":"7.11","sda":"Du kommer til en stoptavle, men hækkene skjuler udsynet til den tværgående vej. Hvordan forholder du dig?","sfa":"به تابلوی ایست می‌رسید، ولی پرچین‌ها دید جاده‌ی متقاطع را گرفته‌اند. چه می‌کنید؟","sen":"You come to a stop sign, but the hedges hide the view of the crossing road. What do you do?","st":[{"da":"Jeg standser helt ved stoplinjen.","fa":"کنار خط ایست کاملاً می‌ایستم.","ok":1,"eda":"Ja. Ved stoptavlen skal du altid standse ved stoplinjen.","efa":"بله. کنار تابلوی ایست همیشه باید پشت خط ایست بایستید.","en":"I stop completely at the stop line.","een":"Yes. At the stop sign you must always stop at the stop line."},{"da":"Kan jeg ikke se nok, kører jeg langsomt lidt frem og standser igen, hvor jeg kan se.","fa":"اگر به اندازه‌ی کافی نبینم، آهسته کمی جلو می‌روم و جایی که می‌بینم دوباره می‌ایستم.","ok":1,"eda":"Ja. Du har ubetinget vigepligt og må først køre ud, når du kan se, at det kan ske uden fare.","efa":"بله. باید بی‌قیدوشرط راه بدهید و فقط وقتی می‌توانید وارد شوید که ببینید بی‌خطر است.","en":"If I cannot see enough, I edge forward slowly and stop again where I can see.","een":"Yes. You must give way unconditionally and may only drive out when you can see that it is safe."},{"da":"Jeg kører ud, når jeg ikke kan høre biler.","fa":"وقتی صدای خودرویی نمی‌شنوم، وارد می‌شوم.","ok":0,"eda":"Nej. Du kan ikke høre alle trafikanter, fx cyklister og elbiler.","efa":"خیر. صدای همه‌ی کاربران راه، مثلاً دوچرخه و خودروی برقی، را نمی‌شنوید.","en":"I drive out when I cannot hear any cars.","een":"No. You cannot hear all road users, for example cyclists and electric cars."},{"da":"Jeg standser kun, hvis der kommer trafik.","fa":"فقط وقتی ترافیک بیاید می‌ایستم.","ok":0,"eda":"Nej. Ved stoptavlen skal du altid standse.","efa":"خیر. کنار تابلوی ایست همیشه باید بایستید.","en":"I only stop if traffic is coming.","een":"No. At the stop sign you must always stop."}]},{"id":5172,"img":"newq-art/5172.png","c":"7.11","sda":"Du nærmer dig et kryds uden tavler og afmærkning. En høj hæk skjuler vejen til højre. Hvordan forholder du dig?","sfa":"به تقاطعی بدون تابلو و خط‌کشی نزدیک می‌شوید. پرچین بلندی جاده‌ی سمت راست را پنهان کرده است. چه می‌کنید؟","sen":"You are approaching a junction with no signs or markings. A high hedge hides the road to the right. What do you do?","st":[{"da":"Jeg skal kunne standse, hvis der kommer nogen fra højre.","fa":"اگر کسی از راست بیاید، باید بتوانم بایستم.","ok":1,"eda":"Ja. Du kan først se trafikken fra højre, når du er helt fremme ved krydset.","efa":"بله. ترافیک سمت راست را فقط وقتی می‌بینید که کاملاً به تقاطع رسیده باشید.","en":"I must be able to stop if someone comes from the right.","een":"Yes. You can only see the traffic from the right when you are right up at the junction."},{"da":"Jeg skal holde tilbage for trafik fra højre.","fa":"باید به ترافیک سمت راست راه بدهم.","ok":1,"eda":"Ja. Uden tavler og afmærkning gælder højrereglen.","efa":"بله. بدون تابلو و خط‌کشی، قاعده‌ی دست راست برقرار است.","en":"I must give way to traffic from the right.","een":"Yes. Without signs or markings the right-hand rule applies."},{"da":"Jeg sænker farten i god tid.","fa":"به موقع سرعتم را کم می‌کنم.","ok":1,"eda":"Ja. Ved vejkryds skal hastigheden være passende lav, især når oversigten er dårlig.","efa":"بله. در تقاطع، به‌ویژه وقتی دید کم است، سرعت باید به اندازه‌ی کافی کم باشد.","en":"I slow down in good time.","een":"Yes. At junctions your speed must be suitably low, especially when the view is poor."},{"da":"Jeg kører igennem, fordi jeg ikke kan se nogen.","fa":"رد می‌شوم، چون کسی را نمی‌بینم.","ok":0,"eda":"Nej. Hækken kan skjule en, der kommer fra højre.","efa":"خیر. پرچین ممکن است کسی را که از راست می‌آید پنهان کند.","en":"I drive through because I cannot see anyone.","een":"No. The hedge may hide someone coming from the right."}]},{"id":5173,"img":"newq-art/5173.png","c":"7.11","sda":"Du kører forbi denne tavle. Hvad betyder den, og hvordan forholder du dig?","sfa":"از کنار این تابلو رد می‌شوید. یعنی چه و چه می‌کنید؟","sen":"You pass this sign. What does it mean, and what do you do?","st":[{"da":"Der kommer en rundkørsel.","fa":"میدانی در پیش است.","ok":1,"eda":"Ja. Tavlen (A 16) varsler en rundkørsel.","efa":"بله. این تابلو (A 16) از میدان خبر می‌دهد.","en":"A roundabout is coming.","een":"Yes. The sign (A 16) warns of a roundabout."},{"da":"Tavlen betyder, at vejen ender.","fa":"این تابلو یعنی جاده تمام می‌شود.","ok":0,"eda":"Nej. Vejen fortsætter gennem rundkørslen.","efa":"خیر. جاده از میان میدان ادامه دارد.","en":"The sign means that the road ends.","een":"No. The road continues through the roundabout."},{"da":"Tavlen betyder, at jeg har forkørselsret i rundkørslen.","fa":"این تابلو یعنی در میدان حق تقدم با من است.","ok":0,"eda":"Nej. Advarselstavlen siger ikke noget om vigepligt; det gør tavlerne ved indkørslen.","efa":"خیر. تابلوی هشدار چیزی درباره‌ی حق تقدم نمی‌گوید؛ تابلوهای ورودی می‌گویند.","en":"The sign means that I have the right of way in the roundabout.","een":"No. The warning sign says nothing about giving way; the signs at the entry do."},{"da":"Jeg sænker farten i god tid.","fa":"به موقع سرعتم را کم می‌کنم.","ok":1,"eda":"Ja. Du skal kunne holde tilbage for dem, der er i rundkørslen, hvis det kræves.","efa":"بله. باید بتوانید در صورت لزوم به کسانی که در میدان‌اند راه بدهید.","en":"I slow down in good time.","een":"Yes. You must be able to give way to those in the roundabout if required."}]},{"id":5174,"img":"newq-art/5174.png","c":"7.11","sda":"Lyssignalerne i krydset er slukket. Ved din vej står en vigepligtstavle, og der er hajtænder. Hvad gælder?","sfa":"چراغ‌های تقاطع خاموش‌اند. در راه شما تابلوی رعایت حق تقدم و دندان‌کوسه هست. چه قاعده‌ای برقرار است؟","sen":"The traffic lights at the junction are switched off. At your road there is a give-way sign and shark teeth. What applies?","st":[{"da":"Jeg har ubetinget vigepligt efter tavlen og hajtænderne.","fa":"طبق تابلو و دندان‌کوسه‌ها باید بی‌قیدوشرط راه بدهم.","ok":1,"eda":"Ja. Når signalet ikke er i drift, gælder tavler og afmærkning.","efa":"بله. وقتی چراغ کار نمی‌کند، تابلو و خط‌کشی معتبرند.","en":"I must give way unconditionally according to the sign and the shark teeth.","een":"Yes. When the signal is not working, the signs and markings apply."},{"da":"Jeg har forkørselsret, fordi signalet er slukket.","fa":"حق تقدم با من است، چون چراغ خاموش است.","ok":0,"eda":"Nej. Et slukket signal giver ingen forkørselsret.","efa":"خیر. چراغ خاموش حق تقدم نمی‌دهد.","en":"I have the right of way because the signal is switched off.","een":"No. A switched-off signal gives no right of way."},{"da":"Alle skal standse helt, som ved en stoptavle.","fa":"همه باید کاملاً بایستند، مثل تابلوی ایست.","ok":0,"eda":"Nej. Vigepligtstavlen kræver ikke fuldt stop, når vejen er fri.","efa":"خیر. تابلوی رعایت حق تقدم، وقتی راه باز است، توقف کامل لازم ندارد.","en":"Everyone must stop completely, as at a stop sign.","een":"No. The give-way sign does not require a full stop when the road is clear."},{"da":"Jeg kører frem med særlig forsigtighed.","fa":"با احتیاط ویژه جلو می‌روم.","ok":1,"eda":"Ja. Andre kan være i tvivl om, hvad der gælder.","efa":"بله. ممکن است دیگران مطمئن نباشند چه قاعده‌ای برقرار است.","en":"I move forward with special care.","een":"Yes. Others may be unsure about what applies."}]},{"id":5175,"img":"newq-art/5175.png","c":"8.1","sda":"Du skal køre en kort tur med en 7-årig pige, der er 125 cm høj, på bagsædet. Hvad gælder?","sfa":"قرار است با دختری ۷ ساله با قد ۱۲۵ سانتی‌متر که روی صندلی عقب نشسته، مسیر کوتاهی بروید. چه قاعده‌ای برقرار است؟","sen":"You are going on a short trip with a 7-year-old girl, 125 cm tall, on the back seat. What applies?","st":[{"da":"Hun skal være spændt fast, også på en kort tur.","fa":"حتی در مسیر کوتاه هم باید کمربندش بسته باشد.","ok":1,"eda":"Ja. Selepligten gælder hele kørslen, uanset hvor kort den er.","efa":"بله. وظیفه‌ی بستن کمربند در تمام مسیر است، هر قدر هم کوتاه باشد.","en":"She must be buckled up, even on a short trip.","een":"Yes. The duty to wear a belt applies to the whole trip, however short."},{"da":"Hun skal bruge godkendt sikkerhedsudstyr, der passer til hendes højde og vægt, fx en selepude med selen.","fa":"باید از تجهیزات ایمنی تأییدشده‌ی متناسب با قد و وزنش استفاده کند، مثلاً تشک‌چه‌ی بالابر با کمربند.","ok":1,"eda":"Ja. Børn under 135 cm skal under kørslen bruge godkendt sikkerhedsudstyr, der passer til barnets højde og vægt.","efa":"بله. کودکان زیر ۱۳۵ سانتی‌متر در حین رانندگی باید از تجهیزات ایمنی تأییدشده‌ی متناسب با قد و وزنشان استفاده کنند.","en":"She must use approved safety equipment that suits her height and weight, for example a booster cushion with the belt.","een":"Yes. Children under 135 cm must use approved safety equipment suited to their height and weight while driving."},{"da":"Hun må sidde uden sele, når hun sidder på bagsædet.","fa":"وقتی روی صندلی عقب نشسته، می‌تواند بدون کمربند بنشیند.","ok":0,"eda":"Nej. Selepligten gælder også på bagsædet.","efa":"خیر. وظیفه‌ی بستن کمربند در صندلی عقب هم هست.","en":"She may sit without a belt when she is on the back seat.","een":"No. The duty to wear a belt applies on the back seat too."},{"da":"Det er mit ansvar som fører, at hun er spændt fast.","fa":"این مسئولیت من به‌عنوان راننده است که کمربندش بسته باشد.","ok":1,"eda":"Ja. Føreren skal påse, at passagerer under 15 år bruger sikkerhedssele.","efa":"بله. راننده باید مراقب باشد مسافران زیر ۱۵ سال کمربند ببندند.","en":"It is my responsibility as the driver that she is buckled up.","een":"Yes. The driver must see to it that passengers under 15 use seat belts."}]},{"id":5176,"img":"newq-art/5176.png","c":"7.4","sda":"Vejen har to vognbaner i din retning før krydset, og du skal ligeud. Hvad gælder?","sfa":"جاده پیش از تقاطع در جهت شما دو خط دارد و می‌خواهید مستقیم بروید. چه قاعده‌ای برقرار است؟","sen":"The road has two lanes in your direction before the junction, and you are going straight on. What applies?","st":[{"da":"Jeg skifter vognbane inde i krydset, hvis den anden vognbane kører hurtigere.","fa":"اگر خط دیگر سریع‌تر حرکت کند، داخل تقاطع خطم را عوض می‌کنم.","ok":0,"eda":"Nej. Et vognbaneskift i krydset kan overraske dem ved siden af dig og skabe fare.","efa":"خیر. تغییر خط داخل تقاطع ممکن است کناری‌ها را غافلگیر کند و خطر بسازد.","en":"I change lanes inside the junction if the other lane is moving faster.","een":"No. A lane change in the junction can surprise those beside you and cause danger."},{"da":"Jeg skal altid bruge den venstre vognbane, når jeg skal ligeud.","fa":"وقتی مستقیم می‌روم، همیشه باید از خط چپ استفاده کنم.","ok":0,"eda":"Nej. Der er ingen sådan regel; vælg den mest hensigtsmæssige vognbane.","efa":"خیر. چنین قاعده‌ای نیست؛ مناسب‌ترین خط را انتخاب کنید.","en":"I must always use the left lane when I am going straight on.","een":"No. There is no such rule; choose the most suitable lane."},{"da":"Jeg kan bruge den vognbane, der passer bedst til trafikken og min videre kørsel.","fa":"می‌توانم از خطی استفاده کنم که با ترافیک و ادامه‌ی مسیرم بیشتر جور است.","ok":1,"eda":"Ja. Skal du ligeud, kan du bruge den vognbane, der er mest hensigtsmæssig.","efa":"بله. اگر مستقیم می‌روید، می‌توانید از مناسب‌ترین خط استفاده کنید.","en":"I can use the lane that best suits the traffic and where I am going next.","een":"Yes. If you are going straight on, you may use the lane that is most suitable."},{"da":"Jeg vælger vognbane i god tid før krydset.","fa":"به موقع پیش از تقاطع خطم را انتخاب می‌کنم.","ok":1,"eda":"Ja. Placeringen skal ske i god tid før vejkrydset.","efa":"بله. قرار گرفتن در خط باید به موقع پیش از تقاطع انجام شود.","en":"I choose my lane in good time before the junction.","een":"Yes. You must take up your position in good time before the junction."}]},{"id":5177,"img":"newq-art/5177.png","c":"7.4","sda":"Mellem din vognbane og vognbanen til venstre er der nu en ubrudt linje. Du vil gerne over i venstre vognbane. Hvad gælder?","sfa":"اکنون بین خط شما و خط سمت چپ یک خط ممتد است. می‌خواهید به خط چپ بروید. چه قاعده‌ای برقرار است؟","sen":"Between your lane and the lane to the left there is now an unbroken line. You would like to move into the left lane. What applies?","st":[{"da":"Linjen gælder kun for lastbiler.","fa":"این خط فقط برای کامیون‌هاست.","ok":0,"eda":"Nej. Linjen gælder alle kørende.","efa":"خیر. این خط برای همه‌ی رانندگان است.","en":"The line only applies to lorries.","een":"No. The line applies to all drivers."},{"da":"Jeg må ikke skifte vognbane over den ubrudte linje.","fa":"نباید از روی خط ممتد تغییر خط بدهم.","ok":1,"eda":"Ja. En spærrelinje adskiller vognbanerne og må ikke overskrides.","efa":"بله. خط ممتد خط‌ها را از هم جدا می‌کند و نباید از آن رد شد.","en":"I must not change lanes across the unbroken line.","een":"Yes. A barrier line separates the lanes and must not be crossed."},{"da":"Jeg må skifte, hvis jeg blinker i god tid.","fa":"اگر به موقع راهنما بزنم، می‌توانم خطم را عوض کنم.","ok":0,"eda":"Nej. Blinklyset gør det ikke tilladt at overskride spærrelinjen.","efa":"خیر. راهنما عبور از خط ممتد را مجاز نمی‌کند.","en":"I may change if I signal in good time.","een":"No. The indicator does not make it allowed to cross the barrier line."}]},{"id":5178,"img":"newq-art/5178.png","c":"7.4","sda":"Du kører forbi denne tavle, og to kørebaner løber sammen længere fremme. Hvad gælder?","sfa":"از کنار این تابلو رد می‌شوید و کمی جلوتر دو سواره‌رو به هم می‌پیوندند. چه قاعده‌ای برقرار است؟","sen":"You pass this sign, and two carriageways join further ahead. What applies?","st":[{"da":"Kørebanerne løber sammen længere fremme.","fa":"سواره‌روها کمی جلوتر به هم می‌پیوندند.","ok":1,"eda":"Ja. Tavlen (B 15) angiver, at kørebaner løber sammen.","efa":"بله. این تابلو (B 15) نشان می‌دهد سواره‌روها به هم می‌پیوندند.","en":"The carriageways join further ahead.","een":"Yes. The sign (B 15) shows that carriageways join."},{"da":"Vi skal under gensidig hensyntagen lette sammenfletningen.","fa":"باید با ملاحظه‌ی متقابل ادغام را آسان کنیم.","ok":1,"eda":"Ja. Ved tavlen skal trafikanterne under gensidig hensyntagen lette sammenfletningen.","efa":"بله. کنار این تابلو کاربران راه باید با ملاحظه‌ی متقابل ادغام را آسان کنند.","en":"We must make the merging easier with mutual consideration.","een":"Yes. At the sign road users must make the merging easier with mutual consideration."},{"da":"Jeg tilpasser farten, så jeg kan flette ind i et hul.","fa":"سرعتم را تنظیم می‌کنم تا در یک فاصله ادغام شوم.","ok":1,"eda":"Ja. Med passende fart og afstand kan begge kørebaners trafik glide sammen.","efa":"بله. با سرعت و فاصله‌ی مناسب، ترافیک هر دو سواره‌رو روان به هم می‌پیوندد.","en":"I adjust my speed so that I can merge into a gap.","een":"Yes. With a suitable speed and distance the traffic from both carriageways can flow together."},{"da":"Den, der kører på den største vej, har altid forkørselsret.","fa":"هر که در جاده‌ی بزرگ‌تر باشد، همیشه حق تقدم دارد.","ok":0,"eda":"Nej. Ved sammenfletning skal begge parter vise hensyn.","efa":"خیر. در ادغام هر دو طرف باید ملاحظه کنند.","en":"Whoever is on the bigger road always has the right of way.","een":"No. When merging, both sides must show consideration."}]},{"id":5179,"img":"newq-art/5179.png","c":"7.1","sda":"Du holder ved kantstenen og vil køre ud. En bil nærmer sig bagfra. Hvordan forholder du dig?","sfa":"کنار جدول ایستاده‌اید و می‌خواهید حرکت کنید. خودرویی از پشت نزدیک می‌شود. چه می‌کنید؟","sen":"You are standing at the kerb and want to drive off. A car is approaching from behind. What do you do?","st":[{"da":"Jeg giver tegn, før jeg kører ud fra kanten.","fa":"پیش از حرکت از کنار جدول علامت می‌دهم.","ok":1,"eda":"Ja. Du skal give tegn før igangsætning fra vejkanten.","efa":"بله. پیش از حرکت از کنار جاده باید علامت بدهید.","en":"I signal before I pull away from the kerb.","een":"Yes. You must signal before pulling away from the edge of the road."},{"da":"Bilen bag mig skal sænke farten, når jeg blinker.","fa":"خودروی پشتی وقتی راهنما بزنم باید سرعتش را کم کند.","ok":0,"eda":"Nej. Blinklyset giver dig ikke ret til at køre ud.","efa":"خیر. راهنما به شما حق حرکت نمی‌دهد.","en":"The car behind me must slow down when I signal.","een":"No. The indicator does not give you the right to pull out."},{"da":"Jeg venter, til bilen er kørt forbi.","fa":"صبر می‌کنم تا آن خودرو رد شود.","ok":1,"eda":"Ja. Du må kun køre ud fra vejkanten, når det kan ske uden fare eller unødig ulempe for andre.","efa":"بله. فقط وقتی می‌توانید از کنار جاده حرکت کنید که برای دیگران خطر یا مزاحمت بی‌جا نداشته باشد.","en":"I wait until the car has gone past.","een":"Yes. You may only pull away from the kerb when it can be done without danger or undue inconvenience to others."},{"da":"Jeg kører hurtigt ud foran bilen.","fa":"سریع جلوی آن خودرو بیرون می‌روم.","ok":0,"eda":"Nej. Bilen kan blive tvunget til at bremse eller svinge ud.","efa":"خیر. ممکن است آن خودرو مجبور به ترمز یا انحراف شود.","en":"I pull out quickly in front of the car.","een":"No. The car may be forced to brake or swerve."}]},{"id":5180,"img":"newq-art/5180.png","c":"7.1","sda":"Du holder ved kantstenen på en stejl vej op ad bakke og skal køre ud. Hvordan forholder du dig?","sfa":"کنار جدول در سربالایی تندی ایستاده‌اید و می‌خواهید حرکت کنید. چه می‌کنید؟","sen":"You are standing at the kerb on a steep road uphill and are going to drive off. What do you do?","st":[{"da":"Det gør ikke noget, at bilen ruller lidt tilbage, når jeg starter.","fa":"اشکالی ندارد اگر خودرو هنگام حرکت کمی به عقب برود.","ok":0,"eda":"Nej. Selv lidt kan være nok til at ramme nogen bag dig.","efa":"خیر. حتی کمی هم ممکن است برای برخورد با کسی پشت سرتان کافی باشد.","en":"It does not matter if the car rolls back a little when I start.","een":"No. Even a little can be enough to hit someone behind you."},{"da":"Jeg giver fuld gas, så jeg hurtigt kommer op ad bakken.","fa":"تا ته گاز می‌دهم تا زود از تپه بالا بروم.","ok":0,"eda":"Nej. Kør roligt ud; fuld gas kan få bilen til at skride eller springe frem.","efa":"خیر. آرام حرکت کنید؛ گاز کامل ممکن است خودرو را بلغزاند یا به جلو پرتاب کند.","en":"I put my foot down so that I get up the hill quickly.","een":"No. Pull away calmly; full throttle can make the car skid or jump forward."},{"da":"Jeg ser mig for og giver tegn, før jeg kører ud.","fa":"پیش از حرکت اطراف را نگاه می‌کنم و علامت می‌دهم.","ok":1,"eda":"Ja. Før igangsætning fra vejkanten skal du give tegn og sikre dig, at det kan ske uden fare.","efa":"بله. پیش از حرکت از کنار جاده باید علامت بدهید و مطمئن شوید بی‌خطر است.","en":"I look around and signal before I pull out.","een":"Yes. Before pulling away from the edge you must signal and make sure it can be done safely."},{"da":"Jeg bruger parkeringsbremsen eller bilens bakkestart, så bilen ikke ruller tilbage.","fa":"از ترمز دستی یا سیستم کمک شروع در سربالایی استفاده می‌کنم تا خودرو به عقب نرود.","ok":1,"eda":"Ja. Ruller bilen tilbage, kan den ramme den bil eller cyklist, der holder bag den.","efa":"بله. اگر خودرو به عقب برود، ممکن است به خودرو یا دوچرخه‌سوار پشتی بخورد.","en":"I use the parking brake or the car's hill-start aid so that the car does not roll back.","een":"Yes. If the car rolls back, it may hit a car or cyclist standing behind it."}]},{"id":5181,"img":"newq-art/5181.png","c":"7.1","sda":"Du vil standse ved kantstenen for at sætte en passager af. Hvordan forholder du dig?","sfa":"می‌خواهید کنار جدول بایستید تا مسافری پیاده شود. چه می‌کنید؟","sen":"You want to stop at the kerb to let a passenger out. What do you do?","st":[{"da":"Jeg ser i spejlet og giver tegn i god tid.","fa":"در آینه نگاه می‌کنم و به موقع علامت می‌دهم.","ok":1,"eda":"Ja. Dem bag dig skal kunne se, at du vil standse.","efa":"بله. پشت‌سری‌ها باید بتوانند ببینند که می‌خواهید بایستید.","en":"I look in the mirror and signal in good time.","een":"Yes. Those behind you must be able to see that you are going to stop."},{"da":"Jeg standser skråt, så jeg hurtigt kan køre ud igen.","fa":"کج می‌ایستم تا زود دوباره حرکت کنم.","ok":0,"eda":"Nej. En skrå bil kan spærre for cyklister og anden trafik.","efa":"خیر. خودروی کج ممکن است راه دوچرخه‌سواران و دیگر ترافیک را ببندد.","en":"I stop at an angle so that I can drive off again quickly.","een":"No. A car at an angle can block cyclists and other traffic."},{"da":"Jeg standser i vejens længderetning tæt ved kørebanens kant.","fa":"در امتداد طول جاده و نزدیک لبه‌ی سواره‌رو می‌ایستم.","ok":1,"eda":"Ja. Ved standsning skal køretøjet anbringes i vejens længderetning ved kørebanens yderkant.","efa":"بله. هنگام توقف، خودرو باید در امتداد طول جاده و کنار لبه‌ی سواره‌رو قرار بگیرد.","en":"I stop lengthwise along the road close to the edge of the carriageway.","een":"Yes. When stopping, the vehicle must be placed lengthwise along the road at the edge of the carriageway."},{"da":"Jeg sikrer mig, at passageren kan stige ud uden fare.","fa":"مطمئن می‌شوم مسافر بی‌خطر پیاده شود.","ok":1,"eda":"Ja. Åbning af døre og afstigning skal ske uden fare eller unødig ulempe.","efa":"بله. باز کردن در و پیاده شدن باید بدون خطر یا مزاحمت بی‌جا باشد.","en":"I make sure that the passenger can get out safely.","een":"Yes. Opening doors and getting out must be done without danger or undue inconvenience."}]},{"id":5182,"img":"newq-art/5182.png","c":"7.2","sda":"Vejen svinger til venstre, og du kan ikke se langt frem. Hvordan placerer du bilen?","sfa":"جاده به چپ می‌پیچد و دور را نمی‌بینید. خودرو را چطور قرار می‌دهید؟","sen":"The road bends to the left, and you cannot see far ahead. How do you position the car?","st":[{"da":"Jeg kører midt på vejen, så jeg kan se længere.","fa":"وسط جاده می‌رانم تا دورتر را ببینم.","ok":0,"eda":"Nej. Midt på vejen risikerer du at møde en modkørende frontalt.","efa":"خیر. وسط جاده خطر برخورد رودررو با خودروی مقابل هست.","en":"I drive in the middle of the road so that I can see further.","een":"No. In the middle of the road you risk meeting an oncoming car head-on."},{"da":"Jeg skærer svinget for at køre mere jævnt.","fa":"پیچ را میان‌بر می‌زنم تا نرم‌تر برانم.","ok":0,"eda":"Nej. Så kommer du over i den modkørendes side, hvor du ikke kan se, hvad der kommer.","efa":"خیر. این‌طور وارد سمت مقابل می‌شوید، جایی که نمی‌بینید چه می‌آید.","en":"I cut the corner to drive more smoothly.","een":"No. Then you move into the oncoming side, where you cannot see what is coming."},{"da":"Jeg holder mig i højre side af min vognbane.","fa":"در سمت راست خط خودم می‌مانم.","ok":1,"eda":"Ja. Kørende skal holde så langt til højre som muligt; i et venstresving kan en modkørende være tæt på midterlinjen.","efa":"بله. رانندگان باید تا جای ممکن سمت راست بمانند؛ در پیچ به چپ ممکن است خودروی روبه‌رو نزدیک خط وسط باشد.","en":"I keep to the right-hand side of my lane.","een":"Yes. Drivers must keep as far right as possible; in a left bend an oncoming car may be close to the centre line."}]},{"id":5183,"img":"newq-art/5183.png","c":"7.2","sda":"Du kører uden for byen på en vej med to vognbaner i din retning og har ikke tænkt dig at overhale. Hvor kører du?","sfa":"بیرون از شهر در جاده‌ای با دو خط در جهت خودتان می‌رانید و قصد سبقت ندارید. کجا می‌رانید؟","sen":"You are driving outside town on a road with two lanes in your direction and are not planning to overtake. Where do you drive?","st":[{"da":"I venstre vognbane, fordi den er hurtigst.","fa":"در خط چپ، چون سریع‌تر است.","ok":0,"eda":"Nej. Du må kun ligge i venstre vognbane, mens du overhaler.","efa":"خیر. فقط هنگام سبقت می‌توانید در خط چپ باشید.","en":"In the left lane, because it is the fastest.","een":"No. You may only be in the left lane while you are overtaking."},{"da":"I den vognbane, hvor der er færrest biler.","fa":"در خطی که خودروی کمتری دارد.","ok":0,"eda":"Nej. Hovedreglen er at holde til højre.","efa":"خیر. قاعده‌ی اصلی سمت راست ماندن است.","en":"In the lane with the fewest cars.","een":"No. The main rule is to keep right."},{"da":"Midt mellem vognbanerne, så jeg kan vælge senere.","fa":"وسط دو خط، تا بعداً انتخاب کنم.","ok":0,"eda":"Nej. Du skal køre inden for én vognbane.","efa":"خیر. باید داخل یک خط برانید.","en":"In the middle between the lanes, so that I can choose later.","een":"No. You must drive within one lane."},{"da":"I højre vognbane.","fa":"در خط راست.","ok":1,"eda":"Ja. Kørende skal holde så langt til højre som muligt; venstre vognbane bruges til at overhale.","efa":"بله. رانندگان باید تا جای ممکن سمت راست بمانند؛ خط چپ برای سبقت است.","en":"In the right-hand lane.","een":"Yes. Drivers must keep as far right as possible; the left lane is used for overtaking."}]},{"id":5184,"img":"newq-art/5184.png","c":"7.2","sda":"Vejen har ingen midterlinje, men er bred nok til to biler. Hvordan placerer du dig?","sfa":"جاده خط وسط ندارد، ولی برای دو خودرو جا دارد. خودتان را چطور قرار می‌دهید؟","sen":"The road has no centre line but is wide enough for two cars. How do you position yourself?","st":[{"da":"Jeg giver manden med hunden god plads, når jeg kører forbi.","fa":"هنگام عبور جای زیادی به مرد و سگش می‌دهم.","ok":1,"eda":"Ja. Du skal give gående tid til at vige og fornøden plads.","efa":"بله. باید به عابران فرصت کنار رفتن و جای لازم بدهید.","en":"I give the man with the dog plenty of room when I pass.","een":"Yes. You must give pedestrians time to step aside and the room they need."},{"da":"Jeg kører midt på vejen, når der ikke er en midterlinje.","fa":"وقتی خط وسط نیست، وسط جاده می‌رانم.","ok":0,"eda":"Nej. Så kan du møde en modkørende, der heller ikke kan se dig, fx i svinget.","efa":"خیر. این‌طور ممکن است با خودروی مقابلی روبه‌رو شوید که شما را نمی‌بیند، مثلاً در پیچ.","en":"I drive in the middle of the road when there is no centre line.","een":"No. Then you may meet an oncoming car that cannot see you either, for example in the bend."},{"da":"Jeg er særligt opmærksom på modkørende i svinget.","fa":"در پیچ به ترافیک روبه‌رو توجه ویژه دارم.","ok":1,"eda":"Ja. Uden midterlinje kan modkørende ligge tæt på midten af vejen.","efa":"بله. بدون خط وسط، خودروهای روبه‌رو ممکن است نزدیک وسط جاده باشند.","en":"I pay special attention to oncoming traffic in the bend.","een":"Yes. Without a centre line oncoming cars may be close to the middle of the road."},{"da":"Jeg holder så langt til højre, som forholdene tillader.","fa":"تا جایی که شرایط اجازه دهد سمت راست می‌مانم.","ok":1,"eda":"Ja. Reglen om at holde til højre gælder, også når der ikke er en midterlinje.","efa":"بله. قاعده‌ی سمت راست ماندن حتی وقتی خط وسط نیست برقرار است.","en":"I keep as far to the right as the conditions allow.","een":"Yes. The keep-right rule applies even when there is no centre line."}]},{"id":5185,"img":"newq-art/5185.png","c":"7.19","sda":"Du kører på en mørk landevej uden gadelys. Ingen kommer imod dig, og der kører ingen foran dig. Hvilket lys bruger du?","sfa":"در جاده‌ای تاریک و بدون چراغ خیابان می‌رانید. کسی از روبه‌رو نمی‌آید و کسی هم جلوی شما نیست. از کدام چراغ استفاده می‌کنید؟","sen":"You are driving on a dark country road without street lights. Nobody is coming towards you, and nobody is driving in front of you. Which lights do you use?","st":[{"da":"Jeg blænder ned i god tid, når der kommer en modkørende.","fa":"وقتی وسیله‌ای از روبه‌رو پیدا شد، به موقع نور را پایین می‌آورم.","ok":1,"eda":"Ja. Fjernlys må ikke bruges ved møde, hvor den modkørende kan blændes.","efa":"بله. هنگام برخورد با وسیله‌ای که ممکن است خیره شود، نور بالا ممنوع است.","en":"I dip in good time when an oncoming vehicle appears.","een":"Yes. High beam must not be used when meeting someone who could be dazzled."},{"da":"Fjernlys, når nærlyset ikke lyser langt nok frem til min fart.","fa":"نور بالا، وقتی نور پایین برای سرعتم به اندازه‌ی کافی دور را روشن نمی‌کند.","ok":1,"eda":"Ja. Fjernlys skal bruges, når førerens synsvidde under hensyn til hastigheden ellers er utilstrækkelig.","efa":"بله. وقتی دید راننده با توجه به سرعت در غیر این صورت کافی نیست، باید از نور بالا استفاده کرد.","en":"High beam, when the dipped beam does not reach far enough ahead for my speed.","een":"Yes. High beam must be used when the driver's range of vision would otherwise be too short for the speed."},{"da":"Jeg kører altid med nærlys om natten for ikke at genere nogen.","fa":"شب‌ها همیشه با نور پایین می‌رانم تا مزاحم کسی نشوم.","ok":0,"eda":"Nej. Er udsynet for kort til farten, skal du bruge fjernlys eller køre langsommere.","efa":"خیر. اگر دیدتان برای سرعتتان کوتاه است، باید از نور بالا استفاده کنید یا آهسته‌تر برانید.","en":"I always drive with dipped beam at night so as not to bother anyone.","een":"No. If your view is too short for your speed, you must use high beam or drive more slowly."},{"da":"Fjernlys må kun bruges på motorvej.","fa":"نور بالا فقط در بزرگراه مجاز است.","ok":0,"eda":"Nej. Fjernlys bruges på alle uoplyste veje, når der er behov for det.","efa":"خیر. نور بالا در همه‌ی جاده‌های بی‌چراغ، وقتی لازم باشد، استفاده می‌شود.","en":"High beam may only be used on the motorway.","een":"No. High beam is used on all unlit roads when it is needed."}]},{"id":5186,"img":"newq-art/5186.png","c":"7.19","sda":"Hvad gælder om bilens lys?","sfa":"درباره‌ی چراغ‌های خودرو چه قاعده‌ای برقرار است؟","sen":"What applies to the car's lights?","st":[{"da":"Om dagen må jeg køre helt uden lys.","fa":"روزها می‌توانم کاملاً بدون چراغ برانم.","ok":0,"eda":"Nej. Bilen skal også om dagen køre med lys.","efa":"خیر. خودرو روزها هم باید با چراغ حرکت کند.","en":"In the daytime I may drive with no lights at all.","een":"No. The car must have lights on in the daytime too."},{"da":"I lygtetændingstiden, fra solnedgang til solopgang, skal de påbudte lygter være tændt.","fa":"در زمان روشن کردن چراغ‌ها، از غروب تا طلوع، چراغ‌های الزامی باید روشن باشند.","ok":1,"eda":"Ja. Lygtetændingstiden er fra solnedgang til solopgang.","efa":"بله. زمان روشن کردن چراغ‌ها از غروب تا طلوع آفتاب است.","en":"During lighting-up time, from sunset to sunrise, the required lights must be on.","een":"Yes. Lighting-up time is from sunset to sunrise."},{"da":"Lygtetændingstiden er kun fra midnat til kl. 5.","fa":"زمان روشن کردن چراغ‌ها فقط از نیمه‌شب تا ساعت ۵ است.","ok":0,"eda":"Nej. Den følger solen: fra solnedgang til solopgang.","efa":"خیر. این زمان از خورشید پیروی می‌کند: از غروب تا طلوع.","en":"Lighting-up time is only from midnight to 5 am.","een":"No. It follows the sun: from sunset to sunrise."},{"da":"Også om dagen skal bilen køre med nærlys eller kørelys.","fa":"روزها هم خودرو باید با نور پایین یا چراغ روز حرکت کند.","ok":1,"eda":"Ja. Uden for lygtetændingstiden skal der køres med nærlys eller kørelys.","efa":"بله. بیرون از زمان روشن کردن چراغ‌ها باید با نور پایین یا چراغ روز رانندگی کرد.","en":"In the daytime too the car must drive with dipped beam or daytime running lights.","een":"Yes. Outside lighting-up time you must drive with dipped beam or daytime running lights."}]},{"id":5187,"img":"newq-art/5187.png","c":"7.19","sda":"Det er tørt og klart vejr i mørke. Hvad gælder om tågelygterne?","sfa":"در تاریکی، هوا خشک و صاف است. درباره‌ی چراغ‌های مه‌شکن چه قاعده‌ای برقرار است؟","sen":"It is dry and clear weather in the dark. What applies to the fog lights?","st":[{"da":"Tågebaglygten må altid være tændt i mørke.","fa":"چراغ مه‌شکن عقب در تاریکی همیشه می‌تواند روشن باشد.","ok":0,"eda":"Nej. Den kraftige tågebaglygte blænder dem bag dig i klart vejr.","efa":"خیر. چراغ مه‌شکن پرنور عقب، در هوای صاف پشت‌سری‌ها را خیره می‌کند.","en":"The rear fog light may always be on in the dark.","een":"No. The bright rear fog light dazzles those behind you in clear weather."},{"da":"Jeg må bruge dem i stedet for nærlys, når jeg vil se bedre.","fa":"وقتی بخواهم بهتر ببینم، می‌توانم به‌جای نور پایین از آن‌ها استفاده کنم.","ok":0,"eda":"Nej. Det må de kun i tåge og under kraftig nedbør.","efa":"خیر. این کار فقط در مه و بارش شدید مجاز است.","en":"I may use them instead of dipped beam when I want to see better.","een":"No. They may only do that in fog and heavy precipitation."},{"da":"Tågelygter må bruges, når vejen er våd.","fa":"وقتی جاده خیس است، چراغ مه‌شکن مجاز است.","ok":0,"eda":"Nej. En våd vej er ikke tåge eller kraftig nedbør.","efa":"خیر. جاده‌ی خیس به معنای مه یا بارش شدید نیست.","en":"Fog lights may be used when the road is wet.","een":"No. A wet road is not fog or heavy precipitation."},{"da":"Jeg må ikke bruge dem, fordi der ikke er tåge eller kraftig nedbør.","fa":"نباید از آن‌ها استفاده کنم، چون مه یا بارش شدیدی نیست.","ok":1,"eda":"Ja. Tågelygter må kun bruges i tåge og under kraftig nedbør.","efa":"بله. چراغ مه‌شکن فقط در مه و بارش شدید مجاز است.","en":"I must not use them because there is no fog or heavy precipitation.","een":"Yes. Fog lights may only be used in fog and heavy precipitation."}]},{"id":5188,"img":"newq-art/5188.png","c":"7.16","sda":"Du skal forlade motorvejen ved den næste frakørsel. Hvordan forholder du dig?","sfa":"می‌خواهید در خروجی بعدی از بزرگراه خارج شوید. چه می‌کنید؟","sen":"You are going to leave the motorway at the next exit. What do you do?","st":[{"da":"Jeg sætter farten ned på frakørselsbanen og ikke på motorvejen.","fa":"سرعتم را در خط خروج کم می‌کنم، نه در بزرگراه.","ok":1,"eda":"Ja. Så generer du ikke trafikken på motorvejen.","efa":"بله. این‌طور مزاحم ترافیک بزرگراه نمی‌شوید.","en":"I slow down in the exit lane, not on the motorway.","een":"Yes. That way you do not hold up the traffic on the motorway."},{"da":"Jeg holder øje med farten, fordi frakørselsvejen kan ende i et skarpt sving.","fa":"مراقب سرعتم هستم، چون راه خروجی ممکن است به پیچ تندی برسد.","ok":1,"eda":"Ja. Efter motorvejen føles farten lavere, end den er.","efa":"بله. بعد از بزرگراه سرعت کمتر از مقدار واقعی‌اش حس می‌شود.","en":"I watch my speed because the exit road may end in a sharp bend.","een":"Yes. After the motorway your speed feels lower than it is."},{"da":"Jeg kører ind på frakørselsbanen, så snart den begynder.","fa":"به محض شروع خط خروج واردش می‌شوم.","ok":1,"eda":"Ja. Frakørselsbanen skal benyttes med det samme, når den begynder.","efa":"بله. از خط خروج باید به محض شروعش استفاده کرد.","en":"I move into the exit lane as soon as it begins.","een":"Yes. The exit lane must be used straight away, as soon as it begins."},{"da":"Jeg giver tegn i god tid, før jeg skifter over på frakørselsbanen.","fa":"پیش از رفتن به خط خروج، به موقع راهنما می‌زنم.","ok":1,"eda":"Ja. På motorvej skal du give tegn før et vognbaneskift.","efa":"بله. در بزرگراه پیش از تغییر خط باید علامت بدهید.","en":"I signal in good time before I move over into the exit lane.","een":"Yes. On the motorway you must signal before a lane change."}]},{"id":5189,"img":"newq-art/5189.png","c":"7.16","sda":"Du kører på motorvejen med to vognbaner i din retning. Hvad gælder?","sfa":"در بزرگراهی با دو خط در جهت خودتان می‌رانید. چه قاعده‌ای برقرار است؟","sen":"You are driving on the motorway with two lanes in your direction. What applies?","st":[{"da":"Jeg giver tegn, før jeg skifter vognbane.","fa":"پیش از تغییر خط علامت می‌دهم.","ok":1,"eda":"Ja. På motorvej skal der gives tegn før vognbaneskift.","efa":"بله. در بزرگراه پیش از تغییر خط باید علامت داد.","en":"I signal before I change lanes.","een":"Yes. On the motorway a signal must be given before a lane change."},{"da":"Jeg kører i højre vognbane, når jeg ikke overhaler.","fa":"وقتی سبقت نمی‌گیرم، در خط راست می‌رانم.","ok":1,"eda":"Ja. Kørende skal holde så langt til højre som muligt.","efa":"بله. رانندگان باید تا جای ممکن سمت راست بمانند.","en":"I drive in the right lane when I am not overtaking.","een":"Yes. Drivers must keep as far to the right as possible."},{"da":"Jeg må blive i venstre vognbane, så længe jeg kører 130 km/t.","fa":"تا وقتی ۱۳۰ می‌رانم، می‌توانم در خط چپ بمانم.","ok":0,"eda":"Nej. Fart giver ingen ret til at blive i venstre vognbane.","efa":"خیر. سرعت حق ماندن در خط چپ را نمی‌دهد.","en":"I may stay in the left lane as long as I am doing 130 km/h.","een":"No. Speed gives no right to stay in the left lane."},{"da":"Jeg må køre i nødsporet, når der er kø.","fa":"وقتی صف است، می‌توانم در شانه‌ی اضطراری برانم.","ok":0,"eda":"Nej. Nødsporet er til nødsituationer, ikke til at køre forbi en kø.","efa":"خیر. شانه‌ی اضطراری برای مواقع اضطراری است، نه برای عبور از کنار صف.","en":"I may drive on the hard shoulder when there is a queue.","een":"No. The hard shoulder is for emergencies, not for driving past a queue."}]},{"id":5190,"img":"newq-art/5190.png","c":"6.2","sda":"Hvornår må du bruge bilens horn?","sfa":"کی می‌توانید از بوق خودرو استفاده کنید؟","sen":"When may you use the car's horn?","st":[{"da":"I lygtetændingstiden skal jeg bruge lyssignal i stedet, medmindre faren er overhængende.","fa":"در زمان روشن کردن چراغ‌ها باید به‌جای بوق چراغ بزنم، مگر خطر فوری باشد.","ok":1,"eda":"Ja. I lygtetændingstiden skal fører af motorkøretøj bruge lyssignal i stedet for lydsignal, medmindre faren er overhængende.","efa":"بله. در زمان روشن کردن چراغ‌ها راننده‌ی وسیله‌ی موتوری باید به‌جای بوق چراغ بزند، مگر خطر فوری باشد.","en":"During lighting-up time I must use a light signal instead, unless the danger is immediate.","een":"Yes. During lighting-up time the driver of a motor vehicle must use a light signal instead of the horn, unless the danger is immediate."},{"da":"For at få bilen foran til at køre, når lyset bliver grønt.","fa":"برای این‌که خودروی جلو با سبز شدن چراغ حرکت کند.","ok":0,"eda":"Nej. At skynde på andre er ikke at afværge fare.","efa":"خیر. عجله‌ دادن به دیگران دفع خطر نیست.","en":"To make the car in front go when the light turns green.","een":"No. Hurrying others is not averting danger."},{"da":"Når det er nødvendigt for at forebygge eller afværge fare.","fa":"وقتی برای پیشگیری یا دفع خطر لازم باشد.","ok":1,"eda":"Ja. Lydsignal må kun bruges, når det er nødvendigt for at forebygge eller afværge fare, og ikke længere end nødvendigt.","efa":"بله. بوق فقط وقتی مجاز است که برای پیشگیری یا دفع خطر لازم باشد، و نه بیشتر از حد لازم.","en":"When it is necessary to prevent or avert danger.","een":"Yes. The horn may only be used when it is necessary to prevent or avert danger, and no longer than necessary."},{"da":"For at hilse på en ven.","fa":"برای سلام کردن به یک دوست.","ok":0,"eda":"Nej. Hornet må ikke bruges til andet end at afværge fare.","efa":"خیر. از بوق فقط برای دفع خطر می‌توان استفاده کرد.","en":"To greet a friend.","een":"No. The horn must not be used for anything other than averting danger."}]},{"id":5191,"img":"newq-art/5191.png","c":"6.2","sda":"Du har grønt lys, men en brandbil med blå blink og sirene er ved at køre ind i krydset fra venstre. Hvordan forholder du dig?","sfa":"چراغ شما سبز است، ولی یک ماشین آتش‌نشانی با چراغ آبی و آژیر از چپ وارد تقاطع می‌شود. چه می‌کنید؟","sen":"You have a green light, but a fire engine with flashing blue lights and siren is about to drive into the junction from the left. What do you do?","st":[{"da":"Jeg holder tilbage og lader brandbilen komme igennem.","fa":"صبر می‌کنم و می‌گذارم ماشین آتش‌نشانی رد شود.","ok":1,"eda":"Ja. Kørende skal holde vejen åben for et udrykningskøretøj og om nødvendigt standse.","efa":"بله. رانندگان باید راه را برای خودروی امدادی باز نگه دارند و در صورت لزوم بایستند.","en":"I hold back and let the fire engine through.","een":"Yes. Drivers must keep the road open for an emergency vehicle and stop if necessary."},{"da":"Jeg holder øje med, om der kommer flere udrykningskøretøjer.","fa":"مراقبم که خودروهای امدادی دیگری هم می‌آیند یا نه.","ok":1,"eda":"Ja. Udrykningskøretøjer kører ofte flere sammen.","efa":"بله. خودروهای امدادی اغلب چندتایی با هم می‌آیند.","en":"I watch whether more emergency vehicles are coming.","een":"Yes. Emergency vehicles often come several at a time."},{"da":"Jeg gør det i god tid, så brandbilen ikke skal bremse.","fa":"این کار را به موقع انجام می‌دهم تا ماشین آتش‌نشانی مجبور به ترمز نشود.","ok":1,"eda":"Ja. Vejen skal holdes åben i god tid.","efa":"بله. راه باید به موقع باز نگه داشته شود.","en":"I do it in good time so that the fire engine does not have to brake.","een":"Yes. The road must be kept open in good time."},{"da":"Jeg kører, fordi jeg har grønt lys.","fa":"حرکت می‌کنم، چون چراغم سبز است.","ok":0,"eda":"Nej. Grønt lys giver ikke ret til at spærre for et udrykningskøretøj.","efa":"خیر. چراغ سبز حق بستن راه خودروی امدادی را نمی‌دهد.","en":"I go because I have a green light.","een":"No. A green light gives no right to block an emergency vehicle."}]},{"id":5192,"img":"newq-art/5192.png","c":"7.15","sda":"Du kører ind i en rundkørsel med denne blå tavle. Hvad gælder?","sfa":"وارد میدانی با این تابلوی آبی می‌شوید. چه قاعده‌ای برقرار است؟","sen":"You are entering a roundabout with this blue sign. What applies?","st":[{"da":"Tavlen betyder, at jeg har forkørselsret i rundkørslen.","fa":"این تابلو یعنی در میدان حق تقدم با من است.","ok":0,"eda":"Nej. Tavlen siger kun noget om retningen; ved indkørslen har du her ubetinget vigepligt.","efa":"خیر. این تابلو فقط درباره‌ی جهت است؛ این‌جا هنگام ورود باید بی‌قیدوشرط راه بدهید.","en":"The sign means that I have the right of way in the roundabout.","een":"No. The sign only says something about direction; at the entry here you must give way unconditionally."},{"da":"Jeg må køre den korteste vej til venstre om øen.","fa":"می‌توانم از کوتاه‌ترین راه از سمت چپ جزیره بروم.","ok":0,"eda":"Nej. Det er at køre mod den påbudte retning.","efa":"خیر. این یعنی رانندگی خلاف جهت اجباری.","en":"I may take the shortest way round the island to the left.","een":"No. That is driving against the required direction."},{"da":"Tavlen viser den påbudte kørselsretning i rundkørslen.","fa":"این تابلو جهت اجباری حرکت در میدان را نشان می‌دهد.","ok":1,"eda":"Ja. Den blå tavle (D 12) er et påbud om kørselsretningen i rundkørslen.","efa":"بله. تابلوی آبی (D 12) دستوری درباره‌ی جهت حرکت در میدان است.","en":"The sign shows the required direction in the roundabout.","een":"Yes. The blue sign (D 12) is an order about the direction in the roundabout."},{"da":"Jeg kører rundt med midterøen på min venstre side.","fa":"با جزیره‌ی وسط در سمت چپم دور میدان می‌چرخم.","ok":1,"eda":"Ja. Kørende skal holde til højre for helleanlæg og lignende, så rundkørslen køres mod uret.","efa":"بله. رانندگان باید سمت راست جزیره‌ها بمانند، پس میدان خلاف جهت عقربه‌های ساعت دور زده می‌شود.","en":"I drive round with the central island on my left.","een":"Yes. Drivers must keep to the right of islands and the like, so the roundabout is driven anticlockwise."}]},{"id":5193,"img":"newq-art/5193.png","c":"7.15","sda":"Foran dig i rundkørslen kører en lang lastbil. Hvordan forholder du dig?","sfa":"جلوی شما در میدان یک کامیون بلند حرکت می‌کند. چه می‌کنید؟","sen":"A long lorry is driving in front of you in the roundabout. What do you do?","st":[{"da":"Jeg holder god afstand og kører ikke op ved siden af lastbilen.","fa":"فاصله‌ی خوبی نگه می‌دارم و کنار کامیون نمی‌روم.","ok":1,"eda":"Ja. Ved siden af lastbilen kan du blive klemt, når den svinger.","efa":"بله. کنار کامیون ممکن است هنگام پیچیدنش گیر بیفتید.","en":"I keep a good distance and do not drive up beside the lorry.","een":"Yes. Beside the lorry you may get squeezed when it turns."},{"da":"Lastbilen kan have brug for hele rundkørslens bredde.","fa":"کامیون ممکن است به تمام عرض میدان نیاز داشته باشد.","ok":1,"eda":"Ja. Lange køretøjer skærer svinget og kan køre over den brostensbelagte kant ved midterøen.","efa":"بله. وسایل بلند از داخل پیچ می‌گذرند و ممکن است از روی حلقه‌ی سنگ‌فرش کنار جزیره رد شوند.","en":"The lorry may need the whole width of the roundabout.","een":"Yes. Long vehicles cut the corner and may drive over the cobbled ring by the island."},{"da":"Lastbilen skal holde helt ind til højre kant hele vejen rundt.","fa":"کامیون باید تمام مسیر کاملاً به لبه‌ی راست بچسبد.","ok":0,"eda":"Nej. Det kan en lang lastbil ikke; dens bagende skærer svinget.","efa":"خیر. کامیون بلند نمی‌تواند؛ قسمت عقبش از داخل پیچ می‌گذرد.","en":"The lorry must keep right in to the right edge all the way round.","een":"No. A long lorry cannot do that; its rear cuts the corner."},{"da":"Jeg overhaler lastbilen i rundkørslen.","fa":"در میدان از کامیون سبقت می‌گیرم.","ok":0,"eda":"Nej. I en rundkørsel med én vognbane er der ikke plads til at overhale lastbilen sikkert.","efa":"خیر. در میدان یک‌خطه جای کافی برای سبقت ایمن از کامیون نیست.","en":"I overtake the lorry in the roundabout.","een":"No. In a single-lane roundabout there is no room to overtake the lorry safely."}]},{"id":5194,"img":"newq-art/5194.png","c":"5.2","sda":"Det er efterår, og der ligger våde blade på vejen. Hvordan forholder du dig?","sfa":"پاییز است و برگ‌های خیس روی جاده ریخته است. چه می‌کنید؟","sen":"It is autumn, and there are wet leaves on the road. What do you do?","st":[{"da":"Jeg regner med, at vejen kan være glat.","fa":"انتظار دارم جاده لغزنده باشد.","ok":1,"eda":"Ja. Våde blade kan gøre vejen lige så glat som is.","efa":"بله. برگ‌های خیس می‌توانند جاده را به لغزندگی یخ کنند.","en":"I expect that the road may be slippery.","een":"Yes. Wet leaves can make the road as slippery as ice."},{"da":"Jeg bremser blødt og undgår at dreje brat.","fa":"نرم ترمز می‌کنم و از فرمان دادن تند پرهیز می‌کنم.","ok":1,"eda":"Ja. Bratte manøvrer kan få bilen til at skride.","efa":"بله. حرکات ناگهانی ممکن است خودرو را بلغزاند.","en":"I brake gently and avoid steering sharply.","een":"Yes. Sharp manoeuvres can make the car skid."},{"da":"Blade har ingen betydning for bremselængden.","fa":"برگ‌ها روی مسافت ترمز اثری ندارند.","ok":0,"eda":"Nej. Blade, især våde, nedsætter dækkenes greb.","efa":"خیر. برگ‌ها، به‌ویژه خیس، چسبندگی لاستیک را کم می‌کنند.","en":"Leaves make no difference to the braking distance.","een":"No. Leaves, especially wet ones, reduce the tyres' grip."},{"da":"Jeg sænker farten og holder større afstand.","fa":"سرعتم را کم می‌کنم و فاصله‌ی بیشتری نگه می‌دارم.","ok":1,"eda":"Ja. På glat vej bliver bremselængden længere.","efa":"بله. روی جاده‌ی لغزنده مسافت ترمز بیشتر می‌شود.","en":"I slow down and keep a greater distance.","een":"Yes. On a slippery road the braking distance gets longer."}]},{"id":5195,"img":"newq-art/5195.png","c":"7.8","sda":"Hvordan kan du vurdere, om du holder en passende afstand til bilen foran på landevejen?","sfa":"در جاده‌ی بیرون شهر چطور می‌توانید بسنجید که فاصله‌ی مناسبی با خودروی جلو دارید؟","sen":"How can you judge whether you are keeping a suitable distance to the car in front on a country road?","st":[{"da":"En anden tommelfingerregel er en afstand i meter på det halve af farten, fx 40 m ved 80 km/t.","fa":"قاعده‌ی دیگر فاصله‌ای به متر برابر نصف سرعت است، مثلاً ۴۰ متر در ۸۰ کیلومتر بر ساعت.","ok":1,"eda":"Ja. Begge tommelfingerregler giver omtrent samme afstand.","efa":"بله. هر دو قاعده تقریباً همان فاصله را می‌دهند.","en":"Another rule of thumb is a distance in metres of half the speed, for example 40 m at 80 km/h.","een":"Yes. Both rules of thumb give roughly the same distance."},{"da":"Det er nok, at jeg kan se bilens baglygter.","fa":"کافی است چراغ‌های عقب آن خودرو را ببینم.","ok":0,"eda":"Nej. Afstanden skal være så stor, at der ikke er fare for påkørsel, hvis bilen foran bremser.","efa":"خیر. فاصله باید آن‌قدر باشد که اگر خودروی جلو ترمز کرد، خطر تصادف نباشد.","en":"It is enough that I can see the car's rear lights.","een":"No. The distance must be so great that there is no risk of a collision if the car in front brakes."},{"da":"På våd eller glat vej holder jeg større afstand.","fa":"در جاده‌ی خیس یا لغزنده فاصله‌ی بیشتری نگه می‌دارم.","ok":1,"eda":"Ja. Bremselængden er længere, når vejen er våd eller glat.","efa":"بله. وقتی جاده خیس یا لغزنده است، مسافت ترمز بیشتر است.","en":"On a wet or slippery road I keep a greater distance.","een":"Yes. The braking distance is longer when the road is wet or slippery."},{"da":"Jeg holder mindst 2 sekunders afstand i godt føre.","fa":"در شرایط خوب دست‌کم ۲ ثانیه فاصله نگه می‌دارم.","ok":1,"eda":"Ja. To sekunder er en god tommelfingerregel: når bilen foran passerer et fast punkt, skal du kunne tælle til to, før du selv er der.","efa":"بله. دو ثانیه قاعده‌ی خوبی است: وقتی خودروی جلو از یک نقطه‌ی ثابت رد شد، باید بتوانید تا دو بشمارید تا خودتان به آن برسید.","en":"I keep at least 2 seconds' distance in good conditions.","een":"Yes. Two seconds is a good rule of thumb: when the car ahead passes a fixed point, you should be able to count to two before you get there."}]},{"id":5196,"img":"newq-art/5196.png","c":"7.5","sda":"Du vil vende på en bred vej uden for byen. Hvordan forholder du dig?","sfa":"می‌خواهید در جاده‌ای پهن بیرون از شهر دور بزنید. چه می‌کنید؟","sen":"You want to turn round on a wide road outside town. What do you do?","st":[{"da":"Jeg sikrer mig, at det kan ske uden fare eller ulempe for andre.","fa":"مطمئن می‌شوم که برای دیگران خطر یا مزاحمتی ندارد.","ok":1,"eda":"Ja. Før vending skal du sikre dig, at manøvren kan udføres uden fare eller ulempe for andre.","efa":"بله. پیش از دور زدن باید مطمئن شوید که برای دیگران خطر یا مزاحمتی ندارد.","en":"I make sure that it can be done without danger or inconvenience to others.","een":"Yes. Before turning round you must make sure the manoeuvre can be done without danger or inconvenience to others."},{"da":"Jeg må vende ved bakketoppen, hvis jeg skynder mig.","fa":"اگر عجله کنم، می‌توانم بالای تپه دور بزنم.","ok":0,"eda":"Nej. Ved en bakketop kan du ikke se, om der kommer nogen, så vendingen kan ikke ske uden fare.","efa":"خیر. بالای تپه نمی‌بینید کسی می‌آید یا نه، پس دور زدن بی‌خطر نیست.","en":"I may turn round at the hilltop if I hurry.","een":"No. At a hilltop you cannot see whether anyone is coming, so turning round cannot be done safely."},{"da":"Jeg vender forlæns til venstre.","fa":"رو به جلو و به سمت چپ دور می‌زنم.","ok":1,"eda":"Ja. Vending skal ske forlæns til venstre.","efa":"بله. دور زدن باید رو به جلو و به سمت چپ انجام شود.","en":"I turn round forwards to the left.","een":"Yes. Turning round must be done forwards to the left."},{"da":"Jeg må vende på motorvejen, når der ikke er trafik.","fa":"وقتی ترافیک نیست، می‌توانم در بزرگراه دور بزنم.","ok":0,"eda":"Nej. Vending er altid forbudt på motorvej.","efa":"خیر. دور زدن در بزرگراه همیشه ممنوع است.","en":"I may turn round on the motorway when there is no traffic.","een":"No. Turning round is always forbidden on the motorway."}]},{"id":5197,"img":"newq-art/5197.png","c":"1.2","sda":"Det har frosset i nat, og der er is på bilens ruder. Hvordan forholder du dig, før du kører?","sfa":"دیشب یخبندان بوده و روی شیشه‌های خودرو یخ بسته است. پیش از رانندگی چه می‌کنید؟","sen":"It froze last night, and there is ice on the car's windows. What do you do before you drive?","st":[{"da":"Jeg skraber alle ruderne helt fri.","fa":"همه‌ی شیشه‌ها را کاملاً تمیز می‌کنم.","ok":1,"eda":"Ja. Du skal have frit udsyn til alle sider.","efa":"بله. باید از همه طرف دید آزاد داشته باشید.","en":"I scrape all the windows completely clear.","een":"Yes. You must have a clear view on all sides."},{"da":"Jeg venter med at køre, til ruderne er klare, hvis isen ikke kan skrabes af.","fa":"اگر یخ کنده نشود، صبر می‌کنم تا شیشه‌ها شفاف شوند و بعد راه می‌افتم.","ok":1,"eda":"Ja. Bilen må ikke bruges, før den kan køres uden fare.","efa":"بله. تا وقتی خودرو را نتوان بی‌خطر راند، نباید از آن استفاده کرد.","en":"I wait to drive until the windows are clear if the ice cannot be scraped off.","een":"Yes. The car must not be used until it can be driven without danger."},{"da":"Jeg gør også spejlene og lygterne rene.","fa":"آینه‌ها و چراغ‌ها را هم تمیز می‌کنم.","ok":1,"eda":"Ja. Spejlene skal kunne bruges, og lygterne skal kunne ses.","efa":"بله. آینه‌ها باید قابل استفاده و چراغ‌ها قابل دیدن باشند.","en":"I clean the mirrors and lights too.","een":"Yes. The mirrors must be usable and the lights must be visible."},{"da":"Det er nok at skrabe et lille hul foran føreren.","fa":"کافی است سوراخ کوچکی جلوی راننده باز کنم.","ok":0,"eda":"Nej. Gennem et lille hul kan du ikke se cyklister og biler fra siden.","efa":"خیر. از یک سوراخ کوچک دوچرخه‌سواران و خودروهای کناری را نمی‌بینید.","en":"Scraping a small hole in front of the driver is enough.","een":"No. Through a small hole you cannot see cyclists and cars from the side."}]},{"id":5198,"img":"newq-art/5198.png","c":"1.2","sda":"Bilen er tungt lastet bagi, og nærlyset peger højere end normalt. Hvad gør du?","sfa":"صندوق عقب خودرو پر از بار سنگین است و نور پایین بالاتر از معمول می‌تابد. چه می‌کنید؟","sen":"The car is heavily loaded at the back, and the dipped beam points higher than normal. What do you do?","st":[{"da":"Jeg kører med fjernlys i stedet.","fa":"به‌جایش با نور بالا می‌رانم.","ok":0,"eda":"Nej. Fjernlyset blænder endnu mere.","efa":"خیر. نور بالا حتی بیشتر خیره می‌کند.","en":"I drive with high beam instead.","een":"No. The high beam dazzles even more."},{"da":"Jeg indstiller lygtehøjden, så de modkørende ikke bliver blændet.","fa":"ارتفاع چراغ‌ها را تنظیم می‌کنم تا رانندگان روبه‌رو خیره نشوند.","ok":1,"eda":"Ja. Lygter må ikke bruges, så andre førere kan blændes.","efa":"بله. از چراغ‌ها نباید طوری استفاده کرد که رانندگان دیگر خیره شوند.","en":"I adjust the headlight height so that oncoming drivers are not dazzled.","een":"Yes. Lights must not be used in a way that can dazzle other drivers."},{"da":"Jeg dækker lygterne delvis med tape.","fa":"چراغ‌ها را تا حدی با چسب می‌پوشانم.","ok":0,"eda":"Nej. Det ændrer lyset og gør bilen dårligere at se; brug lygtehøjdeindstillingen.","efa":"خیر. این کار نور را تغییر می‌دهد و دیدن خودرو را سخت‌تر می‌کند؛ از تنظیم ارتفاع چراغ استفاده کنید.","en":"I partly cover the lights with tape.","een":"No. That changes the light and makes the car harder to see; use the headlight levelling control."},{"da":"Det har ingen betydning, når jeg kører med nærlys.","fa":"وقتی با نور پایین می‌رانم، اهمیتی ندارد.","ok":0,"eda":"Nej. Nærlys, der peger for højt, kan blænde lige så meget som fjernlys.","efa":"خیر. نور پایینی که زیادی بالا بتابد، می‌تواند به اندازه‌ی نور بالا خیره کند.","en":"It makes no difference when I am driving with dipped beam.","een":"No. Dipped beam pointing too high can dazzle as much as high beam."}]},{"id":5199,"img":"newq-art/5199.png","c":"7.7","sda":"Vejen er smal, og en bus kommer imod dig. Rabatten i din side er blød. Hvordan forholder du dig?","sfa":"جاده باریک است و اتوبوسی از روبه‌رو می‌آید. شانه‌ی خاکی سمت شما نرم است. چه می‌کنید؟","sen":"The road is narrow, and a bus is coming towards you. The verge on your side is soft. What do you do?","st":[{"da":"Bussen skal bakke, fordi den er størst.","fa":"اتوبوس باید دنده‌عقب برود، چون بزرگ‌تر است.","ok":0,"eda":"Nej. Der er ingen sådan regel; find sammen den sikreste løsning.","efa":"خیر. چنین قاعده‌ای نیست؛ با هم ایمن‌ترین راه را پیدا کنید.","en":"The bus must reverse because it is the biggest.","een":"No. There is no such rule; find the safest solution together."},{"da":"Jeg standser om nødvendigt ved den faste plads og lader bussen passere.","fa":"در صورت لزوم در جای سفت می‌ایستم و می‌گذارم اتوبوس رد شود.","ok":1,"eda":"Ja. Det er sikrere at vente på et fast sted end at køre ud i en blød rabat.","efa":"بله. صبر کردن در جای سفت ایمن‌تر از رفتن به شانه‌ی نرم است.","en":"If necessary I stop at the firm place and let the bus pass.","een":"Yes. It is safer to wait in a firm place than to drive onto a soft verge."},{"da":"Jeg kører ud i den bløde rabat i fuld fart for at give plads.","fa":"با سرعت کامل به شانه‌ی نرم می‌روم تا جا باز کنم.","ok":0,"eda":"Nej. I en blød rabat kan bilen skride ud eller køre i grøften.","efa":"خیر. در شانه‌ی نرم ممکن است خودرو بلغزد یا به گودال برود.","en":"I drive onto the soft verge at full speed to make room.","een":"No. On a soft verge the car may skid or end up in the ditch."},{"da":"Jeg sænker farten og holder så langt til højre, som det kan ske sikkert.","fa":"سرعتم را کم می‌کنم و تا جایی که ایمن باشد سمت راست می‌مانم.","ok":1,"eda":"Ja. Ved møde på smal vej skal hastigheden være passende lav, og du skal holde til højre.","efa":"بله. هنگام برخورد در جاده‌ی باریک سرعت باید به اندازه‌ی کافی کم باشد و باید سمت راست بمانید.","en":"I slow down and keep as far to the right as it can be done safely.","een":"Yes. When meeting on a narrow road your speed must be suitably low, and you must keep right."}]},{"id":5200,"img":"newq-art/5200.png","c":"7.7","sda":"Før en smal bro står denne tavle. Hvad gælder?","sfa":"پیش از یک پل باریک این تابلو هست. چه قاعده‌ای برقرار است؟","sen":"This sign stands before a narrow bridge. What applies?","st":[{"da":"Jeg kører alligevel forsigtigt og er klar til at standse, hvis en modkørende allerede er på broen.","fa":"با این حال با احتیاط می‌رانم و اگر وسیله‌ای از روبه‌رو روی پل باشد، آماده‌ی ایستادنم.","ok":1,"eda":"Ja. En, der allerede er på broen, kan ikke vige.","efa":"بله. کسی که روی پل است، نمی‌تواند کنار برود.","en":"I still drive carefully and am ready to stop if an oncoming vehicle is already on the bridge.","een":"Yes. Someone already on the bridge cannot make way."},{"da":"Jeg skal holde tilbage for de modkørende.","fa":"باید به ترافیک روبه‌رو راه بدهم.","ok":0,"eda":"Nej. Det er tavlen med rød kant og en rød pil op (B 18), der betyder det.","efa":"خیر. تابلوی با حاشیه‌ی قرمز و فلش قرمز رو به بالا (B 18) این معنا را دارد.","en":"I must give way to oncoming traffic.","een":"No. It is the sign with a red border and a red arrow up (B 18) that means that."},{"da":"De modkørende skal holde tilbage for mig.","fa":"ترافیک روبه‌رو باید به من راه بدهد.","ok":1,"eda":"Ja. Tavlen (B 19) betyder, at den modkørende færdsel skal holde tilbage.","efa":"بله. این تابلو (B 19) یعنی ترافیک روبه‌رو باید راه بدهد.","en":"Oncoming traffic must give way to me.","een":"Yes. The sign (B 19) means that oncoming traffic must give way."},{"da":"Tavlen betyder, at broen er ensrettet.","fa":"این تابلو یعنی پل یک‌طرفه است.","ok":0,"eda":"Nej. Der er trafik i begge retninger; tavlen siger, hvem der skal vente.","efa":"خیر. ترافیک در هر دو جهت است؛ تابلو می‌گوید چه کسی باید صبر کند.","en":"The sign means that the bridge is one-way.","een":"No. There is traffic in both directions; the sign says who must wait."}]},{"id":5201,"img":"newq-art/5201.png","c":"7.18","sda":"Du vil standse og lade en passager stige ud. Der er en ledig plads ved kantstenen lige efter fodgængerfeltet. Hvad gælder?","sfa":"می‌خواهید بایستید تا مسافری پیاده شود. درست بعد از گذرگاه عابر پیاده، کنار جدول جای خالی هست. چه قاعده‌ای برقرار است؟","sen":"You want to stop and let a passenger out. There is a free space at the kerb just after the pedestrian crossing. What applies?","st":[{"da":"Jeg må godt standse lige efter fodgængerfeltet.","fa":"می‌توانم درست بعد از گذرگاه عابر پیاده بایستم.","ok":1,"eda":"Ja. Forbuddet gælder på fodgængerfeltet og på de 5 m før det, ikke efter det.","efa":"بله. ممنوعیت برای خود گذرگاه و ۵ متر پیش از آن است، نه بعد از آن.","en":"I may stop just after the pedestrian crossing.","een":"Yes. The ban covers the crossing and the 5 m before it, not the space after it."},{"da":"Jeg må standse på fodgængerfeltet, når passageren hurtigt kan stige ud.","fa":"اگر مسافر سریع پیاده شود، می‌توانم روی گذرگاه عابر پیاده بایستم.","ok":0,"eda":"Nej. Det er altid forbudt at standse på et fodgængerfelt.","efa":"خیر. ایستادن روی گذرگاه عابر پیاده همیشه ممنوع است.","en":"I may stop on the pedestrian crossing when the passenger can get out quickly.","een":"No. Stopping on a pedestrian crossing is always forbidden."},{"da":"Efter et fodgængerfelt må jeg først standse 10 m efter feltet.","fa":"بعد از گذرگاه عابر پیاده فقط از ۱۰ متر بعد از آن می‌توانم بایستم.","ok":0,"eda":"Nej. Der er ingen sådan regel; reglen om 10 m gælder ved vejkryds.","efa":"خیر. چنین قاعده‌ای نیست؛ قاعده‌ی ۱۰ متر برای تقاطع است.","en":"After a pedestrian crossing I may only stop 10 m beyond it.","een":"No. There is no such rule; the 10 m rule applies at junctions."},{"da":"Jeg må standse 3 m før fodgængerfeltet.","fa":"می‌توانم ۳ متر پیش از گذرگاه عابر پیاده بایستم.","ok":0,"eda":"Nej. Standsning er forbudt nærmere end 5 m før fodgængerfeltet.","efa":"خیر. ایستادن در فاصله‌ی کمتر از ۵ متر پیش از گذرگاه ممنوع است.","en":"I may stop 3 m before the pedestrian crossing.","een":"No. Stopping is forbidden less than 5 m before the crossing."}]},{"id":5202,"img":"newq-art/5202.png","c":"7.18","sda":"En cykelsti fra en park munder ud i vejen til højre. Du vil standse ved kantstenen lige der, hvor stien kommer ud. Hvad gælder?","sfa":"یک مسیر دوچرخه از پارک، سمت راست به جاده می‌رسد. می‌خواهید کنار جدول درست جلوی دهانه‌ی مسیر بایستید. چه قاعده‌ای برقرار است؟","sen":"A cycle path from a park comes out onto the road on the right. You want to stop at the kerb right where the path comes out. What applies?","st":[{"da":"En bil foran stien kan skjule cyklisterne og spærre for dem.","fa":"خودرویی جلوی مسیر ممکن است دوچرخه‌سوارها را پنهان کند و راهشان را ببندد.","ok":1,"eda":"Ja. Derfor er standsning forbudt der; cyklister og bilister skal kunne se hinanden.","efa":"بله. به همین دلیل ایستادن آنجا ممنوع است؛ دوچرخه‌سوار و راننده باید یکدیگر را ببینند.","en":"A car in front of the path can hide the cyclists and block their way.","een":"Yes. That is why stopping is forbidden there; cyclists and drivers must be able to see each other."},{"da":"Jeg må standse lige ud for stien, når jeg kun holder kort.","fa":"اگر کوتاه بایستم، می‌توانم درست جلوی دهانه‌ی مسیر بایستم.","ok":0,"eda":"Nej. Det er forbudt at standse ud for udkørslen fra en cykelsti, også kort.","efa":"خیر. ایستادن جلوی خروجی مسیر دوچرخه ممنوع است، حتی کوتاه.","en":"I may stop right where the path comes out if I only stop briefly.","een":"No. Stopping where a cycle path comes out is forbidden, even briefly."},{"da":"Jeg skal holde mindst 5 m fra stiens udmunding til begge sider.","fa":"باید دست‌کم ۵ متر از دهانه‌ی مسیر، در هر دو طرف، فاصله داشته باشم.","ok":1,"eda":"Ja. Ved en cykelsti, der er tværgående i forhold til kørebanen, er standsning forbudt 5 m på hver side af udkørslen.","efa":"بله. جایی که مسیر دوچرخه از کنار به سواره‌رو می‌رسد، ایستادن در ۵ متریِ هر دو طرف خروجی ممنوع است.","en":"I must stop at least 5 m from the end of the path on either side.","een":"Yes. Where a cycle path meets the carriageway from the side, stopping is forbidden 5 m on each side of its exit."},{"da":"Forbuddet gælder kun, hvis der står en tavle.","fa":"این ممنوعیت فقط وقتی هست که تابلو باشد.","ok":0,"eda":"Nej. Forbuddet står i færdselsloven og gælder uden tavle.","efa":"خیر. این ممنوعیت در قانون راهنمایی و رانندگی آمده و بدون تابلو هم برقرار است.","en":"The ban only applies if there is a sign.","een":"No. The ban is in the Road Traffic Act and applies without a sign."}]},{"id":5203,"img":"newq-art/5203.png","c":"7.18","sda":"Du vil parkere på en befærdet vej med trafik i begge retninger. Den eneste ledige plads er i venstre side af vejen. Hvad gælder?","sfa":"می‌خواهید در جاده‌ای شلوغ با ترافیک دوطرفه پارک کنید. تنها جای خالی، سمت چپ جاده است. چه قاعده‌ای برقرار است؟","sen":"You want to park on a busy road with traffic in both directions. The only free space is on the left-hand side of the road. What applies?","st":[{"da":"Jeg skal finde en plads i højre side af vejen.","fa":"باید جایی سمت راست جاده پیدا کنم.","ok":1,"eda":"Ja. Standsning og parkering må kun ske i højre side i kørselsretningen, med få undtagelser.","efa":"بله. توقف و پارک فقط سمت راستِ جهت حرکت مجاز است، با چند استثنا.","en":"I must find a space on the right-hand side of the road.","een":"Yes. Stopping and parking may only take place on the right in the direction of travel, with few exceptions."},{"da":"Jeg må krydse over og parkere i venstre side.","fa":"می‌توانم به آن طرف بروم و سمت چپ پارک کنم.","ok":0,"eda":"Nej. På en befærdet vej med trafik i begge retninger skal standsning og parkering ske i højre side.","efa":"خیر. در جاده‌ی شلوغ دوطرفه، توقف و پارک باید سمت راست باشد.","en":"I may cross over and park on the left-hand side.","een":"No. On a busy road with traffic in both directions, stopping and parking must be on the right."},{"da":"Var vejen ensrettet, måtte jeg gerne parkere i venstre side.","fa":"اگر جاده یک‌طرفه بود، می‌توانستم سمت چپ پارک کنم.","ok":1,"eda":"Ja. På ensrettet vej og på mindre befærdet vej må der standses og parkeres i venstre side.","efa":"بله. در جاده‌ی یک‌طرفه و جاده‌ی کم‌تردد، توقف و پارک سمت چپ مجاز است.","en":"If the road were one-way, I would be allowed to park on the left.","een":"Yes. On a one-way road and on a road with little traffic, you may stop and park on the left."}]},{"id":5204,"img":"newq-art/5204.png","c":"7.18","sda":"Den ledige plads er afmærket med denne tavle. Du har ikke et parkeringskort for personer med handicap. Hvad gælder?","sfa":"جای خالی با این تابلو مشخص شده است. شما کارت پارک افراد دارای معلولیت ندارید. چه قاعده‌ای برقرار است؟","sen":"The free space is marked with this sign. You do not have a parking permit for people with disabilities. What applies?","st":[{"da":"Jeg må bruge pladsen, når der er flere ledige handicappladser ved siden af.","fa":"اگر کنارش چند جای معلولین دیگر هم خالی باشد، می‌توانم از آن استفاده کنم.","ok":0,"eda":"Nej. Det ændrer ikke på, at pladserne er forbeholdt dem med tilladelse.","efa":"خیر. این چیزی را عوض نمی‌کند؛ این جاها برای دارندگان مجوز است.","en":"I may use the space when there are more free disabled spaces next to it.","een":"No. That does not change that the spaces are reserved for permit holders."},{"da":"Jeg må heller ikke standse der for at sætte en passager af.","fa":"برای پیاده کردن مسافر هم نباید آنجا بایستم.","ok":1,"eda":"Ja. Pladsen må kun benyttes til standsning og parkering af køretøjer med tilladelse.","efa":"بله. این جا فقط برای توقف و پارکِ خودروهای دارای مجوز است.","en":"I may not stop there to let a passenger out either.","een":"Yes. The space may only be used for stopping and parking by vehicles with a permit."},{"da":"Jeg må parkere der, hvis jeg kun er væk i få minutter.","fa":"اگر فقط چند دقیقه دور باشم، می‌توانم آنجا پارک کنم.","ok":0,"eda":"Nej. Pladsen er forbeholdt dem med tilladelse, også til kortvarig parkering.","efa":"خیر. این جا برای دارندگان مجوز است، حتی برای پارک کوتاه.","en":"I may park there if I am only away for a few minutes.","een":"No. The space is reserved for permit holders, also for short parking."},{"da":"Pladsen er forbeholdt køretøjer med et parkeringskort for personer med handicap.","fa":"این جا مخصوص خودروهایی است که کارت پارک افراد دارای معلولیت دارند.","ok":1,"eda":"Ja. Med undertavlen med kørestolen må pladsen kun bruges af køretøjer med en særlig tilladelse.","efa":"بله. با تابلوی زیرینِ ویلچر، فقط خودروهای دارای مجوز ویژه می‌توانند از این جا استفاده کنند.","en":"The space is reserved for vehicles with a parking permit for people with disabilities.","een":"Yes. With the plate showing a wheelchair, the space may only be used by vehicles with a special permit."}]},{"id":5205,"img":"newq-art/5205.png","c":"7.18","sda":"Du kører ind i et område forbi denne tavle. Hvad gælder?","sfa":"از کنار این تابلو وارد یک محدوده می‌شوید. چه قاعده‌ای برقرار است؟","sen":"You drive into an area past this sign. What applies?","st":[{"da":"Forbuddet gælder kun til næste vejkryds.","fa":"این ممنوعیت فقط تا تقاطع بعدی است.","ok":0,"eda":"Nej. Inden for zonen gælder forbuddet også efter krydsene.","efa":"خیر. داخل زون، ممنوعیت بعد از تقاطع‌ها هم برقرار است.","en":"The ban only applies up to the next junction.","een":"No. Inside the zone the ban also applies after the junctions."},{"da":"Jeg må standse et øjeblik på kørebanen for at sætte en passager af.","fa":"می‌توانم لحظه‌ای روی سواره‌رو بایستم تا مسافری پیاده شود.","ok":0,"eda":"Nej. Et standsningsforbud gælder også en kort standsning for af- og påstigning.","efa":"خیر. ممنوعیت توقف، توقف کوتاه برای پیاده و سوار شدن را هم شامل می‌شود.","en":"I may stop briefly on the carriageway to let a passenger out.","een":"No. A no-stopping ban also covers a short stop to let people out or in."},{"da":"Forbuddet gælder kun for lastbiler i området.","fa":"این ممنوعیت فقط برای کامیون‌های داخل محدوده است.","ok":0,"eda":"Nej. Tavlen viser et almindeligt standsningsforbud, der gælder alle køretøjer.","efa":"خیر. تابلو یک ممنوعیت توقف عادی را نشان می‌دهد که برای همه‌ی وسایل نقلیه است.","en":"The ban only applies to lorries in the area.","een":"No. The sign shows an ordinary no-stopping ban, which applies to all vehicles."},{"da":"Standsning er forbudt i hele området, til jeg kører forbi en tavle for zonens ophør.","fa":"توقف در کل محدوده ممنوع است تا وقتی از کنار تابلوی پایان زون رد شوم.","ok":1,"eda":"Ja. En zonetavle gælder i hele området, indtil den ophæves af tavlen for zonens ophør.","efa":"بله. تابلوی زون در کل محدوده برقرار است تا تابلوی پایان زون آن را لغو کند.","en":"Stopping is forbidden throughout the area until I pass a sign for the end of the zone.","een":"Yes. A zone sign applies throughout the area until it is lifted by the end-of-zone sign."}]},{"id":5206,"img":"newq-art/5206.png","c":"7.18","sda":"Gaden i byen er smal. Du vil parkere med to hjul oppe på fortovet, så der bliver mere plads på kørebanen. Hvad gælder?","sfa":"خیابانِ داخل شهر باریک است. می‌خواهید با دو چرخ روی پیاده‌رو پارک کنید تا روی سواره‌رو جای بیشتری بماند. چه قاعده‌ای برقرار است؟","sen":"The street in town is narrow. You want to park with two wheels up on the pavement so that there is more room on the carriageway. What applies?","st":[{"da":"Det er tilladt, hvis der stadig er plads til en barnevogn på fortovet.","fa":"اگر هنوز روی پیاده‌رو جا برای کالسکه باشد، مجاز است.","ok":0,"eda":"Nej. Reglen har ingen sådan undtagelse.","efa":"خیر. این قاعده چنین استثنایی ندارد.","en":"It is allowed if there is still room for a pram on the pavement.","een":"No. The rule has no such exception."},{"da":"Uden for tættere bebygget område må en bil med en tilladt totalvægt på højst 3.500 kg holde med en del af bilen på fortovet.","fa":"بیرون از محدوده‌ی شهری، خودرویی با وزن کل مجاز حداکثر ۳٬۵۰۰ کیلوگرم می‌تواند با بخشی از خود روی پیاده‌رو بایستد.","ok":1,"eda":"Ja. Det er en undtagelse, der kun gælder uden for tættere bebygget område.","efa":"بله. این استثنایی است که فقط بیرون از محدوده‌ی شهری برقرار است.","en":"Outside built-up areas a car with a permitted total weight of at most 3,500 kg may stand with part of it on the pavement.","een":"Yes. That is an exception which only applies outside built-up areas."},{"da":"Jeg må ikke parkere med en del af bilen på fortovet i byen.","fa":"داخل شهر نباید با بخشی از خودرو روی پیاده‌رو پارک کنم.","ok":1,"eda":"Ja. Standsning og parkering må ikke ske på fortov.","efa":"بله. توقف و پارک روی پیاده‌رو ممنوع است.","en":"I may not park with part of the car on the pavement in town.","een":"Yes. Stopping and parking must not take place on the pavement."},{"da":"Det er tilladt, fordi det giver mere plads til trafikken.","fa":"مجاز است، چون جای بیشتری برای ترافیک باز می‌کند.","ok":0,"eda":"Nej. I byen må man ikke standse eller parkere på fortovet, heller ikke med en del af bilen.","efa":"خیر. داخل شهر توقف و پارک روی پیاده‌رو ممنوع است، حتی با بخشی از خودرو.","en":"It is allowed because it gives more room to the traffic.","een":"No. In town you may not stop or park on the pavement, not even with part of the car."}]},{"id":5207,"img":"newq-art/5207.png","c":"7.9","sda":"Midt på vejen er der en dobbelt linje: nærmest dig er linjen brudt, og på de modkørendes side er den ubrudt. Foran dig kører en langsom traktor. Hvad gælder?","sfa":"وسط جاده خط دوتایی است: خطِ نزدیک به شما بریده‌بریده و خطِ سمت خودروهای روبه‌رو ممتد است. جلوی شما یک تراکتور آهسته می‌رود. چه قاعده‌ای برقرار است؟","sen":"There is a double line in the middle of the road: the line nearest you is broken, and on the oncoming side it is unbroken. A slow tractor is driving in front of you. What applies?","st":[{"da":"Jeg må ikke overhale, fordi der er en ubrudt linje midt på vejen.","fa":"نمی‌توانم سبقت بگیرم، چون وسط جاده خط ممتد هست.","ok":0,"eda":"Nej. Den ubrudte linje er på de modkørendes side; for dig gælder den brudte.","efa":"خیر. خط ممتد سمت خودروهای روبه‌روست؛ برای شما خط بریده‌بریده معتبر است.","en":"I may not overtake because there is an unbroken line in the middle of the road.","een":"No. The unbroken line is on the oncoming side; for you the broken one applies."},{"da":"Før jeg trækker ud, sikrer jeg mig, at der er plads til at komme ind igen foran traktoren.","fa":"پیش از بیرون رفتن مطمئن می‌شوم که جلوی تراکتور جا برای برگشتن هست.","ok":1,"eda":"Ja. Der skal være plads til at vende tilbage til højre side uden fare.","efa":"بله. باید جا برای برگشتن بی‌خطر به سمت راست باشد.","en":"Before I pull out, I make sure there is room to get back in front of the tractor.","een":"Yes. There must be room to return to the right without danger."},{"da":"De modkørende må også køre over linjerne for at overhale.","fa":"خودروهای روبه‌رو هم می‌توانند برای سبقت از خطوط رد شوند.","ok":0,"eda":"Nej. For dem er den ubrudte linje nærmest, så de må ikke køre over.","efa":"خیر. برای آن‌ها خط ممتد نزدیک‌تر است، پس نباید از آن رد شوند.","en":"Oncoming drivers may also cross the lines to overtake.","een":"No. For them the unbroken line is nearest, so they may not cross."},{"da":"Jeg må overhale traktoren, hvis det kan ske uden fare.","fa":"اگر بی‌خطر باشد، می‌توانم از تراکتور سبقت بگیرم.","ok":1,"eda":"Ja. Ved en dobbelt linje gælder den linje, der er nærmest dig; her den brudte.","efa":"بله. در خط دوتایی، خطِ نزدیک‌تر به شما معتبر است؛ این‌جا خط بریده‌بریده.","en":"I may overtake the tractor if it can be done without danger.","een":"Yes. With a double line, the line nearest you applies; here the broken one."}]},{"id":5208,"img":"newq-art/5208.png","c":"7.9","sda":"Midt på vejen er der en dobbelt linje: nærmest dig er linjen ubrudt, og på de modkørendes side er den brudt. Hvad gælder?","sfa":"وسط جاده خط دوتایی است: خطِ نزدیک به شما ممتد و خطِ سمت خودروهای روبه‌رو بریده‌بریده است. چه قاعده‌ای برقرار است؟","sen":"There is a double line in the middle of the road: the line nearest you is unbroken, and on the oncoming side it is broken. What applies?","st":[{"da":"De modkørende må gerne køre over linjerne for at overhale, hvis det kan ske uden fare.","fa":"خودروهای روبه‌رو اگر بی‌خطر باشد، می‌توانند برای سبقت از خطوط رد شوند.","ok":1,"eda":"Ja. For dem er den brudte linje nærmest.","efa":"بله. برای آن‌ها خط بریده‌بریده نزدیک‌تر است.","en":"Oncoming drivers may cross the lines to overtake if it can be done without danger.","een":"Yes. For them the broken line is nearest."},{"da":"Jeg må køre over linjerne, hvis bilen foran kører under 50 km/t.","fa":"اگر خودروی جلو کمتر از ۵۰ کیلومتر بر ساعت برود، می‌توانم از خطوط رد شوم.","ok":0,"eda":"Nej. Den ubrudte linje må ikke overskrides for at overhale, uanset hvor langsomt bilen foran kører.","efa":"خیر. برای سبقت نباید از خط ممتد رد شد، خودروی جلو هر قدر هم آهسته برود.","en":"I may cross the lines if the car in front is going under 50 km/h.","een":"No. The unbroken line must not be crossed to overtake, however slowly the car in front is going."},{"da":"Jeg må ikke køre over linjerne for at overhale.","fa":"برای سبقت نباید از خطوط رد شوم.","ok":1,"eda":"Ja. Den ubrudte linje er nærmest dig, og den må du ikke overskride.","efa":"بله. خط ممتد نزدیک‌تر به شماست و نباید از آن رد شوید.","en":"I may not cross the lines to overtake.","een":"Yes. The unbroken line is nearest you, and you must not cross it."}]},{"id":5209,"img":"newq-art/5209.png","c":"7.9","sda":"Du er ved at overhale en lastbil på motorvejen. Hvornår kører du tilbage i højre vognbane?","sfa":"در بزرگراه در حال سبقت از یک کامیون هستید. کی به خط راست برمی‌گردید؟","sen":"You are overtaking a lorry on the motorway. When do you move back into the right-hand lane?","st":[{"da":"Først når der er god afstand til lastbilen, fx når jeg kan se den i det indvendige bakspejl.","fa":"فقط وقتی فاصله‌ی خوبی با کامیون دارم، مثلاً وقتی آن را در آینه‌ی داخلی می‌بینم.","ok":1,"eda":"Ja. En tung lastbil har lang bremselængde og skal have plads foran sig.","efa":"بله. کامیون سنگین مسافت ترمز طولانی دارد و جلویش جا لازم دارد.","en":"Only when there is a good distance to the lorry, for example when I can see it in the interior mirror.","een":"Yes. A heavy lorry has a long braking distance and needs room in front of it."},{"da":"Jeg giver tegn, før jeg skifter tilbage.","fa":"پیش از برگشتن راهنما می‌زنم.","ok":1,"eda":"Ja. På motorvej skal du give tegn før vognbaneskift.","efa":"بله. در بزرگراه باید پیش از تغییر خط راهنما بزنید.","en":"I signal before I move back.","een":"Yes. On the motorway you must signal before changing lanes."},{"da":"Når jeg kan gøre det uden fare eller ulempe for lastbilen.","fa":"وقتی بتوانم بدون خطر یا مزاحمت برای کامیون برگردم.","ok":1,"eda":"Ja. Efter overhalingen skal du tilbage til højre, så snart det kan ske uden fare eller ulempe for den overhalede.","efa":"بله. بعد از سبقت باید به محض این‌که بدون خطر یا مزاحمت برای وسیله‌ی سبقت‌گرفته ممکن شد، به راست برگردید.","en":"When I can do it without danger or inconvenience to the lorry.","een":"Yes. After overtaking you must return to the right as soon as it can be done without danger or inconvenience to the one overtaken."},{"da":"Lige så snart min bil er forbi lastbilens front.","fa":"به محض این‌که خودرویم از جلوی کامیون رد شد.","ok":0,"eda":"Nej. Så skærer du ind tæt foran lastbilen, og den kan blive nødt til at bremse.","efa":"خیر. در این صورت درست جلوی کامیون می‌پیچید و ممکن است مجبور به ترمز شود.","en":"As soon as my car is past the front of the lorry.","een":"No. Then you cut in close in front of the lorry, and it may have to brake."}]},{"id":5210,"img":"newq-art/5210.png","c":"7.9","sda":"Du kører bil med trailer og vil overhale en langsom traktor på landevejen. Hvad gælder?","sfa":"با خودرو و تریلر می‌رانید و می‌خواهید در جاده‌ی بیرون شهر از یک تراکتور آهسته سبقت بگیرید. چه قاعده‌ای برقرار است؟","sen":"You are driving a car with a trailer and want to overtake a slow tractor on a country road. What applies?","st":[{"da":"Jeg må højst køre 80 km/t, også mens jeg overhaler.","fa":"حداکثر ۸۰ کیلومتر بر ساعت می‌توانم برانم، حتی هنگام سبقت.","ok":1,"eda":"Ja. Bil med påhængskøretøj må højst køre 80 km/t (på motorvej 100 km/t, hvis vogntoget er godkendt til det).","efa":"بله. خودرو با تریلر حداکثر ۸۰ کیلومتر بر ساعت می‌تواند برود (در بزرگراه ۱۰۰، اگر مجوزش را داشته باشد).","en":"I may drive at most 80 km/h, also while I am overtaking.","een":"Yes. A car with a trailer may drive at most 80 km/h (on the motorway 100 km/h if the combination is approved for it)."},{"da":"Overhalingen tager længere tid og kræver mere plads end uden trailer.","fa":"سبقت بیشتر طول می‌کشد و جای بیشتری از حالت بدون تریلر لازم دارد.","ok":1,"eda":"Ja. Vogntoget er længere og accelererer langsommere.","efa":"بله. خودرو با تریلر بلندتر است و آهسته‌تر شتاب می‌گیرد.","en":"The overtaking takes longer and needs more room than without a trailer.","een":"Yes. The combination is longer and accelerates more slowly."},{"da":"Jeg kan køre ind igen, så snart bilen er forbi traktoren.","fa":"به محض این‌که خودرو از تراکتور رد شد، می‌توانم برگردم.","ok":0,"eda":"Nej. Traileren skal også være godt forbi, før du kører ind.","efa":"خیر. تریلر هم باید کاملاً رد شده باشد تا برگردید.","en":"I can pull back in as soon as the car is past the tractor.","een":"No. The trailer must also be well past before you pull in."},{"da":"Jeg må køre op til 100 km/t, så overhalingen bliver kortere.","fa":"می‌توانم تا ۱۰۰ کیلومتر بر ساعت بروم تا سبقت کوتاه‌تر شود.","ok":0,"eda":"Nej. Grænsen på 80 km/t gælder også under en overhaling.","efa":"خیر. حد ۸۰ کیلومتر بر ساعت هنگام سبقت هم برقرار است.","en":"I may drive up to 100 km/h so that the overtaking is shorter.","een":"No. The 80 km/h limit also applies while overtaking."}]},{"id":5211,"img":"newq-art/5211.png","c":"7.9","sda":"Det er mørkt, og du vil overhale en langsom bil på landevejen. Langt fremme ser du lygterne fra en modkørende bil. Hvad gælder?","sfa":"هوا تاریک است و می‌خواهید در جاده‌ی بیرون شهر از خودرویی آهسته سبقت بگیرید. دورتر چراغ‌های یک خودروی روبه‌رو را می‌بینید. چه قاعده‌ای برقرار است؟","sen":"It is dark, and you want to overtake a slow car on a country road. Far ahead you see the lights of an oncoming car. What applies?","st":[{"da":"Jeg kan altid nå det, når lygterne er langt væk.","fa":"وقتی چراغ‌ها دورند، همیشه وقت دارم.","ok":0,"eda":"Nej. Lygterne kan være tættere på, end de ser ud, og bilen kan køre hurtigt.","efa":"خیر. چراغ‌ها ممکن است نزدیک‌تر از آن باشند که به نظر می‌رسند و خودرو تند برود.","en":"I can always make it when the lights are far away.","een":"No. The lights may be closer than they look, and the car may be going fast."},{"da":"Er jeg i tvivl, venter jeg med at overhale.","fa":"اگر شک دارم، صبر می‌کنم و سبقت نمی‌گیرم.","ok":1,"eda":"Ja. Du må kun overhale, når du er sikker på, at det kan ske uden fare.","efa":"بله. فقط وقتی می‌توانید سبقت بگیرید که مطمئن باشید بی‌خطر است.","en":"If I am in doubt, I wait before overtaking.","een":"Yes. You may only overtake when you are sure it can be done without danger."},{"da":"I mørke er det sværere at bedømme, hvor langt væk den modkørende er, og hvor hurtigt den kører.","fa":"در تاریکی سخت‌تر است فاصله و سرعت خودروی روبه‌رو را تخمین زد.","ok":1,"eda":"Ja. Du ser kun lygterne, ikke bilen og vejen omkring den.","efa":"بله. فقط چراغ‌ها را می‌بینید، نه خودرو و جاده‌ی اطرافش را.","en":"In the dark it is harder to judge how far away the oncoming car is and how fast it is going.","een":"Yes. You only see the lights, not the car and the road around it."}]},{"id":5212,"img":"newq-art/5212.png","c":"6.1","sda":"Du kører forbi denne tavle med undertavlen »Blød rabat«. Hvad betyder den?","sfa":"از کنار این تابلو با تابلوی زیرینِ «Blød rabat» (شانه‌ی نرم) رد می‌شوید. معنی‌اش چیست؟","sen":"You pass this sign with the plate “Blød rabat” (soft verge). What does it mean?","st":[{"da":"Rabatten langs vejen er blød, så hjulene kan synke ned, hvis jeg kører ud på den.","fa":"شانه‌ی کنار جاده نرم است و اگر رویش بروم، چرخ‌ها ممکن است فرو بروند.","ok":1,"eda":"Ja. Tavlen advarer om farlig rabat; undertavlen angiver årsagen.","efa":"بله. تابلو درباره‌ی شانه‌ی خطرناک هشدار می‌دهد و تابلوی زیرین دلیلش را می‌گوید.","en":"The verge beside the road is soft, so the wheels may sink if I drive onto it.","een":"Yes. The sign warns of a dangerous verge; the plate gives the cause."},{"da":"Ved møde med en bred lastbil kører jeg helt ud på rabatten.","fa":"هنگام روبه‌رو شدن با کامیونی پهن، کاملاً روی شانه‌ی جاده می‌روم.","ok":0,"eda":"Nej. En blød rabat kan få bilen til at skride ud eller vælte; sæt hellere farten ned og stands om nødvendigt.","efa":"خیر. شانه‌ی نرم ممکن است خودرو را بلغزاند یا واژگون کند؛ بهتر است سرعت را کم کنید و در صورت لزوم بایستید.","en":"When meeting a wide lorry, I drive right out onto the verge.","een":"No. A soft verge can make the car slide off or tip over; slow down instead and stop if necessary."},{"da":"Vejen bliver smallere længere fremme.","fa":"جاده کمی جلوتر باریک می‌شود.","ok":0,"eda":"Nej. Det angives med tavlen for indsnævret vej.","efa":"خیر. این را تابلوی باریک شدن جاده نشان می‌دهد.","en":"The road narrows further ahead.","een":"No. That is shown by the sign for a road narrowing."},{"da":"Der er vejarbejde i rabatten.","fa":"روی شانه‌ی جاده کار راه‌سازی در جریان است.","ok":0,"eda":"Nej. Vejarbejde har sin egen advarselstavle.","efa":"خیر. کار راه‌سازی تابلوی هشدار خودش را دارد.","en":"There are road works on the verge.","een":"No. Road works have their own warning sign."}]},{"id":5213,"img":"newq-art/5213.png","c":"6.1","sda":"Du kører forbi denne tavle uden for byen. Undertavlen viser 40. Det regner kraftigt. Hvad gælder?","sfa":"بیرون از شهر از کنار این تابلو رد می‌شوید. تابلوی زیرین عدد ۴۰ را نشان می‌دهد. باران شدیدی می‌بارد. چه قاعده‌ای برقرار است؟","sen":"You pass this sign outside a built-up area. The plate shows 40. It is raining heavily. What applies?","st":[{"da":"Jeg skal køre mindst 40 km/t i svinget.","fa":"باید پیچ را دست‌کم با ۴۰ کیلومتر بر ساعت بروم.","ok":0,"eda":"Nej. Undertavlen angiver ikke en mindste hastighed.","efa":"خیر. تابلوی زیرین حداقل سرعت را نشان نمی‌دهد.","en":"I must drive at least 40 km/h in the bend.","een":"No. The plate does not give a minimum speed."},{"da":"Tallet er en hastighedsgrænse, så jeg må køre 40 km/t i svinget uanset vejret.","fa":"این عدد حد سرعت است، پس در هر هوایی می‌توانم پیچ را با ۴۰ کیلومتر بر ساعت بروم.","ok":0,"eda":"Nej. Tallet er en vejledning for normale forhold; farten skal altid passe til vej og vejr.","efa":"خیر. این عدد راهنما برای شرایط عادی است؛ سرعت همیشه باید با جاده و هوا جور باشد.","en":"The number is a speed limit, so I may drive 40 km/h in the bend whatever the weather.","een":"No. The number is guidance for normal conditions; the speed must always suit the road and the weather."},{"da":"40 er den hastighed, svinget kan køres med under normale forhold; i kraftig regn kan jeg være nødt til at køre langsommere.","fa":"۴۰ سرعتی است که در شرایط عادی می‌توان پیچ را با آن رد کرد؛ در باران شدید شاید لازم باشد آهسته‌تر بروم.","ok":1,"eda":"Ja. Undertavlen angiver den hastighed, svinget under normale forhold kan gennemkøres med.","efa":"بله. تابلوی زیرین سرعتی را نشان می‌دهد که پیچ در شرایط عادی با آن پیموده می‌شود.","en":"40 is the speed at which the bend can be taken in normal conditions; in heavy rain I may have to go slower.","een":"Yes. The plate gives the speed at which the bend can be driven in normal conditions."},{"da":"Der kommer et farligt sving til højre.","fa":"یک پیچ خطرناک به راست در پیش است.","ok":1,"eda":"Ja. Tavlen advarer om et farligt vejsving.","efa":"بله. تابلو درباره‌ی پیچ خطرناک هشدار می‌دهد.","en":"A dangerous bend to the right is coming.","een":"Yes. The sign warns of a dangerous bend."}]},{"id":5214,"img":"newq-art/5214.png","c":"6.1","sda":"Du kører forbi denne tavle. Undertavlen viser 3,5 m. En lastbil kommer imod dig. Hvad gælder?","sfa":"از کنار این تابلو رد می‌شوید. تابلوی زیرین «۳٫۵ متر» را نشان می‌دهد. کامیونی از روبه‌رو می‌آید. چه قاعده‌ای برقرار است؟","sen":"You pass this sign. The plate shows 3.5 m. A lorry is coming towards you. What applies?","st":[{"da":"Vejen er kun 3,5 m bred på det smalle stykke.","fa":"عرض جاده در بخش باریک فقط ۳٫۵ متر است.","ok":1,"eda":"Ja. Undertavlen angiver den fri bredde på den indsnævrede strækning.","efa":"بله. تابلوی زیرین عرض آزاد بخش باریک را نشان می‌دهد.","en":"The road is only 3.5 m wide on the narrow stretch.","een":"Yes. The plate gives the free width of the narrowed stretch."},{"da":"Undertavlen betyder, at køretøjer, der er bredere end 3,5 m, ikke må køre ind.","fa":"تابلوی زیرین یعنی وسایل نقلیه‌ی پهن‌تر از ۳٫۵ متر نباید وارد شوند.","ok":0,"eda":"Nej. Undertavlen fortæller den fri bredde; et forbud for brede køretøjer har sin egen tavle.","efa":"خیر. تابلوی زیرین عرض آزاد را می‌گوید؛ ممنوعیت وسایل پهن تابلوی جداگانه دارد.","en":"The plate means that vehicles wider than 3.5 m may not drive in.","een":"No. The plate tells the free width; a ban on wide vehicles has its own sign."},{"da":"Vejen bliver smallere længere fremme.","fa":"جاده کمی جلوتر باریک‌تر می‌شود.","ok":1,"eda":"Ja. Tavlen advarer om indsnævret vej.","efa":"بله. تابلو درباره‌ی باریک شدن جاده هشدار می‌دهد.","en":"The road gets narrower further ahead.","een":"Yes. The sign warns of a road narrowing."},{"da":"Lastbilen og jeg kan ikke passere hinanden på det smalle stykke, så jeg er klar til at vente.","fa":"من و کامیون در بخش باریک نمی‌توانیم از کنار هم رد شویم، پس آماده‌ی صبر کردنم.","ok":1,"eda":"Ja. En lastbil og en bil er tilsammen bredere end 3,5 m.","efa":"بله. عرض کامیون و خودرو روی هم بیش از ۳٫۵ متر است.","en":"The lorry and I cannot pass each other on the narrow stretch, so I am ready to wait.","een":"Yes. A lorry and a car together are wider than 3.5 m."}]},{"id":5215,"img":"newq-art/5215.png","c":"6.1","sda":"Du kører forbi denne tavle. Hvad betyder den, og hvordan forholder du dig?","sfa":"از کنار این تابلو رد می‌شوید. معنی‌اش چیست و چه می‌کنید؟","sen":"You pass this sign. What does it mean, and what do you do?","st":[{"da":"Der kommer en stejl stigning, hvor jeg skal give mere gas.","fa":"سربالایی تندی در پیش است که باید بیشتر گاز بدهم.","ok":0,"eda":"Nej. En stigning har sin egen tavle; denne viser en nedkørsel.","efa":"خیر. سربالایی تابلوی خودش را دارد؛ این یکی سرپایینی را نشان می‌دهد.","en":"A steep climb is coming where I need to accelerate more.","een":"No. A climb has its own sign; this one shows a descent."},{"da":"Ned ad bakke bliver bremselængden længere end på flad vej.","fa":"در سرپایینی مسافت ترمز از جاده‌ی صاف طولانی‌تر است.","ok":1,"eda":"Ja. Tyngdekraften trækker bilen fremad, mens du bremser.","efa":"بله. گرانش هنگام ترمز خودرو را به جلو می‌کشد.","en":"Downhill the braking distance becomes longer than on a flat road.","een":"Yes. Gravity pulls the car forward while you brake."},{"da":"Jeg holder farten nede, fx med et lavere gear, så bremserne ikke bliver for varme.","fa":"سرعت را پایین نگه می‌دارم، مثلاً با دنده‌ی سنگین‌تر، تا ترمزها بیش از حد داغ نشوند.","ok":1,"eda":"Ja. Motorbremsning aflaster bremserne på en lang nedkørsel.","efa":"بله. ترمز موتور در سرپایینی طولانی بار ترمزها را کم می‌کند.","en":"I keep my speed down, for example with a lower gear, so that the brakes do not get too hot.","een":"Yes. Engine braking takes load off the brakes on a long descent."},{"da":"Der kommer en stejl nedkørsel med en hældning på op til 10 %.","fa":"سرپایینی تندی با شیب حداکثر ۱۰ درصد در پیش است.","ok":1,"eda":"Ja. Tavlen advarer om stejl nedkørsel; tallet angiver den største hældning.","efa":"بله. تابلو درباره‌ی سرپایینی تند هشدار می‌دهد؛ عدد بیشترین شیب را نشان می‌دهد.","en":"A steep descent with a gradient of up to 10 % is coming.","een":"Yes. The sign warns of a steep descent; the number gives the greatest gradient."}]},{"id":5216,"img":"newq-art/5216.png","c":"6.1","sda":"Du kommer til en jernbaneoverkørsel uden bomme og uden lyssignal. Lige før overkørslen står disse tavler. Hvad gælder?","sfa":"به گذرگاه راه‌آهنی بدون راه‌بند و بدون چراغ می‌رسید. درست پیش از گذرگاه این تابلوها نصب شده‌اند. چه قاعده‌ای برقرار است؟","sen":"You come to a level crossing without barriers and without light signals. Just before the crossing stand these signs. What applies?","st":[{"da":"Tavlerne står 150–250 m før overkørslen.","fa":"این تابلوها ۱۵۰ تا ۲۵۰ متر پیش از گذرگاه نصب شده‌اند.","ok":0,"eda":"Nej. Krydsmærket står umiddelbart foran overkørslen.","efa":"خیر. صلیب درست جلوی گذرگاه نصب می‌شود.","en":"The signs stand 150–250 m before the crossing.","een":"No. The cross marker stands right in front of the crossing."},{"da":"Der er mere end ét spor, så der kan komme endnu et tog, når det første er kørt forbi.","fa":"بیش از یک ریل هست، پس بعد از رد شدن قطار اول ممکن است قطار دیگری بیاید.","ok":1,"eda":"Ja. Det dobbelte krydsmærke betyder en overkørsel med flere spor.","efa":"بله. صلیبِ دوتایی یعنی گذرگاهی با چند ریل.","en":"There is more than one track, so another train may come when the first has gone by.","een":"Yes. The double cross marker means a crossing with several tracks."},{"da":"Jeg må standse på sporene, hvis der er kø på vejen efter overkørslen.","fa":"اگر بعد از گذرگاه صف باشد، می‌توانم روی ریل‌ها بایستم.","ok":0,"eda":"Nej. Det er forbudt at standse på en jernbaneoverkørsel; kør først ud på den, når du kan komme helt over.","efa":"خیر. توقف روی گذرگاه راه‌آهن ممنوع است؛ فقط وقتی واردش شوید که بتوانید کامل رد شوید.","en":"I may stop on the tracks if there is a queue on the road after the crossing.","een":"No. Stopping on a level crossing is forbidden; only drive onto it when you can get all the way across."},{"da":"Jeg skal selv se efter tog i begge retninger, før jeg kører over.","fa":"پیش از عبور باید خودم دو طرف را برای قطار نگاه کنم.","ok":1,"eda":"Ja. Undertavlen »Se efter tog« bruges, hvor overkørslen kun er sikret med afmærkning.","efa":"بله. تابلوی زیرینِ «Se efter tog» (مراقب قطار باشید) جایی است که گذرگاه فقط با تابلو ایمن شده است.","en":"I must look for trains in both directions myself before I cross.","een":"Yes. The plate “Se efter tog” (look for trains) is used where the crossing is protected by signs only."}]},{"id":5217,"img":"newq-art/5217.png","c":"7.6","sda":"Du nærmer dig et fodgængerfelt uden lyssignal. En kvinde står ved kantstenen og er på vej ud på feltet. Hvordan forholder du dig?","sfa":"به گذرگاه عابر پیاده‌ای بدون چراغ نزدیک می‌شوید. زنی کنار جدول ایستاده و می‌خواهد وارد گذرگاه شود. چه می‌کنید؟","sen":"You are approaching a pedestrian crossing without light signals. A woman is standing at the kerb and is about to step onto the crossing. What do you do?","st":[{"da":"Jeg sænker farten, så jeg kan standse, hvis hun går ud.","fa":"سرعت را کم می‌کنم تا اگر وارد شد، بتوانم بایستم.","ok":1,"eda":"Ja. Du skal tilpasse farten, så der ikke opstår fare eller ulempe for gående, der er på vej ud i feltet.","efa":"بله. باید سرعت را طوری تنظیم کنید که برای عابری که می‌خواهد وارد گذرگاه شود خطر یا مزاحمتی پیش نیاید.","en":"I slow down so that I can stop if she steps out.","een":"Yes. You must adjust your speed so that there is no danger or inconvenience to pedestrians about to step onto the crossing."},{"da":"Jeg dytter, så hun ved, at jeg kommer.","fa":"بوق می‌زنم تا بداند من دارم می‌آیم.","ok":0,"eda":"Nej. Hornet må kun bruges for at forebygge eller afværge fare.","efa":"خیر. بوق فقط برای پیشگیری یا دفع خطر است.","en":"I sound the horn so that she knows I am coming.","een":"No. The horn may only be used to prevent or avert danger."},{"da":"Om nødvendigt standser jeg og lader hende gå over.","fa":"در صورت لزوم می‌ایستم و می‌گذارم رد شود.","ok":1,"eda":"Ja. Du skal standse, hvis det er nødvendigt for at lade de gående passere.","efa":"بله. اگر لازم باشد، باید بایستید تا عابران رد شوند.","en":"If necessary, I stop and let her cross.","een":"Yes. You must stop if that is necessary to let the pedestrians cross."},{"da":"Jeg kører videre, fordi hun endnu ikke er ude på feltet.","fa":"ادامه می‌دهم، چون هنوز وارد گذرگاه نشده است.","ok":0,"eda":"Nej. Reglen gælder også gående, der er på vej ud i feltet.","efa":"خیر. این قاعده عابری را هم که در حال وارد شدن به گذرگاه است شامل می‌شود.","en":"I drive on because she is not on the crossing yet.","een":"No. The rule also covers pedestrians who are about to step onto the crossing."}]},{"id":5218,"img":"newq-art/5218.png","c":"7.6","sda":"En skraldebil holder i din side af vejen, og skraldemændene går frem og tilbage mellem bilen og husene. Hvordan forholder du dig?","sfa":"یک کامیون زباله در سمت شما ایستاده و کارگرانش میان کامیون و خانه‌ها رفت‌وآمد می‌کنند. چه می‌کنید؟","sen":"A refuse lorry is standing on your side of the road, and the refuse collectors are walking back and forth between the lorry and the houses. What do you do?","st":[{"da":"Jeg kører først forbi, når der er plads, og ingen modkørende er i vejen.","fa":"فقط وقتی رد می‌شوم که جا باشد و خودرویی از روبه‌رو مانع نباشد.","ok":1,"eda":"Ja. Er spærringen i din side, skal du om nødvendigt standse og lade de modkørende passere.","efa":"بله. اگر مانع در سمت شماست، در صورت لزوم باید بایستید تا خودروهای روبه‌رو رد شوند.","en":"I only pass when there is room and no oncoming traffic is in the way.","een":"Yes. If the obstruction is on your side, you must stop if necessary and let oncoming traffic pass."},{"da":"Jeg sænker farten og er klar til at standse.","fa":"سرعت را کم می‌کنم و آماده‌ی ایستادنم.","ok":1,"eda":"Ja. En person kan pludselig træde ud bag skraldebilen.","efa":"بله. ممکن است کسی ناگهان از پشت کامیون زباله بیرون بیاید.","en":"I slow down and am ready to stop.","een":"Yes. A person may suddenly step out from behind the refuse lorry."},{"da":"Jeg dytter, så skraldemændene går til side.","fa":"بوق می‌زنم تا کارگرها کنار بروند.","ok":0,"eda":"Nej. Hornet må kun bruges for at forebygge eller afværge fare, ikke for at skaffe plads.","efa":"خیر. بوق فقط برای پیشگیری یا دفع خطر است، نه برای باز کردن راه.","en":"I sound the horn so that the refuse collectors step aside.","een":"No. The horn may only be used to prevent or avert danger, not to make room."},{"da":"Jeg holder god afstand til siden, når jeg kører forbi.","fa":"هنگام رد شدن فاصله‌ی جانبی خوبی نگه می‌دارم.","ok":1,"eda":"Ja. Så har du plads, hvis en skraldemand træder frem.","efa":"بله. این‌طور اگر کارگری بیرون بیاید، جا دارید.","en":"I keep a good distance to the side when I pass.","een":"Yes. Then you have room if a refuse collector steps out."}]},{"id":5219,"img":"newq-art/5219.png","c":"7.6","sda":"Du kører langsomt på en parkeringsplads. Lidt fremme lyser baklygterne på en bil, der holder i en bås. Hvordan forholder du dig?","sfa":"در پارکینگ آهسته می‌رانید. کمی جلوتر چراغ دنده‌عقبِ خودرویی که در جای پارک ایستاده روشن است. چه می‌کنید؟","sen":"You are driving slowly in a car park. A little ahead, the reversing lights of a car standing in a bay are on. What do you do?","st":[{"da":"Jeg sænker farten og er klar til at standse, fordi bilen kan bakke ud foran mig.","fa":"سرعت را کم می‌کنم و آماده‌ی ایستادنم، چون ممکن است آن خودرو جلوی من دنده‌عقب بیرون بیاید.","ok":1,"eda":"Ja. Baklygterne viser, at bilen er sat i bakgear.","efa":"بله. چراغ دنده‌عقب نشان می‌دهد خودرو در دنده‌عقب است.","en":"I slow down and am ready to stop because the car may reverse out in front of me.","een":"Yes. The reversing lights show that the car is in reverse gear."},{"da":"Den, der bakker, skal sikre sig, at det kan ske uden fare eller ulempe for andre.","fa":"کسی که دنده‌عقب می‌رود باید مطمئن شود برای دیگران خطر یا مزاحمتی ندارد.","ok":1,"eda":"Ja. Det følger af reglerne om bakning; du skal alligevel være klar til at standse.","efa":"بله. این از قواعد دنده‌عقب است؛ با این حال شما هم باید آماده‌ی ایستادن باشید.","en":"Whoever is reversing must make sure it can be done without danger or inconvenience to others.","een":"Yes. That follows from the rules on reversing; you must still be ready to stop."},{"da":"Jeg kan regne med, at føreren har set mig.","fa":"می‌توانم مطمئن باشم راننده مرا دیده است.","ok":0,"eda":"Nej. Føreren kan have svært ved at se dig bag bilen; vær klar til at standse.","efa":"خیر. ممکن است راننده شما را پشت خودرو به‌سختی ببیند؛ آماده‌ی ایستادن باشید.","en":"I can count on the driver having seen me.","een":"No. The driver may find it hard to see you behind the car; be ready to stop."}]},{"id":5220,"img":"newq-art/5220.png","c":"7.6","sda":"En fodgænger går i højre side af landevejen med ryggen til dig. Der er hverken fortov eller sti. Hvordan forholder du dig?","sfa":"عابری در سمت راست جاده‌ی بیرون شهر، پشت به شما راه می‌رود. نه پیاده‌رو هست و نه مسیر. چه می‌کنید؟","sen":"A pedestrian is walking on the right-hand side of the country road with his back to you. There is neither a pavement nor a path. What do you do?","st":[{"da":"Jeg dytter tæt bag ham, så han går over i den rigtige side.","fa":"از نزدیک پشت سرش بوق می‌زنم تا به سمت درست برود.","ok":0,"eda":"Nej. Et dyt tæt på kan forskrække ham, så han træder ud foran dig.","efa":"خیر. بوقِ نزدیک ممکن است او را بترساند و جلوی شما بپرد.","en":"I sound the horn close behind him so that he moves to the correct side.","een":"No. A honk close by can startle him so that he steps out in front of you."},{"da":"Fodgængeren burde gå i venstre side, men jeg skal tage hensyn til ham alligevel.","fa":"عابر باید سمت چپ راه برود، ولی من به هر حال باید مراقبش باشم.","ok":1,"eda":"Ja. Gående på kørebanen skal gå i venstre side; din pligt til at tage hensyn gælder dog altid.","efa":"بله. عابری که روی سواره‌رو راه می‌رود باید سمت چپ باشد؛ ولی وظیفه‌ی ملاحظه‌ی شما همیشه برقرار است.","en":"The pedestrian should be walking on the left, but I must take care of him anyway.","een":"Yes. Pedestrians on the carriageway must walk on the left; but your duty to take care always applies."},{"da":"Jeg sænker farten og giver fodgængeren god plads, når jeg kører forbi.","fa":"سرعت را کم می‌کنم و هنگام رد شدن جای کافی به عابر می‌دهم.","ok":1,"eda":"Ja. Du skal give gående tid til at gå til side og i øvrigt give dem fornøden plads på vejen.","efa":"بله. باید به عابر وقت بدهید کنار برود و جای کافی روی جاده به او بدهید.","en":"I slow down and give the pedestrian plenty of room when I pass.","een":"Yes. You must give pedestrians time to step aside and otherwise give them enough room on the road."},{"da":"Før jeg kører ud omkring ham, sikrer jeg mig, at der ikke kommer modkørende.","fa":"پیش از دور زدن او مطمئن می‌شوم خودرویی از روبه‌رو نمی‌آید.","ok":1,"eda":"Ja. Er der modkørende, venter du bag fodgængeren, til der er plads.","efa":"بله. اگر خودرویی از روبه‌رو بیاید، پشت عابر صبر می‌کنید تا جا باز شود.","en":"Before I swing out around him, I make sure that no oncoming traffic is coming.","een":"Yes. If there is oncoming traffic, you wait behind the pedestrian until there is room."}]},{"id":5221,"img":"newq-art/5221.png","c":"7.3","sda":"Du kører forbi denne tavle. Der er ingen hastighedstavler. Hvad gælder?","sfa":"از کنار این تابلو رد می‌شوید. تابلوی سرعتی نیست. چه قاعده‌ای برقرار است؟","sen":"You pass this sign. There are no speed signs. What applies?","st":[{"da":"Den højst tilladte hastighed er 50 km/t.","fa":"حداکثر سرعت مجاز ۵۰ کیلومتر بر ساعت است.","ok":1,"eda":"Ja. Tavlen viser, at du kører ind i tættere bebygget område, hvor grænsen er 50 km/t.","efa":"بله. تابلو نشان می‌دهد وارد محدوده‌ی شهری می‌شوید که حد سرعتش ۵۰ کیلومتر بر ساعت است.","en":"The maximum permitted speed is 50 km/h.","een":"Yes. The sign shows that you are entering a built-up area, where the limit is 50 km/h."},{"da":"Grænsen er 60 km/t, indtil jeg ser en tavle med 50.","fa":"تا تابلوی ۵۰ را نبینم، حد سرعت ۶۰ است.","ok":0,"eda":"Nej. Grænsen på 50 km/t gælder fra byzonetavlen.","efa":"خیر. حد ۵۰ از همین تابلوی ورود به شهر برقرار است.","en":"The limit is 60 km/h until I see a sign with 50.","een":"No. The 50 km/h limit applies from the built-up area sign."},{"da":"Tavlen viser kun byens navn og har ingen betydning for hastigheden.","fa":"این تابلو فقط نام شهر است و ربطی به سرعت ندارد.","ok":0,"eda":"Nej. Byzonetavlen angiver, at reglerne for tættere bebygget område gælder.","efa":"خیر. تابلوی ورود به شهر یعنی قواعد محدوده‌ی شهری برقرار است.","en":"The sign only shows the name of the town and means nothing for the speed.","een":"No. The built-up area sign shows that the rules for built-up areas apply."},{"da":"Grænsen på 50 km/t gælder kun om dagen.","fa":"حد ۵۰ فقط در روز است.","ok":0,"eda":"Nej. Grænsen gælder hele døgnet.","efa":"خیر. این حد در تمام شبانه‌روز برقرار است.","en":"The 50 km/h limit only applies in the daytime.","een":"No. The limit applies around the clock."}]},{"id":5222,"img":"newq-art/5222.png","c":"7.3","sda":"Du kører forbi denne tavle ud af byen. Der er ingen hastighedstavler. Hvad gælder?","sfa":"هنگام خروج از شهر از کنار این تابلو رد می‌شوید. تابلوی سرعتی نیست. چه قاعده‌ای برقرار است؟","sen":"You pass this sign on your way out of the town. There are no speed signs. What applies?","st":[{"da":"Den højst tilladte hastighed er nu 80 km/t.","fa":"اکنون حداکثر سرعت مجاز ۸۰ کیلومتر بر ساعت است.","ok":1,"eda":"Ja. Tavlen angiver, at det tættere bebyggede område ophører; uden for gælder 80 km/t.","efa":"بله. تابلو پایان محدوده‌ی شهری را نشان می‌دهد؛ بیرون از آن حد ۸۰ است.","en":"The maximum permitted speed is now 80 km/h.","een":"Yes. The sign shows that the built-up area ends; outside it 80 km/h applies."},{"da":"Jeg skal stadig tilpasse farten til vejen og trafikken.","fa":"همچنان باید سرعتم را با جاده و ترافیک تنظیم کنم.","ok":1,"eda":"Ja. Hastighedsgrænsen er det højeste; forholdene kan kræve mindre.","efa":"بله. حد سرعت حداکثر است؛ شرایط ممکن است کمتر بخواهد.","en":"I must still adjust my speed to the road and the traffic.","een":"Yes. The limit is the highest; conditions may require less."},{"da":"Nu gælder der ingen hastighedsgrænse, indtil næste tavle.","fa":"تا تابلوی بعدی هیچ حد سرعتی برقرار نیست.","ok":0,"eda":"Nej. Den generelle grænse uden for tættere bebygget område er 80 km/t.","efa":"خیر. حد عمومی بیرون از محدوده‌ی شهری ۸۰ کیلومتر بر ساعت است.","en":"Now there is no speed limit until the next sign.","een":"No. The general limit outside built-up areas is 80 km/h."}]},{"id":5223,"img":"newq-art/5223.png","c":"7.3","sda":"Du kører på en motortrafikvej. Der er ingen hastighedstavler. Hvad er den højst tilladte hastighed for en almindelig personbil?","sfa":"در یک جاده‌ی ویژه‌ی خودرو (motortrafikvej) می‌رانید. تابلوی سرعتی نیست. حداکثر سرعت مجاز برای یک خودروی سواری معمولی چقدر است؟","sen":"You are driving on a motortrafikvej (a road for motor vehicles only). There are no speed signs. What is the maximum permitted speed for an ordinary car?","st":[{"da":"130 km/t.","fa":"۱۳۰ کیلومتر بر ساعت.","ok":0,"eda":"Nej. 130 km/t er den generelle grænse på motorvej.","efa":"خیر. ۱۳۰ حد عمومی بزرگراه است.","en":"130 km/h.","een":"No. 130 km/h is the general limit on the motorway."},{"da":"110 km/t.","fa":"۱۱۰ کیلومتر بر ساعت.","ok":0,"eda":"Nej. På motortrafikvej må grænsen højst være 100 km/t.","efa":"خیر. در motortrafikvej حد سرعت حداکثر ۱۰۰ است.","en":"110 km/h.","een":"No. On a motortrafikvej the limit can be at most 100 km/h."},{"da":"80 km/t.","fa":"۸۰ کیلومتر بر ساعت.","ok":1,"eda":"Ja. Den generelle grænse på motortrafikvej er 80 km/t; med tavler kan den være højst 100 km/t.","efa":"بله. حد عمومی در motortrafikvej ۸۰ است؛ با تابلو حداکثر تا ۱۰۰ می‌تواند بالا برود.","en":"80 km/h.","een":"Yes. The general limit on a motortrafikvej is 80 km/h; signs can raise it to at most 100 km/h."},{"da":"90 km/t.","fa":"۹۰ کیلومتر بر ساعت.","ok":0,"eda":"Nej. 90 km/t gælder kun, hvor det er skiltet.","efa":"خیر. ۹۰ فقط جایی است که تابلو داشته باشد.","en":"90 km/h.","een":"No. 90 km/h only applies where it is signposted."}]},{"id":5224,"img":"newq-art/5224.png","c":"7.3","sda":"Du kører på motorvejen med en almindelig trailer, som ikke er godkendt til 100 km/t. Hvad er den højst tilladte hastighed?","sfa":"در بزرگراه با یک تریلر معمولی می‌رانید که مجوز ۱۰۰ کیلومتر بر ساعت ندارد. حداکثر سرعت مجاز چقدر است؟","sen":"You are driving on the motorway with an ordinary trailer that is not approved for 100 km/h. What is the maximum permitted speed?","st":[{"da":"80 km/t.","fa":"۸۰ کیلومتر بر ساعت.","ok":1,"eda":"Ja. Bil med påhængskøretøj må højst køre 80 km/t; på motorvej 100 km/t kun, hvis vogntoget er godkendt til det (Tempo 100).","efa":"بله. خودرو با تریلر حداکثر ۸۰ کیلومتر بر ساعت؛ در بزرگراه فقط اگر مجوزش را داشته باشد (Tempo 100)، ۱۰۰.","en":"80 km/h.","een":"Yes. A car with a trailer may drive at most 80 km/h; on the motorway 100 km/h only if the combination is approved for it (Tempo 100)."},{"da":"100 km/t.","fa":"۱۰۰ کیلومتر بر ساعت.","ok":0,"eda":"Nej. 100 km/t kræver en særlig godkendelse af vogntoget.","efa":"خیر. ۱۰۰ کیلومتر بر ساعت مجوز ویژه لازم دارد.","en":"100 km/h.","een":"No. 100 km/h requires a special approval of the combination."},{"da":"110 km/t.","fa":"۱۱۰ کیلومتر بر ساعت.","ok":0,"eda":"Nej. Med trailer må du aldrig køre så hurtigt.","efa":"خیر. با تریلر هیچ‌وقت نباید این‌قدر تند برانید.","en":"110 km/h.","een":"No. With a trailer you may never drive that fast."},{"da":"130 km/t.","fa":"۱۳۰ کیلومتر بر ساعت.","ok":0,"eda":"Nej. 130 km/t gælder for biler uden påhængskøretøj.","efa":"خیر. ۱۳۰ برای خودروهای بدون تریلر است.","en":"130 km/h.","een":"No. 130 km/h applies to cars without a trailer."}]},{"id":5225,"img":"newq-art/5225.png","c":"1.2","sda":"Hvad gælder om bilens dæktryk?","sfa":"درباره‌ی فشار باد لاستیک‌های خودرو چه درست است؟","sen":"What applies to the car's tyre pressure?","st":[{"da":"Trykket skal altid være det samme, uanset hvor meget bilen er lastet.","fa":"فشار باید همیشه یکی باشد، خودرو هر قدر هم بار داشته باشد.","ok":0,"eda":"Nej. Ofte skal trykket være højere, når bilen er fuldt lastet.","efa":"خیر. اغلب وقتی خودرو پربار است، فشار باید بیشتر باشد.","en":"The pressure must always be the same, however heavily the car is loaded.","een":"No. The pressure often needs to be higher when the car is fully loaded."},{"da":"Jeg måler trykket, når dækkene er kolde, fx før jeg kører.","fa":"فشار را وقتی لاستیک‌ها سردند، مثلاً پیش از حرکت، اندازه می‌گیرم.","ok":1,"eda":"Ja. Varme dæk viser et højere tryk, så målingen bliver forkert.","efa":"بله. لاستیک گرم فشار بیشتری نشان می‌دهد و اندازه‌گیری نادرست می‌شود.","en":"I check the pressure when the tyres are cold, for example before I drive.","een":"Yes. Warm tyres show a higher pressure, so the reading is wrong."},{"da":"Det rigtige tryk står i instruktionsbogen eller på et mærkat på bilen.","fa":"فشار درست در دفترچه‌ی راهنما یا روی برچسبی روی خودرو نوشته شده است.","ok":1,"eda":"Ja. Fabrikken angiver trykket, ofte i dørkarmen eller i tankklappen.","efa":"بله. کارخانه فشار را معمولاً روی چارچوب در یا درِ باک می‌نویسد.","en":"The correct pressure is given in the owner's manual or on a label on the car.","een":"Yes. The manufacturer gives the pressure, often in the door frame or the fuel flap."},{"da":"For lavt dæktryk kan give dårligere vejgreb og en længere bremselængde.","fa":"فشار باد خیلی کم ممکن است چسبندگی را کم و مسافت ترمز را بیشتر کند.","ok":1,"eda":"Ja. Dækket bliver blødt og arbejder dårligere mod vejen.","efa":"بله. لاستیک نرم می‌شود و روی جاده بدتر کار می‌کند.","en":"Too low a tyre pressure can give poorer grip and a longer braking distance.","een":"Yes. The tyre gets soft and works worse against the road."}]},{"id":5226,"img":"newq-art/5226.png","c":"7.12","sda":"Du kommer ad en sidevej med hajtænder og en vigepligtstavle og skal ligeud over hovedvejen. Langs hovedvejen er der en dobbeltrettet cykelsti. Hvad gælder?","sfa":"از جاده‌ای فرعی با خط دندان‌کوسه و تابلوی حق تقدم می‌آیید و می‌خواهید مستقیم از جاده‌ی اصلی رد شوید. کنار جاده‌ی اصلی مسیر دوچرخه‌ی دوطرفه هست. چه قاعده‌ای برقرار است؟","sen":"You are coming along a side road with shark teeth and a give-way sign and are going straight across the main road. Along the main road there is a two-way cycle path. What applies?","st":[{"da":"Cyklister fra højre på cykelstien skal holde tilbage for mig.","fa":"دوچرخه‌سوارهایی که از راست روی مسیر دوچرخه می‌آیند باید به من راه بدهند.","ok":0,"eda":"Nej. Du har ubetinget vigepligt for alle; på en dobbeltrettet sti kan cyklister komme fra begge retninger.","efa":"خیر. شما باید به همه راه بدهید؛ در مسیر دوطرفه دوچرخه‌سوار از هر دو جهت می‌آید.","en":"Cyclists from the right on the cycle path must give way to me.","een":"No. You must give way to everyone; on a two-way path cyclists can come from both directions."},{"da":"Jeg skal holde tilbage for cyklister på cykelstien fra begge retninger.","fa":"باید به دوچرخه‌سوارهای مسیر دوچرخه از هر دو جهت راه بدهم.","ok":1,"eda":"Ja. Ubetinget vigepligt gælder den kørende færdsel fra begge sider, også cyklister på cykelstien.","efa":"بله. حق تقدم مطلق برای ترافیک هر دو طرف است، از جمله دوچرخه‌سوارهای مسیر دوچرخه.","en":"I must give way to cyclists on the cycle path from both directions.","een":"Yes. The duty to give way applies to traffic from both sides, also cyclists on the cycle path."},{"da":"Jeg viser i god tid, at jeg vil holde tilbage, ved at sætte farten ned eller standse.","fa":"به موقع با کم کردن سرعت یا ایستادن نشان می‌دهم که راه می‌دهم.","ok":1,"eda":"Ja. Den, der har vigepligt, skal tydeligt og i god tid vise det ved at nedsætte farten eller standse.","efa":"بله. کسی که باید راه بدهد، باید به‌روشنی و به موقع با کم کردن سرعت یا ایستادن این را نشان دهد.","en":"I show in good time that I will give way by slowing down or stopping.","een":"Yes. Whoever has to give way must show it clearly and in good time by slowing down or stopping."},{"da":"Jeg skal holde tilbage for bilerne på hovedvejen fra både venstre og højre.","fa":"باید به خودروهای جاده‌ی اصلی، هم از چپ و هم از راست، راه بدهم.","ok":1,"eda":"Ja. Med ubetinget vigepligt skal du holde tilbage for al kørende færdsel på den vej, du kører ind på eller over.","efa":"بله. با حق تقدم مطلق باید به همه‌ی ترافیک جاده‌ای که واردش می‌شوید یا از آن رد می‌شوید راه بدهید.","en":"I must give way to the cars on the main road from both left and right.","een":"Yes. With an unconditional duty to give way, you must give way to all traffic on the road you drive onto or across."}]},{"id":5227,"img":"newq-art/5227.png","c":"7.12","sda":"Du kører ligeud ad vejen gennem et T-kryds uden tavler og afmærkning. Fra sidevejen til højre kommer en bil. Hvad gælder?","sfa":"در امتداد جاده از یک سه‌راهی بدون تابلو و خط‌کشی مستقیم می‌روید. خودرویی از جاده‌ی فرعی سمت راست می‌آید. چه قاعده‌ای برقرار است؟","sen":"You are driving straight on along the road through a T-junction without signs or markings. A car is coming from the side road on the right. What applies?","st":[{"da":"Jeg sætter farten ned i god tid, så føreren kan se, at jeg holder tilbage.","fa":"به موقع سرعت را کم می‌کنم تا راننده ببیند که راه می‌دهم.","ok":1,"eda":"Ja. Den, der har vigepligt, skal vise det tydeligt og i god tid.","efa":"بله. کسی که باید راه بدهد، باید این را به‌روشنی و به موقع نشان دهد.","en":"I slow down in good time so that the driver can see that I am giving way.","een":"Yes. Whoever has to give way must show it clearly and in good time."},{"da":"Jeg har forkørselsret, fordi jeg kører på den gennemgående vej.","fa":"حق تقدم با من است، چون در جاده‌ی سرتاسری می‌رانم.","ok":0,"eda":"Nej. Den gennemgående vej giver kun forkørselsret, hvis det er afmærket, fx med hajtænder på sidevejen.","efa":"خیر. جاده‌ی سرتاسری فقط وقتی حق تقدم می‌دهد که علامت داشته باشد، مثلاً خط دندان‌کوسه روی فرعی.","en":"I have the right of way because I am on the road that goes straight through.","een":"No. The road going through only gives the right of way if it is marked, for example with shark teeth on the side road."},{"da":"Jeg skal holde tilbage for bilen fra højre.","fa":"باید به خودرویی که از راست می‌آید راه بدهم.","ok":1,"eda":"Ja. Uden tavler og afmærkning gælder højrevigepligt, også i et T-kryds.","efa":"بله. بدون تابلو و خط‌کشی، قاعده‌ی دست راست برقرار است، در سه‌راهی هم.","en":"I must give way to the car from the right.","een":"Yes. Without signs or markings the right-hand rule applies, also at a T-junction."},{"da":"Bilen fra højre skal holde tilbage, fordi den kommer fra en mindre vej.","fa":"خودروی سمت راست باید راه بدهد، چون از جاده‌ی کوچک‌تری می‌آید.","ok":0,"eda":"Nej. Vejens størrelse ændrer ikke højrevigepligten; det gør kun tavler og afmærkning.","efa":"خیر. اندازه‌ی جاده قاعده‌ی دست راست را تغییر نمی‌دهد؛ فقط تابلو و خط‌کشی.","en":"The car from the right must give way because it is coming from a smaller road.","een":"No. The size of the road does not change the right-hand rule; only signs and markings do."}]},{"id":5228,"img":"newq-art/5228.png","c":"7.12","sda":"Du kører ud fra en sidevej. Fortovet og cykelstien langs den større vej fortsætter i deres egen højde hen over sidevejens udmunding, og du skal køre op over dem. Der er ingen tavler. Hvad gælder?","sfa":"از جاده‌ای فرعی بیرون می‌آیید. پیاده‌رو و مسیر دوچرخه‌ی کنار جاده‌ی بزرگ‌تر، هم‌سطح خودشان از جلوی دهانه‌ی فرعی می‌گذرند و باید از رویشان رد شوید. تابلویی نیست. چه قاعده‌ای برقرار است؟","sen":"You are driving out of a side road. The pavement and the cycle path along the bigger road continue across the mouth of the side road at their own level, and you have to drive up over them. There are no signs. What applies?","st":[{"da":"Højrevigepligten gælder, fordi der ikke er nogen tavle.","fa":"قاعده‌ی دست راست برقرار است، چون تابلویی نیست.","ok":0,"eda":"Nej. Udkørslen over det hævede fortov giver ubetinget vigepligt, også uden tavle.","efa":"خیر. خروج از روی پیاده‌روی بلندتر، حتی بدون تابلو، حق تقدم را مطلقاً به دیگران می‌دهد.","en":"The right-hand rule applies because there is no sign.","een":"No. The exit over the raised pavement gives an unconditional duty to give way, also without a sign."},{"da":"Jeg har ubetinget vigepligt for den trafik, jeg skal ind i.","fa":"در برابر ترافیکی که واردش می‌شوم حق تقدم مطلق با دیگران است.","ok":1,"eda":"Ja. Ved udkørsel fra en vej over et fortov eller en cykelsti, der er hævet over kørebanen, har du ubetinget vigepligt.","efa":"بله. وقتی از جاده‌ای از روی پیاده‌رو یا مسیر دوچرخه‌ای که بالاتر از سواره‌روست بیرون می‌آیید، باید بی‌قید و شرط راه بدهید.","en":"I have an unconditional duty to give way to the traffic I am driving into.","een":"Yes. When you drive out of a road over a pavement or cycle path raised above the carriageway, you have an unconditional duty to give way."},{"da":"Jeg skal holde tilbage for den gående på fortovet og for cyklisten på cykelstien.","fa":"باید به عابرِ پیاده‌رو و دوچرخه‌سوارِ مسیر دوچرخه راه بدهم.","ok":1,"eda":"Ja. Når du kører over et fortov, skal du holde tilbage for gående, og vigepligten gælder også cyklisterne.","efa":"بله. وقتی از روی پیاده‌رو رد می‌شوید باید به عابران راه بدهید و وظیفه‌ی راه دادن شامل دوچرخه‌سوارها هم هست.","en":"I must give way to the pedestrian on the pavement and to the cyclist on the cycle path.","een":"Yes. When you drive over a pavement you must give way to pedestrians, and your duty to give way also covers the cyclists."},{"da":"Cyklisten skal holde tilbage for mig, fordi han kommer fra venstre.","fa":"دوچرخه‌سوار باید به من راه بدهد، چون از چپ می‌آید.","ok":0,"eda":"Nej. Du har vigepligt for trafikken fra begge sider.","efa":"خیر. شما باید به ترافیک هر دو طرف راه بدهید.","en":"The cyclist must give way to me because he is coming from the left.","een":"No. You must give way to the traffic from both sides."}]},{"id":5229,"img":"newq-art/5229.png","c":"7.12","sda":"Du har grønt lys og skal ligeud. En ung mand løber ud på fodgængerfeltet foran dig, selv om han har rødt. Hvordan forholder du dig?","sfa":"چراغ شما سبز است و مستقیم می‌روید. مرد جوانی با این‌که چراغش قرمز است، روی گذرگاه عابر جلوی شما می‌دود. چه می‌کنید؟","sen":"You have a green light and are going straight on. A young man runs out onto the pedestrian crossing in front of you even though he has a red light. What do you do?","st":[{"da":"Jeg skal holde tilbage for gående, der er i feltet, selv om jeg har grønt.","fa":"باید به عابرانی که روی گذرگاه هستند راه بدهم، حتی اگر چراغم سبز باشد.","ok":1,"eda":"Ja. Selv om signalet giver dig lov til at køre, skal du holde tilbage for gående, der er i feltet.","efa":"بله. حتی اگر چراغ اجازه‌ی حرکت بدهد، باید به عابرانی که روی گذرگاه هستند راه بدهید.","en":"I must give way to pedestrians who are on the crossing, even though I have green.","een":"Yes. Even though the signal lets you drive, you must give way to pedestrians who are on the crossing."},{"da":"Jeg bremser og gør, hvad jeg kan, for at undgå at ramme ham.","fa":"ترمز می‌کنم و هر کاری بتوانم می‌کنم تا به او نزنم.","ok":1,"eda":"Ja. Grønt lys fritager dig ikke for at undgå et uheld.","efa":"بله. چراغ سبز شما را از پرهیز از تصادف معاف نمی‌کند.","en":"I brake and do what I can to avoid hitting him.","een":"Yes. A green light does not free you from avoiding an accident."},{"da":"Jeg kører videre, fordi han har rødt og selv må tage ansvaret.","fa":"ادامه می‌دهم، چون چراغ او قرمز است و خودش مسئول است.","ok":0,"eda":"Nej. Du skal holde tilbage for gående i feltet, også når de går over for rødt.","efa":"خیر. باید به عابرانِ روی گذرگاه راه بدهید، حتی وقتی با چراغ قرمز رد می‌شوند.","en":"I drive on because he has a red light and must take the responsibility himself.","een":"No. You must give way to pedestrians on the crossing, also when they cross on red."}]},{"id":5230,"img":"newq-art/5230.png","c":"7.12","sda":"Du venter ved hajtænderne på at køre ligeud over hovedvejen. En bil kommer fra venstre ad hovedvejen og blinker til højre, som om den vil ind på din vej. Hvordan forholder du dig?","sfa":"پشت خط دندان‌کوسه منتظرید تا مستقیم از جاده‌ی اصلی رد شوید. خودرویی از چپ در جاده‌ی اصلی می‌آید و راهنمای راست زده، گویی می‌خواهد وارد جاده‌ی شما شود. چه می‌کنید؟","sen":"You are waiting at the shark teeth to drive straight across the main road. A car is coming from the left along the main road with its right indicator on, as if it is going to turn into your road. What do you do?","st":[{"da":"Jeg kører ud, så snart bilen blinker, for så skal den ikke ligeud.","fa":"به محض این‌که راهنما زد حرکت می‌کنم، چون پس مستقیم نمی‌رود.","ok":0,"eda":"Nej. Et blinklys er ingen garanti; du har stadig ubetinget vigepligt.","efa":"خیر. راهنما تضمین نیست؛ شما همچنان باید بی‌قید و شرط راه بدهید.","en":"I drive out as soon as the car signals, because then it is not going straight on.","een":"No. An indicator is no guarantee; you still have an unconditional duty to give way."},{"da":"Når bilen blinker, har den pligt til at svinge, så jeg kan køre.","fa":"وقتی راهنما می‌زند، موظف است بپیچد، پس می‌توانم بروم.","ok":0,"eda":"Nej. Blinklyset forpligter ikke føreren; du må først køre, når det kan ske uden fare.","efa":"خیر. راهنما راننده را متعهد نمی‌کند؛ فقط وقتی بروید که بی‌خطر باشد.","en":"When the car signals, it is obliged to turn, so I can go.","een":"No. The indicator does not bind the driver; you may only go when it can be done without danger."},{"da":"Jeg venter, til jeg kan se, at bilen virkelig svinger.","fa":"صبر می‌کنم تا ببینم آن خودرو واقعاً می‌پیچد.","ok":1,"eda":"Ja. Føreren kan have glemt at slukke blinklyset eller vil svinge længere fremme.","efa":"بله. ممکن است راننده خاموش کردن راهنما را فراموش کرده باشد یا جلوتر بپیچد.","en":"I wait until I can see that the car really is turning.","een":"Yes. The driver may have forgotten to cancel the indicator or may be turning further on."},{"da":"Jeg blinker med forlygterne for at vise, at jeg kører først.","fa":"با چراغ جلو چشمک می‌زنم تا نشان دهم اول می‌روم.","ok":0,"eda":"Nej. Du har vigepligt og skal vise, at du holder tilbage, ikke det modsatte.","efa":"خیر. شما باید راه بدهید و باید نشان دهید که صبر می‌کنید، نه برعکس.","en":"I flash my headlights to show that I am going first.","een":"No. You have to give way and must show that you are holding back, not the opposite."}]},{"id":5231,"img":"newq-art/5231.png","c":"7.12","sda":"Du holder for rødt i krydset og skal ligeud. Ved siden af dit signal står et mindre signal med et cykelsymbol, og det skifter til grønt. Hvad gælder?","sfa":"پشت چراغ قرمز تقاطع ایستاده‌اید و می‌خواهید مستقیم بروید. کنار چراغ شما چراغ کوچک‌تری با علامت دوچرخه هست که سبز می‌شود. چه قاعده‌ای برقرار است؟","sen":"You are stopped at a red light in the junction and are going straight on. Beside your signal there is a smaller signal with a bicycle symbol, and it changes to green. What applies?","st":[{"da":"Jeg venter, til mit eget signal viser grønt.","fa":"صبر می‌کنم تا چراغ خودم سبز شود.","ok":1,"eda":"Ja. Signalet med cykelsymbol gælder kun cyklister og små knallerter, der kører samme sted.","efa":"بله. چراغی که علامت دوچرخه دارد فقط برای دوچرخه‌سوارها و موپدهای کوچکی است که همان‌جا می‌رانند.","en":"I wait until my own signal shows green.","een":"Yes. The signal with the bicycle symbol only applies to cyclists and small mopeds riding there."},{"da":"Det grønne cykelsignal betyder, at alle i min retning må køre.","fa":"چراغ سبز دوچرخه یعنی همه‌ی کسانی که در جهت من هستند می‌توانند بروند.","ok":0,"eda":"Nej. Cyklistsignalet gælder kun for cyklister.","efa":"خیر. چراغ دوچرخه فقط برای دوچرخه‌سوارهاست.","en":"The green cyclist signal means that everyone in my direction may go.","een":"No. The cyclist signal only applies to cyclists."},{"da":"Jeg må køre, fordi cyklisterne har fået grønt.","fa":"می‌توانم بروم، چون چراغ دوچرخه‌ها سبز شده است.","ok":0,"eda":"Nej. Du skal følge dit eget signal.","efa":"خیر. باید از چراغ خودتان پیروی کنید.","en":"I may go because the cyclists have got green.","een":"No. You must follow your own signal."},{"da":"Jeg må køre, hvis der ikke kommer cyklister.","fa":"اگر دوچرخه‌سواری نیاید، می‌توانم بروم.","ok":0,"eda":"Nej. Rødt lys betyder stop, uanset hvad cyklistsignalet viser.","efa":"خیر. چراغ قرمز یعنی ایست، چراغ دوچرخه هر چه نشان دهد.","en":"I may go if no cyclists are coming.","een":"No. A red light means stop, whatever the cyclist signal shows."}]},{"id":5232,"img":"newq-art/5232.png","c":"7.12","sda":"Du har grønt lys og skal ligeud. En modkørende bil holder midt i krydset og venter på at svinge til venstre. Hvad gælder?","sfa":"چراغ شما سبز است و مستقیم می‌روید. خودرویی از روبه‌رو وسط تقاطع منتظر گردش به چپ است. چه قاعده‌ای برقرار است؟","sen":"You have a green light and are going straight on. An oncoming car is waiting in the middle of the junction to turn left. What applies?","st":[{"da":"Bilen skal holde tilbage for mig, fordi den skal svinge til venstre.","fa":"آن خودرو باید به من راه بدهد، چون به چپ می‌پیچد.","ok":1,"eda":"Ja. Den, der svinger til venstre, må ikke være til ulempe for modkørende færdsel.","efa":"بله. کسی که به چپ می‌پیچد نباید برای ترافیک روبه‌رو مزاحمت ایجاد کند.","en":"The car must give way to me because it is turning left.","een":"Yes. Whoever turns left must not inconvenience oncoming traffic."},{"da":"Jeg dytter, så bilen ved, at den skal vente.","fa":"بوق می‌زنم تا آن خودرو بداند باید صبر کند.","ok":0,"eda":"Nej. Hornet må kun bruges for at forebygge eller afværge fare.","efa":"خیر. بوق فقط برای پیشگیری یا دفع خطر است.","en":"I sound the horn so that the car knows it must wait.","een":"No. The horn may only be used to prevent or avert danger."},{"da":"Jeg holder øje med bilen og er klar til at bremse, hvis den alligevel svinger ud foran mig.","fa":"مراقب آن خودرو هستم و اگر با این حال جلوی من بپیچد، آماده‌ی ترمزم.","ok":1,"eda":"Ja. Du må regne med, at andre følger reglerne, men skal være klar, hvis de ikke gør.","efa":"بله. می‌توانید فرض کنید دیگران قواعد را رعایت می‌کنند، ولی اگر نکردند باید آماده باشید.","en":"I keep an eye on the car and am ready to brake if it turns out in front of me anyway.","een":"Yes. You may count on others following the rules, but must be ready if they do not."},{"da":"Jeg standser og lader bilen svinge først.","fa":"می‌ایستم تا آن خودرو اول بپیچد.","ok":0,"eda":"Nej. Du har forkørselsret; en unødig standsning kan forvirre og overraske dem bag dig.","efa":"خیر. حق تقدم با شماست؛ ایستادن بی‌دلیل ممکن است پشت‌سری‌ها را گیج و غافلگیر کند.","en":"I stop and let the car turn first.","een":"No. You have the right of way; an unnecessary stop can confuse and surprise those behind you."}]},{"id":5233,"img":"newq-art/5233.png","c":"7.12","sda":"Du kører 50 km/t, og lyset skifter fra grønt til gult, lige da du er få meter fra stoplinjen. Hvad gælder?","sfa":"با ۵۰ کیلومتر بر ساعت می‌رانید و درست وقتی چند متر تا خط ایست مانده، چراغ از سبز به زرد تغییر می‌کند. چه قاعده‌ای برقرار است؟","sen":"You are driving at 50 km/h, and the light changes from green to yellow just as you are a few metres from the stop line. What applies?","st":[{"da":"Havde jeg været længere fra stoplinjen og kunnet standse sikkert, skulle jeg have standset.","fa":"اگر از خط ایست دورتر بودم و می‌توانستم بی‌خطر بایستم، باید می‌ایستادم.","ok":1,"eda":"Ja. Gult lys har samme betydning som rødt, når du kan standse uden fare.","efa":"بله. وقتی بتوانید بی‌خطر بایستید، چراغ زرد همان معنای قرمز را دارد.","en":"Had I been further from the stop line and able to stop safely, I should have stopped.","een":"Yes. A yellow light means the same as red when you can stop without danger."},{"da":"Jeg må fortsætte, hvis en standsning nu vil medføre fare.","fa":"اگر ایستادن در این لحظه خطرناک باشد، می‌توانم ادامه دهم.","ok":1,"eda":"Ja. Gult betyder stop, men du skal ikke standse, hvis du er så tæt på, at en standsning vil medføre fare.","efa":"بله. زرد یعنی ایست، ولی اگر آن‌قدر نزدیک باشید که ایستادن خطر بسازد، نباید بایستید.","en":"I may continue if stopping now would cause danger.","een":"Yes. Yellow means stop, but you should not stop if you are so close that stopping would cause danger."},{"da":"Gult lys betyder, at jeg skal sætte farten op for at nå over.","fa":"چراغ زرد یعنی باید سرعتم را زیاد کنم تا رد شوم.","ok":0,"eda":"Nej. Gult betyder stop; du må kun fortsætte, hvis en standsning vil medføre fare.","efa":"خیر. زرد یعنی ایست؛ فقط وقتی می‌توانید ادامه دهید که ایستادن خطرناک باشد.","en":"A yellow light means I should speed up to get across.","een":"No. Yellow means stop; you may only continue if stopping would cause danger."}]},{"id":5234,"img":"newq-art/5234.png","c":"7.14","sda":"Du holder i venstresvingsbanen. Dit signal viser en grøn pil mod venstre. Hvad gælder?","sfa":"در خط گردش به چپ هستید. چراغ شما فلش سبز به چپ نشان می‌دهد. چه قاعده‌ای برقرار است؟","sen":"You are in the left-turn lane. Your signal shows a green arrow to the left. What applies?","st":[{"da":"Jeg må svinge til venstre.","fa":"می‌توانم به چپ بپیچم.","ok":1,"eda":"Ja. Et pilsignal gælder for dem, der skal køre i pilens retning.","efa":"بله. چراغ فلش‌دار برای کسانی است که در جهت فلش می‌روند.","en":"I may turn left.","een":"Yes. An arrow signal applies to those who are going in the direction of the arrow."},{"da":"Den grønne pil betyder, at jeg også må køre ligeud.","fa":"فلش سبز یعنی می‌توانم مستقیم هم بروم.","ok":0,"eda":"Nej. Pilen gælder kun i pilens retning.","efa":"خیر. فلش فقط برای جهت خودش است.","en":"The green arrow means that I may also go straight on.","een":"No. The arrow only applies in its own direction."},{"da":"Jeg skal stadig holde tilbage for gående, der er i feltet på den vej, jeg svinger ind på.","fa":"همچنان باید به عابرانی که روی گذرگاهِ جاده‌ی مقصد هستند راه بدهم.","ok":1,"eda":"Ja. Selv om signalet giver dig lov til at køre, skal du holde tilbage for gående i feltet.","efa":"بله. حتی اگر چراغ اجازه‌ی حرکت بدهد، باید به عابرانِ روی گذرگاه راه بدهید.","en":"I must still give way to pedestrians on the crossing of the road I am turning into.","een":"Yes. Even though the signal lets you drive, you must give way to pedestrians on the crossing."},{"da":"Jeg holder øje med, om der alligevel kommer nogen ind i krydset, fx en, der kører over for rødt.","fa":"حواسم هست که با این حال کسی وارد تقاطع نشود، مثلاً کسی که از چراغ قرمز رد می‌شود.","ok":1,"eda":"Ja. Grønt lys fritager dig ikke for at se dig for.","efa":"بله. چراغ سبز شما را از نگاه کردن به اطراف معاف نمی‌کند.","en":"I watch out in case someone enters the junction anyway, for example someone running a red light.","een":"Yes. A green light does not free you from looking out."}]},{"id":5235,"img":"newq-art/5235.png","c":"7.14","sda":"Du vil svinge til venstre ind i en indkørsel til et hus. Du skal krydse den modkørende vognbane og fortovet. Hvad gælder?","sfa":"می‌خواهید به چپ وارد ورودیِ یک خانه شوید. باید از خط روبه‌رو و پیاده‌رو رد شوید. چه قاعده‌ای برقرار است؟","sen":"You want to turn left into the driveway of a house. You have to cross the oncoming lane and the pavement. What applies?","st":[{"da":"Jeg skal holde tilbage for gående på fortovet.","fa":"باید به عابرانِ پیاده‌رو راه بدهم.","ok":1,"eda":"Ja. Når du kører over et fortov, skal du holde tilbage for gående.","efa":"بله. وقتی از روی پیاده‌رو رد می‌شوید، باید به عابران راه بدهید.","en":"I must give way to pedestrians on the pavement.","een":"Yes. When you drive over a pavement, you must give way to pedestrians."},{"da":"Jeg må først svinge, når det kan ske uden ulempe for de modkørende.","fa":"فقط وقتی می‌توانم بپیچم که برای خودروهای روبه‌رو مزاحمتی نداشته باشد.","ok":1,"eda":"Ja. Reglen for venstresving gælder også, når du kører bort fra kørebanen uden for et kryds.","efa":"بله. قاعده‌ی گردش به چپ وقتی بیرون از تقاطع از سواره‌رو خارج می‌شوید هم برقرار است.","en":"I may only turn when it can be done without inconvenience to oncoming traffic.","een":"Yes. The rule for left turns also applies when you leave the carriageway outside a junction."},{"da":"Jeg giver tegn til venstre i god tid og placerer mig ind mod midten af vejen.","fa":"به موقع راهنمای چپ می‌زنم و به سمت وسط جاده می‌روم.","ok":1,"eda":"Ja. Ved venstresving skal du give tegn og så vidt muligt placere dig ind mod kørebanens midte.","efa":"بله. برای گردش به چپ باید راهنما بزنید و تا جای ممکن به وسط سواره‌رو نزدیک شوید.","en":"I signal left in good time and position myself towards the middle of the road.","een":"Yes. For a left turn you must signal and keep as close as possible to the middle of the carriageway."},{"da":"Jeg kan svinge med det samme, fordi de modkørende kan se mit blinklys.","fa":"می‌توانم فوراً بپیچم، چون خودروهای روبه‌رو راهنمای مرا می‌بینند.","ok":0,"eda":"Nej. Blinklyset giver dig ikke ret til at svinge foran de modkørende.","efa":"خیر. راهنما به شما حق نمی‌دهد جلوی خودروهای روبه‌رو بپیچید.","en":"I can turn straight away because oncoming drivers can see my indicator.","een":"No. The indicator does not give you the right to turn in front of oncoming traffic."}]},{"id":5236,"img":"newq-art/5236.png","c":"7.14","sda":"Du holder stille midt i krydset og venter på at svinge til venstre. Hvordan skal forhjulene stå, mens du venter?","sfa":"وسط تقاطع ایستاده‌اید و منتظر گردش به چپ هستید. هنگام انتظار، چرخ‌های جلو باید چطور باشند؟","sen":"You are standing still in the middle of the junction waiting to turn left. How should the front wheels point while you wait?","st":[{"da":"Drejet til venstre, så jeg hurtigt kan komme af sted.","fa":"به چپ چرخیده، تا زود حرکت کنم.","ok":0,"eda":"Nej. Det sparer næsten ingen tid og er farligt, hvis nogen kører ind bagi.","efa":"خیر. تقریباً وقتی صرفه‌جویی نمی‌شود و اگر کسی از پشت بزند خطرناک است.","en":"Turned to the left, so that I can get away quickly.","een":"No. It saves almost no time and is dangerous if someone runs into the back."},{"da":"Lige frem, så bilen ikke skubbes ud foran de modkørende, hvis nogen kører ind bagi.","fa":"مستقیم، تا اگر کسی از پشت به خودرو زد، به جلوی خودروهای روبه‌رو پرتاب نشود.","ok":1,"eda":"Ja. Står hjulene drejet, kan en påkørsel bagfra skubbe dig ud i den modkørende trafik.","efa":"بله. اگر چرخ‌ها چرخیده باشند، ضربه از پشت ممکن است شما را به میان ترافیک روبه‌رو بفرستد.","en":"Straight ahead, so that the car is not pushed out in front of oncoming traffic if someone runs into the back.","een":"Yes. If the wheels are turned, a collision from behind can push you into the oncoming traffic."},{"da":"Det er ligegyldigt, hvordan hjulene står.","fa":"فرقی نمی‌کند چرخ‌ها چطور باشند.","ok":0,"eda":"Nej. Hjulenes stilling betyder meget, hvis der sker en påkørsel bagfra.","efa":"خیر. اگر از پشت تصادف شود، جهت چرخ‌ها خیلی مهم است.","en":"It does not matter how the wheels point.","een":"No. How the wheels point matters a lot if there is a collision from behind."}]},{"id":5237,"img":"newq-art/5237.png","c":"7.14","sda":"Du kører på en hovedvej og vil svinge til venstre ind ad en sidevej med hajtænder. En bil kommer imod dig. Hvad gælder?","sfa":"در جاده‌ی اصلی هستید و می‌خواهید به چپ وارد فرعی‌ای با خط دندان‌کوسه شوید. خودرویی از روبه‌رو می‌آید. چه قاعده‌ای برقرار است؟","sen":"You are on a main road and want to turn left into a side road with shark teeth. A car is coming towards you. What applies?","st":[{"da":"Jeg skal holde tilbage for den modkørende bil.","fa":"باید به خودروی روبه‌رو راه بدهم.","ok":1,"eda":"Ja. Du må ikke svinge til venstre, før det kan ske uden ulempe for modkørende, heller ikke fra en hovedvej.","efa":"بله. تا وقتی گردش به چپ برای خودروهای روبه‌رو مزاحمت نداشته باشد، نباید بپیچید، حتی از جاده‌ی اصلی.","en":"I must give way to the oncoming car.","een":"Yes. You may not turn left until it can be done without inconvenience to oncoming traffic, not even from a main road."},{"da":"Jeg giver tegn i god tid og placerer mig ind mod midten af vejen.","fa":"به موقع راهنما می‌زنم و به سمت وسط جاده می‌روم.","ok":1,"eda":"Ja. Så kan de bagvedkørende passere til højre for dig, mens du venter.","efa":"بله. این‌طور پشت‌سری‌ها هنگام انتظار شما می‌توانند از سمت راستتان رد شوند.","en":"I signal in good time and position myself towards the middle of the road.","een":"Yes. Then those behind can pass on your right while you wait."},{"da":"Den modkørende skal sætte farten ned, når jeg blinker.","fa":"خودروی روبه‌رو باید وقتی راهنما می‌زنم سرعتش را کم کند.","ok":0,"eda":"Nej. Blinklyset giver dig ikke ret til at svinge foran den modkørende.","efa":"خیر. راهنما به شما حق نمی‌دهد جلوی خودروی روبه‌رو بپیچید.","en":"The oncoming driver must slow down when I signal.","een":"No. The indicator does not give you the right to turn in front of the oncoming driver."},{"da":"Jeg har forkørselsret, fordi jeg kører på hovedvejen.","fa":"حق تقدم با من است، چون در جاده‌ی اصلی هستم.","ok":0,"eda":"Nej. Hovedvejen giver forkørselsret over for trafikken fra sidevejene, ikke over for de modkørende.","efa":"خیر. جاده‌ی اصلی در برابر ترافیک فرعی‌ها حق تقدم می‌دهد، نه در برابر خودروهای روبه‌رو.","en":"I have the right of way because I am on the main road.","een":"No. The main road gives the right of way over traffic from the side roads, not over oncoming traffic."}]},{"id":5238,"img":"newq-art/5238.png","c":"7.14","sda":"Du kommer ad en sidevej med hajtænder og vil svinge til venstre ind på hovedvejen. Hvad gælder?","sfa":"از فرعی‌ای با خط دندان‌کوسه می‌آیید و می‌خواهید به چپ وارد جاده‌ی اصلی شوید. چه قاعده‌ای برقرار است؟","sen":"You are coming along a side road with shark teeth and want to turn left onto the main road. What applies?","st":[{"da":"Jeg skal holde tilbage for trafikken på hovedvejen fra både venstre og højre.","fa":"باید به ترافیک جاده‌ی اصلی، هم از چپ و هم از راست، راه بدهم.","ok":1,"eda":"Ja. Hajtænderne giver ubetinget vigepligt for den kørende færdsel fra begge sider.","efa":"بله. خط دندان‌کوسه حق تقدم مطلق را به ترافیک هر دو طرف می‌دهد.","en":"I must give way to the traffic on the main road from both left and right.","een":"Yes. The shark teeth give an unconditional duty to give way to traffic from both sides."},{"da":"Højrevigepligten gælder, fordi jeg svinger til venstre.","fa":"چون به چپ می‌پیچم، قاعده‌ی دست راست برقرار است.","ok":0,"eda":"Nej. Hajtænderne ophæver højrevigepligten; du har ubetinget vigepligt.","efa":"خیر. خط دندان‌کوسه قاعده‌ی دست راست را کنار می‌گذارد؛ شما باید بی‌قید و شرط راه بدهید.","en":"The right-hand rule applies because I am turning left.","een":"No. The shark teeth cancel the right-hand rule; you have an unconditional duty to give way."},{"da":"Efter svinget skal jeg være i højre side af hovedvejen.","fa":"بعد از پیچیدن باید در سمت راست جاده‌ی اصلی باشم.","ok":1,"eda":"Ja. Et sving skal ende i højre side af den vej, du svinger ind på.","efa":"بله. پیچیدن باید در سمت راستِ جاده‌ای که واردش می‌شوید تمام شود.","en":"After the turn I must be on the right-hand side of the main road.","een":"Yes. A turn must end on the right-hand side of the road you turn into."},{"da":"Jeg må køre ud til midten af hovedvejen og vente der, når der kun kommer biler fra højre.","fa":"وقتی فقط از راست خودرو می‌آید، می‌توانم تا وسط جاده‌ی اصلی بروم و آنجا صبر کنم.","ok":0,"eda":"Nej. Du må først køre ud, når det kan ske uden fare eller ulempe for trafikken fra begge sider.","efa":"خیر. فقط وقتی می‌توانید وارد شوید که برای ترافیک هر دو طرف خطر یا مزاحمتی نداشته باشد.","en":"I may drive out to the middle of the main road and wait there when cars are only coming from the right.","een":"No. You may only drive out when it can be done without danger or inconvenience to traffic from both sides."}]},{"id":5239,"img":"newq-art/5239.png","c":"7.13","sda":"Du holder for rødt og vil svinge til højre. Foran dig ved stoplinjen holder to cyklister, som skal ligeud. Nu skifter lyset til grønt. Hvordan forholder du dig?","sfa":"پشت چراغ قرمز هستید و می‌خواهید به راست بپیچید. جلوی شما کنار خط ایست دو دوچرخه‌سوار ایستاده‌اند که مستقیم می‌روند. حالا چراغ سبز می‌شود. چه می‌کنید؟","sen":"You are stopped at a red light and want to turn right. In front of you at the stop line two cyclists are waiting who are going straight on. Now the light changes to green. What do you do?","st":[{"da":"Jeg ser over højre skulder, før jeg svinger, fordi der kan komme flere cyklister bagfra.","fa":"پیش از پیچیدن از روی شانه‌ی راست نگاه می‌کنم، چون ممکن است دوچرخه‌سوارهای دیگری از پشت بیایند.","ok":1,"eda":"Ja. Cyklister kan være i den blinde vinkel ved siden af bilen.","efa":"بله. دوچرخه‌سوار ممکن است در نقطه‌ی کورِ کنار خودرو باشد.","en":"I look over my right shoulder before I turn, because more cyclists may come from behind.","een":"Yes. Cyclists may be in the blind spot beside the car."},{"da":"Jeg lader cyklisterne køre over krydset, før jeg svinger.","fa":"می‌گذارم دوچرخه‌سوارها از تقاطع رد شوند و بعد می‌پیچم.","ok":1,"eda":"Ja. Når du svinger til højre, må du ikke være til ulempe for cyklister, der kører ligeud.","efa":"بله. هنگام گردش به راست نباید برای دوچرخه‌سوارانی که مستقیم می‌روند مزاحمت ایجاد کنید.","en":"I let the cyclists ride across the junction before I turn.","een":"Yes. When you turn right, you must not inconvenience cyclists going straight on."},{"da":"Jeg svinger hurtigt, før cyklisterne kommer i gang.","fa":"پیش از راه افتادن دوچرخه‌سوارها سریع می‌پیچم.","ok":0,"eda":"Nej. Det kan føre til en farlig ulykke, hvor bilen svinger ind over cyklisterne.","efa":"خیر. ممکن است به تصادفی خطرناک برسد که خودرو روی دوچرخه‌سوارها می‌پیچد.","en":"I turn quickly before the cyclists get going.","een":"No. It can lead to a dangerous accident where the car turns across the cyclists."},{"da":"Cyklisterne skal vente, fordi bilerne kører først ved grønt.","fa":"دوچرخه‌سوارها باید صبر کنند، چون با چراغ سبز اول خودروها می‌روند.","ok":0,"eda":"Nej. Grønt gælder alle i retningen, og cyklister, der kører ligeud, skal ikke vente på højresvingende.","efa":"خیر. سبز برای همه‌ی آن جهت است و دوچرخه‌سوارانی که مستقیم می‌روند لازم نیست منتظر گردش به راستی‌ها بمانند.","en":"The cyclists must wait because cars go first on green.","een":"No. Green applies to everyone in that direction, and cyclists going straight on do not have to wait for those turning right."}]},{"id":5240,"img":"newq-art/5240.png","c":"7.13","sda":"Du vil svinge til højre. Lige efter hjørnet er der et fodgængerfelt på den vej, du skal ind på, og to fodgængere er på vej ud på det. Hvordan forholder du dig?","sfa":"می‌خواهید به راست بپیچید. درست بعد از پیچ، روی جاده‌ای که واردش می‌شوید گذرگاه عابر پیاده هست و دو عابر می‌خواهند واردش شوند. چه می‌کنید؟","sen":"You want to turn right. Just after the corner there is a pedestrian crossing on the road you are turning into, and two pedestrians are about to step onto it. What do you do?","st":[{"da":"Fodgængerne skal vente, fordi jeg allerede er i gang med at svinge.","fa":"عابران باید صبر کنند، چون من در حال پیچیدنم.","ok":0,"eda":"Nej. Gående, der er på vej ud i feltet, skal kunne gå over uden fare.","efa":"خیر. عابری که در حال وارد شدن به گذرگاه است باید بتواند بی‌خطر رد شود.","en":"The pedestrians must wait because I am already turning.","een":"No. Pedestrians about to step onto the crossing must be able to cross without danger."},{"da":"Jeg standser og lader fodgængerne gå over, før jeg kører videre.","fa":"می‌ایستم و می‌گذارم عابران رد شوند و بعد ادامه می‌دهم.","ok":1,"eda":"Ja. Om nødvendigt skal du standse for at lade de gående passere.","efa":"بله. در صورت لزوم باید بایستید تا عابران رد شوند.","en":"I stop and let the pedestrians cross before I drive on.","een":"Yes. If necessary, you must stop to let the pedestrians cross."},{"da":"Jeg standser på fodgængerfeltet og venter, til de er gået forbi foran bilen.","fa":"روی گذرگاه می‌ایستم و صبر می‌کنم تا از جلوی خودرو رد شوند.","ok":0,"eda":"Nej. Du skal så vidt muligt undgå at standse på fodgængerfeltet.","efa":"خیر. باید تا جای ممکن از ایستادن روی گذرگاه عابر پیاده پرهیز کنید.","en":"I stop on the pedestrian crossing and wait until they have walked past in front of the car.","een":"No. You must as far as possible avoid stopping on the pedestrian crossing."},{"da":"Jeg svinger med lav fart og er klar til at standse før feltet.","fa":"با سرعت کم می‌پیچم و آماده‌ام پیش از گذرگاه بایستم.","ok":1,"eda":"Ja. Du skal tilpasse farten, så der ikke opstår fare for gående, der er på vej ud i feltet.","efa":"بله. باید سرعت را طوری تنظیم کنید که برای عابرانی که می‌خواهند وارد گذرگاه شوند خطری پیش نیاید.","en":"I turn at a low speed and am ready to stop before the crossing.","een":"Yes. You must adjust your speed so that there is no danger to pedestrians about to step onto the crossing."}]},{"id":5241,"img":"newq-art/5241.png","c":"7.13","sda":"Du vil svinge til højre. Dit signal viser en grøn pil mod højre. På den vej, du svinger ind på, går en ældre mand stadig over fodgængerfeltet. Hvad gælder?","sfa":"می‌خواهید به راست بپیچید. چراغ شما فلش سبز به راست نشان می‌دهد. روی جاده‌ای که واردش می‌شوید، مردی مسن هنوز در حال عبور از گذرگاه است. چه قاعده‌ای برقرار است؟","sen":"You want to turn right. Your signal shows a green arrow to the right. On the road you are turning into, an elderly man is still walking across the pedestrian crossing. What applies?","st":[{"da":"Jeg må svinge i pilens retning, men skal holde tilbage for manden i feltet.","fa":"می‌توانم در جهت فلش بپیچم، ولی باید به مردِ روی گذرگاه راه بدهم.","ok":1,"eda":"Ja. Selv om signalet giver dig lov til at køre, skal du holde tilbage for gående, der er i feltet.","efa":"بله. حتی اگر چراغ اجازه‌ی حرکت بدهد، باید به عابرانِ روی گذرگاه راه بدهید.","en":"I may turn in the direction of the arrow, but must give way to the man on the crossing.","een":"Yes. Even though the signal lets you drive, you must give way to pedestrians on the crossing."},{"da":"Den grønne pil giver mig ret til at køre, selv om manden er i feltet.","fa":"فلش سبز به من حق حرکت می‌دهد، حتی اگر آن مرد روی گذرگاه باشد.","ok":0,"eda":"Nej. Gående i feltet skal kunne gå færdig over.","efa":"خیر. عابرانِ روی گذرگاه باید بتوانند عبورشان را تمام کنند.","en":"The green arrow gives me the right to drive even though the man is on the crossing.","een":"No. Pedestrians on the crossing must be able to finish crossing."},{"da":"Jeg svinger med lav fart og standser, hvis det er nødvendigt.","fa":"با سرعت کم می‌پیچم و اگر لازم باشد می‌ایستم.","ok":1,"eda":"Ja. Efter et sving i krydset skal du passere feltet med passende lav fart og om nødvendigt standse.","efa":"بله. بعد از پیچیدن در تقاطع باید با سرعت مناسبِ کم از گذرگاه بگذرید و در صورت لزوم بایستید.","en":"I turn at a low speed and stop if necessary.","een":"Yes. After turning in the junction you must pass the crossing at a suitably low speed and stop if necessary."}]},{"id":5242,"img":"newq-art/5242.png","c":"7.13","sda":"Du vil svinge til højre ind på en vej, hvor der midt på vejen lige efter krydset er et helleanlæg. Hvordan kører du?","sfa":"می‌خواهید به راست وارد جاده‌ای شوید که درست بعد از تقاطع، وسطش یک جزیره‌ی میانی (helle) دارد. چطور می‌رانید؟","sen":"You want to turn right into a road that has a traffic island in the middle just after the junction. How do you drive?","st":[{"da":"Helleanlægget er kun for fodgængere, så jeg må køre hen over det.","fa":"این جزیره فقط برای عابران است، پس می‌توانم از رویش رد شوم.","ok":0,"eda":"Nej. Du skal køre til højre for helleanlægget, ikke over det.","efa":"خیر. باید از سمت راست جزیره بگذرید، نه از رویش.","en":"The island is only for pedestrians, so I may drive over it.","een":"No. You must drive to the right of the island, not over it."},{"da":"Jeg kører til venstre for helleanlægget, fordi svinget så bliver blødere.","fa":"از سمت چپ جزیره می‌روم، چون پیچ نرم‌تر می‌شود.","ok":0,"eda":"Nej. Venstre om helleanlægget er kun tilladt, hvis afmærkningen viser det, eller hvis vejen er ensrettet.","efa":"خیر. عبور از چپ جزیره فقط وقتی مجاز است که علامت‌ها نشان دهند یا جاده یک‌طرفه باشد.","en":"I drive to the left of the island because the turn is then smoother.","een":"No. Passing the island on the left is only allowed if the markings show it or if the road is one-way."},{"da":"Jeg kører til højre for helleanlægget.","fa":"از سمت راست جزیره‌ی میانی می‌روم.","ok":1,"eda":"Ja. Kørende skal holde til højre for helleanlæg på kørebanen.","efa":"بله. رانندگان باید از سمت راستِ جزیره‌های روی سواره‌رو بگذرند.","en":"I drive to the right of the traffic island.","een":"Yes. Drivers must keep to the right of traffic islands on the carriageway."},{"da":"Jeg kan vælge den side af helleanlægget, der passer mig bedst.","fa":"هر طرف جزیره را که برایم راحت‌تر است انتخاب می‌کنم.","ok":0,"eda":"Nej. Du skal holde til højre for helleanlægget.","efa":"خیر. باید از سمت راست جزیره بگذرید.","en":"I can choose whichever side of the island suits me best.","een":"No. You must keep to the right of the island."}]},{"id":5243,"img":"newq-art/5243.png","c":"7.11","sda":"Ved krydset står en vigepligtstavle, og der er hajtænder. Lyssignalet i krydset virker, og du har grønt. Hvad gælder?","sfa":"کنار تقاطع تابلوی حق تقدم و خط دندان‌کوسه هست. چراغ راهنمایی تقاطع کار می‌کند و چراغ شما سبز است. چه قاعده‌ای برقرار است؟","sen":"At the junction there is a give-way sign and there are shark teeth. The traffic lights in the junction are working, and you have green. What applies?","st":[{"da":"Når der både er signal og vigepligtstavle, gælder højrevigepligten.","fa":"وقتی هم چراغ هست و هم تابلوی حق تقدم، قاعده‌ی دست راست برقرار است.","ok":0,"eda":"Nej. Signalet regulerer krydset; højrevigepligten gælder ikke her.","efa":"خیر. چراغ تقاطع را تنظیم می‌کند؛ قاعده‌ی دست راست این‌جا برقرار نیست.","en":"When there are both lights and a give-way sign, the right-hand rule applies.","een":"No. The signal controls the junction; the right-hand rule does not apply here."},{"da":"Vigepligtstavlen gælder før lyssignalet, så jeg skal holde tilbage for alle.","fa":"تابلوی حق تقدم بر چراغ مقدم است، پس باید به همه راه بدهم.","ok":0,"eda":"Nej. Når signalet virker, er det signalet, der gælder.","efa":"خیر. وقتی چراغ کار می‌کند، چراغ معتبر است.","en":"The give-way sign comes before the traffic lights, so I must give way to everyone.","een":"No. When the signal works, it is the signal that applies."},{"da":"Jeg følger lyssignalet, så jeg må køre ved grønt.","fa":"از چراغ پیروی می‌کنم، پس با سبز می‌توانم بروم.","ok":1,"eda":"Ja. Uanset afmærkning med ubetinget vigepligt skal du rette dig efter signalanlægget i krydset.","efa":"بله. با وجود علامت‌های حق تقدم، باید از چراغ راهنمایی تقاطع پیروی کنید.","en":"I follow the traffic lights, so I may drive on green.","een":"Yes. Whatever markings give the duty to give way, you must follow the traffic lights in the junction."},{"da":"Jeg skal standse helt ved hajtænderne, før jeg kører over for grønt.","fa":"باید پیش از رد شدن با چراغ سبز، کنار خط دندان‌کوسه کامل بایستم.","ok":0,"eda":"Nej. Hajtænderne og tavlen gælder først, hvis signalet er slukket eller blinker gult.","efa":"خیر. خط دندان‌کوسه و تابلو فقط وقتی معتبرند که چراغ خاموش باشد یا زرد چشمک بزند.","en":"I must come to a full stop at the shark teeth before I drive on green.","een":"No. The shark teeth and the sign only apply if the signal is off or flashing yellow."}]},{"id":5244,"img":"newq-art/5244.png","c":"7.11","sda":"Du nærmer dig et lyskryds. Den lave sol skinner lige ind i øjnene, og du kan dårligt se, hvad signalet viser. Hvordan forholder du dig?","sfa":"به تقاطعی چراغ‌دار نزدیک می‌شوید. خورشیدِ پایین مستقیم به چشمتان می‌تابد و به‌سختی می‌بینید چراغ چه نشان می‌دهد. چه می‌کنید؟","sen":"You are approaching a junction with traffic lights. The low sun is shining straight into your eyes, and you can hardly see what the signal shows. What do you do?","st":[{"da":"Jeg slår solskærmen ned og bruger solbriller, hvis jeg har dem.","fa":"آفتاب‌گیر را پایین می‌آورم و اگر عینک آفتابی دارم، می‌زنم.","ok":1,"eda":"Ja. Det mindsker blændingen.","efa":"بله. این کار خیرگی را کم می‌کند.","en":"I lower the sun visor and wear sunglasses if I have them.","een":"Yes. That reduces the glare."},{"da":"Jeg sænker farten, så jeg kan standse, hvis signalet viser rødt.","fa":"سرعت را کم می‌کنم تا اگر چراغ قرمز بود، بتوانم بایستم.","ok":1,"eda":"Ja. Ved risiko for blænding skal du holde en passende lav hastighed.","efa":"بله. وقتی خطر خیره شدن هست، باید سرعت مناسبِ کمی داشته باشید.","en":"I slow down so that I can stop if the signal shows red.","een":"Yes. When there is a risk of being dazzled, you must keep a suitably low speed."},{"da":"Jeg fortsætter med samme fart, fordi signalet nok er grønt.","fa":"با همان سرعت ادامه می‌دهم، چون چراغ احتمالاً سبز است.","ok":0,"eda":"Nej. Du må ikke gætte; kan du ikke se signalet, skal du være klar til at standse.","efa":"خیر. نباید حدس بزنید؛ اگر چراغ را نمی‌بینید، باید آماده‌ی ایستادن باشید.","en":"I carry on at the same speed because the signal is probably green.","een":"No. You must not guess; if you cannot see the signal, you must be ready to stop."},{"da":"Jeg holder også øje med de andre trafikanter, men kører først, når jeg er sikker på signalet.","fa":"به بقیه‌ی کاربران راه هم نگاه می‌کنم، ولی فقط وقتی حرکت می‌کنم که از رنگ چراغ مطمئن باشم.","ok":1,"eda":"Ja. Andre trafikanter kan give et fingerpeg, men det er signalet, du skal følge.","efa":"بله. دیگران می‌توانند سرنخی بدهند، ولی باید از چراغ پیروی کنید.","en":"I also watch the other road users, but only drive on when I am sure of the signal.","een":"Yes. Other road users can give a clue, but it is the signal you must follow."}]},{"id":5245,"img":"newq-art/5245.png","c":"7.11","sda":"Du nærmer dig et kryds uden tavler og afmærkning. Der holder parkerede varevogne helt hen til hjørnet, så du ikke kan se ind på sidevejen til højre. Hvordan forholder du dig?","sfa":"به تقاطعی بدون تابلو و خط‌کشی نزدیک می‌شوید. ون‌های پارک‌شده تا خود نبش ایستاده‌اند و نمی‌توانید فرعی سمت راست را ببینید. چه می‌کنید؟","sen":"You are approaching a junction without signs or markings. Parked vans stand right up to the corner, so you cannot see into the side road on the right. What do you do?","st":[{"da":"Varevognene holder ulovligt tæt på hjørnet, så jeg har ikke vigepligt.","fa":"ون‌ها غیرقانونی نزدیک نبش پارک کرده‌اند، پس من لازم نیست راه بدهم.","ok":0,"eda":"Nej. Parkeringen ændrer ikke på vigepligten; højrevigepligten gælder stadig.","efa":"خیر. این پارک چیزی را در حق تقدم عوض نمی‌کند؛ قاعده‌ی دست راست همچنان برقرار است.","en":"The vans are parked illegally close to the corner, so I do not have to give way.","een":"No. The parking does not change who gives way; the right-hand rule still applies."},{"da":"Jeg er også opmærksom på cyklister og fodgængere, der kan komme frem bag varevognene.","fa":"حواسم به دوچرخه‌سوارها و عابرانی هم هست که ممکن است از پشت ون‌ها بیرون بیایند.","ok":1,"eda":"Ja. Varevognene skjuler alle, der kommer fra højre.","efa":"بله. ون‌ها همه‌ی کسانی را که از راست می‌آیند پنهان می‌کنند.","en":"I also watch out for cyclists and pedestrians who may appear from behind the vans.","een":"Yes. The vans hide everyone coming from the right."},{"da":"Jeg sænker farten så meget, at jeg kan holde tilbage for trafik fra højre.","fa":"سرعت را آن‌قدر کم می‌کنم که بتوانم به ترافیک سمت راست راه بدهم.","ok":1,"eda":"Ja. Højrevigepligten gælder, og ved vejkryds med begrænset oversigt skal du holde en passende lav hastighed.","efa":"بله. قاعده‌ی دست راست برقرار است و در تقاطعِ کم‌دید باید سرعت مناسبِ کمی داشته باشید.","en":"I slow down enough to be able to give way to traffic from the right.","een":"Yes. The right-hand rule applies, and at junctions where the view is limited you must keep a suitably low speed."},{"da":"Jeg kører igennem med samme fart, fordi jeg ikke kan se nogen.","fa":"با همان سرعت رد می‌شوم، چون کسی را نمی‌بینم.","ok":0,"eda":"Nej. At du ikke kan se nogen, betyder ikke, at der ikke kommer nogen.","efa":"خیر. این‌که کسی را نمی‌بینید، به این معنا نیست که کسی نمی‌آید.","en":"I drive through at the same speed because I cannot see anyone.","een":"No. Not being able to see anyone does not mean that no one is coming."}]},{"id":5246,"img":"newq-art/5246.png","c":"7.11","sda":"Du kører bag en lastbil mod et lyskryds. Lastbilen skjuler signalet for dig. Hvordan forholder du dig?","sfa":"پشت کامیونی به سمت تقاطعی چراغ‌دار می‌روید. کامیون چراغ را از دید شما پنهان کرده است. چه می‌کنید؟","sen":"You are driving behind a lorry towards a junction with traffic lights. The lorry hides the signal from you. What do you do?","st":[{"da":"Jeg følger tæt efter lastbilen, så jeg også når over, hvis den gør.","fa":"از نزدیک دنبال کامیون می‌روم تا اگر او رد شد، من هم برسم.","ok":0,"eda":"Nej. Det er signalet, du skal følge, ikke lastbilen.","efa":"خیر. باید از چراغ پیروی کنید، نه از کامیون.","en":"I follow the lorry closely so that I get across too if it does.","een":"No. It is the signal you must follow, not the lorry."},{"da":"Jeg holder større afstand, så jeg kan se mere af krydset og signalerne.","fa":"فاصله را بیشتر می‌کنم تا بیشتر از تقاطع و چراغ‌ها را ببینم.","ok":1,"eda":"Ja. Med større afstand ser du ud forbi lastbilen.","efa":"بله. با فاصله‌ی بیشتر می‌توانید کنار کامیون را ببینید.","en":"I keep a greater distance so that I can see more of the junction and the signals.","een":"Yes. With a greater distance you can see past the lorry."},{"da":"Jeg er klar til at standse, hvis signalet skifter, når lastbilen er kørt over.","fa":"آماده‌ام اگر بعد از رد شدن کامیون چراغ عوض شد، بایستم.","ok":1,"eda":"Ja. Signalet kan skifte til gult eller rødt, lige når lastbilen har passeret.","efa":"بله. چراغ ممکن است درست بعد از رد شدن کامیون زرد یا قرمز شود.","en":"I am ready to stop if the signal changes once the lorry has crossed.","een":"Yes. The signal can change to yellow or red just as the lorry has passed."},{"da":"Jeg kigger efter et andet signal i krydset, fx i den anden side af vejen.","fa":"دنبال چراغ دیگری در تقاطع می‌گردم، مثلاً آن طرف جاده.","ok":1,"eda":"Ja. I mange kryds er der flere signaler, så du kan se et af dem.","efa":"بله. بسیاری از تقاطع‌ها چند چراغ دارند و می‌توانید یکی را ببینید.","en":"I look for another signal at the junction, for example on the other side of the road.","een":"Yes. Many junctions have several signals, so you can see one of them."}]},{"id":5247,"img":"newq-art/5247.png","c":"7.15","sda":"Du er ved at køre ud af rundkørslen. I udkørslen er der et fodgængerfelt, og en mand med en hund er på vej ud på det. Hvordan forholder du dig?","sfa":"در حال خارج شدن از میدان هستید. در خروجی گذرگاه عابر پیاده هست و مردی با سگش می‌خواهد واردش شود. چه می‌کنید؟","sen":"You are about to leave the roundabout. In the exit there is a pedestrian crossing, and a man with a dog is about to step onto it. What do you do?","st":[{"da":"Manden skal vente, fordi trafikken i rundkørslen har forkørselsret.","fa":"آن مرد باید صبر کند، چون ترافیک داخل میدان حق تقدم دارد.","ok":0,"eda":"Nej. Forkørselsretten i rundkørslen gælder over for dem, der kører ind, ikke over for gående i et fodgængerfelt.","efa":"خیر. حق تقدم داخل میدان در برابر کسانی است که وارد می‌شوند، نه در برابر عابرانِ روی گذرگاه.","en":"The man must wait because the traffic in the roundabout has the right of way.","een":"No. The right of way in the roundabout is over those driving in, not over pedestrians on a crossing."},{"da":"Jeg giver tegn til højre, før jeg kører ud af rundkørslen.","fa":"پیش از خروج از میدان راهنمای راست می‌زنم.","ok":1,"eda":"Ja. Du skal give tegn, når du forlader rundkørslen.","efa":"بله. هنگام خروج از میدان باید راهنما بزنید.","en":"I signal right before I leave the roundabout.","een":"Yes. You must signal when you leave the roundabout."},{"da":"Jeg sænker farten og lader manden gå over.","fa":"سرعت را کم می‌کنم و می‌گذارم آن مرد رد شود.","ok":1,"eda":"Ja. Du skal afpasse farten efter gående, der er på vej ud i feltet, og om nødvendigt standse.","efa":"بله. باید سرعت را با عابری که در حال وارد شدن به گذرگاه است تنظیم کنید و در صورت لزوم بایستید.","en":"I slow down and let the man cross.","een":"Yes. You must adjust your speed to pedestrians about to step onto the crossing and stop if necessary."},{"da":"Jeg kører ud uden at standse, fordi bilen bag mig i rundkørslen ellers må bremse.","fa":"بدون ایستادن بیرون می‌روم، چون وگرنه خودروی پشت سرم در میدان باید ترمز کند.","ok":0,"eda":"Nej. Den gående på vej ud i feltet skal kunne gå over uden fare.","efa":"خیر. عابری که در حال وارد شدن به گذرگاه است باید بتواند بی‌خطر رد شود.","en":"I drive out without stopping, because otherwise the car behind me in the roundabout has to brake.","een":"No. The pedestrian about to step onto the crossing must be able to cross without danger."}]},{"id":5248,"img":"newq-art/5248.png","c":"7.15","sda":"Du vil køre ind i rundkørslen. Der er hajtænder ved indkørslen. En cyklist kommer kørende i yderkanten af rundkørslen fra venstre. Hvad gælder?","sfa":"می‌خواهید وارد میدان شوید. کنار ورودی خط دندان‌کوسه هست. دوچرخه‌سواری در لبه‌ی بیرونیِ میدان از چپ می‌آید. چه قاعده‌ای برقرار است؟","sen":"You want to drive into the roundabout. There are shark teeth at the entry. A cyclist is riding along the outer edge of the roundabout from the left. What applies?","st":[{"da":"Jeg skal kun holde tilbage for biler i rundkørslen, ikke for cyklister.","fa":"فقط باید به خودروهای داخل میدان راه بدهم، نه به دوچرخه‌سوارها.","ok":0,"eda":"Nej. Vigepligten gælder al kørende færdsel.","efa":"خیر. این وظیفه شامل همه‌ی ترافیک است.","en":"I only have to give way to cars in the roundabout, not to cyclists.","een":"No. The duty to give way covers all traffic."},{"da":"Cyklisten skal holde tilbage, fordi jeg kommer fra højre.","fa":"دوچرخه‌سوار باید راه بدهد، چون من از راست می‌آیم.","ok":0,"eda":"Nej. Hajtænderne ophæver højrevigepligten.","efa":"خیر. خط دندان‌کوسه قاعده‌ی دست راست را کنار می‌گذارد.","en":"The cyclist must give way because I am coming from the right.","een":"No. The shark teeth cancel the right-hand rule."},{"da":"Jeg skal holde tilbage for cyklisten.","fa":"باید به دوچرخه‌سوار راه بدهم.","ok":1,"eda":"Ja. Hajtænderne giver ubetinget vigepligt for al kørende færdsel i rundkørslen, også cyklister.","efa":"بله. خط دندان‌کوسه یعنی باید بی‌قید و شرط به همه‌ی ترافیک داخل میدان راه بدهید، از جمله دوچرخه‌سوارها.","en":"I must give way to the cyclist.","een":"Yes. The shark teeth give an unconditional duty to give way to all traffic in the roundabout, also cyclists."},{"da":"Jeg må køre ind foran cyklisten, når jeg skal ud ved første udkørsel.","fa":"وقتی از خروجی اول بیرون می‌روم، می‌توانم جلوی دوچرخه‌سوار وارد شوم.","ok":0,"eda":"Nej. Vigepligten gælder, uanset hvor du skal ud.","efa":"خیر. این وظیفه، از هر خروجی هم که بیرون بروید، برقرار است.","en":"I may drive in in front of the cyclist when I am leaving at the first exit.","een":"No. The duty to give way applies whichever exit you are taking."}]},{"id":5249,"img":"newq-art/5249.png","c":"4.5","sda":"Du vil svinge til venstre. En motorcykel kommer imod dig. Hvad skal du være opmærksom på?","sfa":"می‌خواهید به چپ بپیچید. موتورسیکلتی از روبه‌رو می‌آید. به چه چیزی باید توجه کنید؟","sen":"You want to turn left. A motorcycle is coming towards you. What should you be aware of?","st":[{"da":"Er jeg i tvivl, venter jeg, til motorcyklen er kørt forbi.","fa":"اگر شک دارم، صبر می‌کنم تا موتورسیکلت رد شود.","ok":1,"eda":"Ja. Du må først svinge, når det kan ske uden ulempe for de modkørende.","efa":"بله. فقط وقتی می‌توانید بپیچید که برای خودروهای روبه‌رو مزاحمتی نداشته باشد.","en":"If I am in doubt, I wait until the motorcycle has gone by.","een":"Yes. You may only turn when it can be done without inconvenience to oncoming traffic."},{"da":"Det kan være svært at bedømme, hvor hurtigt motorcyklen kører, og hvor langt væk den er.","fa":"ممکن است تخمین سرعت و فاصله‌ی موتورسیکلت سخت باشد.","ok":1,"eda":"Ja. En motorcykel er smal, så den kan virke længere væk og langsommere, end den er.","efa":"بله. موتورسیکلت باریک است و ممکن است دورتر و آهسته‌تر از واقع به نظر برسد.","en":"It can be hard to judge how fast the motorcycle is going and how far away it is.","een":"Yes. A motorcycle is narrow, so it may seem further away and slower than it is."},{"da":"En motorcykel kan altid standse hurtigere end en bil, så jeg kan godt svinge.","fa":"موتورسیکلت همیشه زودتر از خودرو می‌ایستد، پس می‌توانم بپیچم.","ok":0,"eda":"Nej. Du må ikke regne med, at motorcyklisten kan nå at bremse; en hård opbremsning er også farlig for ham.","efa":"خیر. نباید فرض کنید موتورسوار به موقع ترمز می‌کند؛ ترمز شدید برای خودش هم خطرناک است.","en":"A motorcycle can always stop faster than a car, so I can go ahead and turn.","een":"No. You must not count on the motorcyclist being able to brake in time; hard braking is dangerous for him too."}]},{"id":5250,"img":"newq-art/5250.png","c":"6.2","sda":"Hvad gælder om at give tegn med blinklyset?","sfa":"درباره‌ی علامت دادن با راهنما چه درست است؟","sen":"What applies to signalling with the indicator?","st":[{"da":"Blinklyset skal slukkes, når manøvren er færdig.","fa":"وقتی مانور تمام شد، راهنما باید خاموش شود.","ok":1,"eda":"Ja. Tegnet skal ophøre senest, når manøvren er afsluttet.","efa":"بله. علامت باید حداکثر تا پایان مانور قطع شود.","en":"The indicator must be switched off when the manoeuvre is finished.","een":"Yes. The signal must stop at the latest when the manoeuvre is finished."},{"da":"Tegnet skal være tydeligt, så andre ikke er i tvivl om, hvad jeg vil.","fa":"علامت باید روشن باشد تا دیگران درباره‌ی قصد من شک نکنند.","ok":1,"eda":"Ja. Tegn skal gives tydeligt og utvetydigt.","efa":"بله. علامت باید روشن و بی‌ابهام باشد.","en":"The signal must be clear so that others are in no doubt about what I am going to do.","een":"Yes. Signals must be given clearly and unambiguously."},{"da":"Jeg giver tegn i god tid før manøvren.","fa":"به موقع پیش از مانور راهنما می‌زنم.","ok":1,"eda":"Ja. Tegn skal gives i god tid før den påtænkte manøvre.","efa":"بله. علامت باید به موقع پیش از مانورِ موردنظر داده شود.","en":"I signal in good time before the manoeuvre.","een":"Yes. Signals must be given in good time before the intended manoeuvre."},{"da":"Jeg giver tegn, før jeg kører ud fra kantstenen, og før jeg svinger.","fa":"پیش از حرکت از کنار جدول و پیش از پیچیدن راهنما می‌زنم.","ok":1,"eda":"Ja. Du skal give tegn før igangsætning fra kanten af vejen og før vending og svingning.","efa":"بله. پیش از حرکت از کنار جاده و پیش از دور زدن و پیچیدن باید علامت بدهید.","en":"I signal before I pull away from the kerb and before I turn.","een":"Yes. You must signal before pulling away from the edge of the road and before turning round and turning."}]},{"id":5251,"img":"newq-art/5251.png","c":"7.18","sda":"Du kører op ad en lang bakke, hvor der er et krybespor i højre side. Du vil standse i krybesporet og tage et billede af udsigten. Hvad gælder?","sfa":"از سربالایی طولانی‌ای بالا می‌روید که در سمت راستش یک خط کُندرو هست. می‌خواهید در خط کُندرو بایستید و از منظره عکس بگیرید. چه قاعده‌ای برقرار است؟","sen":"You are driving up a long hill with a crawler lane on the right. You want to stop in the crawler lane and take a photo of the view. What applies?","st":[{"da":"Krybesporet skal bruges af køretøjer, der kører langsommere end den øvrige trafik, fx en tung lastbil op ad bakken.","fa":"خط کُندرو را باید وسایلی استفاده کنند که کندتر از بقیه‌ی ترافیک می‌روند، مثلاً کامیون سنگین در سربالایی.","ok":1,"eda":"Ja. Tavlen angiver en særlig vognbane, som skal bruges af køretøjer, der kører med lavere hastighed.","efa":"بله. این تابلو خط ویژه‌ای را نشان می‌دهد که وسایل کندتر باید از آن استفاده کنند.","en":"The crawler lane must be used by vehicles going slower than the other traffic, for example a heavy lorry up the hill.","een":"Yes. The sign marks a special lane that must be used by vehicles going at a lower speed."},{"da":"Krybesporet er en nødholdeplads, hvor biler med motorstop kan holde.","fa":"خط کُندرو جای توقف اضطراری برای خودروهای خراب است.","ok":0,"eda":"Nej. En nødholdeplads har sin egen tavle; krybesporet er en vognbane for langsom trafik.","efa":"خیر. جای توقف اضطراری تابلوی خودش را دارد؛ خط کُندرو یک خط عبور برای ترافیک کند است.","en":"The crawler lane is an emergency lay-by where cars with engine trouble may stand.","een":"No. An emergency lay-by has its own sign; the crawler lane is a lane for slow traffic."},{"da":"Jeg må hverken standse eller parkere i krybesporet.","fa":"در خط کُندرو نه می‌توانم توقف کنم و نه پارک.","ok":1,"eda":"Ja. Standsning og parkering er forbudt i krybespor.","efa":"بله. توقف و پارک در خط کُندرو ممنوع است.","en":"I may neither stop nor park in the crawler lane.","een":"Yes. Stopping and parking are forbidden in a crawler lane."},{"da":"Jeg må godt standse kort i krybesporet, når jeg tænder havariblinket.","fa":"اگر چراغ خطر را روشن کنم، می‌توانم کوتاه در خط کُندرو بایستم.","ok":0,"eda":"Nej. Det er forbudt at standse i et krybespor, også kortvarigt; havariblinket ændrer ikke på det.","efa":"خیر. توقف در خط کُندرو ممنوع است، حتی کوتاه؛ چراغ خطر این را تغییر نمی‌دهد.","en":"I may stop briefly in the crawler lane if I switch on the hazard lights.","een":"No. Stopping in a crawler lane is forbidden, even briefly; the hazard lights do not change that."}]},{"id":5252,"img":"newq-art/5252.png","c":"7.18","sda":"Du kører på en landevej med denne tavle. Du er træt og vil holde ind og hvile dig et kvarter. Hvad gælder?","sfa":"در جاده‌ای بیرون شهر با این تابلو رانندگی می‌کنید. خسته‌اید و می‌خواهید کنار بزنید و یک ربع استراحت کنید. چه قاعده‌ای برقرار است؟","sen":"You are driving on a country road with this sign. You are tired and want to pull in and rest for a quarter of an hour. What applies?","st":[{"da":"Jeg kører videre til en parkeringsplads eller rasteplads og holder pause der.","fa":"تا یک پارکینگ یا استراحتگاه ادامه می‌دهم و آنجا استراحت می‌کنم.","ok":1,"eda":"Ja. Der kan du holde pause uden at være til fare for dig selv og andre.","efa":"بله. آنجا می‌توانید بدون خطر برای خود و دیگران استراحت کنید.","en":"I drive on to a car park or rest area and take my break there.","een":"Yes. There you can take a break without being a danger to yourself and others."},{"da":"Jeg må parkere på kørebanen, når jeg tænder havariblinket.","fa":"اگر چراغ خطر را روشن کنم، می‌توانم روی سواره‌رو پارک کنم.","ok":0,"eda":"Nej. Havariblinket gør ikke parkering tilladt, hvor den er forbudt.","efa":"خیر. چراغ خطر پارک را در جایی که ممنوع است مجاز نمی‌کند.","en":"I may park on the carriageway if I switch on the hazard lights.","een":"No. The hazard lights do not make parking allowed where it is forbidden."},{"da":"Jeg må ikke parkere på kørebanen her.","fa":"اینجا نباید روی سواره‌رو پارک کنم.","ok":1,"eda":"Ja. Tavlen viser en hovedvej, og uden for tættere bebygget område er parkering på hovedvejens kørebane forbudt.","efa":"بله. این تابلو جاده‌ی اصلی را نشان می‌دهد و بیرون از مناطق مسکونی پارک روی سواره‌روی جاده‌ی اصلی ممنوع است.","en":"I must not park on the carriageway here.","een":"Yes. The sign shows a main road, and outside built-up areas parking on a main road's carriageway is forbidden."},{"da":"Tavlen betyder, at jeg har ubetinget vigepligt for trafikken fra sidevejene.","fa":"این تابلو یعنی من باید به ترافیک راه‌های فرعی بی‌قیدوشرط حق تقدم بدهم.","ok":0,"eda":"Nej. Det er omvendt: trafikken fra sidevejene har ubetinget vigepligt for dig.","efa":"خیر. برعکس است: ترافیک راه‌های فرعی باید بی‌قیدوشرط به شما حق تقدم بدهد.","en":"The sign means that I must give way to the traffic from the side roads.","een":"No. It is the other way round: the traffic from the side roads must give way to you."}]},{"id":5253,"img":"newq-art/5253.png","c":"7.18","sda":"Du holder ind for at hente en pakke i en butik og er kun væk et par minutter. Hvad gælder, når du forlader bilen?","sfa":"کنار می‌زنید تا بسته‌ای را از یک مغازه بگیرید و فقط چند دقیقه دور می‌شوید. وقتی خودرو را ترک می‌کنید، چه قاعده‌ای برقرار است؟","sen":"You pull in to collect a parcel in a shop and will only be away for a couple of minutes. What applies when you leave the car?","st":[{"da":"Jeg sikrer, at bilen ikke kan sætte sig i gang af sig selv, fx med parkeringsbremsen.","fa":"مطمئن می‌شوم خودرو خودبه‌خود راه نمی‌افتد، مثلاً با ترمز دستی.","ok":1,"eda":"Ja. Når føreren forlader køretøjet, skal det sikres, at det ikke kan sætte i gang af sig selv.","efa":"بله. وقتی راننده خودرو را ترک می‌کند، باید مطمئن شود خودرو خودبه‌خود حرکت نمی‌کند.","en":"I make sure the car cannot start moving by itself, for example with the parking brake.","een":"Yes. When the driver leaves the vehicle, it must be secured so that it cannot start moving by itself."},{"da":"Jeg lader motoren køre, da jeg kun er væk et par minutter.","fa":"موتور را روشن می‌گذارم، چون فقط چند دقیقه دور می‌شوم.","ok":0,"eda":"Nej. En bil med motoren i gang og nøglen i kan let blive stjålet eller sat i bevægelse.","efa":"خیر. خودرویی که موتورش روشن و سوییچش داخل است، به‌راحتی دزدیده می‌شود یا به حرکت می‌افتد.","en":"I leave the engine running, as I will only be away for a couple of minutes.","een":"No. A car with its engine running and the key in can easily be stolen or set moving."},{"da":"Jeg tager nøglen med og låser bilen.","fa":"سوییچ را با خودم می‌برم و در خودرو را قفل می‌کنم.","ok":1,"eda":"Ja. Føreren skal sørge for, at bilen ikke uberettiget kan benyttes af andre.","efa":"بله. راننده باید مراقب باشد که دیگران نتوانند بدون اجازه از خودرو استفاده کنند.","en":"I take the key with me and lock the car.","een":"Yes. The driver must make sure that the car cannot be used by others without permission."},{"da":"Reglerne gælder, selv om jeg kun er væk et øjeblik.","fa":"این قواعد حتی اگر فقط لحظه‌ای دور شوم هم برقرارند.","ok":1,"eda":"Ja. Kravene gælder, hver gang føreren forlader køretøjet.","efa":"بله. این الزام‌ها هر بار که راننده خودرو را ترک می‌کند برقرارند.","en":"The rules apply even if I am only away for a moment.","een":"Yes. The requirements apply every time the driver leaves the vehicle."}]},{"id":5254,"img":"newq-art/5254.png","c":"7.18","sda":"Du kører en høj varevogn og vil parkere ved kantstenen lige foran denne tavle. Varevognen vil skjule tavlen for trafikken bag dig. Hvad gælder?","sfa":"با یک ون بلند رانندگی می‌کنید و می‌خواهید درست جلوی این تابلو کنار جدول پارک کنید. ون، تابلو را از دید ترافیک پشت سرتان پنهان می‌کند. چه قاعده‌ای برقرار است؟","sen":"You are driving a tall van and want to park at the kerb just in front of this sign. The van will hide the sign from the traffic behind you. What applies?","st":[{"da":"Det er tilladt, fordi de andre har set tavlen, før jeg holdt ind.","fa":"مجاز است، چون دیگران پیش از توقف من تابلو را دیده‌اند.","ok":0,"eda":"Nej. Trafikanter, der kommer senere, skal også kunne se tavlen.","efa":"خیر. کاربرانی که بعداً می‌رسند هم باید تابلو را ببینند.","en":"It is allowed because the others saw the sign before I pulled in.","een":"No. Road users who come later must also be able to see the sign."},{"da":"Forbuddet gælder kun lyssignaler, ikke tavler.","fa":"این ممنوعیت فقط برای چراغ‌هاست، نه تابلوها.","ok":0,"eda":"Nej. Det gælder både færdselstavler og signaler.","efa":"خیر. هم تابلوها و هم چراغ‌ها را شامل می‌شود.","en":"The ban only applies to traffic lights, not signs.","een":"No. It applies to both traffic signs and signals."},{"da":"Jeg må ikke standse eller parkere, så tavlen bliver skjult.","fa":"نباید طوری توقف یا پارک کنم که تابلو پنهان شود.","ok":1,"eda":"Ja. Det er forbudt at standse eller parkere på en sådan måde, at en færdselstavle eller et signal dækkes.","efa":"بله. توقف یا پارک به شکلی که تابلو یا چراغ راهنمایی را بپوشاند ممنوع است.","en":"I must not stop or park so that the sign is hidden.","een":"Yes. Stopping or parking in a way that covers a traffic sign or signal is forbidden."},{"da":"Jeg må holde der, hvis jeg er tilbage inden for 3 minutter.","fa":"اگر ظرف ۳ دقیقه برگردم، می‌توانم آنجا بایستم.","ok":0,"eda":"Nej. Forbuddet gælder også standsning, ikke kun parkering.","efa":"خیر. این ممنوعیت شامل توقف هم می‌شود، نه فقط پارک.","en":"I may stand there if I am back within 3 minutes.","een":"No. The ban also covers stopping, not only parking."}]},{"id":5255,"img":"newq-art/5255.png","c":"7.18","sda":"Før krydset er kørebanen delt i vognbaner med en ubrudt linje. Du vil standse ved kantstenen i den højre vognbane og sætte en passager af. Hvad gælder?","sfa":"پیش از تقاطع، سواره‌رو با یک خط ممتد به چند خط عبور تقسیم شده است. می‌خواهید در خط راست کنار جدول بایستید و مسافری را پیاده کنید. چه قاعده‌ای برقرار است؟","sen":"Before the junction the carriageway is divided into lanes by an unbroken line. You want to stop at the kerb in the right lane and let a passenger out. What applies?","st":[{"da":"Jeg må standse 3 m før det sted, hvor den ubrudte linje begynder.","fa":"می‌توانم ۳ متر پیش از جایی که خط ممتد شروع می‌شود بایستم.","ok":0,"eda":"Nej. Forbuddet gælder også de 5 m før strækningen med spærrelinjer.","efa":"خیر. این ممنوعیت ۵ متر پیش از شروع خط‌های ممتد را هم شامل می‌شود.","en":"I may stop 3 m before the point where the unbroken line begins.","een":"No. The ban also covers the 5 m before the stretch with barrier lines."},{"da":"Det er forbudt at standse her.","fa":"توقف در اینجا ممنوع است.","ok":1,"eda":"Ja. Standsning og parkering er forbudt på en strækning, hvor kørebanen før et vejkryds er delt i vognbaner med spærrelinjer.","efa":"بله. توقف و پارک در جایی که سواره‌رو پیش از تقاطع با خط‌های ممتد به چند خط تقسیم شده ممنوع است.","en":"Stopping is forbidden here.","een":"Yes. Stopping and parking are forbidden on a stretch where the carriageway before a junction is divided into lanes by barrier lines."},{"da":"Jeg må standse, hvis passageren stiger hurtigt ud.","fa":"اگر مسافر سریع پیاده شود، می‌توانم بایستم.","ok":0,"eda":"Nej. Forbuddet gælder enhver standsning, også for af- og påstigning.","efa":"خیر. این ممنوعیت هر توقفی را شامل می‌شود، حتی برای سوار و پیاده شدن.","en":"I may stop if the passenger gets out quickly.","een":"No. The ban covers every stop, also to let people in or out."},{"da":"Forbuddet gælder kun den venstre vognbane.","fa":"این ممنوعیت فقط برای خط چپ است.","ok":0,"eda":"Nej. Det gælder på hele strækningen, hvor kørebanen er delt med spærrelinjer.","efa":"خیر. در تمام طولی که سواره‌رو با خط ممتد تقسیم شده برقرار است.","en":"The ban only applies to the left lane.","een":"No. It applies along the whole stretch where the carriageway is divided by barrier lines."}]},{"id":5256,"img":"newq-art/5256.png","c":"7.9","sda":"Du kører i en almindelig personbil og passerer denne tavle. Foran dig kører en langsom varevogn, og der kommer ingen imod dig. Hvad gælder?","sfa":"با یک خودروی سواری معمولی از کنار این تابلو می‌گذرید. یک ون کُند جلوی شماست و از روبه‌رو کسی نمی‌آید. چه قاعده‌ای برقرار است؟","sen":"You are driving an ordinary car and pass this sign. A slow van is in front of you, and nothing is coming towards you. What applies?","st":[{"da":"Jeg må gerne overhale varevognen i min personbil, hvis det kan ske uden fare.","fa":"با خودروی سواری‌ام اگر بی‌خطر باشد می‌توانم از ون سبقت بگیرم.","ok":1,"eda":"Ja. Forbuddet gælder ikke personbiler; her gælder de almindelige regler om overhaling.","efa":"بله. این ممنوعیت شامل خودروهای سواری نمی‌شود؛ قواعد معمول سبقت برقرار است.","en":"I may overtake the van in my car if it can be done safely.","een":"Yes. The ban does not apply to cars; the ordinary rules on overtaking apply."},{"da":"Tavlen forbyder alle køretøjer at overhale.","fa":"این تابلو سبقت را برای همه‌ی وسایل نقلیه ممنوع می‌کند.","ok":0,"eda":"Nej. Det almindelige overhalingsforbud har sin egen tavle med to biler.","efa":"خیر. ممنوعیت کلی سبقت تابلوی خودش را با دو خودرو دارد.","en":"The sign forbids all vehicles to overtake.","een":"No. The general no-overtaking ban has its own sign showing two cars."},{"da":"Tavlen forbyder lastbiler at overhale.","fa":"این تابلو سبقت گرفتن کامیون‌ها را ممنوع می‌کند.","ok":1,"eda":"Ja. Tavlen forbyder overhaling med lastbil og lastbilvogntog.","efa":"بله. این تابلو سبقت کامیون و کامیون با یدک را ممنوع می‌کند.","en":"The sign forbids lorries to overtake.","een":"Yes. The sign forbids overtaking by lorries and lorry combinations."},{"da":"Forbuddet ophører ved næste vejkryds.","fa":"این ممنوعیت در تقاطع بعدی تمام می‌شود.","ok":0,"eda":"Nej. Forbuddet gælder, indtil det ophæves med en tavle for ophør eller ved en afstand på en undertavle.","efa":"خیر. این ممنوعیت تا تابلوی پایان یا تا فاصله‌ای که زیرتابلو نشان می‌دهد ادامه دارد.","en":"The ban ends at the next junction.","een":"No. The ban applies until it is lifted by an end sign or after a distance shown on a sub-plate."}]},{"id":5257,"img":"newq-art/5257.png","c":"7.9","sda":"Der er tæt trafik, og bilerne kører i kø i begge vognbaner i din retning. Din vognbane til højre glider lidt hurtigere end den venstre. Hvad gælder?","sfa":"ترافیک سنگین است و خودروها در هر دو خط جهت شما در صف حرکت می‌کنند. خط شما در سمت راست کمی سریع‌تر از خط چپ پیش می‌رود. چه قاعده‌ای برقرار است؟","sen":"The traffic is dense and the cars are queuing in both lanes in your direction. Your lane on the right is moving a little faster than the left one. What applies?","st":[{"da":"Det regnes ikke som overhaling, at jeg kører forbi bilerne i den venstre vognbane.","fa":"رد شدن من از کنار خودروهای خط چپ سبقت حساب نمی‌شود.","ok":1,"eda":"Ja. I tæt trafik i flere rækker anses det ikke som overhaling, at et køretøj i én vognbane kører forbi et køretøj i en anden.","efa":"بله. در ترافیک سنگین چندصفی، رد شدن یک خودرو در یک خط از خودرویی در خط دیگر سبقت حساب نمی‌شود.","en":"It does not count as overtaking when I pass the cars in the left lane.","een":"Yes. In dense traffic in several rows, a vehicle in one lane passing a vehicle in another lane does not count as overtaking."},{"da":"Det er forbudt at køre hurtigere i højre vognbane end i venstre.","fa":"سریع‌تر رفتن در خط راست نسبت به خط چپ ممنوع است.","ok":0,"eda":"Nej. I tæt kø i flere vognbaner må den højre vognbane gerne glide hurtigere end den venstre.","efa":"خیر. در صف‌های سنگین چندخطه، خط راست می‌تواند سریع‌تر از خط چپ حرکت کند.","en":"It is forbidden to go faster in the right lane than in the left.","een":"No. In dense queues in several lanes, the right lane may well move faster than the left."},{"da":"Jeg må ikke skifte vognbane frem og tilbage for at komme hurtigere frem.","fa":"نباید برای جلو افتادن مدام خط عوض کنم.","ok":1,"eda":"Ja. I sådan tæt trafik må du kun skifte vognbane, når det er nødvendigt, fx for at komme i den rigtige vognbane før et kryds eller for at standse eller parkere.","efa":"بله. در چنین ترافیکی فقط وقتی می‌توانید خط عوض کنید که لازم باشد، مثلاً برای رفتن به خط درست پیش از تقاطع یا برای توقف و پارک.","en":"I must not change lanes back and forth to get on faster.","een":"Yes. In such dense traffic you may only change lanes when necessary, for example to get into the right lane before a junction or to stop or park."}]},{"id":5258,"img":"newq-art/5258.png","c":"7.9","sda":"Du kører på en strækning med denne tavle. Bilen foran dig holder ved midterlinjen og blinker til venstre for at svinge ind på en sidevej. Hvad gælder?","sfa":"در مسیری با این تابلو رانندگی می‌کنید. خودروی جلویی کنار خط وسط ایستاده و راهنمای چپ زده تا به راه فرعی بپیچد. چه قاعده‌ای برقرار است؟","sen":"You are on a stretch of road with this sign. The car in front of you is waiting at the centre line, signalling left to turn into a side road. What applies?","st":[{"da":"Jeg skal vente bag bilen, fordi overhaling er forbudt på strækningen.","fa":"باید پشت آن خودرو منتظر بمانم، چون سبقت در این مسیر ممنوع است.","ok":0,"eda":"Nej. Forbuddet har en undtagelse for køretøjer, der svinger af vejen.","efa":"خیر. این ممنوعیت برای وسایلی که از جاده خارج می‌شوند استثنا دارد.","en":"I must wait behind the car because overtaking is forbidden on this stretch.","een":"No. The ban has an exception for vehicles turning off the road."},{"da":"Jeg må køre forbi bilen i højre side, når der er plads til det.","fa":"اگر جا باشد، می‌توانم از سمت راست آن خودرو رد شوم.","ok":1,"eda":"Ja. Overhalingsforbuddet gælder ikke overhaling af et køretøj, der svinger af vejen, og en bil, der svinger til venstre, overhales i højre side.","efa":"بله. ممنوعیت سبقت شامل وسیله‌ای که از جاده خارج می‌شود نیست، و خودرویی را که به چپ می‌پیچد باید از سمت راست رد کرد.","en":"I may pass the car on its right when there is room for it.","een":"Yes. The no-overtaking ban does not apply to overtaking a vehicle that is turning off the road, and a car turning left is overtaken on its right."},{"da":"Jeg må køre forbi bilen i venstre side, fordi den holder stille.","fa":"چون آن خودرو ایستاده، می‌توانم از سمت چپش رد شوم.","ok":0,"eda":"Nej. En bil, der svinger til venstre, skal overhales i højre side; til venstre kører du ud foran den og ind i de modkørendes vognbane.","efa":"خیر. خودرویی را که به چپ می‌پیچد باید از راست رد کرد؛ از چپ، جلوی او و وارد خط ترافیک روبه‌رو می‌شوید.","en":"I may pass the car on its left because it is standing still.","een":"No. A car turning left must be overtaken on its right; on the left you would drive out in front of it and into the oncoming lane."}]},{"id":5259,"img":"newq-art/5259.png","c":"7.9","sda":"Foran dig kører en cyklist op mod en bakketop, hvor du ikke kan se, om der kommer modkørende. Din vognbane er bred. Hvad gælder for overhaling af cyklisten?","sfa":"جلوی شما دوچرخه‌سواری به سمت بالای تپه‌ای می‌رود که نمی‌بینید از روبه‌رو کسی می‌آید یا نه. خط شما پهن است. درباره‌ی سبقت از دوچرخه‌سوار چه قاعده‌ای برقرار است؟","sen":"In front of you a cyclist is riding up towards a hilltop where you cannot see whether anything is coming towards you. Your lane is wide. What applies to overtaking the cyclist?","st":[{"da":"Jeg må kun overhale, hvis jeg kan holde god afstand til cyklisten uden at komme over i den modkørende vognbane.","fa":"فقط وقتی می‌توانم سبقت بگیرم که بدون رفتن به خط مقابل، فاصله‌ی کافی با دوچرخه‌سوار داشته باشم.","ok":1,"eda":"Ja. Du må ikke bruge en vognbane, som du ikke kan se er fri for modkørende, og du skal holde tilstrækkelig afstand til siden.","efa":"بله. نباید از خطی استفاده کنید که نمی‌بینید از ترافیک روبه‌رو خالی است، و باید فاصله‌ی کافی از پهلو داشته باشید.","en":"I may only overtake if I can keep a good distance to the cyclist without crossing into the oncoming lane.","een":"Yes. You must not use a lane that you cannot see is free of oncoming traffic, and you must keep enough distance to the side."},{"da":"Forbuddet mod overhaling ved en uoverskuelig bakke gælder ikke overhaling af en tohjulet cykel.","fa":"ممنوعیت سبقت در تپه‌ی بی‌دید شامل سبقت از دوچرخه‌ی دوچرخ نمی‌شود.","ok":1,"eda":"Ja. Overhalingsforbuddet ved uoverskuelige bakker, sving og kryds gælder ikke over for tohjulede cykler og små knallerter.","efa":"بله. ممنوعیت سبقت در تپه‌ی بی‌دید، پیچ و تقاطع شامل دوچرخه‌ی دوچرخ و موپد کوچک نمی‌شود.","en":"The ban on overtaking at a blind hill does not apply to overtaking a two-wheeled bicycle.","een":"Yes. The overtaking ban at blind hills, bends and junctions does not apply to two-wheeled bicycles and small mopeds."},{"da":"Jeg dytter, så cyklisten kører helt ind til kanten.","fa":"بوق می‌زنم تا دوچرخه‌سوار کاملاً به لبه برود.","ok":0,"eda":"Nej. Hornet må kun bruges for at forebygge eller afværge fare.","efa":"خیر. بوق فقط برای پیشگیری یا دفع خطر است.","en":"I sound the horn so that the cyclist moves right over to the edge.","een":"No. The horn may only be used to prevent or avert danger."},{"da":"Jeg overhaler tæt forbi cyklisten, så jeg ikke kommer over midterlinjen.","fa":"از نزدیکِ دوچرخه‌سوار سبقت می‌گیرم تا از خط وسط رد نشوم.","ok":0,"eda":"Nej. Du skal holde tilstrækkelig afstand til siden; er der ikke plads i din egen side, venter du til efter bakketoppen.","efa":"خیر. باید فاصله‌ی کافی از پهلو داشته باشید؛ اگر در سمت خودتان جا نیست، تا بعد از تپه صبر کنید.","en":"I overtake close past the cyclist so that I do not cross the centre line.","een":"No. You must keep enough distance to the side; if there is not room on your own side, you wait until after the hilltop."}]},{"id":5260,"img":"newq-art/5260.png","c":"7.9","sda":"Et vejarbejdskøretøj maler midterlinjen og kører meget langsomt midt på vejen. Der er plads til højre for det. Hvad gælder?","sfa":"یک خودروی راهسازی در حال رنگ‌آمیزی خط وسط است و خیلی آهسته وسط جاده حرکت می‌کند. سمت راستش جا هست. چه قاعده‌ای برقرار است؟","sen":"A road-works vehicle is painting the centre line and driving very slowly in the middle of the road. There is room to its right. What applies?","st":[{"da":"Jeg kører forbi med lav fart og god afstand.","fa":"با سرعت کم و فاصله‌ی کافی رد می‌شوم.","ok":1,"eda":"Ja. Hvor der arbejdes på vejen, skal du holde en passende lav hastighed.","efa":"بله. جایی که روی جاده کار انجام می‌شود، باید سرعت مناسبِ کمی داشته باشید.","en":"I pass at a low speed with a good distance.","een":"Yes. Where work is being done on the road, you must keep a suitably low speed."},{"da":"Jeg må aldrig overhale i højre side.","fa":"هرگز نباید از سمت راست سبقت بگیرم.","ok":0,"eda":"Nej. Et køretøj, der bruges ved vejarbejde, må overhales på den mest hensigtsmæssige måde, også i højre side.","efa":"خیر. خودروی راهسازی را می‌توان به مناسب‌ترین شکل سبقت گرفت، حتی از سمت راست.","en":"I may never overtake on the right.","een":"No. A vehicle used for road works may be overtaken in the most suitable way, also on its right."},{"da":"Jeg skal blive bag køretøjet, til det er færdigt med at male.","fa":"باید تا پایان رنگ‌آمیزی پشت آن خودرو بمانم.","ok":0,"eda":"Nej. Du må overhale det, når det kan ske med fornøden forsigtighed.","efa":"خیر. وقتی با احتیاط لازم ممکن باشد، می‌توانید از آن سبقت بگیرید.","en":"I must stay behind the vehicle until it has finished painting.","een":"No. You may overtake it when it can be done with due care."},{"da":"Jeg må overhale køretøjet i højre side, hvis det er det mest hensigtsmæssige.","fa":"اگر مناسب‌ترین راه باشد، می‌توانم از سمت راست آن خودرو سبقت بگیرم.","ok":1,"eda":"Ja. Et køretøj, der bruges ved vejarbejde, må med fornøden forsigtighed overhales på den måde, der er mest hensigtsmæssig.","efa":"بله. خودرویی را که در کار راهسازی است می‌توان با احتیاط لازم به مناسب‌ترین شکل سبقت گرفت.","en":"I may overtake the vehicle on its right if that is the most suitable way.","een":"Yes. A vehicle used for road works may be overtaken with due care in whatever way is most suitable."}]},{"id":5261,"img":"newq-art/5261.png","c":"6.1","sda":"Du kører forbi denne tavle. Hvad betyder den?","sfa":"از کنار این تابلو می‌گذرید. معنی‌اش چیست؟","sen":"You pass this sign. What does it mean?","st":[{"da":"Det er en hastighedsgrænse på samme måde som en rund tavle med rød kant.","fa":"این هم مثل تابلوی گرد با حاشیه‌ی قرمز، حد سرعت است.","ok":0,"eda":"Nej. Den blå firkantede tavle er en anbefaling; den runde tavle med rød kant er et forbud.","efa":"خیر. تابلوی مربعی آبی توصیه است؛ تابلوی گرد با حاشیه‌ی قرمز ممنوعیت است.","en":"It is a speed limit in the same way as a round sign with a red border.","een":"No. The blue square sign is a recommendation; the round sign with a red border is a ban."},{"da":"Anbefalingen gælder, indtil en tavle ophæver den, eller til den afstand, som en undertavle angiver.","fa":"این توصیه تا تابلویی که آن را لغو کند، یا تا فاصله‌ای که زیرتابلو نشان می‌دهد، برقرار است.","ok":1,"eda":"Ja. Den anbefalede hastighed ophæves med tavlen for ophør eller ved en afstand på en undertavle.","efa":"بله. سرعت توصیه‌شده با تابلوی پایان یا با فاصله‌ی زیرتابلو لغو می‌شود.","en":"The recommendation applies until a sign ends it, or for the distance shown on a sub-plate.","een":"Yes. The recommended speed is ended by the end sign or by a distance on a sub-plate."},{"da":"Jeg skal køre mindst 60 km/t.","fa":"باید دست‌کم ۶۰ کیلومتر بر ساعت برانم.","ok":0,"eda":"Nej. En påbudt mindste hastighed vises på en rund blå tavle.","efa":"خیر. حداقل سرعت اجباری با تابلوی گرد آبی نشان داده می‌شود.","en":"I must drive at least 60 km/h.","een":"No. A compulsory minimum speed is shown on a round blue sign."},{"da":"Vejen er ikke egnet til kørsel med højere hastighed end 60 km/t.","fa":"این جاده برای رانندگی با سرعتی بیش از ۶۰ کیلومتر بر ساعت مناسب نیست.","ok":1,"eda":"Ja. Tavlen angiver en anbefalet hastighed: vejen er ikke egnet til højere hastighed end den angivne.","efa":"بله. این تابلو سرعت توصیه‌شده را نشان می‌دهد: جاده برای سرعتی بیش از عدد روی تابلو مناسب نیست.","en":"The road is not suitable for driving faster than 60 km/h.","een":"Yes. The sign gives a recommended speed: the road is not suitable for a higher speed than the one shown."}]},{"id":5262,"img":"newq-art/5262.png","c":"6.1","sda":"Du vil køre ind ad vejen med denne tavle. Hvad betyder den?","sfa":"می‌خواهید وارد راهی با این تابلو شوید. معنی‌اش چیست؟","sen":"You are about to turn into the road with this sign. What does it mean?","st":[{"da":"Vejen er kun for cyklister og gående.","fa":"این راه فقط برای دوچرخه‌سواران و عابران است.","ok":0,"eda":"Nej. Kun stien i enden er for dem; på selve vejen må biler køre.","efa":"خیر. فقط مسیرِ انتهای راه برای آن‌هاست؛ خودروها می‌توانند در خودِ راه برانند.","en":"The road is only for cyclists and pedestrians.","een":"No. Only the path at the end is for them; cars may drive on the road itself."},{"da":"Den tynde hvide streg viser, at vejen fortsætter som en sti.","fa":"خط باریک سفید نشان می‌دهد راه به صورت یک مسیر پیاده یا دوچرخه ادامه دارد.","ok":1,"eda":"Ja. Med en tynd hvid streg på tavlen angives, at vejen fortsætter i en sti.","efa":"بله. خط باریک سفید روی تابلو یعنی راه به صورت مسیر ادامه پیدا می‌کند.","en":"The thin white line shows that the road continues as a path.","een":"Yes. A thin white line on the sign shows that the road continues as a path."},{"da":"Jeg må godt køre ind på vejen, fx for at besøge et af husene.","fa":"می‌توانم وارد این راه شوم، مثلاً برای رفتن به یکی از خانه‌ها.","ok":1,"eda":"Ja. Tavlen er en oplysning, ikke et forbud; du skal blot vende for at komme ud igen.","efa":"بله. این تابلو اطلاع‌رسانی است، نه ممنوعیت؛ فقط برای بیرون آمدن باید دور بزنید.","en":"I may drive into the road, for example to visit one of the houses.","een":"Yes. The sign is information, not a ban; you just have to turn round to get out again."},{"da":"Vejen er blind for biler, så jeg kan ikke køre igennem.","fa":"این راه برای خودروها بن‌بست است و نمی‌توانم از آن عبور کنم.","ok":1,"eda":"Ja. Tavlen angiver blind vej.","efa":"بله. این تابلو بن‌بست را نشان می‌دهد.","en":"The road is a dead end for cars, so I cannot drive through.","een":"Yes. The sign shows a dead-end road."}]},{"id":5263,"img":"newq-art/5263.png","c":"6.1","sda":"Foran dig er der et skraveret felt på kørebanen, omgivet af en ubrudt linje. Hvad gælder?","sfa":"جلوی شما روی سواره‌رو یک محدوده‌ی هاشورخورده هست که دورش خط ممتد کشیده شده. چه قاعده‌ای برقرار است؟","sen":"In front of you there is a hatched area on the carriageway, framed by an unbroken line. What applies?","st":[{"da":"Jeg må hverken køre, standse eller parkere på feltet.","fa":"روی این محدوده نه می‌توانم برانم، نه توقف کنم و نه پارک.","ok":1,"eda":"Ja. Feltet er en spærreflade, hvor der ikke må køres, standses eller parkeres.","efa":"بله. این محدوده هاشورخورده است و رانندگی، توقف و پارک در آن ممنوع است.","en":"I may neither drive, stop nor park on the area.","een":"Yes. The area is a hatched no-go area where driving, stopping and parking are not allowed."},{"da":"Jeg må parkere på feltet, når det ikke er i vejen for nogen.","fa":"اگر مزاحم کسی نباشد، می‌توانم روی آن پارک کنم.","ok":0,"eda":"Nej. Parkering er forbudt på spærrefladen.","efa":"خیر. پارک روی محدوده‌ی هاشورخورده ممنوع است.","en":"I may park on the area when it is not in anyone's way.","een":"No. Parking is forbidden on the hatched area."},{"da":"Feltet er en cykelbane.","fa":"این محدوده خط دوچرخه است.","ok":0,"eda":"Nej. En spærreflade er ikke for nogen trafik.","efa":"خیر. محدوده‌ی هاشورخورده برای هیچ ترافیکی نیست.","en":"The area is a cycle lane.","een":"No. A hatched area is not for any traffic."},{"da":"Jeg må køre hen over feltet for at komme hurtigere ind i venstresvingsbanen.","fa":"می‌توانم برای زودتر رسیدن به خط گردش به چپ از روی آن رد شوم.","ok":0,"eda":"Nej. Du skal køre ind i venstresvingsbanen, hvor den begynder, ikke hen over spærrefladen.","efa":"خیر. باید از جایی که خط گردش به چپ شروع می‌شود واردش شوید، نه از روی محدوده‌ی هاشورخورده.","en":"I may drive across the area to get into the left-turn lane sooner.","een":"No. You must enter the left-turn lane where it begins, not across the hatched area."}]},{"id":5264,"img":"newq-art/5264.png","c":"6.1","sda":"Du kører på en vej med to vognbaner i din retning og passerer denne tavle. Hvad betyder den?","sfa":"در جاده‌ای با دو خط در جهت خودتان رانندگی می‌کنید و از کنار این تابلو می‌گذرید. معنی‌اش چیست؟","sen":"You are driving on a road with two lanes in your direction and pass this sign. What does it mean?","st":[{"da":"Vejen er ensrettet efter tavlen.","fa":"پس از این تابلو، جاده یک‌طرفه است.","ok":0,"eda":"Nej. Tavlen betyder det modsatte: der kommer trafik imod dig.","efa":"خیر. این تابلو برعکس است: ترافیک از روبه‌رو می‌آید.","en":"The road is one-way after the sign.","een":"No. The sign means the opposite: traffic will come towards you."},{"da":"Tavlen betyder, at jeg skal holde tilbage for modkørende ved en indsnævring.","fa":"این تابلو یعنی در یک باریک‌شدگی باید به ترافیک روبه‌رو راه بدهم.","ok":0,"eda":"Nej. Tavlen er en advarsel og giver ingen vigepligt; vigepligt for modkørende har sin egen tavle.","efa":"خیر. این تابلو هشدار است و تکلیف حق تقدم تعیین نمی‌کند؛ راه دادن به ترافیک روبه‌رو تابلوی خودش را دارد.","en":"The sign means that I must give way to oncoming traffic at a narrowing.","een":"No. The sign is a warning and gives no duty to give way; giving way to oncoming traffic has its own sign."},{"da":"Længere fremme kommer der modkørende trafik.","fa":"کمی جلوتر ترافیک روبه‌رو وجود دارد.","ok":1,"eda":"Ja. Tavlen advarer om modkørende færdsel.","efa":"بله. این تابلو درباره‌ی ترافیک روبه‌رو هشدار می‌دهد.","en":"Further ahead there will be oncoming traffic.","een":"Yes. The sign warns of oncoming traffic."},{"da":"Jeg kan blive i venstre vognbane, også efter at vejen er blevet dobbeltrettet.","fa":"حتی پس از دوطرفه شدن جاده هم می‌توانم در خط چپ بمانم.","ok":0,"eda":"Nej. Når der kommer modkørende færdsel, skal du holde til højre i din egen side af vejen.","efa":"خیر. وقتی ترافیک روبه‌رو هست، باید در سمت خودتان به راست بمانید.","en":"I can stay in the left lane, also after the road has become two-way.","een":"No. When there is oncoming traffic, you must keep right on your own side of the road."}]},{"id":5265,"img":"newq-art/5265.png","c":"7.6","sda":"En bus holder ved stoppestedet i den modsatte side af vejen, og passagerer stiger af. Hvordan forholder du dig?","sfa":"اتوبوسی در ایستگاه آن طرف خیابان ایستاده و مسافرها پیاده می‌شوند. چه می‌کنید؟","sen":"A bus is standing at the stop on the opposite side of the road, and passengers are getting off. What do you do?","st":[{"da":"Jeg sænker farten og er klar til at standse, fordi passagerer kan gå ud på vejen foran bussen.","fa":"سرعتم را کم می‌کنم و آماده‌ی توقفم، چون ممکن است مسافرها از جلوی اتوبوس وارد خیابان شوند.","ok":1,"eda":"Ja. Når du nærmer dig en bus, der holder for at afsætte passagerer, skal du holde en passende lav hastighed.","efa":"بله. وقتی به اتوبوسی نزدیک می‌شوید که برای پیاده کردن مسافر ایستاده، باید سرعت مناسبِ کمی داشته باشید.","en":"I slow down and am ready to stop, because passengers may step out onto the road in front of the bus.","een":"Yes. When you approach a bus that is standing to let passengers off, you must keep a suitably low speed."},{"da":"Jeg kan holde farten, fordi bussen holder i den modsatte side.","fa":"می‌توانم با همان سرعت ادامه بدهم، چون اتوبوس آن طرف خیابان است.","ok":0,"eda":"Nej. Passagerer, der skal over vejen, kommer frem foran bussen lige ud i din side.","efa":"خیر. مسافرانی که می‌خواهند از خیابان رد شوند، از جلوی اتوبوس درست وارد سمت شما می‌شوند.","en":"I can keep my speed because the bus is on the opposite side.","een":"No. Passengers crossing the road come out in front of the bus right into your side."},{"da":"Passagererne skal vente, til bussen er kørt, så jeg behøver ikke tage hensyn.","fa":"مسافرها باید تا رفتن اتوبوس صبر کنند، پس لازم نیست ملاحظه کنم.","ok":0,"eda":"Nej. Du skal altid køre, så du kan undgå at ramme en gående, også én, der går ud uden at se sig for.","efa":"خیر. همیشه باید طوری برانید که بتوانید با عابر برخورد نکنید، حتی اگر بی‌توجه وارد خیابان شود.","en":"The passengers have to wait until the bus has left, so I need not take care.","een":"No. You must always drive so that you can avoid hitting a pedestrian, also one who steps out without looking."}]},{"id":5266,"img":"newq-art/5266.png","c":"7.6","sda":"Lidt fremme har der været et uheld. En ambulance og politiet holder i vejkanten. Hvordan forholder du dig?","sfa":"کمی جلوتر تصادفی رخ داده است. یک آمبولانس و پلیس کنار جاده ایستاده‌اند. چه می‌کنید؟","sen":"Just ahead there has been an accident. An ambulance and the police are standing at the roadside. What do you do?","st":[{"da":"Jeg følger politibetjentens tegn.","fa":"از علامت‌های مأمور پلیس پیروی می‌کنم.","ok":1,"eda":"Ja. Du skal efterkomme politiets anvisninger.","efa":"بله. باید از دستورهای پلیس پیروی کنید.","en":"I follow the police officer's signals.","een":"Yes. You must obey the police's directions."},{"da":"Jeg sænker farten og kører forsigtigt forbi uheldsstedet.","fa":"سرعتم را کم می‌کنم و با احتیاط از محل تصادف رد می‌شوم.","ok":1,"eda":"Ja. Forbi et uheldssted skal du holde en passende lav hastighed.","efa":"بله. هنگام رد شدن از محل تصادف باید سرعت مناسبِ کمی داشته باشید.","en":"I slow down and drive carefully past the accident site.","een":"Yes. Past an accident site you must keep a suitably low speed."},{"da":"Jeg holder øje med folk, der går på vejen ved uheldsstedet.","fa":"مراقب کسانی هستم که در محل تصادف روی جاده راه می‌روند.","ok":1,"eda":"Ja. Ved et uheldssted kan redningsfolk og andre pludselig gå ud på kørebanen.","efa":"بله. در محل تصادف، امدادگران و دیگران ممکن است ناگهان وارد سواره‌رو شوند.","en":"I watch out for people walking on the road at the accident site.","een":"Yes. At an accident site rescue workers and others may suddenly step out onto the carriageway."},{"da":"Jeg tager et billede med telefonen, mens jeg kører langsomt forbi.","fa":"هنگام رد شدن آهسته، با گوشی عکس می‌گیرم.","ok":0,"eda":"Nej. Du må ikke bruge en håndholdt mobiltelefon under kørslen, og din opmærksomhed skal være på vejen.","efa":"خیر. هنگام رانندگی نباید با گوشیِ در دست کار کنید و حواستان باید به جاده باشد.","en":"I take a picture with my phone while I drive slowly past.","een":"No. You must not use a hand-held phone while driving, and your attention must be on the road."}]},{"id":5267,"img":"newq-art/5267.png","c":"7.6","sda":"En varevogn holder ved kantstenen, og føreren læsser pakker ud af sidedøren i vejsiden. Hvordan forholder du dig?","sfa":"یک ون کنار جدول ایستاده و راننده‌اش از در کناریِ سمت خیابان بسته‌ها را بیرون می‌آورد. چه می‌کنید؟","sen":"A van is standing at the kerb, and the driver is unloading parcels from the side door on the street side. What do you do?","st":[{"da":"Jeg sænker farten, så jeg kan standse, hvis føreren træder ud foran mig.","fa":"سرعتم را کم می‌کنم تا اگر راننده جلویم آمد، بتوانم بایستم.","ok":1,"eda":"Ja. Han har travlt med pakkerne og ser sig måske ikke for.","efa":"بله. او سرگرم بسته‌هاست و ممکن است اطرافش را نگاه نکند.","en":"I slow down so that I can stop if the driver steps out in front of me.","een":"Yes. He is busy with the parcels and may not look around."},{"da":"Jeg kører tæt forbi, fordi det er føreren, der skal passe på, når han læsser ud i vejsiden.","fa":"از نزدیکش رد می‌شوم، چون کسی که در سمت خیابان بار خالی می‌کند باید مراقب باشد.","ok":0,"eda":"Nej. Han skal passe på, men du skal også tage hensyn og holde afstand.","efa":"خیر. او باید مراقب باشد، ولی شما هم باید ملاحظه کنید و فاصله بگیرید.","en":"I drive close past, because it is the driver who must take care when he unloads on the street side.","een":"No. He must take care, but you too must show consideration and keep your distance."},{"da":"Jeg holder god afstand til siden, når jeg kører forbi.","fa":"هنگام رد شدن، فاصله‌ی کافی از پهلو نگه می‌دارم.","ok":1,"eda":"Ja. Føreren kan pludselig træde ud på kørebanen med pakkerne.","efa":"بله. ممکن است راننده با بسته‌ها ناگهان وارد سواره‌رو شود.","en":"I keep a good distance to the side when I drive past.","een":"Yes. The driver may suddenly step out onto the carriageway with the parcels."}]},{"id":5268,"img":"newq-art/5268.png","c":"7.6","sda":"Mellem to parkerede biler står en kvinde med en barnevogn og ser ud til at ville gå over vejen. Der er intet fodgængerfelt. Hvordan forholder du dig?","sfa":"بین دو خودروی پارک‌شده زنی با کالسکه ایستاده و به نظر می‌رسد می‌خواهد از خیابان رد شود. گذرگاه عابر پیاده‌ای نیست. چه می‌کنید؟","sen":"Between two parked cars a woman with a pram is standing and looks as if she wants to cross the road. There is no pedestrian crossing. What do you do?","st":[{"da":"Barnevognen kommer ud på vejen før kvinden, så jeg holder øje med den.","fa":"کالسکه پیش از خودِ زن وارد خیابان می‌شود، پس مراقبش هستم.","ok":1,"eda":"Ja. Barnevognen skubbes foran og er det første, der kommer frem mellem bilerne.","efa":"بله. کالسکه جلوتر هل داده می‌شود و اولین چیزی است که از بین خودروها بیرون می‌آید.","en":"The pram comes out onto the road before the woman, so I keep an eye on it.","een":"Yes. The pram is pushed in front and is the first thing to appear between the cars."},{"da":"Jeg kører tæt ind mod de parkerede biler, så jeg hurtigt kommer forbi.","fa":"به خودروهای پارک‌شده نزدیک می‌شوم تا زود رد شوم.","ok":0,"eda":"Nej. Hold god afstand til de parkerede biler; der kan komme nogen frem mellem dem.","efa":"خیر. از خودروهای پارک‌شده فاصله بگیرید؛ ممکن است کسی از بینشان بیرون بیاید.","en":"I drive close to the parked cars so that I get past quickly.","een":"No. Keep a good distance from the parked cars; someone may come out between them."},{"da":"Hun skal vente, fordi der ikke er et fodgængerfelt, så jeg kører videre med samme fart.","fa":"او باید صبر کند چون گذرگاه نیست، پس با همان سرعت ادامه می‌دهم.","ok":0,"eda":"Nej. Uanset hvor en gående går over, skal du køre, så du kan undgå at ramme vedkommende.","efa":"خیر. عابر هر جا که از خیابان بگذرد، باید طوری برانید که با او برخورد نکنید.","en":"She has to wait because there is no pedestrian crossing, so I carry on at the same speed.","een":"No. Wherever a pedestrian crosses, you must drive so that you can avoid hitting them."},{"da":"Jeg sænker farten og er klar til at standse.","fa":"سرعتم را کم می‌کنم و آماده‌ی توقفم.","ok":1,"eda":"Ja. Hun kan gå ud på vejen, og du skal kunne standse foran enhver hindring, der kan forventes.","efa":"بله. ممکن است وارد خیابان شود و شما باید بتوانید جلوی هر مانعی که انتظارش می‌رود بایستید.","en":"I slow down and am ready to stop.","een":"Yes. She may step out, and you must be able to stop in front of any obstacle that can be expected."}]},{"id":5269,"img":"newq-art/5269.png","c":"7.3","sda":"Du kører ind i et boligområde forbi denne tavle. Hvad gælder?","sfa":"از کنار این تابلو وارد یک محله‌ی مسکونی می‌شوید. چه قاعده‌ای برقرار است؟","sen":"You drive into a residential area past this sign. What applies?","st":[{"da":"Grænsen gælder kun til det første vejkryds.","fa":"این حد فقط تا اولین تقاطع است.","ok":0,"eda":"Nej. En zonetavle gælder også efter krydsene inde i området.","efa":"خیر. تابلوی منطقه پس از تقاطع‌های داخل محدوده هم برقرار است.","en":"The limit only applies until the first junction.","een":"No. A zone sign also applies after the junctions inside the area."},{"da":"Grænsen gælder, indtil jeg kører forbi en tavle, der viser, at zonen ophører.","fa":"این حد تا رسیدن به تابلویی که پایان منطقه را نشان دهد برقرار است.","ok":1,"eda":"Ja. Zonetavlens bestemmelser gælder, indtil de ophæves af tavlen for zonens ophør.","efa":"بله. مقررات تابلوی منطقه تا تابلوی پایان منطقه برقرارند.","en":"The limit applies until I pass a sign showing that the zone ends.","een":"Yes. The zone sign's rules apply until they are ended by the end-of-zone sign."},{"da":"Jeg må højst køre 40 km/t på vejene i området, medmindre andet er skiltet.","fa":"در راه‌های این محدوده حداکثر ۴۰ کیلومتر بر ساعت مجازم، مگر تابلوی دیگری چیز دیگری بگوید.","ok":1,"eda":"Ja. En zonetavle gælder i hele området; lokal skiltning inde i området kan dog fravige den.","efa":"بله. تابلوی منطقه در تمام محدوده برقرار است؛ البته تابلوهای محلی داخل محدوده می‌توانند از آن مستثنا کنند.","en":"I may drive at most 40 km/h on the roads in the area, unless other signs say otherwise.","een":"Yes. A zone sign applies in the whole area; local signs inside the area can depart from it, though."},{"da":"40 km/t er kun en anbefaling.","fa":"۴۰ کیلومتر بر ساعت فقط توصیه است.","ok":0,"eda":"Nej. Den røde kant viser en hastighedsgrænse, ikke en anbefaling.","efa":"خیر. حاشیه‌ی قرمز حد سرعت را نشان می‌دهد، نه توصیه.","en":"40 km/h is only a recommendation.","een":"No. The red border shows a speed limit, not a recommendation."}]},{"id":5270,"img":"newq-art/5270.png","c":"7.3","sda":"Det har sneet, og vejen er glat. Hastighedsgrænsen er 80 km/t. Hvordan forholder du dig?","sfa":"برف باریده و جاده لغزنده است. حد سرعت ۸۰ کیلومتر بر ساعت است. چه می‌کنید؟","sen":"It has snowed and the road is slippery. The speed limit is 80 km/h. What do you do?","st":[{"da":"Jeg bremser, drejer og accelererer blødt.","fa":"نرم ترمز می‌کنم، فرمان می‌دهم و گاز می‌دهم.","ok":1,"eda":"Ja. Bratte bevægelser kan få hjulene til at miste grebet.","efa":"بله. حرکت‌های ناگهانی ممکن است چسبندگی چرخ‌ها را از بین ببرند.","en":"I brake, steer and accelerate gently.","een":"Yes. Abrupt movements can make the wheels lose their grip."},{"da":"Jeg kører langsommere, end grænsen tillader.","fa":"آهسته‌تر از حدِ مجاز می‌رانم.","ok":1,"eda":"Ja. I vådt, glat eller fedtet føre skal du holde en passende lav hastighed.","efa":"بله. در جاده‌ی خیس، لغزنده یا چرب باید سرعت مناسبِ کمی داشته باشید.","en":"I drive more slowly than the limit allows.","een":"Yes. On wet, slippery or greasy roads you must keep a suitably low speed."},{"da":"Så længe jeg kører under 80 km/t, kører jeg efter reglerne.","fa":"تا وقتی زیر ۸۰ کیلومتر بر ساعت برانم، طبق قوانین رانده‌ام.","ok":0,"eda":"Nej. Hastigheden skal altid passe til forholdene; grænsen er kun det højeste, du må køre.","efa":"خیر. سرعت باید همیشه با شرایط جور باشد؛ حد سرعت فقط بیشترین مقدار مجاز است.","en":"As long as I drive below 80 km/h, I am following the rules.","een":"No. Your speed must always suit the conditions; the limit is only the most you may drive."},{"da":"Jeg holder større afstand til bilen foran.","fa":"فاصله‌ام را با خودروی جلویی بیشتر می‌کنم.","ok":1,"eda":"Ja. På glat vej bliver bremselængden meget længere.","efa":"بله. در جاده‌ی لغزنده مسافت ترمز خیلی بیشتر می‌شود.","en":"I keep a greater distance to the car in front.","een":"Yes. On a slippery road the braking distance becomes much longer."}]},{"id":5271,"img":"newq-art/5271.png","c":"7.3","sda":"En landmand driver nogle køer over vejen foran dig. Hvordan forholder du dig?","sfa":"کشاورزی چند گاو را جلوی شما از عرض جاده رد می‌کند. چه می‌کنید؟","sen":"A farmer is driving some cows across the road in front of you. What do you do?","st":[{"da":"Jeg kører forbi i den modsatte vognbane, mens køerne går over.","fa":"در حالی که گاوها رد می‌شوند، از خط مقابل عبور می‌کنم.","ok":0,"eda":"Nej. Køerne går over hele vejen; vent, til vejen er fri.","efa":"خیر. گاوها از تمام عرض جاده رد می‌شوند؛ صبر کنید تا جاده خالی شود.","en":"I drive past in the opposite lane while the cows are crossing.","een":"No. The cows are crossing the whole road; wait until it is clear."},{"da":"Jeg kører videre, for det er landmanden, der skal holde køerne tilbage for trafikken.","fa":"ادامه می‌دهم، چون کشاورز باید گاوها را برای ترافیک نگه دارد.","ok":0,"eda":"Nej. Du skal tage hensyn til dyrene på vejen og om nødvendigt standse.","efa":"خیر. باید مراقب حیوان‌های روی جاده باشید و در صورت لزوم بایستید.","en":"I drive on, as it is the farmer who must hold the cows back for the traffic.","een":"No. You must take care of the animals on the road and stop if necessary."},{"da":"Jeg kører langsomt ind mellem køerne, så de går til side.","fa":"آهسته بین گاوها می‌رانم تا کنار بروند.","ok":0,"eda":"Nej. Dyrene kan blive bange og løbe ind i bilen; vent, til de er kommet over.","efa":"خیر. حیوان‌ها ممکن است بترسند و به خودرو بخورند؛ صبر کنید تا رد شوند.","en":"I drive slowly in among the cows so that they move aside.","een":"No. The animals may get frightened and run into the car; wait until they have crossed."},{"da":"Jeg sænker farten og standser, indtil vejen er fri.","fa":"سرعتم را کم می‌کنم و تا خالی شدن جاده می‌ایستم.","ok":1,"eda":"Ja. Når du nærmer dig kreaturer på vejen, skal du holde en passende lav hastighed og om nødvendigt standse.","efa":"بله. وقتی به دام روی جاده نزدیک می‌شوید، باید سرعت مناسبِ کمی داشته باشید و در صورت لزوم بایستید.","en":"I slow down and stop until the road is clear.","een":"Yes. When you approach cattle on the road, you must keep a suitably low speed and stop if necessary."}]},{"id":5272,"img":"newq-art/5272.png","c":"7.3","sda":"Du kører med en trailer, der er godkendt til 100 km/t på motorvej. Nu kører du på en motortrafikvej, hvor grænsen er skiltet til 90 km/t. Hvad gælder?","sfa":"تریلری می‌کشید که برای ۱۰۰ کیلومتر بر ساعت در آزادراه تأیید شده است. حالا در یک «جاده‌ی ویژه‌ی موتوری» (motortrafikvej) هستید که حد سرعتش با تابلو ۹۰ است. چه قاعده‌ای برقرار است؟","sen":"You are towing a trailer that is approved for 100 km/h on motorways. Now you are on a motor-traffic road where the limit is signed at 90 km/h. What applies?","st":[{"da":"Godkendelsen til 100 km/t gælder kun på motorvej.","fa":"تأییدیه‌ی ۱۰۰ کیلومتر بر ساعت فقط برای آزادراه است.","ok":1,"eda":"Ja. Med en Tempo 100-godkendelse må du køre 100 km/t med trailer på motorvejen.","efa":"بله. با تأییدیه‌ی «تمپو ۱۰۰» می‌توانید در آزادراه با تریلر ۱۰۰ کیلومتر بر ساعت برانید.","en":"The approval for 100 km/h only applies on motorways.","een":"Yes. With a Tempo 100 approval you may drive 100 km/h with a trailer on the motorway."},{"da":"Jeg må køre 90 km/t, fordi tavlen viser 90.","fa":"چون تابلو ۹۰ نشان می‌دهد، می‌توانم ۹۰ برانم.","ok":0,"eda":"Nej. Tavlen gælder den almindelige trafik; med trailer gælder din egen grænse på 80 km/t.","efa":"خیر. تابلو برای ترافیک عادی است؛ با تریلر حد خودتان یعنی ۸۰ برقرار است.","en":"I may drive 90 km/h because the sign shows 90.","een":"No. The sign applies to ordinary traffic; with a trailer your own limit of 80 km/h applies."},{"da":"Jeg må højst køre 80 km/t.","fa":"حداکثر ۸۰ کیلومتر بر ساعت مجازم.","ok":1,"eda":"Ja. Bil med påhængskøretøj må højst køre 80 km/t; 100 km/t gælder kun på motorvej for et godkendt vogntog.","efa":"بله. خودرو با یدک حداکثر ۸۰ کیلومتر بر ساعت مجاز است؛ ۱۰۰ فقط در آزادراه و برای مجموعه‌ی تأییدشده است.","en":"I may drive at most 80 km/h.","een":"Yes. A car with a trailer may drive at most 80 km/h; 100 km/h only applies on motorways to an approved combination."},{"da":"Jeg må køre 100 km/t, fordi traileren er godkendt til det.","fa":"چون تریلر تأیید شده، می‌توانم ۱۰۰ برانم.","ok":0,"eda":"Nej. 100 km/t med trailer er kun tilladt på motorvej.","efa":"خیر. ۱۰۰ کیلومتر بر ساعت با تریلر فقط در آزادراه مجاز است.","en":"I may drive 100 km/h because the trailer is approved for it.","een":"No. 100 km/h with a trailer is only allowed on motorways."}]},{"id":5273,"img":"newq-art/5273.png","c":"1.2","sda":"Under kørslen begynder denne røde advarselslampe at lyse. Hvad gør du?","sfa":"در حین رانندگی این چراغ هشدار قرمز روشن می‌شود. چه می‌کنید؟","sen":"While you are driving, this red warning lamp lights up. What do you do?","st":[{"da":"Jeg standser, så snart det kan ske uden fare, og slukker motoren.","fa":"به محض این‌که بی‌خطر ممکن باشد می‌ایستم و موتور را خاموش می‌کنم.","ok":1,"eda":"Ja. Lampen viser for lavt olietryk, og motoren kan tage alvorlig skade, hvis du kører videre.","efa":"بله. این چراغ فشار کم روغن را نشان می‌دهد و اگر ادامه بدهید ممکن است موتور آسیب جدی ببیند.","en":"I stop as soon as it can be done safely and switch off the engine.","een":"Yes. The lamp shows that the oil pressure is too low, and the engine can be badly damaged if you drive on."},{"da":"Røde og gule advarselslamper betyder det samme.","fa":"چراغ‌های هشدار قرمز و زرد یک معنی دارند.","ok":0,"eda":"Nej. Rød betyder som regel en alvorlig fejl, hvor du skal standse; gul, at noget skal efterses snart.","efa":"خیر. قرمز معمولاً یعنی ایراد جدی و باید بایستید؛ زرد یعنی چیزی باید به‌زودی بررسی شود.","en":"Red and yellow warning lamps mean the same.","een":"No. Red usually means a serious fault where you must stop; yellow that something must be checked soon."},{"da":"Jeg kontrollerer oliestanden eller får hjælp, før jeg kører videre.","fa":"پیش از ادامه دادن، سطح روغن را بررسی می‌کنم یا کمک می‌گیرم.","ok":1,"eda":"Ja. Er der for lidt olie, skal der fyldes på; ellers kan fejlen være alvorlig.","efa":"بله. اگر روغن کم باشد باید اضافه شود؛ وگرنه ممکن است ایراد جدی باشد.","en":"I check the oil level or get help before I drive on.","een":"Yes. If there is too little oil, it must be topped up; otherwise the fault may be serious."},{"da":"Jeg kører videre til næste service, for lampen er kun en påmindelse.","fa":"تا سرویس بعدی ادامه می‌دهم، چون این چراغ فقط یادآوری است.","ok":0,"eda":"Nej. En rød advarselslampe betyder som regel, at du skal standse.","efa":"خیر. چراغ هشدار قرمز معمولاً یعنی باید بایستید.","en":"I drive on until the next service, as the lamp is only a reminder.","een":"No. A red warning lamp usually means that you must stop."}]},{"id":5274,"img":"newq-art/5274.png","c":"1.2","sda":"Du skal på ferie med fem personer, meget bagage og en tagboks. Hvad gælder?","sfa":"با پنج نفر، بار زیاد و یک باکس سقفی به تعطیلات می‌روید. چه قاعده‌ای برقرار است؟","sen":"You are going on holiday with five people, a lot of luggage and a roof box. What applies?","st":[{"da":"Jeg må overskride totalvægten lidt, hvis jeg kører langsomt.","fa":"اگر آهسته برانم، می‌توانم کمی از وزن کل بیشتر بار کنم.","ok":0,"eda":"Nej. Den tilladte totalvægt må ikke overskrides, uanset farten.","efa":"خیر. وزن کل مجاز در هیچ سرعتی نباید رد شود.","en":"I may exceed the total weight a little if I drive slowly.","een":"No. The permitted total weight must not be exceeded, whatever the speed."},{"da":"Med tung last og tagboks bliver bilen mere følsom over for sidevind og i sving.","fa":"با بار سنگین و باکس سقفی، خودرو در برابر باد جانبی و در پیچ‌ها حساس‌تر می‌شود.","ok":1,"eda":"Ja. Tyngdepunktet kommer højere op, og bilen bliver tungere at bremse.","efa":"بله. مرکز ثقل بالاتر می‌رود و ترمز کردن خودرو سخت‌تر می‌شود.","en":"With a heavy load and a roof box the car becomes more sensitive to side wind and in bends.","een":"Yes. The centre of gravity moves up and the car takes longer to stop."},{"da":"Tagboksen må ikke lastes tungere end bilens største tilladte taglast.","fa":"باکس سقفی نباید سنگین‌تر از حداکثر بار مجاز سقف خودرو بار شود.","ok":1,"eda":"Ja. Den største taglast står i bilens instruktionsbog.","efa":"بله. حداکثر بار سقف در دفترچه‌ی راهنمای خودرو آمده است.","en":"The roof box must not be loaded heavier than the car's maximum permitted roof load.","een":"Yes. The maximum roof load is given in the car's handbook."},{"da":"Bilen må ikke veje mere end den tilladte totalvægt, som står i registreringsattesten.","fa":"وزن خودرو نباید از وزن کل مجازی که در برگه‌ی ثبت خودرو آمده بیشتر شود.","ok":1,"eda":"Ja. Den tilladte totalvægt er bilen med fører, passagerer og last; den må ikke overskrides.","efa":"بله. وزن کل مجاز یعنی خودرو با راننده، سرنشینان و بار؛ نباید از آن بیشتر شود.","en":"The car must not weigh more than the permitted total weight shown in the registration certificate.","een":"Yes. The permitted total weight is the car with driver, passengers and load; it must not be exceeded."}]},{"id":5275,"img":"newq-art/5275.png","c":"1.2","sda":"Det regner, og viskerbladene efterlader striber på forruden. Hvad gør du?","sfa":"باران می‌بارد و تیغه‌های برف‌پاک‌کن روی شیشه‌ی جلو رگه به جا می‌گذارند. چه می‌کنید؟","sen":"It is raining and the wiper blades leave streaks on the windscreen. What do you do?","st":[{"da":"Jeg får skiftet viskerbladene, så jeg kan se ordentligt.","fa":"تیغه‌های برف‌پاک‌کن را عوض می‌کنم تا درست ببینم.","ok":1,"eda":"Ja. Slidte viskerblade giver dårligt udsyn, især i mørke og modlys.","efa":"بله. تیغه‌های فرسوده دید را بد می‌کنند، به‌خصوص در تاریکی و نور روبه‌رو.","en":"I have the wiper blades replaced so that I can see properly.","een":"Yes. Worn wiper blades give poor visibility, especially in the dark and against the light."},{"da":"Det gør ikke noget, så længe viskerne bevæger sig.","fa":"تا وقتی برف‌پاک‌کن‌ها کار می‌کنند، مهم نیست.","ok":0,"eda":"Nej. Viskerne skal fjerne vandet, så du har frit udsyn; striber gør det svært at se.","efa":"خیر. برف‌پاک‌کن باید آب را پاک کند تا دید شما آزاد باشد؛ رگه‌ها دیدن را سخت می‌کنند.","en":"It does not matter as long as the wipers move.","een":"No. The wipers must remove the water so that you have a clear view; streaks make it hard to see."},{"da":"Indtil da kører jeg langsommere, fordi jeg ser dårligere.","fa":"تا آن موقع آهسته‌تر می‌رانم، چون دیدم کمتر است.","ok":1,"eda":"Ja. Når sigtbarheden er nedsat, skal du holde en passende lav hastighed.","efa":"بله. وقتی دید کم است، باید سرعت مناسبِ کمی داشته باشید.","en":"Until then I drive more slowly because I can see less well.","een":"Yes. When visibility is reduced, you must keep a suitably low speed."},{"da":"Om vinteren bruger jeg sprinklervæske, der tåler frost.","fa":"در زمستان از مایع شیشه‌شوی ضدیخ استفاده می‌کنم.","ok":1,"eda":"Ja. Almindeligt vand kan fryse i beholderen og på ruden.","efa":"بله. آب معمولی ممکن است در مخزن و روی شیشه یخ بزند.","en":"In winter I use screen wash that can stand frost.","een":"Yes. Plain water can freeze in the reservoir and on the glass."}]},{"id":5276,"img":"newq-art/5276.png","c":"7.7","sda":"En modkørende bil overhaler en lastbil og kommer imod dig i din vognbane. Hvordan forholder du dig?","sfa":"خودرویی از روبه‌رو در حال سبقت از یک کامیون است و در خط شما به سمتتان می‌آید. چه می‌کنید؟","sen":"An oncoming car is overtaking a lorry and coming towards you in your lane. What do you do?","st":[{"da":"Jeg holder så langt til højre, som det kan ske sikkert.","fa":"تا جایی که بی‌خطر باشد به راست می‌روم.","ok":1,"eda":"Ja. Så bliver der mere plads midt på vejen.","efa":"بله. این کار جای بیشتری در وسط جاده باز می‌کند.","en":"I keep as far to the right as can be done safely.","een":"Yes. That leaves more room in the middle of the road."},{"da":"Om nødvendigt standser jeg helt.","fa":"در صورت لزوم کاملاً می‌ایستم.","ok":1,"eda":"Ja. Det er bedre at standse end at risikere et frontalt sammenstød.","efa":"بله. توقف بهتر از خطر برخورد رودررو است.","en":"If necessary I stop completely.","een":"Yes. It is better to stop than to risk a head-on collision."},{"da":"Jeg sænker farten med det samme, så den overhalende kan nå at komme ind.","fa":"فوراً سرعتم را کم می‌کنم تا خودروی سبقت‌گیرنده بتواند به خط خودش برگردد.","ok":1,"eda":"Ja. Jo lavere farten er, jo mere tid og plads bliver der til, at den overhalende kan nå ind.","efa":"بله. هرچه سرعت کمتر باشد، زمان و جای بیشتری برای برگشتن خودروی سبقت‌گیرنده می‌ماند.","en":"I slow down at once so that the overtaking car has time to get back in.","een":"Yes. The lower your speed, the more time and room there is for the overtaking car to get back in."},{"da":"Jeg holder farten og blinker med lyset, for det er den overhalende, der skal vige.","fa":"سرعتم را حفظ می‌کنم و چراغ می‌زنم، چون خودروی سبقت‌گیرنده باید کنار برود.","ok":0,"eda":"Nej. Den overhalende har bedømt situationen forkert, men du skal gøre, hvad du kan, for at undgå et uheld.","efa":"خیر. راننده‌ی سبقت‌گیرنده اشتباه کرده، ولی شما باید هر کاری می‌توانید برای جلوگیری از تصادف انجام دهید.","en":"I keep my speed and flash my lights, as it is the overtaking car that must give way.","een":"No. The overtaking driver has misjudged the situation, but you must do what you can to avoid an accident."}]},{"id":5277,"img":"newq-art/5277.png","c":"7.7","sda":"En traktor med et bredt redskab kommer imod dig på en smal vej. Redskabet fylder mere end traktorens side af vejen. Hvordan forholder du dig?","sfa":"تراکتوری با یک ادوات پهن در جاده‌ای باریک از روبه‌رو می‌آید. ادواتش بیشتر از سهم تراکتور از جاده جا گرفته است. چه می‌کنید؟","sen":"A tractor with a wide implement is coming towards you on a narrow road. The implement takes up more than the tractor's side of the road. What do you do?","st":[{"da":"Jeg kører forbi i samme fart, fordi traktoren skal holde sig i sin egen side.","fa":"با همان سرعت رد می‌شوم، چون تراکتور باید در سمت خودش بماند.","ok":0,"eda":"Nej. Redskabet kan ramme dig; du skal tage hensyn og give plads.","efa":"خیر. ادوات ممکن است به شما بخورد؛ باید ملاحظه کنید و جا بدهید.","en":"I drive past at the same speed, as the tractor must keep to its own side.","een":"No. The implement may hit you; you must take care and give room."},{"da":"Jeg sænker farten, holder helt til højre og standser om nødvendigt, hvor der er plads.","fa":"سرعتم را کم می‌کنم، کاملاً به راست می‌روم و در صورت لزوم جایی که جا هست می‌ایستم.","ok":1,"eda":"Ja. Ved møde på en smal vej skal du holde en passende lav hastighed og give god plads.","efa":"بله. هنگام روبه‌رو شدن در جاده‌ی باریک باید سرعت مناسبِ کمی داشته باشید و جای کافی بدهید.","en":"I slow down, keep right over and stop if necessary where there is room.","een":"Yes. When meeting on a narrow road you must keep a suitably low speed and give plenty of room."},{"da":"Jeg blinker med fjernlyset, så traktoren kører ind til siden.","fa":"با نور بالا چراغ می‌زنم تا تراکتور کنار بکشد.","ok":0,"eda":"Nej. Lyssignal må kun bruges for at advare om fare, og traktoren har måske ingen plads at køre ind på.","efa":"خیر. علامت نوری فقط برای هشدار خطر است و شاید تراکتور جایی برای کنار کشیدن نداشته باشد.","en":"I flash my high beam so that the tractor pulls in to the side.","een":"No. A light signal may only be used to warn of danger, and the tractor may have nowhere to pull in."},{"da":"Traktoren skal standse for mig, fordi den kører langsommere.","fa":"تراکتور باید برای من بایستد، چون کندتر است.","ok":0,"eda":"Nej. Langsomme køretøjer har ikke pligt til at standse for dig; I skal begge vise hensyn.","efa":"خیر. وسایل کُند وظیفه ندارند برایتان بایستند؛ هر دو باید ملاحظه کنید.","en":"The tractor must stop for me because it is slower.","een":"No. Slow vehicles have no duty to stop for you; you must both show consideration."}]},{"id":5278,"img":"newq-art/5278.png","c":"7.7","sda":"Du kører på en smal grusvej, og en bil kommer imod dig. Hvordan forholder du dig?","sfa":"در یک جاده‌ی خاکی باریک رانندگی می‌کنید و خودرویی از روبه‌رو می‌آید. چه می‌کنید؟","sen":"You are driving on a narrow gravel road and a car is coming towards you. What do you do?","st":[{"da":"Jeg holder godt til højre, men passer på, at hjulene ikke glider i det løse grus i kanten.","fa":"به خوبی سمت راست می‌مانم، ولی مراقبم چرخ‌ها در شن‌های شلِ لبه نلغزند.","ok":1,"eda":"Ja. Det løse grus i kanten giver dårligt vejgreb.","efa":"بله. شن‌های شلِ لبه چسبندگی کمی دارند.","en":"I keep well to the right, but take care that the wheels do not slide in the loose gravel at the edge.","een":"Yes. The loose gravel at the edge gives poor grip."},{"da":"På grus er bremselængden kortere end på asfalt.","fa":"روی شن مسافت ترمز کوتاه‌تر از آسفالت است.","ok":0,"eda":"Nej. Bremselængden bliver længere på grus, fordi hjulene har mindre greb.","efa":"خیر. روی شن مسافت ترمز بیشتر می‌شود، چون چرخ‌ها چسبندگی کمتری دارند.","en":"On gravel the braking distance is shorter than on asphalt.","een":"No. The braking distance becomes longer on gravel because the wheels have less grip."},{"da":"Jeg sænker farten, så vi ikke slynger sten op mod hinanden.","fa":"سرعتم را کم می‌کنم تا سنگ‌ریزه به سمت هم پرتاب نکنیم.","ok":1,"eda":"Ja. Ved møde på smal vej skal farten være lav, og på grus kan sten ramme ruder og lak.","efa":"بله. هنگام روبه‌رو شدن در جاده‌ی باریک سرعت باید کم باشد و روی شن، سنگ‌ریزه ممکن است به شیشه و رنگ بخورد.","en":"I slow down so that we do not throw stones up at each other.","een":"Yes. When meeting on a narrow road the speed must be low, and on gravel stones can hit windows and paint."}]},{"id":5279,"img":"newq-art/5279.png","c":"7.7","sda":"I et skarpt sving kommer en lastbil imod dig, og den kommer et stykke over midterlinjen. Hvordan forholder du dig?","sfa":"در یک پیچ تند، کامیونی از روبه‌رو می‌آید و کمی از خط وسط رد شده است. چه می‌کنید؟","sen":"In a sharp bend a lorry is coming towards you, and it is some way over the centre line. What do you do?","st":[{"da":"Jeg sænker farten og holder helt ind til højre.","fa":"سرعتم را کم می‌کنم و کاملاً به راست می‌روم.","ok":1,"eda":"Ja. Et langt køretøj har brug for plads i et skarpt sving; giv det plads og vær klar til at standse.","efa":"بله. وسیله‌ی بلند در پیچ تند جا لازم دارد؛ به آن جا بدهید و آماده‌ی توقف باشید.","en":"I slow down and keep well in to the right.","een":"Yes. A long vehicle needs room in a sharp bend; give it room and be ready to stop."},{"da":"Jeg bliver midt i min vognbane, for det er lastbilen, der kører forkert.","fa":"در وسط خط خودم می‌مانم، چون کامیون اشتباه می‌کند.","ok":0,"eda":"Nej. Du skal gøre, hvad du kan, for at undgå et sammenstød.","efa":"خیر. باید هر کاری می‌توانید برای جلوگیری از برخورد انجام دهید.","en":"I stay in the middle of my lane, as it is the lorry that is in the wrong.","een":"No. You must do what you can to avoid a collision."},{"da":"Jeg skærer selv svinget, så jeg hurtigere kommer forbi lastbilen.","fa":"خودم هم پیچ را میان‌بر می‌زنم تا زودتر از کنار کامیون رد شوم.","ok":0,"eda":"Nej. Så kommer du endnu tættere på lastbilen; hold dig til højre.","efa":"خیر. این‌طور به کامیون نزدیک‌تر می‌شوید؛ سمت راست بمانید.","en":"I cut the bend myself so that I get past the lorry sooner.","een":"No. Then you get even closer to the lorry; keep to the right."},{"da":"Jeg accelererer, så jeg er forbi lastbilen, før svinget bliver skarpest.","fa":"گاز می‌دهم تا پیش از تندترین قسمت پیچ از کامیون رد شوم.","ok":0,"eda":"Nej. Høj fart i svinget giver mindre tid og plads; sæt farten ned.","efa":"خیر. سرعت زیاد در پیچ زمان و جای کمتری می‌دهد؛ سرعت را کم کنید.","en":"I accelerate so that I am past the lorry before the bend gets sharpest.","een":"No. High speed in the bend gives less time and room; slow down."}]},{"id":5280,"img":"newq-art/5280.png","c":"7.4","sda":"Du kører i højre vognbane på motorvejen. En bil på accelerationsbanen skal ind på motorvejen lige ved siden af dig. Hvordan forholder du dig?","sfa":"در خط راست آزادراه هستید. خودرویی در خط شتاب‌گیری درست کنار شما می‌خواهد وارد آزادراه شود. چه می‌کنید؟","sen":"You are in the right lane on the motorway. A car on the acceleration lane is about to join the motorway right beside you. What do you do?","st":[{"da":"Kan jeg ikke skifte vognbane, tilpasser jeg farten, så der bliver et hul.","fa":"اگر نتوانم خط عوض کنم، سرعتم را طوری تنظیم می‌کنم که فاصله‌ای باز شود.","ok":1,"eda":"Ja. Så kan bilen glide ind foran eller bag dig.","efa":"بله. این‌طور آن خودرو می‌تواند جلو یا پشت شما وارد شود.","en":"If I cannot change lanes, I adjust my speed so that a gap opens.","een":"Yes. Then the car can slip in in front of or behind you."},{"da":"Jeg accelererer, så bilen ikke kommer ind foran mig.","fa":"گاز می‌دهم تا آن خودرو جلوی من وارد نشود.","ok":0,"eda":"Nej. Det gør det sværere og farligere for bilen at komme ind.","efa":"خیر. این کار ورود آن خودرو را سخت‌تر و خطرناک‌تر می‌کند.","en":"I speed up so that the car does not get in in front of me.","een":"No. That makes it harder and more dangerous for the car to join."},{"da":"Jeg letter indkørslen, fx ved at skifte til venstre vognbane, hvis den er fri.","fa":"ورودش را آسان می‌کنم، مثلاً اگر خط چپ خالی باشد به آن می‌روم.","ok":1,"eda":"Ja. Den, der kører i vognbanen ved accelerationsbanen, skal så vidt muligt lette indkørslen.","efa":"بله. کسی که در خطِ کنار خط شتاب‌گیری می‌راند، باید تا جای ممکن ورود را آسان کند.","en":"I make it easier for it to join, for example by moving into the left lane if it is free.","een":"Yes. Whoever is driving in the lane by the acceleration lane must make the joining easier where possible."},{"da":"Bilen på accelerationsbanen skal altid vente, til motorvejen er helt fri.","fa":"خودروی خط شتاب‌گیری همیشه باید صبر کند تا آزادراه کاملاً خالی شود.","ok":0,"eda":"Nej. Den skal tilpasse farten og køre ind, når det kan ske uden fare, og trafikken skal lette det.","efa":"خیر. باید سرعتش را تنظیم کند و وقتی بی‌خطر شد وارد شود، و ترافیک هم باید ورود را آسان کند.","en":"The car on the acceleration lane must always wait until the motorway is completely free.","een":"No. It must adjust its speed and join when it can do so safely, and the traffic must make it easier."}]},{"id":5281,"img":"newq-art/5281.png","c":"7.4","sda":"Du er havnet i vognbanen med pil til højre, men du skal ligeud. Linjen mellem vognbanerne er ubrudt. Hvad gælder?","sfa":"در خطی قرار گرفته‌اید که فلش به راست دارد، ولی می‌خواهید مستقیم بروید. خط بین خط‌های عبور ممتد است. چه قاعده‌ای برقرار است؟","sen":"You have ended up in the lane with an arrow to the right, but you are going straight on. The line between the lanes is unbroken. What applies?","st":[{"da":"Jeg må køre ligeud fra højre vognbane, når der ikke kommer nogen.","fa":"اگر کسی نیاید، می‌توانم از خط راست مستقیم بروم.","ok":0,"eda":"Nej. Du skal følge pilen, uanset trafikken.","efa":"خیر. باید فلش را دنبال کنید، ترافیک هر چه باشد.","en":"I may go straight on from the right lane when nobody is coming.","een":"No. You must follow the arrow, whatever the traffic."},{"da":"Jeg må skifte over den ubrudte linje i sidste øjeblik, hvis jeg blinker.","fa":"اگر راهنما بزنم، می‌توانم در آخرین لحظه از روی خط ممتد خط عوض کنم.","ok":0,"eda":"Nej. Den ubrudte linje må ikke overskrides, og et sent vognbaneskift er farligt.","efa":"خیر. نباید از خط ممتد رد شد و تغییر خط دیرهنگام خطرناک است.","en":"I may change across the unbroken line at the last moment if I signal.","een":"No. The unbroken line must not be crossed, and a late lane change is dangerous."},{"da":"Jeg svinger til højre, som pilen viser, og finder en anden vej tilbage.","fa":"همان‌طور که فلش نشان می‌دهد به راست می‌پیچم و راه دیگری برای برگشتن پیدا می‌کنم.","ok":1,"eda":"Ja. Pile foran et kryds angiver, at de kørende i vognbanen skal følge pilens retning.","efa":"بله. فلش‌های پیش از تقاطع یعنی رانندگانِ آن خط باید جهت فلش را دنبال کنند.","en":"I turn right as the arrow shows and find another way back.","een":"Yes. Arrows before a junction show that drivers in that lane must follow the arrow's direction."},{"da":"Jeg standser ved krydset og venter på et hul i venstre vognbane.","fa":"کنار تقاطع می‌ایستم و منتظر فاصله‌ای در خط چپ می‌مانم.","ok":0,"eda":"Nej. En unødig standsning overrasker dem bag dig, og du må alligevel ikke skifte over den ubrudte linje.","efa":"خیر. توقف بی‌جا پشت‌سری‌ها را غافلگیر می‌کند و در هر حال نباید از روی خط ممتد خط عوض کنید.","en":"I stop at the junction and wait for a gap in the left lane.","een":"No. A needless stop surprises those behind you, and you may not change across the unbroken line anyway."}]},{"id":5282,"img":"newq-art/5282.png","c":"7.4","sda":"Du vil skifte fra venstre vognbane til midtervognbanen på motorvejen. En bil i højre vognbane blinker også for at komme over i midtervognbanen. Hvordan forholder du dig?","sfa":"در آزادراه می‌خواهید از خط چپ به خط وسط بروید. خودرویی در خط راست هم راهنما زده تا به خط وسط بیاید. چه می‌کنید؟","sen":"You want to move from the left lane to the middle lane on the motorway. A car in the right lane is also signalling to move into the middle lane. What do you do?","st":[{"da":"Jeg ser over skulderen, før jeg skifter vognbane.","fa":"پیش از تغییر خط از روی شانه نگاه می‌کنم.","ok":1,"eda":"Ja. En bil kan være i den blinde vinkel, hvor spejlene ikke viser den.","efa":"بله. ممکن است خودرویی در نقطه‌ی کور باشد که آینه‌ها نشانش نمی‌دهند.","en":"I look over my shoulder before I change lanes.","een":"Yes. A car may be in the blind spot where the mirrors do not show it."},{"da":"Jeg giver tegn i god tid, før jeg skifter vognbane.","fa":"به موقع پیش از تغییر خط راهنما می‌زنم.","ok":1,"eda":"Ja. På motorvej skal du give tegn før vognbaneskift.","efa":"بله. در آزادراه پیش از تغییر خط باید راهنما بزنید.","en":"I signal in good time before I change lanes.","een":"Yes. On the motorway you must signal before changing lanes."},{"da":"Jeg har ret til midtervognbanen, fordi jeg kommer fra venstre.","fa":"حق خط وسط با من است، چون از چپ می‌آیم.","ok":0,"eda":"Nej. Ingen af jer har ret til vognbanen før den anden; begge skal sikre sig, at skiftet kan ske uden fare.","efa":"خیر. هیچ‌کس حق تقدم خط را ندارد؛ هر دو باید مطمئن شوند تغییر خط بی‌خطر است.","en":"I have the right to the middle lane because I am coming from the left.","een":"No. Neither has priority to the lane; both must make sure the change can be made safely."},{"da":"Jeg venter med at skifte, til jeg er sikker på, at den anden bil ikke kommer over ved siden af mig.","fa":"صبر می‌کنم تا مطمئن شوم آن خودرو کنار من به خط وسط نمی‌آید، بعد خط عوض می‌کنم.","ok":1,"eda":"Ja. Et vognbaneskift må kun ske, når det kan ske uden fare eller ulempe for andre.","efa":"بله. تغییر خط فقط وقتی مجاز است که برای دیگران خطر یا مزاحمتی نداشته باشد.","en":"I wait to change until I am sure the other car is not coming over beside me.","een":"Yes. A lane change may only be made when it can be done without danger or inconvenience to others."}]},{"id":5283,"img":"newq-art/5283.png","c":"7.1","sda":"Du holder parkeret tæt bag en anden bil ved kantstenen og skal køre ud. Hvordan forholder du dig?","sfa":"کنار جدول، درست پشت خودروی دیگری پارک کرده‌اید و می‌خواهید حرکت کنید. چه می‌کنید؟","sen":"You are parked close behind another car at the kerb and are going to pull out. What do you do?","st":[{"da":"Jeg ser i spejlet og over venstre skulder, før jeg kører ud.","fa":"پیش از حرکت در آینه و از روی شانه‌ی چپ نگاه می‌کنم.","ok":1,"eda":"Ja. Du må kun køre ud, når det kan ske uden fare eller ulempe for andre, og spejlet viser ikke alt.","efa":"بله. فقط وقتی می‌توانید حرکت کنید که برای دیگران خطر یا مزاحمتی نداشته باشد، و آینه همه چیز را نشان نمی‌دهد.","en":"I look in the mirror and over my left shoulder before I pull out.","een":"Yes. You may only pull out when it can be done without danger or inconvenience to others, and the mirror does not show everything."},{"da":"Jeg giver tegn, før jeg kører ud fra kanten.","fa":"پیش از حرکت از کنار جدول راهنما می‌زنم.","ok":1,"eda":"Ja. Du skal give tegn før igangsætning fra kanten af vejen.","efa":"بله. پیش از حرکت از کنار جاده باید راهنما بزنید.","en":"I signal before I pull out from the kerb.","een":"Yes. You must signal before pulling away from the edge of the road."},{"da":"Jeg passer på, at fronten af min bil ikke rammer bilen foran, når jeg drejer ud.","fa":"مراقبم جلوی خودرویم هنگام بیرون آمدن به خودروی جلویی نخورد.","ok":1,"eda":"Ja. Når du drejer ud tæt bag en bil, svinger din front ud mod den.","efa":"بله. وقتی درست پشت خودرویی فرمان می‌دهید، جلوی خودروی شما به سمت آن می‌چرخد.","en":"I take care that the front of my car does not hit the car in front as I turn out.","een":"Yes. When you turn out close behind a car, your front swings out towards it."},{"da":"Jeg kører ud, når der er et lille hul, og lader de andre bremse for mig.","fa":"وقتی فاصله‌ی کوچکی پیدا شد بیرون می‌روم و می‌گذارم بقیه برایم ترمز کنند.","ok":0,"eda":"Nej. Andre må ikke tvinges til at bremse eller svinge ud for dig.","efa":"خیر. دیگران نباید مجبور شوند برای شما ترمز کنند یا منحرف شوند.","en":"I pull out when there is a small gap and let the others brake for me.","een":"No. Others must not be forced to brake or swerve for you."}]},{"id":5284,"img":"newq-art/5284.png","c":"7.1","sda":"Du holder i venstre side af en ensrettet gade og vil køre ud. Hvordan forholder du dig?","sfa":"در سمت چپ یک خیابان یک‌طرفه پارک کرده‌اید و می‌خواهید حرکت کنید. چه می‌کنید؟","sen":"You are parked on the left side of a one-way street and want to pull out. What do you do?","st":[{"da":"Jeg ser over højre skulder efter trafik bagfra, før jeg kører ud.","fa":"پیش از حرکت، از روی شانه‌ی راست ترافیک پشت سر را نگاه می‌کنم.","ok":1,"eda":"Ja. Når du holder i venstre side, kommer trafikken bagfra forbi på din højre side.","efa":"بله. وقتی در سمت چپ ایستاده‌اید، ترافیکِ پشت سر از سمت راست شما رد می‌شود.","en":"I look over my right shoulder for traffic from behind before I pull out.","een":"Yes. When you are on the left side, traffic from behind passes on your right."},{"da":"Jeg giver tegn til venstre, fordi jeg holder i venstre side.","fa":"راهنمای چپ می‌زنم، چون در سمت چپ ایستاده‌ام.","ok":0,"eda":"Nej. Tegnet viser den retning, du vil køre i; her er det mod højre.","efa":"خیر. راهنما جهتی را نشان می‌دهد که می‌خواهید به آن بروید؛ اینجا راست است.","en":"I signal left because I am standing on the left side.","een":"No. The signal shows the direction you are going to move in; here it is to the right."},{"da":"I en ensrettet gade kommer der ingen bagfra, så jeg behøver ikke se mig for.","fa":"در خیابان یک‌طرفه کسی از پشت نمی‌آید، پس لازم نیست نگاه کنم.","ok":0,"eda":"Nej. Al trafikken i gaden kommer netop bagfra.","efa":"خیر. همه‌ی ترافیک این خیابان دقیقاً از پشت می‌آید.","en":"In a one-way street nobody comes from behind, so I need not look.","een":"No. All the traffic in the street comes precisely from behind."},{"da":"Jeg giver tegn til højre, fordi jeg kører ud mod højre.","fa":"راهنمای راست می‌زنم، چون به سمت راست حرکت می‌کنم.","ok":1,"eda":"Ja. Tegnet skal vise, hvilken vej du kører ud fra kanten.","efa":"بله. راهنما باید نشان بدهد از کنار جاده به کدام سمت حرکت می‌کنید.","en":"I signal right because I am pulling out to the right.","een":"Yes. The signal must show which way you are pulling away from the edge."}]},{"id":5285,"img":"newq-art/5285.png","c":"7.1","sda":"Du holder ved kantstenen på en isglat gade og vil køre ud. Hjulene begynder at spinde. Hvordan forholder du dig?","sfa":"کنار جدول در خیابانی یخ‌زده ایستاده‌اید و می‌خواهید حرکت کنید. چرخ‌ها شروع به سُر خوردن می‌کنند. چه می‌کنید؟","sen":"You are at the kerb on an icy street and want to pull out. The wheels begin to spin. What do you do?","st":[{"da":"Jeg starter med hjulene lige og drejer først, når bilen ruller.","fa":"با چرخ‌های صاف حرکت را شروع می‌کنم و وقتی خودرو راه افتاد فرمان می‌دهم.","ok":1,"eda":"Ja. Lige hjul får bedre fat end drejede.","efa":"بله. چرخ صاف بهتر از چرخ چرخیده می‌گیرد.","en":"I start with the wheels straight and only steer once the car is rolling.","een":"Yes. Straight wheels grip better than turned ones."},{"da":"Spinder hjulene, er det et tegn på, at jeg skal give mere gas.","fa":"اگر چرخ‌ها درجا بچرخند، یعنی باید بیشتر گاز بدهم.","ok":0,"eda":"Nej. Det er omvendt: giv mindre gas.","efa":"خیر. برعکس است: گاز کمتری بدهید.","en":"If the wheels spin, it is a sign that I must give more throttle.","een":"No. It is the other way round: give less throttle."},{"da":"Jeg giver fuld gas, så bilen hurtigt kommer ud.","fa":"تا ته گاز می‌دهم تا خودرو زود بیرون برود.","ok":0,"eda":"Nej. Fuld gas får hjulene til at spinde endnu mere, og bilen kan skride ud.","efa":"خیر. گاز کامل چرخ‌ها را بیشتر می‌چرخاند و خودرو ممکن است بلغزد.","en":"I put my foot down so that the car gets out quickly.","een":"No. Full throttle makes the wheels spin even more, and the car may slide out."},{"da":"Jeg giver mindre gas, så hjulene kan få fat.","fa":"گاز را کم می‌کنم تا چرخ‌ها بتوانند بگیرند.","ok":1,"eda":"Ja. Spinder hjulene, har de mistet grebet; mindre gas giver dem greb igen.","efa":"بله. چرخی که می‌چرخد و جلو نمی‌رود چسبندگی‌اش را از دست داده؛ گاز کمتر آن را برمی‌گرداند.","en":"I ease off the accelerator so that the wheels can grip.","een":"Yes. Spinning wheels have lost their grip; less throttle gives them grip again."}]},{"id":5286,"img":"newq-art/5286.png","c":"7.2","sda":"Den højre vognbane er afmærket med »BUS« og adskilt fra din med en ubrudt linje. Du kører i en almindelig bil. Hvad gælder?","sfa":"خط راست با «BUS» علامت‌گذاری شده و با یک خط ممتد از خط شما جدا شده است. با یک خودروی معمولی رانندگی می‌کنید. چه قاعده‌ای برقرار است؟","sen":"The right lane is marked «BUS» and separated from yours by an unbroken line. You are driving an ordinary car. What applies?","st":[{"da":"Busbanen må bruges af alle biler uden for myldretiden.","fa":"خارج از ساعت شلوغی، همه‌ی خودروها می‌توانند از خط اتوبوس استفاده کنند.","ok":0,"eda":"Nej. Afmærkningen gælder hele døgnet, når der ikke er andet skiltet.","efa":"خیر. این علامت‌گذاری در تمام شبانه‌روز برقرار است، مگر تابلویی چیز دیگری بگوید.","en":"The bus lane may be used by all cars outside the rush hours.","een":"No. The marking applies round the clock unless something else is signed."},{"da":"Jeg skal blive i den venstre vognbane.","fa":"باید در خط چپ بمانم.","ok":1,"eda":"Ja. Vognbanen med »BUS« må kun bruges af busser i rutekørsel, og af dem, som symboler i banen ellers giver lov.","efa":"بله. خطی که «BUS» دارد فقط برای اتوبوس‌های خطی است و برای کسانی که نمادهای دیگرِ داخل خط اجازه بدهند.","en":"I must stay in the left lane.","een":"Yes. The lane marked «BUS» may only be used by buses on regular routes, and by those that other symbols in the lane allow."},{"da":"Jeg må køre i busbanen, når der ikke kommer en bus.","fa":"اگر اتوبوسی نیاید، می‌توانم در خط اتوبوس برانم.","ok":0,"eda":"Nej. Busbanen er forbeholdt busser, også når der ikke er nogen.","efa":"خیر. خط اتوبوس حتی وقتی اتوبوسی نیست برای اتوبوس‌ها نگه داشته شده است.","en":"I may drive in the bus lane when no bus is coming.","een":"No. The bus lane is reserved for buses, also when there are none."},{"da":"Der kan køre cyklister i busbanen.","fa":"ممکن است دوچرخه‌سوارها در خط اتوبوس برانند.","ok":1,"eda":"Ja. Cyklister og førere af lille knallert skal bruge en busbane, der ligger til højre.","efa":"بله. دوچرخه‌سواران و موپدسواران کوچک باید از خط اتوبوسِ سمت راست استفاده کنند.","en":"There may be cyclists riding in the bus lane.","een":"Yes. Cyclists and riders of small mopeds must use a bus lane on the right."}]},{"id":5287,"img":"newq-art/5287.png","c":"7.2","sda":"Du kører forbi en lang række parkerede biler. Hvordan placerer du bilen?","sfa":"از کنار ردیف بلندی از خودروهای پارک‌شده رد می‌شوید. خودرو را چطور قرار می‌دهید؟","sen":"You are driving past a long row of parked cars. How do you position the car?","st":[{"da":"Jeg holder øje med folk i bilerne og med børn, der kan komme frem mellem dem.","fa":"مراقب آدم‌های داخل خودروها و بچه‌هایی هستم که ممکن است از بینشان بیرون بیایند.","ok":1,"eda":"Ja. De parkerede biler skjuler gående, især små børn.","efa":"بله. خودروهای پارک‌شده عابران، به‌خصوص بچه‌های کوچک، را پنهان می‌کنند.","en":"I watch for people in the cars and for children who may come out between them.","een":"Yes. The parked cars hide pedestrians, especially small children."},{"da":"Jeg holder så meget afstand, at jeg ikke rammer en dør, der pludselig bliver åbnet.","fa":"آن‌قدر فاصله می‌گیرم که اگر دری ناگهان باز شد، به آن نخورم.","ok":1,"eda":"Ja. En bildør kan åbnes uden varsel; hold cirka en dørs bredde fra bilerne, hvis der er plads.","efa":"بله. در خودرو ممکن است بی‌خبر باز شود؛ اگر جا هست، حدود عرض یک در فاصله بگیرید.","en":"I keep enough distance not to hit a door that is suddenly opened.","een":"Yes. A car door can open without warning; keep about a door's width from the cars if there is room."},{"da":"Jeg kører helt tæt på de parkerede biler, så de modkørende får bedre plads.","fa":"کاملاً نزدیک خودروهای پارک‌شده می‌رانم تا ترافیک روبه‌رو جای بیشتری داشته باشد.","ok":0,"eda":"Nej. Tæt på de parkerede biler har du ingen plads, hvis en dør åbnes eller nogen træder ud.","efa":"خیر. نزدیکِ خودروهای پارک‌شده، اگر دری باز شود یا کسی بیرون بیاید، جایی ندارید.","en":"I drive right next to the parked cars so that the oncoming traffic has more room.","een":"No. Close to the parked cars you have no room if a door opens or someone steps out."}]},{"id":5288,"img":"newq-art/5288.png","c":"7.2","sda":"Langs højre side af vejen er der en ubrudt kantlinje og uden for den en smal asfalteret kant. Hvad gælder?","sfa":"در سمت راست جاده یک خط کناری ممتد هست و بیرون آن یک نوار آسفالتِ باریک. چه قاعده‌ای برقرار است؟","sen":"Along the right side of the road there is an unbroken edge line and outside it a narrow paved strip. What applies?","st":[{"da":"Jeg kører inden for kantlinjen.","fa":"داخل خط کناری می‌رانم.","ok":1,"eda":"Ja. Den ubrudte kantlinje afgrænser den del af kørebanen, der er beregnet til motorkøretøjer.","efa":"بله. خط کناری ممتد بخشی از سواره‌رو را که برای وسایل موتوری است مشخص می‌کند.","en":"I drive inside the edge line.","een":"Yes. The unbroken edge line marks off the part of the carriageway meant for motor vehicles."},{"da":"Jeg må køre over kantlinjen, når jeg skal standse eller parkere.","fa":"وقتی می‌خواهم توقف یا پارک کنم، می‌توانم از خط کناری رد شوم.","ok":1,"eda":"Ja. Motorkøretøjer må krydse kantlinjen for at standse, parkere eller køre ind på eller ud fra vejen.","efa":"بله. وسایل موتوری برای توقف، پارک یا ورود و خروج از جاده می‌توانند از خط کناری رد شوند.","en":"I may cross the edge line when I am going to stop or park.","een":"Yes. Motor vehicles may cross the edge line to stop, park, or drive onto or off the road."},{"da":"Uden for kantlinjen kan der gå fodgængere og køre cyklister.","fa":"بیرون خط کناری ممکن است عابر پیاده و دوچرخه‌سوار باشد.","ok":1,"eda":"Ja. Kanten uden for linjen bruges ofte af gående og cyklister.","efa":"بله. نوار بیرون خط اغلب محل رفت‌وآمد عابران و دوچرخه‌سواران است.","en":"Outside the edge line there may be pedestrians walking and cyclists riding.","een":"Yes. The strip outside the line is often used by pedestrians and cyclists."},{"da":"Jeg må køre uden for kantlinjen, hvis det går hurtigere.","fa":"اگر سریع‌تر باشد، می‌توانم بیرون خط کناری برانم.","ok":0,"eda":"Nej. Kanten uden for linjen er ikke til almindelig kørsel med bil.","efa":"خیر. نوار بیرون خط برای رانندگی معمولی با خودرو نیست.","en":"I may drive outside the edge line if it is quicker.","een":"No. The strip outside the line is not for ordinary driving by car."}]},{"id":5289,"img":"newq-art/5289.png","c":"7.19","sda":"Du kører med fjernlys på en mørk vej, der løber langs en jernbane. Et tog kommer imod dig på sporet. Hvad gælder?","sfa":"با نور بالا در جاده‌ای تاریک کنار راه‌آهن رانندگی می‌کنید. قطاری روی ریل از روبه‌رو می‌آید. چه قاعده‌ای برقرار است؟","sen":"You are driving with high beam on a dark road running alongside a railway. A train is coming towards you on the track. What applies?","st":[{"da":"Jeg slukker alt lyset, indtil toget er kørt forbi.","fa":"تا رد شدن قطار همه‌ی چراغ‌ها را خاموش می‌کنم.","ok":0,"eda":"Nej. Du skal bruge nærlys; i mørke skal de påbudte lygter være tændt.","efa":"خیر. باید از نور پایین استفاده کنید؛ در تاریکی چراغ‌های الزامی باید روشن باشند.","en":"I switch off all my lights until the train has passed.","een":"No. You must use dipped beam; in the dark the required lights must be on."},{"da":"Jeg må beholde fjernlyset, fordi toget ikke kører på vejen.","fa":"می‌توانم نور بالا را نگه دارم، چون قطار روی جاده نیست.","ok":0,"eda":"Nej. Reglen gælder også tog langs vejen.","efa":"خیر. این قاعده قطارهای کنار جاده را هم شامل می‌شود.","en":"I may keep the high beam because the train is not on the road.","een":"No. The rule also covers trains alongside the road."},{"da":"Jeg blænder ned, så lokomotivføreren ikke bliver blændet.","fa":"نور را پایین می‌آورم تا راننده‌ی قطار خیره نشود.","ok":1,"eda":"Ja. Fjernlys må ikke bruges ved møde med tog, der kører langs vejen, hvis det kan blænde.","efa":"بله. هنگام روبه‌رو شدن با قطاری که کنار جاده حرکت می‌کند، اگر خطر خیرگی باشد نباید نور بالا زد.","en":"I dip my lights so that the train driver is not dazzled.","een":"Yes. High beam must not be used when meeting a train running alongside the road if it may dazzle."},{"da":"Jeg tænder tågelygterne i stedet for nærlyset.","fa":"به جای نور پایین، چراغ مه‌شکن را روشن می‌کنم.","ok":0,"eda":"Nej. Tågelygter må kun bruges i tåge og kraftig nedbør.","efa":"خیر. چراغ مه‌شکن فقط در مه و بارش شدید مجاز است.","en":"I switch on the fog lights instead of the dipped beam.","een":"No. Fog lights may only be used in fog and heavy precipitation."}]},{"id":5290,"img":"newq-art/5290.png","c":"7.19","sda":"Det er midt på dagen, men tåge og regn gør det svært at se. Hvad gælder om lyset?","sfa":"وسط روز است، ولی مه و باران دیدن را سخت کرده‌اند. درباره‌ی چراغ‌ها چه قاعده‌ای برقرار است؟","sen":"It is the middle of the day, but fog and rain make it hard to see. What applies to the lights?","st":[{"da":"Er sigtbarheden meget nedsat af tåge, må jeg bruge tågelygterne.","fa":"اگر مه دید را خیلی کم کرده باشد، می‌توانم از چراغ مه‌شکن استفاده کنم.","ok":1,"eda":"Ja. Tågelygter må bruges i tåge og under kraftig nedbør.","efa":"بله. چراغ مه‌شکن در مه و بارش شدید مجاز است.","en":"If visibility is much reduced by fog, I may use the fog lights.","een":"Yes. Fog lights may be used in fog and in heavy precipitation."},{"da":"Kørelys er altid nok om dagen, uanset vejret.","fa":"روز، چراغ روز همیشه کافی است، هوا هر طور که باشد.","ok":0,"eda":"Nej. Når sigtbarheden er dårlig, skal de påbudte lygter være tændt.","efa":"خیر. وقتی دید کم است، چراغ‌های الزامی باید روشن باشند.","en":"Daytime running lights are always enough by day, whatever the weather.","een":"No. When visibility is poor, the required lights must be on."},{"da":"Det er lygtetændingstid, så de påbudte lygter skal være tændt.","fa":"اکنون «زمان روشن کردن چراغ‌ها» است و چراغ‌های الزامی باید روشن باشند.","ok":1,"eda":"Ja. Lygtetændingstid er også, når tåge, regn eller lignende gør lygterne nødvendige for at blive set eller for at se.","efa":"بله. «زمان روشن کردن چراغ‌ها» شامل وقتی هم می‌شود که مه، باران و مانند آن چراغ را برای دیده شدن یا دیدن لازم کنند.","en":"It is lighting-up time, so the required lights must be on.","een":"Yes. Lighting-up time also covers times when fog, rain or the like make the lights necessary to be seen or to see."},{"da":"Jeg tænder nærlyset, så baglygterne også lyser.","fa":"نور پایین را روشن می‌کنم تا چراغ‌های عقب هم روشن شوند.","ok":1,"eda":"Ja. Kørelys alene tænder ofte ikke baglygterne, og så kan bilen være svær at se bagfra.","efa":"بله. چراغ روز به‌تنهایی اغلب چراغ‌های عقب را روشن نمی‌کند و خودرو از پشت سخت دیده می‌شود.","en":"I switch on the dipped beam so that the rear lights are lit too.","een":"Yes. Daytime running lights alone often do not light the rear lights, and then the car can be hard to see from behind."}]},{"id":5291,"img":"newq-art/5291.png","c":"7.19","sda":"Det er mørkt, og bilen bag dig kører tæt på med fjernlys, så du bliver blændet i spejlet. Hvad gælder?","sfa":"هوا تاریک است و خودروی پشتی با نور بالا نزدیک شما می‌آید و در آینه خیره‌تان می‌کند. چه قاعده‌ای برقرار است؟","sen":"It is dark, and the car behind you is close with its high beam on, so you are dazzled in the mirror. What applies?","st":[{"da":"Jeg kan vippe bakspejlet til nattestilling.","fa":"می‌توانم آینه‌ی وسط را روی حالت شب بگذارم.","ok":1,"eda":"Ja. Nattestillingen dæmper lyset fra bilen bag dig.","efa":"بله. حالت شب نور خودروی پشتی را کم می‌کند.","en":"I can tilt the rear-view mirror to its night setting.","een":"Yes. The night setting dims the light from the car behind you."},{"da":"Føreren bag mig må ikke bruge fjernlys, når det kan blænde mig.","fa":"راننده‌ی پشتی وقتی ممکن است مرا خیره کند، نباید نور بالا بزند.","ok":1,"eda":"Ja. Fjernlys må ikke bruges bag et andet køretøj, hvis føreren foran kan blændes.","efa":"بله. پشت وسیله‌ی دیگر، اگر راننده‌ی جلویی خیره شود، نباید نور بالا زد.","en":"The driver behind me must not use high beam when it can dazzle me.","een":"Yes. High beam must not be used behind another vehicle if its driver can be dazzled."},{"da":"Jeg tænder tågebaglygten, så føreren bliver blændet tilbage.","fa":"چراغ مه‌شکن عقب را روشن می‌کنم تا راننده هم خیره شود.","ok":0,"eda":"Nej. Tågebaglygten må kun bruges i tåge og kraftig nedbør, og lygter må ikke bruges, så andre blændes.","efa":"خیر. چراغ مه‌شکن عقب فقط در مه و بارش شدید مجاز است و نباید چراغ را طوری به کار برد که دیگران خیره شوند.","en":"I switch on the rear fog light so that the driver is dazzled back.","een":"No. The rear fog light may only be used in fog and heavy precipitation, and lights must not be used so that others are dazzled."},{"da":"Jeg bremser hårdt, så føreren lærer at blænde ned.","fa":"محکم ترمز می‌کنم تا راننده یاد بگیرد نورش را پایین بیاورد.","ok":0,"eda":"Nej. Du må ikke bremse pludseligt uden grund; det kan give en påkørsel bagfra.","efa":"خیر. نباید بی‌دلیل ناگهان ترمز کنید؛ ممکن است از پشت با شما تصادف شود.","en":"I brake hard so that the driver learns to dip.","een":"No. You must not brake suddenly without reason; it can cause a rear-end collision."}]},{"id":5292,"img":"newq-art/5292.png","c":"7.16","sda":"Din bil får motorstop på motorvejen. Hvad gør du?","sfa":"خودروی شما در آزادراه خاموش می‌شود و از کار می‌افتد. چه می‌کنید؟","sen":"Your car breaks down on the motorway. What do you do?","st":[{"da":"Jeg får så vidt muligt bilen ud af kørebanen, fx ind i nødsporet, og tænder havariblinket.","fa":"تا جای ممکن خودرو را از سواره‌رو بیرون می‌برم، مثلاً به خط اضطراری، و چراغ خطر را روشن می‌کنم.","ok":1,"eda":"Ja. Et køretøj, der må standse på motorvejen, skal så vidt muligt placeres uden for kørebanen og fjernes snarest muligt.","efa":"بله. وسیله‌ای که مجبور به توقف در آزادراه شود، باید تا جای ممکن بیرون از سواره‌رو قرار بگیرد و هرچه زودتر برده شود.","en":"I get the car off the carriageway as far as possible, for example onto the hard shoulder, and switch on the hazard lights.","een":"Yes. A vehicle that has to stop on the motorway must be placed off the carriageway as far as possible and removed as soon as possible."},{"da":"Står bilen, hvor den kan være til fare, advarer jeg de andre, fx med en advarselstrekant langt bag bilen.","fa":"اگر خودرو جایی ایستاده که ممکن است خطرناک باشد، به دیگران هشدار می‌دهم، مثلاً با مثلث هشدار در فاصله‌ی زیادی پشت خودرو.","ok":1,"eda":"Ja. Andre trafikanter skal advares i god tid; på motorvej sættes trekanten omkring 100 m bag bilen.","efa":"بله. باید به موقع به دیگران هشدار داد؛ در آزادراه مثلث را حدود ۱۰۰ متر پشت خودرو می‌گذارند.","en":"If the car stands where it can be a danger, I warn the others, for example with a warning triangle well behind the car.","een":"Yes. Other road users must be warned in good time; on the motorway the triangle is put about 100 m behind the car."},{"da":"Jeg reparerer bilen i nødsporet, så længe det tager.","fa":"هر قدر طول بکشد، خودرو را در خط اضطراری تعمیر می‌کنم.","ok":0,"eda":"Nej. Reparation på stedet må kun ske, hvis den er nødvendig for at få bilen hurtigt væk fra motorvejen.","efa":"خیر. تعمیر در محل فقط وقتی مجاز است که برای بردن سریع خودرو از آزادراه لازم باشد.","en":"I repair the car on the hard shoulder for as long as it takes.","een":"No. Repairs on the spot may only be done if they are needed to get the car off the motorway quickly."},{"da":"Jeg og passagererne stiger ud i højre side og venter bag autoværnet.","fa":"من و سرنشینان از سمت راست پیاده می‌شویم و پشت گاردریل منتظر می‌مانیم.","ok":1,"eda":"Ja. I nødsporet er I tæt på trafikken; bag autoværnet er I i sikkerhed.","efa":"بله. در خط اضطراری به ترافیک نزدیکید؛ پشت گاردریل در امانید.","en":"The passengers and I get out on the right side and wait behind the crash barrier.","een":"Yes. On the hard shoulder you are close to the traffic; behind the crash barrier you are safe."}]},{"id":5293,"img":"newq-art/5293.png","c":"7.16","sda":"På motorvejen kører du forbi denne tavle. Hvad betyder den?","sfa":"در آزادراه از کنار این تابلو می‌گذرید. معنی‌اش چیست؟","sen":"On the motorway you pass this sign. What does it mean?","st":[{"da":"Det er en rasteplads, hvor jeg kan holde pause og spise.","fa":"این یک استراحتگاه است که می‌توانم آنجا استراحت کنم و غذا بخورم.","ok":0,"eda":"Nej. Nødpladsen er kun til nødsituationer; til pauser bruger du en rasteplads.","efa":"خیر. جای توقف اضطراری فقط برای اضطرار است؛ برای استراحت از استراحتگاه استفاده کنید.","en":"It is a rest area where I can take a break and eat.","een":"No. The emergency lay-by is only for emergencies; for breaks you use a rest area."},{"da":"Der kommer en nødplads, hvor jeg kan standse i en nødsituation.","fa":"جلوتر یک جای توقف اضطراری هست که در شرایط اضطراری می‌توانم آنجا بایستم.","ok":1,"eda":"Ja. Tavlen angiver en nødplads, der kan bruges ved nødstop.","efa":"بله. این تابلو جای توقف اضطراری را نشان می‌دهد که برای توقف اضطراری است.","en":"An emergency lay-by is coming where I can stop in an emergency.","een":"Yes. The sign shows an emergency lay-by that can be used for emergency stops."},{"da":"Jeg må holde der for at ringe til en ven.","fa":"می‌توانم آنجا بایستم و به دوستم زنگ بزنم.","ok":0,"eda":"Nej. På motorvejen må du kun standse på parkerings- og rastepladser, ved en nødtelefon for at bruge den, eller når du er tvunget til det.","efa":"خیر. در آزادراه فقط در پارکینگ‌ها و استراحتگاه‌ها، کنار تلفن اضطراری برای استفاده از آن، یا وقتی ناچار باشید می‌توانید بایستید.","en":"I may stop there to call a friend.","een":"No. On the motorway you may only stop at car parks and rest areas, at an emergency phone to use it, or when you are forced to."}]},{"id":5294,"img":"newq-art/5294.png","c":"6.2","sda":"Du kører i venstre vognbane på motorvejen, selv om der er plads i højre. En bil kommer hurtigt op bag dig. Hvordan forholder du dig?","sfa":"در آزادراه در خط چپ می‌رانید، با این‌که خط راست جا دارد. خودرویی با سرعت از پشت به شما نزدیک می‌شود. چه می‌کنید؟","sen":"You are driving in the left lane on the motorway although there is room in the right one. A car is coming up fast behind you. What do you do?","st":[{"da":"Jeg bliver i venstre vognbane, så bilen kan overhale mig i højre side.","fa":"در خط چپ می‌مانم تا آن خودرو بتواند از سمت راستم سبقت بگیرد.","ok":0,"eda":"Nej. Overhaling skal ske til venstre; giv plads ved at køre til højre.","efa":"خیر. سبقت باید از چپ باشد؛ با رفتن به راست جا باز کنید.","en":"I stay in the left lane so that the car can overtake me on the right.","een":"No. Overtaking must be done on the left; make room by moving to the right."},{"da":"Jeg bliver i venstre vognbane, fordi jeg holder hastighedsgrænsen.","fa":"در خط چپ می‌مانم، چون حد سرعت را رعایت می‌کنم.","ok":0,"eda":"Nej. Du skal holde til højre, også når du kører lovligt hurtigt.","efa":"خیر. حتی وقتی با سرعت مجاز می‌رانید، باید سمت راست بمانید.","en":"I stay in the left lane because I am keeping to the speed limit.","een":"No. You must keep right, also when you are driving at a lawful speed."},{"da":"Jeg bremser lidt, så bilen bag mig holder større afstand.","fa":"کمی ترمز می‌کنم تا خودروی پشتی فاصله‌ی بیشتری بگیرد.","ok":0,"eda":"Nej. Du må ikke bremse pludseligt uden grund; det kan give en påkørsel bagfra.","efa":"خیر. نباید بی‌دلیل ناگهان ترمز کنید؛ ممکن است از پشت با شما تصادف شود.","en":"I brake a little so that the car behind me keeps a greater distance.","een":"No. You must not brake suddenly without reason; it can cause a rear-end collision."},{"da":"Jeg skifter til højre vognbane, så snart det kan ske uden fare.","fa":"به محض این‌که بی‌خطر ممکن باشد، به خط راست می‌روم.","ok":1,"eda":"Ja. Du skal holde så langt til højre som muligt; venstre vognbane er til overhaling.","efa":"بله. باید تا جای ممکن سمت راست بمانید؛ خط چپ برای سبقت است.","en":"I move into the right lane as soon as it can be done safely.","een":"Yes. You must keep as far to the right as possible; the left lane is for overtaking."}]},{"id":5295,"img":"newq-art/5295.png","c":"5.2","sda":"Det regner kraftigt, og der står vand i hjulsporene. Hvad skal du være opmærksom på?","sfa":"باران شدید می‌بارد و در شیارهای چرخ آب جمع شده است. به چه چیزی باید توجه کنید؟","sen":"It is raining heavily and water is standing in the wheel ruts. What must you be aware of?","st":[{"da":"Jeg sænker farten, så dækkene bedre kan fjerne vandet.","fa":"سرعتم را کم می‌کنم تا تایرها بهتر آب را کنار بزنند.","ok":1,"eda":"Ja. Jo højere fart, jo større risiko for vandplaning.","efa":"بله. هرچه سرعت بیشتر باشد، خطر آکواپلنینگ بیشتر است.","en":"I slow down so that the tyres can clear the water better.","een":"Yes. The higher the speed, the greater the risk of aquaplaning."},{"da":"Mærker jeg, at rattet bliver let, slipper jeg speederen og holder rattet lige.","fa":"اگر حس کنم فرمان سبک شده، پایم را از پدال گاز برمی‌دارم و فرمان را صاف نگه می‌دارم.","ok":1,"eda":"Ja. Så kan dækkene få fat igen; en hård opbremsning eller et ryk i rattet kan få bilen til at skride.","efa":"بله. این‌طور تایرها دوباره می‌گیرند؛ ترمز شدید یا چرخاندن ناگهانی فرمان ممکن است خودرو را بلغزاند.","en":"If I feel the steering go light, I take my foot off the accelerator and hold the wheel straight.","een":"Yes. Then the tyres can grip again; hard braking or a jerk of the wheel can make the car skid."},{"da":"Slidte dæk har ingen betydning, når vandet er lavt.","fa":"وقتی آب کم‌عمق است، تایر فرسوده اهمیتی ندارد.","ok":0,"eda":"Nej. Jo mindre mønster, jo dårligere fjerner dækket vandet.","efa":"خیر. هرچه آج کمتر باشد، تایر آب را بدتر کنار می‌زند.","en":"Worn tyres do not matter when the water is shallow.","een":"No. The less tread, the worse the tyre clears the water."},{"da":"Bilen kan begynde at flyde på vandet, så jeg ikke kan styre eller bremse.","fa":"خودرو ممکن است روی آب سُر بخورد و نتوانم فرمان بدهم یا ترمز کنم.","ok":1,"eda":"Ja. Ved vandplaning kan dækkene ikke nå at fjerne vandet og mister kontakten med vejen.","efa":"بله. در «آکواپلنینگ» تایرها نمی‌توانند آب را به‌موقع کنار بزنند و تماسشان با جاده قطع می‌شود.","en":"The car may start to float on the water so that I cannot steer or brake.","een":"Yes. In aquaplaning the tyres cannot clear the water fast enough and lose contact with the road."}]},{"id":5296,"img":"newq-art/5296.png","c":"5.2","sda":"Du kører over en lang bro i kraftig blæst fra siden. Hvordan forholder du dig?","sfa":"در باد شدیدِ جانبی از روی یک پل طولانی می‌گذرید. چه می‌کنید؟","sen":"You are driving over a long bridge in a strong side wind. What do you do?","st":[{"da":"Med tagboks eller trailer bliver min bil mere følsom for sidevind.","fa":"با باکس سقفی یا تریلر، خودروی من در برابر باد جانبی حساس‌تر می‌شود.","ok":1,"eda":"Ja. Jo større flade vinden kan tage fat i, jo mere skubbes bilen.","efa":"بله. هرچه سطحی که باد به آن می‌خورد بزرگ‌تر باشد، خودرو بیشتر رانده می‌شود.","en":"With a roof box or a trailer my car becomes more sensitive to side wind.","een":"Yes. The bigger the surface the wind can catch, the more the car is pushed."},{"da":"Jeg sænker farten og holder godt fast i rattet.","fa":"سرعتم را کم می‌کنم و فرمان را محکم نگه می‌دارم.","ok":1,"eda":"Ja. Et vindstød kan skubbe bilen til siden.","efa":"بله. تندباد ممکن است خودرو را به کنار هل بدهد.","en":"I slow down and hold the steering wheel firmly.","een":"Yes. A gust can push the car sideways."},{"da":"En høj vogn foran mig kan blive skubbet til siden, så jeg holder god afstand til den.","fa":"وسیله‌ی بلند جلوی من ممکن است به کنار رانده شود، پس فاصله‌ی زیادی با آن نگه می‌دارم.","ok":1,"eda":"Ja. Høje køretøjer fanger mere vind.","efa":"بله. وسایل بلند باد بیشتری می‌گیرند.","en":"A tall vehicle in front of me may be pushed sideways, so I keep a good distance to it.","een":"Yes. Tall vehicles catch more wind."},{"da":"Jeg er forberedt på et vindstød, når jeg kommer ud af læ, fx forbi en lastbil eller for enden af broen.","fa":"وقتی از پناه بیرون می‌آیم، مثلاً پس از رد شدن از کنار کامیون یا در انتهای پل، آماده‌ی تندباد هستم.","ok":1,"eda":"Ja. Vinden rammer pludseligt, når læet forsvinder.","efa":"بله. وقتی پناه از بین برود، باد ناگهان می‌وزد.","en":"I am prepared for a gust when I come out of shelter, for example past a lorry or at the end of the bridge.","een":"Yes. The wind hits suddenly when the shelter disappears."}]},{"id":5297,"img":"newq-art/5297.png","c":"7.8","sda":"Du standser bag en bil i en kø. Hvor langt bag den holder du?","sfa":"در صف پشت خودرویی می‌ایستید. چقدر عقب‌تر از آن می‌ایستید؟","sen":"You stop behind a car in a queue. How far behind it do you stand?","st":[{"da":"Helt tæt, så der kan være flere biler i køen.","fa":"کاملاً نزدیک، تا خودروهای بیشتری در صف جا شوند.","ok":0,"eda":"Nej. Helt tæt på har du ingen plads til at komme fri eller undgå et uheld.","efa":"خیر. اگر خیلی نزدیک بایستید، جایی برای خارج شدن یا اجتناب از تصادف ندارید.","en":"Right up close, so that there is room for more cars in the queue.","een":"No. Right up close you have no room to get clear or to avoid an accident."},{"da":"Så jeg kan køre uden om den, hvis den går i stå.","fa":"به اندازه‌ای که اگر خاموش شد، بتوانم از کنارش رد شوم.","ok":1,"eda":"Ja. Med lidt plads foran dig kan du komme fri, og en påkørsel bagfra skubber dig ikke ind i den.","efa":"بله. با کمی جا در جلو می‌توانید خارج شوید و اگر از پشت به شما بزنند، به آن خودرو کوبیده نمی‌شوید.","en":"So that I can drive round it if it breaks down.","een":"Yes. With a little room in front of you, you can get clear, and a shunt from behind does not push you into it."},{"da":"Så langt, at jeg kan se dens baghjul og lidt af asfalten bag dem.","fa":"آن‌قدر عقب که چرخ‌های عقبش و کمی از آسفالت پشت آن‌ها را ببینم.","ok":1,"eda":"Ja. Det er en god tommelfingerregel for afstanden, når du holder i kø.","efa":"بله. این یک قاعده‌ی سرانگشتی خوب برای فاصله در صف است.","en":"Far enough back that I can see its rear wheels and a little of the road behind them.","een":"Yes. That is a good rule of thumb for the distance when you are standing in a queue."}]},{"id":5298,"img":"newq-art/5298.png","c":"7.8","sda":"Du kører bag en stor lastbil på landevejen. Hvordan forholder du dig?","sfa":"در جاده‌ی بیرون شهر پشت یک کامیون بزرگ رانندگی می‌کنید. چه می‌کنید؟","sen":"You are driving behind a big lorry on a country road. What do you do?","st":[{"da":"Kan jeg ikke se lastbilens spejle, kan føreren heller ikke se mig.","fa":"اگر آینه‌های کامیون را نبینم، راننده هم مرا نمی‌بیند.","ok":1,"eda":"Ja. Holder du afstand, ser lastbilens fører dig i sine spejle.","efa":"بله. اگر فاصله بگیرید، راننده‌ی کامیون شما را در آینه‌هایش می‌بیند.","en":"If I cannot see the lorry's mirrors, the driver cannot see me either.","een":"Yes. If you keep your distance, the lorry driver sees you in the mirrors."},{"da":"Jeg kører tæt bag den for at spare brændstof i læet.","fa":"نزدیکش می‌رانم تا در پناه آن سوخت کمتری مصرف کنم.","ok":0,"eda":"Nej. Afstanden skal være så stor, at du kan standse, hvis lastbilen bremser.","efa":"خیر. فاصله باید آن‌قدر باشد که اگر کامیون ترمز کرد، بتوانید بایستید.","en":"I drive close behind it to save fuel in its slipstream.","een":"No. The distance must be large enough for you to stop if the lorry brakes."},{"da":"Jeg kører tæt bag den, så jeg er klar til at overhale med det samme.","fa":"نزدیکش می‌رانم تا بلافاصله آماده‌ی سبقت باشم.","ok":0,"eda":"Nej. Tæt bag lastbilen kan du netop ikke se, om vejen er fri til overhaling.","efa":"خیر. پشتِ نزدیکِ کامیون دقیقاً نمی‌بینید که جاده برای سبقت خالی است یا نه.","en":"I drive close behind it so that I am ready to overtake at once.","een":"No. Close behind the lorry you precisely cannot see whether the road is clear for overtaking."},{"da":"Jeg holder god afstand, så jeg kan se forbi lastbilen og se, hvad der sker foran.","fa":"فاصله‌ی زیادی نگه می‌دارم تا بتوانم از کنار کامیون جلوتر را ببینم.","ok":1,"eda":"Ja. Tæt bag lastbilen skjuler den alt foran dig.","efa":"بله. پشتِ نزدیکِ کامیون، همه‌ی جلوی شما پنهان می‌ماند.","en":"I keep a good distance so that I can see past the lorry and what is happening ahead.","een":"Yes. Close behind the lorry, it hides everything in front of you."}]},{"id":5299,"img":"newq-art/5299.png","c":"7.5","sda":"Du vil bakke ind i en parkeringsbås. Bilen har bakkamera. Hvad gælder?","sfa":"می‌خواهید با دنده‌عقب در یک جای پارک بروید. خودرو دوربین دنده‌عقب دارد. چه قاعده‌ای برقرار است؟","sen":"You want to reverse into a parking bay. The car has a reversing camera. What applies?","st":[{"da":"Jeg ser mig også selv for og stoler ikke kun på kameraet.","fa":"خودم هم اطراف را نگاه می‌کنم و فقط به دوربین تکیه نمی‌کنم.","ok":1,"eda":"Ja. Kameraet viser ikke alt; et barn kan være uden for billedet.","efa":"بله. دوربین همه چیز را نشان نمی‌دهد؛ ممکن است کودکی بیرون از تصویر باشد.","en":"I look around myself too and do not rely only on the camera.","een":"Yes. The camera does not show everything; a child may be outside the picture."},{"da":"Jeg skal sikre mig, at bakningen kan ske uden fare eller ulempe for andre.","fa":"باید مطمئن شوم دنده‌عقب رفتن برای دیگران خطر یا مزاحمتی ندارد.","ok":1,"eda":"Ja. Den, der bakker, har ansvaret for, at det sker uden fare.","efa":"بله. کسی که دنده‌عقب می‌رود، مسئول بی‌خطر بودن آن است.","en":"I must make sure the reversing can be done without danger or inconvenience to others.","een":"Yes. Whoever reverses is responsible for doing it safely."},{"da":"Gående skal holde tilbage for mig, når baklygterne lyser.","fa":"وقتی چراغ دنده‌عقبم روشن است، عابران باید برایم صبر کنند.","ok":0,"eda":"Nej. Baklygterne advarer kun; det er dig, der skal holde tilbage.","efa":"خیر. چراغ دنده‌عقب فقط هشدار است؛ این شما هستید که باید صبر کنید.","en":"Pedestrians must give way to me when my reversing lights are on.","een":"No. The reversing lights only warn; it is you who must give way."},{"da":"Mens jeg bakker, behøver jeg ikke have sikkerhedsselen på.","fa":"هنگام دنده‌عقب رفتن لازم نیست کمربند ایمنی بسته باشم.","ok":1,"eda":"Ja. Pligten til at bruge sikkerhedssele gælder ikke ved bakning.","efa":"بله. الزام بستن کمربند ایمنی هنگام دنده‌عقب برقرار نیست.","en":"While I am reversing, I need not wear my seat belt.","een":"Yes. The duty to wear a seat belt does not apply when reversing."}]},{"id":5300,"img":"newq-art/5300.png","c":"5.1","sda":"Du kører forbi denne tavle i et boligområde. Hvad betyder den?","sfa":"در یک محله‌ی مسکونی از کنار این تابلو می‌گذرید. معنی‌اش چیست؟","sen":"You pass this sign in a residential area. What does it mean?","st":[{"da":"Bumpene er kun for lastbiler og busser.","fa":"سرعت‌گیرها فقط برای کامیون و اتوبوس است.","ok":0,"eda":"Nej. Bumpene gælder al trafik på vejen.","efa":"خیر. سرعت‌گیرها برای همه‌ی ترافیک جاده است.","en":"The humps are only for lorries and buses.","een":"No. The humps are for all traffic on the road."},{"da":"Jeg kan køre over bumpene i samme fart, når min bil er ny.","fa":"اگر خودرویم نو باشد، می‌توانم با همان سرعت از روی سرعت‌گیرها رد شوم.","ok":0,"eda":"Nej. Bumpene er lavet til lav fart; i høj fart kan du miste herredømmet og skade bilen.","efa":"خیر. سرعت‌گیرها برای سرعت کم ساخته شده‌اند؛ با سرعت زیاد ممکن است کنترل را از دست بدهید و خودرو آسیب ببیند.","en":"I can drive over the humps at the same speed when my car is new.","een":"No. The humps are made for low speed; at high speed you may lose control and damage the car."},{"da":"Tavlen betyder, at vejen er ujævn på grund af vejarbejde.","fa":"این تابلو یعنی جاده به خاطر کار راهسازی ناهموار است.","ok":0,"eda":"Nej. Vejarbejde har sin egen advarselstavle.","efa":"خیر. کار راهسازی تابلوی هشدار خودش را دارد.","en":"The sign means that the road is uneven because of road works.","een":"No. Road works have their own warning sign."},{"da":"Der er bump på vejen længere fremme, som skal få trafikken til at køre langsomt.","fa":"کمی جلوتر روی جاده سرعت‌گیر هست که برای کند کردن ترافیک است.","ok":1,"eda":"Ja. Tavlen angiver hastighedsdæmpende bump på vejen.","efa":"بله. این تابلو سرعت‌گیرهای روی جاده را نشان می‌دهد.","en":"There are humps on the road further ahead, meant to make the traffic go slowly.","een":"Yes. The sign shows speed-reducing humps on the road."}]},{"id":5301,"img":"newq-art/5301.png","c":"7.18","sda":"Du vil parkere på en parkeringsplads med afmærkede båse. Hvad gælder?","sfa":"می‌خواهید در پارکینگی با جاهای خط‌کشی‌شده پارک کنید. چه قاعده‌ای برقرار است؟","sen":"You want to park in a car park with marked bays. What applies?","st":[{"da":"Jeg må godt holde hen over to båse, når der er mange ledige.","fa":"وقتی جاهای خالی زیاد است، می‌توانم روی دو جا پارک کنم.","ok":0,"eda":"Nej. Bilen skal holde inden for én bås, uanset hvor mange der er ledige.","efa":"خیر. خودرو باید داخل یک جا بایستد، هر چقدر هم جای خالی باشد.","en":"I may stand across two bays when many are free.","een":"No. The car must stand inside one bay, however many are free."},{"da":"Bilen skal holde inden for båsens linjer.","fa":"خودرو باید داخل خط‌های جای پارک بایستد.","ok":1,"eda":"Ja. Ved parkering i afmærkede parkeringsbåse skal køretøjet parkeres inden for båsen.","efa":"بله. هنگام پارک در جاهای خط‌کشی‌شده، خودرو باید داخل همان جا پارک شود.","en":"The car must stand inside the bay's lines.","een":"Yes. When parking in marked bays, the vehicle must be parked inside the bay."},{"da":"Hjulene må gerne stå på en bred kantlinje ud mod kørebanen, men ikke ud over den.","fa":"چرخ‌ها می‌توانند روی خط کناری پهنِ سمت سواره‌رو باشند، ولی نه بیرون از آن.","ok":1,"eda":"Ja. Ved båse langs vejen med en bred kantlinje ud mod kørebanen må hjulene stå på linjen, ikke uden for den.","efa":"بله. در جاهای پارکِ کنار جاده که خط کناری پهن به سمت سواره‌رو دارند، چرخ‌ها می‌توانند روی خط باشند، نه بیرون آن.","en":"The wheels may stand on a broad edge line towards the carriageway, but not beyond it.","een":"Yes. With bays along the road and a broad edge line towards the carriageway, the wheels may stand on the line, not outside it."},{"da":"Jeg holder, så de andre kan komme ind i deres biler.","fa":"طوری پارک می‌کنم که دیگران بتوانند سوار خودروهایشان شوند.","ok":1,"eda":"Ja. Det er forbudt at parkere, så adgangen til et andet køretøj hindres.","efa":"بله. پارک به شکلی که دسترسی به خودروی دیگر را ببندد ممنوع است.","en":"I park so that the others can get into their cars.","een":"Yes. It is forbidden to park so that access to another vehicle is blocked."}]},{"id":5302,"img":"newq-art/5302.png","c":"7.18","sda":"Langs kantstenen er der en stiplet gul linje. Du vil sætte en passager af og derefter køre videre. Hvad gælder?","sfa":"کنار جدول یک خط زرد خط‌چین هست. می‌خواهید مسافری را پیاده کنید و بعد ادامه دهید. چه قاعده‌ای برقرار است؟","sen":"Along the kerb there is a broken yellow line. You want to let a passenger out and then drive on. What applies?","st":[{"da":"Jeg må godt standse et øjeblik og lade passageren stige ud.","fa":"می‌توانم کوتاه بایستم تا مسافر پیاده شود.","ok":1,"eda":"Ja. Den stiplede gule linje angiver parkeringsforbud, og standsning for af- og påstigning er ikke parkering.","efa":"بله. خط زرد خط‌چین ممنوعیت پارک را نشان می‌دهد و توقف برای سوار و پیاده شدن پارک حساب نمی‌شود.","en":"I may stop briefly to let the passenger out.","een":"Yes. The broken yellow line marks a parking ban, and stopping to let people in or out is not parking."},{"da":"Jeg må parkere her i op til en time.","fa":"می‌توانم تا یک ساعت اینجا پارک کنم.","ok":0,"eda":"Nej. Parkering er forbudt langs den stiplede gule linje.","efa":"خیر. پارک کنار خط زرد خط‌چین ممنوع است.","en":"I may park here for up to an hour.","een":"No. Parking is forbidden along the broken yellow line."},{"da":"En ubrudt gul linje ville betyde, at jeg slet ikke må standse.","fa":"خط زرد ممتد یعنی اصلاً نمی‌توانم توقف کنم.","ok":1,"eda":"Ja. Den ubrudte gule linje angiver standsningsforbud.","efa":"بله. خط زرد ممتد ممنوعیت توقف را نشان می‌دهد.","en":"An unbroken yellow line would mean that I may not stop at all.","een":"Yes. The unbroken yellow line marks a stopping ban."},{"da":"Den stiplede gule linje betyder, at der kommer et fodgængerfelt.","fa":"خط زرد خط‌چین یعنی جلوتر گذرگاه عابر پیاده هست.","ok":0,"eda":"Nej. Gule linjer langs kantstenen handler om standsning og parkering.","efa":"خیر. خط‌های زرد کنار جدول مربوط به توقف و پارک‌اند.","en":"The broken yellow line means that a pedestrian crossing is coming.","een":"No. Yellow lines along the kerb are about stopping and parking."}]},{"id":5303,"img":"newq-art/5303.png","c":"7.18","sda":"Ved kantstenen er der en afmærket holdeplads for taxier. Den er tom. Du vil standse og hente en ven. Hvad gælder?","sfa":"کنار جدول یک ایستگاه تاکسیِ خط‌کشی‌شده هست که خالی است. می‌خواهید بایستید و دوستتان را سوار کنید. چه قاعده‌ای برقرار است؟","sen":"At the kerb there is a marked taxi stand. It is empty. You want to stop and pick up a friend. What applies?","st":[{"da":"Jeg må ikke standse på taxiholdepladsen.","fa":"نباید در ایستگاه تاکسی توقف کنم.","ok":1,"eda":"Ja. Det er forbudt at standse eller parkere på en afmærket holdeplads for hyrevogne.","efa":"بله. توقف یا پارک در ایستگاه تاکسیِ خط‌کشی‌شده ممنوع است.","en":"I must not stop on the taxi stand.","een":"Yes. Stopping or parking on a marked taxi stand is forbidden."},{"da":"Jeg må standse kort, hvis jeg bliver siddende i bilen.","fa":"اگر داخل خودرو بمانم، می‌توانم کوتاه بایستم.","ok":0,"eda":"Nej. Forbuddet gælder enhver standsning, også med føreren i bilen.","efa":"خیر. این ممنوعیت هر توقفی را شامل می‌شود، حتی اگر راننده داخل خودرو باشد.","en":"I may stop briefly if I stay in the car.","een":"No. The ban covers every stop, also with the driver in the car."},{"da":"Jeg må standse, fordi der ikke holder nogen taxier.","fa":"چون تاکسی‌ای آنجا نیست، می‌توانم بایستم.","ok":0,"eda":"Nej. Forbuddet gælder også, når holdepladsen er tom.","efa":"خیر. این ممنوعیت وقتی ایستگاه خالی است هم برقرار است.","en":"I may stop because no taxis are there.","een":"No. The ban also applies when the stand is empty."}]},{"id":5304,"img":"newq-art/5304.png","c":"7.18","sda":"Din passager vil stige ud ved et hus, der ligger ved rundkørslen. Du overvejer at standse i rundkørslen. Hvad gælder?","sfa":"مسافرتان می‌خواهد کنار خانه‌ای که کنار میدان است پیاده شود. به توقف در میدان فکر می‌کنید. چه قاعده‌ای برقرار است؟","sen":"Your passenger wants to get out at a house beside the roundabout. You are thinking of stopping in the roundabout. What applies?","st":[{"da":"Det er tilladt, hvis passageren skynder sig.","fa":"اگر مسافر عجله کند، مجاز است.","ok":0,"eda":"Nej. Forbuddet gælder enhver standsning, også en kort.","efa":"خیر. این ممنوعیت هر توقفی را شامل می‌شود، حتی کوتاه.","en":"It is allowed if the passenger hurries.","een":"No. The ban covers every stop, also a short one."},{"da":"Jeg må standse helt ude i kanten af rundkørslen, hvis jeg tænder havariblinket.","fa":"اگر چراغ خطر را روشن کنم، می‌توانم کاملاً لبه‌ی میدان بایستم.","ok":0,"eda":"Nej. Havariblinket gør ikke standsning tilladt, hvor den er forbudt.","efa":"خیر. چراغ خطر توقف را در جایی که ممنوع است مجاز نمی‌کند.","en":"I may stop right at the roundabout's edge if I switch on the hazard lights.","een":"No. The hazard lights do not make stopping allowed where it is forbidden."},{"da":"Jeg kører ud af rundkørslen og standser et lovligt sted, mindst 10 m fra krydset.","fa":"از میدان بیرون می‌روم و جایی مجاز، دست‌کم ۱۰ متر دورتر از تقاطع، می‌ایستم.","ok":1,"eda":"Ja. Standsning er forbudt i et vejkryds og nærmere end 10 m fra den tværgående kørebanes kant.","efa":"بله. توقف در تقاطع و کمتر از ۱۰ متر از لبه‌ی سواره‌روی عرضی ممنوع است.","en":"I leave the roundabout and stop at a lawful place, at least 10 m from the junction.","een":"Yes. Stopping is forbidden in a junction and closer than 10 m to the edge of the crossing carriageway."},{"da":"Det er forbudt at standse i rundkørslen.","fa":"توقف در میدان ممنوع است.","ok":1,"eda":"Ja. En rundkørsel er et vejkryds, og i vejkryds er standsning og parkering forbudt.","efa":"بله. میدان یک تقاطع است و توقف و پارک در تقاطع ممنوع است.","en":"Stopping in the roundabout is forbidden.","een":"Yes. A roundabout is a junction, and in a junction stopping and parking are forbidden."}]},{"id":5305,"img":"newq-art/5305.png","c":"7.18","sda":"Du har parkeret ved kantstenen i en befærdet gade. To børn på bagsædet skal ud. Hvordan forholder du dig?","sfa":"در خیابانی شلوغ کنار جدول پارک کرده‌اید. دو کودک روی صندلی عقب می‌خواهند پیاده شوند. چه می‌کنید؟","sen":"You have parked at the kerb in a busy street. Two children on the back seat are getting out. What do you do?","st":[{"da":"Det er hurtigst at lade dem stige ud i vejsiden, hvor døren er nærmest.","fa":"سریع‌تر است از سمت خیابان پیاده شوند، چون در به آن‌ها نزدیک‌تر است.","ok":0,"eda":"Nej. I vejsiden kan de blive ramt af den forbikørende trafik.","efa":"خیر. در سمت خیابان ممکن است ترافیک عبوری به آن‌ها بزند.","en":"It is quickest to let them out on the street side, where the door is nearest.","een":"No. On the street side they can be hit by passing traffic."},{"da":"Jeg lader børnene stige ud i fortovssiden.","fa":"می‌گذارم بچه‌ها از سمت پیاده‌رو پیاده شوند.","ok":1,"eda":"Ja. Afstigning skal ske uden fare; i fortovssiden er børnene væk fra trafikken.","efa":"بله. پیاده شدن باید بی‌خطر باشد؛ در سمت پیاده‌رو بچه‌ها از ترافیک دورند.","en":"I let the children get out on the pavement side.","een":"Yes. Getting out must be done without danger; on the pavement side the children are away from the traffic."},{"da":"Jeg bruger børnesikringen i bagdørene, så de ikke åbner døren i vejsiden.","fa":"قفل کودک درهای عقب را فعال می‌کنم تا در سمت خیابان را باز نکنند.","ok":1,"eda":"Ja. Børn kan åbne døren uden at se sig for.","efa":"بله. بچه‌ها ممکن است بدون نگاه کردن در را باز کنند.","en":"I use the child locks in the rear doors so that they do not open the door on the street side.","een":"Yes. Children may open the door without looking."},{"da":"Jeg holder øje med cyklister og gående, når dørene åbnes.","fa":"هنگام باز شدن درها مراقب دوچرخه‌سواران و عابران هستم.","ok":1,"eda":"Ja. Døre skal åbnes, så der ikke opstår fare eller unødig ulempe for andre.","efa":"بله. درها باید طوری باز شوند که برای دیگران خطر یا مزاحمتی پیش نیاید.","en":"I watch out for cyclists and pedestrians when the doors are opened.","een":"Yes. Doors must be opened so that there is no danger or undue inconvenience to others."}]},{"id":5306,"img":"newq-art/5306.png","c":"7.18","sda":"Du har parkeret med P-skive på en plads, hvor du må holde 2 timer. Tiden er snart gået, men du er ikke færdig med at handle. Hvad gælder?","sfa":"با صفحه‌ی ساعت پارک (P-skive) جایی پارک کرده‌اید که ۲ ساعت مجاز است. وقت تقریباً تمام است، ولی خریدتان تمام نشده. چه قاعده‌ای برقرار است؟","sen":"You have parked with a parking disc at a place where you may stay 2 hours. The time is nearly up, but you have not finished shopping. What applies?","st":[{"da":"P-skiven skal ligge lige inden for forruden, så den kan læses udefra.","fa":"صفحه‌ی ساعت پارک باید درست پشت شیشه‌ی جلو باشد تا از بیرون خوانده شود.","ok":1,"eda":"Ja. Skiven skal anbringes umiddelbart inden for forruden og tydeligt kunne aflæses udefra.","efa":"بله. صفحه باید درست پشت شیشه‌ی جلو گذاشته شود و از بیرون به‌روشنی خوانده شود.","en":"The parking disc must lie just inside the windscreen so that it can be read from outside.","een":"Yes. The disc must be placed immediately inside the windscreen and be clearly readable from outside."},{"da":"Jeg skal køre bilen væk, inden de 2 timer er gået.","fa":"باید پیش از پایان ۲ ساعت خودرو را از آنجا ببرم.","ok":1,"eda":"Ja. Parkeringen skal ophøre senest, når den tilladte tid er udløbet.","efa":"بله. پارک باید حداکثر تا پایان مدت مجاز تمام شود.","en":"I must drive the car away before the 2 hours are up.","een":"Yes. The parking must end at the latest when the permitted time has run out."},{"da":"Reglerne gælder ikke, hvis jeg lægger en seddel med mit telefonnummer i ruden.","fa":"اگر یادداشتی با شماره‌تلفنم پشت شیشه بگذارم، این قواعد برقرار نیستند.","ok":0,"eda":"Nej. En seddel ændrer ikke på tidsbegrænsningen.","efa":"خیر. یادداشت محدودیت زمانی را تغییر نمی‌دهد.","en":"The rules do not apply if I leave a note with my phone number in the window.","een":"No. A note does not change the time limit."},{"da":"Jeg går ud og stiller P-skiven frem, så har jeg 2 timer mere.","fa":"می‌روم و صفحه‌ی ساعت پارک را جلو می‌کشم تا ۲ ساعت دیگر وقت داشته باشم.","ok":0,"eda":"Nej. P-skivens indstilling må ikke ændres, mens bilen holder parkeret.","efa":"خیر. تا وقتی خودرو پارک است، تنظیم صفحه‌ی ساعت پارک نباید تغییر کند.","en":"I go out and set the parking disc forward, and then I have 2 more hours.","een":"No. The parking disc's setting must not be changed while the car is parked."}]},{"id":5307,"img":"newq-art/5307.png","c":"7.9","sda":"Foran dig kører to cyklister ved siden af hinanden. Du vil overhale dem. Hvad gælder?","sfa":"جلوی شما دو دوچرخه‌سوار کنار هم رکاب می‌زنند. می‌خواهید از آن‌ها سبقت بگیرید. چه قاعده‌ای برقرار است؟","sen":"In front of you two cyclists are riding side by side. You want to overtake them. What applies?","st":[{"da":"Når de kører ved siden af hinanden, må jeg overhale tæt forbi dem.","fa":"وقتی کنار هم می‌رانند، می‌توانم از نزدیکشان سبقت بگیرم.","ok":0,"eda":"Nej. Du skal altid holde tilstrækkelig afstand til siden, når du overhaler.","efa":"خیر. هنگام سبقت همیشه باید فاصله‌ی کافی از پهلو داشته باشید.","en":"When they ride side by side, I may overtake close past them.","een":"No. You must always keep enough distance to the side when overtaking."},{"da":"Cyklisterne må godt køre ved siden af hinanden, når der er plads, og det kan ske uden fare.","fa":"دوچرخه‌سواران وقتی جا هست و بی‌خطر است، می‌توانند کنار هم برانند.","ok":1,"eda":"Ja. Hvor der er tilstrækkelig plads, må to cyklister køre ved siden af hinanden, hvis det kan ske uden fare eller unødig ulempe.","efa":"بله. جایی که جای کافی هست، دو دوچرخه‌سوار می‌توانند کنار هم برانند، اگر خطر یا مزاحمتی نداشته باشد.","en":"The cyclists may ride side by side when there is room and it can be done safely.","een":"Yes. Where there is enough room, two cyclists may ride side by side if it can be done without danger or undue inconvenience."},{"da":"Jeg overhaler først, når jeg kan holde god afstand til siden og ikke kommer i vejen for den modkørende.","fa":"فقط وقتی سبقت می‌گیرم که بتوانم فاصله‌ی کافی از پهلو داشته باشم و سر راه خودروی روبه‌رو قرار نگیرم.","ok":1,"eda":"Ja. Den modsatte vognbane skal være fri på en tilstrækkeligt lang strækning, og du skal holde tilstrækkelig sideafstand.","efa":"بله. خط مقابل باید در طول کافی خالی باشد و باید فاصله‌ی کافی از پهلو داشته باشید.","en":"I only overtake when I can keep a good distance to the side and do not get in the way of the oncoming car.","een":"Yes. The opposite lane must be free for a long enough stretch, and you must keep enough side distance."},{"da":"Cyklister må aldrig køre ved siden af hinanden.","fa":"دوچرخه‌سواران هیچ‌وقت نباید کنار هم برانند.","ok":0,"eda":"Nej. Det er tilladt, når der er plads, og det kan ske uden fare.","efa":"خیر. وقتی جا هست و بی‌خطر است، مجاز است.","en":"Cyclists may never ride side by side.","een":"No. It is allowed when there is room and it can be done safely."}]},{"id":5308,"img":"newq-art/5308.png","c":"7.9","sda":"Midterlinjen skifter til lange streger med korte mellemrum, og længere fremme bliver den ubrudt. Foran dig kører en langsom bil. Hvad gælder?","sfa":"خط وسط به خط‌چین‌های بلند با فاصله‌ی کم تبدیل می‌شود و جلوتر ممتد می‌شود. یک خودروی کُند جلوی شماست. چه قاعده‌ای برقرار است؟","sen":"The centre line changes to long dashes with short gaps, and further ahead it becomes unbroken. A slow car is in front of you. What applies?","st":[{"da":"De lange streger betyder, at jeg slet ikke må krydse dem.","fa":"خط‌چین‌های بلند یعنی اصلاً نباید از رویشان رد شوم.","ok":0,"eda":"Nej. En varsellinje må krydses med forsigtighed; det er den ubrudte linje, der ikke må.","efa":"خیر. از خط هشدار با احتیاط می‌توان رد شد؛ این خط ممتد است که نباید از آن گذشت.","en":"The long dashes mean that I may not cross them at all.","een":"No. A warning line may be crossed with care; it is the unbroken line that may not."},{"da":"Jeg begynder ikke en overhaling, som jeg ikke kan nå at afslutte, før den ubrudte linje begynder.","fa":"سبقتی را که پیش از شروع خط ممتد تمام نمی‌شود شروع نمی‌کنم.","ok":1,"eda":"Ja. Den ubrudte linje må ikke overskrides, heller ikke for at afslutte en overhaling.","efa":"بله. نباید از خط ممتد رد شد، حتی برای تمام کردن سبقت.","en":"I do not start an overtaking that I cannot finish before the unbroken line begins.","een":"Yes. The unbroken line must not be crossed, not even to finish an overtaking."},{"da":"Jeg må køre over den ubrudte linje, hvis jeg begyndte overhalingen før den.","fa":"اگر سبقت را پیش از خط ممتد شروع کرده باشم، می‌توانم از روی آن رد شوم.","ok":0,"eda":"Nej. Spærrelinjen må ikke overskrides; overhalingen skal være afsluttet inden.","efa":"خیر. از خط ممتد نباید رد شد؛ سبقت باید پیش از آن تمام شده باشد.","en":"I may cross the unbroken line if I began overtaking before it.","een":"No. The barrier line must not be crossed; the overtaking must be finished before it."},{"da":"De lange streger er en varsellinje, der advarer om, at der snart kommer en ubrudt linje eller et farligt sted.","fa":"خط‌چین‌های بلند خط هشدارند و خبر می‌دهند که به‌زودی خط ممتد یا جای خطرناکی می‌آید.","ok":1,"eda":"Ja. Varsellinjen varsler en spærrelinje eller et farligt sted, og den kræver særlig opmærksomhed.","efa":"بله. خط هشدار از نزدیک بودن خط ممتد یا جای خطرناک خبر می‌دهد و توجه ویژه می‌خواهد.","en":"The long dashes are a warning line telling that an unbroken line or a dangerous place is coming soon.","een":"Yes. The warning line announces a barrier line or a dangerous place, and it calls for extra care."}]},{"id":5309,"img":"newq-art/5309.png","c":"7.9","sda":"Du kører forbi denne tavle. Foran dig kører en langsom varevogn. Hvad gælder for overhaling?","sfa":"از کنار این تابلو می‌گذرید. یک ون کُند جلوی شما می‌رود. درباره‌ی سبقت چه قاعده‌ای برقرار است؟","sen":"You pass this sign. A slow van is driving in front of you. What applies to overtaking?","st":[{"da":"Jeg venter med at overhale, til vejen er bred igen.","fa":"تا پهن شدن دوباره‌ی جاده برای سبقت صبر می‌کنم.","ok":1,"eda":"Ja. Der skal være plads til at komme ind igen uden fare; ved indsnævringen er der ikke det.","efa":"بله. باید جای کافی برای برگشتن بی‌خطر باشد؛ در باریک‌شدگی چنین جایی نیست.","en":"I wait to overtake until the road is wide again.","een":"Yes. There must be room to get back in safely; at the narrowing there is not."},{"da":"Tavlen betyder, at overhaling er forbudt på resten af vejen.","fa":"این تابلو یعنی سبقت در بقیه‌ی جاده ممنوع است.","ok":0,"eda":"Nej. Tavlen er en advarsel, ikke et overhalingsforbud.","efa":"خیر. این تابلو هشدار است، نه ممنوعیت سبقت.","en":"The sign means that overtaking is forbidden for the rest of the road.","een":"No. The sign is a warning, not a ban on overtaking."},{"da":"Jeg skynder mig at overhale, før vejen bliver smal.","fa":"عجله می‌کنم تا پیش از باریک شدن جاده سبقت بگیرم.","ok":0,"eda":"Nej. Når du skynder dig mod en indsnævring, risikerer du at møde nogen der, hvor ingen kan vige.","efa":"خیر. با عجله به سمت باریک‌شدگی، خطر دارد در جایی با کسی روبه‌رو شوید که هیچ‌کس نمی‌تواند کنار برود.","en":"I hurry to overtake before the road becomes narrow.","een":"No. Hurrying towards a narrowing, you risk meeting someone there where nobody can give way."},{"da":"Tavlen advarer om, at vejen bliver smallere.","fa":"این تابلو هشدار می‌دهد که جاده باریک‌تر می‌شود.","ok":1,"eda":"Ja. Tavlen advarer om indsnævret vej.","efa":"بله. این تابلو درباره‌ی باریک‌شدگی جاده هشدار می‌دهد.","en":"The sign warns that the road becomes narrower.","een":"Yes. The sign warns of a narrowing road."}]},{"id":5310,"img":"newq-art/5310.png","c":"7.9","sda":"Du vil overhale traktoren foran dig. I spejlet ser du, at bilen bag dig allerede er trukket ud for at overhale. Hvad gælder?","sfa":"می‌خواهید از تراکتور جلویی سبقت بگیرید. در آینه می‌بینید خودروی پشتی برای سبقت بیرون آمده است. چه قاعده‌ای برقرار است؟","sen":"You want to overtake the tractor in front of you. In the mirror you see that the car behind you has already pulled out to overtake. What applies?","st":[{"da":"Jeg holder til højre og farten jævn, så bilen let kan komme forbi.","fa":"سمت راست می‌مانم و سرعتم را ثابت نگه می‌دارم تا آن خودرو راحت رد شود.","ok":1,"eda":"Ja. Den, der bliver overhalet, skal holde til højre og ikke sætte farten op.","efa":"بله. کسی که از او سبقت گرفته می‌شود باید سمت راست بماند و سرعتش را بالا نبرد.","en":"I keep right and my speed steady so that the car can get past easily.","een":"Yes. The one being overtaken must keep right and not speed up."},{"da":"Jeg trækker ud alligevel, fordi jeg var først bag traktoren.","fa":"به هر حال بیرون می‌روم، چون اول پشت تراکتور بودم.","ok":0,"eda":"Nej. Så kan I støde sammen; den, der allerede er i gang, skal kunne gøre overhalingen færdig.","efa":"خیر. ممکن است با هم برخورد کنید؛ کسی که سبقت را شروع کرده باید بتواند تمامش کند.","en":"I pull out anyway because I was first behind the tractor.","een":"No. Then you may collide; the one already overtaking must be able to finish."},{"da":"Jeg venter, til bilen bag mig er kommet forbi.","fa":"صبر می‌کنم تا خودروی پشتی رد شود.","ok":1,"eda":"Ja. Du må ikke begynde at overhale, når et køretøj bagfra er begyndt at overhale.","efa":"بله. وقتی وسیله‌ای از پشت سبقت را شروع کرده، نباید سبقت را آغاز کنید.","en":"I wait until the car behind me has passed.","een":"Yes. You must not start overtaking when a vehicle from behind has begun to overtake."},{"da":"Jeg giver tegn til venstre, så bilen bag mig må vente.","fa":"راهنمای چپ می‌زنم تا خودروی پشتی مجبور به صبر شود.","ok":0,"eda":"Nej. Blinklyset giver dig ikke ret til at trække ud foran en, der allerede overhaler.","efa":"خیر. راهنما به شما حق نمی‌دهد جلوی کسی که در حال سبقت است بیرون بروید.","en":"I signal left so that the car behind me has to wait.","een":"No. The indicator does not give you the right to pull out in front of someone already overtaking."}]},{"id":5311,"img":"newq-art/5311.png","c":"7.9","sda":"På motorvejen kører en bil langsomt i venstre vognbane, selv om højre vognbane er fri. Du kommer bagfra. Hvad gælder?","sfa":"در آزادراه خودرویی آهسته در خط چپ می‌رود، با این‌که خط راست خالی است. شما از پشت می‌رسید. چه قاعده‌ای برقرار است؟","sen":"On the motorway a car is driving slowly in the left lane although the right lane is free. You come up behind it. What applies?","st":[{"da":"Jeg kører tæt op bag den og blinker med fjernlyset, så den flytter sig.","fa":"به آن خیلی نزدیک می‌شوم و با نور بالا چراغ می‌زنم تا کنار برود.","ok":0,"eda":"Nej. Du skal holde afstand, og lyssignal er kun til at advare om fare.","efa":"خیر. باید فاصله بگیرید و علامت نوری فقط برای هشدار خطر است.","en":"I drive right up behind it and flash my high beam so that it moves.","een":"No. You must keep your distance, and a light signal is only for warning of danger."},{"da":"Normalt skal overhaling ske i venstre side.","fa":"سبقت معمولاً باید از سمت چپ انجام شود.","ok":1,"eda":"Ja. Overhaling skal ske til venstre, med få undtagelser som et køretøj, der svinger til venstre.","efa":"بله. سبقت باید از چپ باشد، با چند استثنا مثل وسیله‌ای که به چپ می‌پیچد.","en":"Overtaking must normally be done on the left.","een":"Yes. Overtaking must be done on the left, with a few exceptions such as a vehicle turning left."},{"da":"Jeg bliver bag den og holder god afstand, til den kører ind til højre.","fa":"پشتش می‌مانم و فاصله‌ی کافی نگه می‌دارم تا به راست برود.","ok":1,"eda":"Ja. Så undgår du både en farlig overhaling og at køre for tæt på.","efa":"بله. این‌طور هم از سبقت خطرناک و هم از نزدیک شدن بیش از حد پرهیز می‌کنید.","en":"I stay behind it and keep a good distance until it moves to the right.","een":"Yes. That way you avoid both a dangerous overtaking and driving too close."},{"da":"Jeg må overhale den i højre side, fordi den kører forkert.","fa":"چون آن خودرو اشتباه می‌کند، می‌توانم از سمت راستش سبقت بگیرم.","ok":0,"eda":"Nej. Overhaling skal ske til venstre; kun i tæt kø i flere rækker regnes det ikke som overhaling at køre forbi i en anden vognbane.","efa":"خیر. سبقت باید از چپ باشد؛ فقط در صف‌های سنگین چندردیفه رد شدن در خط دیگر سبقت حساب نمی‌شود.","en":"I may overtake it on the right because it is in the wrong.","een":"No. Overtaking must be done on the left; only in dense queues in several rows does passing in another lane not count as overtaking."}]},{"id":5312,"img":"newq-art/5312.png","c":"6.1","sda":"Ved indkørslen til vejen står denne tavle. Hvad betyder den?","sfa":"در ورودی راه این تابلو قرار دارد. معنی‌اش چیست؟","sen":"At the entrance to the road stands this sign. What does it mean?","st":[{"da":"Tavlen gælder kun om natten.","fa":"این تابلو فقط شب‌ها برقرار است.","ok":0,"eda":"Nej. Uden undertavle med et tidsrum gælder forbuddet hele døgnet.","efa":"خیر. بدون زیرتابلوی ساعت، این ممنوعیت در تمام شبانه‌روز برقرار است.","en":"The sign only applies at night.","een":"No. Without a sub-plate giving times, the ban applies round the clock."},{"da":"Cykler må gerne køre ind, fordi tavlen kun gælder motorkøretøjer.","fa":"دوچرخه‌ها می‌توانند وارد شوند، چون این تابلو فقط برای وسایل موتوری است.","ok":0,"eda":"Nej. Forbuddet gælder al kørsel; et forbud kun for motorkøretøjer har sin egen tavle.","efa":"خیر. این ممنوعیت همه‌ی رانندگی‌ها را شامل می‌شود؛ ممنوعیتِ فقط وسایل موتوری تابلوی خودش را دارد.","en":"Bicycles may ride in because the sign only applies to motor vehicles.","een":"No. The ban covers all driving; a ban only for motor vehicles has its own sign."},{"da":"Kørsel i begge retninger er forbudt.","fa":"رانندگی در هر دو جهت ممنوع است.","ok":1,"eda":"Ja. Tavlen forbyder kørsel i begge retninger.","efa":"بله. این تابلو رانندگی در هر دو جهت را ممنوع می‌کند.","en":"Driving in both directions is forbidden.","een":"Yes. The sign bans driving in both directions."},{"da":"Tavlen forbyder kun indkørsel fra denne side; fra den anden ende må jeg gerne køre ind.","fa":"این تابلو فقط ورود از این طرف را ممنوع می‌کند؛ از سر دیگر می‌توانم وارد شوم.","ok":0,"eda":"Nej. Forbuddet gælder kørsel i begge retninger.","efa":"خیر. این ممنوعیت رانندگی در هر دو جهت را شامل می‌شود.","en":"The sign only bans entry from this side; from the other end I may drive in.","een":"No. The ban covers driving in both directions."}]},{"id":5313,"img":"newq-art/5313.png","c":"6.1","sda":"Du kører i en almindelig personbil. Ved indkørslen til vejen står denne tavle. Hvad gælder?","sfa":"با یک خودروی سواری معمولی رانندگی می‌کنید. در ورودی راه این تابلو هست. چه قاعده‌ای برقرار است؟","sen":"You are driving an ordinary car. At the entrance to the road stands this sign. What applies?","st":[{"da":"Jeg må køre ind på vejen i min personbil.","fa":"با خودروی سواری‌ام می‌توانم وارد این راه شوم.","ok":1,"eda":"Ja. Tavlen forbyder lastbiler, ikke personbiler.","efa":"بله. این تابلو کامیون را ممنوع می‌کند، نه خودروی سواری.","en":"I may drive into the road in my car.","een":"Yes. The sign bans lorries, not cars."},{"da":"Forbuddet gælder lastbiler over den vægt, undertavlen viser.","fa":"این ممنوعیت برای کامیون‌های سنگین‌تر از وزنی است که زیرتابلو نشان می‌دهد.","ok":1,"eda":"Ja. Med en vægtangivelse på undertavlen er forbuddet begrænset til lastbiler over den vægt.","efa":"بله. با قید وزن در زیرتابلو، ممنوعیت به کامیون‌های سنگین‌تر از آن وزن محدود می‌شود.","en":"The ban applies to lorries above the weight shown on the sub-plate.","een":"Yes. With a weight on the sub-plate, the ban is limited to lorries above that weight."},{"da":"Tavlen forbyder alle biler at køre ind.","fa":"این تابلو ورود همه‌ی خودروها را ممنوع می‌کند.","ok":0,"eda":"Nej. Symbolet viser en lastbil; forbuddet gælder kun lastbiler.","efa":"خیر. نماد تابلو کامیون است؛ ممنوعیت فقط برای کامیون است.","en":"The sign bans all cars from driving in.","een":"No. The symbol shows a lorry; the ban applies only to lorries."},{"da":"En varebil på højst 3,5 t er ikke en lastbil og må køre ind.","fa":"یک ون حداکثر ۳٫۵ تنی کامیون حساب نمی‌شود و می‌تواند وارد شود.","ok":1,"eda":"Ja. Godsbiler op til 3.500 kg er varebiler; lastbiler er tungere.","efa":"بله. خودروهای باری تا ۳٬۵۰۰ کیلوگرم ون حساب می‌شوند؛ کامیون‌ها سنگین‌ترند.","en":"A van of at most 3.5 t is not a lorry and may drive in.","een":"Yes. Goods vehicles up to 3,500 kg are vans; lorries are heavier."}]},{"id":5314,"img":"newq-art/5314.png","c":"6.1","sda":"Du har kørt på en strækning med overhalingsforbud. Nu kører du forbi denne tavle. Hvad betyder den?","sfa":"در مسیری با ممنوعیت سبقت رانندگی کرده‌اید. حالا از کنار این تابلو می‌گذرید. معنی‌اش چیست؟","sen":"You have been driving on a stretch with an overtaking ban. Now you pass this sign. What does it mean?","st":[{"da":"Overhalingsforbuddet ophører her.","fa":"ممنوعیت سبقت اینجا تمام می‌شود.","ok":1,"eda":"Ja. Tavlen angiver ophør af overhalingsforbud.","efa":"بله. این تابلو پایان ممنوعیت سبقت را نشان می‌دهد.","en":"The overtaking ban ends here.","een":"Yes. The sign shows the end of the overtaking ban."},{"da":"Nu må jeg overhale overalt, også i kryds og ved bakketoppe.","fa":"حالا هر جا می‌توانم سبقت بگیرم، حتی در تقاطع و بالای تپه.","ok":0,"eda":"Nej. Lovens forbud mod overhaling i kryds og ved uoverskuelige bakker gælder stadig.","efa":"خیر. ممنوعیت‌های قانونی سبقت در تقاطع و تپه‌های بی‌دید همچنان برقرارند.","en":"Now I may overtake anywhere, also in junctions and at hilltops.","een":"No. The law's bans on overtaking in junctions and at blind hills still apply."},{"da":"Tavlen ophæver også en lokal hastighedsgrænse.","fa":"این تابلو حد سرعت محلی را هم لغو می‌کند.","ok":0,"eda":"Nej. Tavlen gælder kun overhalingsforbuddet.","efa":"خیر. این تابلو فقط درباره‌ی ممنوعیت سبقت است.","en":"The sign also ends a local speed limit.","een":"No. The sign only concerns the overtaking ban."},{"da":"Jeg må overhale igen efter de almindelige regler.","fa":"دوباره می‌توانم طبق قواعد معمول سبقت بگیرم.","ok":1,"eda":"Ja. Der skal stadig være fri bane, og overhalingen skal kunne ske uden fare.","efa":"بله. هنوز باید جاده خالی باشد و سبقت بی‌خطر انجام شود.","en":"I may overtake again under the ordinary rules.","een":"Yes. The road must still be clear, and the overtaking must be possible without danger."}]},{"id":5315,"img":"newq-art/5315.png","c":"6.1","sda":"Ved krydset står denne blå tavle. Hvad betyder den?","sfa":"کنار تقاطع این تابلوی آبی قرار دارد. معنی‌اش چیست؟","sen":"At the junction stands this blue sign. What does it mean?","st":[{"da":"Jeg skal svinge til højre.","fa":"باید به راست بپیچم.","ok":1,"eda":"Ja. Tavlen er et påbud: kørselsretningen er den, pilen viser.","efa":"بله. این تابلو الزامی است: جهت حرکت همانی است که فلش نشان می‌دهد.","en":"I must turn right.","een":"Yes. The sign is a requirement: the direction of travel is the one the arrow shows."},{"da":"Tavlen anbefaler, at jeg kører til højre, men jeg må selv vælge.","fa":"این تابلو پیشنهاد می‌کند به راست بپیچم، ولی خودم می‌توانم انتخاب کنم.","ok":0,"eda":"Nej. Runde blå tavler er påbud, ikke anbefalinger.","efa":"خیر. تابلوهای گرد آبی الزام‌اند، نه پیشنهاد.","en":"The sign recommends turning right, but I may choose for myself.","een":"No. Round blue signs are requirements, not recommendations."},{"da":"Jeg må køre ligeud, hvis der ikke kommer nogen.","fa":"اگر کسی نیاید، می‌توانم مستقیم بروم.","ok":0,"eda":"Nej. Påbuddet gælder, uanset trafikken.","efa":"خیر. این الزام، ترافیک هر چه باشد، برقرار است.","en":"I may go straight on if nobody is coming.","een":"No. The requirement applies whatever the traffic."}]},{"id":5316,"img":"newq-art/5316.png","c":"6.1","sda":"Du drejer ind på en gade med denne tavle. Hvad betyder den?","sfa":"وارد خیابانی با این تابلو می‌شوید. معنی‌اش چیست؟","sen":"You turn into a street with this sign. What does it mean?","st":[{"da":"Jeg må parkere i venstre side af gaden.","fa":"می‌توانم در سمت چپ خیابان پارک کنم.","ok":1,"eda":"Ja. På vej med ensrettet færdsel må der standses og parkeres i venstre side.","efa":"بله. در راه یک‌طرفه توقف و پارک در سمت چپ مجاز است.","en":"I may park on the left side of the street.","een":"Yes. On a one-way road you may stop and park on the left side."},{"da":"Der kan komme biler imod mig i gaden.","fa":"ممکن است در این خیابان خودروها از روبه‌رو بیایند.","ok":0,"eda":"Nej. Gaden er ensrettet, så biler kører kun i din retning.","efa":"خیر. خیابان یک‌طرفه است، پس خودروها فقط در جهت شما می‌روند.","en":"Cars may come towards me in the street.","een":"No. The street is one-way, so cars only drive in your direction."},{"da":"Gaden er ensrettet i den retning, pilen viser.","fa":"این خیابان در جهتی که فلش نشان می‌دهد یک‌طرفه است.","ok":1,"eda":"Ja. Tavlen angiver ensrettet færdsel.","efa":"بله. این تابلو ترافیک یک‌طرفه را نشان می‌دهد.","en":"The street is one-way in the direction the arrow shows.","een":"Yes. The sign shows one-way traffic."},{"da":"Tavlen betyder, at jeg skal køre ligeud i næste kryds.","fa":"این تابلو یعنی در تقاطع بعدی باید مستقیم بروم.","ok":0,"eda":"Nej. Et påbud om kørselsretning vises på en rund blå tavle.","efa":"خیر. جهت الزامی با تابلوی گرد آبی نشان داده می‌شود.","en":"The sign means that I must go straight on at the next junction.","een":"No. A required direction is shown on a round blue sign."}]},{"id":5317,"img":"newq-art/5317.png","c":"7.6","sda":"Fodgængerfeltet foran dig er delt af en helle. En kvinde står på hellen og vil gå videre over din side. Hvordan forholder du dig?","sfa":"گذرگاه عابر پیاده‌ی جلوی شما با یک جزیره‌ی میانی دو قسمت شده است. زنی روی جزیره ایستاده و می‌خواهد از سمت شما ادامه دهد. چه می‌کنید؟","sen":"The pedestrian crossing in front of you is split by a traffic island. A woman is standing on the island and wants to carry on across your side. What do you do?","st":[{"da":"Hun skal vente, fordi hun står på hellen og ikke på feltet.","fa":"او باید صبر کند، چون روی جزیره ایستاده نه روی گذرگاه.","ok":0,"eda":"Nej. Hun er på vej ud i feltet, og du skal lade hende gå over uden fare.","efa":"خیر. او در حال ورود به گذرگاه است و باید بگذارید بی‌خطر رد شود.","en":"She must wait because she is standing on the island, not on the crossing.","een":"No. She is about to step onto the crossing, and you must let her cross safely."},{"da":"Jeg standser og lader hende gå over.","fa":"می‌ایستم و می‌گذارم رد شود.","ok":1,"eda":"Ja. Ved et fodgængerfelt uden signal skal du om nødvendigt standse for gående, der er ved at gå ud i feltet.","efa":"بله. در گذرگاه بدون چراغ، در صورت لزوم باید برای عابرانی که می‌خواهند وارد گذرگاه شوند بایستید.","en":"I stop and let her cross.","een":"Yes. At a crossing without signals you must stop if necessary for pedestrians about to step onto it."},{"da":"Jeg sænker farten i god tid, når der er gående ved feltet.","fa":"وقتی کنار گذرگاه عابر هست، به موقع سرعتم را کم می‌کنم.","ok":1,"eda":"Ja. Før et fodgængerfelt skal du holde en passende lav hastighed.","efa":"بله. پیش از گذرگاه عابر پیاده باید سرعت مناسبِ کمی داشته باشید.","en":"I slow down in good time when there are pedestrians at the crossing.","een":"Yes. Before a pedestrian crossing you must keep a suitably low speed."}]},{"id":5318,"img":"newq-art/5318.png","c":"7.6","sda":"En letbane holder ved et stoppested midt på vejen, og passagerer stiger af. Hvordan forholder du dig?","sfa":"یک قطار شهری سبک (letbane) در ایستگاهی وسط خیابان ایستاده و مسافرها پیاده می‌شوند. چه می‌کنید؟","sen":"A light-rail tram is standing at a stop in the middle of the road, and passengers are getting off. What do you do?","st":[{"da":"Jeg kører hurtigt forbi, før letbanen kører igen.","fa":"پیش از راه افتادن دوباره‌ی قطار، سریع رد می‌شوم.","ok":0,"eda":"Nej. Høj fart her giver ingen tid til at standse for gående.","efa":"خیر. سرعت زیاد اینجا فرصتی برای توقف برای عابران نمی‌گذارد.","en":"I drive past quickly before the tram leaves again.","een":"No. High speed here leaves no time to stop for pedestrians."},{"da":"Jeg er klar til at standse for gående.","fa":"آماده‌ی توقف برای عابرانم.","ok":1,"eda":"Ja. Gående på vej til og fra stoppestedet kan træde ud foran dig.","efa":"بله. عابرانی که به ایستگاه می‌روند یا از آن می‌آیند ممکن است جلوی شما بیایند.","en":"I am ready to stop for pedestrians.","een":"Yes. Pedestrians on their way to and from the stop may step out in front of you."},{"da":"Gående kan dukke frem bag letbanen.","fa":"ممکن است عابران از پشت قطار بیرون بیایند.","ok":1,"eda":"Ja. Letbanen skjuler dem, der går om bag den.","efa":"بله. قطار کسانی را که از پشتش رد می‌شوند پنهان می‌کند.","en":"Pedestrians may appear from behind the tram.","een":"Yes. The tram hides those who walk round behind it."},{"da":"Jeg sænker farten, fordi passagerer kan gå over vejen til og fra stoppestedet.","fa":"سرعتم را کم می‌کنم، چون مسافرها ممکن است برای رفتن به ایستگاه یا آمدن از آن از خیابان رد شوند.","ok":1,"eda":"Ja. Når du nærmer dig et letbanekøretøj, der holder for at sætte passagerer af, skal du holde en passende lav hastighed.","efa":"بله. وقتی به قطار شهری‌ای نزدیک می‌شوید که برای پیاده کردن مسافر ایستاده، باید سرعت مناسبِ کمی داشته باشید.","en":"I slow down because passengers may cross the road to and from the stop.","een":"Yes. When you approach a light-rail vehicle standing to let passengers off, you must keep a suitably low speed."}]},{"id":5319,"img":"newq-art/5319.png","c":"7.6","sda":"Det er mørkt. To løbere i mørkt tøj løber i højre vejkant med ryggen til dig. Hvordan forholder du dig?","sfa":"هوا تاریک است. دو دونده با لباس تیره، پشت به شما، در لبه‌ی راست جاده می‌دوند. چه می‌کنید؟","sen":"It is dark. Two runners in dark clothes are running at the right edge of the road with their backs to you. What do you do?","st":[{"da":"Jeg sænker farten og giver løberne god plads, når jeg kører forbi.","fa":"سرعتم را کم می‌کنم و هنگام رد شدن جای کافی به آن‌ها می‌دهم.","ok":1,"eda":"Ja. Du skal give gående fornøden plads, og i mørke ser du dem sent.","efa":"بله. باید به عابران جای کافی بدهید، و در تاریکی آن‌ها را دیر می‌بینید.","en":"I slow down and give them plenty of room when I drive past.","een":"Yes. You must give pedestrians the room they need, and in the dark you see them late."},{"da":"Uden refleks kan gående i mørkt tøj først ses meget sent.","fa":"عابران با لباس تیره و بدون شبرنگ خیلی دیر دیده می‌شوند.","ok":1,"eda":"Ja. Mørkt tøj ses kun på kort afstand i nærlys; refleks ses langt længere væk.","efa":"بله. لباس تیره در نور پایین فقط از فاصله‌ی کم دیده می‌شود؛ شبرنگ از فاصله‌ی خیلی بیشتر.","en":"Without reflectors, pedestrians in dark clothes can only be seen very late.","een":"Yes. Dark clothes are only seen at a short distance in dipped beam; reflectors are seen much further away."},{"da":"De skal flytte sig, fordi de løber i den forkerte side.","fa":"باید کنار بروند، چون در سمت اشتباه می‌دوند.","ok":0,"eda":"Nej. Gående på kørebanen skal som regel gå i venstre side, men du skal alligevel tage hensyn til dem.","efa":"خیر. عابران روی سواره‌رو معمولاً باید سمت چپ بروند، ولی شما در هر حال باید مراقبشان باشید.","en":"They must move because they are running on the wrong side.","een":"No. Pedestrians on the carriageway must as a rule walk on the left, but you must still take care of them."},{"da":"Kommer der en bil imod mig, venter jeg bag løberne, til der er plads.","fa":"اگر خودرویی از روبه‌رو بیاید، پشت دونده‌ها صبر می‌کنم تا جا باز شود.","ok":1,"eda":"Ja. Ved møde skal du tage hensyn til dem, der færdes i vejkanten.","efa":"بله. هنگام روبه‌رو شدن باید مراقب کسانی باشید که لبه‌ی جاده حرکت می‌کنند.","en":"If a car comes towards me, I wait behind the runners until there is room.","een":"Yes. When meeting, you must take care of those using the edge of the road."}]},{"id":5320,"img":"newq-art/5320.png","c":"7.6","sda":"En mand i kørestol er ved at krydse vejen i fodgængerfeltet foran dig. Det går langsomt. Hvordan forholder du dig?","sfa":"مردی با ویلچر در گذرگاه عابر پیاده‌ی جلوی شما در حال رد شدن از خیابان است و آهسته پیش می‌رود. چه می‌کنید؟","sen":"A man in a wheelchair is crossing the road on the pedestrian crossing in front of you. He is slow. What do you do?","st":[{"da":"Jeg kører uden om ham i den modsatte vognbane.","fa":"از خط مقابل دورش می‌زنم و رد می‌شوم.","ok":0,"eda":"Nej. Du må ikke køre ind på feltet, mens han krydser.","efa":"خیر. تا وقتی او در حال رد شدن است، نباید وارد گذرگاه شوید.","en":"I drive round him in the opposite lane.","een":"No. You must not drive onto the crossing while he is crossing."},{"da":"Jeg venter tålmodigt, til han er kommet over.","fa":"با حوصله صبر می‌کنم تا رد شود.","ok":1,"eda":"Ja. Gående i et fodgængerfelt skal kunne komme over uden fare, uanset hvor langsomt det går.","efa":"بله. عابر در گذرگاه باید بتواند بی‌خطر رد شود، هر قدر هم آهسته باشد.","en":"I wait patiently until he has crossed.","een":"Yes. Pedestrians on a crossing must be able to get across safely, however slowly they go."},{"da":"Jeg ruller lidt frem, så han kan se, at jeg gerne vil videre.","fa":"کمی جلو می‌روم تا ببیند می‌خواهم ادامه دهم.","ok":0,"eda":"Nej. Det kan skræmme ham og presse ham; vent stille.","efa":"خیر. این کار ممکن است او را بترساند و تحت فشار بگذارد؛ آرام صبر کنید.","en":"I roll forward a little so that he can see that I want to move on.","een":"No. That can frighten and pressure him; wait quietly."}]},{"id":5321,"img":"newq-art/5321.png","c":"7.3","sda":"Du kører dobbelt så hurtigt som før. Hvad sker der med bremselængden?","sfa":"دو برابر قبل سریع می‌رانید. مسافت ترمز چه تغییری می‌کند؟","sen":"You are driving twice as fast as before. What happens to the braking distance?","st":[{"da":"Den bliver cirka fire gange så lang.","fa":"تقریباً چهار برابر می‌شود.","ok":1,"eda":"Ja. Bremselængden vokser med farten i anden potens: dobbelt fart giver omkring fire gange så lang bremselængde.","efa":"بله. مسافت ترمز با مجذور سرعت زیاد می‌شود: سرعت دو برابر یعنی مسافت ترمز حدوداً چهار برابر.","en":"It becomes about four times as long.","een":"Yes. The braking distance grows with the square of the speed: twice the speed gives about four times the braking distance."},{"da":"Den er den samme, hvis bremserne er gode.","fa":"اگر ترمزها خوب باشند، همان می‌ماند.","ok":0,"eda":"Nej. Selv med gode bremser bliver bremselængden meget længere ved højere fart.","efa":"خیر. حتی با ترمز خوب، در سرعت بیشتر مسافت ترمز خیلی بیشتر می‌شود.","en":"It is the same if the brakes are good.","een":"No. Even with good brakes the braking distance becomes much longer at a higher speed."},{"da":"Den bliver dobbelt så lang.","fa":"دو برابر می‌شود.","ok":0,"eda":"Nej. Den bliver længere end det: omkring fire gange.","efa":"خیر. بیشتر از این می‌شود: حدود چهار برابر.","en":"It becomes twice as long.","een":"No. It becomes longer than that: about four times."}]},{"id":5322,"img":"newq-art/5322.png","c":"7.3","sda":"Du kører 50 km/t, og et barn løber pludselig ud på vejen. Hvad gælder for din reaktion?","sfa":"با ۵۰ کیلومتر بر ساعت می‌رانید و کودکی ناگهان وارد خیابان می‌دود. درباره‌ی واکنش شما چه درست است؟","sen":"You are driving at 50 km/h and a child suddenly runs out onto the road. What applies to your reaction?","st":[{"da":"Stopafstanden er reaktionslængden plus bremselængden.","fa":"مسافت توقف برابر است با مسافت واکنش به‌علاوه‌ی مسافت ترمز.","ok":1,"eda":"Ja. Bilen kører, mens du reagerer, og derefter, mens den bremser.","efa":"بله. خودرو هم در زمان واکنش شما و هم در زمان ترمز جلو می‌رود.","en":"The stopping distance is the reaction distance plus the braking distance.","een":"Yes. The car travels while you react, and then while it brakes."},{"da":"Er jeg træt eller uopmærksom, bliver reaktionstiden længere.","fa":"اگر خسته یا بی‌حواس باشم، زمان واکنشم بیشتر می‌شود.","ok":1,"eda":"Ja. Så kører bilen længere, før bremsningen overhovedet begynder.","efa":"بله. در این صورت خودرو پیش از شروع ترمز مسافت بیشتری می‌رود.","en":"If I am tired or inattentive, the reaction time becomes longer.","een":"Yes. Then the car travels further before the braking even begins."},{"da":"Reaktionslængden afhænger kun af bremserne.","fa":"مسافت واکنش فقط به ترمزها بستگی دارد.","ok":0,"eda":"Nej. Reaktionslængden afhænger af farten og af, hvor hurtigt du reagerer.","efa":"خیر. مسافت واکنش به سرعت و به سرعت واکنش شما بستگی دارد.","en":"The reaction distance only depends on the brakes.","een":"No. The reaction distance depends on the speed and on how quickly you react."},{"da":"Før jeg når at træde på bremsen, kører bilen cirka 14 m, hvis min reaktionstid er 1 sekund.","fa":"اگر زمان واکنشم ۱ ثانیه باشد، پیش از رسیدن پایم به ترمز، خودرو حدود ۱۴ متر جلو می‌رود.","ok":1,"eda":"Ja. Ved 50 km/t kører bilen knap 14 m i sekundet.","efa":"بله. در ۵۰ کیلومتر بر ساعت خودرو در هر ثانیه نزدیک ۱۴ متر می‌رود.","en":"Before I manage to press the brake, the car travels about 14 m if my reaction time is 1 second.","een":"Yes. At 50 km/h the car travels almost 14 m a second."}]},{"id":5323,"img":"newq-art/5323.png","c":"7.3","sda":"Vejen fører gennem en lille landsby. Der er ingen byzonetavle og ingen hastighedstavler. Hvad gælder?","sfa":"جاده از یک روستای کوچک می‌گذرد. نه تابلوی ورود به منطقه‌ی شهری هست و نه تابلوی سرعت. چه قاعده‌ای برقرار است؟","sen":"The road goes through a small village. There is no built-up-area sign and no speed signs. What applies?","st":[{"da":"Den højst tilladte hastighed er 80 km/t.","fa":"حداکثر سرعت مجاز ۸۰ کیلومتر بر ساعت است.","ok":1,"eda":"Ja. Tættere bebygget område er kun der, hvor det er afmærket med tavler; ellers gælder 80 km/t.","efa":"بله. «منطقه‌ی مسکونیِ متراکم» فقط جایی است که با تابلو مشخص شده؛ وگرنه ۸۰ کیلومتر بر ساعت برقرار است.","en":"The highest permitted speed is 80 km/h.","een":"Yes. A built-up area only exists where it is marked with signs; otherwise 80 km/h applies."},{"da":"Der gælder automatisk 50 km/t, fordi der ligger huse ved vejen.","fa":"چون کنار جاده خانه هست، خودبه‌خود ۵۰ کیلومتر بر ساعت برقرار است.","ok":0,"eda":"Nej. Grænsen på 50 km/t gælder kun, hvor byzonetavlen står.","efa":"خیر. حد ۵۰ فقط جایی برقرار است که تابلوی ورود به منطقه‌ی شهری نصب شده باشد.","en":"50 km/h applies automatically because there are houses by the road.","een":"No. The 50 km/h limit only applies where the built-up-area sign stands."},{"da":"Jeg må køre 80 km/t uanset forholdene.","fa":"در هر شرایطی می‌توانم ۸۰ برانم.","ok":0,"eda":"Nej. 80 km/t er det højeste; forholdene kan kræve mindre.","efa":"خیر. ۸۰ حداکثر است؛ شرایط ممکن است سرعت کمتری بخواهد.","en":"I may drive at 80 km/h whatever the conditions.","een":"No. 80 km/h is the most; the conditions may call for less."},{"da":"Jeg sænker alligevel farten, fordi der kan være børn, gående og biler, der kører ud fra husene.","fa":"با این حال سرعتم را کم می‌کنم، چون ممکن است بچه‌ها، عابران و خودروهایی که از خانه‌ها بیرون می‌آیند باشند.","ok":1,"eda":"Ja. Farten skal altid passe til forholdene, også under grænsen.","efa":"بله. سرعت همیشه باید با شرایط جور باشد، حتی زیر حد مجاز.","en":"I slow down anyway, because there may be children, pedestrians and cars coming out of the houses.","een":"Yes. The speed must always suit the conditions, also below the limit."}]},{"id":5324,"img":"newq-art/5324.png","c":"7.3","sda":"Du har kørt på en strækning med en lokal hastighedsgrænse på 60 km/t. Nu kører du forbi denne tavle uden for byen. Hvad gælder?","sfa":"در مسیری با حد سرعت محلی ۶۰ کیلومتر بر ساعت رانده‌اید. حالا بیرون شهر از کنار این تابلو می‌گذرید. چه قاعده‌ای برقرار است؟","sen":"You have been driving on a stretch with a local speed limit of 60 km/h. Now you pass this sign outside town. What applies?","st":[{"da":"Den lokale grænse ophører, og nu gælder den generelle grænse på 80 km/t uden for byen.","fa":"حد محلی تمام می‌شود و حالا حد عمومی ۸۰ کیلومتر بر ساعتِ بیرون شهر برقرار است.","ok":1,"eda":"Ja. Tavlen ophæver den lokale hastighedsbegrænsning, så den generelle grænse gælder igen.","efa":"بله. این تابلو حد سرعت محلی را لغو می‌کند و حد عمومی دوباره برقرار می‌شود.","en":"The local limit ends, and now the general limit of 80 km/h outside town applies.","een":"Yes. The sign ends the local speed limit, so the general limit applies again."},{"da":"Jeg skal blive ved med at køre højst 60 km/t til næste kryds.","fa":"تا تقاطع بعدی باید همچنان حداکثر ۶۰ برانم.","ok":0,"eda":"Nej. Grænsen ophører ved tavlen.","efa":"خیر. حد سرعت در محل تابلو تمام می‌شود.","en":"I must keep to at most 60 km/h until the next junction.","een":"No. The limit ends at the sign."},{"da":"Nu er der ingen hastighedsgrænse.","fa":"حالا هیچ حد سرعتی وجود ندارد.","ok":0,"eda":"Nej. Den generelle grænse gælder altid, når der ikke er en lokal.","efa":"خیر. وقتی حد محلی نیست، حد عمومی همیشه برقرار است.","en":"Now there is no speed limit.","een":"No. The general limit always applies when there is no local one."},{"da":"Tavlen ophæver også et overhalingsforbud på strækningen.","fa":"این تابلو ممنوعیت سبقت را هم لغو می‌کند.","ok":0,"eda":"Nej. Tavlen gælder kun hastighedsgrænsen; overhalingsforbud har sin egen ophørstavle.","efa":"خیر. این تابلو فقط درباره‌ی حد سرعت است؛ ممنوعیت سبقت تابلوی پایان خودش را دارد.","en":"The sign also ends an overtaking ban on the stretch.","een":"No. The sign only concerns the speed limit; an overtaking ban has its own end sign."}]},{"id":5325,"img":"newq-art/5325.png","c":"1.2","sda":"Du har skiftet et punkteret hjul med bilens smalle nødhjul. Hvad gælder?","sfa":"چرخ پنچر را با زاپاس باریکِ خودرو عوض کرده‌اید. چه قاعده‌ای برقرار است؟","sen":"You have changed a punctured wheel for the car's narrow spare wheel. What applies?","st":[{"da":"Jeg får det punkterede dæk repareret eller skiftet så hurtigt som muligt.","fa":"هرچه زودتر تایر پنچر را تعمیر یا عوض می‌کنم.","ok":1,"eda":"Ja. Nødhjulet er ikke beregnet til almindelig kørsel.","efa":"بله. زاپاس باریک برای رانندگی معمولی ساخته نشده است.","en":"I have the punctured tyre repaired or replaced as soon as possible.","een":"Yes. The spare wheel is not meant for ordinary driving."},{"da":"Nødhjulet er kun til kortvarig brug, og jeg kører langsommere, som regel højst 80 km/t.","fa":"زاپاس باریک فقط برای استفاده‌ی کوتاه است و آهسته‌تر می‌رانم، معمولاً حداکثر ۸۰ کیلومتر بر ساعت.","ok":1,"eda":"Ja. Et smalt nødhjul har dårligere greb, og fabrikkens højeste hastighed står på hjulet eller i instruktionsbogen.","efa":"بله. زاپاس باریک چسبندگی کمتری دارد و حداکثر سرعتِ سازنده روی چرخ یا در دفترچه‌ی راهنما آمده است.","en":"The spare wheel is only for short-term use, and I drive more slowly, usually at most 80 km/h.","een":"Yes. A narrow spare wheel has less grip, and the maker's top speed is on the wheel or in the handbook."},{"da":"Jeg kan køre lige så hurtigt som med almindelige hjul, hvis jeg er forsigtig i sving.","fa":"اگر در پیچ‌ها مراقب باشم، می‌توانم به همان سرعت چرخ‌های معمولی برانم.","ok":0,"eda":"Nej. Med nødhjul gælder fabrikkens lavere højeste hastighed.","efa":"خیر. با زاپاس باریک، حداکثر سرعت کمترِ سازنده برقرار است.","en":"I can drive as fast as with ordinary wheels if I am careful in bends.","een":"No. With a spare wheel the maker's lower top speed applies."},{"da":"Nødhjulet kan blive siddende, så længe der er luft i det.","fa":"تا وقتی باد دارد، زاپاس می‌تواند روی خودرو بماند.","ok":0,"eda":"Nej. Det er kun til at komme frem til et værksted.","efa":"خیر. فقط برای رساندن خودرو به تعمیرگاه است.","en":"The spare wheel can stay on as long as it has air in it.","een":"No. It is only for getting to a workshop."}]},{"id":5326,"img":"newq-art/5326.png","c":"1.2","sda":"Under kørslen mærker du, at bremsepedalen er blød og skal trædes meget længere ned end normalt. Hvad gør du?","sfa":"هنگام رانندگی متوجه می‌شوید پدال ترمز نرم شده و باید خیلی بیشتر از معمول پایینش ببرید. چه می‌کنید؟","sen":"While driving, you notice that the brake pedal is soft and has to be pressed much further down than usual. What do you do?","st":[{"da":"Jeg standser forsigtigt et sikkert sted og kører ikke videre, før bremserne er efterset.","fa":"با احتیاط جایی امن می‌ایستم و تا ترمزها بررسی نشده‌اند، ادامه نمی‌دهم.","ok":1,"eda":"Ja. Bremserne kan svigte helt, og det er farligt at køre videre.","efa":"بله. ممکن است ترمزها کاملاً از کار بیفتند و ادامه‌ی رانندگی خطرناک است.","en":"I stop carefully at a safe place and do not drive on until the brakes have been checked.","een":"Yes. The brakes may fail completely, and it is dangerous to drive on."},{"da":"Det er nok at få bremserne set efter ved næste service.","fa":"کافی است ترمزها در سرویس بعدی بررسی شوند.","ok":0,"eda":"Nej. En fejl ved bremserne skal udbedres, før du kører videre.","efa":"خیر. عیب ترمز باید پیش از ادامه‌ی رانندگی برطرف شود.","en":"It is enough to have the brakes looked at at the next service.","een":"No. A brake fault must be put right before you drive on."},{"da":"Jeg kan køre videre, hvis jeg bare træder hårdere på pedalen.","fa":"اگر پدال را محکم‌تر فشار دهم، می‌توانم ادامه دهم.","ok":0,"eda":"Nej. Fejlen kan blive værre, og som fører skal du sikre dig, at bremserne virker.","efa":"خیر. عیب ممکن است بدتر شود و شما به‌عنوان راننده باید مطمئن شوید ترمزها کار می‌کنند.","en":"I can drive on if I just press the pedal harder.","een":"No. The fault can get worse, and as the driver you must make sure that the brakes work."},{"da":"Det kan skyldes for lidt bremsevæske eller en utæthed i bremsesystemet.","fa":"علتش می‌تواند کم بودن روغن ترمز یا نشتی در سیستم ترمز باشد.","ok":1,"eda":"Ja. Det er typiske årsager til en blød bremsepedal, ligesom luft i systemet.","efa":"بله. این‌ها، مثل هوا در سیستم، علت‌های رایج نرم شدن پدال ترمزند.","en":"It may be caused by too little brake fluid or a leak in the brake system.","een":"Yes. Those are typical causes of a soft brake pedal, as is air in the system."}]},{"id":5327,"img":"newq-art/5327.png","c":"1.2","sda":"Når du bremser, trækker bilen tydeligt til den ene side. Hvad gælder?","sfa":"وقتی ترمز می‌گیرید، خودرو به‌وضوح به یک طرف کشیده می‌شود. چه قاعده‌ای برقرار است؟","sen":"When you brake, the car clearly pulls to one side. What applies?","st":[{"da":"Bremserne virker ikke ens i begge sider, og bilen skal efterses hurtigst muligt.","fa":"ترمزها در دو طرف یکسان کار نمی‌کنند و خودرو باید هرچه زودتر بررسی شود.","ok":1,"eda":"Ja. Ved en hård opbremsning kan bilen skride ud; skævtræk kan også skyldes forskelligt dæktryk.","efa":"بله. در ترمز شدید ممکن است خودرو منحرف شود؛ کشیده شدن می‌تواند از فشار باد متفاوت لاستیک‌ها هم باشد.","en":"The brakes do not work equally on both sides, and the car must be checked as soon as possible.","een":"Yes. In hard braking the car may skid; pulling can also be caused by different tyre pressures."},{"da":"Det skyldes vejens hældning og har intet med bilen at gøre.","fa":"علتش شیب جاده است و ربطی به خودرو ندارد.","ok":0,"eda":"Nej. Trækker bilen tydeligt, hver gang du bremser, er der noget galt med bilen.","efa":"خیر. اگر خودرو هر بار که ترمز می‌گیرید به‌وضوح کشیده شود، خودرو ایراد دارد.","en":"It is caused by the slope of the road and has nothing to do with the car.","een":"No. If the car clearly pulls every time you brake, something is wrong with the car."},{"da":"Det er normalt, at en bil trækker lidt, så jeg retter bare op med rattet.","fa":"طبیعی است که خودرو کمی کشیده شود، پس فقط با فرمان اصلاحش می‌کنم.","ok":0,"eda":"Nej. En bil i orden bremser lige ud; skævtræk er tegn på en fejl.","efa":"خیر. خودروی سالم در خط مستقیم ترمز می‌کند؛ کشیده شدن نشانه‌ی عیب است.","en":"It is normal for a car to pull a little, so I just correct it with the steering wheel.","een":"No. A car in good order brakes in a straight line; pulling is a sign of a fault."}]},{"id":5328,"img":"newq-art/5328.png","c":"1.2","sda":"Du har koblet en trailer på bilen og skal til at køre. Hvad gælder om trailerens lygter?","sfa":"یک تریلر به خودرو وصل کرده‌اید و می‌خواهید راه بیفتید. درباره‌ی چراغ‌های تریلر چه قاعده‌ای برقرار است؟","sen":"You have hitched a trailer to the car and are about to drive. What applies to the trailer's lights?","st":[{"da":"Det er nok, at bilens egne baglygter virker.","fa":"کافی است چراغ‌های عقب خود خودرو کار کنند.","ok":0,"eda":"Nej. Traileren skjuler dem; dens egne lygter skal virke.","efa":"خیر. تریلر آن‌ها را می‌پوشاند؛ چراغ‌های خود تریلر باید کار کنند.","en":"It is enough that the car's own rear lights work.","een":"No. The trailer hides them; its own lights must work."},{"da":"En hjælper kan stå bag traileren og se, om lygterne lyser, når jeg tænder dem og træder på bremsen.","fa":"کسی می‌تواند پشت تریلر بایستد و ببیند وقتی چراغ‌ها را روشن می‌کنم و ترمز می‌گیرم، روشن می‌شوند یا نه.","ok":1,"eda":"Ja. Så kan du kontrollere bremselys og blinklys, som du ikke selv kan se fra førersædet.","efa":"بله. این‌طور چراغ ترمز و راهنماهایی را که از صندلی راننده نمی‌بینید بررسی می‌کنید.","en":"A helper can stand behind the trailer and see whether the lights come on when I switch them on and press the brake.","een":"Yes. That way you can check brake lights and indicators that you cannot see yourself from the driver's seat."},{"da":"Trailerens lygter skal virke, fordi bilens baglygter er skjult bag traileren.","fa":"چراغ‌های تریلر باید کار کنند، چون چراغ‌های عقب خودرو پشت تریلر پنهان می‌شوند.","ok":1,"eda":"Ja. Bagfra er det trailerens lygter og blinklys, der viser de andre, hvad du gør.","efa":"بله. از پشت، چراغ‌ها و راهنماهای تریلر هستند که به دیگران نشان می‌دهند چه می‌کنید.","en":"The trailer's lights must work because the car's rear lights are hidden behind the trailer.","een":"Yes. From behind, it is the trailer's lights and indicators that show the others what you are doing."},{"da":"Jeg sætter stikket i og kontrollerer, at baglygter, bremselys og blinklys virker.","fa":"دوشاخه‌ی برق تریلر را وصل می‌کنم و بررسی می‌کنم چراغ‌های عقب، چراغ ترمز و راهنماها کار کنند.","ok":1,"eda":"Ja. Som fører skal du sikre dig, at lygter og signaler virker, også på traileren.","efa":"بله. شما به‌عنوان راننده باید مطمئن شوید چراغ‌ها و راهنماها کار می‌کنند، روی تریلر هم.","en":"I plug in the connector and check that the rear lights, brake lights and indicators work.","een":"Yes. As the driver you must make sure that the lights and signals work, also on the trailer."}]},{"id":5329,"img":"newq-art/5329.png","c":"7.18","sda":"Din bil er gået i stykker, og du har måttet efterlade den ved kantstenen på en gade med parkeringsforbud. Den kan først blive hentet i morgen. Hvad gælder?","sfa":"خودروتان خراب شده و مجبور شده‌اید آن را کنار جدولِ خیابانی با ممنوعیت پارک بگذارید. فقط فردا می‌شود آن را برد. چه قاعده‌ای برقرار است؟","sen":"Your car has broken down, and you have had to leave it at the kerb in a street with a parking ban. It can only be collected tomorrow. What applies?","st":[{"da":"Bilen regnes først for parkeret, når den har holdt der en uge.","fa":"خودرو فقط وقتی پارک‌شده حساب می‌شود که یک هفته آنجا مانده باشد.","ok":0,"eda":"Nej. Grænsen er 18 timer.","efa":"خیر. این مدت ۱۸ ساعت است.","en":"The car only counts as parked once it has stood there for a week.","een":"No. The limit is 18 hours."},{"da":"Når bilen har holdt der i 18 timer, regnes den for parkeret.","fa":"وقتی خودرو ۱۸ ساعت آنجا مانده باشد، پارک‌شده حساب می‌شود.","ok":1,"eda":"Ja. Et køretøj, der efterlades, fordi det efter et uheld eller en teknisk fejl ikke kan køre videre, anses for parkeret 18 timer efter, at det er hensat.","efa":"بله. وسیله‌ای که به‌خاطر تصادف یا نقص فنی نمی‌تواند ادامه دهد و رها شده، ۱۸ ساعت پس از رها شدن پارک‌شده حساب می‌شود.","en":"When the car has stood there for 18 hours, it counts as parked.","een":"Yes. A vehicle left because it cannot go on after an accident or a technical fault counts as parked 18 hours after it was left."},{"da":"Holder bilen, så den er til fare for andre, skal den fjernes hurtigst muligt, og andre skal advares.","fa":"اگر خودرو طوری ایستاده که برای دیگران خطرناک است، باید هرچه زودتر برداشته شود و به دیگران هشدار داده شود.","ok":1,"eda":"Ja. Et køretøj, der holder, så det er til fare, skal fjernes snarest muligt, og der skal advares, fx med en advarselstrekant.","efa":"بله. وسیله‌ای که در جای خطرناک ایستاده باید هرچه زودتر برداشته شود و هشدار داده شود، مثلاً با مثلث خطر.","en":"If the car stands where it is a danger to others, it must be removed as soon as possible and others must be warned.","een":"Yes. A vehicle standing where it is a danger must be removed as soon as possible, and a warning must be given, for example with a warning triangle."},{"da":"En bil med en teknisk fejl må holde der, lige så længe det tager at få den repareret.","fa":"خودروی دارای نقص فنی تا هر وقت تعمیرش طول بکشد می‌تواند آنجا بماند.","ok":0,"eda":"Nej. Efter 18 timer gælder parkeringsreglerne, også parkeringsforbuddet.","efa":"خیر. پس از ۱۸ ساعت قواعد پارک، از جمله ممنوعیت پارک، برقرار می‌شوند.","en":"A car with a technical fault may stand there for as long as the repair takes.","een":"No. After 18 hours the parking rules apply, including the parking ban."}]},{"id":5330,"img":"newq-art/5330.png","c":"7.18","sda":"Ved kantstenen står en tavle med parkeringsforbud. Undertavlen viser »9–17« og »(9–13)« med sort skrift. Hvad gælder?","sfa":"کنار جدول تابلوی پارک ممنوع هست. زیرتابلو با رنگ مشکی «9–17» و «(9–13)» را نشان می‌دهد. چه قاعده‌ای برقرار است؟","sen":"At the kerb stands a no-parking sign. The plate under it shows «9–17» and «(9–13)» in black. What applies?","st":[{"da":"En søndag må jeg parkere her hele dagen.","fa":"یکشنبه تمام روز می‌توانم اینجا پارک کنم.","ok":1,"eda":"Ja. Tider for søn- og helligdage står med rød skrift; her er der ingen, så forbuddet gælder ikke om søndagen.","efa":"بله. ساعت‌های یکشنبه و تعطیلات رسمی با رنگ قرمز نوشته می‌شوند؛ اینجا چنین ساعتی نیست، پس ممنوعیت یکشنبه برقرار نیست.","en":"On a Sunday I may park here all day.","een":"Yes. Times for Sundays and public holidays are in red; there are none here, so the ban does not apply on Sundays."},{"da":"Tiden i parentes gælder søn- og helligdage.","fa":"ساعت داخل پرانتز برای یکشنبه‌ها و تعطیلات رسمی است.","ok":0,"eda":"Nej. Tider i parentes gælder lørdage; søn- og helligdage står med rød skrift.","efa":"خیر. ساعت‌های داخل پرانتز برای شنبه‌هاست؛ یکشنبه‌ها و تعطیلات با رنگ قرمز نوشته می‌شوند.","en":"The time in brackets applies on Sundays and public holidays.","een":"No. Times in brackets apply on Saturdays; Sundays and public holidays are in red."},{"da":"En tirsdag kl. 18 må jeg parkere her.","fa":"سه‌شنبه ساعت ۱۸ می‌توانم اینجا پارک کنم.","ok":1,"eda":"Ja. Tider med sort skrift gælder på hverdage, og kl. 18 ligger efter forbuddets tidsrum.","efa":"بله. ساعت‌های مشکی برای روزهای کاری‌اند و ساعت ۱۸ بعد از بازه‌ی ممنوعیت است.","en":"On a Tuesday at 6 pm I may park here.","een":"Yes. Times in black apply on weekdays, and 6 pm is after the ban's hours."},{"da":"En lørdag kl. 11 må jeg parkere her.","fa":"شنبه ساعت ۱۱ می‌توانم اینجا پارک کنم.","ok":0,"eda":"Nej. Tiden i parentes gælder lørdage, så forbuddet gælder lørdag fra 9 til 13.","efa":"خیر. ساعت داخل پرانتز برای شنبه‌هاست، پس ممنوعیت شنبه از ۹ تا ۱۳ برقرار است.","en":"On a Saturday at 11 am I may park here.","een":"No. The time in brackets applies on Saturdays, so the ban applies on Saturday from 9 to 13."}]},{"id":5331,"img":"newq-art/5331.png","c":"7.18","sda":"Den eneste ledige bås på parkeringspladsen er afmærket med et motorcykelsymbol. Du kører i bil. Hvad gælder?","sfa":"تنها جای خالی پارکینگ با نماد موتورسیکلت مشخص شده است. شما با خودرو هستید. چه قاعده‌ای برقرار است؟","sen":"The only free bay in the car park is marked with a motorcycle symbol. You are driving a car. What applies?","st":[{"da":"Båsen er forbeholdt motorcykler, så jeg må ikke parkere bilen der.","fa":"این جا مخصوص موتورسیکلت است، پس نباید خودرو را آنجا پارک کنم.","ok":1,"eda":"Ja. Et symbol i båsen, fx for motorcykel, bus eller taxi, forbeholder båsen til den slags køretøjer.","efa":"بله. نمادی داخل جای پارک، مثلاً موتورسیکلت، اتوبوس یا تاکسی، آن جا را مخصوص همان نوع وسیله می‌کند.","en":"The bay is reserved for motorcycles, so I must not park the car there.","een":"Yes. A symbol in the bay, for example for motorcycle, bus or taxi, reserves the bay for that kind of vehicle."},{"da":"Jeg må parkere der, når der ikke holder nogen motorcykler.","fa":"وقتی موتورسیکلتی آنجا نیست، می‌توانم پارک کنم.","ok":0,"eda":"Nej. Båsen er forbeholdt motorcykler, også når den er tom.","efa":"خیر. این جا حتی وقتی خالی است مخصوص موتورسیکلت است.","en":"I may park there when no motorcycles are parked there.","een":"No. The bay is reserved for motorcycles, also when it is empty."},{"da":"Jeg må parkere der, hvis bilen kan være inden for linjerne.","fa":"اگر خودرو داخل خط‌ها جا شود، می‌توانم آنجا پارک کنم.","ok":0,"eda":"Nej. Det er symbolet, der bestemmer, hvem båsen er til, ikke dens størrelse.","efa":"خیر. نماد تعیین می‌کند آن جا برای کیست، نه اندازه‌اش.","en":"I may park there if the car fits inside the lines.","een":"No. It is the symbol that decides whom the bay is for, not its size."}]},{"id":5332,"img":"newq-art/5332.png","c":"7.18","sda":"Du skal handle i en kiosk og regner med at være væk fra bilen i omkring 10 minutter. Hvordan forholder du dig?","sfa":"می‌خواهید از یک فروشگاه کوچک خرید کنید و حدود ۱۰ دقیقه از خودرو دور می‌شوید. چه می‌کنید؟","sen":"You are going shopping in a kiosk and expect to be away from the car for about 10 minutes. What do you do?","st":[{"da":"Jeg lader motoren køre og nøglen sidde, fordi jeg snart er tilbage.","fa":"موتور را روشن و سوئیچ را سر جایش می‌گذارم، چون زود برمی‌گردم.","ok":0,"eda":"Nej. Så kan andre køre væk i bilen; den skal sikres, også når du kun er væk kort tid.","efa":"خیر. این‌طور دیگران می‌توانند با خودرو بروند؛ حتی وقتی کوتاه دور هستید، باید ایمن شود.","en":"I leave the engine running and the key in, because I will soon be back.","een":"No. Then others can drive off in the car; it must be secured, also when you are only away for a short time."},{"da":"Jeg trækker håndbremsen, så bilen ikke kan rulle.","fa":"ترمزدستی را می‌کشم تا خودرو حرکت نکند.","ok":1,"eda":"Ja. Når føreren forlader køretøjet, skal det sikres, så det ikke kan sætte sig i gang af sig selv.","efa":"بله. وقتی راننده از خودرو دور می‌شود، باید آن را طوری ایمن کند که خودبه‌خود راه نیفتد.","en":"I apply the handbrake so that the car cannot roll.","een":"Yes. When the driver leaves the vehicle, it must be secured so that it cannot start moving by itself."},{"da":"Jeg holder et sted, hvor det er tilladt at parkere.","fa":"جایی می‌ایستم که پارک در آن مجاز است.","ok":1,"eda":"Ja. Holder bilen i mere end 3 minutter, er det parkering, og så skal parkeringsreglerne overholdes.","efa":"بله. اگر خودرو بیش از ۳ دقیقه بایستد، پارک حساب می‌شود و باید قواعد پارک رعایت شود.","en":"I stop at a place where parking is allowed.","een":"Yes. If the car stands for more than 3 minutes, it is parking, and then the parking rules must be kept."},{"da":"Jeg låser bilen og tager nøglen med mig.","fa":"درها را قفل می‌کنم و سوئیچ را با خودم می‌برم.","ok":1,"eda":"Ja. Føreren skal sikre, at bilen ikke uberettiget kan bruges af andre.","efa":"بله. راننده باید مطمئن شود دیگران بدون اجازه نمی‌توانند از خودرو استفاده کنند.","en":"I lock the car and take the key with me.","een":"Yes. The driver must make sure that the car cannot be used by others without permission."}]},{"id":5333,"img":"newq-art/5333.png","c":"7.18","sda":"Uden for byen vil du holde ind og ringe til nogen. Mellem kørebanen og cykelstien er der en bred græsrabat. Hvad gælder?","sfa":"بیرون شهر می‌خواهید کنار بکشید و به کسی زنگ بزنید. بین سواره‌رو و مسیر دوچرخه یک نوار چمنی پهن هست. چه قاعده‌ای برقرار است؟","sen":"Outside town you want to pull in and phone someone. Between the carriageway and the cycle path there is a wide grass verge. What applies?","st":[{"da":"Inde i byen må jeg ikke holde med hjulene oppe på fortovet.","fa":"داخل شهر نباید با چرخ‌ها روی پیاده‌رو بایستم.","ok":1,"eda":"Ja. Undtagelsen for fortov og skillerabat gælder kun uden for tættere bebygget område.","efa":"بله. استثنای پیاده‌رو و نوار جداکننده فقط بیرون از محدوده‌ی شهری برقرار است.","en":"In town I must not stand with the wheels up on the pavement.","een":"Yes. The exception for pavements and separating verges only applies outside built-up areas."},{"da":"Rabatten må kun bruges af lastbiler.","fa":"از نوار چمنی فقط کامیون‌ها می‌توانند استفاده کنند.","ok":0,"eda":"Nej. Undtagelsen gælder netop køretøjer på højst 3.500 kg, fx almindelige personbiler.","efa":"خیر. این استثنا دقیقاً برای وسایل حداکثر ۳٬۵۰۰ کیلوگرمی، مثل خودروهای سواری معمولی، است.","en":"The verge may only be used by lorries.","een":"No. The exception is precisely for vehicles of at most 3,500 kg, such as ordinary cars."},{"da":"Jeg må holde på cykelstien, når der ikke kommer cyklister.","fa":"وقتی دوچرخه‌سواری نمی‌آید، می‌توانم روی مسیر دوچرخه بایستم.","ok":0,"eda":"Nej. Standsning og parkering på cykelsti er forbudt.","efa":"خیر. توقف و پارک روی مسیر دوچرخه ممنوع است.","en":"I may stand on the cycle path when no cyclists are coming.","een":"No. Stopping and parking on a cycle path are forbidden."},{"da":"Jeg må holde med en del af bilen på græsrabatten.","fa":"می‌توانم با بخشی از خودرو روی نوار چمنی بایستم.","ok":1,"eda":"Ja. Uden for tættere bebygget område må et køretøj på højst 3.500 kg standse eller parkere med en del af køretøjet på fortov eller skillerabat.","efa":"بله. بیرون از محدوده‌ی شهری، وسیله‌ای با وزن کل مجاز حداکثر ۳٬۵۰۰ کیلوگرم می‌تواند با بخشی از خود روی پیاده‌رو یا نوار جداکننده توقف یا پارک کند.","en":"I may stand with part of the car on the grass verge.","een":"Yes. Outside built-up areas a vehicle of at most 3,500 kg may stop or park with part of the vehicle on a pavement or a separating verge."}]},{"id":5334,"img":"newq-art/5334.png","c":"7.9","sda":"Op ad en lang bakke har din side af vejen to vognbaner, mens de modkørende har én. En langsom lastbil kører i den højre vognbane, og du kan ikke se over bakketoppen. Hvad gælder?","sfa":"در یک سربالایی طولانی، سمت شما دو خط دارد و سمت مقابل یک خط. یک کامیون کُند در خط راست می‌رود و آن طرف بالای تپه را نمی‌بینید. چه قاعده‌ای برقرار است؟","sen":"Up a long hill, your side of the road has two lanes, while the oncoming traffic has one. A slow lorry is in the right lane, and you cannot see over the hilltop. What applies?","st":[{"da":"Jeg må aldrig overhale før en bakketop.","fa":"هیچ‌وقت نباید پیش از بالای تپه سبقت بگیرم.","ok":0,"eda":"Nej. Med mindst to vognbaner i din retning uden modkørende er det tilladt.","efa":"خیر. با دست‌کم دو خط در جهت شما و بدون ترافیک روبه‌رو در آن‌ها، مجاز است.","en":"I may never overtake before a hilltop.","een":"No. With at least two lanes in your direction and no oncoming traffic in them, it is allowed."},{"da":"Lastbilen skal køre over i venstre vognbane, så jeg kan komme forbi i højre.","fa":"کامیون باید به خط چپ برود تا من از راست رد شوم.","ok":0,"eda":"Nej. Langsomme køretøjer skal holde til højre, og overhaling sker til venstre.","efa":"خیر. وسایل کُند باید سمت راست بمانند و سبقت از چپ انجام می‌شود.","en":"The lorry must move over into the left lane so that I can get past on the right.","een":"No. Slow vehicles must keep right, and overtaking is done on the left."},{"da":"Jeg må ikke køre over i de modkørendes vognbane.","fa":"نباید وارد خط ترافیک روبه‌رو شوم.","ok":1,"eda":"Ja. Midterlinjen er ubrudt, og over bakketoppen kan der komme modkørende, som du ikke kan se.","efa":"بله. خط وسط ممتد است و ممکن است از آن طرف تپه وسایلی بیایند که آن‌ها را نمی‌بینید.","en":"I must not move over into the oncoming lane.","een":"Yes. The centre line is unbroken, and oncoming traffic you cannot see may come over the hilltop."},{"da":"Jeg må godt overhale lastbilen i min venstre vognbane, selv om jeg ikke kan se over bakketoppen.","fa":"می‌توانم در خط چپِ سمت خودم از کامیون سبقت بگیرم، با این‌که آن طرف تپه را نمی‌بینم.","ok":1,"eda":"Ja. Forbuddet mod overhaling ved uoverskuelige bakker gælder ikke, når kørebanen i din retning har mindst to vognbaner, hvor der ikke må komme modkørende.","efa":"بله. ممنوعیت سبقت در تپه‌های بی‌دید وقتی برقرار نیست که سواره‌روی سمت شما دست‌کم دو خط داشته باشد که ترافیک روبه‌رو حق ورود به آن‌ها را ندارد.","en":"I may overtake the lorry in my left lane, even though I cannot see over the hilltop.","een":"Yes. The ban on overtaking at blind hills does not apply when the carriageway in your direction has at least two lanes where oncoming traffic is not allowed."}]},{"id":5335,"img":"newq-art/5335.png","c":"7.9","sda":"Det regner kraftigt, og lastbilen foran dig sprøjter så meget vand op, at du dårligt kan se. Du vil overhale den. Hvordan forholder du dig?","sfa":"باران شدیدی می‌بارد و کامیونِ جلو آن‌قدر آب به هوا می‌پاشد که به‌سختی می‌بینید. می‌خواهید از آن سبقت بگیرید. چه می‌کنید؟","sen":"It is raining heavily, and the lorry in front of you throws up so much spray that you can hardly see. You want to overtake it. What do you do?","st":[{"da":"Jeg overhaler kun, hvis jeg kan se, at den modsatte vognbane er fri langt nok frem.","fa":"فقط وقتی سبقت می‌گیرم که ببینم خط مقابل تا فاصله‌ی کافی خالی است.","ok":1,"eda":"Ja. Før du overhaler, skal du sikre dig, at den modsatte vognbane er fri på en tilstrækkelig lang strækning.","efa":"بله. پیش از سبقت باید مطمئن شوید خط مقابل در طول کافی خالی است.","en":"I only overtake if I can see that the opposite lane is clear far enough ahead.","een":"Yes. Before you overtake, you must make sure that the opposite lane is clear for a long enough stretch."},{"da":"Jeg holder større afstand til lastbilen, så jeg bedre kan se frem forbi den.","fa":"فاصله‌ام را با کامیون بیشتر می‌کنم تا جلوی مسیر را از کنار آن بهتر ببینم.","ok":1,"eda":"Ja. Tæt bag lastbilen er du inde i vandtågen og kan hverken se de modkørende eller vejen.","efa":"بله. نزدیک کامیون وسط مه آب هستید و نه ترافیک روبه‌رو را می‌بینید نه جاده را.","en":"I keep a larger distance to the lorry so that I can see better ahead past it.","een":"Yes. Close behind the lorry you are inside the spray and can see neither the oncoming traffic nor the road."},{"da":"Jeg lægger mig tæt bag lastbilen, så overhalingen tager kortere tid.","fa":"نزدیک پشت کامیون می‌روم تا سبقت کوتاه‌تر شود.","ok":0,"eda":"Nej. Tæt bag den ser du endnu mindre, og du har ikke tid til at reagere, hvis den bremser.","efa":"خیر. نزدیکش حتی کمتر می‌بینید و اگر ترمز کند فرصت واکنش ندارید.","en":"I move up close behind the lorry so that the overtaking takes less time.","een":"No. Close behind it you see even less, and you have no time to react if it brakes."},{"da":"Jeg sætter viskerne på højeste hastighed, før jeg trækker ud.","fa":"پیش از بیرون رفتن، برف‌پاک‌کن‌ها را روی بیشترین سرعت می‌گذارم.","ok":1,"eda":"Ja. Når du kører op langs lastbilen, får du ekstra meget vand på forruden.","efa":"بله. وقتی کنار کامیون می‌رسید، آب خیلی بیشتری روی شیشه‌ی جلو می‌ریزد.","en":"I set the wipers to the highest speed before I pull out.","een":"Yes. When you drive up alongside the lorry, you get a lot of extra water on the windscreen."}]},{"id":5336,"img":"newq-art/5336.png","c":"7.9","sda":"Foran dig kører fire biler i kø bag en traktor. Du vil gerne forbi. Hvad gælder?","sfa":"جلوی شما چهار خودرو پشت یک تراکتور صف کشیده‌اند و می‌روند. می‌خواهید رد شوید. چه قاعده‌ای برقرار است؟","sen":"In front of you, four cars are driving in a queue behind a tractor. You would like to get past. What applies?","st":[{"da":"Jeg må overhale køen i højre side, hvis der er en bred rabat.","fa":"اگر شانه‌ی جاده پهن باشد، می‌توانم از سمت راست از صف سبقت بگیرم.","ok":0,"eda":"Nej. Overhaling skal ske til venstre, og rabatten er ikke til at køre på.","efa":"خیر. سبقت باید از چپ باشد و شانه‌ی جاده برای رانندگی نیست.","en":"I may overtake the queue on the right if there is a wide verge.","een":"No. Overtaking must be done on the left, and the verge is not for driving on."},{"da":"Skal jeg forbi hele køen på én gang, skal den modsatte vognbane være fri over en meget lang strækning.","fa":"اگر بخواهم یک‌جا از کل صف رد شوم، خط مقابل باید در مسافت خیلی طولانی خالی باشد.","ok":1,"eda":"Ja. Jo flere køretøjer du skal forbi, jo længere tid er du i den modsatte vognbane.","efa":"بله. هرچه از وسایل بیشتری بخواهید رد شوید، مدت بیشتری در خط مقابل هستید.","en":"If I am to pass the whole queue in one go, the opposite lane must be clear over a very long stretch.","een":"Yes. The more vehicles you have to pass, the longer you are in the opposite lane."},{"da":"Kommer der en modkørende, kan jeg bare presse mig ind i et hul i køen.","fa":"اگر خودرویی از روبه‌رو بیاید، کافی است خودم را در یک فاصله‌ی خالیِ صف جا بدهم.","ok":0,"eda":"Nej. Du må kun begynde, når du har plads til at komme ind igen uden fare; et hul i køen kan være for lille.","efa":"خیر. فقط وقتی می‌توانید شروع کنید که جای کافی برای برگشتن بی‌خطر داشته باشید؛ فاصله‌ی داخل صف ممکن است خیلی کم باشد.","en":"If an oncoming car appears, I can just squeeze into a gap in the queue.","een":"No. You may only begin when you have room to get back in safely; a gap in the queue may be too small."},{"da":"Jeg må ikke begynde at overhale, hvis bilen foran mig selv har givet tegn til at overhale.","fa":"اگر خودروی جلوی من خودش برای سبقت راهنما زده باشد، نباید سبقت را شروع کنم.","ok":1,"eda":"Ja. Før du overhaler, skal du sikre dig, at den forankørende ikke har givet tegn til, at den vil overhale.","efa":"بله. پیش از سبقت باید مطمئن شوید وسیله‌ی جلویی برای سبقت علامت نداده است.","en":"I must not begin overtaking if the car in front of me has itself signalled to overtake.","een":"Yes. Before you overtake, you must make sure that the one in front has not signalled that it is going to overtake."}]},{"id":5337,"img":"newq-art/5337.png","c":"7.9","sda":"Traktoren foran dig kører ind til højre, og føreren vinker dig forbi. Hvordan forholder du dig?","sfa":"تراکتورِ جلو به راست کنار می‌کشد و راننده‌اش با دست اشاره می‌کند که رد شوید. چه می‌کنید؟","sen":"The tractor in front of you moves in to the right, and the driver waves you past. What do you do?","st":[{"da":"Når traktorføreren vinker, er det ham, der har ansvaret, hvis der sker noget.","fa":"وقتی راننده‌ی تراکتور اشاره می‌کند، اگر اتفاقی بیفتد او مسئول است.","ok":0,"eda":"Nej. Ansvaret for overhalingen er dit.","efa":"خیر. مسئولیت سبقت با شماست.","en":"When the tractor driver waves, he is the one responsible if something happens.","een":"No. The responsibility for the overtaking is yours."},{"da":"Vinket betyder, at jeg trygt kan overhale med det samme.","fa":"اشاره‌ی دست یعنی می‌توانم فوراً و با خیال راحت سبقت بگیرم.","ok":0,"eda":"Nej. Traktorføreren kan tage fejl eller se noget andet end dig; svinget foran skjuler vejen.","efa":"خیر. راننده‌ی تراکتور ممکن است اشتباه کند یا چیز دیگری ببیند؛ پیچ جلو جاده را پنهان کرده است.","en":"The wave means that I can safely overtake straight away.","een":"No. The tractor driver may be mistaken or see something different from you; the bend ahead hides the road."},{"da":"Jeg sikrer mig selv, at vejen foran er fri, før jeg overhaler.","fa":"خودم مطمئن می‌شوم جاده‌ی جلو خالی است و بعد سبقت می‌گیرم.","ok":1,"eda":"Ja. Det er dig, der overhaler, og dig, der skal sikre, at det kan ske uden fare.","efa":"بله. سبقت‌گیرنده شما هستید و شما باید مطمئن شوید بی‌خطر است.","en":"I make sure myself that the road ahead is clear before I overtake.","een":"Yes. You are the one overtaking, and you must make sure that it can be done safely."}]},{"id":5338,"img":"newq-art/5338.png","c":"7.9","sda":"Du er ved at overhale en bil på landevejen, men den sætter farten op, så du ikke kommer forbi. Hvordan forholder du dig?","sfa":"در جاده‌ی بیرون شهر در حال سبقت از یک خودرو هستید، ولی سرعتش را بالا می‌برد و نمی‌توانید رد شوید. چه می‌کنید؟","sen":"You are overtaking a car on a country road, but it speeds up so that you cannot get past. What do you do?","st":[{"da":"Jeg sætter farten op over hastighedsgrænsen for at komme forbi.","fa":"سرعتم را از حد مجاز بالاتر می‌برم تا رد شوم.","ok":0,"eda":"Nej. Hastighedsgrænsen gælder også under overhaling.","efa":"خیر. حد سرعت هنگام سبقت هم برقرار است.","en":"I speed up above the speed limit to get past.","een":"No. The speed limit also applies when overtaking."},{"da":"Jeg opgiver overhalingen og lægger mig ind bag bilen igen.","fa":"از سبقت منصرف می‌شوم و دوباره پشت آن خودرو قرار می‌گیرم.","ok":1,"eda":"Ja. Kan overhalingen ikke gennemføres uden fare, skal du afbryde den i tide.","efa":"بله. اگر سبقت بی‌خطر تمام نمی‌شود، باید به‌موقع آن را رها کنید.","en":"I give up the overtaking and move back in behind the car.","een":"Yes. If the overtaking cannot be completed safely, you must break it off in time."},{"da":"Jeg trækker ind foran bilen, så snart min front er forbi den.","fa":"به محض این‌که جلوی خودرویم از آن رد شد، جلویش می‌پیچم.","ok":0,"eda":"Nej. Du skal have plads til at komme ind igen uden fare for den, du overhaler.","efa":"خیر. باید جای کافی داشته باشید تا بدون خطر برای کسی که از او سبقت گرفته‌اید برگردید.","en":"I pull in in front of the car as soon as my front is past it.","een":"No. You must have room to get back in without danger to the one you are overtaking."},{"da":"Den, der bliver overhalet, må ikke sætte farten op.","fa":"کسی که از او سبقت گرفته می‌شود نباید سرعتش را بالا ببرد.","ok":1,"eda":"Ja. Når du bliver overhalet, skal du holde til højre og ikke øge farten.","efa":"بله. وقتی از شما سبقت گرفته می‌شود، باید سمت راست بمانید و سرعت را زیاد نکنید.","en":"The one being overtaken must not speed up.","een":"Yes. When you are being overtaken, you must keep right and not increase your speed."}]},{"id":5339,"img":"newq-art/5339.png","c":"6.1","sda":"Du kører forbi denne tavle på motorvejen. Hvad betyder den?","sfa":"در آزادراه از کنار این تابلو می‌گذرید. معنی‌اش چیست؟","sen":"You pass this sign on the motorway. What does it mean?","st":[{"da":"Tavlen viser, at der er vejarbejde.","fa":"این تابلو نشان می‌دهد کار جاده‌ای در جریان است.","ok":0,"eda":"Nej. Vejarbejde har sin egen advarselstavle med en person, der graver.","efa":"خیر. کار جاده‌ای تابلوی هشدار خودش را دارد که فردی را در حال کندن نشان می‌دهد.","en":"The sign shows that there are road works.","een":"No. Road works have their own warning sign showing a person digging."},{"da":"Jeg skal skifte til venstre vognbane.","fa":"باید به خط چپ بروم.","ok":0,"eda":"Nej. Tavlen er en advarsel og siger ikke noget om, hvilken vognbane du skal bruge.","efa":"خیر. این تابلو هشدار است و درباره‌ی این‌که از کدام خط استفاده کنید چیزی نمی‌گوید.","en":"I must change to the left lane.","een":"No. The sign is a warning and says nothing about which lane to use."},{"da":"Der er særlig risiko for kø længere fremme.","fa":"جلوتر خطر ویژه‌ی تشکیل صف وجود دارد.","ok":1,"eda":"Ja. Tavlen angiver særlig risiko for kødannelse; sænk farten, hold afstand, og vær klar til at bremse.","efa":"بله. این تابلو خطر ویژه‌ی تشکیل صف را نشان می‌دهد؛ سرعت را کم کنید، فاصله بگیرید و آماده‌ی ترمز باشید.","en":"There is a particular risk of queues further ahead.","een":"Yes. The sign shows a particular risk of queues forming; slow down, keep your distance and be ready to brake."},{"da":"Tavlen betyder, at overhaling er forbudt.","fa":"این تابلو یعنی سبقت ممنوع است.","ok":0,"eda":"Nej. Det er en advarselstavle, ikke et forbud.","efa":"خیر. این تابلوی هشدار است، نه ممنوعیت.","en":"The sign means that overtaking is forbidden.","een":"No. It is a warning sign, not a ban."}]},{"id":5340,"img":"newq-art/5340.png","c":"6.1","sda":"Du kører forbi denne tavle uden for byen. Det har regnet kraftigt. Hvad betyder tavlen?","sfa":"بیرون شهر از کنار این تابلو می‌گذرید. باران شدیدی باریده است. معنی تابلو چیست؟","sen":"You pass this sign outside town. It has been raining heavily. What does the sign mean?","st":[{"da":"Vejen fører ned til en havn eller et færgeleje.","fa":"جاده به بندر یا اسکله‌ی کشتی می‌رسد.","ok":0,"eda":"Nej. Det er en anden tavle, der advarer om havnekaj og færgeleje.","efa":"خیر. تابلوی دیگری درباره‌ی اسکله و محل پهلوگیری کشتی هشدار می‌دهد.","en":"The road leads down to a harbour or a ferry berth.","een":"No. It is a different sign that warns of a quay or a ferry berth."},{"da":"Tavlen gælder kun, når det sner.","fa":"این تابلو فقط وقتی برف می‌بارد برقرار است.","ok":0,"eda":"Nej. Advarslen gælder især ved kraftig regn, hvor der kan samle sig vand i lavningen.","efa":"خیر. این هشدار به‌ویژه در باران شدید است که آب در گودی جمع می‌شود.","en":"The sign only applies when it snows.","een":"No. The warning matters especially in heavy rain, when water can collect in the dip."},{"da":"Der er et vejbump længere fremme.","fa":"جلوتر یک سرعت‌گیر هست.","ok":0,"eda":"Nej. Vejbump har deres egen advarselstavle.","efa":"خیر. سرعت‌گیر تابلوی هشدار خودش را دارد.","en":"There is a speed hump further ahead.","een":"No. Speed humps have their own warning sign."},{"da":"Der er en lavning i vejen, hvor der kan stå vand på kørebanen.","fa":"در جاده یک گودی هست که ممکن است روی سواره‌رو آب جمع شده باشد.","ok":1,"eda":"Ja. Tavlen angiver en lunke i vejen, hvor der ved kraftig nedbør kan være vand på kørebanen.","efa":"بله. این تابلو گودی‌ای در جاده را نشان می‌دهد که در بارش شدید ممکن است روی سواره‌رو آب باشد.","en":"There is a dip in the road where water may lie on the carriageway.","een":"Yes. The sign shows a dip in the road where there may be water on the carriageway in heavy rain."}]},{"id":5341,"img":"newq-art/5341.png","c":"6.1","sda":"Ved grænsen kører du forbi denne tavle. Hvad betyder den?","sfa":"در مرز از کنار این تابلو می‌گذرید. معنی‌اش چیست؟","sen":"At the border you pass this sign. What does it mean?","st":[{"da":"Jeg skal kun standse, hvis en betjent vinker mig ind.","fa":"فقط وقتی باید بایستم که مأموری اشاره کند.","ok":0,"eda":"Nej. Tavlen kræver, at du standser, også uden et tegn.","efa":"خیر. این تابلو حتی بدون اشاره هم شما را ملزم به توقف می‌کند.","en":"I only have to stop if an officer waves me in.","een":"No. The sign requires you to stop, also without a signal."},{"da":"Tavlen angiver en hastighedsgrænse ved grænsen.","fa":"این تابلو حد سرعت در مرز را نشان می‌دهد.","ok":0,"eda":"Nej. Det er et forbud mod at køre forbi uden at standse, ikke en hastighedsgrænse.","efa":"خیر. این ممنوعیتِ عبور بدون توقف است، نه حد سرعت.","en":"The sign shows a speed limit at the border.","een":"No. It is a ban on passing without stopping, not a speed limit."},{"da":"Tavlen betyder, at kørsel er forbudt i begge retninger.","fa":"این تابلو یعنی رانندگی در هر دو جهت ممنوع است.","ok":0,"eda":"Nej. Du må køre videre, når du har standset ved kontrollen.","efa":"خیر. پس از توقف در محل بازرسی می‌توانید ادامه دهید.","en":"The sign means that driving is forbidden in both directions.","een":"No. You may drive on once you have stopped at the check."},{"da":"Jeg skal standse ved kontrolstedet og må ikke køre forbi uden at standse.","fa":"باید در محل بازرسی بایستم و بدون توقف نباید رد شوم.","ok":1,"eda":"Ja. Tavlen forbyder passage uden stop; grunden, her told, står på tavlen.","efa":"بله. این تابلو عبور بدون توقف را ممنوع می‌کند؛ دلیلش، اینجا گمرک، روی تابلو نوشته شده است.","en":"I must stop at the check point and must not drive past without stopping.","een":"Yes. The sign bans passing without stopping; the reason, here customs, is on the sign."}]},{"id":5342,"img":"newq-art/5342.png","c":"6.1","sda":"Du kører forbi denne tavle. Lidt længere fremme begynder de røde lys ved broen at lyse, og bommene går ned. Hvad gælder?","sfa":"از کنار این تابلو می‌گذرید. کمی جلوتر چراغ‌های قرمز کنار پل روشن می‌شوند و راهبندها پایین می‌آیند. چه قاعده‌ای برقرار است؟","sen":"You pass this sign. A little further ahead the red lights at the bridge come on and the barriers come down. What applies?","st":[{"da":"Tavlen advarer om en bro, der kan åbnes for skibe.","fa":"این تابلو درباره‌ی پلی هشدار می‌دهد که برای عبور کشتی‌ها باز می‌شود.","ok":1,"eda":"Ja. Tavlen advarer om en oplukkelig bro.","efa":"بله. این تابلو درباره‌ی پل متحرک (بازشونده) هشدار می‌دهد.","en":"The sign warns of a bridge that can be opened for ships.","een":"Yes. The sign warns of an opening bridge."},{"da":"Jeg skynder mig over, før bommene er helt nede.","fa":"عجله می‌کنم تا پیش از پایین آمدن کامل راهبندها رد شوم.","ok":0,"eda":"Nej. Rødt lys betyder stop, og broen kan begynde at åbne sig.","efa":"خیر. چراغ قرمز یعنی ایست و ممکن است پل شروع به باز شدن کند.","en":"I hurry across before the barriers are fully down.","een":"No. A red light means stop, and the bridge may begin to open."},{"da":"Jeg standser før bommen og venter, til broen er lukket, og bommene er oppe igen.","fa":"پیش از راهبند می‌ایستم و صبر می‌کنم تا پل بسته شود و راهبندها دوباره بالا بروند.","ok":1,"eda":"Ja. Rødt lys betyder stop, og broen er spærret, mens den er åben for skibe.","efa":"بله. چراغ قرمز یعنی ایست، و تا وقتی پل برای کشتی‌ها باز است، عبور بسته است.","en":"I stop before the barrier and wait until the bridge has closed and the barriers are up again.","een":"Yes. A red light means stop, and the bridge is closed to traffic while it is open for ships."},{"da":"Tavlen betyder, at broen altid er lukket for biler.","fa":"این تابلو یعنی پل همیشه به روی خودروها بسته است.","ok":0,"eda":"Nej. Broen er kun spærret, når den åbnes for skibe.","efa":"خیر. پل فقط وقتی بسته است که برای کشتی‌ها باز می‌شود.","en":"The sign means that the bridge is always closed to cars.","een":"No. The bridge is only closed when it opens for ships."}]},{"id":5343,"img":"newq-art/5343.png","c":"7.6","sda":"Foran dig kører en ledig taxi. Lidt længere fremme står en mand på fortovet og rækker armen op mod den. Hvordan forholder du dig?","sfa":"جلوی شما یک تاکسی آزاد می‌رود. کمی جلوتر مردی روی پیاده‌رو ایستاده و دستش را به طرف تاکسی بالا برده است. چه می‌کنید؟","sen":"A free taxi is driving in front of you. A little further ahead a man stands on the pavement holding his arm up towards it. What do you do?","st":[{"da":"Manden kan træde ud på kørebanen for at komme hen til taxien.","fa":"آن مرد ممکن است برای رسیدن به تاکسی وارد سواره‌رو شود.","ok":1,"eda":"Ja. Gående, der har travlt med at nå en taxi, ser sig ikke altid for.","efa":"بله. عابرانی که برای رسیدن به تاکسی عجله دارند همیشه حواسشان به اطراف نیست.","en":"The man may step out onto the carriageway to get to the taxi.","een":"Yes. Pedestrians in a hurry to catch a taxi do not always look out."},{"da":"Taxien skal blinke i mindst 5 sekunder, før den holder ind.","fa":"تاکسی باید پیش از کنار کشیدن دست‌کم ۵ ثانیه راهنما بزند.","ok":0,"eda":"Nej. Der er ingen sådan regel; der skal gives tegn i god tid, men du må regne med, at det kan komme sent.","efa":"خیر. چنین قاعده‌ای نیست؛ باید به‌موقع راهنما زد، ولی باید انتظار داشته باشید دیر زده شود.","en":"The taxi must signal for at least 5 seconds before it pulls in.","een":"No. There is no such rule; a signal must be given in good time, but you must expect that it may come late."},{"da":"Jeg holder større afstand, fordi taxien kan bremse og holde ind uden ret meget varsel.","fa":"فاصله‌ی بیشتری می‌گیرم، چون تاکسی ممکن است بدون هشدار زیاد ترمز کند و کنار بکشد.","ok":1,"eda":"Ja. Du skal holde så stor afstand, at du ikke kører ind i den forankørende, hvis den standser.","efa":"بله. باید آن‌قدر فاصله بگیرید که اگر وسیله‌ی جلویی ایستاد، به آن نزنید.","en":"I keep a larger distance because the taxi may brake and pull in without much warning.","een":"Yes. You must keep such a distance that you do not run into the one in front if it stops."},{"da":"Holder taxien ind, må jeg dytte, så passageren skynder sig.","fa":"اگر تاکسی کنار بکشد، می‌توانم بوق بزنم تا مسافر عجله کند.","ok":0,"eda":"Nej. Hornet må kun bruges for at forebygge eller afværge fare.","efa":"خیر. از بوق فقط برای پیشگیری یا دفع خطر می‌توان استفاده کرد.","en":"If the taxi pulls in, I may sound the horn so that the passenger hurries.","een":"No. The horn may only be used to prevent or avert danger."}]},{"id":5344,"img":"newq-art/5344.png","c":"7.6","sda":"En cyklist kører foran dig i højre side af vejen. Lidt længere fremme holder en varevogn parkeret ved kantstenen, og en bil kommer imod dig. Hvordan forholder du dig?","sfa":"دوچرخه‌سواری جلوی شما در سمت راست جاده می‌راند. کمی جلوتر یک ون کنار جدول پارک شده و خودرویی از روبه‌رو می‌آید. چه می‌کنید؟","sen":"A cyclist is riding in front of you on the right side of the road. A little further ahead a van is parked at the kerb, and a car is coming towards you. What do you do?","st":[{"da":"Jeg skynder mig forbi cyklisten, før vi når varevognen.","fa":"عجله می‌کنم تا پیش از رسیدن به ون از دوچرخه‌سوار رد شوم.","ok":0,"eda":"Nej. Så kan I ende side om side lige ved varevognen, hvor cyklisten trækker ud.","efa":"خیر. ممکن است درست کنار ون، جایی که دوچرخه‌سوار به وسط می‌آید، کنار هم قرار بگیرید.","en":"I hurry past the cyclist before we reach the van.","een":"No. Then you may end up side by side right at the van, where the cyclist pulls out."},{"da":"Der kan også stige nogen ud af varevognen eller gå frem bag den.","fa":"ممکن است کسی هم از ون پیاده شود یا از پشتش بیرون بیاید.","ok":1,"eda":"Ja. Holdende køretøjer kan skjule gående og døre, der bliver åbnet.","efa":"بله. وسایل متوقف ممکن است عابران و درهایی را که باز می‌شوند پنهان کنند.","en":"Someone may also get out of the van or step out from behind it.","een":"Yes. Stationary vehicles can hide pedestrians and doors being opened."},{"da":"Jeg regner med, at cyklisten trækker ud for at komme forbi varevognen.","fa":"انتظار دارم دوچرخه‌سوار برای رد شدن از کنار ون به سمت وسط جاده بیاید.","ok":1,"eda":"Ja. Cyklisten skal uden om varevognen og kommer derfor længere ud på vejen.","efa":"بله. دوچرخه‌سوار باید دور ون بزند و بنابراین بیشتر وارد جاده می‌شود.","en":"I expect the cyclist to pull out to get past the van.","een":"Yes. The cyclist has to go round the van and so comes further out into the road."},{"da":"Jeg sænker farten og venter med at køre forbi cyklisten, til der er plads.","fa":"سرعتم را کم می‌کنم و تا جا باز نشده از کنار دوچرخه‌سوار رد نمی‌شوم.","ok":1,"eda":"Ja. Ved varevognen og med en modkørende bliver der ikke plads til at give cyklisten god sideafstand.","efa":"بله. کنار ون و با وجود خودروی روبه‌رو، جای کافی برای فاصله‌ی مناسب از دوچرخه‌سوار نمی‌ماند.","en":"I slow down and wait to drive past the cyclist until there is room.","een":"Yes. At the van, with an oncoming car, there will not be room to give the cyclist a good side distance."}]},{"id":5345,"img":"newq-art/5345.png","c":"7.6","sda":"Fortovet er spærret på grund af vejarbejde, så de gående må gå ude på kørebanen. Hvordan forholder du dig?","sfa":"پیاده‌رو به‌خاطر کار جاده‌ای بسته شده و عابران مجبورند روی سواره‌رو راه بروند. چه می‌کنید؟","sen":"The pavement is closed because of road works, so pedestrians have to walk out on the carriageway. What do you do?","st":[{"da":"Jeg sænker farten og giver de gående god plads.","fa":"سرعتم را کم می‌کنم و به عابران جای کافی می‌دهم.","ok":1,"eda":"Ja. Hvor der arbejdes på vejen, og gående færdes på kørebanen, skal farten være passende lav.","efa":"بله. جایی که روی جاده کار می‌کنند و عابران روی سواره‌رو هستند، سرعت باید به اندازه‌ی کافی کم باشد.","en":"I slow down and give the pedestrians plenty of room.","een":"Yes. Where there is work on the road and pedestrians are on the carriageway, the speed must be suitably low."},{"da":"De gående har ikke lov at gå på kørebanen, så de skal vige for mig.","fa":"عابران اجازه ندارند روی سواره‌رو راه بروند، پس باید برای من کنار بروند.","ok":0,"eda":"Nej. Når fortovet ikke kan bruges, må de gå på kørebanen, og du skal tage hensyn til dem.","efa":"خیر. وقتی نمی‌شود از پیاده‌رو استفاده کرد، می‌توانند روی سواره‌رو راه بروند و شما باید مراقبشان باشید.","en":"The pedestrians are not allowed to walk on the carriageway, so they must give way to me.","een":"No. When the pavement cannot be used, they may walk on the carriageway, and you must take care of them."},{"da":"Er der ikke plads til at komme forbi, venter jeg bag dem.","fa":"اگر جا برای رد شدن نیست، پشتشان صبر می‌کنم.","ok":1,"eda":"Ja. Du må først køre forbi, når det kan ske uden fare for de gående.","efa":"بله. فقط وقتی می‌توانید رد شوید که برای عابران خطری نداشته باشد.","en":"If there is no room to get past, I wait behind them.","een":"Yes. You may only drive past when it can be done without danger to the pedestrians."}]},{"id":5346,"img":"newq-art/5346.png","c":"7.6","sda":"En koncert i parken er lige slut, og mange mennesker går langs vejen og over den. Hvordan forholder du dig?","sfa":"یک کنسرت در پارک تازه تمام شده و افراد زیادی کنار جاده و از عرض آن رد می‌شوند. چه می‌کنید؟","sen":"A concert in the park has just ended, and many people are walking along the road and across it. What do you do?","st":[{"da":"Jeg dytter, så folk går ind til siden.","fa":"بوق می‌زنم تا مردم کنار بروند.","ok":0,"eda":"Nej. Hornet må kun bruges for at forebygge eller afværge fare.","efa":"خیر. بوق فقط برای پیشگیری یا دفع خطر است.","en":"I sound the horn so that people move to the side.","een":"No. The horn may only be used to prevent or avert danger."},{"da":"Dirigerer politiet trafikken, følger jeg deres tegn.","fa":"اگر پلیس ترافیک را هدایت می‌کند، از علامت‌هایش پیروی می‌کنم.","ok":1,"eda":"Ja. Politiets anvisninger går forud for tavler, signaler og færdselsreglerne.","efa":"بله. دستورهای پلیس بر تابلوها، چراغ‌ها و قواعد رانندگی مقدم است.","en":"If the police are directing the traffic, I follow their signals.","een":"Yes. Police directions take precedence over signs, signals and the traffic rules."},{"da":"Jeg kører meget langsomt og er klar til at standse.","fa":"خیلی آهسته می‌رانم و آماده‌ی توقف هستم.","ok":1,"eda":"Ja. Mange gående på og ved vejen kræver en passende lav hastighed.","efa":"بله. عابران زیاد روی جاده و کنار آن سرعت مناسبِ کمی می‌طلبد.","en":"I drive very slowly and am ready to stop.","een":"Yes. Many pedestrians on and beside the road call for a suitably low speed."},{"da":"Jeg må regne med, at nogle går ud på vejen uden at se sig for.","fa":"باید انتظار داشته باشم برخی بدون نگاه کردن وارد جاده شوند.","ok":1,"eda":"Ja. I en menneskemængde holder den enkelte ikke altid øje med trafikken.","efa":"بله. در جمعیت، افراد همیشه حواسشان به ترافیک نیست.","en":"I must expect some people to step onto the road without looking.","een":"Yes. In a crowd, individuals do not always keep an eye on the traffic."}]},{"id":5347,"img":"newq-art/5347.png","c":"7.3","sda":"Ved indkørslen til gågaden står denne tavle med en undertavle, der tillader varekørsel om morgenen. Du skal aflevere varer i en butik i gaden. Hvad gælder?","sfa":"در ورودی خیابان پیاده این تابلو با زیرتابلویی هست که صبح‌ها رفت‌وآمد برای حمل کالا را مجاز می‌کند. باید به مغازه‌ای در این خیابان کالا تحویل دهید. چه قاعده‌ای برقرار است؟","sen":"At the entrance to the pedestrian street stands this sign with a plate that allows deliveries in the morning. You have to deliver goods to a shop in the street. What applies?","st":[{"da":"Når kørsel er tilladt, gælder den almindelige grænse på 50 km/t i byen.","fa":"وقتی رانندگی مجاز است، همان حد معمول ۵۰ کیلومتر بر ساعتِ شهر برقرار است.","ok":0,"eda":"Nej. Gaden er beregnet til gående, og du må kun køre meget langsomt.","efa":"خیر. این خیابان برای عابران است و فقط خیلی آهسته می‌توانید برانید.","en":"When driving is allowed, the ordinary 50 km/h limit in town applies.","een":"No. The street is meant for pedestrians, and you may only drive very slowly."},{"da":"Jeg må kun køre meget langsomt, normalt under 15 km/t.","fa":"فقط خیلی آهسته، معمولاً زیر ۱۵ کیلومتر بر ساعت، می‌توانم برانم.","ok":1,"eda":"Ja. I en gågade må der kun køres med meget lav hastighed (normalt under 15 km/t).","efa":"بله. در خیابان پیاده فقط با سرعت خیلی کم (معمولاً زیر ۱۵ کیلومتر بر ساعت) می‌توان راند.","en":"I may only drive very slowly, normally under 15 km/h.","een":"Yes. In a pedestrian street, driving may only be done at a very low speed (normally under 15 km/h)."},{"da":"Jeg må kun parkere på særligt afmærkede pladser.","fa":"فقط در جاهای مخصوصِ مشخص‌شده می‌توانم پارک کنم.","ok":1,"eda":"Ja. Parkering i en gågade må ikke ske uden for særligt afmærkede pladser.","efa":"بله. پارک در خیابان پیاده بیرون از جاهای مخصوصِ مشخص‌شده مجاز نیست.","en":"I may only park in specially marked places.","een":"Yes. Parking in a pedestrian street must not take place outside specially marked places."},{"da":"Jeg må køre ind i gågaden når som helst, fordi jeg har varer med.","fa":"چون کالا همراهم دارم، هر وقت بخواهم می‌توانم وارد خیابان پیاده شوم.","ok":0,"eda":"Nej. Undertavlen bestemmer, hvornår kørslen er tilladt.","efa":"خیر. زیرتابلو تعیین می‌کند چه زمانی رانندگی مجاز است.","en":"I may drive into the pedestrian street at any time because I am carrying goods.","een":"No. The plate decides when driving is allowed."}]},{"id":5348,"img":"newq-art/5348.png","c":"7.3","sda":"Du kører ind i Danmark og passerer denne tavle. Hvad gælder?","sfa":"وارد دانمارک می‌شوید و از کنار این تابلو می‌گذرید. چه قاعده‌ای برقرار است؟","sen":"You drive into Denmark and pass this sign. What applies?","st":[{"da":"Tavlen viser de generelle hastighedsgrænser i landet.","fa":"این تابلو حدهای سرعت عمومی کشور را نشان می‌دهد.","ok":1,"eda":"Ja. Tavlen angiver de generelle hastighedsbegrænsninger, som gælder i landet.","efa":"بله. این تابلو محدودیت‌های سرعت عمومی کشور را نشان می‌دهد.","en":"The sign shows the general speed limits in the country.","een":"Yes. The sign shows the general speed limits that apply in the country."},{"da":"Uden andre tavler er grænsen 50 km/t i byen, 80 km/t uden for byen og 130 km/t på motorvej.","fa":"بدون تابلوهای دیگر، حد سرعت در شهر ۵۰، بیرون شهر ۸۰ و در آزادراه ۱۳۰ کیلومتر بر ساعت است.","ok":1,"eda":"Ja. Det er de generelle grænser for personbiler i Danmark.","efa":"بله. این‌ها حدهای عمومی برای خودروهای سواری در دانمارک‌اند.","en":"Without other signs the limit is 50 km/h in town, 80 km/h outside town and 130 km/h on the motorway.","een":"Yes. Those are the general limits for cars in Denmark."},{"da":"Undertavlen minder om, at kørelys, sikkerhedssele og sikkerhedsudstyr til børn er påbudt.","fa":"زیرتابلو یادآوری می‌کند که چراغ روشن در روز، کمربند ایمنی و تجهیزات ایمنی کودک الزامی‌اند.","ok":1,"eda":"Ja. Undertavlen angiver, at det er påbudt at bruge kørelys, sikkerhedsseler og sikkerhedsudstyr til børn.","efa":"بله. زیرتابلو نشان می‌دهد استفاده از چراغ روشن در روز، کمربند ایمنی و تجهیزات ایمنی کودک الزامی است.","en":"The plate is a reminder that daytime running lights, seat belts and child safety equipment are compulsory.","een":"Yes. The plate shows that using daytime running lights, seat belts and child safety equipment is compulsory."},{"da":"Grænserne gælder kun for biler med danske nummerplader.","fa":"این حدها فقط برای خودروهای دارای پلاک دانمارکی است.","ok":0,"eda":"Nej. Reglerne gælder for alle, der kører i Danmark.","efa":"خیر. این قواعد برای همه‌ی کسانی است که در دانمارک رانندگی می‌کنند.","en":"The limits only apply to cars with Danish number plates.","een":"No. The rules apply to everyone driving in Denmark."}]},{"id":5349,"img":"newq-art/5349.png","c":"7.3","sda":"Du kører forbi denne tavle. Hvad betyder den?","sfa":"از کنار این تابلو می‌گذرید. معنی‌اش چیست؟","sen":"You pass this sign. What does it mean?","st":[{"da":"Der kan være automatisk trafikkontrol, fx fartkontrol med kamera.","fa":"ممکن است کنترل خودکار ترافیک باشد، مثلاً کنترل سرعت با دوربین.","ok":1,"eda":"Ja. Tavlen angiver, at der kan være automatisk trafikkontrol (ATK).","efa":"بله. این تابلو نشان می‌دهد ممکن است کنترل خودکار ترافیک (ATK) باشد.","en":"There may be automatic traffic control, for example speed checks with a camera.","een":"Yes. The sign shows that there may be automatic traffic control (ATK)."},{"da":"Tavlen viser, hvor hurtigt jeg kører.","fa":"این تابلو نشان می‌دهد با چه سرعتی می‌رانم.","ok":0,"eda":"Nej. Det gør en fartviser, som er en anden tavle.","efa":"خیر. این کار را نمایشگر سرعت انجام می‌دهد که تابلوی دیگری است.","en":"The sign shows how fast I am driving.","een":"No. A speed display does that, which is a different sign."},{"da":"Hastighedsgrænsen er sat ned på strækningen.","fa":"حد سرعت در این مسیر کم شده است.","ok":0,"eda":"Nej. Tavlen ændrer ikke hastighedsgrænsen.","efa":"خیر. این تابلو حد سرعت را تغییر نمی‌دهد.","en":"The speed limit has been lowered on the stretch.","een":"No. The sign does not change the speed limit."},{"da":"Jeg må køre lidt over grænsen, fordi kameraet kun registrerer store overskridelser.","fa":"می‌توانم کمی بیشتر از حد مجاز برانم، چون دوربین فقط تخلف‌های بزرگ را ثبت می‌کند.","ok":0,"eda":"Nej. Hastighedsgrænsen gælder altid, uanset om der er kontrol.","efa":"خیر. حد سرعت همیشه برقرار است، چه کنترل باشد چه نباشد.","en":"I may drive a little over the limit because the camera only registers large excesses.","een":"No. The speed limit always applies, whether or not there is a check."}]},{"id":5350,"img":"newq-art/5350.png","c":"7.3","sda":"Du kører på en hovedvej og nærmer dig et kryds. På sidevejene er der hajtænder, og en bil holder i sidevejen til højre. Hvordan forholder du dig?","sfa":"در یک جاده‌ی اصلی می‌رانید و به تقاطعی نزدیک می‌شوید. در خیابان‌های فرعی دندان‌کوسه هست و خودرویی در خیابان فرعیِ سمت راست منتظر است. چه می‌کنید؟","sen":"You are driving on a main road and approaching a junction. The side roads have shark teeth, and a car is waiting in the side road on the right. What do you do?","st":[{"da":"Jeg holder en passende lav hastighed ved krydset, selv om jeg har forkørselsret.","fa":"با این‌که حق تقدم دارم، در تقاطع سرعتم را به اندازه‌ی کافی پایین نگه می‌دارم.","ok":1,"eda":"Ja. Ved vejkryds skal kørende holde en efter forholdene passende lav hastighed.","efa":"بله. در تقاطع‌ها رانندگان باید سرعتی متناسب با شرایط و به اندازه‌ی کافی پایین داشته باشند.","en":"I keep a suitably low speed at the junction, even though I have priority.","een":"Yes. At junctions drivers must keep a speed suitably low for the conditions."},{"da":"Hajtænderne betyder, at jeg skal holde tilbage for bilerne fra sidevejene.","fa":"دندان‌کوسه‌ها یعنی من باید به خودروهای خیابان‌های فرعی راه بدهم.","ok":0,"eda":"Nej. Hajtænderne gælder for dem på sidevejene; det er dem, der har ubetinget vigepligt.","efa":"خیر. دندان‌کوسه‌ها برای کسانی است که در خیابان‌های فرعی‌اند؛ آن‌ها باید بی‌قیدوشرط راه بدهند.","en":"The shark teeth mean that I must give way to the cars from the side roads.","een":"No. The shark teeth apply to those on the side roads; they are the ones who must give way."},{"da":"Bilen i sidevejen kan have overset mig.","fa":"ممکن است خودروی خیابان فرعی مرا ندیده باشد.","ok":1,"eda":"Ja. Du skal være forberedt på, at andre begår fejl.","efa":"بله. باید آماده باشید که دیگران اشتباه کنند.","en":"The car in the side road may have overlooked me.","een":"Yes. You must be prepared for others to make mistakes."},{"da":"Med forkørselsret må jeg køre gennem krydset med fuld fart.","fa":"با حق تقدم می‌توانم با سرعت کامل از تقاطع رد شوم.","ok":0,"eda":"Nej. Forkørselsret fjerner ikke kravet om passende lav hastighed ved kryds.","efa":"خیر. حق تقدم الزام سرعت مناسبِ پایین در تقاطع را از بین نمی‌برد.","en":"With priority I may drive through the junction at full speed.","een":"No. Priority does not remove the requirement for a suitably low speed at junctions."}]},{"id":5351,"img":"newq-art/5351.png","c":"7.12","sda":"Du har afleveret varer i gågaden og vil køre ud af den og ligeud over vejen for enden. Hvad gælder?","sfa":"در خیابان پیاده کالا تحویل داده‌اید و می‌خواهید از آن خارج شوید و مستقیم از عرض جاده‌ی انتهای آن رد شوید. چه قاعده‌ای برقرار است؟","sen":"You have delivered goods in the pedestrian street and want to drive out of it and straight across the road at its end. What applies?","st":[{"da":"Jeg har ubetinget vigepligt over for trafikken på vejen.","fa":"باید بی‌قیدوشرط به ترافیک جاده راه بدهم.","ok":1,"eda":"Ja. Kørende har ubetinget vigepligt ved udkørsel fra en gågade.","efa":"بله. رانندگان هنگام خروج از خیابان پیاده باید بی‌قیدوشرط راه بدهند.","en":"I must give way to the traffic on the road.","een":"Yes. Drivers must give way when they drive out of a pedestrian street."},{"da":"Biler fra venstre skal holde tilbage for mig, fordi jeg kommer fra højre.","fa":"خودروهای سمت چپ باید به من راه بدهند، چون من از راست می‌آیم.","ok":0,"eda":"Nej. Højre vigepligt hjælper ikke dig, når du kører ud fra en gågade.","efa":"خیر. قاعده‌ی حق تقدم سمت راست هنگام خروج از خیابان پیاده به نفع شما نیست.","en":"Cars from the left must give way to me because I come from the right.","een":"No. The right-hand rule does not help you when you drive out of a pedestrian street."},{"da":"Jeg holder også tilbage for cyklisten på cykelstien.","fa":"به دوچرخه‌سوارِ مسیر دوچرخه هم راه می‌دهم.","ok":1,"eda":"Ja. Vigepligten gælder over for alle kørende på den vej, du kører ud på, også cyklister.","efa":"بله. این وظیفه در برابر همه‌ی وسایلِ جاده‌ای است که واردش می‌شوید، دوچرخه‌سواران هم.","en":"I also give way to the cyclist on the cycle path.","een":"Yes. The duty applies to all traffic on the road you drive out onto, cyclists too."},{"da":"Jeg har kun vigepligt, hvis der er hajtænder.","fa":"فقط وقتی باید راه بدهم که دندان‌کوسه باشد.","ok":0,"eda":"Nej. Vigepligten ved udkørsel fra en gågade gælder også uden afmærkning.","efa":"خیر. وظیفه‌ی راه دادن هنگام خروج از خیابان پیاده بدون خط‌کشی هم برقرار است.","en":"I only have to give way if there are shark teeth.","een":"No. The duty to give way when leaving a pedestrian street applies also without markings."}]},{"id":5352,"img":"newq-art/5352.png","c":"7.12","sda":"Lyssignalerne i krydset er slukket på grund af en fejl. Der er ingen tavler eller hajtænder. En bil kommer fra højre. Hvad gælder?","sfa":"چراغ‌های راهنمایی تقاطع به‌خاطر نقص خاموش‌اند. هیچ تابلو یا دندان‌کوسه‌ای نیست. خودرویی از راست می‌آید. چه قاعده‌ای برقرار است؟","sen":"The traffic lights at the junction are switched off because of a fault. There are no signs or shark teeth. A car is coming from the right. What applies?","st":[{"da":"Jeg har forkørselsret, fordi jeg kører på den største vej.","fa":"چون در جاده‌ی بزرگ‌تر هستم، حق تقدم دارم.","ok":0,"eda":"Nej. Vejens størrelse giver ikke forkørselsret; det gør kun tavler og afmærkning.","efa":"خیر. بزرگی جاده حق تقدم نمی‌دهد؛ فقط تابلو و خط‌کشی می‌دهد.","en":"I have priority because I am on the larger road.","een":"No. The size of the road does not give priority; only signs and markings do."},{"da":"Bilen fra højre skal have lov at køre først.","fa":"خودروی سمت راست باید اول برود.","ok":1,"eda":"Ja. Når signalerne er slukket, og der ikke er anden afmærkning, gælder højre vigepligt.","efa":"بله. وقتی چراغ‌ها خاموش‌اند و علامت دیگری نیست، حق تقدم سمت راست برقرار است.","en":"The car from the right must be allowed to go first.","een":"Yes. When the signals are off and there is no other marking, the right-hand rule applies."},{"da":"Den, der kommer først til krydset, må køre først.","fa":"هر کس اول به تقاطع برسد، اول می‌رود.","ok":0,"eda":"Nej. Det er højre vigepligt, der gælder, ikke hvem der kom først.","efa":"خیر. قاعده‌ی سمت راست برقرار است، نه این‌که چه کسی اول رسیده.","en":"Whoever reaches the junction first may go first.","een":"No. It is the right-hand rule that applies, not who came first."},{"da":"Krydset må ikke bruges, før signalerne virker igen.","fa":"تا وقتی چراغ‌ها دوباره کار نکنند، نباید از تقاطع استفاده کرد.","ok":0,"eda":"Nej. Du må køre gennem krydset efter de almindelige vigepligtsregler.","efa":"خیر. می‌توانید طبق قواعد معمول حق تقدم از تقاطع رد شوید.","en":"The junction must not be used until the signals work again.","een":"No. You may drive through the junction under the ordinary give-way rules."}]},{"id":5353,"img":"newq-art/5353.png","c":"7.12","sda":"Du vil køre ligeud i et kryds uden tavler og afmærkning. Fra højre kommer en bybus, som også skal ligeud. Hvad gælder?","sfa":"می‌خواهید در تقاطعی بدون تابلو و خط‌کشی مستقیم بروید. از سمت راست یک اتوبوس شهری می‌آید که آن هم مستقیم می‌رود. چه قاعده‌ای برقرار است؟","sen":"You want to go straight on at a junction without signs or markings. A city bus is coming from the right, also going straight on. What applies?","st":[{"da":"Jeg holder tilbage for bussen.","fa":"به اتوبوس راه می‌دهم.","ok":1,"eda":"Ja. Højre vigepligt gælder over for alle køretøjer fra højre, også busser.","efa":"بله. حق تقدم سمت راست برای همه‌ی وسایلی است که از راست می‌آیند، از جمله اتوبوس.","en":"I give way to the bus.","een":"Yes. The right-hand rule applies to all vehicles from the right, buses too."},{"da":"Bussen skal holde tilbage for mig, fordi den er langsom og stor.","fa":"اتوبوس باید به من راه بدهد، چون کُند و بزرگ است.","ok":0,"eda":"Nej. Et køretøjs fart og størrelse har intet med vigepligten at gøre.","efa":"خیر. سرعت و اندازه‌ی وسیله ربطی به حق تقدم ندارد.","en":"The bus must give way to me because it is slow and big.","een":"No. A vehicle's speed and size have nothing to do with the duty to give way."},{"da":"Busser i rutekørsel skal altid holde tilbage for personbiler i kryds.","fa":"اتوبوس‌های خط همیشه باید در تقاطع به خودروهای سواری راه بدهند.","ok":0,"eda":"Nej. Der er ingen sådan regel; i et kryds uden tavler gælder højre vigepligt for alle.","efa":"خیر. چنین قاعده‌ای نیست؛ در تقاطع بدون تابلو حق تقدم سمت راست برای همه برقرار است.","en":"Buses on regular routes must always give way to cars at junctions.","een":"No. There is no such rule; at a junction without signs the right-hand rule applies to everyone."}]},{"id":5354,"img":"newq-art/5354.png","c":"7.12","sda":"Du skal ligeud over en jernbaneoverkørsel med bomme. Lige efter overkørslen holder bilerne i kø. Hvordan forholder du dig?","sfa":"باید مستقیم از روی یک تقاطع راه‌آهنِ دارای راهبند رد شوید. درست بعد از آن خودروها در صف ایستاده‌اند. چه می‌کنید؟","sen":"You are going straight on over a level crossing with barriers. Just after the crossing the cars are standing in a queue. What do you do?","st":[{"da":"Blinker de røde lys, eller er bommene på vej ned, standser jeg før overkørslen.","fa":"اگر چراغ‌های قرمز چشمک بزنند یا راهبندها در حال پایین آمدن باشند، پیش از تقاطع می‌ایستم.","ok":1,"eda":"Ja. Så nærmer der sig et tog, og du må ikke køre ud på overkørslen.","efa":"بله. یعنی قطاری نزدیک می‌شود و نباید وارد تقاطع شوید.","en":"If the red lights flash or the barriers are coming down, I stop before the crossing.","een":"Yes. Then a train is approaching, and you must not drive onto the crossing."},{"da":"Går bommene ned, mens jeg holder på sporet, bliver jeg stående og venter, til toget er kørt forbi.","fa":"اگر وقتی روی ریل هستم راهبندها پایین بیایند، همان‌جا می‌مانم تا قطار رد شود.","ok":0,"eda":"Nej. Du skal straks væk fra sporet; et tog kan ikke standse i tide.","efa":"خیر. باید فوراً از روی ریل دور شوید؛ قطار نمی‌تواند به‌موقع بایستد.","en":"If the barriers come down while I am on the tracks, I stay where I am and wait until the train has passed.","een":"No. You must get off the tracks at once; a train cannot stop in time."},{"da":"Jeg venter før overkørslen, til der er plads til hele bilen på den anden side.","fa":"پیش از ریل صبر می‌کنم تا آن طرف برای تمام خودرو جا باشد.","ok":1,"eda":"Ja. Du må ikke risikere at blive holdende på sporet.","efa":"بله. نباید این خطر را بپذیرید که روی ریل بمانید.","en":"I wait before the crossing until there is room for the whole car on the other side.","een":"Yes. You must not risk being left standing on the tracks."},{"da":"Det er forbudt at standse på en jernbaneoverkørsel.","fa":"توقف روی تقاطع راه‌آهن ممنوع است.","ok":1,"eda":"Ja. Standsning og parkering er forbudt på en jernbaneoverkørsel.","efa":"بله. توقف و پارک روی تقاطع راه‌آهن ممنوع است.","en":"Stopping on a level crossing is forbidden.","een":"Yes. Stopping and parking are forbidden on a level crossing."}]},{"id":5355,"img":"newq-art/5355.png","c":"7.12","sda":"Du kører ligeud ad gaden. Fra en parkeringsplads til højre er en bil ved at køre ud. Hvad gælder?","sfa":"در خیابان مستقیم می‌رانید. از یک پارکینگ در سمت راست خودرویی در حال بیرون آمدن است. چه قاعده‌ای برقرار است؟","sen":"You are driving straight along the street. From a car park on the right a car is about to drive out. What applies?","st":[{"da":"Bilen fra parkeringspladsen har ubetinget vigepligt over for mig.","fa":"خودرویی که از پارکینگ بیرون می‌آید باید بی‌قیدوشرط به من راه بدهد.","ok":1,"eda":"Ja. Den, der kører ud fra en parkeringsplads, har ubetinget vigepligt.","efa":"بله. هر کس از پارکینگ بیرون می‌آید، باید بی‌قیدوشرط راه بدهد.","en":"The car from the car park must give way to me.","een":"Yes. Anyone driving out of a car park must give way."},{"da":"Jeg holder øje med bilen og er klar til at bremse, hvis den kører ud foran mig.","fa":"مراقب آن خودرو هستم و اگر جلویم بیرون بیاید، آماده‌ی ترمزم.","ok":1,"eda":"Ja. Du skal være forberedt på, at føreren kan overse dig.","efa":"بله. باید آماده باشید که راننده شما را نبیند.","en":"I watch the car and am ready to brake if it drives out in front of me.","een":"Yes. You must be prepared for the driver to overlook you."},{"da":"Jeg har vigepligt, fordi bilen kommer fra min højre side.","fa":"باید راه بدهم، چون آن خودرو از سمت راست من می‌آید.","ok":0,"eda":"Nej. Højre vigepligt gælder ikke for den, der kører ud fra en parkeringsplads.","efa":"خیر. قاعده‌ی سمت راست برای کسی که از پارکینگ بیرون می‌آید برقرار نیست.","en":"I have to give way because the car comes from my right-hand side.","een":"No. The right-hand rule does not apply to someone driving out of a car park."},{"da":"Bilen må køre ud, så snart den har givet tegn.","fa":"آن خودرو به محض راهنما زدن می‌تواند بیرون بیاید.","ok":0,"eda":"Nej. Blinklyset giver ikke ret til at køre ud foran andre.","efa":"خیر. راهنما حق بیرون آمدن جلوی دیگران را نمی‌دهد.","en":"The car may drive out as soon as it has signalled.","een":"No. The indicator gives no right to drive out in front of others."}]},{"id":5356,"img":"newq-art/5356.png","c":"7.12","sda":"Du kører ligeud gennem et T-kryds uden tavler og afmærkning. Sidevejen kommer fra venstre, og der holder en bil i den. Hvad gælder?","sfa":"از یک سه‌راهی بدون تابلو و خط‌کشی مستقیم می‌گذرید. خیابان فرعی از چپ وصل می‌شود و خودرویی در آن منتظر است. چه قاعده‌ای برقرار است؟","sen":"You are driving straight through a T-junction without signs or markings. The side road joins from the left, and a car is waiting in it. What applies?","st":[{"da":"Jeg skal holde tilbage, fordi bilen allerede holder ved krydset.","fa":"باید راه بدهم، چون آن خودرو زودتر به تقاطع رسیده است.","ok":0,"eda":"Nej. Det afgørende er, hvem der kommer fra højre, ikke hvem der kom først.","efa":"خیر. تعیین‌کننده این است که چه کسی از راست می‌آید، نه این‌که چه کسی زودتر رسیده.","en":"I must give way because the car is already waiting at the junction.","een":"No. What decides it is who comes from the right, not who arrived first."},{"da":"Bilen i sidevejen skal holde tilbage for mig.","fa":"خودروی داخل خیابان فرعی باید به من راه بدهد.","ok":1,"eda":"Ja. Højre vigepligt gælder også i T-kryds, og for bilen i sidevejen kommer du fra højre.","efa":"بله. قاعده‌ی سمت راست در سه‌راهی هم برقرار است و برای خودروی خیابان فرعی، شما از راست می‌آیید.","en":"The car in the side road must give way to me.","een":"Yes. The right-hand rule also applies at T-junctions, and for the car in the side road you come from the right."},{"da":"I et T-kryds skal den, der kører ligeud, altid holde tilbage.","fa":"در سه‌راهی کسی که مستقیم می‌رود همیشه باید راه بدهد.","ok":0,"eda":"Nej. Det er højre vigepligt, der gælder; lå sidevejen til højre, skulle du holde tilbage for bilen i den.","efa":"خیر. قاعده‌ی سمت راست برقرار است؛ اگر خیابان فرعی سمت راست بود، باید به خودروی داخل آن راه می‌دادید.","en":"At a T-junction the one going straight on must always give way.","een":"No. It is the right-hand rule that applies; if the side road were on the right, you would have to give way to the car in it."}]},{"id":5357,"img":"newq-art/5357.png","c":"7.14","sda":"Du vil svinge til venstre i et kryds uden tavler og afmærkning. En bil kommer imod dig og skal ligeud, og en anden bil kommer fra højre. Hvad gælder?","sfa":"می‌خواهید در تقاطعی بدون تابلو و خط‌کشی به چپ بپیچید. خودرویی از روبه‌رو می‌آید و مستقیم می‌رود و خودروی دیگری از راست می‌آید. چه قاعده‌ای برقرار است؟","sen":"You want to turn left at a junction without signs or markings. A car is coming towards you and going straight on, and another car is coming from the right. What applies?","st":[{"da":"Den modkørende skal holde tilbage for mig, fordi jeg blinker.","fa":"خودروی روبه‌رو باید به من راه بدهد، چون من راهنما زده‌ام.","ok":0,"eda":"Nej. Blinklyset viser, hvad du vil, men giver dig ingen ret.","efa":"خیر. راهنما نشان می‌دهد چه می‌خواهید بکنید، ولی حقی به شما نمی‌دهد.","en":"The oncoming car must give way to me because I am signalling.","een":"No. The indicator shows what you intend to do, but gives you no right."},{"da":"Jeg må svinge først, fordi jeg kom først til krydset.","fa":"چون اول به تقاطع رسیدم، می‌توانم اول بپیچم.","ok":0,"eda":"Nej. Hvem der kom først, betyder ikke noget for vigepligten.","efa":"خیر. این‌که چه کسی اول رسیده در حق تقدم اثری ندارد.","en":"I may turn first because I reached the junction first.","een":"No. Who came first does not matter for the duty to give way."},{"da":"Jeg holder også tilbage for bilen fra højre.","fa":"به خودروی سمت راست هم راه می‌دهم.","ok":1,"eda":"Ja. I et kryds uden tavler og afmærkning gælder højre vigepligt.","efa":"بله. در تقاطع بدون تابلو و خط‌کشی حق تقدم سمت راست برقرار است.","en":"I also give way to the car from the right.","een":"Yes. At a junction without signs or markings the right-hand rule applies."},{"da":"Jeg holder tilbage for den modkørende, der skal ligeud.","fa":"به خودروی روبه‌رو که مستقیم می‌رود راه می‌دهم.","ok":1,"eda":"Ja. Den, der svinger til venstre, skal holde tilbage for modkørende.","efa":"بله. کسی که به چپ می‌پیچد باید به ترافیک روبه‌رو راه بدهد.","en":"I give way to the oncoming car going straight on.","een":"Yes. Anyone turning left must give way to oncoming traffic."}]},{"id":5358,"img":"newq-art/5358.png","c":"7.14","sda":"Der er to vognbaner til venstresving i krydset, og du holder i den højre af dem. Hvordan svinger du?","sfa":"در تقاطع دو خط گردش به چپ هست و شما در خط سمت راستیِ آن دو هستید. چطور می‌پیچید؟","sen":"There are two left-turn lanes at the junction, and you are in the right one. How do you turn?","st":[{"da":"Jeg må skære over i den venstre vognbane i svinget, hvis den er fri.","fa":"اگر خط چپ خالی باشد، می‌توانم وسط پیچ به آن بروم.","ok":0,"eda":"Nej. Et vognbaneskift i krydset kan overraske bilen ved siden af; skift først bane efter krydset, når det kan ske uden fare.","efa":"خیر. تغییر خط داخل تقاطع ممکن است خودروی کناری را غافلگیر کند؛ فقط بعد از تقاطع و وقتی بی‌خطر است خط عوض کنید.","en":"I may cut across into the left lane during the turn if it is free.","een":"No. A lane change in the junction can surprise the car beside you; change lanes only after the junction, when it can be done safely."},{"da":"Bilen i den venstre vognbane skal vente, til jeg har svunget.","fa":"خودروی خط چپ باید صبر کند تا من بپیچم.","ok":0,"eda":"Nej. I svinger samtidig, hver i sin egen vognbane.","efa":"خیر. هم‌زمان می‌پیچید، هر کدام در خط خودش.","en":"The car in the left lane must wait until I have turned.","een":"No. You turn at the same time, each in your own lane."},{"da":"Jeg bliver i min egen bane gennem svinget og ender i den højre vognbane på den nye vej.","fa":"در طول پیچ در خط خودم می‌مانم و در خط راستِ جاده‌ی جدید قرار می‌گیرم.","ok":1,"eda":"Ja. Bilen ved siden af svinger samtidig; skifter du bane i svinget, kan I støde sammen.","efa":"بله. خودروی کناری هم‌زمان می‌پیچد؛ اگر وسط پیچ خط عوض کنید، ممکن است با هم برخورد کنید.","en":"I stay in my own lane through the turn and end up in the right lane of the new road.","een":"Yes. The car beside you turns at the same time; if you change lanes in the turn, you may collide."},{"da":"Jeg holder øje med bilen i vognbanen til venstre for mig.","fa":"مراقب خودروی خط سمت چپم هستم.","ok":1,"eda":"Ja. Den kan komme for tæt på eller skære svinget.","efa":"بله. ممکن است بیش از حد نزدیک شود یا پیچ را میان‌بُر بزند.","en":"I keep an eye on the car in the lane to my left.","een":"Yes. It may come too close or cut the turn."}]},{"id":5359,"img":"newq-art/5359.png","c":"7.14","sda":"Du vil svinge til venstre. En modkørende lastbil vil også svinge til venstre og holder i krydset. Den skjuler, om der kommer noget bag den. Hvordan forholder du dig?","sfa":"می‌خواهید به چپ بپیچید. یک کامیون از روبه‌رو هم می‌خواهد به چپ بپیچد و داخل تقاطع ایستاده است و نمی‌گذارد ببینید پشتش چیزی می‌آید یا نه. چه می‌کنید؟","sen":"You want to turn left. An oncoming lorry also wants to turn left and is waiting in the junction. It hides whether anything is coming behind it. What do you do?","st":[{"da":"Når lastbilen holder stille, kan jeg regne med, at der ikke kommer andre.","fa":"وقتی کامیون ایستاده، می‌توانم فرض کنم کس دیگری نمی‌آید.","ok":0,"eda":"Nej. Lastbilen holder for at svinge; der kan sagtens komme trafik ligeud bag den.","efa":"خیر. کامیون برای پیچیدن ایستاده؛ ممکن است پشتش ترافیکی مستقیم بیاید.","en":"When the lorry is standing still, I can assume that no one else is coming.","een":"No. The lorry is waiting to turn; traffic may well be coming straight on behind it."},{"da":"Jeg venter, til jeg kan se, at der ikke kommer modkørende ligeud.","fa":"صبر می‌کنم تا ببینم ترافیکی از روبه‌رو مستقیم نمی‌آید.","ok":1,"eda":"Ja. Du skal holde tilbage for modkørende; kan du ikke se dem, ved du ikke, om vejen er fri.","efa":"بله. باید به ترافیک روبه‌رو راه بدهید؛ وقتی آن را نمی‌بینید، نمی‌دانید راه باز است یا نه.","en":"I wait until I can see that no oncoming traffic is going straight on.","een":"Yes. You must give way to oncoming traffic; if you cannot see it, you do not know whether the way is clear."},{"da":"En motorcykel eller en cyklist kan være skjult bag lastbilen.","fa":"ممکن است یک موتورسیکلت یا دوچرخه‌سوار پشت کامیون پنهان باشد.","ok":1,"eda":"Ja. Små trafikanter ses dårligt bag store køretøjer.","efa":"بله. کاربران کوچک راه پشت وسایل بزرگ به‌سختی دیده می‌شوند.","en":"A motorcycle or a cyclist may be hidden behind the lorry.","een":"Yes. Small road users are hard to see behind large vehicles."},{"da":"Jeg kan køre lidt frem, så jeg bedre kan se forbi lastbilen, hvis det kan ske uden fare.","fa":"اگر بی‌خطر باشد، می‌توانم کمی جلو بروم تا کنار کامیون را بهتر ببینم.","ok":1,"eda":"Ja. En bedre placering kan give dig udsyn, men du svinger først, når du kan se, at der er fri bane.","efa":"بله. جای بهتر می‌تواند دید بدهد، ولی فقط وقتی می‌پیچید که ببینید راه باز است.","en":"I can move forward a little to see better past the lorry, if it can be done safely.","een":"Yes. A better position can give you a view, but you only turn when you can see that the way is clear."}]},{"id":5360,"img":"newq-art/5360.png","c":"7.14","sda":"Du holder i venstresvingsbanen. Signalet for din vognbane viser en rød pil mod venstre, mens signalet for ligeud viser grønt. Hvad gælder?","sfa":"در خط گردش به چپ هستید. چراغِ خط شما یک فلش قرمز رو به چپ نشان می‌دهد، در حالی که چراغِ مستقیم سبز است. چه قاعده‌ای برقرار است؟","sen":"You are in the left-turn lane. The signal for your lane shows a red arrow to the left, while the signal for straight on shows green. What applies?","st":[{"da":"Jeg må svinge, når der ikke kommer modkørende, fordi der er grønt for ligeud.","fa":"وقتی ترافیکی از روبه‌رو نمی‌آید، می‌توانم بپیچم، چون چراغ مستقیم سبز است.","ok":0,"eda":"Nej. Det grønne lys for ligeud gælder ikke for dig, der skal til venstre.","efa":"خیر. چراغ سبزِ مستقیم برای شما که به چپ می‌روید نیست.","en":"I may turn when no oncoming traffic is coming, because it is green for straight on.","een":"No. The green light for straight on does not apply to you turning left."},{"da":"Den røde pil betyder, at jeg skal svinge forsigtigt.","fa":"فلش قرمز یعنی باید با احتیاط بپیچم.","ok":0,"eda":"Nej. Rødt betyder stop, også når lyset har form som en pil.","efa":"خیر. قرمز یعنی ایست، حتی وقتی چراغ به شکل فلش است.","en":"The red arrow means that I must turn carefully.","een":"No. Red means stop, also when the light is shaped like an arrow."},{"da":"Jeg holder for rødt, til min pil bliver grøn.","fa":"پشت چراغ قرمز می‌مانم تا فلش من سبز شود.","ok":1,"eda":"Ja. Et pilsignal gælder for dem, der vil køre i den retning, pilen viser.","efa":"بله. چراغ فلش‌دار برای کسانی است که می‌خواهند در جهت فلش بروند.","en":"I wait at red until my arrow turns green.","een":"Yes. An arrow signal applies to those who want to go the way the arrow shows."}]},{"id":5361,"img":"newq-art/5361.png","c":"7.14","sda":"Det er mørkt, og du vil svinge til venstre. Et køretøj med kun én forlygte kommer imod dig. Hvordan forholder du dig?","sfa":"هوا تاریک است و می‌خواهید به چپ بپیچید. وسیله‌ای با فقط یک چراغ جلو از روبه‌رو می‌آید. چه می‌کنید؟","sen":"It is dark, and you want to turn left. A vehicle with only one headlight is coming towards you. What do you do?","st":[{"da":"Én forlygte betyder altid en motorcykel, så den fylder kun lidt på vejen.","fa":"یک چراغ جلو همیشه یعنی موتورسیکلت، پس جای کمی از جاده را می‌گیرد.","ok":0,"eda":"Nej. Det kan lige så godt være en bil med en defekt forlygte.","efa":"خیر. ممکن است همان‌قدر خودرویی با چراغ خراب باشد.","en":"One headlight always means a motorcycle, so it only takes up a little of the road.","een":"No. It may just as well be a car with a faulty headlight."},{"da":"Jeg svinger hurtigt foran den, fordi den er langt væk.","fa":"سریع جلویش می‌پیچم، چون دور است.","ok":0,"eda":"Nej. Du kan ikke vide, hvor langt væk den er, eller hvor hurtigt den kører.","efa":"خیر. نمی‌توانید بدانید چقدر دور است یا با چه سرعتی می‌آید.","en":"I turn quickly in front of it because it is far away.","een":"No. You cannot know how far away it is or how fast it is going."},{"da":"Det kan være en motorcykel, men også en bil, hvor den ene forlygte ikke virker.","fa":"ممکن است موتورسیکلت باشد، ولی ممکن است خودرویی باشد که یکی از چراغ‌های جلویش کار نمی‌کند.","ok":1,"eda":"Ja. I mørke kan du ikke se køretøjets bredde, kun lygten.","efa":"بله. در تاریکی پهنای وسیله را نمی‌بینید، فقط چراغش را.","en":"It may be a motorcycle, but also a car with one headlight not working.","een":"Yes. In the dark you cannot see the vehicle's width, only the light."},{"da":"Er jeg i tvivl om dens afstand og fart, venter jeg, til den er kørt forbi.","fa":"اگر درباره‌ی فاصله و سرعتش مطمئن نیستم، صبر می‌کنم تا رد شود.","ok":1,"eda":"Ja. Afstand og fart er svære at bedømme ud fra én lygte i mørke.","efa":"بله. تخمین فاصله و سرعت از روی یک چراغ در تاریکی سخت است.","en":"If I am unsure of its distance and speed, I wait until it has passed.","een":"Yes. Distance and speed are hard to judge from one light in the dark."}]},{"id":5362,"img":"newq-art/5362.png","c":"7.14","sda":"Du vil svinge til venstre ind i en indkørsel. Midt på vejen er der en ubrudt linje. Hvad gælder?","sfa":"می‌خواهید به چپ وارد یک ورودیِ خانه شوید. وسط جاده یک خط ممتد هست. چه قاعده‌ای برقرار است؟","sen":"You want to turn left into a driveway. There is an unbroken line in the middle of the road. What applies?","st":[{"da":"Jeg må krydse linjen, hvis jeg giver tegn i god tid.","fa":"اگر به‌موقع راهنما بزنم، می‌توانم از روی خط رد شوم.","ok":0,"eda":"Nej. Blinklyset ændrer ikke ved forbuddet.","efa":"خیر. راهنما این ممنوعیت را تغییر نمی‌دهد.","en":"I may cross the line if I signal in good time.","een":"No. The indicator does not change the ban."},{"da":"Jeg må gerne krydse linjen, når der ikke kommer modkørende.","fa":"وقتی ترافیکی از روبه‌رو نمی‌آید، می‌توانم از روی خط رد شوم.","ok":0,"eda":"Nej. Forbuddet gælder, uanset om der kommer nogen.","efa":"خیر. این ممنوعیت برقرار است، چه کسی بیاید چه نیاید.","en":"I may cross the line when there is no oncoming traffic.","een":"No. The ban applies whether or not anyone is coming."},{"da":"Den ubrudte linje gælder kun for overhaling, ikke for svingning.","fa":"خط ممتد فقط برای سبقت است، نه برای پیچیدن.","ok":0,"eda":"Nej. Spærrelinjen må ikke overskrides, heller ikke for at svinge.","efa":"خیر. از خط ممتد نباید رد شد، حتی برای پیچیدن.","en":"The unbroken line only applies to overtaking, not to turning.","een":"No. The barrier line must not be crossed, not even to turn."},{"da":"Jeg må ikke køre over den ubrudte linje for at svinge ind.","fa":"نباید برای پیچیدن از روی خط ممتد رد شوم.","ok":1,"eda":"Ja. En spærrelinje må ikke overskrides; du må finde en anden vej, fx vende et sted, hvor det er tilladt.","efa":"بله. از خط ممتد نباید رد شد؛ باید راه دیگری پیدا کنید، مثلاً جایی که مجاز است دور بزنید.","en":"I must not cross the unbroken line to turn in.","een":"Yes. A barrier line must not be crossed; you must find another way, for example turn round somewhere it is allowed."}]},{"id":5363,"img":"newq-art/5363.png","c":"7.13","sda":"Du vil svinge til højre. En modkørende bil vil svinge til venstre ind på samme vej. Hvad gælder?","sfa":"می‌خواهید به راست بپیچید. خودرویی از روبه‌رو می‌خواهد به چپ وارد همان خیابان شود. چه قاعده‌ای برقرار است؟","sen":"You want to turn right. An oncoming car wants to turn left into the same road. What applies?","st":[{"da":"Den modkørende skal holde tilbage for mig.","fa":"خودروی روبه‌رو باید به من راه بدهد.","ok":1,"eda":"Ja. Den, der svinger til venstre, skal holde tilbage for modkørende, også for dem, der svinger til højre.","efa":"بله. کسی که به چپ می‌پیچد باید به ترافیک روبه‌رو راه بدهد، از جمله به کسانی که به راست می‌پیچند.","en":"The oncoming car must give way to me.","een":"Yes. Anyone turning left must give way to oncoming traffic, including those turning right."},{"da":"Vi må begge svinge samtidig ind i samme vognbane.","fa":"هر دو می‌توانیم هم‌زمان وارد یک خط شویم.","ok":0,"eda":"Nej. Det kan ikke ske uden fare; den venstresvingende venter.","efa":"خیر. این کار بی‌خطر نیست؛ کسی که به چپ می‌پیچد صبر می‌کند.","en":"We may both turn into the same lane at the same time.","een":"No. That cannot be done safely; the one turning left waits."},{"da":"Jeg holder øje med, om den modkørende faktisk venter, før jeg svinger.","fa":"پیش از پیچیدن نگاه می‌کنم که خودروی روبه‌رو واقعاً منتظر می‌ماند یا نه.","ok":1,"eda":"Ja. Du skal være forberedt på, at andre ikke overholder deres vigepligt.","efa":"بله. باید آماده باشید که دیگران وظیفه‌ی راه دادنشان را رعایت نکنند.","en":"I watch whether the oncoming car actually waits before I turn.","een":"Yes. You must be prepared for others not to keep their duty to give way."},{"da":"Jeg skal holde tilbage, fordi den modkørende kom først til krydset.","fa":"باید راه بدهم، چون خودروی روبه‌رو زودتر به تقاطع رسید.","ok":0,"eda":"Nej. Hvem der kom først, betyder ikke noget; den venstresvingende har vigepligt.","efa":"خیر. این‌که چه کسی اول رسیده مهم نیست؛ کسی که به چپ می‌پیچد باید راه بدهد.","en":"I must give way because the oncoming car reached the junction first.","een":"No. Who came first does not matter; the one turning left must give way."}]},{"id":5364,"img":"newq-art/5364.png","c":"7.13","sda":"Du kører med en lang trailer og skal svinge til højre i et kryds. Hvad skal du være opmærksom på?","sfa":"با یک تریلر بلند می‌رانید و باید در تقاطعی به راست بپیچید. به چه چیزی باید توجه کنید؟","sen":"You are pulling a long trailer and have to turn right at a junction. What must you be aware of?","st":[{"da":"Jeg kører lidt længere frem, før jeg drejer, så traileren ikke rammer kantstenen.","fa":"کمی بیشتر جلو می‌روم و بعد می‌پیچم تا تریلر به جدول نخورد.","ok":1,"eda":"Ja. Et lidt større sving giver plads til trailerens kortere spor.","efa":"بله. پیچیدنِ کمی بازتر برای مسیر تنگ‌ترِ تریلر جا باز می‌کند.","en":"I drive a little further forward before I turn, so that the trailer does not hit the kerb.","een":"Yes. A slightly wider turn leaves room for the trailer's tighter track."},{"da":"Jeg holder øje med cyklister og gående ved hjørnet, som traileren kan ramme.","fa":"مراقب دوچرخه‌سواران و عابران کنار گوشه هستم که ممکن است تریلر به آن‌ها بخورد.","ok":1,"eda":"Ja. Den, der venter ved hjørnet, regner måske ikke med, at traileren kommer så tæt på.","efa":"بله. کسی که کنار گوشه منتظر است شاید انتظار نداشته باشد تریلر آن‌قدر نزدیک بیاید.","en":"I watch out for cyclists and pedestrians at the corner, who could be hit by the trailer.","een":"Yes. Someone waiting at the corner may not expect the trailer to come so close."},{"da":"Traileren følger nøjagtigt bilens spor gennem svinget.","fa":"تریلر دقیقاً رد خودرو را در پیچ دنبال می‌کند.","ok":0,"eda":"Nej. Traileren skærer svinget og kører længere inde end bilen.","efa":"خیر. تریلر پیچ را میان‌بُر می‌زند و از داخل‌تر از خودرو می‌گذرد.","en":"The trailer follows exactly the car's track through the turn.","een":"No. The trailer cuts the turn and runs further inside than the car."},{"da":"Traileren skærer hjørnet og kører tættere på kantstenen end bilen.","fa":"تریلر گوشه را میان‌بُر می‌زند و از خودرو به جدول نزدیک‌تر می‌شود.","ok":1,"eda":"Ja. I et sving følger traileren ikke bilens spor, men kører længere inde i svinget.","efa":"بله. در پیچ، تریلر رد خودرو را دنبال نمی‌کند و از داخلِ پیچ می‌گذرد.","en":"The trailer cuts the corner and runs closer to the kerb than the car.","een":"Yes. In a turn the trailer does not follow the car's track but runs further inside the turn."}]},{"id":5365,"img":"newq-art/5365.png","c":"7.13","sda":"Du holder i en højresvingsbane ved et lyskryds. Til venstre for dig holder en cyklist på linjen mellem din vognbane og vognbanen ligeud. Cyklisten skal ligeud. Hvad gælder?","sfa":"در خط گردش به راستِ یک تقاطع چراغ‌دار ایستاده‌اید. سمت چپ شما دوچرخه‌سواری روی خطِ بین خط شما و خط مستقیم ایستاده و می‌خواهد مستقیم برود. چه قاعده‌ای برقرار است؟","sen":"You are in a right-turn lane at a junction with traffic lights. To your left a cyclist is waiting on the line between your lane and the lane going straight on. The cyclist is going straight on. What applies?","st":[{"da":"Cyklisten skal holde yderst til højre i højresvingsbanen.","fa":"دوچرخه‌سوار باید در منتهی‌الیه سمت راستِ خط گردش به راست بایستد.","ok":0,"eda":"Nej. Reglen giver netop cyklisten lov til at holde ved linjen, så han ikke er i vejen for dem, der svinger til højre.","efa":"خیر. قاعده دقیقاً اجازه می‌دهد دوچرخه‌سوار روی خط بایستد تا سر راه کسانی که به راست می‌پیچند نباشد.","en":"The cyclist must keep to the far right of the right-turn lane.","een":"No. The rule specifically allows the cyclist to wait at the line, so that he is not in the way of those turning right."},{"da":"Cyklisten må gerne placere sig ved linjen mellem vognbanerne.","fa":"دوچرخه‌سوار مجاز است روی خطِ بین دو خط بایستد.","ok":1,"eda":"Ja. Hvor der er afmærket vognbaner til højresving, må en cyklist, der skal ligeud, placere sig ved linjen mellem højresvingsbanen og den nærmeste vognbane.","efa":"بله. جایی که خط ویژه‌ی گردش به راست مشخص شده، دوچرخه‌سواری که مستقیم می‌رود می‌تواند روی خطِ بین خط گردش به راست و خط کناری‌اش بایستد.","en":"The cyclist may position himself at the line between the lanes.","een":"Yes. Where lanes are marked for right turns, a cyclist going straight on may position himself at the line between the right-turn lane and the nearest lane."},{"da":"Når jeg svinger til højre, krydser jeg ikke cyklistens vej, men jeg holder øje med ham.","fa":"وقتی به راست می‌پیچم، از مسیر دوچرخه‌سوار عبور نمی‌کنم، ولی مراقبش هستم.","ok":1,"eda":"Ja. Cyklisten kører ligeud på din venstre side; han kan alligevel slingre eller ændre mening.","efa":"بله. دوچرخه‌سوار در سمت چپ شما مستقیم می‌رود؛ با این حال ممکن است تلوتلو بخورد یا تصمیمش را عوض کند.","en":"When I turn right, I do not cross the cyclist's path, but I keep an eye on him.","een":"Yes. The cyclist goes straight on at your left side; he may still wobble or change his mind."},{"da":"Cyklisten holder ulovligt og skal flytte sig, før jeg kører.","fa":"دوچرخه‌سوار غیرمجاز ایستاده و باید پیش از حرکت من کنار برود.","ok":0,"eda":"Nej. Placeringen er tilladt.","efa":"خیر. این جایگاه مجاز است.","en":"The cyclist is waiting illegally and must move before I go.","een":"No. The position is allowed."}]},{"id":5366,"img":"newq-art/5366.png","c":"7.13","sda":"Det er mørkt, og du vil svinge til højre over en cykelsti. Hvordan forholder du dig?","sfa":"هوا تاریک است و می‌خواهید به راست بپیچید و از روی یک مسیر دوچرخه بگذرید. چه می‌کنید؟","sen":"It is dark, and you want to turn right across a cycle path. What do you do?","st":[{"da":"Jeg sænker farten, så jeg kan nå at standse for en cyklist, jeg først ser sent.","fa":"سرعتم را کم می‌کنم تا برای دوچرخه‌سواری که دیر می‌بینم به‌موقع بایستم.","ok":1,"eda":"Ja. Du skal svinge uden ulempe for cyklister, der kører ligeud på cykelstien.","efa":"بله. باید طوری بپیچید که برای دوچرخه‌سوارانی که در مسیر دوچرخه مستقیم می‌روند مزاحمتی نباشد.","en":"I slow down so that I can stop in time for a cyclist I only see late.","een":"Yes. You must turn without inconvenience to cyclists going straight on along the cycle path."},{"da":"En cyklist uden lys har mistet sin ret, så jeg skal ikke holde tilbage for ham.","fa":"دوچرخه‌سوارِ بدون چراغ حقش را از دست داده، پس لازم نیست به او راه بدهم.","ok":0,"eda":"Nej. Cyklisten bryder reglerne ved at køre uden lys, men du skal stadig holde tilbage for ham.","efa":"خیر. دوچرخه‌سوار با راندن بدون چراغ قانون را زیر پا می‌گذارد، ولی شما همچنان باید به او راه بدهید.","en":"A cyclist without lights has lost his right, so I do not have to give way to him.","een":"No. The cyclist breaks the rules by riding without lights, but you must still give way to him."},{"da":"Jeg kigger ekstra grundigt i spejlet og over højre skulder.","fa":"با دقت بیشتری در آینه و از روی شانه‌ی راستم نگاه می‌کنم.","ok":1,"eda":"Ja. I mørke er cyklister svære at se, og de kan være i den blinde vinkel.","efa":"بله. در تاریکی دوچرخه‌سواران به‌سختی دیده می‌شوند و ممکن است در نقطه‌ی کور باشند.","en":"I look extra carefully in the mirror and over my right shoulder.","een":"Yes. In the dark cyclists are hard to see, and they may be in the blind spot."},{"da":"Der kan komme cyklister uden lys, som er svære at se.","fa":"ممکن است دوچرخه‌سوارانی بدون چراغ بیایند که به‌سختی دیده می‌شوند.","ok":1,"eda":"Ja. Du må regne med, at ikke alle cyklister har lys på.","efa":"بله. باید انتظار داشته باشید همه‌ی دوچرخه‌سواران چراغ روشن نداشته باشند.","en":"Cyclists without lights may come, and they are hard to see.","een":"Yes. You must expect that not all cyclists have their lights on."}]},{"id":5367,"img":"newq-art/5367.png","c":"7.7","sda":"Før en smal strækning, hvor kun én bil kan komme frem ad gangen, står denne tavle. En bil kommer imod dig. Hvad gælder?","sfa":"پیش از یک بخش باریک که هر بار فقط یک خودرو می‌تواند از آن بگذرد، این تابلو هست. خودرویی از روبه‌رو می‌آید. چه قاعده‌ای برقرار است؟","sen":"Before a narrow stretch where only one car can pass at a time stands this sign. A car is coming towards you. What applies?","st":[{"da":"Den modkørende bil skal vente på mig.","fa":"خودروی روبه‌رو باید منتظر من بماند.","ok":0,"eda":"Nej. Det er dig, der har vigepligt; den modkørende har en tavle, der giver den forkørselsret.","efa":"خیر. این شما هستید که باید راه بدهید؛ طرف مقابل تابلویی دارد که به او حق تقدم می‌دهد.","en":"The oncoming car must wait for me.","een":"No. You are the one who must give way; the oncoming traffic has a sign giving it priority."},{"da":"Den, der kommer først til den smalle strækning, må køre først.","fa":"هر کس اول به بخش باریک برسد، اول می‌رود.","ok":0,"eda":"Nej. Tavlen afgør, hvem der skal vente, ikke hvem der kom først.","efa":"خیر. تابلو تعیین می‌کند چه کسی صبر کند، نه این‌که چه کسی اول رسیده.","en":"Whoever reaches the narrow stretch first may go first.","een":"No. The sign decides who must wait, not who arrived first."},{"da":"Jeg skal holde tilbage for den modkørende.","fa":"باید به خودروی روبه‌رو راه بدهم.","ok":1,"eda":"Ja. Tavlen betyder, at du har ubetinget vigepligt over for modkørende på den smalle strækning.","efa":"بله. این تابلو یعنی در بخش باریک باید بی‌قیدوشرط به ترافیک روبه‌رو راه بدهید.","en":"I must give way to the oncoming car.","een":"Yes. The sign means that you must give way to oncoming traffic on the narrow stretch."},{"da":"Tavlen betyder, at kørsel er forbudt.","fa":"این تابلو یعنی رانندگی ممنوع است.","ok":0,"eda":"Nej. Du må køre, når de modkørende er kommet forbi.","efa":"خیر. وقتی ترافیک روبه‌رو رد شد، می‌توانید بروید.","en":"The sign means that driving is forbidden.","een":"No. You may go once the oncoming traffic has passed."}]},{"id":5368,"img":"newq-art/5368.png","c":"7.7","sda":"En fodgænger går i højre vejkant foran dig, og samtidig kommer en bil imod dig. Vejen er smal. Hvordan forholder du dig?","sfa":"عابری جلوی شما در لبه‌ی راست جاده راه می‌رود و هم‌زمان خودرویی از روبه‌رو می‌آید. جاده باریک است. چه می‌کنید؟","sen":"A pedestrian is walking at the right edge of the road in front of you, and at the same time a car is coming towards you. The road is narrow. What do you do?","st":[{"da":"Jeg kører forbi fodgængeren med det samme, så jeg er forbi, før bilen kommer.","fa":"فوراً از کنار عابر می‌گذرم تا پیش از رسیدن آن خودرو رد شده باشم.","ok":0,"eda":"Nej. Så risikerer I at mødes lige ved fodgængeren.","efa":"خیر. این‌طور ممکن است درست کنار عابر به هم برسید.","en":"I drive past the pedestrian at once, so that I am past before the car arrives.","een":"No. Then you risk meeting right next to the pedestrian."},{"da":"Jeg giver fodgængeren god plads, når jeg kører forbi.","fa":"وقتی از کنار عابر می‌گذرم، جای کافی به او می‌دهم.","ok":1,"eda":"Ja. Du skal holde tilstrækkelig afstand til siden.","efa":"بله. باید فاصله‌ی کافی از پهلو داشته باشید.","en":"I give the pedestrian plenty of room when I drive past.","een":"Yes. You must keep enough distance to the side."},{"da":"Fodgængeren kan træde ud på vejen, fx for at gå uden om en vandpyt.","fa":"ممکن است عابر وارد جاده شود، مثلاً برای دور زدن یک چاله‌ی آب.","ok":1,"eda":"Ja. Gående med ryggen til trafikken ser ikke, at du kommer.","efa":"بله. عابری که پشتش به ترافیک است آمدن شما را نمی‌بیند.","en":"The pedestrian may step out into the road, for example to go round a puddle.","een":"Yes. Pedestrians with their backs to the traffic do not see you coming."},{"da":"Jeg sænker farten og venter med at køre forbi fodgængeren, til bilen er passeret.","fa":"سرعتم را کم می‌کنم و تا آن خودرو رد نشده از کنار عابر نمی‌گذرم.","ok":1,"eda":"Ja. Ved møde skal du tage hensyn til dem, der færdes i vejkanten, og der er ikke plads til både fodgængeren og den modkørende.","efa":"بله. هنگام روبه‌رو شدن باید مراقب کسانی باشید که لبه‌ی جاده حرکت می‌کنند، و جای کافی برای عابر و خودروی روبه‌رو با هم نیست.","en":"I slow down and wait to pass the pedestrian until the car has gone by.","een":"Yes. When meeting, you must take care of those at the edge of the road, and there is not room for both the pedestrian and the oncoming car."}]},{"id":5369,"img":"newq-art/5369.png","c":"7.7","sda":"På en smal vej kommer en ambulance med blå blink og sirene imod dig. Hvordan forholder du dig?","sfa":"در یک جاده‌ی باریک آمبولانسی با چراغ گردان آبی و آژیر از روبه‌رو می‌آید. چه می‌کنید؟","sen":"On a narrow road an ambulance with blue lights and siren is coming towards you. What do you do?","st":[{"da":"Jeg fortsætter med samme fart, fordi ambulancen ikke skal forbi mig bagfra.","fa":"با همان سرعت ادامه می‌دهم، چون آمبولانس از پشت سر من نمی‌آید.","ok":0,"eda":"Nej. Pligten til at give fri bane gælder også over for et modkørende udrykningskøretøj.","efa":"خیر. وظیفه‌ی باز کردن راه در برابر خودروی امدادیِ روبه‌رو هم برقرار است.","en":"I carry on at the same speed because the ambulance is not coming past me from behind.","een":"No. The duty to make way also applies to an oncoming emergency vehicle."},{"da":"Jeg standser midt på vejen, så ambulancen kan se mig.","fa":"وسط جاده می‌ایستم تا آمبولانس مرا ببیند.","ok":0,"eda":"Nej. Så spærrer du vejen for ambulancen.","efa":"خیر. این‌طور راه آمبولانس را می‌بندید.","en":"I stop in the middle of the road so that the ambulance can see me.","een":"No. Then you block the road for the ambulance."},{"da":"Jeg holder helt ind til højre og standser om nødvendigt.","fa":"کاملاً به راست کنار می‌کشم و در صورت لزوم می‌ایستم.","ok":1,"eda":"Ja. Du skal i god tid give fri bane for et udrykningskøretøj og om nødvendigt standse.","efa":"بله. باید به‌موقع راه را برای خودروی امدادی باز کنید و در صورت لزوم بایستید.","en":"I pull right over to the right and stop if necessary.","een":"Yes. You must make way for an emergency vehicle in good time and stop if necessary."},{"da":"Jeg vælger et sted at holde ind, hvor ambulancen kan komme uhindret forbi.","fa":"جایی را برای کنار کشیدن انتخاب می‌کنم که آمبولانس بتواند بدون مانع رد شود.","ok":1,"eda":"Ja. På en smal vej skal der være plads nok til, at ambulancen kan passere.","efa":"بله. در جاده‌ی باریک باید جای کافی برای عبور آمبولانس باشد.","en":"I choose a place to pull in where the ambulance can get past unhindered.","een":"Yes. On a narrow road there must be enough room for the ambulance to pass."}]},{"id":5370,"img":"newq-art/5370.png","c":"7.7","sda":"Vejen er smal og har ingen midterlinje. Du nærmer dig en bakketop. Hvordan forholder du dig?","sfa":"جاده باریک است و خط وسط ندارد. به بالای یک تپه نزدیک می‌شوید. چه می‌کنید؟","sen":"The road is narrow and has no centre line. You are approaching a hilltop. What do you do?","st":[{"da":"Jeg holder godt til højre, fordi der kan komme nogen imod mig over bakketoppen.","fa":"کاملاً سمت راست می‌مانم، چون ممکن است کسی از آن طرف تپه به سمتم بیاید.","ok":1,"eda":"Ja. Ved møde skal du holde til højre, og over bakketoppen kan du ikke se de modkørende.","efa":"بله. هنگام روبه‌رو شدن باید سمت راست بمانید و از آن طرف تپه ترافیک روبه‌رو را نمی‌بینید.","en":"I keep well to the right, because someone may come towards me over the hilltop.","een":"Yes. When meeting you must keep right, and you cannot see oncoming traffic over the hilltop."},{"da":"Jeg sænker farten, så jeg kan standse, hvis der kommer en bil midt på vejen.","fa":"سرعتم را کم می‌کنم تا اگر خودرویی وسط جاده آمد، بتوانم بایستم.","ok":1,"eda":"Ja. Foran en bakketop skal farten være passende lav, og du skal kunne standse på den strækning, du kan se.","efa":"بله. پیش از بالای تپه سرعت باید به اندازه‌ی کافی کم باشد و باید بتوانید در مسافتی که می‌بینید بایستید.","en":"I slow down so that I can stop if a car comes in the middle of the road.","een":"Yes. Before a hilltop the speed must be suitably low, and you must be able to stop within the distance you can see."},{"da":"Jeg kører midt på vejen, så jeg bedre kan se over bakketoppen.","fa":"وسط جاده می‌رانم تا آن طرف تپه را بهتر ببینم.","ok":0,"eda":"Nej. Midt på vejen kan du støde ind i en modkørende, som du først ser på toppen.","efa":"خیر. وسط جاده ممکن است با خودرویی از روبه‌رو برخورد کنید که فقط بالای تپه آن را می‌بینید.","en":"I drive in the middle of the road so that I can see better over the hilltop.","een":"No. In the middle of the road you may run into an oncoming car that you only see at the top."}]},{"id":5371,"img":"newq-art/5371.png","c":"7.11","sda":"Du kører forbi denne tavle. Hvad betyder den?","sfa":"از کنار این تابلو می‌گذرید. معنی‌اش چیست؟","sen":"You pass this sign. What does it mean?","st":[{"da":"Tavlen betyder, at jeg har forkørselsret i krydset.","fa":"این تابلو یعنی در تقاطع حق تقدم دارم.","ok":0,"eda":"Nej. Det er lyssignalet, der regulerer trafikken; tavlen giver ingen forkørselsret.","efa":"خیر. چراغ راهنمایی ترافیک را کنترل می‌کند؛ این تابلو حق تقدمی نمی‌دهد.","en":"The sign means that I have priority at the junction.","een":"No. It is the light signal that controls the traffic; the sign gives no priority."},{"da":"Længere fremme er der et sted, hvor trafikken reguleres med lyssignal.","fa":"جلوتر جایی هست که ترافیک با چراغ راهنمایی کنترل می‌شود.","ok":1,"eda":"Ja. Tavlen advarer om lyssignal, fx ved et kryds, du endnu ikke kan se.","efa":"بله. این تابلو درباره‌ی چراغ راهنمایی هشدار می‌دهد، مثلاً در تقاطعی که هنوز دیده نمی‌شود.","en":"Further ahead there is a place where the traffic is controlled by light signals.","een":"Yes. The sign warns of light signals, for example at a junction you cannot see yet."},{"da":"Lyssignalet længere fremme er ude af drift.","fa":"چراغ راهنمایی جلوتر خراب است.","ok":0,"eda":"Nej. Tavlen siger kun, at der kommer et lyssignal.","efa":"خیر. این تابلو فقط می‌گوید جلوتر چراغ راهنمایی هست.","en":"The traffic light further ahead is out of order.","een":"No. The sign only says that a light signal is coming."},{"da":"Tavlen betyder, at der kommer en rundkørsel.","fa":"این تابلو یعنی جلوتر میدان هست.","ok":0,"eda":"Nej. En rundkørsel har sin egen advarselstavle med tre pile i en cirkel.","efa":"خیر. میدان تابلوی هشدار خودش را دارد که سه فلش در یک دایره است.","en":"The sign means that a roundabout is coming.","een":"No. A roundabout has its own warning sign with three arrows in a circle."}]},{"id":5372,"img":"newq-art/5372.png","c":"7.11","sda":"Før krydset kører du forbi denne tavle. Du skal til venstre. Hvad gælder?","sfa":"پیش از تقاطع از کنار این تابلو می‌گذرید. باید به چپ بروید. چه قاعده‌ای برقرار است؟","sen":"Before the junction you pass this sign. You are going left. What applies?","st":[{"da":"Jeg skal i god tid placere mig i den vognbane, som tavlen viser er til venstresving.","fa":"باید به‌موقع در خطی قرار بگیرم که تابلو نشان می‌دهد برای گردش به چپ است.","ok":1,"eda":"Ja. Tavlen viser, hvilke kørselsretninger i krydset de enkelte vognbaner er beregnet til.","efa":"بله. این تابلو نشان می‌دهد هر خط برای کدام جهت در تقاطع است.","en":"I must move in good time into the lane that the sign shows is for turning left.","een":"Yes. The sign shows which directions at the junction each lane is meant for."},{"da":"Tavlen er et påbud om at køre ligeud.","fa":"این تابلو دستور به مستقیم رفتن است.","ok":0,"eda":"Nej. Den er en oplysningstavle om vognbanerne.","efa":"خیر. این یک تابلوی اطلاعاتی درباره‌ی خط‌هاست.","en":"The sign is an order to go straight on.","een":"No. It is an information sign about the lanes."},{"da":"Jeg må blive i midterbanen og skifte over i krydset.","fa":"می‌توانم در خط وسط بمانم و داخل تقاطع خط عوض کنم.","ok":0,"eda":"Nej. Du skal vælge vognbane før krydset; at skifte i krydset kan være farligt for andre.","efa":"خیر. باید پیش از تقاطع خط را انتخاب کنید؛ عوض کردن خط داخل تقاطع برای دیگران خطرناک است.","en":"I may stay in the middle lane and move over in the junction.","een":"No. You must choose your lane before the junction; changing in the junction can be dangerous to others."},{"da":"Tavlen viser, hvor mange vognbaner der er efter krydset.","fa":"این تابلو نشان می‌دهد بعد از تقاطع چند خط هست.","ok":0,"eda":"Nej. Den viser, hvor de enkelte vognbaner fører hen i krydset.","efa":"خیر. نشان می‌دهد هر خط در تقاطع به کجا می‌رود.","en":"The sign shows how many lanes there are after the junction.","een":"No. It shows where each lane leads at the junction."}]},{"id":5373,"img":"newq-art/5373.png","c":"7.11","sda":"Før krydset kører du forbi denne tavle. Hvad betyder den?","sfa":"پیش از تقاطع از کنار این تابلو می‌گذرید. معنی‌اش چیست؟","sen":"Before the junction you pass this sign. What does it mean?","st":[{"da":"Tavlen betyder, at jeg har ubetinget vigepligt i krydset.","fa":"این تابلو یعنی در تقاطع باید بی‌قیدوشرط راه بدهم.","ok":0,"eda":"Nej. Tavlen siger intet om vigepligt; den har sin egen tavle og afmærkning.","efa":"خیر. این تابلو چیزی درباره‌ی حق تقدم نمی‌گوید؛ حق تقدم تابلو و خط‌کشی خودش را دارد.","en":"The sign means that I must give way at the junction.","een":"No. The sign says nothing about giving way; that has its own sign and markings."},{"da":"Tavlen betyder, at krydset er lukket.","fa":"این تابلو یعنی تقاطع بسته است.","ok":0,"eda":"Nej. Det er en advarsel, ikke et forbud.","efa":"خیر. این هشدار است، نه ممنوعیت.","en":"The sign means that the junction is closed.","een":"No. It is a warning, not a ban."},{"da":"Jeg sænker farten og er ekstra opmærksom i krydset.","fa":"سرعتم را کم می‌کنم و در تقاطع بیشتر حواسم را جمع می‌کنم.","ok":1,"eda":"Ja. En advarselstavle betyder, at du skal være særligt agtpågivende.","efa":"بله. تابلوی هشدار یعنی باید احتیاط ویژه کنید.","en":"I slow down and pay extra attention at the junction.","een":"Yes. A warning sign means that you must take particular care."},{"da":"Der sker særligt mange uheld i krydset.","fa":"در این تقاطع تصادف‌های زیادی رخ می‌دهد.","ok":1,"eda":"Ja. Undertavlen angiver, at krydset er særligt belastet af uheld.","efa":"بله. زیرتابلو نشان می‌دهد این تقاطع به‌طور ویژه پرتصادف است.","en":"Particularly many accidents happen at the junction.","een":"Yes. The plate shows that the junction has a particularly high number of accidents."}]},{"id":5374,"img":"newq-art/5374.png","c":"7.4","sda":"Du kører i højre vognbane og passerer denne tavle. Din vognbane ophører længere fremme. Hvad gælder?","sfa":"در خط راست می‌رانید و از کنار این تابلو می‌گذرید. خط شما جلوتر تمام می‌شود. چه قاعده‌ای برقرار است؟","sen":"You are driving in the right lane and pass this sign. Your lane ends further ahead. What applies?","st":[{"da":"Jeg ser i spejlet og over skulderen og giver tegn, før jeg skifter.","fa":"پیش از تغییر خط در آینه و از روی شانه نگاه می‌کنم و راهنما می‌زنم.","ok":1,"eda":"Ja. Du skal give tegn i god tid og sikre dig, at vognbanen ved siden af er fri.","efa":"بله. باید به‌موقع راهنما بزنید و مطمئن شوید خط کناری خالی است.","en":"I look in the mirror and over my shoulder and signal before I change.","een":"Yes. You must signal in good time and make sure that the lane beside you is clear."},{"da":"Det er mig, der skal sikre mig, at vognbaneskiftet kan ske uden fare.","fa":"این من هستم که باید مطمئن شوم تغییر خط بی‌خطر انجام می‌شود.","ok":1,"eda":"Ja. Tavlen viser et vognbaneskift, og den, der skifter vognbane, skal sikre sig, at det kan ske uden fare.","efa":"بله. این تابلو تغییر خط را نشان می‌دهد و کسی که خط عوض می‌کند باید مطمئن شود بی‌خطر است.","en":"It is I who must make sure that the lane change can be made safely.","een":"Yes. The sign shows a lane change, and the one changing lanes must make sure that it can be done safely."},{"da":"Bilerne i venstre vognbane skal lade mig komme ind efter tur, som ved sammenfletning.","fa":"خودروهای خط چپ باید به نوبت اجازه دهند وارد شوم، مثل وقتی دو خط ادغام می‌شوند.","ok":0,"eda":"Nej. Her er det et vognbaneskift, ikke en sammenfletning; du skal finde et sikkert hul.","efa":"خیر. اینجا تغییر خط است، نه ادغام؛ باید یک فاصله‌ی امن پیدا کنید.","en":"The cars in the left lane must let me in in turn, as when two lanes merge.","een":"No. Here it is a lane change, not a merge; you must find a safe gap."},{"da":"Jeg kører helt frem til enden af vognbanen og presser mig ind.","fa":"تا انتهای خط می‌روم و به‌زور وارد می‌شوم.","ok":0,"eda":"Nej. Du skal skifte, når det kan ske uden fare, ikke presse dig ind.","efa":"خیر. باید وقتی بی‌خطر است خط عوض کنید، نه این‌که به‌زور وارد شوید.","en":"I drive right up to the end of the lane and push my way in.","een":"No. You must change when it can be done safely, not force your way in."}]},{"id":5375,"img":"newq-art/5375.png","c":"7.4","sda":"Du vil skifte til venstre vognbane på motorvejen for at overhale. I spejlet ser du en bil langt tilbage i venstre vognbane, men den kommer meget hurtigt. Hvordan forholder du dig?","sfa":"در آزادراه می‌خواهید برای سبقت به خط چپ بروید. در آینه خودرویی را می‌بینید که در خط چپ خیلی عقب است، ولی خیلی سریع می‌آید. چه می‌کنید؟","sen":"You want to change to the left lane on the motorway to overtake. In the mirror you see a car far back in the left lane, but it is coming very fast. What do you do?","st":[{"da":"Jeg vurderer bilens fart, ikke kun hvor langt væk den er.","fa":"سرعت آن خودرو را می‌سنجم، نه فقط فاصله‌اش را.","ok":1,"eda":"Ja. En bil, der kommer hurtigt, er hurtigt fremme, selv om den ser ud til at være langt væk.","efa":"بله. خودرویی که سریع می‌آید زود می‌رسد، حتی اگر دور به نظر برسد.","en":"I judge the car's speed, not only how far away it is.","een":"Yes. A car coming fast arrives quickly, even if it looks far away."},{"da":"Jeg giver tegn i god tid og kigger over skulderen, før jeg skifter.","fa":"به‌موقع راهنما می‌زنم و پیش از تغییر خط از روی شانه نگاه می‌کنم.","ok":1,"eda":"Ja. På motorvejen skal du give tegn før vognbaneskift, og spejlet viser ikke den blinde vinkel.","efa":"بله. در آزادراه باید پیش از تغییر خط راهنما بزنید و آینه نقطه‌ی کور را نشان نمی‌دهد.","en":"I signal in good time and look over my shoulder before I change.","een":"Yes. On the motorway you must signal before changing lanes, and the mirror does not show the blind spot."},{"da":"Jeg venter med at skifte vognbane, til bilen er kørt forbi.","fa":"تا آن خودرو رد نشده، خط عوض نمی‌کنم.","ok":1,"eda":"Ja. Vognbaneskift må kun ske, når det kan ske uden fare eller ulempe for andre.","efa":"بله. تغییر خط فقط وقتی مجاز است که برای دیگران خطر یا مزاحمتی نداشته باشد.","en":"I wait to change lanes until the car has gone past.","een":"Yes. A lane change may only be made when it can be done without danger or inconvenience to others."},{"da":"Bilen er langt væk, så jeg skifter vognbane med det samme og lader den bremse.","fa":"آن خودرو دور است، پس فوراً خط عوض می‌کنم و می‌گذارم ترمز کند.","ok":0,"eda":"Nej. Du må ikke tvinge andre til at bremse, når du skifter vognbane.","efa":"خیر. هنگام تغییر خط نباید دیگران را مجبور به ترمز کنید.","en":"The car is far away, so I change lanes at once and let it brake.","een":"No. You must not force others to brake when you change lanes."}]},{"id":5376,"img":"newq-art/5376.png","c":"7.4","sda":"Du kører i venstre af to vognbaner og skal til højre i et kryds om ca. 300 m. Der er tæt trafik. Hvordan forholder du dig?","sfa":"در خط چپِ یک جاده‌ی دوخطه می‌رانید و باید حدود ۳۰۰ متر جلوتر در تقاطعی به راست بپیچید. ترافیک سنگین است. چه می‌کنید؟","sen":"You are driving in the left of two lanes and have to turn right at a junction in about 300 m. The traffic is dense. What do you do?","st":[{"da":"Jeg bliver i venstre vognbane til lige før krydset og skærer så ind foran bilerne i højre.","fa":"تا درست پیش از تقاطع در خط چپ می‌مانم و بعد جلوی خودروهای خط راست می‌پیچم.","ok":0,"eda":"Nej. Et sent vognbaneskift i tæt trafik er farligt og til ulempe for de andre.","efa":"خیر. تغییر خطِ دیرهنگام در ترافیک سنگین خطرناک است و برای دیگران مزاحمت ایجاد می‌کند.","en":"I stay in the left lane until just before the junction and then cut in in front of the cars on the right.","een":"No. A late lane change in dense traffic is dangerous and a nuisance to the others."},{"da":"Jeg skifter i god tid over i højre vognbane, når det kan ske uden fare.","fa":"به‌موقع، وقتی بی‌خطر باشد، به خط راست می‌روم.","ok":1,"eda":"Ja. Skal du svinge til højre, skal du i god tid før krydset vælge den højre vognbane.","efa":"بله. اگر می‌خواهید به راست بپیچید، باید به‌موقع پیش از تقاطع خط راست را انتخاب کنید.","en":"I move over into the right lane in good time, when it can be done safely.","een":"Yes. If you are turning right, you must choose the right lane in good time before the junction."},{"da":"Jeg må svinge til højre fra venstre vognbane, hvis jeg giver tegn i god tid.","fa":"اگر به‌موقع راهنما بزنم، می‌توانم از خط چپ به راست بپیچم.","ok":0,"eda":"Nej. Så kører du ind foran dem i højre vognbane; højresving sker fra højre vognbane.","efa":"خیر. این‌طور جلوی خودروهای خط راست می‌پیچید؛ گردش به راست از خط راست انجام می‌شود.","en":"I may turn right from the left lane if I signal in good time.","een":"No. Then you cut across those in the right lane; right turns are made from the right lane."}]},{"id":5377,"img":"newq-art/5377.png","c":"7.1","sda":"Du holder ved kantstenen lige bag en parkeret lastbil og vil køre ud. Lastbilen skjuler vejen foran. Hvordan forholder du dig?","sfa":"کنار جدول درست پشت یک کامیونِ پارک‌شده ایستاده‌اید و می‌خواهید حرکت کنید. کامیون جلوی دید جاده را گرفته است. چه می‌کنید؟","sen":"You are parked at the kerb right behind a parked lorry and want to pull out. The lorry hides the road ahead. What do you do?","st":[{"da":"Når jeg blinker, skal trafikken bagfra lade mig komme ud.","fa":"وقتی راهنما بزنم، ترافیکِ پشت سر باید بگذارد بیرون بیایم.","ok":0,"eda":"Nej. Blinklyset giver dig ingen ret; du skal vente, til der er plads.","efa":"خیر. راهنما حقی به شما نمی‌دهد؛ باید صبر کنید تا جا باز شود.","en":"When I signal, the traffic from behind must let me out.","een":"No. The indicator gives you no right; you must wait until there is room."},{"da":"Jeg holder øje med gående, der kan komme frem foran lastbilen.","fa":"مراقب عابرانی هستم که ممکن است از جلوی کامیون بیرون بیایند.","ok":1,"eda":"Ja. Gående, der går over vejen foran lastbilen, kan ikke se dig, og du kan ikke se dem.","efa":"بله. عابرانی که از جلوی کامیون از عرض خیابان رد می‌شوند شما را نمی‌بینند و شما هم آن‌ها را نمی‌بینید.","en":"I watch out for pedestrians who may come out in front of the lorry.","een":"Yes. Pedestrians crossing in front of the lorry cannot see you, and you cannot see them."},{"da":"Jeg ser i spejlet og over venstre skulder og giver tegn, før jeg kører ud.","fa":"پیش از حرکت در آینه و از روی شانه‌ی چپ نگاه می‌کنم و راهنما می‌زنم.","ok":1,"eda":"Ja. Du må kun køre ud fra kanten, når det kan ske uden fare eller ulempe for andre, og du skal give tegn.","efa":"بله. فقط وقتی می‌توانید از کنار جاده حرکت کنید که برای دیگران خطر یا مزاحمتی نداشته باشد، و باید راهنما بزنید.","en":"I look in the mirror and over my left shoulder and signal before I pull out.","een":"Yes. You may only pull out from the edge when it can be done without danger or inconvenience to others, and you must signal."},{"da":"Jeg kører langsomt frem, så jeg kan se forbi lastbilen, før jeg kører helt ud.","fa":"آهسته جلو می‌روم تا پیش از بیرون رفتن کامل، کنار کامیون را ببینم.","ok":1,"eda":"Ja. Lastbilen skjuler både modkørende og gående foran den.","efa":"بله. کامیون هم ترافیک روبه‌رو و هم عابرانِ جلوی خودش را پنهان می‌کند.","en":"I move forward slowly so that I can see past the lorry before I pull right out.","een":"Yes. The lorry hides both oncoming traffic and pedestrians in front of it."}]},{"id":5378,"img":"newq-art/5378.png","c":"7.1","sda":"Det er mørkt. Du holder parkeret ved kantstenen og skal køre ud. Hvordan forholder du dig?","sfa":"هوا تاریک است. کنار جدول پارک کرده‌اید و می‌خواهید حرکت کنید. چه می‌کنید؟","sen":"It is dark. You are parked at the kerb and are about to pull out. What do you do?","st":[{"da":"Det er nok med parkeringslyset, til jeg er kommet ud på vejen.","fa":"تا وقتی وارد جاده نشده‌ام، چراغ پارک کافی است.","ok":0,"eda":"Nej. Så snart du kører, skal nærlyset være tændt, så du kan se og blive set.","efa":"خیر. به محض این‌که حرکت می‌کنید، نور پایین باید روشن باشد تا ببینید و دیده شوید.","en":"The parking lights are enough until I have got out onto the road.","een":"No. As soon as you are driving, the dipped beam must be on, so that you can see and be seen."},{"da":"Jeg holder ekstra godt øje med cyklister, der kan komme bagfra uden lys.","fa":"به‌خصوص مراقب دوچرخه‌سوارانی هستم که ممکن است بدون چراغ از پشت بیایند.","ok":1,"eda":"Ja. I mørke er en cyklist uden lys svær at se i spejlet.","efa":"بله. در تاریکی دوچرخه‌سوارِ بدون چراغ در آینه به‌سختی دیده می‌شود.","en":"I watch extra carefully for cyclists who may come from behind without lights.","een":"Yes. In the dark a cyclist without lights is hard to see in the mirror."},{"da":"Jeg tænder nærlyset, før jeg kører ud.","fa":"پیش از حرکت نور پایین را روشن می‌کنم.","ok":1,"eda":"Ja. I lygtetændingstiden skal du køre med nærlys, eller fjernlys hvor det er tilladt; positionslys alene er ikke nok.","efa":"بله. در زمان روشن کردن چراغ‌ها باید با نور پایین، یا نور بالا در جای مجاز، برانید؛ چراغ کوچک به‌تنهایی کافی نیست.","en":"I switch on the dipped beam before I pull out.","een":"Yes. In lighting-up time you must drive with dipped beam, or high beam where it is allowed; position lights alone are not enough."},{"da":"Jeg blinker med fjernlyset for at vise de andre, at jeg vil køre ud.","fa":"با نور بالا چراغ می‌زنم تا به دیگران نشان دهم می‌خواهم حرکت کنم.","ok":0,"eda":"Nej. Lyssignal må kun bruges for at advare om fare; at du vil køre ud, viser du med blinklyset.","efa":"خیر. علامت نوری فقط برای هشدار خطر است؛ این‌که می‌خواهید حرکت کنید را با راهنما نشان می‌دهید.","en":"I flash my high beam to show the others that I want to pull out.","een":"No. A light signal may only be used to warn of danger; you show that you want to pull out with the indicator."}]},{"id":5379,"img":"newq-art/5379.png","c":"7.1","sda":"Du standser for at lade en passager stige ud. Mellem kørebanen og fortovet er der en cykelsti. Hvordan forholder du dig?","sfa":"می‌ایستید تا مسافری پیاده شود. بین سواره‌رو و پیاده‌رو یک مسیر دوچرخه هست. چه می‌کنید؟","sen":"You stop to let a passenger out. Between the carriageway and the pavement there is a cycle path. What do you do?","st":[{"da":"Passageren skal se sig for efter cyklister, før døren åbnes.","fa":"مسافر باید پیش از باز کردن در، مراقب دوچرخه‌سواران باشد.","ok":1,"eda":"Ja. Døre skal åbnes, så der ikke opstår fare eller unødig ulempe for andre.","efa":"بله. درها باید طوری باز شوند که برای دیگران خطر یا مزاحمتی پیش نیاید.","en":"The passenger must look out for cyclists before the door is opened.","een":"Yes. Doors must be opened so that there is no danger or undue inconvenience to others."},{"da":"Jeg holder et øjeblik inde på cykelstien, så jeg ikke generer trafikken.","fa":"لحظه‌ای روی مسیر دوچرخه می‌ایستم تا مزاحم ترافیک نشوم.","ok":0,"eda":"Nej. Standsning på cykelsti er forbudt, også et øjeblik.","efa":"خیر. توقف روی مسیر دوچرخه ممنوع است، حتی برای یک لحظه.","en":"I stop for a moment on the cycle path so that I do not hold up the traffic.","een":"No. Stopping on a cycle path is forbidden, also for a moment."},{"da":"Jeg standser på kørebanen tæt ved cykelstien, ikke på den.","fa":"روی سواره‌رو و نزدیک مسیر دوچرخه می‌ایستم، نه روی آن.","ok":1,"eda":"Ja. Standsning på cykelsti er forbudt.","efa":"بله. توقف روی مسیر دوچرخه ممنوع است.","en":"I stop on the carriageway close to the cycle path, not on it.","een":"Yes. Stopping on a cycle path is forbidden."},{"da":"Jeg ser selv i højre spejl, før passageren åbner døren.","fa":"پیش از این‌که مسافر در را باز کند، خودم در آینه‌ی راست نگاه می‌کنم.","ok":1,"eda":"Ja. Som fører har du også ansvar for, at afstigningen kan ske uden fare.","efa":"بله. شما به‌عنوان راننده هم مسئولید که پیاده شدن بی‌خطر انجام شود.","en":"I look in the right mirror myself before the passenger opens the door.","een":"Yes. As the driver you are also responsible for the getting out being done safely."}]},{"id":5380,"img":"newq-art/5380.png","c":"7.2","sda":"Sne dækker vejens afmærkning, så du ikke kan se midterlinjen og kantlinjerne. Hvordan placerer du bilen?","sfa":"برف خط‌کشی جاده را پوشانده و خط وسط و خط‌های کناری دیده نمی‌شوند. خودرو را کجای جاده قرار می‌دهید؟","sen":"Snow covers the road markings, so you cannot see the centre line or the edge lines. How do you position the car?","st":[{"da":"Jeg sænker farten, fordi kantsten og rabat kan være skjult under sneen.","fa":"سرعتم را کم می‌کنم، چون ممکن است جدول و شانه‌ی جاده زیر برف پنهان باشند.","ok":1,"eda":"Ja. Farten skal passe til føret og til, hvor godt du kan se vejen.","efa":"بله. سرعت باید با وضعیت سطح جاده و میزان دیدن جاده جور باشد.","en":"I slow down because kerbs and verges may be hidden under the snow.","een":"Yes. The speed must suit the road surface and how well you can see the road."},{"da":"Når afmærkningen ikke kan ses, gælder reglen om at holde til højre ikke.","fa":"وقتی خط‌کشی دیده نمی‌شود، قاعده‌ی سمت راست ماندن برقرار نیست.","ok":0,"eda":"Nej. Du skal altid holde til højre, også uden afmærkning.","efa":"خیر. همیشه باید سمت راست بمانید، حتی بدون خط‌کشی.","en":"When the markings cannot be seen, the rule to keep right does not apply.","een":"No. You must always keep right, also without markings."},{"da":"Jeg kører midt på vejen, fordi jeg ikke kan se midterlinjen.","fa":"وسط جاده می‌رانم، چون خط وسط را نمی‌بینم.","ok":0,"eda":"Nej. Så kan du komme for tæt på de modkørende.","efa":"خیر. این‌طور ممکن است بیش از حد به ترافیک روبه‌رو نزدیک شوید.","en":"I drive in the middle of the road because I cannot see the centre line.","een":"No. Then you may come too close to the oncoming traffic."},{"da":"Jeg holder til højre og vurderer vejens bredde ud fra kanterne og de andre biler.","fa":"سمت راست می‌مانم و پهنای جاده را از روی لبه‌ها و خودروهای دیگر تخمین می‌زنم.","ok":1,"eda":"Ja. Reglen om at holde til højre gælder, selv om afmærkningen ikke kan ses.","efa":"بله. قاعده‌ی سمت راست ماندن برقرار است، حتی وقتی خط‌کشی دیده نمی‌شود.","en":"I keep to the right and judge the width of the road from its edges and the other cars.","een":"Yes. The rule to keep right applies even when the markings cannot be seen."}]},{"id":5381,"img":"newq-art/5381.png","c":"7.2","sda":"Midt på kørebanen ligger en helle med denne blå tavle. Pilen peger skråt ned mod venstre. Hvordan kører du?","sfa":"وسط سواره‌رو جزیره‌ای با این تابلوی آبی هست. فلش به‌صورت مورب رو به پایین و چپ است. چطور رانندگی می‌کنید؟","sen":"In the middle of the carriageway there is a traffic island with this blue sign. The arrow points diagonally down to the left. How do you drive?","st":[{"da":"Jeg kører forbi hellen i venstre side.","fa":"از سمت چپِ جزیره رد می‌شوم.","ok":1,"eda":"Ja. Tavlen påbyder passage i den side, pilen viser.","efa":"بله. این تابلو عبور از سمتی را که فلش نشان می‌دهد الزامی می‌کند.","en":"I pass the island on its left side.","een":"Yes. The sign orders passing on the side the arrow shows."},{"da":"Jeg skal altid holde til højre for en helle.","fa":"همیشه باید از سمت راستِ جزیره رد شوم.","ok":0,"eda":"Nej. Normalt holder du til højre for en helle, men her påbyder tavlen venstre side.","efa":"خیر. معمولاً از سمت راست جزیره رد می‌شوید، ولی اینجا تابلو سمت چپ را الزامی کرده است.","en":"I must always keep to the right of an island.","een":"No. Normally you keep to the right of an island, but here the sign orders the left side."},{"da":"Jeg må selv vælge, hvilken side jeg kører forbi hellen.","fa":"خودم می‌توانم انتخاب کنم از کدام طرف جزیره رد شوم.","ok":0,"eda":"Nej. Tavlen er et påbud, og du skal følge pilen.","efa":"خیر. این تابلو الزامی است و باید از فلش پیروی کنید.","en":"I may choose for myself which side of the island I pass.","een":"No. The sign is an order, and you must follow the arrow."}]},{"id":5382,"img":"newq-art/5382.png","c":"7.2","sda":"Ved et vejarbejde er der malet gule linjer på kørebanen. De gamle hvide linjer kan stadig ses. Hvad gælder?","sfa":"در محل کار جاده‌ای خط‌های زرد روی سواره‌رو کشیده شده و خط‌های سفید قبلی هم هنوز دیده می‌شوند. چه قاعده‌ای برقرار است؟","sen":"At road works yellow lines have been painted on the carriageway. The old white lines can still be seen. What applies?","st":[{"da":"Gule linjer gælder kun for lastbiler.","fa":"خط‌های زرد فقط برای کامیون‌هاست.","ok":0,"eda":"Nej. Afmærkningen gælder for alle kørende.","efa":"خیر. این خط‌کشی برای همه‌ی رانندگان است.","en":"Yellow lines only apply to lorries.","een":"No. The markings apply to all traffic."},{"da":"Jeg følger de hvide linjer, fordi det er dem, der er de faste.","fa":"از خط‌های سفید پیروی می‌کنم، چون آن‌ها دائمی‌اند.","ok":0,"eda":"Nej. Den gule afmærkning går forud for den hvide.","efa":"خیر. خط‌کشی زرد بر خط‌کشی سفید مقدم است.","en":"I follow the white lines because they are the permanent ones.","een":"No. The yellow markings come before the white ones."},{"da":"Jeg følger de gule linjer.","fa":"از خط‌های زرد پیروی می‌کنم.","ok":1,"eda":"Ja. Gul afmærkning angiver midlertidig regulering, fx ved vejarbejde, og skal følges forud for hvid afmærkning.","efa":"بله. خط‌کشی زرد تنظیمات موقت، مثلاً در کار جاده‌ای، را نشان می‌دهد و بر خط‌کشی سفید مقدم است.","en":"I follow the yellow lines.","een":"Yes. Yellow markings show temporary arrangements, for example at road works, and must be followed before white markings."},{"da":"Den gule afmærkning er midlertidig.","fa":"خط‌کشی زرد موقت است.","ok":1,"eda":"Ja. Gule linjer på kørebanen bruges fx ved vejarbejde og omlægning af vejen.","efa":"بله. خط‌های زرد روی سواره‌رو مثلاً در کار جاده‌ای و تغییر مسیر جاده به کار می‌روند.","en":"The yellow markings are temporary.","een":"Yes. Yellow lines on the carriageway are used for example at road works and diversions."}]},{"id":5383,"img":"newq-art/5383.png","c":"7.19","sda":"Det er mørkt, og du vil overhale en bil på landevejen. Der kommer ingen imod dig. Hvilket lys bruger du?","sfa":"هوا تاریک است و می‌خواهید در جاده‌ی بیرون شهر از یک خودرو سبقت بگیرید. کسی از روبه‌رو نمی‌آید. از کدام نور استفاده می‌کنید؟","sen":"It is dark, and you want to overtake a car on a country road. Nothing is coming towards you. Which lights do you use?","st":[{"da":"Jeg slukker kort for lyset, så føreren kan se, at jeg vil forbi.","fa":"چراغ‌ها را لحظه‌ای خاموش می‌کنم تا راننده ببیند می‌خواهم رد شوم.","ok":0,"eda":"Nej. Det er farligt; i mørke skal du altid køre med lys.","efa":"خیر. این کار خطرناک است؛ در تاریکی همیشه باید با چراغ برانید.","en":"I switch my lights off briefly so that the driver can see that I want to pass.","een":"No. That is dangerous; in the dark you must always drive with lights."},{"da":"Når jeg er oppe på siden af bilen, kan jeg skifte til fjernlys.","fa":"وقتی کنار آن خودرو رسیدم، می‌توانم نور بالا را روشن کنم.","ok":1,"eda":"Ja. Så blænder du ikke længere føreren gennem spejlene, og du kan se langt frem.","efa":"بله. در این حالت دیگر راننده را از طریق آینه‌ها خیره نمی‌کنید و می‌توانید تا دوردست را ببینید.","en":"Once I am alongside the car, I can switch to high beam.","een":"Yes. Then you no longer dazzle the driver through the mirrors, and you can see far ahead."},{"da":"Jeg kører med fjernlys hele vejen, fordi der ikke kommer nogen imod mig.","fa":"تمام مدت با نور بالا می‌رانم، چون کسی از روبه‌رو نمی‌آید.","ok":0,"eda":"Nej. Bag bilen blænder fjernlyset føreren gennem spejlene.","efa":"خیر. پشت آن خودرو، نور بالا راننده را از طریق آینه‌ها خیره می‌کند.","en":"I drive with high beam all the way, because nothing is coming towards me.","een":"No. Behind the car, the high beam dazzles its driver through the mirrors."},{"da":"Jeg kører med nærlys, mens jeg er bag bilen, så jeg ikke blænder føreren.","fa":"تا وقتی پشت آن خودرو هستم با نور پایین می‌رانم تا راننده‌اش را خیره نکنم.","ok":1,"eda":"Ja. Fjernlys må ikke bruges, når du kører bag et andet køretøj, så føreren kan blændes.","efa":"بله. وقتی پشت وسیله‌ی دیگری هستید و ممکن است راننده‌اش خیره شود، نباید از نور بالا استفاده کنید.","en":"I drive with dipped beam while I am behind the car, so that I do not dazzle the driver.","een":"Yes. High beam must not be used when you are driving behind another vehicle so that its driver may be dazzled."}]},{"id":5384,"img":"newq-art/5384.png","c":"7.19","sda":"Det er mørkt, og du parkerer din personbil ved kantstenen på en villavej i byen uden gadelys. Hvad gælder om lyset?","sfa":"هوا تاریک است و خودروی سواری‌تان را کنار جدولِ یک خیابان مسکونی در شهر که چراغ خیابان ندارد پارک می‌کنید. درباره‌ی چراغ‌ها چه قاعده‌ای برقرار است؟","sen":"It is dark, and you park your car at the kerb in a residential street in town without street lights. What applies to the lights?","st":[{"da":"Det er nok, at positionslyset og baglygten i den side, der vender mod vejens midte, er tændt.","fa":"کافی است چراغ کوچک و چراغ عقبِ سمتی که رو به وسط جاده است روشن باشند.","ok":1,"eda":"Ja. I tættere bebygget område er det nok for en bil på højst 6 m i længden og 2 m i bredden, der holder langs vejkanten.","efa":"بله. در محدوده‌ی شهری این برای خودرویی با حداکثر ۶ متر طول و ۲ متر عرض که کنار جاده ایستاده کافی است.","en":"It is enough for the position light and the rear light on the side facing the middle of the road to be on.","een":"Yes. In a built-up area that is enough for a car at most 6 m long and 2 m wide standing along the edge of the road."},{"da":"Har bilen en trailer koblet på, gælder lempelsen ikke.","fa":"اگر تریلری به خودرو وصل باشد، این تسهیل برقرار نیست.","ok":1,"eda":"Ja. Undtagelsen gælder ikke, når bilen trækker et andet køretøj.","efa":"بله. این استثنا وقتی خودرو وسیله‌ی دیگری را می‌کشد برقرار نیست.","en":"If the car has a trailer hitched to it, the relaxation does not apply.","een":"Yes. The exception does not apply when the car is towing another vehicle."},{"da":"Havariblinket skal være tændt hele natten.","fa":"چراغ خطر باید تمام شب روشن باشد.","ok":0,"eda":"Nej. Ved almindelig parkering bruges parkeringslys, ikke havariblink.","efa":"خیر. برای پارک معمولی از چراغ پارک استفاده می‌شود، نه چراغ خطر.","en":"The hazard lights must be on all night.","een":"No. For ordinary parking, parking lights are used, not hazard lights."},{"da":"Nærlyset må ikke være tændt, mens bilen holder parkeret.","fa":"تا وقتی خودرو پارک است، نور پایین نباید روشن باشد.","ok":1,"eda":"Ja. Andre lygter end de påbudte må ikke være tændt, når bilen holder parkeret.","efa":"بله. وقتی خودرو پارک است، چراغ‌هایی غیر از چراغ‌های الزامی نباید روشن باشند.","en":"The dipped beam must not be on while the car is parked.","een":"Yes. Lights other than the required ones must not be on while the car is parked."}]},{"id":5385,"img":"newq-art/5385.png","c":"7.19","sda":"Det er mørkt, og du kører med fjernlys ind i tæt tåge. Hvordan forholder du dig?","sfa":"هوا تاریک است و با نور بالا وارد مه غلیظ می‌شوید. چه می‌کنید؟","sen":"It is dark, and you drive with high beam into thick fog. What do you do?","st":[{"da":"Jeg beholder fjernlyset, fordi det lyser længst frem.","fa":"نور بالا را نگه می‌دارم، چون دورتر را روشن می‌کند.","ok":0,"eda":"Nej. I tåge oplyser fjernlyset tågen i stedet for vejen.","efa":"خیر. در مه، نور بالا به‌جای جاده خودِ مه را روشن می‌کند.","en":"I keep the high beam, because it lights furthest ahead.","een":"No. In fog the high beam lights up the fog instead of the road."},{"da":"Jeg skifter til nærlys, fordi fjernlyset kastes tilbage af tågen og blænder mig.","fa":"نور پایین را روشن می‌کنم، چون مه نور بالا را برمی‌گرداند و چشمم را می‌زند.","ok":1,"eda":"Ja. I tåge giver fjernlyset en hvid væg af lys, så du ser mindre.","efa":"بله. در مه، نور بالا دیواری سفید از نور می‌سازد و کمتر می‌بینید.","en":"I switch to dipped beam, because the fog throws the high beam back and dazzles me.","een":"Yes. In fog the high beam makes a white wall of light, so you see less."},{"da":"Jeg lægger mig tæt bag bilen foran og følger dens baglygter.","fa":"نزدیک پشت خودروی جلویی می‌روم و چراغ‌های عقبش را دنبال می‌کنم.","ok":0,"eda":"Nej. Du skal holde så stor afstand, at du kan standse, hvis den bremser.","efa":"خیر. باید آن‌قدر فاصله بگیرید که اگر ترمز کرد، بتوانید بایستید.","en":"I move up close behind the car in front and follow its rear lights.","een":"No. You must keep such a distance that you can stop if it brakes."},{"da":"Jeg sænker farten, så jeg kan standse på den strækning, jeg kan se.","fa":"سرعتم را کم می‌کنم تا بتوانم در مسافتی که می‌بینم بایستم.","ok":1,"eda":"Ja. Du skal kunne standse på den del af vejen, du har udsyn over.","efa":"بله. باید بتوانید در بخشی از جاده که می‌بینید بایستید.","en":"I slow down so that I can stop within the distance I can see.","een":"Yes. You must be able to stop on the part of the road you can see."}]},{"id":5386,"img":"newq-art/5386.png","c":"7.16","sda":"Du kører forbi denne tavle. Hvad gælder herefter?","sfa":"از کنار این تابلو می‌گذرید. از اینجا به بعد چه قاعده‌ای برقرار است؟","sen":"You pass this sign. What applies from here on?","st":[{"da":"Der kan komme cyklister, knallerter og traktorer på vejen.","fa":"ممکن است دوچرخه‌سوار، موتور گازی و تراکتور در جاده باشند.","ok":1,"eda":"Ja. De må ikke køre på motorvej, men de må godt køre på almindelige veje.","efa":"بله. آن‌ها اجازه‌ی رانندگی در آزادراه را ندارند، ولی در جاده‌های معمولی می‌توانند.","en":"Cyclists, mopeds and tractors may appear on the road.","een":"Yes. They may not use the motorway, but they may use ordinary roads."},{"da":"Jeg må fortsætte med 130 km/t, til jeg kører forbi en ny hastighedstavle.","fa":"تا وقتی از کنار تابلوی سرعت جدیدی نگذشته‌ام، می‌توانم با ۱۳۰ ادامه دهم.","ok":0,"eda":"Nej. Når motorvejen ophører, gælder den generelle grænse for den vej, du nu kører på.","efa":"خیر. وقتی آزادراه تمام می‌شود، حد عمومیِ جاده‌ای که اکنون در آن هستید برقرار است.","en":"I may carry on at 130 km/h until I pass a new speed sign.","een":"No. When the motorway ends, the general limit for the road you are now on applies."},{"da":"Motorvejen ophører, og de særlige regler for motorvej gælder ikke længere.","fa":"آزادراه تمام می‌شود و قواعد ویژه‌ی آزادراه دیگر برقرار نیستند.","ok":1,"eda":"Ja. Tavlen viser, at motorvejsstrækningen slutter.","efa":"بله. این تابلو پایان مسیر آزادراه را نشان می‌دهد.","en":"The motorway ends, and the special motorway rules no longer apply.","een":"Yes. The sign shows that the motorway stretch ends."},{"da":"Uden andre tavler gælder den generelle grænse på 80 km/t uden for byen.","fa":"بدون تابلوهای دیگر، حد عمومی ۸۰ کیلومتر بر ساعتِ بیرون شهر برقرار است.","ok":1,"eda":"Ja. Grænsen på 130 km/t gælder kun på motorvej.","efa":"بله. حد ۱۳۰ کیلومتر بر ساعت فقط در آزادراه برقرار است.","en":"Without other signs the general limit of 80 km/h outside town applies.","een":"Yes. The 130 km/h limit only applies on the motorway."}]},{"id":5387,"img":"newq-art/5387.png","c":"7.16","sda":"Over motorvejen viser elektroniske tavler 90 km/t i en rød ring. Der er ingen kø at se. Hvad gælder?","sfa":"بالای آزادراه تابلوهای الکترونیکی عدد ۹۰ را داخل حلقه‌ی قرمز نشان می‌دهند. صفی دیده نمی‌شود. چه قاعده‌ای برقرار است؟","sen":"Above the motorway electronic signs show 90 km/h in a red ring. No queue can be seen. What applies?","st":[{"da":"Det er en hastighedsgrænse, som jeg skal overholde.","fa":"این حد سرعتی است که باید رعایتش کنم.","ok":1,"eda":"Ja. Elektroniske tavler med en hastighedsgrænse har samme betydning som faste tavler.","efa":"بله. تابلوهای الکترونیکیِ حد سرعت همان معنای تابلوهای ثابت را دارند.","en":"It is a speed limit that I must keep to.","een":"Yes. Electronic signs showing a speed limit have the same meaning as fixed signs."},{"da":"Grænsen gælder kun, når jeg selv kan se en kø.","fa":"این حد فقط وقتی برقرار است که خودم صفی ببینم.","ok":0,"eda":"Nej. Grænsen kan være sat ned af en grund, du endnu ikke kan se, fx kø eller et uheld længere fremme.","efa":"خیر. ممکن است حد سرعت به دلیلی کم شده باشد که هنوز نمی‌بینید، مثلاً صف یا تصادف جلوتر.","en":"The limit only applies when I can see a queue myself.","een":"No. The limit may have been lowered for a reason you cannot see yet, for example a queue or an accident further ahead."},{"da":"Grænsen gælder kun for lastbiler.","fa":"این حد فقط برای کامیون‌هاست.","ok":0,"eda":"Nej. Uden undertavle gælder den for alle.","efa":"خیر. بدون زیرتابلو برای همه برقرار است.","en":"The limit only applies to lorries.","een":"No. Without a plate under it, it applies to everyone."},{"da":"Elektroniske tavler er kun anbefalinger.","fa":"تابلوهای الکترونیکی فقط توصیه‌اند.","ok":0,"eda":"Nej. En rød ring med et tal er en hastighedsgrænse, også på en elektronisk tavle.","efa":"خیر. حلقه‌ی قرمز با عدد یعنی حد سرعت، حتی روی تابلوی الکترونیکی.","en":"Electronic signs are only recommendations.","een":"No. A red ring with a number is a speed limit, also on an electronic sign."}]},{"id":5388,"img":"newq-art/5388.png","c":"6.2","sda":"Som trafikant kan du som regel regne med, at andre overholder færdselsreglerne. Hvornår skal du være særligt varsom med at regne med det?","sfa":"به‌عنوان کاربر راه معمولاً می‌توانید روی این حساب کنید که دیگران قوانین رانندگی را رعایت می‌کنند. چه وقت باید در این حساب کردن به‌ویژه محتاط باشید؟","sen":"As a road user you can usually count on others keeping the traffic rules. When must you be particularly careful about counting on that?","st":[{"da":"Når der er børn på eller ved vejen.","fa":"وقتی کودکان روی جاده یا کنار آن هستند.","ok":1,"eda":"Ja. Børn kan ikke overskue trafikken, og der skal vises særligt hensyn over for dem.","efa":"بله. کودکان نمی‌توانند ترافیک را درست درک کنند و باید ملاحظه‌ی ویژه‌ای نسبت به آن‌ها داشت.","en":"When there are children on or beside the road.","een":"Yes. Children cannot take in the traffic, and particular consideration must be shown to them."},{"da":"Kun når jeg kører på motorvej.","fa":"فقط وقتی در آزادراه رانندگی می‌کنم.","ok":0,"eda":"Nej. Det gælder overalt, og især hvor der færdes børn, ældre og andre sårbare trafikanter.","efa":"خیر. این همه‌جا برقرار است، به‌ویژه جایی که کودکان، سالمندان و دیگر کاربران آسیب‌پذیر راه حضور دارند.","en":"Only when I am driving on the motorway.","een":"No. It applies everywhere, especially where children, elderly people and other vulnerable road users are about."},{"da":"Aldrig; jeg må altid regne med, at alle overholder reglerne.","fa":"هیچ‌وقت؛ همیشه می‌توانم روی این حساب کنم که همه قوانین را رعایت می‌کنند.","ok":0,"eda":"Nej. Du skal tage højde for, at andre kan begå fejl, især børn og ældre.","efa":"خیر. باید در نظر بگیرید که دیگران، به‌ویژه کودکان و سالمندان، ممکن است اشتباه کنند.","en":"Never; I may always count on everyone keeping the rules.","een":"No. You must allow for others making mistakes, especially children and the elderly."},{"da":"Når en ældre person ser ud til ikke at have set mig.","fa":"وقتی به نظر می‌رسد فردی سالمند مرا ندیده است.","ok":1,"eda":"Ja. Der skal vises særligt hensyn over for ældre og over for personer, der ser eller hører dårligt.","efa":"بله. باید نسبت به سالمندان و کسانی که بینایی یا شنوایی ضعیفی دارند ملاحظه‌ی ویژه داشت.","en":"When an elderly person seems not to have seen me.","een":"Yes. Particular consideration must be shown to elderly people and to people who see or hear poorly."}]},{"id":5389,"img":"newq-art/5389.png","c":"6.2","sda":"Du har været involveret i et færdselsuheld, hvor en person er kommet til skade. Hvad skal du gøre?","sfa":"در یک تصادف رانندگی دخیل بوده‌اید که در آن کسی آسیب دیده است. چه باید بکنید؟","sen":"You have been involved in a traffic accident in which a person has been injured. What must you do?","st":[{"da":"Jeg standser straks.","fa":"فوراً می‌ایستم.","ok":1,"eda":"Ja. Den, der er involveret i et færdselsuheld, skal straks standse, uanset hvem der har skylden.","efa":"بله. هر کس در تصادف رانندگی دخیل است، صرف‌نظر از مقصر بودن، باید فوراً بایستد.","en":"I stop at once.","een":"Yes. Anyone involved in a traffic accident must stop at once, whoever is to blame."},{"da":"Jeg hjælper den tilskadekomne, så godt jeg kan, og ringer 1-1-2, hvis der er brug for det.","fa":"تا جایی که می‌توانم به فرد آسیب‌دیده کمک می‌کنم و در صورت نیاز با ۱۱۲ تماس می‌گیرم.","ok":1,"eda":"Ja. Du skal i muligt omfang hjælpe personer, der er kommet til skade.","efa":"بله. باید تا حد امکان به افرادی که آسیب دیده‌اند کمک کنید.","en":"I help the injured person as well as I can and call 1-1-2 if it is needed.","een":"Yes. You must help people who have been injured as far as you can."},{"da":"Jeg er med til at sikre uheldsstedet, så der ikke sker flere uheld.","fa":"در ایمن کردن محل تصادف کمک می‌کنم تا تصادف دیگری رخ ندهد.","ok":1,"eda":"Ja. Du skal deltage i de foranstaltninger til færdslens sikring, som uheldet kræver.","efa":"بله. باید در اقداماتی که تصادف برای ایمن کردن ترافیک لازم دارد شرکت کنید.","en":"I help to secure the accident site so that no further accidents happen.","een":"Yes. You must take part in the measures to make the traffic safe that the accident requires."},{"da":"Jeg oplyser mit navn og min adresse, hvis en anden part beder om det.","fa":"اگر طرف دیگرِ تصادف بخواهد، نام و نشانی‌ام را به او می‌دهم.","ok":1,"eda":"Ja. Du skal opgive navn og adresse til andre, der er involveret i uheldet, hvis de beder om det.","efa":"بله. اگر دیگرانِ دخیل در تصادف بخواهند، باید نام و نشانی‌تان را بدهید.","en":"I give my name and address if another party asks for it.","een":"Yes. You must give your name and address to others involved in the accident if they ask for it."}]},{"id":5390,"img":"newq-art/5390.png","c":"7.15","sda":"Rundt om rundkørslen er der en cykelsti for sig, som krydser udkørslerne. Der er ingen hajtænder eller anden afmærkning på cykelstien. Du vil køre ud af rundkørslen. Hvad gælder?","sfa":"دور میدان یک مسیر دوچرخه‌ی جداگانه هست که از روی خروجی‌ها می‌گذرد. روی مسیر دوچرخه دندان‌کوسه یا خط‌کشی دیگری نیست. می‌خواهید از میدان خارج شوید. چه قاعده‌ای برقرار است؟","sen":"Round the roundabout there is a separate cycle path that crosses the exits. There are no shark teeth or other markings on the cycle path. You want to leave the roundabout. What applies?","st":[{"da":"Cyklisterne skal holde tilbage, fordi jeg kommer ud fra rundkørslen.","fa":"دوچرخه‌سواران باید راه بدهند، چون من از میدان بیرون می‌آیم.","ok":0,"eda":"Nej. Uden afmærkning har du vigepligt over for cyklister, der kører ligeud på cykelstien.","efa":"خیر. بدون خط‌کشی، شما باید به دوچرخه‌سوارانی که در مسیر دوچرخه مستقیم می‌روند راه بدهید.","en":"The cyclists must give way because I am coming out of the roundabout.","een":"No. Without markings you must give way to cyclists going straight on along the cycle path."},{"da":"Når jeg blinker, kan jeg regne med, at cyklisten har set mig.","fa":"وقتی راهنما می‌زنم، می‌توانم مطمئن باشم دوچرخه‌سوار مرا دیده است.","ok":0,"eda":"Nej. Cyklisten kan have overset dig; du skal selv sikre dig, at du kan svinge uden fare.","efa":"خیر. ممکن است دوچرخه‌سوار شما را ندیده باشد؛ خودتان باید مطمئن شوید بی‌خطر می‌پیچید.","en":"When I signal, I can count on the cyclist having seen me.","een":"No. The cyclist may have overlooked you; you must make sure yourself that you can turn safely."},{"da":"Jeg holder tilbage for cyklisten på cykelstien, der skal videre rundt.","fa":"به دوچرخه‌سوارِ مسیر دوچرخه که دور میدان ادامه می‌دهد راه می‌دهم.","ok":1,"eda":"Ja. Når du svinger til højre over en cykelsti, må du ikke være til ulempe for cyklister, der kører ligeud ad den.","efa":"بله. وقتی به راست می‌پیچید و از روی مسیر دوچرخه می‌گذرید، نباید برای دوچرخه‌سوارانی که مستقیم در آن می‌روند مزاحمت ایجاد کنید.","en":"I give way to the cyclist on the cycle path who is going on round.","een":"Yes. When you turn right across a cycle path, you must not inconvenience cyclists going straight on along it."},{"da":"Jeg giver tegn til højre, inden jeg forlader rundkørslen.","fa":"پیش از ترک میدان راهنمای راست می‌زنم.","ok":1,"eda":"Ja. Du skal give tegn, før du svinger ud af rundkørslen.","efa":"بله. پیش از خروج از میدان باید راهنما بزنید.","en":"I signal right before I leave the roundabout.","een":"Yes. You must signal before you turn out of the roundabout."}]},{"id":5391,"img":"newq-art/5391.png","c":"7.15","sda":"Du venter ved hajtænderne ved indkørslen til rundkørslen. En bil kommer i rundkørslen fra venstre og blinker til højre. Hvordan forholder du dig?","sfa":"پشت دندان‌کوسه‌های ورودی میدان منتظرید. خودرویی در میدان از چپ می‌آید و راهنمای راست زده است. چه می‌کنید؟","sen":"You are waiting at the shark teeth at the entry to the roundabout. A car is coming round from the left with its right indicator flashing. What do you do?","st":[{"da":"Blinklyset betyder, at bilen giver mig lov til at køre ind.","fa":"راهنما یعنی آن خودرو به من اجازه‌ی ورود می‌دهد.","ok":0,"eda":"Nej. Blinklyset viser kun, hvad føreren vil; du har stadig vigepligt.","efa":"خیر. راهنما فقط نشان می‌دهد راننده چه می‌خواهد؛ شما همچنان باید راه بدهید.","en":"The indicator means that the car is letting me drive in.","een":"No. The indicator only shows what the driver intends; you still have to give way."},{"da":"Jeg kører ind med det samme, fordi bilen skal ud før min indkørsel.","fa":"فوراً وارد می‌شوم، چون آن خودرو پیش از ورودی من خارج می‌شود.","ok":0,"eda":"Nej. Det ved du først, når den faktisk svinger ud.","efa":"خیر. این را فقط وقتی می‌دانید که واقعاً خارج شود.","en":"I drive in at once, because the car is leaving before my entry.","een":"No. You only know that once it actually turns out."},{"da":"Jeg venter, til jeg er sikker på, at bilen kører ud af rundkørslen.","fa":"صبر می‌کنم تا مطمئن شوم آن خودرو از میدان خارج می‌شود.","ok":1,"eda":"Ja. Bilen kan blinke for tidligt eller have glemt at slå blinklyset fra.","efa":"بله. ممکن است آن خودرو زودتر از موقع راهنما زده یا فراموش کرده باشد راهنما را خاموش کند.","en":"I wait until I am sure that the car is leaving the roundabout.","een":"Yes. The car may be signalling too early or have forgotten to switch the indicator off."}]},{"id":5392,"img":"newq-art/5392.png","c":"7.5","sda":"Du skal bakke ind i en indkørsel med en trailer. Hvordan forholder du dig?","sfa":"باید با تریلر دنده‌عقب وارد یک ورودیِ خانه شوید. چه می‌کنید؟","sen":"You have to reverse into a driveway with a trailer. What do you do?","st":[{"da":"Traileren svinger samme vej, som jeg drejer rattet.","fa":"تریلر به همان سمتی می‌چرخد که فرمان را می‌چرخانم.","ok":0,"eda":"Nej. Når du bakker, svinger traileren den modsatte vej af den, du drejer rattet.","efa":"خیر. هنگام دنده‌عقب، تریلر برخلاف جهتی که فرمان را می‌چرخانید می‌چرخد.","en":"The trailer swings the same way as I turn the steering wheel.","een":"No. When you reverse, the trailer swings the opposite way to the way you turn the wheel."},{"da":"Jeg bakker i meget lav fart, så jeg kan standse med det samme.","fa":"با سرعت خیلی کم دنده‌عقب می‌روم تا بتوانم فوراً بایستم.","ok":1,"eda":"Ja. Baglænskørsel må kun ske, når det kan ske uden fare eller ulempe for andre.","efa":"بله. دنده‌عقب فقط وقتی مجاز است که برای دیگران خطر یا مزاحمتی نداشته باشد.","en":"I reverse at a very low speed so that I can stop at once.","een":"Yes. Reversing may only be done when it can be done without danger or inconvenience to others."},{"da":"Jeg sikrer mig, at der ikke er gående eller cyklister på fortovet bag traileren.","fa":"مطمئن می‌شوم پشت تریلر روی پیاده‌رو عابر یا دوچرخه‌سواری نیست.","ok":1,"eda":"Ja. Du krydser fortovet, og gående kan være skjult bag traileren.","efa":"بله. از روی پیاده‌رو می‌گذرید و ممکن است عابران پشت تریلر پنهان باشند.","en":"I make sure that there are no pedestrians or cyclists on the pavement behind the trailer.","een":"Yes. You cross the pavement, and pedestrians may be hidden behind the trailer."},{"da":"Jeg får en person til at hjælpe mig, hvis jeg ikke kan se, hvad der er bag traileren.","fa":"اگر نتوانم پشت تریلر را ببینم، از کسی کمک می‌گیرم.","ok":1,"eda":"Ja. Traileren skjuler meget af udsynet bagud.","efa":"بله. تریلر بخش زیادی از دید عقب را می‌پوشاند.","en":"I get someone to help me if I cannot see what is behind the trailer.","een":"Yes. The trailer hides much of the view to the rear."}]},{"id":5393,"img":"newq-art/5393.png","c":"7.5","sda":"Du har kørt forbi den indkørsel, du skulle ind ad, på en befærdet vej. Hvad gør du?","sfa":"در یک جاده‌ی شلوغ از ورودی‌ای که باید واردش می‌شدید رد شده‌اید. چه می‌کنید؟","sen":"On a busy road you have driven past the driveway you wanted to turn into. What do you do?","st":[{"da":"Jeg bakker tilbage langs vejkanten med havariblinket tændt.","fa":"با چراغ خطرِ روشن، کنار جاده دنده‌عقب برمی‌گردم.","ok":0,"eda":"Nej. Baglænskørsel på en befærdet vej er farlig, og havariblinket gør den ikke sikker.","efa":"خیر. دنده‌عقب در جاده‌ی شلوغ خطرناک است و چراغ خطر آن را ایمن نمی‌کند.","en":"I reverse back along the edge of the road with the hazard lights on.","een":"No. Reversing on a busy road is dangerous, and the hazard lights do not make it safe."},{"da":"Bakning er tilladt, når jeg viser det med blinklyset.","fa":"اگر با راهنما نشانش دهم، دنده‌عقب مجاز است.","ok":0,"eda":"Nej. Der er ingen pligt til at give tegn, når du bakker, og et blinklys gør ikke bakningen tilladt; den må kun ske, når det kan ske uden fare.","efa":"خیر. هنگام دنده‌عقب الزامی به راهنما زدن نیست و راهنما هم دنده‌عقب را مجاز نمی‌کند؛ فقط وقتی مجاز است که بی‌خطر باشد.","en":"Reversing is allowed when I show it with the indicator.","een":"No. There is no duty to signal when reversing, and an indicator does not make reversing allowed; it may only be done when it can be done safely."},{"da":"Jeg kører videre og vender et sted, hvor det kan ske uden fare.","fa":"ادامه می‌دهم و جایی دور می‌زنم که بی‌خطر باشد.","ok":1,"eda":"Ja. Baglænskørsel og vending må kun ske, hvor det kan ske uden fare eller ulempe for andre.","efa":"بله. دنده‌عقب و دور زدن فقط جایی مجاز است که برای دیگران خطر یا مزاحمتی نداشته باشد.","en":"I drive on and turn round at a place where it can be done safely.","een":"Yes. Reversing and turning round may only be done where it can be done without danger or inconvenience to others."},{"da":"Jeg bakker hurtigt, så jeg ikke er længe i vejen.","fa":"سریع دنده‌عقب می‌روم تا مدت زیادی سر راه نباشم.","ok":0,"eda":"Nej. Hurtig baglænskørsel giver dig endnu mindre kontrol og tid til at reagere.","efa":"خیر. دنده‌عقبِ سریع کنترل و فرصت واکنش شما را باز هم کمتر می‌کند.","en":"I reverse quickly so that I am not in the way for long.","een":"No. Fast reversing gives you even less control and time to react."}]},{"id":5394,"img":"newq-art/5394.png","c":"5.2","sda":"Det har været tørt i flere uger. Nu begynder det at regne. Hvad skal du være opmærksom på?","sfa":"چند هفته هوا خشک بوده و حالا باران شروع شده است. به چه چیزی باید توجه کنید؟","sen":"It has been dry for several weeks. Now it starts to rain. What must you be aware of?","st":[{"da":"Regnen har ingen betydning for bremselængden.","fa":"باران تأثیری روی مسافت ترمز ندارد.","ok":0,"eda":"Nej. På våd vej bliver bremselængden længere.","efa":"خیر. در جاده‌ی خیس مسافت ترمز بیشتر می‌شود.","en":"The rain makes no difference to the braking distance.","een":"No. On a wet road the braking distance becomes longer."},{"da":"Vejen kan være særligt glat i starten, fordi støv, gummi og olie blandes med vandet.","fa":"ممکن است جاده در ابتدا به‌ویژه لغزنده باشد، چون گرد و خاک، ذرات لاستیک و روغن با آب مخلوط می‌شوند.","ok":1,"eda":"Ja. Den første regn efter en tør periode giver en glat hinde på asfalten.","efa":"بله. اولین باران پس از یک دوره‌ی خشک لایه‌ای لغزنده روی آسفالت می‌سازد.","en":"The road may be particularly slippery at first, because dust, rubber and oil mix with the water.","een":"Yes. The first rain after a dry spell leaves a slippery film on the asphalt."},{"da":"Vejen kan kun blive glat, når det fryser.","fa":"جاده فقط وقتی یخ ببندد لغزنده می‌شود.","ok":0,"eda":"Nej. Også regn kan gøre vejen glat, især lige efter en tør periode.","efa":"خیر. باران هم می‌تواند جاده را لغزنده کند، به‌ویژه درست پس از یک دوره‌ی خشک.","en":"The road can only become slippery when it freezes.","een":"No. Rain can also make the road slippery, especially just after a dry spell."},{"da":"Vejen er mindre glat end normalt, fordi den har været tør længe.","fa":"جاده کمتر از معمول لغزنده است، چون مدت زیادی خشک بوده.","ok":0,"eda":"Nej. Det er omvendt: snavset på vejen gør den ekstra glat.","efa":"خیر. برعکس است: آلودگی روی جاده آن را لغزنده‌تر می‌کند.","en":"The road is less slippery than usual because it has been dry for a long time.","een":"No. It is the other way round: the dirt on the road makes it extra slippery."}]},{"id":5395,"img":"newq-art/5395.png","c":"7.8","sda":"Du kører 80 km/t bag en anden bil på landevejen. Hvad gælder?","sfa":"در جاده‌ی بیرون شهر با سرعت ۸۰ کیلومتر بر ساعت پشت خودروی دیگری می‌رانید. چه قاعده‌ای برقرار است؟","sen":"You are driving at 80 km/h behind another car on a country road. What applies?","st":[{"da":"Bremser bilen foran, kører jeg omkring 22 m, før jeg når at reagere, hvis min reaktionstid er 1 sekund.","fa":"اگر خودروی جلو ترمز کند و زمان واکنش من ۱ ثانیه باشد، پیش از واکنش حدود ۲۲ متر جلو می‌روم.","ok":1,"eda":"Ja. I reaktionstiden kører bilen videre med uændret fart.","efa":"بله. در زمان واکنش، خودرو با همان سرعت به راهش ادامه می‌دهد.","en":"If the car in front brakes, I travel about 22 m before I manage to react, if my reaction time is 1 second.","een":"Yes. During the reaction time the car carries on at the same speed."},{"da":"Ved 80 km/t er 10 m afstand nok, hvis jeg er opmærksom.","fa":"در سرعت ۸۰، ده متر فاصله کافی است اگر حواسم جمع باشد.","ok":0,"eda":"Nej. 10 m kører du på under et halvt sekund; det er ikke nok til at nå at reagere.","efa":"خیر. ده متر را در کمتر از نیم ثانیه طی می‌کنید؛ این برای واکنش به‌موقع کافی نیست.","en":"At 80 km/h a distance of 10 m is enough if I am attentive.","een":"No. You cover 10 m in less than half a second; that is not enough to react in time."},{"da":"Afstanden skal være så stor, at jeg kan standse, hvis bilen foran bremser hårdt.","fa":"فاصله باید آن‌قدر باشد که اگر خودروی جلو ترمز شدید کرد، بتوانم بایستم.","ok":1,"eda":"Ja. Du skal holde så stor afstand, at du ikke kører ind i den forankørende, hvis den standser.","efa":"بله. باید آن‌قدر فاصله بگیرید که اگر وسیله‌ی جلو ایستاد، به آن نزنید.","en":"The distance must be so large that I can stop if the car in front brakes hard.","een":"Yes. You must keep such a distance that you do not run into the one in front if it stops."},{"da":"Bilen kører omkring 22 m i sekundet.","fa":"خودرو در هر ثانیه حدود ۲۲ متر جلو می‌رود.","ok":1,"eda":"Ja. 80 km/t svarer til godt 22 m i sekundet.","efa":"بله. ۸۰ کیلومتر بر ساعت کمی بیش از ۲۲ متر در ثانیه است.","en":"The car travels about 22 m a second.","een":"Yes. 80 km/h is just over 22 m a second."}]},{"id":5396,"img":"newq-art/5396.png","c":"4.5","sda":"En cyklist foran dig skal til venstre i krydset. Hvordan må du forvente, at cyklisten kører?","sfa":"دوچرخه‌سواری جلوی شما می‌خواهد در تقاطع به چپ برود. باید انتظار داشته باشید چطور حرکت کند؟","sen":"A cyclist in front of you is going left at the junction. How should you expect the cyclist to ride?","st":[{"da":"Cyklisten venter på hjørnet og kører først videre til venstre, når det kan ske uden ulempe for den øvrige trafik.","fa":"دوچرخه‌سوار در گوشه منتظر می‌ماند و فقط وقتی به چپ ادامه می‌دهد که برای بقیه‌ی ترافیک مزاحمتی نداشته باشد.","ok":1,"eda":"Ja. Cyklisten må først svinge, når det kan ske uden ulempe for den øvrige færdsel.","efa":"بله. دوچرخه‌سوار فقط وقتی می‌تواند بپیچد که برای بقیه‌ی ترافیک مزاحمتی نداشته باشد.","en":"The cyclist waits at the corner and only carries on to the left when it can be done without inconvenience to other traffic.","een":"Yes. The cyclist may only turn when it can be done without inconvenience to the other traffic."},{"da":"Cyklisten trækker ud midt på vejen og svinger til venstre ligesom en bil.","fa":"دوچرخه‌سوار به وسط جاده می‌رود و مثل خودرو به چپ می‌پیچد.","ok":0,"eda":"Nej. Medmindre afmærkningen viser andet for cyklister, skal de svinge til venstre i to tempi.","efa":"خیر. مگر این‌که خط‌کشی برای دوچرخه‌سواران چیز دیگری نشان دهد، آن‌ها باید در دو مرحله به چپ بپیچند.","en":"The cyclist pulls out into the middle of the road and turns left like a car.","een":"No. Unless the markings show otherwise for cyclists, they must turn left in two stages."},{"da":"Cyklisten holder til højre og kører ligeud over krydset til det modsatte hjørne.","fa":"دوچرخه‌سوار سمت راست می‌ماند و مستقیم از تقاطع تا گوشه‌ی مقابل می‌رود.","ok":1,"eda":"Ja. En cyklist, der vil svinge til venstre, skal fortsætte gennem krydset til dets modsatte side.","efa":"بله. دوچرخه‌سواری که می‌خواهد به چپ بپیچد باید از تقاطع تا طرف مقابل آن ادامه دهد.","en":"The cyclist keeps right and rides straight across the junction to the opposite corner.","een":"Yes. A cyclist who wants to turn left must carry on through the junction to its opposite side."},{"da":"I et lyskryds følger cyklisten signalet for ligeud, når han kører over til det modsatte hjørne.","fa":"در تقاطع چراغ‌دار، دوچرخه‌سوار وقتی به گوشه‌ی مقابل می‌رود از چراغ مستقیم پیروی می‌کند.","ok":1,"eda":"Ja. Venstresvingende cyklister skal rette sig efter de signaler, der gælder for kørsel ligeud.","efa":"بله. دوچرخه‌سوارانی که به چپ می‌پیچند باید از چراغ‌های مربوط به حرکت مستقیم پیروی کنند.","en":"At a junction with traffic lights the cyclist follows the signal for straight on when he rides across to the opposite corner.","een":"Yes. Cyclists turning left must follow the signals that apply to going straight on."}]},{"id":5397,"img":"newq-art/5397.png","c":"5.1","sda":"Du kører ind på en gade med denne tavle. Undertavlen tillader kørsel med bil. Hvad gælder?","sfa":"وارد خیابانی با این تابلو می‌شوید. زیرتابلو رانندگی با خودرو را مجاز می‌کند. چه قاعده‌ای برقرار است؟","sen":"You turn into a street with this sign. The plate under it allows cars. What applies?","st":[{"da":"Gaden er først og fremmest beregnet til cyklister.","fa":"این خیابان پیش از هر چیز برای دوچرخه‌سواران است.","ok":1,"eda":"Ja. Kørebanen i en cykelgade er reserveret til cykler og små knallerter; andre køretøjer kan få lov at køre der.","efa":"بله. سواره‌روی خیابان دوچرخه مخصوص دوچرخه و موتور گازیِ کوچک است؛ ممکن است به وسایل دیگر هم اجازه‌ی رانندگی داده شود.","en":"The street is first and foremost meant for cyclists.","een":"Yes. The carriageway of a cycle street is reserved for bicycles and small mopeds; other vehicles may be allowed to drive there."},{"da":"Jeg må kun køre med en fart, der svarer til cyklisternes, normalt under 30 km/t.","fa":"فقط با سرعتی هم‌اندازه‌ی سرعت دوچرخه‌سواران، معمولاً زیر ۳۰ کیلومتر بر ساعت، می‌توانم برانم.","ok":1,"eda":"Ja. Kørsel i en cykelgade må kun ske med en hastighed svarende til cyklisternes (normalt under 30 km/t).","efa":"بله. رانندگی در خیابان دوچرخه فقط با سرعتی هم‌اندازه‌ی دوچرخه‌سواران (معمولاً زیر ۳۰ کیلومتر بر ساعت) مجاز است.","en":"I may only drive at a speed matching the cyclists', normally under 30 km/h.","een":"Yes. Driving in a cycle street may only be done at a speed matching the cyclists' (normally under 30 km/h)."},{"da":"Jeg skal vise særlig agtpågivenhed og hensyn over for cyklisterne.","fa":"باید نسبت به دوچرخه‌سواران احتیاط و ملاحظه‌ی ویژه داشته باشم.","ok":1,"eda":"Ja. De kørende i en cykelgade skal udvise særlig agtpågivenhed og hensynsfuldhed over for hinanden.","efa":"بله. کسانی که در خیابان دوچرخه رانندگی می‌کنند باید نسبت به هم احتیاط و ملاحظه‌ی ویژه داشته باشند.","en":"I must take particular care and show consideration for the cyclists.","een":"Yes. Those driving and riding in a cycle street must take particular care and show consideration for one another."},{"da":"Parkering må kun ske på de særligt afmærkede pladser.","fa":"پارک فقط در جاهای مخصوصِ مشخص‌شده مجاز است.","ok":1,"eda":"Ja. Parkering i en cykelgade må ikke ske uden for særligt afmærkede pladser.","efa":"بله. پارک در خیابان دوچرخه بیرون از جاهای مخصوصِ مشخص‌شده مجاز نیست.","en":"Parking is only allowed in the specially marked places.","een":"Yes. Parking in a cycle street must not take place outside specially marked places."}]},{"id":5398,"img":"newq-art/5398.png","c":"3.2","sda":"Du har overhalet en lastbil på motorvejen og vil køre ind i højre vognbane foran den. Hvad skal du være opmærksom på?","sfa":"در آزادراه از یک کامیون سبقت گرفته‌اید و می‌خواهید جلوی آن به خط راست برگردید. به چه چیزی باید توجه کنید؟","sen":"You have overtaken a lorry on the motorway and want to move into the right lane in front of it. What must you be aware of?","st":[{"da":"Lastbiler kan bremse lige så hurtigt som personbiler.","fa":"کامیون‌ها به همان سرعت خودروهای سواری ترمز می‌کنند.","ok":0,"eda":"Nej. Lastbiler er tungere og har længere bremselængde.","efa":"خیر. کامیون‌ها سنگین‌ترند و مسافت ترمز بیشتری دارند.","en":"Lorries can brake as quickly as cars.","een":"No. Lorries are heavier and have longer braking distances."},{"da":"Lastbilen har lang bremselængde, så jeg kører først ind, når der er god afstand til den.","fa":"مسافت ترمز کامیون طولانی است، پس فقط وقتی برمی‌گردم که فاصله‌ی کافی با آن داشته باشم.","ok":1,"eda":"Ja. En tung lastbil kan ikke standse så hurtigt som en personbil.","efa":"بله. کامیون سنگین نمی‌تواند به سرعت یک خودروی سواری بایستد.","en":"The lorry has a long braking distance, so I only move in when there is a good distance to it.","een":"Yes. A heavy lorry cannot stop as quickly as a car."},{"da":"Jeg kan godt køre ind lige foran lastbilen og bremse, fordi den skal holde afstand.","fa":"می‌توانم درست جلوی کامیون برگردم و ترمز کنم، چون او باید فاصله نگه دارد.","ok":0,"eda":"Nej. Du må ikke køre ind, så den, du har overhalet, må bremse.","efa":"خیر. نباید طوری برگردید که کسی که از او سبقت گرفته‌اید مجبور به ترمز شود.","en":"I can move in right in front of the lorry and brake, because it has to keep its distance.","een":"No. You must not move in so that the one you have overtaken has to brake."},{"da":"Chaufføren kan have svært ved at se en bil, der er lige foran eller ved siden af lastbilens front.","fa":"ممکن است راننده‌ی کامیون خودرویی را که درست جلوی کابین یا کنار آن است به‌سختی ببیند.","ok":1,"eda":"Ja. Lastbiler har store blinde vinkler tæt ved førerhuset.","efa":"بله. کامیون‌ها نزدیک کابین نقطه‌های کور بزرگی دارند.","en":"The driver may find it hard to see a car right in front of or beside the front of the lorry.","een":"Yes. Lorries have large blind spots close to the cab."}]},{"id":5399,"img":"newq-art/5399.png","c":"8.1","sda":"Din mobiltelefon sidder i en holder, og du har et headset på. Telefonen ringer, mens du kører. Hvad gælder?","sfa":"تلفن همراهتان در پایه‌ی نگهدارنده است و هدست به گوش دارید. هنگام رانندگی تلفن زنگ می‌زند. چه قاعده‌ای برقرار است؟","sen":"Your mobile phone is in a holder, and you are wearing a headset. The phone rings while you are driving. What applies?","st":[{"da":"Også en håndfri samtale kan tage min opmærksomhed fra trafikken.","fa":"صحبت بدون دست هم می‌تواند حواسم را از ترافیک پرت کند.","ok":1,"eda":"Ja. Samtalen optager dine tanker, så du opdager farer senere.","efa":"بله. گفت‌وگو ذهن شما را مشغول می‌کند و خطرها را دیرتر می‌بینید.","en":"A hands-free call can also take my attention away from the traffic.","een":"Yes. The conversation occupies your thoughts, so you notice dangers later."},{"da":"Jeg må tale i telefonen med headsettet, når jeg ikke holder telefonen i hånden.","fa":"تا وقتی تلفن را در دست نگیرم، می‌توانم با هدست صحبت کنم.","ok":1,"eda":"Ja. Det er forbudt at bruge en håndholdt mobiltelefon under kørslen; håndfri samtale er tilladt.","efa":"بله. استفاده از تلفن همراهِ در دست هنگام رانندگی ممنوع است؛ صحبت بدون دست مجاز است.","en":"I may talk on the phone with the headset as long as I do not hold the phone in my hand.","een":"Yes. Using a hand-held mobile phone while driving is forbidden; a hands-free call is allowed."},{"da":"Jeg må tage telefonen i hånden, hvis jeg kører langsomt.","fa":"اگر آهسته برانم، می‌توانم تلفن را در دست بگیرم.","ok":0,"eda":"Nej. Forbuddet gælder under hele kørslen, uanset farten.","efa":"خیر. این ممنوعیت در تمام مدت رانندگی، با هر سرعتی، برقرار است.","en":"I may take the phone in my hand if I am driving slowly.","een":"No. The ban applies throughout the drive, whatever the speed."},{"da":"Det er ulovligt at tale i telefon under kørslen, også med headset.","fa":"صحبت با تلفن هنگام رانندگی، حتی با هدست، غیرقانونی است.","ok":0,"eda":"Nej. Håndfri samtale er tilladt; det er håndholdt brug, der er forbudt.","efa":"خیر. صحبت بدون دست مجاز است؛ استفاده‌ی در دست ممنوع است.","en":"It is illegal to talk on the phone while driving, also with a headset.","een":"No. Hands-free calls are allowed; it is hand-held use that is forbidden."}]},{"id":5400,"img":"newq-art/5400.png","c":"10.3","sda":"Du er 17 år og har lige fået kørekort til bil. Hvad gælder?","sfa":"۱۷ ساله هستید و تازه گواهینامه‌ی خودرو گرفته‌اید. چه قاعده‌ای برقرار است؟","sen":"You are 17 and have just got your car driving licence. What applies?","st":[{"da":"Når jeg kører alene, gælder promillegrænsen på 0,5.","fa":"وقتی تنها رانندگی می‌کنم، حد مجاز الکل ۰٫۵ در هزار است.","ok":0,"eda":"Nej. I de første 3 år efter, at du har fået kørekort, er grænsen 0,2 promille.","efa":"خیر. در ۳ سال اول پس از گرفتن گواهینامه، حد مجاز ۰٫۲ در هزار است.","en":"When I drive alone, the 0.5 per mille limit applies.","een":"No. In the first 3 years after getting your licence, the limit is 0.2 per mille."},{"da":"Mellem kl. 20 og 5 skal jeg have en ledsager med på forsædet, til jeg fylder 18.","fa":"بین ساعت ۸ شب تا ۵ صبح، تا ۱۸ سالگی باید یک همراه روی صندلی جلو داشته باشم.","ok":1,"eda":"Ja. Om aftenen og natten gælder kravet om ledsager stadig, indtil du fylder 18 år.","efa":"بله. در عصر و شب، تا وقتی ۱۸ ساله شوید، الزام داشتن همراه همچنان برقرار است.","en":"Between 8 pm and 5 am I must have a companion in the front seat until I turn 18.","een":"Yes. In the evening and at night the companion requirement still applies until you turn 18."},{"da":"Mellem kl. 5 og 20 må jeg køre alene.","fa":"بین ساعت ۵ صبح تا ۸ شب می‌توانم تنها رانندگی کنم.","ok":1,"eda":"Ja. Siden 1. juli 2025 må 17-årige køre uden ledsager mellem kl. 5 og 20.","efa":"بله. از ۱ ژوئیه‌ی ۲۰۲۵، افراد ۱۷ ساله می‌توانند بین ساعت ۵ صبح تا ۸ شب بدون همراه رانندگی کنند.","en":"Between 5 am and 8 pm I may drive alone.","een":"Yes. Since 1 July 2025, 17-year-olds may drive without a companion between 5 am and 8 pm."},{"da":"Kravet om ledsager gælder, til jeg har haft kørekort i 3 år.","fa":"الزام داشتن همراه تا وقتی ۳ سال از گرفتن گواهینامه‌ام بگذرد برقرار است.","ok":0,"eda":"Nej. Kravet om ledsager mellem kl. 20 og 5 gælder, til du fylder 18.","efa":"خیر. الزام داشتن همراه بین ساعت ۸ شب تا ۵ صبح تا ۱۸ سالگی برقرار است.","en":"The companion requirement applies until I have held my licence for 3 years.","een":"No. The companion requirement between 8 pm and 5 am applies until you turn 18."}]}]};
